      const parentInfo = findParent(_root, node.id);
      const parentDir = parentInfo ? parentInfo.node.direction : 'horizontal';
      bar.classList.add('gb-split-collapsed-' + parentDir);

      // カラム移動用のドラッグハンドル（バー先頭に配置）
