    const initialPane = initialPaneInfo.node;
    const preferTargetPane = !!opts.preferTargetPane;
    // 「メインパネルで開く」昇格専用（2026-07-31計画）。true の場合、既存タブや
    // 他ペインの同一ファイル・同種タブを一切再利用せず、必ず新しいタブを作る。
    const forceNewTab = !!opts.forceNewTab;

