// === VersionComponent ===
// バージョン管理パネルの絞り込みのうち、制作進行の日次記録だけは対象ファイルではなく
// ワークスペースの記録を見る（制作タスク実績時間の計画書 §7.2）。
const PRODUCTION_DAILY_KIND = 'production-daily';

class VersionComponent extends ToolComponent {
  destroy() {
    this._destroyed = true;
    super.destroy();
  }

  create() {
    this.el = document.createElement('div');
    this.el.className = 'gb-tool-version';
    this.el.style.cssText = 'display:flex;flex-direction:column;flex:1;overflow:hidden;';
    return this.el;
  }

  _getTabPath() {
    // tabId からタブオブジェクトを探してパスを取得
    if (typeof GBLayout !== 'undefined') {
      const allPanes = GBLayout.getAllPanes(GBLayout.root);
      for (const pane of allPanes) {
        const tab = (pane.tabs || []).find(t => t.id === this.tabId);
        if (tab) return tab.path || '';
      }
    }
    return '';
  }

  activate() {
    super.activate();
    const path = this._getTabPath() || this.state.versionPath || '';
    const vType = this.state.versionType || 'file';
    if (path) {
      this._loadVersions(path, vType);
    } else {
      this._renderNoTargetView();
    }
  }

  // 対象ファイルが無い状態の表示。制作進行の日次記録は対象ファイルに依存しないため、
  // その絞り込みを選んでいる間は対象未指定でも一覧を出す。
  _renderNoTargetView() {
    if (!this.el) return;
    this._loadSeq = (this._loadSeq || 0) + 1;
    this._timelineEntries = [];
    this._timelineTotal = 0;
    if ((this.state.timelineKind || '') === PRODUCTION_DAILY_KIND) {
      this._timelineEntries = [];
      this.el.innerHTML = `${_railTargetHeaderHtml('', '制作進行の日次記録')}<div class="gb-tool-version-body" style="padding:12px;overflow:auto;">
        ${this._buildTimelineHtml('', 'file', [])}
      </div>`;
      this._bindVersionActions();
      this._mountProductionDailyRecords();
      return;
    }
    this.el.innerHTML = `${_railTargetHeaderHtml('')}<div class="gb-tool-version-body" style="padding:12px;overflow:auto;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap;">
        <span style="margin-left:auto;color:var(--fg2);display:inline-flex;align-items:center;gap:4px;">${typeof lucide === 'function' ? lucide('filter', 12) : ''}</span>
        ${this._buildKindFilterHtml(this.state.timelineKind || 'named,auto,edit')}
      </div>
      <div class="gb-empty-state" style="padding:24px;">
        <div class="gb-empty-icon">${typeof lucide === 'function' ? lucide('gitBranch', 48) : ''}</div>
        <div class="gb-empty-message">バージョン管理</div>
        <div class="gb-empty-hint">ファイルまたはフォルダを開いてからバージョン管理を使用してください（「制作進行の日次記録」はファイルを開かなくても見られます）</div>
      </div>
    </div>`;
    this._bindVersionActions();
  }

  _mountProductionDailyRecords() {
    const host = this.el?.querySelector('[data-production-daily-host]');
    if (!host) return;
    const Panel = typeof window !== 'undefined' ? window.MeldexProductionDailySnapshotPanel : null;
    if (typeof Panel !== 'function') {
      host.textContent = '制作進行の日次記録を読み込めませんでした';
      return;
    }
    if (!this._productionDailyPanel) this._productionDailyPanel = new Panel();
    const panel = this._productionDailyPanel;
    const showList = () => {
      panel.renderSnapshotList(host, {
        onSelectSnapshot: (snap, compareSnapshot) => {
          panel.renderDayView(host, snap, { compareSnapshot, onBack: showList });
        },
      });
    };
    showList();
  }

  async _loadVersions(path, vType) {
    const loadSeq = (this._loadSeq || 0) + 1;
    this._loadSeq = loadSeq;
    if (this.state.versionPath !== path || this.state.versionType !== vType) this._timelineOffset = 0;
    this.state.versionPath = path;
    this.state.versionType = vType;
    if (!this.el || this._destroyed) return;
    this.el.innerHTML = `${_railTargetHeaderHtml(path)}<div class="gb-history-loading" style="padding:16px;color:var(--fg2);">読み込み中...</div>`;
    if (vType === 'annotations') {
      let versions = [];
      try {
        versions = await apiFetch('/annotations/versions?target=' + encodeURIComponent(path));
      } catch (error) {
        if (this._destroyed || this._loadSeq !== loadSeq || !this.el) return;
        this.el.innerHTML = _railTargetHeaderHtml(path) + this._loadErrorHtml(path, vType, ['アノテートバージョン: ' + (error?.message || '取得失敗')]);
        this._bindVersionActions();
        return;
      }
      if (this._destroyed || this._loadSeq !== loadSeq || !this.el) return;
      this._timelineEntries = [];
      this.el.innerHTML = _railTargetHeaderHtml(path) + this._buildAnnotationVersionsHtml(path, versions);
      this._bindVersionActions();
      return;
    }
    const isFolder = vType === 'folder';
    const isDb = vType === 'db';
    const timelineKind = this.state.timelineKind || 'named,auto,edit';
    const timelineActorKind = this.state.timelineActorKind || '';
    // ファイル編集中(file/db)はファイルバージョンのみ、フォルダ選択中はフォルダバージョンのみを取得・表示する
    let versions = [];
    let folderVersions = [];
    let timeline = { entries: [] };
    const errors = [];
    const folderPath = isFolder ? path : '';
    if (timelineKind === PRODUCTION_DAILY_KIND) {
      // 日次記録はファイル版の取得失敗や待ち時間に依存させない。
    } else if (isFolder) {
      try {
        folderVersions = await apiFetch('/version/list-folder?path=' + encodeURIComponent(path));
      } catch (error) { errors.push('フォルダバージョン: ' + (error?.message || '取得失敗')); }
    } else {
      try {
        versions = await apiFetch((isDb ? '/version/list-db' : '/version/list') + '?path=' + encodeURIComponent(path));
      } catch (error) { errors.push('ファイルバージョン: ' + (error?.message || '取得失敗')); }
    }
    if (this._destroyed || this._loadSeq !== loadSeq || !this.el) return;
    // 制作進行の日次記録は対象ファイルに紐づかないため、タイムラインAPIは呼ばない
    if (timelineKind !== PRODUCTION_DAILY_KIND) {
      try {
        const params = new URLSearchParams({ target_path: path, kinds: timelineKind, limit: '200', offset: String(this._timelineOffset || 0) });
        if (timelineActorKind) params.set('actor_kind', timelineActorKind);
        timeline = await apiFetch('/version-panel/timeline?' + params.toString());
      } catch (error) { errors.push('タイムライン: ' + (error?.message || '取得失敗')); }
    }
    if (this._destroyed || this._loadSeq !== loadSeq || !this.el) return;
    this._timelineEntries = Array.isArray(timeline?.entries) ? timeline.entries : [];
    this._timelineTotal = Number(timeline?.total || this._timelineEntries.length);
    this.el.innerHTML = _railTargetHeaderHtml(path, timelineKind === PRODUCTION_DAILY_KIND ? '制作進行の日次記録' : '')
      + (errors.length ? this._loadErrorHtml(path, vType, errors) : '')
      + this._buildHtml(path, vType, versions, folderPath, folderVersions, this._timelineEntries);
    this._bindVersionActions();
    if (timelineKind === PRODUCTION_DAILY_KIND) this._mountProductionDailyRecords();
  }

  _loadErrorHtml(path, vType, errors) {
    return `<div role="alert" class="gb-version-load-error" style="padding:8px;">一覧の一部を読み込めませんでした。<br>${errors.map(esc).join('<br>')}
      <button class="gb-btn gb-btn-sm" ${this._versionButtonAttrs('refresh', path, '', vType)}>再読み込み</button></div>`;
  }

  _syncVersionBusy() {
    if (!this.el) return;
    this.el.setAttribute('aria-busy', String(!!this._actionBusy));
    this.el.querySelectorAll('[data-version-action]').forEach(button => { button.disabled = !!this._actionBusy; });
  }

  async _runVersionAction(action, path, versionName, vType) {
    if (this._actionBusy || this._destroyed) return;
    const calls = {
      showFolderFiles: () => showFolderVersionFiles(path, versionName),
      restoreFolder: () => restoreFolderVersion(path, versionName),
      deleteFolder: () => deleteFolderVersion(path, versionName),
      promoteFolder: () => this._promoteFolderVersion(path, versionName),
      timelineShowFolderFiles: () => showFolderVersionFiles(path, versionName),
      timelineRestoreFolder: () => restoreFolderVersion(path, versionName),
      timelineDeleteFolder: () => deleteFolderVersion(path, versionName),
      timelinePromoteFolder: () => this._promoteFolderVersion(path, versionName),
      saveFolder: () => saveFolderVersion(path),
      saveCurrent: () => (vType === 'folder' ? saveFolderVersion(path) : saveManualVersion(path, vType)),
      preview: () => previewVersion(path, versionName, vType),
      compare: () => compareVersion(path, versionName, vType),
      restore: () => restoreVersion(path, versionName, vType),
      delete: () => deleteVersion(path, versionName, vType),
      timelinePreview: () => previewVersion(path, versionName, vType),
      timelineCompare: () => compareVersion(path, versionName, vType),
      timelineRestore: () => restoreVersion(path, versionName, vType),
      timelineDelete: () => deleteVersion(path, versionName, vType),
      save: () => saveManualVersion(path, vType),
      refresh: () => this._loadVersions(this.state.versionPath || path, this.state.versionType || vType),
      timelinePrevious: () => { this._timelineOffset = Math.max(0, (this._timelineOffset || 0) - 200); return this._loadVersions(path, vType); },
      timelineNext: () => { this._timelineOffset = (this._timelineOffset || 0) + 200; return this._loadVersions(path, vType); },
      annotationSave: () => this._saveAnnotationVersion(path),
      annotationPreview: () => this._showAnnotationVersion(path, versionName, false),
      annotationCompare: () => this._showAnnotationVersion(path, versionName, true),
      annotationRestore: () => this._restoreAnnotationVersion(path, versionName),
      annotationDelete: () => this._deleteAnnotationVersion(path, versionName),
    };
    const fn = calls[action];
    if (!fn) return;
    this._actionBusy = true;
    this._syncVersionBusy();
    try {
      const result = await fn();
      const reloadActions = new Set([
        'save', 'saveCurrent', 'restore', 'delete', 'saveFolder', 'restoreFolder', 'deleteFolder', 'promoteFolder',
        'timelineRestore', 'timelineDelete', 'timelineRestoreFolder', 'timelineDeleteFolder', 'timelinePromoteFolder',
        'annotationSave', 'annotationRestore', 'annotationDelete',
      ]);
      if (reloadActions.has(action) && result !== false && !this._destroyed) {
        const reloadPath = this.state.versionPath || path;
        const reloadType = this.state.versionType || vType || 'file';
        if (reloadPath) await this._loadVersions(reloadPath, reloadType);
      }
    } catch (error) {
      if (typeof showStatus === 'function') showStatus('バージョン操作に失敗しました: ' + (error?.message || ''), true);
    } finally {
      this._actionBusy = false;
      this._syncVersionBusy();
    }
  }

  async _saveAnnotationVersion(path) {
    const defaultLabel = '保存_' + new Date().toISOString().slice(0, 16).replace('T', '_').replace(':', '-');
    const label = await cfPrompt('アノテートバージョン名:', defaultLabel);
    if (label === null || !String(label).trim()) return false;
    await apiPost('/annotations/versions/save', { target: path, label: String(label).trim() });
    if (typeof showStatus === 'function') showStatus('アノテートバージョンを保存しました');
  }

  async _readAnnotationVersion(path, versionName) {
    return apiFetch('/annotations/versions/read?target=' + encodeURIComponent(path) + '&version=' + encodeURIComponent(versionName));
  }

  async _showAnnotationVersion(path, versionName, compare) {
    const data = await this._readAnnotationVersion(path, versionName);
    const saved = Array.isArray(data?.savedAnnotations) ? data.savedAnnotations : [];
    const current = Array.isArray(data?.currentAnnotations) ? data.currentAnnotations : [];
    const savedText = JSON.stringify(saved, null, 2);
    const label = data?.version?.label || '保存版';
    if (typeof showDiffModal === 'function') {
      if (compare) showDiffModal(savedText, JSON.stringify(current, null, 2), label, '現在のアノテート');
      else showDiffModal('', savedText, '', `${label}（${saved.length}件）`);
      return;
    }
    if (typeof cfAlert === 'function') await cfAlert(`${label}\n\n${savedText}`);
  }

  async _restoreAnnotationVersion(path, versionName) {
    const current = await this._readAnnotationVersion(path, versionName);
    if (!await cfConfirm('このアノテートバージョンに復元しますか？\n（現在のアノテートは自動保存されます）')) return false;
    const result = await apiPost('/annotations/versions/restore', {
      target: path,
      version: versionName,
      expectedRevision: current?.annotationWriteRevision || '',
    });
    if (typeof loadAnnotations === 'function') await loadAnnotations();
    if (typeof showStatus === 'function') showStatus(`${Number(result?.count || 0)}件のアノテートを復元しました`);
  }

  async _deleteAnnotationVersion(path, versionName) {
    if (!await cfConfirm('この手動保存バージョンを削除しますか？')) return false;
    await apiDelete('/annotations/versions/' + encodeURIComponent(versionName) + '?target=' + encodeURIComponent(path));
    if (typeof showStatus === 'function') showStatus('アノテートバージョンを削除しました');
  }

  async _promoteFolderVersion(path, versionName) {
    const defaultLabel = '保存_' + new Date().toISOString().slice(0, 16).replace('T', '_').replace(':', '-');
    const label = await cfPrompt('手動復元ポイント名:', defaultLabel);
    if (label === null) return false;
    await apiPost('/version/promote', { path, version: versionName, type: 'folder', label });
    showStatus('手動復元ポイントとして保存しました');
  }

  _previewEditEntry(entry) {
    if (!entry) return;
    const existing = document.querySelector('.version-edit-record-preview-overlay');
    if (existing?._versionPreviewModalApi?.isOpen?.()) {
      existing._versionPreviewModalApi.modal.focus?.({ preventScroll: true });
      return existing._versionPreviewModalApi;
    }
    const time = this._formatTimelineDate(entry);
    const oldValue = entry.old_value || entry.old_status || '';
    const newValue = entry.new_value || entry.new_status || '';
    const summary = entry.body_diff_summary || '';
    const integrityWarning = entry.integrity_warning || '';
    if (typeof window.GBUI?.createModal !== 'function') {
      throw new Error('変更レコードを初期化できませんでした。');
    }
    const content = document.createElement('div');
    content.style.cssText = 'font-size:12px;line-height:1.5;';
    content.innerHTML = `
        <div class="gb-section-desc" style="margin-bottom:8px;">${esc(time)} / ${esc(entry.user || '')}${entry.actor_model ? ' / ' + esc(entry.actor_model) : ''}</div>
        ${integrityWarning ? `<div role="alert" style="margin-bottom:8px;padding:8px;border:1px solid var(--danger,#c33);border-radius:6px;color:var(--danger,#c33);">${esc(integrityWarning)}</div>` : ''}
        <div style="margin-bottom:8px;"><b>${esc(entry.action || '')}</b> ${esc(entry.entity_name || '')}${entry.property_name ? ' / ' + esc(entry.property_name) : ''}</div>
        ${summary ? `<pre style="white-space:pre-wrap;background:var(--bg2);border:1px solid var(--border);border-radius:6px;padding:8px;">${esc(summary)}</pre>` : ''}
        ${oldValue || newValue ? `<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">
          <div><div class="gb-section-desc">変更前</div><pre style="white-space:pre-wrap;background:var(--bg2);border:1px solid var(--border);border-radius:6px;padding:8px;min-height:64px;">${esc(oldValue)}</pre></div>
          <div><div class="gb-section-desc">変更後</div><pre style="white-space:pre-wrap;background:var(--bg2);border:1px solid var(--border);border-radius:6px;padding:8px;min-height:64px;">${esc(newValue)}</pre></div>
        </div>` : ''}`;
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'gb-btn gb-btn-sm';
    close.dataset.versionPreviewClose = '';
    close.textContent = '閉じる';
    const modalApi = window.GBUI.createModal({
      id: 'version-edit-record-preview',
      title: '変更レコード',
      body: content,
      footer: close,
      variant: 'standard',
      extraClass: 'version-edit-record-preview-modal',
      geometryKey: 'version-edit-record-preview',
      minWidth: '0',
      initialFocus: close,
      returnFocus: document.activeElement,
      closeLabel: '変更レコードを閉じる',
      closeOnEsc: true,
      closeOnOverlay: true,
    });
    modalApi.overlay.classList.add('modal-overlay', 'version-edit-record-preview-overlay');
    modalApi.overlay._versionPreviewModalApi = modalApi;
    modalApi.overlay.dataset.e2eId = 'version-edit-record-preview-overlay';
    modalApi.modal.dataset.e2eId = 'version-edit-record-preview-dialog';
    modalApi.modal.style.maxWidth = 'min(80vw, 920px)';
    close.addEventListener('click', () => modalApi.close('footer-close'));
    modalApi.open();
    return modalApi;
  }

  _bindVersionActions() {
    if (!this.el) return;
    this.el.querySelectorAll('[data-version-action]').forEach(btn => {
      btn.addEventListener('click', () => {
        const { versionAction, versionPath, versionName, versionType } = btn.dataset;
        if (versionAction === 'previewEdit') {
          const index = parseInt(btn.dataset.versionEntryIndex || '-1', 10);
          try { this._previewEditEntry(this._timelineEntries?.[index]); }
          catch (error) { showStatus(error?.message || '変更レコードを表示できませんでした', true); }
          return;
        }
        this._runVersionAction(versionAction, versionPath || '', versionName || '', versionType || this.state.versionType || 'file');
      });
    });
    this.el.querySelectorAll('[data-version-filter]').forEach(input => {
      input.addEventListener('change', () => {
        if (input.dataset.versionFilter === 'kind') this.state.timelineKind = input.value || 'named,auto,edit';
        if (input.dataset.versionFilter === 'actor') this.state.timelineActorKind = input.value || '';
        this._timelineOffset = 0;
        const reloadPath = this.state.versionPath || this._getTabPath() || '';
        if (reloadPath) this._loadVersions(reloadPath, this.state.versionType || 'file');
        else this._renderNoTargetView();
      });
    });
    this._syncVersionBusy();
    this.el.querySelectorAll('[data-version-integrity-recovery]').forEach(button => {
      button.addEventListener('click', () => {
        window.MeldexOwnerKeyRecovery?.showRecoveryDialog?.({
          reason: '変更レコードの整合性を確認するため、管理者鍵を復旧してください。',
          trigger: button,
        });
      });
    });
  }

  _getFolderPath(path, vType) {
    if (vType === 'db') return path; // DBのパスはフォルダ
    if (vType === 'folder') return path;
    // ファイルパスの親フォルダ
    const idx = path.lastIndexOf('/');
    return idx > 0 ? path.substring(0, idx) : '';
  }

  _formatVersionDate(version) {
    if (typeof _versionDisplayDate === 'function') return _versionDisplayDate(version);
    const value = String(version?.created || version?.modified || '');
    return value ? value.substring(0, 19).replace('T', ' ') : '';
  }

  _formatTimelineDate(entry) {
    const value = String(entry?.timestamp || entry?.created || entry?.modified || '');
    return value ? value.substring(0, 19).replace('T', ' ') : '';
  }

  _versionSelectOption(value, label, current) {
    return `<option value="${esc(value)}"${value === current ? ' selected' : ''}>${esc(label)}</option>`;
  }

  _timelineIcon(entry) {
    if (entry.type === 'named') return 'tag';
    if (entry.type === 'auto') return 'history';
    return entry.actor_kind === 'llm' ? 'bot' : 'pencilLine';
  }

  _timelineLabel(entry) {
    if (entry.type === 'named') return entry.label ? `復元ポイント「${entry.label}」` : '復元ポイント';
    if (entry.type === 'auto') return entry.label && entry.label !== '自動復元ポイント' ? `自動復元ポイント: ${entry.label}` : '自動復元ポイント';
    return entry.label || entry.body_diff_summary || entry.action || '変更レコード';
  }

  _timelineIntegrityBadge(entry) {
    if (entry.type !== 'edit') return '';
    const status = String(entry.integrity_status || '');
    if (status === 'verified') return '<span class="gb-badge gb-badge-manual" title="管理者署名を検証済み">署名確認済み</span>';
    if (status === 'legacy-unsigned') return '<span class="gb-badge gb-badge-auto" title="署名機能導入前の変更レコード">旧記録・署名対象外</span>';
    if (status === 'pending-owner-signature') return '<span class="gb-badge gb-badge-auto" title="管理者端末での署名を待っています">管理者署名待ち</span>';
    if (status === 'owner-verification-required') return '<span class="gb-badge gb-badge-auto" title="署名鍵は管理者端末だけが保持します">管理者端末で確認</span>';
    if (status === 'tampered') return '<span class="gb-badge gb-badge-danger" role="alert" title="署名後に改変された可能性があります">改変の可能性</span>';
    if (status === 'owner-key-missing') return '<span class="gb-badge gb-badge-danger" role="alert" title="管理者鍵を復旧して検証してください">管理者鍵が必要</span>';
    return '';
  }

  _timelineActions(entry, index) {
    if (entry.type === 'edit') {
      const editId = ['version-edit-preview', entry.id || index, entry.path || this.state.versionPath || '']
        .map(value => this._versionE2eToken(value))
        .filter(Boolean)
        .join('-');
      return `<button class="gb-btn gb-btn-xs" data-e2e-id="${esc(editId)}" data-version-action="previewEdit" data-version-entry-index="${index}" title="詳細">${typeof lucide === 'function' ? lucide('eye', 12) : '表示'}</button>`;
    }
    const path = entry.path || this.state.versionPath || '';
    const version = entry.snapshot_version || '';
    const type = entry.version_type || entry.snapshot_kind || this.state.versionType || 'file';
    if (type === 'folder') {
      return `<button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('timelineShowFolderFiles', path, version, 'folder')} title="一覧">${typeof lucide === 'function' ? lucide('eye', 12) : '一覧'}</button>
        ${entry.type === 'auto' ? `<button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('timelinePromoteFolder', path, version, 'folder')} title="手動復元ポイントとして保存">${typeof lucide === 'function' ? lucide('bookmarkPlus', 12) : '保存'}</button>` : ''}
        <button class="gb-btn gb-btn-xs gb-btn-warn" ${this._versionButtonAttrs('timelineRestoreFolder', path, version, 'folder')} title="復元">${typeof lucide === 'function' ? lucide('rotateCcw', 12) : '復元'}</button>
        ${entry.type === 'named' ? `<button class="gb-btn gb-btn-xs gb-btn-danger" ${this._versionButtonAttrs('timelineDeleteFolder', path, version, 'folder')} title="削除">${typeof lucide === 'function' ? lucide('trash2', 12) : '削除'}</button>` : ''}`;
    }
    return `<button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('timelinePreview', path, version, type)} title="表示">${typeof lucide === 'function' ? lucide('eye', 12) : '表示'}</button>
      <button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('timelineCompare', path, version, type)} title="比較">${typeof lucide === 'function' ? lucide('gitCompare', 12) : '比較'}</button>
      <button class="gb-btn gb-btn-xs gb-btn-warn" ${this._versionButtonAttrs('timelineRestore', path, version, type)} title="復元">${typeof lucide === 'function' ? lucide('rotateCcw', 12) : '復元'}</button>
      ${entry.type === 'named' ? `<button class="gb-btn gb-btn-xs gb-btn-danger" ${this._versionButtonAttrs('timelineDelete', path, version, type)} title="削除">${typeof lucide === 'function' ? lucide('trash2', 12) : '削除'}</button>` : ''}`;
  }

  _buildTimelineHtml(path, vType, timelineEntries) {
    const entries = Array.isArray(timelineEntries) ? timelineEntries : [];
    const kind = this.state.timelineKind || 'named,auto,edit';
    const actor = this.state.timelineActorKind || '';
    if (kind === PRODUCTION_DAILY_KIND) return this._buildProductionDailyHtml(kind);
    const rows = entries.length ? entries.map((entry, index) => {
      const time = this._formatTimelineDate(entry);
      const actorBadge = entry.actor_kind === 'llm'
        ? `<span class="gb-badge gb-badge-auto">${typeof lucide === 'function' ? lucide('bot', 11) : ''}${esc(entry.actor_model || 'LLM')}</span>`
        : entry.actor_kind ? `<span class="gb-badge gb-badge-manual">${esc(entry.user || entry.actor_kind)}</span>` : '';
      const typeBadge = entry.type === 'named'
        ? '<span class="gb-badge gb-badge-manual">手動復元ポイント</span>'
        : entry.type === 'auto'
          ? '<span class="gb-badge gb-badge-auto">自動</span>'
          : '<span class="gb-badge gb-badge-manual">変更</span>';
      const integrityBadge = this._timelineIntegrityBadge(entry);
      const recoveryButton = entry.integrity_recovery_action === 'open-owner-key-recovery'
        ? '<button class="gb-btn gb-btn-xs gb-btn-warn" data-version-integrity-recovery>管理者鍵を復旧</button>' : '';
      return `<div class="gb-history-row gb-history-row-compact" style="align-items:center;">
        <span style="width:18px;display:inline-flex;align-items:center;justify-content:center;color:var(--fg2);">${typeof lucide === 'function' ? lucide(this._timelineIcon(entry), 14) : ''}</span>
        ${typeBadge}
        ${integrityBadge}
        <span class="gb-history-label" title="${esc(entry.label || '')}"><span style="color:var(--fg2);">${esc(time)}</span> ${esc(this._timelineLabel(entry))}</span>
        ${actorBadge}
        <div class="gb-history-actions">${recoveryButton}${this._timelineActions(entry, index)}</div>
      </div>`;
    }).join('') : '<div class="gb-section-desc" style="padding:8px 0;">タイムラインに表示する項目がありません</div>';

    return `<section class="gb-version-timeline" style="margin-bottom:10px;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap;">
        <button class="gb-btn gb-btn-xs gb-btn-primary" ${this._versionButtonAttrs('saveCurrent', path, '', vType)}>${typeof lucide === 'function' ? lucide('bookmarkPlus', 12) : '+'} 復元ポイントを作成</button>
        <span style="margin-left:auto;color:var(--fg2);display:inline-flex;align-items:center;gap:4px;">${typeof lucide === 'function' ? lucide('filter', 12) : ''}</span>
        ${this._buildKindFilterHtml(kind)}
        <select data-e2e-id="version-timeline-actor-filter" data-version-filter="actor" style="font-size:12px;background:var(--bg);color:var(--fg);border:1px solid var(--border);border-radius:4px;padding:2px 4px;">
          ${this._versionSelectOption('', '全主体', actor)}
          ${this._versionSelectOption('human', '人間', actor)}
          ${this._versionSelectOption('llm', 'LLM', actor)}
        </select>
      </div>
      <div class="gb-history-list">${rows}</div>
      ${this._timelineTotal > 200 || this._timelineOffset ? `<div class="gb-version-pagination" style="display:flex;gap:8px;align-items:center;">
        ${(this._timelineOffset || 0) > 0 ? `<button class="gb-btn gb-btn-sm" ${this._versionButtonAttrs('timelinePrevious', path, '', vType)}>前の200件</button>` : ''}
        <span>${(this._timelineOffset || 0) + 1}～${(this._timelineOffset || 0) + entries.length} / ${this._timelineTotal}件</span>
        ${(this._timelineOffset || 0) + entries.length < this._timelineTotal ? `<button class="gb-btn gb-btn-sm" ${this._versionButtonAttrs('timelineNext', path, '', vType)}>次の200件</button>` : ''}
      </div>` : ''}
    </section>`;
  }

  // 種類の絞り込み（対象ファイルの有無に関わらず同じ候補を出す）
  _buildKindFilterHtml(kind) {
    return `<select data-e2e-id="version-timeline-kind-filter" data-version-filter="kind" style="font-size:12px;background:var(--bg);color:var(--fg);border:1px solid var(--border);border-radius:4px;padding:2px 4px;">
      ${this._versionSelectOption('named,auto,edit', '全て', kind)}
      ${this._versionSelectOption('named', '手動復元ポイント', kind)}
      ${this._versionSelectOption('auto', '復元ポイント', kind)}
      ${this._versionSelectOption('edit', '変更ログ', kind)}
      ${this._versionSelectOption(PRODUCTION_DAILY_KIND, '制作進行の日次記録', kind)}
    </select>`;
  }

  // 制作進行の日次記録の絞り込み。対象ファイルの版一覧ではなく、日次記録の一覧を出す。
  _buildProductionDailyHtml(kind) {
    return `<section class="gb-version-timeline gb-version-production-daily" style="margin-bottom:10px;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap;">
        <span style="margin-left:auto;color:var(--fg2);display:inline-flex;align-items:center;gap:4px;">${typeof lucide === 'function' ? lucide('filter', 12) : ''}</span>
        ${this._buildKindFilterHtml(kind)}
      </div>
      <div data-production-daily-host data-e2e-id="version-production-daily-host"></div>
    </section>`;
  }

  _versionE2eToken(value) {
    return String(value == null ? '' : value)
      .trim()
      .replace(/[^a-zA-Z0-9_-]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }

  _versionButtonAttrs(action, path, versionName = '', vType = '') {
    const id = ['version', vType, path, versionName, action]
      .map(value => this._versionE2eToken(value))
      .filter(Boolean)
      .join('-');
    let attrs = `data-e2e-id="${esc(id)}" data-version-action="${esc(action)}"`;
    if (path != null) attrs += ` data-version-path="${esc(path)}"`;
    if (versionName) attrs += ` data-version-name="${esc(versionName)}"`;
    if (vType) attrs += ` data-version-type="${esc(vType)}"`;
    return attrs;
  }

  _buildHtml(path, vType, versions, folderPath, folderVersions, timelineEntries) {
    const safePath = esc(path);
    const fileName = path.split('/').pop() || path;
    const isFolder = vType === 'folder';

    // フォルダバージョンセクション（フォルダ選択中のみ表示）
    let folderSection = '';
    if (isFolder && folderPath) {
      const safeFolderPath = esc(folderPath);
      const folderName = folderPath.split('/').pop() || folderPath;
      let folderListHtml = '';
      if (!folderVersions || !folderVersions.length) {
        folderListHtml = '<div class="gb-section-desc" style="padding:8px 0;">フォルダバージョンがありません</div>';
      } else {
        folderVersions.forEach(v => {
          const dt = this._formatVersionDate(v);
          const label = v.label ? ' — ' + esc(v.label) : '';
          const fileCount = v.file_count || 0;
          const totalSize = v.total_size ? formatFileSize(v.total_size) : '';
          const badge = v.auto ? '<span class="gb-badge gb-badge-auto">自動</span>' : '<span class="gb-badge gb-badge-manual">手動</span>';
          folderListHtml += `<div class="gb-history-row gb-history-row-compact">
            ${badge}
            <span class="gb-history-label">${dt}${label}</span>
            <span class="gb-history-size">${fileCount}ファイル${totalSize ? ', ' + totalSize : ''}</span>
            <div class="gb-history-actions">
              <button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('showFolderFiles', folderPath, v.name, 'folder')} title="一覧">一覧</button>
              ${v.auto ? `<button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('promoteFolder', folderPath, v.name, 'folder')} title="手動復元ポイントとして保存">${typeof lucide === 'function' ? lucide('bookmarkPlus', 12) : ''}</button>` : ''}
              <button class="gb-btn gb-btn-xs gb-btn-warn" ${this._versionButtonAttrs('restoreFolder', folderPath, v.name, 'folder')} title="復元">復元</button>
              ${v.auto ? '' : `<button class="gb-btn gb-btn-xs gb-btn-danger" ${this._versionButtonAttrs('deleteFolder', folderPath, v.name, 'folder')} title="削除">${typeof lucide === 'function' ? lucide('x', 12) : '削除'}</button>`}
            </div>
          </div>`;
        });
      }
      folderSection = `<details class="gb-version-section" open>
        <summary class="gb-version-section-header">${typeof lucide === 'function' ? lucide('folder', 14) : ''} フォルダバージョン（${esc(folderName)}）</summary>
        <div class="gb-version-section-body">
          <div style="margin-bottom:8px;">
            <button class="gb-btn gb-btn-xs gb-btn-primary" ${this._versionButtonAttrs('saveFolder', folderPath, '', 'folder')} title="フォルダ版を保存">+ フォルダ版を保存</button>
          </div>
          ${folderListHtml}
        </div>
      </details>`;
    }

    // 個別ファイルバージョンセクション
    let fileListHtml = '';
    if (!versions.length) {
      fileListHtml = '<div class="gb-section-desc" style="padding:8px 0;">バージョンがありません</div>';
    } else {
      versions.forEach(v => {
        const dt = this._formatVersionDate(v);
        const badge = v.auto ? '<span class="gb-badge gb-badge-auto">自動</span>' : '<span class="gb-badge gb-badge-manual">手動</span>';
        const label = v.label ? ' — ' + esc(v.label) : '';
        fileListHtml += `<div class="gb-history-row gb-history-row-compact">
          ${badge}<span class="gb-history-label">${dt}${label}</span>
          <span class="gb-history-size">${formatFileSize(v.size)}</span>
          <div class="gb-history-actions">
            <button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('preview', path, v.name, vType)}>表示</button>
            <button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('compare', path, v.name, vType)}>比較</button>
            <button class="gb-btn gb-btn-xs gb-btn-warn" ${this._versionButtonAttrs('restore', path, v.name, vType)}>復元</button>
            <button class="gb-btn gb-btn-xs gb-btn-danger" ${this._versionButtonAttrs('delete', path, v.name, vType)}>${lucide('x', 12)}</button>
          </div>
        </div>`;
      });
    }
    const fileSection = `<details class="gb-version-section" open>
      <summary class="gb-version-section-header">${typeof lucide === 'function' ? lucide('file', 14) : ''} ファイルバージョン（${esc(fileName)}）</summary>
      <div class="gb-version-section-body">
        ${fileListHtml}
      </div>
    </details>`;

    return `<div class="gb-version-panel" style="overflow:auto;flex:1;padding:8px;">
      <div class="gb-version-panel-header" style="display:flex;align-items:center;gap:6px;padding-bottom:8px;border-bottom:1px solid var(--border);margin-bottom:8px;">
        ${typeof lucide === 'function' ? lucide('gitBranch', 16) : ''}
        <span style="font-weight:bold;font-size:13px;">バージョン管理</span>
        <button class="gb-btn gb-btn-xs gb-btn-quiet" ${this._versionButtonAttrs('refresh', path, '', vType)} title="更新">${typeof lucide === 'function' ? lucide('refreshCw', 12) : '↻'}</button>
      </div>
      ${this._buildTimelineHtml(path, vType, timelineEntries)}
      ${folderSection}
      ${isFolder ? '' : fileSection}
    </div>`;
  }

  _buildAnnotationVersionsHtml(path, versions) {
    const rows = Array.isArray(versions) && versions.length
      ? versions.map(version => {
          const badge = version.auto
            ? '<span class="gb-badge gb-badge-auto">自動</span>'
            : '<span class="gb-badge gb-badge-manual">手動</span>';
          const label = version.label ? ` — ${esc(version.label)}` : '';
          return `<div class="gb-history-row gb-history-row-compact">
            ${badge}
            <span class="gb-history-label">${esc(this._formatVersionDate(version))}${label}</span>
            <span class="gb-history-size">${Number(version.annotationCount || 0)}件</span>
            <div class="gb-history-actions">
              <button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('annotationPreview', path, version.name, 'annotations')}>表示</button>
              <button class="gb-btn gb-btn-xs" ${this._versionButtonAttrs('annotationCompare', path, version.name, 'annotations')}>比較</button>
              <button class="gb-btn gb-btn-xs gb-btn-warn" ${this._versionButtonAttrs('annotationRestore', path, version.name, 'annotations')}>復元</button>
              ${version.auto ? '' : `<button class="gb-btn gb-btn-xs gb-btn-danger" ${this._versionButtonAttrs('annotationDelete', path, version.name, 'annotations')}>${typeof lucide === 'function' ? lucide('x', 12) : '削除'}</button>`}
            </div>
          </div>`;
        }).join('')
      : '<div class="gb-section-desc" style="padding:8px 0;">アノテートバージョンがありません</div>';
    return `<div class="gb-version-panel" style="overflow:auto;flex:1;padding:8px;">
      <div class="gb-version-panel-header" style="display:flex;align-items:center;gap:6px;padding-bottom:8px;border-bottom:1px solid var(--border);margin-bottom:8px;">
        ${typeof lucide === 'function' ? lucide('gitBranch', 16) : ''}
        <span style="font-weight:bold;font-size:13px;">アノテートのバージョン管理</span>
        <button class="gb-btn gb-btn-xs gb-btn-primary" ${this._versionButtonAttrs('annotationSave', path, '', 'annotations')}>+ 復元ポイントを作成</button>
        <button class="gb-btn gb-btn-xs gb-btn-quiet" ${this._versionButtonAttrs('refresh', path, '', 'annotations')} title="更新">${typeof lucide === 'function' ? lucide('refreshCw', 12) : '↻'}</button>
      </div>
      <div class="gb-section-desc" style="padding-bottom:8px;">${esc(path)}</div>
      <div class="gb-history-list">${rows}</div>
    </div>`;
  }

  getState() {
    return {
      versionPath: this.state.versionPath || '',
      versionType: this.state.versionType || 'file',
      timelineKind: this.state.timelineKind || 'named,auto,edit',
      timelineActorKind: this.state.timelineActorKind || '',
      // 対象未指定で開いた（パネルメニュー/コマンドパレット/右レール由来の）タブは true。
      // openVersionTab(path, type) 等でファイルを明示して開いたタブは false のままピン留めする。
      // 保存済みレイアウトから復元される旧タブにはこのフィールドが無いため、
      // restoreState 側で未指定時は false（=ピン留め扱い）に倒して互換性を保つ。
      versionFollow: !!this.state.versionFollow,
    };
  }

  restoreState(s) {
    super.restoreState(s);
    if (s) {
      this.state.versionPath = s.versionPath || '';
      this.state.versionType = s.versionType || 'file';
      this.state.timelineKind = s.timelineKind || 'named,auto,edit';
      this.state.timelineActorKind = s.timelineActorKind || '';
      this.state.versionFollow = !!s.versionFollow;
    }
  }
}

// === コンポーネントレジストリ登録 ===
// Audit-P2 H-7: requiresViewLock は計画書 §8.2 に基づく。
registerToolComponent('outliner',   { cls: OutlinerComponent, icon: 'folderTree', label: 'フォルダ', multi: false });
registerToolComponent('db',         { cls: DatabaseComponent, icon: 'db', label: 'シート', multi: true, requiresViewLock: true });
registerToolComponent('page',       { cls: EditorComponent, icon: 'page', label: 'ページ', multi: true, requiresViewLock: true });
// CanvasComponent は gb-tool-canvas.js で登録済み (Phase C)。計画書 §8.2 より requiresViewLock=false。
// CalendarComponent は gb-tool-calendar.js で登録済み (Phase C)。requiresViewLock=true。
registerToolComponent('chat',       { cls: ChatComponent, icon: 'messagesSquare', label: 'チャット', multi: false });
registerToolComponent('annotation', { cls: AnnotationComponent, icon: 'squarePen', label: 'アノテート', multi: false });
registerToolComponent('history',    { cls: HistoryComponent, icon: 'history', label: 'ヒストリー', multi: false });
registerToolComponent('detail',     { cls: DetailComponent, icon: 'slidersHorizontal', label: 'オプション', multi: false });
registerToolComponent('information',{ cls: InformationComponent, icon: 'info', label: 'プロパティ', multi: false });
registerToolComponent('backlinks',  { cls: BacklinksComponent, icon: 'fileSymlink', label: 'バックリンク', multi: false });
registerToolComponent('file-theme', { cls: FileThemeComponent, icon: 'palette', label: 'テーマ', multi: false });
registerToolComponent('folder',     { cls: FolderComponent, icon: 'folder', label: 'フォルダビュー', multi: true, requiresViewLock: true });
registerToolComponent('media',      { cls: MediaComponent, icon: 'galleryThumbnails', label: 'メディア', multi: true, requiresViewLock: true });
registerToolComponent('compare',    { cls: CompareComponent, icon: 'columns', label: '比較', multi: true, requiresViewLock: true });
registerToolComponent('version',    { cls: VersionComponent, icon: 'gitBranch', label: 'バージョン管理', multi: true });

;

/* === gb-tool-calendar.js === */
;
/* ==============================
   gb-tool-calendar.js: CalendarComponent (v5.0 Phase C)
   calendar.html → JSモジュール変換
   ============================== */

class CalendarComponent extends ToolComponent {
  constructor(paneId, tabId) {
    super(paneId, tabId);
    this._view = 'month';
    // _view は月・週・ToDoなどカレンダー内の表示形式を保持する。
    // 制作タスクリストは同名の既存ToDoと混同しないよう、独立した surface で切り替える。
    this._surface = 'calendar';
    this._date = new Date();
    this._events = [];
    this._tasks = [];
    this._calendars = [];
    this._visibleCalIds = new Set();
    this._selectedCalendarId = localStorage.getItem('gb:cal-selected-id') || '';
    this._shifts = [];
    this._undoStack = [];
    this._redoStack = [];
    this._undoLoadWindow = null;
    this._startDay = parseInt(localStorage.getItem('gb-cal-start-day') || '0');
    this._multiDayCount = this._normalizeMultiDayCount(localStorage.getItem('gb:cal-multi-day-count') || '3');
    this._ganttScale = localStorage.getItem('gb:cal-gantt-scale') || 'day';
    this._ganttGroup = localStorage.getItem('gb:cal-gantt-group') || 'none';
    this._selectedMiniDates = new Set();
    this._lastMiniDateStr = '';
    const sidebarMode = localStorage.getItem('gb:cal-sidebar-mode') || '';
    this._sidebarMode = sidebarMode || (localStorage.getItem('gb:cal-sidebar-only') === 'true' ? 'only' : 'all');
    this._sidebarOnly = this._sidebarMode === 'only';
    this._alarmInterval = null;
    this._alertedIds = new Set();
    this._clockEnabled = localStorage.getItem('gb:clock-enabled') === 'true';
    this._UNDO_MAX = 50;
    // DOM refs (set in create)
    this._contentEl = null;
    this._titleEl = null;
    this._sidebarEl = null;
    this._rightPanelEl = null;
    this._miniGridEl = null;
    this._miniTitleEl = null;
    this._todayTasksEl = null;
    this._calListEl = null;
    this._statusEl = null;
    this._clockBtnsEl = null;
    this._clockStatusEl = null;
    this._renderSeq = 0;
    this._initialized = false;
    this._initPromise = null;
    this._destroyed = false;
  }

  // === DOM生成 ===
  create() {
    this.el = document.createElement('div');
    this.el.className = 'gb-cal-root';
    this.el.innerHTML = CalendarComponent._buildHTML(this._startDay, this._multiDayCount);
    // DOM refs
    this._contentEl = this.el.querySelector('.gb-cal-content');
    this._titleEl = this.el.querySelector('.gb-cal-title');
    this._sidebarEl = this.el.querySelector('.gb-cal-sidebar');
    this._rightPanelEl = this.el.querySelector('.gb-cal-right-panel');
    this._miniGridEl = this.el.querySelector('.gb-cal-mini-grid');
    this._miniTitleEl = this.el.querySelector('.gb-cal-mini-title');
    this._todayTasksEl = this.el.querySelector('.gb-cal-today-tasks');
    this._calListEl = this.el.querySelector('.gb-cal-list');
    this._statusEl = this.el.querySelector('.gb-cal-status');
    this._clockBtnsEl = this.el.querySelector('.gb-cal-clock-buttons');
    this._clockStatusEl = null;
    this._bindToolbar();
    if (typeof this._bindProductionTemplateDnD === 'function') this._bindProductionTemplateDnD();
    this._bindSidebarResize();
    this._initClockPanel();
    if (typeof this._applySidebarMode === 'function') this._applySidebarMode();
    this._syncMultiDayControls();
    // ツールバーの操作グループ（.gb-cal-toolbar-actions）を、ツールバー自身が狭くなった
    // ときに優先ボタン＋あふれメニューへ畳む（狭幅ツールバー未対応の残作業）。
    window.MeldexCalToolbarOverflow?.setup?.(this.el);
    return this.el;
  }

  static _buildHTML(startDay, multiDayCount) {
    void startDay;
    return `<div class="gb-cal-status" role="status" aria-live="polite"></div>
<div class="gb-toolbar gb-toolbar-cal" role="toolbar" aria-label="スケジュール">
  <button type="button" class="tb-icon-btn tool-menu-btn" title="メニュー" aria-label="メニュー" aria-haspopup="menu" data-action="showToolMenu(event,'calendar')"><span class="ico ico-menu"></span></button>
  <button type="button" class="tb-icon-btn" title="フォルダツリーで表示" aria-label="フォルダツリーで表示" data-action="revealCurrentInFolderTree('calendar', event)"><span class="ico ico-folderTree"></span></button>
  <button type="button" class="tb-icon-btn gb-cal-calendar-control" data-cal-action="toggleSidebar" title="スケジュールサイドバー" aria-label="スケジュールサイドバー"><span class="ico ico-panelLeft"></span></button>
  <div class="sep"></div>
  <div class="gb-cal-surface-switch" role="tablist" aria-label="表示するシート">
    <button type="button" role="tab" class="tb-text-btn gb-inner-tab gb-cal-surface-btn gb-inner-tab-active" data-production-tab="calendar" data-cal-surface="calendar" data-e2e-id="gb-cal-surface-calendar" aria-selected="true" tabindex="0" title="カレンダーを表示">${lucide('calendarDays', 14)}<span class="gb-inner-tab-label">カレンダー</span></button>
    <button type="button" role="tab" class="tb-text-btn gb-inner-tab gb-cal-surface-btn" data-production-tab="tasks" data-cal-surface="productionTasks" data-e2e-id="gb-cal-surface-production-tasks" aria-selected="false" tabindex="-1" title="タスクリストを表示">${lucide('listTodo', 14)}<span class="gb-inner-tab-label">タスクリスト</span></button>
    <button type="button" role="tab" class="tb-text-btn gb-inner-tab gb-cal-surface-btn" data-production-tab="works" data-production-managed-list="works" data-e2e-id="gb-cal-surface-managed-works" aria-selected="false" tabindex="-1" title="プロジェクト一覧を表示">${lucide('folderKanban', 14)}<span class="gb-inner-tab-label">プロジェクト一覧</span></button>
  </div>
  <div class="sep gb-cal-calendar-control"></div>
  <button type="button" class="tb-icon-btn gb-cal-calendar-control" data-cal-action="today" title="今日に戻る" aria-label="今日に戻る">${lucide('calendar', 16)}</button>
  <button type="button" class="tb-icon-btn gb-cal-calendar-control" data-cal-action="prev" title="前へ" aria-label="前へ">${lucide('chevronLeft', 16)}</button>
  <span class="tb-title gb-cal-title gb-cal-calendar-control">---</span>
  <button type="button" class="tb-icon-btn gb-cal-calendar-control" data-cal-action="next" title="次へ" aria-label="次へ">${lucide('chevronRight', 16)}</button>
  <div class="sep gb-cal-calendar-control"></div>
  <select class="tb-select gb-cal-view-select gb-cal-calendar-control" title="表示" aria-label="表示" data-cal-setting="view">
    <option value="month">月</option>
    <option value="week">週</option>
    <option value="multi">複数日</option>
    <option value="day">日</option>
    <option value="tasks">ToDoリスト</option>
    <option value="shifts">シフト</option>
    <option value="gantt">ガント</option>
    <option value="clock12">アナログ時計（12時間）</option>
    <option value="clock24">アナログ時計（24時間）</option>
  </select>
  <input class="tb-input gb-cal-multi-day-count gb-cal-calendar-control" type="number" min="2" max="14" step="1" value="${multiDayCount || 3}" title="表示日数" aria-label="表示日数" data-cal-setting="multi-day-count" style="width:48px;" hidden>
  <div class="tb-spacer"></div>
  <div class="gb-cal-toolbar-actions">
    <button type="button" class="tb-icon-btn gb-cal-calendar-control" data-cal-action="undo" title="元に戻す (Ctrl+Z)" aria-label="元に戻す" data-undo-button><span class="ico ico-undo2"></span></button>
    <button type="button" class="tb-icon-btn gb-cal-calendar-control" data-cal-action="redo" title="やり直し (Ctrl+Y)" aria-label="やり直し" data-redo-button><span class="ico ico-redo2"></span></button>
    <div class="sep gb-cal-calendar-control"></div>
    <button type="button" class="tb-icon-btn gb-cal-production-control" data-cal-action="sheetAutoFit" data-e2e-id="gb-production-sheet-auto-fit" title="列幅自動調整" aria-label="列幅自動調整"><span class="ico ico-columns3"></span></button>
    <button type="button" class="tb-icon-btn gb-cal-production-control" data-cal-action="sheetColumnDisplayOrder" data-e2e-id="gb-production-sheet-column-display-order" title="列の表示と順序" aria-label="列の表示と順序"><span class="ico ico-listChecks"></span></button>
    <button type="button" class="tb-icon-btn gb-cal-production-control" data-cal-action="sheetFilter" data-e2e-id="gb-production-sheet-filter" title="フィルタ" aria-label="フィルタ"><span class="ico ico-filter"></span></button>
    <button type="button" class="tb-icon-btn gb-cal-production-control" data-cal-action="sheetSort" data-e2e-id="gb-production-sheet-sort" title="並び替え" aria-label="並び替え" aria-haspopup="menu"><span class="ico ico-arrowUpDown"></span></button>
    <div class="sep gb-cal-production-control"></div>
    <button type="button" class="tb-icon-btn gb-cal-production-control" data-cal-action="bulkCreateTasks" data-e2e-id="gb-production-bulk-create-open" data-production-write-action="1" title="タスクを一括作成" aria-label="タスクを一括作成">${lucide('listPlus', 16)}</button>
    <button type="button" class="tb-icon-btn gb-cal-production-control" data-cal-action="recalculate" data-e2e-id="gb-production-task-recalculate" title="自動割り当て" aria-label="自動割り当て">${lucide('calculator', 16)}</button>
    <button type="button" class="tb-icon-btn gb-cal-production-control" data-cal-action="productionManagement" data-e2e-id="gb-production-management-open" title="管理操作" aria-label="管理操作">${lucide('settings2', 16)}</button>
    <button type="button" class="tb-icon-btn" data-cal-action="template" title="テンプレート" aria-label="テンプレート" data-e2e-id="gb-production-open-templates">${lucide('layoutTemplate', 16)}</button>
    <div class="sep gb-cal-calendar-control"></div>
    <button type="button" class="tb-icon-btn" data-cal-action="reload" title="再読み込み" aria-label="再読み込み" data-e2e-id="gb-production-task-refresh"><span class="ico ico-refreshCw"></span></button>
    <button type="button" class="tb-icon-btn gb-cal-calendar-control" data-cal-action="sync" title="同期" aria-label="同期"><span class="ico ico-calendarSync"></span></button>
    <button type="button" class="tb-icon-btn gb-toolbar-option-panel-btn" data-cal-action="detail" title="オプションを開く" aria-label="オプションを開く"><span class="ico ico-slidersHorizontal"></span></button>
  </div>
</div>
<div class="gb-cal-main">
  <div class="gb-cal-sidebar">
    <div class="gb-cal-clock-panel">
      <div style="display:flex;align-items:center;margin-bottom:8px;">
        <span style="font-size:13px;font-weight:bold;flex:1;">打刻</span>
        <label style="font-size:11px;color:var(--cal-muted-fg, var(--fg2));cursor:pointer;display:flex;align-items:center;gap:3px;">
          <input type="checkbox" class="gb-cal-clock-toggle" data-cal-setting="clock-enabled" aria-label="打刻を有効にする"> 有効
        </label>
      </div>
      <div class="gb-cal-clock-buttons" style="display:none;">
        <button type="button" class="gb-cal-clock-btn clock-in" data-clock="clock_in" aria-label="出勤">出勤</button>
        <button type="button" class="gb-cal-clock-btn clock-out" data-clock="clock_out" aria-label="退勤">退勤</button>
        <button type="button" class="gb-cal-clock-btn break" data-clock="break_start" aria-label="離席">離席</button>
        <button type="button" class="gb-cal-clock-btn break" data-clock="break_end" aria-label="復帰">復帰</button>
      </div>
    </div>
    <div class="gb-cal-mini">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
        <button type="button" class="gb-cal-mini-nav" data-cal-action="miniPrev" title="前の月" aria-label="前の月">${lucide('chevronLeft', 12)}</button>
        <span class="gb-cal-mini-title" style="font-size:12px;font-weight:bold;"></span>
        <button type="button" class="gb-cal-mini-nav" data-cal-action="miniNext" title="次の月" aria-label="次の月">${lucide('chevronRight', 12)}</button>
      </div>
      <div class="gb-cal-mini-grid"></div>
    </div>
    <div><div class="gb-cal-sidebar-title-row"><span>今日のToDo</span><button type="button" data-cal-action="addTodayTask" class="gb-cal-sidebar-add-task" title="ToDo追加" aria-label="今日のToDoを追加">${lucide('plus', 16)}</button></div><div class="gb-cal-today-tasks" style="font-size:12px;"></div></div>
    <div style="margin-top:12px;">
      <div class="gb-cal-sidebar-title-row">
        <span>カレンダー</span>
        <button type="button" data-cal-action="createCalendar" class="gb-cal-sidebar-add-task gb-cal-sidebar-add-calendar" title="新規カレンダー" aria-label="新規カレンダー">${lucide('plus', 16)}</button>
      </div>
      <div class="gb-cal-list" style="font-size:12px;"></div>
    </div>
  </div>
  <div class="gb-cal-sidebar-resize"></div>
  <div class="gb-cal-content"></div>
  <div class="gb-cal-right-panel"></div>
</div>`;
  }

  _bindToolbar() {
    this.el.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-cal-action]');
      if (btn) { this._handleAction(btn.dataset.calAction, btn); return; }
      const surfaceBtn = e.target.closest('button[data-production-tab]');
      if (surfaceBtn) {
        const key = surfaceBtn.dataset.productionTab;
        if (typeof this._selectProductionTab === 'function') this._selectProductionTab(key);
        else this.setSurface(key === 'calendar' ? 'calendar' : 'productionTasks');
        return;
      }
      const viewBtn = e.target.closest('[data-cal-view]');
      if (viewBtn) { this.setView(viewBtn.dataset.calView); return; }
      const clockBtn = e.target.closest('[data-clock]');
      if (clockBtn) { this._clockAction(clockBtn.dataset.clock); return; }
    });
    const sel = this.el.querySelector('.gb-cal-start-day-sel');
    if (sel) sel.addEventListener('change', () => { this._startDay = parseInt(sel.value); localStorage.setItem('gb-cal-start-day', this._startDay); this._render(); this._renderMiniCal(); });
    const viewSel = this.el.querySelector('.gb-cal-view-select');
    if (viewSel) viewSel.addEventListener('change', () => this.setView(viewSel.value));
    const multiDayCount = this.el.querySelector('.gb-cal-multi-day-count');
    if (multiDayCount) {
      multiDayCount.addEventListener('change', () => {
        this._multiDayCount = this._normalizeMultiDayCount(multiDayCount.value);
        localStorage.setItem('gb:cal-multi-day-count', String(this._multiDayCount));
        this._selectedMiniDates.clear();
        this._lastMiniDateStr = '';
        if (this._view !== 'multi') this.setView('multi');
        else { this._syncMultiDayControls(); this._render(); this._renderMiniCal(); }
      });
    }
    const surfaceSwitch = this.el.querySelector('.gb-cal-surface-switch');
    surfaceSwitch?.addEventListener('keydown', event => {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      const tabs = [...surfaceSwitch.querySelectorAll('[role="tab"]')].filter(tab => !tab.disabled);
      const current = event.target.closest('[role="tab"]');
      const index = tabs.indexOf(current);
      if (index < 0 || !tabs.length) return;
      event.preventDefault();
      const nextIndex = event.key === 'Home' ? 0
        : event.key === 'End' ? tabs.length - 1
        : (index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
      tabs[nextIndex].focus();
      tabs[nextIndex].click();
    });
  }

  _openDetailPanel() {
    const panel = document.getElementById('right-panel');
    const activeTab = document.querySelector('.rp-tab.active')?.dataset.rpTab;
    const detailOpen = !!(panel?.classList.contains('open') && activeTab === 'detail');
    if (!detailOpen) {
      if (typeof toggleOptionPanel === 'function') toggleOptionPanel();
      else if (typeof toggleDetailPanel === 'function') toggleDetailPanel();
    }
    if (typeof this._syncDetailPanel === 'function') this._syncDetailPanel();
  }

  _handleAction(action, anchor) {
    switch (action) {
      case 'today':
        this._date = new Date();
        // ミニカレンダーの複数選択が残っていると表示が変わらないため、今日基準へ戻す
        this._selectedMiniDates?.clear?.();
        this._lastMiniDateStr = '';
        if (typeof this._persistViewToTabState === 'function') this._persistViewToTabState();
        this._loadEvents().then(() => this._render());
        this._renderMiniCal();
        break;
      case 'prev': this._goNav(-1); break;
      case 'next': this._goNav(1); break;
      case 'template':
        if (this._surface === 'productionTasks' && window.MeldexProductionSidebar?.showTemplates) {
          window.MeldexProductionSidebar.showTemplates(this);
        } else {
          this._showScheduleTemplateModal();
        }
        break;
      case 'bulkCreateTasks':
        if (window.MeldexProductionUiAvailability?.ensureWritable?.() === false) break;
        if (this._surface === 'productionTasks' && typeof this._openProductionTaskCreate === 'function') {
          this._openProductionTaskCreate(anchor);
        }
        break;
      case 'recalculate':
        if (this._surface === 'productionTasks' && typeof this._openProductionRecalculate === 'function') {
          this._openProductionRecalculate(anchor);
        }
        break;
      case 'productionManagement':
        if (this._surface === 'productionTasks') window.MeldexProductionSidebar?.showActions?.(this);
        break;
      case 'sheetAutoFit':
      case 'sheetColumnDisplayOrder':
      case 'sheetFilter':
      case 'sheetSort':
        if (this._surface === 'productionTasks' && typeof this._runProductionSheetDisplayAction === 'function') {
          this._runProductionSheetDisplayAction(action, anchor);
        }
        break;
      case 'undo': if (typeof meldexUndo === 'function') meldexUndo(); break;
      case 'redo': if (typeof meldexRedo === 'function') meldexRedo(); break;
      case 'reload': this.reload(); break;
      case 'sync': this._showSyncModal(); break;
      case 'toggleSidebar': this._toggleSidebar(); break;
      case 'sidebarOnly': if (typeof this._setSidebarOnly === 'function') this._setSidebarOnly(!this._sidebarOnly); break;
      case 'detail': this._openDetailPanel(); break;
      case 'addTodayTask':
        if (typeof this._createTaskQuick === 'function') this._createTaskQuick({ status: 'todo', due_date: this._localDateStr() });
        else this._showTaskModal(null, 'todo');
        break;
      case 'miniPrev': this._addMonths(-1); this._renderMiniCal(); this._loadEvents().then(() => this._render()); break;
      case 'miniNext': this._addMonths(1); this._renderMiniCal(); this._loadEvents().then(() => this._render()); break;
      case 'createCalendar':
        if (typeof this._showCreateCalendarMenu === 'function') this._showCreateCalendarMenu(anchor);
        else this._createCalendar();
        break;
    }
  }

  _goNav(dir) {
    if (this._view === 'month') this._addMonths(dir);
    else if (this._view === 'week') this._date.setDate(this._date.getDate() + dir * 7);
    else if (this._view === 'multi') {
      const selected = this._selectedMiniDateList();
      if (selected.length > 1) this._shiftSelectedMiniDates(dir * selected.length);
      else this._date.setDate(this._date.getDate() + dir * this._multiDayCount);
    }
    else if (this._view === 'shifts') this._addMonths(dir); // シフト表は月単位の表のため月送り
    else if (this._view === 'gantt') {
      const step = this._ganttScale === 'month' ? 90 : this._ganttScale === 'week' ? 21 : 7;
      this._date.setDate(this._date.getDate() + dir * step);
    }
    else this._date.setDate(this._date.getDate() + dir);
    this._loadEvents().then(() => this._render());
    this._renderMiniCal();
  }

  // === ライフサイクル ===
  activate() {
    const wasActive = this._active;
    super.activate();
    if (this._initPromise) return;
    if (this._initialized) {
      if (!wasActive) this._refreshAfterActivation();
      return;
    }
    this._initPromise = this._init().catch(error => {
      this._initialized = false;
      console.warn('[CalendarComponent] init failed:', error);
    }).finally(() => {
      this._initPromise = null;
    });
  }

  deactivate() {
    super.deactivate();
    // アラーム監視はタブ非表示中も継続する（停止すると裏で作業中に通知を取り逃すため、解除は destroy 時のみ）
    if (typeof this._clearNowLineTimer === 'function') this._clearNowLineTimer();
  }

  destroy() {
    this._destroyed = true;
    if (this._alarmInterval) clearInterval(this._alarmInterval);
    if (typeof this._clearNowLineTimer === 'function') this._clearNowLineTimer();
    if (this.el) window.MeldexCalToolbarOverflow?.teardown?.(this.el);
    super.destroy();
  }

  async _init() {
    if (this._initialized) return;
    this._initialized = true;
    await Promise.all([this._loadEvents(), this._loadTasks(), this._loadCalendars()]);
    if (this._destroyed || !this._active) return;
    this._refreshAfterActivation();
  }

  _refreshAfterActivation() {
    if (this._destroyed || !this._active) return;
    this._render();
    this._renderMiniCal();
    this._renderTodayTasks();
    this._updateClockStatus();
    this._ensureAlarmTimer();
    if (typeof this._syncHistoryScope === 'function') this._syncHistoryScope();
    if (typeof updateUndoRedoButtonStates === 'function') updateUndoRedoButtonStates();
  }

  _ensureAlarmTimer() {
    if (this._destroyed || !this._active) return;
    if (!this._alarmInterval) {
      this._alarmInterval = setInterval(() => this._checkAlarms(), 60000);
      setTimeout(() => this._checkAlarms(), 3000);
    }
  }

  handleKeyDown(e) {
    // テキスト入力中はカレンダーのアンドゥで横取りせず、入力欄のネイティブUndoに任せる
    const target = e.target;
    if (target instanceof Element && (target.closest('input, textarea, select') || target.isContentEditable)) return false;
    if (e.ctrlKey && e.key === 'z' && !e.shiftKey) { e.preventDefault(); this._undo(); return true; }
    if ((e.ctrlKey && e.key === 'y') || (e.ctrlKey && e.shiftKey && e.key === 'z')) { e.preventDefault(); this._redo(); return true; }
    return false;
  }

  // === 状態永続化 ===
  getState() {
    return {
      view: this._view,
      surface: this._surface,
      calendarPath: this.state.calendarPath || '',
      multiDayCount: this._multiDayCount,
      selectedMiniDates: this._selectedMiniDateList(),
      ganttScale: this._ganttScale,
      ganttGroup: this._ganttGroup,
      productionTaskSelection: this.state.productionTaskSelection || null,
      productionTaskLastSheetName: this.state.productionTaskLastSheetName || '',
    };
  }
  restoreState(s) {
    super.restoreState(s);
    if (s) {
      this._view = s.view || 'month';
      this._surface = s.surface === 'productionTasks' ? 'productionTasks' : 'calendar';
      this.state.calendarPath = s.calendarPath || '';
      this._multiDayCount = this._normalizeMultiDayCount(s.multiDayCount || this._multiDayCount);
      this._selectedMiniDates = new Set(Array.isArray(s.selectedMiniDates) ? s.selectedMiniDates.filter(v => /^\d{4}-\d{2}-\d{2}$/.test(String(v))) : []);
      this._lastMiniDateStr = this._selectedMiniDateList()[0] || '';
      this._ganttScale = ['day', 'week', 'month'].includes(s.ganttScale) ? s.ganttScale : this._ganttScale;
      this._ganttGroup = ['none', 'calendar', 'source'].includes(s.ganttGroup) ? s.ganttGroup : this._ganttGroup;
    }
  }

  // === 公開API (postMessage置換) ===
  pushUndo(label) { this._pushUndo(label); }
  async reload() {
    const requests = [this._loadTasks()];
    if (typeof this._refreshShiftStateAfterMutation === 'function') {
      requests.push(this._refreshShiftStateAfterMutation({ renderCalendarList: false }));
    } else {
      requests.push(this._loadEvents(), this._loadCalendars());
    }
    if (this._surface === 'productionTasks' && typeof this._refreshProductionTaskEmbed === 'function') {
      requests.push(this._refreshProductionTaskEmbed());
    }
    await Promise.all(requests);
    this._render();
    this._renderMiniCal();
    this._renderTodayTasks();
  }

  // === ユーティリティ ===
  _getUser() { try { return JSON.parse(localStorage.getItem('meldex-user') || '{}').name || 'anonymous'; } catch { return 'anonymous'; } }
  _normalizeMultiDayCount(value) {
    const n = parseInt(value, 10);
    return Math.max(2, Math.min(14, Number.isFinite(n) ? n : 3));
  }
  _addMonths(delta) {
    const d = this._date;
    const originalDay = d.getDate();
    d.setDate(1);
    d.setMonth(d.getMonth() + delta);
    d.setDate(Math.min(originalDay, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
  }
  _localDateStr(d) { if (!d) d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
  _localDateTimeStr(d) {
    if (!d) d = new Date();
    return `${this._localDateStr(d)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
  }
  _parseLocalDate(dateStr) {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(dateStr || ''));
    if (!match) return new Date(dateStr);
    return new Date(parseInt(match[1], 10), parseInt(match[2], 10) - 1, parseInt(match[3], 10));
  }
  _getDayNames() { const a = ['日','月','火','水','木','金','土']; return [...a.slice(this._startDay), ...a.slice(0, this._startDay)]; }
  _isCalVisible(ev) { if (this._calendars.length === 0 || !ev.calendar_id) return true; return this._visibleCalIds.has(ev.calendar_id); }

  _firstCalendar() {
    const calendars = this._calendars || [];
    const visible = calendars.filter(c => this._visibleCalIds?.has(c.id));
    return visible[0] || calendars[0] || null;
  }
  _selectedMiniDateList() {
    return [...(this._selectedMiniDates || new Set())].filter(v => /^\d{4}-\d{2}-\d{2}$/.test(String(v))).sort();
  }
  _multiDayDateStrs() {
    const selected = this._selectedMiniDateList();
    if (selected.length > 1) return selected;
    const out = [];
    const start = new Date(this._date);
    for (let i = 0; i < this._multiDayCount; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      out.push(this._localDateStr(d));
    }
    return out;
  }
  _shiftSelectedMiniDates(days) {
    const shifted = this._selectedMiniDateList().map(dateStr => {
      const d = this._parseLocalDate(dateStr);
      d.setDate(d.getDate() + days);
      return this._localDateStr(d);
    });
    this._selectedMiniDates = new Set(shifted);
    if (shifted[0]) this._date = this._parseLocalDate(shifted[0]);
    this._lastMiniDateStr = shifted[0] || '';
  }
  _syncMultiDayControls() {
    const input = this.el?.querySelector?.('.gb-cal-multi-day-count');
    if (!input) return;
    input.hidden = this._view !== 'multi';
    input.value = String(this._selectedMiniDateList().length > 1 ? this._selectedMiniDateList().length : this._multiDayCount);
  }
  _multiDayTitle() {
    const dates = this._multiDayDateStrs();
    if (!dates.length) return '複数日';
    const first = dates[0];
    const last = dates[dates.length - 1];
    return first === last ? first : `${first} – ${last}（${dates.length}日）`;
  }

  _selectedCalendar() {
    const calendars = this._calendars || [];
    if (this._selectedCalendarId) {
      const selected = calendars.find(c => c.id === this._selectedCalendarId);
      if (selected && this._visibleCalIds?.has(selected.id)) return selected;
    }
    return this._firstCalendar();
  }

  _calendarIdForNewEvent() {
    const cal = this._selectedCalendar() || this._firstCalendar();
    if (cal && !this._visibleCalIds.has(cal.id)) {
      this._visibleCalIds.add(cal.id);
      apiPut('/cal/calendars/' + cal.id + '?_user=' + encodeURIComponent(this._getUser()), { visible: 1 }).catch(() => {});
      this._renderCalendarList?.();
    }
    return cal?.id || '';
  }

  _ensureSelectedCalendar() {
    const cal = this._selectedCalendar();
    this._selectedCalendarId = cal?.id || '';
    if (this._selectedCalendarId) localStorage.setItem('gb:cal-selected-id', this._selectedCalendarId);
    else localStorage.removeItem('gb:cal-selected-id');
    return cal;
  }

  _selectCalendar(id, options = {}) {
    const cal = (this._calendars || []).find(c => c.id === id);
    if (!cal) return null;
    this._selectedCalendarId = cal.id;
    localStorage.setItem('gb:cal-selected-id', cal.id);
    if (options.ensureVisible !== false && !this._visibleCalIds.has(cal.id)) {
      this._visibleCalIds.add(cal.id);
      apiPut('/cal/calendars/' + cal.id + '?_user=' + encodeURIComponent(this._getUser()), { visible: 1 }).catch(() => {});
    }
    if (options.render !== false) {
      this._renderCalendarList();
      this._render();
    }
    return cal;
  }

  _showStatus(msg, isError) {
    if (!this._statusEl?.isConnected) this._statusEl = this.el?.querySelector('.gb-cal-status') || null;
    if (this._statusEl) { this._statusEl.textContent = msg; this._statusEl.style.color = isError ? 'var(--red)' : 'var(--cal-muted-fg, var(--fg2))'; }
    // 親のshowStatusも呼ぶ
    if (typeof showStatus === 'function') showStatus(msg, isError);
  }

  // === データロード ===
  async _loadEvents() {
    const y = this._date.getFullYear(), m = this._date.getMonth();
    const start = new Date(y, m - 1, 1).toISOString();
    const end = new Date(y, m + 2, 0).toISOString();
    this._guardUndoLoadWindow(start + '|' + end, start, end);
    const seq = (this._loadEventsSeq = (this._loadEventsSeq || 0) + 1);
    try {
      const events = await apiFetch('/cal/events?start=' + encodeURIComponent(start) + '&end=' + encodeURIComponent(end) + '&user=' + encodeURIComponent(this._getUser()));
      if (seq !== this._loadEventsSeq) return { ok: true, stale: true }; // 古い読み込み窓の応答は破棄（連打時の巻き戻り防止）
      this._events = events;
      return { ok: true, stale: false };
    } catch (error) {
      if (seq !== this._loadEventsSeq) return { ok: true, stale: true };
      if (!Array.isArray(this._events)) this._events = [];
      this._showStatus('予定の読み込みに失敗', true);
      return { ok: false, stale: false, error };
    }
  }

  // 読み込み窓（表示期間）が変わったらアンドゥ履歴を破棄する。
  // 窓違いのスナップショット復元は、現在の窓にだけ存在する予定を巻き添え削除するため
  _guardUndoLoadWindow(windowKey, start, end) {
    if (this._undoWindowKey && this._undoWindowKey !== windowKey && this._hasUndoHistoryEntries()) {
      this._clearUndoStacks();
      this._notifyParentHistory();
    }
    this._undoWindowKey = windowKey;
    this._undoLoadWindow = { key: windowKey, start, end };
  }

  // 共通履歴（'schedule:<tabId>' スコープ）と自己完結スタックの両方をまたいで
  // 「取り消せる/やり直せる操作が何かあるか」を判定する（表示期間変更時の破棄要否判定用）。
  _hasUndoHistoryEntries() {
    if (this._undoStack.length || this._redoStack.length) return true;
    if (typeof _schedHasCommonHistory === 'function' && _schedHasCommonHistory() && typeof _historyStacks !== 'undefined') {
      const stack = _historyStacks[_schedHistoryScope(this)];
      if (stack && (stack.undo.length || stack.redo.length)) return true;
    }
    return false;
  }

  // 共通履歴のこのタブ用スコープと、自己完結スタックの両方をクリアする
  // （ボードの bdClearUndoStacks() と同じ二重クリア方式。表示期間変更時に呼ばれる）。
  _clearUndoStacks() {
    if (typeof _schedHasCommonHistory === 'function' && _schedHasCommonHistory() && typeof _historyStacks !== 'undefined') {
      const stack = _historyStacks[_schedHistoryScope(this)];
      if (stack) { stack.undo.length = 0; stack.redo.length = 0; }
    }
    this._undoStack.length = 0;
    this._redoStack.length = 0;
  }

  async _loadTasks() {
    const seq = (this._loadTasksSeq = (this._loadTasksSeq || 0) + 1);
    const user = this._getUser();
    const stale = () => this._destroyed || seq !== this._loadTasksSeq || user !== this._getUser();
    try {
      const tasks = await apiFetch('/cal/tasks?user=' + encodeURIComponent(user));
      if (stale()) return { ok: true, stale: true };
      if (!Array.isArray(tasks)) throw new Error('Invalid ToDo response');
      this._tasks = tasks;
      return { ok: true, stale: false };
    } catch (error) {
      if (stale()) return { ok: true, stale: true };
      if (!Array.isArray(this._tasks)) this._tasks = [];
      this._showStatus('ToDoリストの読み込みに失敗', true);
      return { ok: false, stale: false, error };
    }
  }

  async _loadCalendars() {
    try {
      this._calendars = await apiFetch('/cal/calendars?user=' + encodeURIComponent(this._getUser()));
      if (this._calendars.length === 0) {
        await apiPost('/cal/calendars', { name: 'マイカレンダー', color: '#569cd6', user: this._getUser() });
        this._calendars = await apiFetch('/cal/calendars?user=' + encodeURIComponent(this._getUser()));
      }
      this._visibleCalIds = new Set(this._calendars.filter(c => c.visible).map(c => c.id));
      this._ensureSelectedCalendar();
      this._renderCalendarList();
    } catch {}
  }

  // === Undo/Redo ===
  _eventIsUndoable(ev) {
    // 自動生成イベント（シフト・実績・制作タスク由来）は元データ側が正本のため undo 対象にしない
    // （対象にすると undo がミラーだけを通常イベントとして再作成し、実データと乖離した幽霊行が残る）
    return ev && !ev._recurrence_instance
      && !['shift', 'shift-break', 'attendance', 'production-task', 'renderlist'].includes(String(ev.calendar_source || ''));
  }

  _snapshotEventsForUndo() {
    const seen = new Set();
    return (this._events || []).filter(ev => {
      if (!this._eventIsUndoable(ev) || !ev.id || seen.has(ev.id)) return false;
      seen.add(ev.id);
      return true;
    }).map(ev => JSON.parse(JSON.stringify(ev)));
  }

  _snapshotTasksForUndo() {
    return JSON.parse(JSON.stringify(this._tasks || []));
  }

  _snapshotEventWindowForUndo() {
    return this._undoLoadWindow ? { ...this._undoLoadWindow } : null;
  }

  _eventIntersectsUndoWindow(ev, windowInfo) {
    if (!windowInfo?.start || !windowInfo?.end) return true;
    const windowStart = Date.parse(windowInfo.start);
    const windowEnd = Date.parse(windowInfo.end);
    if (!Number.isFinite(windowStart) || !Number.isFinite(windowEnd)) return true;
    const eventStart = Date.parse(ev?.start || ev?.end || '');
    const eventEnd = Date.parse(ev?.end || ev?.start || '');
    if (!Number.isFinite(eventStart) || !Number.isFinite(eventEnd)) return true;
    return eventEnd >= windowStart && eventStart <= windowEnd;
  }

  // v0.6.199: 共通履歴（gb-history.js）が読み込まれている環境（本体アプリ）では
  // 'schedule:<tabId>' スコープの共通履歴（historyPush）へ委譲し、右パネルの操作履歴タブ・
  // 操作履歴パネルの両方と連動する。共通履歴が無い環境（将来の単独起動・テストスタブ向けの保険。
  // 現状このコンポーネントを読み込む単独起動アプリは存在しない）は、従来どおり
  // this._undoStack/_redoStack の自己完結スタックへ自動フォールバックし挙動を変えない。
  _pushUndo(label) {
    if (typeof _schedHasCommonHistory === 'function' && _schedHasCommonHistory()) {
      const snap = { events: this._snapshotEventsForUndo(), tasks: this._snapshotTasksForUndo(), eventWindow: this._snapshotEventWindowForUndo() };
      historyPush(label, () => this._restoreSnapshot(snap), null, _schedHistoryScope(this));
    } else {
      this._undoStack.push({ label, events: this._snapshotEventsForUndo(), tasks: this._snapshotTasksForUndo(), eventWindow: this._snapshotEventWindowForUndo() });
      if (this._undoStack.length > this._UNDO_MAX) this._undoStack.shift();
      this._redoStack.length = 0;
    }
    this._notifyParentHistory();
  }

  async _undo() {
    // 復元はサーバーへの逐次API呼び出しを伴う長い処理のため、完了まで再入を受け付けない。
    // 共通履歴経路でも「component._undo()/_redo() を経由する限り」このガードで多重実行を防ぐ
    // （historyUndo() 自体は scope の stack.pop() を同期的に行うため、ガード無しで連打すると
    // 2件目の復元が1件目と並行実行され、レストア対象のずれや redo スタックの不整合を招く）。
    if (typeof _schedHasCommonHistory === 'function' && _schedHasCommonHistory()) {
      if (this._undoBusy) return;
      this._undoBusy = true;
      try { await historyUndo(_schedHistoryScope(this)); }
      finally { this._undoBusy = false; }
      return;
    }
    if (!this._undoStack.length || this._undoBusy) return;
    this._undoBusy = true;
    const entry = this._undoStack.pop();
    try {
      this._redoStack.push({ label: '(現在)', events: this._snapshotEventsForUndo(), tasks: this._snapshotTasksForUndo(), eventWindow: this._snapshotEventWindowForUndo() });
      await this._restoreSnapshot(entry);
      this._notifyParentHistory();
    } catch (error) {
      this._redoStack.pop();
      this._undoStack.push(entry);
      return false;
    } finally {
      this._undoBusy = false;
    }
  }

  async _redo() {
    if (typeof _schedHasCommonHistory === 'function' && _schedHasCommonHistory()) {
      if (this._undoBusy) return;
      this._undoBusy = true;
      try { await historyRedo(_schedHistoryScope(this)); }
      finally { this._undoBusy = false; }
      return;
    }
    if (!this._redoStack.length || this._undoBusy) return;
    this._undoBusy = true;
    const entry = this._redoStack.pop();
    try {
      this._undoStack.push({ label: '(現在)', events: this._snapshotEventsForUndo(), tasks: this._snapshotTasksForUndo(), eventWindow: this._snapshotEventWindowForUndo() });
      await this._restoreSnapshot(entry);
      this._notifyParentHistory();
    } catch (error) {
      this._undoStack.pop();
      this._redoStack.push(entry);
      return false;
    } finally {
      this._undoBusy = false;
    }
  }

  async _restoreSnapshot(snap) {
    const failures = [];
    const attempt = async (label, operation) => {
      try { await operation(); }
      catch (error) { failures.push(`${label}: ${error?.message || error}`); }
    };
    try {
      // 一時ID・保存未確定（saving/confirming/retrying/unsaved）のイベントは
      // まだサーバーに存在しないか状態が確定していないため、アンドゥ/リドゥの
      // DELETE・POST・PUT対象から除外する（送信するとサーバー側で不整合を招く）。
      const isPending = ev => window.MeldexCalendarSaveQueue?.isPendingEvent?.(ev) || false;
      const snapEvents = (snap.events || []).filter(ev => this._eventIsUndoable(ev) && !isPending(ev));
      const curEvents = (this._events || []).filter(ev => this._eventIsUndoable(ev) && !isPending(ev));
      const snapEvIds = new Set(snapEvents.map(e => e.id));
      const curEvIds = new Set(curEvents.map(e => e.id));
      for (const ev of curEvents) {
        if (!snapEvIds.has(ev.id) && this._eventIntersectsUndoWindow(ev, snap.eventWindow)) {
          await attempt(`イベント削除 ${ev.id}`, () => apiFetch('/cal/events/' + ev.id, { method: 'DELETE' }));
        }
      }
      for (const ev of snapEvents) {
        const { id, created, modified, uid, ical_uid, recurrence_id, original_start, ...data } = ev;
        data.user = data.user || this._getUser();
        if (curEvIds.has(id)) {
          await attempt(`イベント更新 ${id}`, () => apiPut('/cal/events/' + id, data));
        } else {
          await attempt(`イベント作成 ${id}`, async () => {
            try { await apiPost('/cal/events', { ...data, id }); }
            catch { await apiPut('/cal/events/' + id, data); }
          });
        }
      }
      const snapTasks = snap.tasks || [];
      const snapTkIds = new Set(snapTasks.map(t => t.id));
      const curTkIds = new Set((this._tasks || []).map(t => t.id));
      for (const t of this._tasks || []) {
        if (!snapTkIds.has(t.id)) await attempt(`ToDo削除 ${t.id}`, () => apiFetch('/cal/tasks/' + t.id, { method: 'DELETE' }));
      }
      for (const t of snapTasks) {
        const { id, created, modified, external_id, task_source, last_synced, ...data } = t;
        if (curTkIds.has(id)) await attempt(`ToDo更新 ${id}`, () => apiPut('/cal/tasks/' + id, data));
        else await attempt(`ToDo作成 ${id}`, () => apiPost('/cal/tasks', { ...data, id }));
      }
      await this._loadEvents(); await this._loadTasks();
      this._render(); this._renderTodayTasks();
      if (failures.length) throw new Error(failures.join(' / '));
      this._showStatus('元に戻しました');
    } catch (error) {
      // 部分成功時も現役サーバー状態を再取得済み。失敗を呼出元へ返して共通履歴が
      // entry を undo 側へ戻せるようにし、成功通知を出さない。
      this._showStatus('元に戻す操作に失敗', true);
      throw error;
    }
  }

  _notifyParentHistory() {
    if (typeof renderHistoryList === 'function') renderHistoryList();
  }

  // === ビュー切り替え ===
  setView(v) {
    this._view = v;
    this._surface = 'calendar';
    // タブの永続状態へ即時反映。パネル再マウント時に restoreState が
    // 古い activeTab.state で _view を上書きしてしまう問題を防ぐ。
    this._persistViewToTabState(v);
    this.el.querySelectorAll('.gb-toolbar-cal [data-cal-view]').forEach(b => b.classList.remove('active'));
    const btn = this.el.querySelector(`[data-cal-view="${v}"]`);
    if (btn) btn.classList.add('active');
    const sel = this.el.querySelector('.gb-cal-view-select');
    if (sel && sel.value !== v) sel.value = v;
    this._syncMultiDayControls();
    this._render();
  }

  setSurface(surface, onConfirmed) {
    const next = surface === 'productionTasks' ? 'productionTasks' : 'calendar';
    if (this._surface === next) {
      this._syncSurfaceControls();
      return true;
    }
    const applySurface = () => {
      this._surface = next;
      this._persistViewToTabState(this._view);
      this._syncSurfaceControls();
      this._render();
      if (typeof this._syncHistoryScope === 'function') this._syncHistoryScope();
      if (typeof updateUndoRedoButtonStates === 'function') updateUndoRedoButtonStates();
    };
    if (next === 'productionTasks') {
      const canSwitch = window.MeldexProductionSidebar?.prepareTaskListSurface?.(this, () => {
        applySurface();
        onConfirmed?.();
      });
      if (canSwitch === false) return false;
    }
    applySurface();
    return true;
  }

  _syncSurfaceControls() {
    if (!this.el) return;
    this.el.dataset.calSurface = this._surface;
    const activeKey = this._surface === 'calendar'
      ? 'calendar'
      : (typeof this._productionActiveTabKey === 'function' ? this._productionActiveTabKey() : 'tasks');
    let activeButton = null;
    this.el.querySelectorAll('[data-production-tab]').forEach(button => {
      const active = button.dataset.productionTab === activeKey;
      button.classList.toggle('gb-inner-tab-active', active);
      button.setAttribute('aria-selected', active ? 'true' : 'false');
      button.tabIndex = active ? 0 : -1;
      if (active) activeButton = button;
    });
    // The tab list wraps like Sheet view tabs.  Do not retain a legacy horizontal
    // scroll offset: every production surface remains visible at once.
    const tablist = this.el.querySelector('.gb-cal-surface-switch');
    if (activeButton && tablist) tablist.scrollLeft = 0;
  }

  _persistViewToTabState(view) {
    if (typeof GBLayout === 'undefined' || !GBLayout.root) return;
    try {
      const paneInfo = GBLayout.findNode?.(GBLayout.root, this.paneId);
      const tab = paneInfo?.node?.tabs?.find?.(t => t.id === this.tabId);
      if (!tab) return;
      if (!tab.state) tab.state = {};
      tab.state.view = view;
      tab.state.surface = this._surface;
      tab.state.multiDayCount = this._multiDayCount;
      tab.state.selectedMiniDates = this._selectedMiniDateList();
      tab.state.ganttScale = this._ganttScale;
      tab.state.ganttGroup = this._ganttGroup;
      tab.state.productionTaskSelection = this.state.productionTaskSelection || null;
      tab.state.productionTaskLastSheetName = this.state.productionTaskLastSheetName || '';
    } catch {}
  }

  // === メイン描画 ===
  _render() {
    const renderSeq = ++this._renderSeq;
    this._syncSurfaceControls();
    if (this._surface === 'productionTasks') {
      this._titleEl.textContent = '';
      this._syncMultiDayControls();
      if (typeof this._clearNowLineTimer === 'function') this._clearNowLineTimer();
      if (typeof this._renderProductionTaskView === 'function') this._renderProductionTaskView();
      else this._contentEl.textContent = 'タスクリストを初期化しています…';
      return;
    }
    if (typeof this._hideProductionTaskEmbed === 'function') this._hideProductionTaskEmbed();
    const y = this._date.getFullYear(), m = this._date.getMonth(), d = this._date.getDate();
    this._titleEl.textContent =
      this._view === 'day' ? `${y}年${m+1}月${d}日` :
      this._view === 'week' ? `${y}年${m+1}月 第${Math.ceil(d/7)}週` :
      this._view === 'multi' ? this._multiDayTitle() :
      this._view === 'tasks' ? 'ToDoリスト' :
      this._view === 'shifts' ? `${y}年${m+1}月 シフト表` :
      this._view === 'gantt' ? 'ガント' :
      `${y}年${m+1}月`;
    this._syncMultiDayControls();
    if (this._view === 'month') this._renderMonth();
    else if (this._view === 'week') this._renderWeek();
    else if (this._view === 'multi') this._renderMultiDays();
    else if (this._view === 'day') this._renderDay();
    else if (this._view === 'tasks') this._renderTaskBoard();
    else if (this._view === 'shifts') this._renderShiftView(renderSeq);
    else if (this._view === 'gantt' && typeof this._renderGantt === 'function') this._renderGantt();
    if (!['week', 'multi', 'day'].includes(this._view) && typeof this._clearNowLineTimer === 'function') this._clearNowLineTimer();
    // Audit-P1 H-6 (残作業): カレンダーイベント要素にコメントバッジを描画
    if (this._contentEl && typeof CommentBadges !== 'undefined' && typeof CommentBadges.refreshCalendar === 'function') {
      try { CommentBadges.refreshCalendar(this._contentEl); } catch (_) {}
    }
  }

  // 以降の描画メソッドは gb-tool-calendar-views.js に定義
}

/* ==============================
   v0.6.199: 「スケジュール」タブ本体（系統(A) CalendarComponent）の取り消し・やり直しを
   共通履歴（gb-history.js）へ統合するための補助関数。

   背景: 2026-07-19 に判明した既存不具合（AGENT_INBOX参照）— CalendarComponentは
   独自の this._undoStack/_redoStack を持つが、Ctrl+Z・ツールバーボタンのどちらからも
   到達できず、かつシートの「カレンダー表示モード」用の別系統(_calUndoStack, 系統(B))へ
   誤ってルーティングされていた。本ファイルの _pushUndo/_undo/_redo（上記）を
   'schedule:<tabId>' スコープの共通履歴へ統合し、gb-history.part02.js 側のルーターで
   このスコープを優先解決することで、系統(A)自身の予定/ToDo編集がCtrl+Z・ツールバー
   ボタン・履歴パネルの3経路すべてから機能するようにする（系統(B)は無変更）。

   スコープの接頭辞は 'calendar:' ではなく 'schedule:' を採用する。理由:
   gb-tool-calendar-options.js は既に 'calendar:settings'（サイドバー表示・週開始曜日等の
   localStorage設定変更用スコープ）を使っており、historyRegisterSnapshotProvider の
   マッチングは scope.startsWith(prefix) の前方一致で行われるため、'calendar:' を
   プレフィックス登録すると 'calendar:settings' にも誤って一致してしまう
   （設定変更のredoクロージャがスナップショット・プロバイダで上書きされ、
   設定変更のやり直しが壊れる）。'schedule:' なら前方一致の衝突が無い。

   tabId は getComponentInstance()/setComponentInstance() のキーと同一の値を使うため、
   スコープ文字列からコンポーネントインスタンスを逆引きできる（複数のスケジュールタブを
   同時に開いても、タブごとに独立した取り消し履歴になる）。
   ============================== */
function _schedHasCommonHistory() {
  return typeof historyPush === 'function' && typeof historyUndo === 'function' && typeof historyRedo === 'function';
}
function _schedHistoryScope(component) {
  return 'schedule:' + (component && component.tabId ? component.tabId : '');
}
function _schedComponentForScope(scope) {
  if (!scope || typeof scope !== 'string' || !scope.startsWith('schedule:')) return null;
  const tabId = scope.slice('schedule:'.length);
  if (!tabId || typeof getComponentInstance !== 'function') return null;
  const comp = getComponentInstance(tabId);
  return (comp && typeof CalendarComponent !== 'undefined' && comp instanceof CalendarComponent) ? comp : null;
}
// gb-history.part02.js の historyRegisterSnapshotProvider('schedule:', {...}) から呼ばれる
// capture/restore の実処理。既存の _snapshotXForUndo() 3点セット・_restoreSnapshot() を
// そのまま再利用し、挙動（何を保存し何を復元するか）は自己完結スタック時代と変えていない。
function _schedCaptureSnapshot(scope) {
  const comp = _schedComponentForScope(scope);
  if (!comp) return null;
  return {
    events: comp._snapshotEventsForUndo(),
    tasks: comp._snapshotTasksForUndo(),
    eventWindow: comp._snapshotEventWindowForUndo(),
  };
}
async function _schedRestoreSnapshot(snap, scope) {
  const comp = _schedComponentForScope(scope);
  if (!comp || snap == null) return;
  await comp._restoreSnapshot(snap);
}

// コンポーネントレジストリ更新
window.CalendarComponent = CalendarComponent;
registerToolComponent('calendar', { cls: CalendarComponent, icon: 'calendar', label: 'スケジュール', multi: true, requiresViewLock: true });

;

/* === gb-cal-toolbar-overflow.js === */
;
/* gb-cal-toolbar-overflow.js: スケジュールツールバーの操作グループを、ツールバー自身の
 * 実測幅に応じて優先ボタン＋あふれメニューへ畳む。
 *
 * 背景（狭幅ツールバー未対応の残作業）: .gb-cal-toolbar-actions は十数個のアイコン
 * ボタンと区切り線を並べるが、折返し（.gb-toolbar-cal の flex-wrap）で自分の行へ
 * 落ちるだけで、行自体の幅がツールバーより狭くなると操作グループごとツールバー右端の
 * 外側へはみ出し、操作が届かなくなっていた。単独アプリ（standalone-mobile-toolbar.js）
 * が使う「優先ボタン＋あふれメニュー」と同じ考え方を、ビューポート幅のメディアクエリ
 * ではなくツールバー自身の実測幅（ResizeObserver）で判定する形で適用する
 * （ウィンドウは変わらずオプションパネルの分割等でツールバー自体が狭くなるケースにも
 *   対応するため。単独アプリ側の判定方式はそのまま流用しない＝別モジュールとする）。
 *
 * 44px未満へのボタン縮小はしない（タップ領域の既定ルール）。入りきらない分は表示
 * サイズを変えず、区切り線ごと畳んだうえで丸ごと「その他」メニューへ移す。
 */
(function () {
  'use strict';
  if (typeof window === 'undefined') return;

  // 優先順位（数字が小さいほど狭幅でも残す）。表に無い data-cal-action は最初に畳む。
  const RANK = {
    detail: 0, productionManagement: 1, recalculate: 2,
    undo: 3, redo: 3, sync: 4,
    bulkCreateTasks: 5, sheetFilter: 6, reload: 7, sheetSort: 8,
    template: 9, sheetAutoFit: 10, sheetColumnDisplayOrder: 11, timer: 12,
  };

  const registry = new Map(); // toolbar要素 -> entry

  function _zoom() {
    return typeof window._getZoom === 'function' ? (window._getZoom() || 1) : 1;
  }

  function _isSep(el) { return el.classList.contains('sep'); }

  function _rankFor(el) {
    const action = el.dataset ? (el.dataset.calAction || '') : '';
    return Object.prototype.hasOwnProperty.call(RANK, action) ? RANK[action] : 99;
  }

  function _labelFor(el) {
    const aria = String(el.getAttribute('aria-label') || '').trim();
    if (aria) return aria;
    const title = String(el.getAttribute('title') || '').trim();
    return title || String(el.textContent || '').trim() || '操作';
  }

  function _iconHtmlFor(el) {
    const svg = el.querySelector('svg');
    if (svg) return svg.outerHTML;
    const ico = el.querySelector('.ico');
    return ico ? ico.outerHTML : '';
  }

  function _sumWidth(list, widthOf, gap) {
    if (!list.length) return 0;
    return list.reduce((sum, el) => sum + widthOf.get(el), 0) + gap * (list.length - 1);
  }

  function _createMoreButton() {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'tb-icon-btn gb-cto-more-btn';
    btn.title = 'その他の操作';
    btn.setAttribute('aria-label', 'その他の操作');
    btn.setAttribute('aria-haspopup', 'menu');
    btn.setAttribute('aria-expanded', 'false');
    btn.dataset.e2eId = 'gb-cal-toolbar-actions-more';
    btn.hidden = true;
    if (typeof lucide === 'function') btn.innerHTML = lucide('moreHorizontal', 16);
    return btn;
  }

  function _closeMenu(entry) {
    entry.menu?.remove();
    entry.menu = null;
    if (entry.menuKeydown) { document.removeEventListener('keydown', entry.menuKeydown); entry.menuKeydown = null; }
    if (entry.menuDismiss) { document.removeEventListener('pointerdown', entry.menuDismiss); entry.menuDismiss = null; }
    entry.moreBtn.setAttribute('aria-expanded', 'false');
  }

  // あふれた元ボタンは display:none のままなので、代理クリックの瞬間だけ実レイアウトを
  // 持たせる。並び替えメニュー等はクリックハンドラ内で anchor.getBoundingClientRect() を
  // 同期的に読んで位置決めする（gb-tool-calendar-production-task-view.part03.js の
  // _runProductionSheetDisplayAction 等）ため、非表示のままだと (0,0) 相当の矩形しか
  // 取れずポップアップが左上へ張り付く（standalone-mobile-toolbar.js と同じ手当て）。
  function _activateOverflowItem(entry, el, rowRect) {
    if (el.disabled) return;
    _closeMenu(entry);
    const prevStyle = el.getAttribute('style');
    const set = (prop, value) => el.style.setProperty(prop, value, 'important');
    set('display', 'inline-flex');
    set('position', 'fixed');
    set('left', Math.max(0, rowRect.left) + 'px');
    set('top', Math.max(0, rowRect.top) + 'px');
    set('width', (rowRect.width || 22) + 'px');
    set('height', (rowRect.height || 22) + 'px');
    set('margin', '0');
    set('visibility', 'hidden');
    set('pointer-events', 'none');
    set('z-index', '-1');
    try { el.click(); }
    finally {
      if (prevStyle === null) el.removeAttribute('style');
      else el.setAttribute('style', prevStyle);
    }
    entry.moreBtn.focus?.({ preventScroll: true });
  }

  function _openMenu(entry) {
    if (entry.menu) { _closeMenu(entry); return; }
    const items = entry.overflowItems || [];
    if (!items.length) return;
    const menu = document.createElement('div');
    menu.className = 'gb-context-menu gb-cal-toolbar-overflow-menu';
    menu.dataset.e2eId = 'gb-cal-toolbar-actions-overflow-menu';
    menu.setAttribute('role', 'menu');
    items.forEach(el => {
      const row = document.createElement('div');
      row.className = 'gb-context-menu-item' + (el.disabled ? ' disabled' : '');
      row.setAttribute('role', 'menuitem');
      if (el.dataset?.e2eId) row.dataset.e2eId = 'gb-cal-toolbar-overflow-' + el.dataset.e2eId;
      row.innerHTML = _iconHtmlFor(el) + ' ';
      row.appendChild(document.createTextNode(_labelFor(el)));
      if (el.disabled) row.setAttribute('aria-disabled', 'true');
      else row.addEventListener('click', () => _activateOverflowItem(entry, el, row.getBoundingClientRect()));
      menu.appendChild(row);
    });
    entry.menu = menu;
    if (typeof window.positionPopup === 'function') {
      window.positionPopup(menu, entry.moreBtn.getBoundingClientRect());
    } else {
      document.body.appendChild(menu);
      window.clampPopupToViewport?.(menu);
    }
    entry.moreBtn.setAttribute('aria-expanded', 'true');
    entry.menuDismiss = event => {
      if (!menu.contains(event.target) && event.target !== entry.moreBtn) _closeMenu(entry);
    };
    entry.menuKeydown = event => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      _closeMenu(entry);
      entry.moreBtn.focus?.();
    };
    setTimeout(() => {
      document.addEventListener('pointerdown', entry.menuDismiss);
      document.addEventListener('keydown', entry.menuKeydown);
    }, 0);
  }

  function _classify(children) {
    const seps = []; const mandatory = []; const collapsible = [];
    children.forEach(el => {
      if (_isSep(el)) { seps.push(el); return; }
      // ボタン以外（スケジューラーが差し込む表示案セレクタ等）は畳まない。
      // アクションではなく現在の文脈を示す要素のため、あふれメニューの選択肢にしない。
      if (el.tagName !== 'BUTTON') { mandatory.push(el); return; }
      collapsible.push(el);
    });
    return { seps, mandatory, collapsible };
  }

  function _availableWidth(toolbar) {
    const z = _zoom();
    const style = window.getComputedStyle(toolbar);
    const paddingLeft = (parseFloat(style.paddingLeft) || 0) * z;
    const paddingRight = (parseFloat(style.paddingRight) || 0) * z;
    return Math.max(0, toolbar.getBoundingClientRect().width - paddingLeft - paddingRight);
  }

  function _recompute(entry) {
    const { toolbar, group, moreBtn } = entry;
    if (!toolbar.isConnected || !group.isConnected) return;
    _closeMenu(entry); // 判定をやり直すので、開いていたメニューは作り直す
    const children = Array.from(group.children).filter(el => el !== moreBtn);
    // 前回の折り畳み状態をいったんリセットし、自然な幅を測れる状態に戻す。
    children.forEach(el => el.style.removeProperty('display'));
    moreBtn.hidden = false;

    const available = _availableWidth(toolbar);
    const groupStyle = window.getComputedStyle(group);
    const gap = (parseFloat(groupStyle.columnGap || groupStyle.gap) || 0) * _zoom();
    const moreBtnWidth = moreBtn.getBoundingClientRect().width;

    const { seps, mandatory, collapsible } = _classify(children);
    const widthOf = new Map();
    children.forEach(el => widthOf.set(el, el.getBoundingClientRect().width));

    if (_sumWidth([...seps, ...mandatory, ...collapsible], widthOf, gap) <= available + 1) {
      moreBtn.hidden = true;
      entry.overflowItems = [];
      return;
    }

    // まず区切り線を畳む（操作ではないため、あふれメニューの項目にはしない）。
    seps.forEach(el => el.style.setProperty('display', 'none', 'important'));
    if (_sumWidth([...mandatory, ...collapsible], widthOf, gap) <= available + 1) {
      moreBtn.hidden = true;
      entry.overflowItems = [];
      return;
    }

    // 「その他」ボタン分を確保したうえで、優先順位の高い操作から入るだけ表示する。
    const budget = available - moreBtnWidth - gap;
    let used = _sumWidth(mandatory, widthOf, gap);
    let visibleCount = mandatory.length;
    const ordered = collapsible.slice().sort((a, b) => _rankFor(a) - _rankFor(b));
    const shown = new Set();
    for (const el of ordered) {
      const addGap = visibleCount > 0 ? gap : 0;
      const w = widthOf.get(el);
      if (used + addGap + w > budget) break; // 優先順位順の先着で確定させる
      used += addGap + w;
      visibleCount += 1;
      shown.add(el);
    }
    collapsible.forEach(el => {
      if (shown.has(el)) el.style.removeProperty('display');
      else el.style.setProperty('display', 'none', 'important');
    });
    entry.overflowItems = collapsible.filter(el => !shown.has(el));
    moreBtn.hidden = entry.overflowItems.length === 0;
  }

  // ResizeObserver/MutationObserverのコールバックはレイアウト確定後（ペイント直前）に
  // 走るため、requestAnimationFrame越しに遅延させる必要はない。実測でも、ペインが
  // 表示されずコンポジット（画面合成）が起きていない環境ではrAF自体が発火しないことが
  // あり、その場合はいつまで待っても畳み込みが反映されなかった。ResizeObserverの
  // コールバック内で直接再計算する。
  function _requestRecompute(entry) {
    _recompute(entry);
  }

  function setup(rootEl) {
    if (!rootEl) return null;
    const toolbar = rootEl.querySelector('.gb-toolbar-cal');
    const group = toolbar?.querySelector('.gb-cal-toolbar-actions');
    if (!toolbar || !group) return null;
    if (registry.has(toolbar)) return registry.get(toolbar);

    const moreBtn = _createMoreButton();
    group.appendChild(moreBtn);

    const entry = {
      toolbar, group, moreBtn, overflowItems: [],
      menu: null, menuDismiss: null, menuKeydown: null,
    };
    registry.set(toolbar, entry);
    moreBtn.addEventListener('click', () => _openMenu(entry));

    const resizeObserver = new ResizeObserver(() => _requestRecompute(entry));
    resizeObserver.observe(toolbar);
    entry.resizeObserver = resizeObserver;

    // サーフェス切替（カレンダー/タスクリスト）は data-cal-surface 属性で表示ボタン群が
    // 入れ替わるが、ツールバー自身の幅が変わるとは限らずResizeObserverが発火しない
    // ことがあるため、属性変化と操作グループへの子要素追加（スケジューラーが差し込む
    // 表示案セレクタ等）も監視して再判定する。
    const mutationObserver = new MutationObserver(() => _requestRecompute(entry));
    mutationObserver.observe(rootEl, { attributes: true, attributeFilter: ['data-cal-surface'] });
    mutationObserver.observe(group, { childList: true });
    entry.mutationObserver = mutationObserver;

    _requestRecompute(entry);
    return entry;
  }

  function refresh(rootEl) {
    const toolbar = (rootEl?.querySelector?.('.gb-toolbar-cal')) || rootEl;
    const entry = toolbar && registry.get(toolbar);
    if (entry) _requestRecompute(entry);
  }

  function teardown(rootEl) {
    const toolbar = rootEl?.querySelector?.('.gb-toolbar-cal');
    const entry = toolbar && registry.get(toolbar);
    if (!entry) return;
    _closeMenu(entry);
    entry.resizeObserver?.disconnect();
    entry.mutationObserver?.disconnect();
    registry.delete(toolbar);
  }

  window.MeldexCalToolbarOverflow = { setup, refresh, teardown };
})();

;

/* === gb-tool-calendar-views.js === */
;
/* ==============================
   gb-tool-calendar-views.js: CalendarComponent描画・CRUD・モーダル
   gb-tool-calendar.js のプロトタイプ拡張
   ============================== */

function _gbCalModalSizeStyle(minWidth, extra, options) {
  const width = Math.max(240, Number(minWidth) || 400);
  const zoom = Math.max(0.1, (typeof _getZoom === 'function' ? _getZoom() : parseFloat(document.documentElement?.style?.zoom || '')) || 1);
  const viewportWidth = Math.floor(window.visualViewport?.width || window.innerWidth || document.documentElement?.clientWidth || width + 16);
  const viewportHeight = Math.floor(window.visualViewport?.height || window.innerHeight || document.documentElement?.clientHeight || 720);
  const safeWidth = Math.max(240, Math.min(width, viewportWidth - 16));
  const safeHeight = Math.max(180, Math.floor((viewportHeight - 56) / zoom));
  const overflow = extra == null ? 'overflow-y:auto;' : String(extra);
  const height = options?.forceHeight ? `height:${safeHeight}px;` : '';
  return `min-width:0;min-height:0;width:${safeWidth}px;max-width:${safeWidth}px;max-height:${safeHeight}px;${height}${overflow}`;
}

// === 月表示 ===
CalendarComponent.prototype._renderMonth = function() {
  const el = this._contentEl;
  const y = this._date.getFullYear(), m = this._date.getMonth();
  const rawFirst = new Date(y, m, 1).getDay();
  const firstDay = (rawFirst - this._startDay + 7) % 7;
  const daysInMonth = new Date(y, m + 1, 0).getDate();
  const todayStr = this._localDateStr();
  let html = '<div class="gb-cal-month">';
  const dayNames = this._getDayNames();
  dayNames.forEach((d, i) => {
    const dow = (this._startDay + i) % 7;
    html += `<div class="gb-cal-month-header" data-cal-dow="${dow}">${d}</div>`;
  });
  const prevDays = new Date(y, m, 0).getDate();
  const prevM = m === 0 ? 12 : m, prevY = m === 0 ? y - 1 : y;
  for (let i = firstDay - 1; i >= 0; i--) { const day = prevDays - i; const ds = `${prevY}-${String(prevM).padStart(2,'0')}-${String(day).padStart(2,'0')}`; html += this._monthDayCell(ds, day, ds === todayStr, true); }
  for (let d = 1; d <= daysInMonth; d++) { const ds = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`; html += this._monthDayCell(ds, d, ds === todayStr, false); }
  const total = firstDay + daysInMonth, rem = Math.max(0, 42 - total);
  const nextM = m + 2 > 12 ? 1 : m + 2, nextY = m + 2 > 12 ? y + 1 : y;
  for (let i = 1; i <= rem; i++) { const ds = `${nextY}-${String(nextM).padStart(2,'0')}-${String(i).padStart(2,'0')}`; html += this._monthDayCell(ds, i, ds === todayStr, true); }
  html += '</div>';
  el.innerHTML = html;
  // イベント委譲（前回リスナーを除去してから追加）
  if (el._calClickHandler) el.removeEventListener('click', el._calClickHandler);
  el._calClickHandler = (e) => {
    const evEl = e.target.closest('.gb-cal-day-event');
    const moreBtn = e.target.closest('[data-cal-event-more]');
    if (moreBtn && evEl) {
      e.preventDefault();
      e.stopPropagation();
      const eid = evEl.dataset.eventId;
      if (eid && typeof this._showEventCardMenu === 'function') this._showEventCardMenu(moreBtn, eid);
      return;
    }
    if (evEl) { e.stopPropagation(); const eid = evEl.dataset.eventId; const tid = evEl.dataset.taskId; if (eid) this._openEventInPanel(eid); else if (tid) this._showTaskModal(tid); return; }
    const dayEl = e.target.closest('.gb-cal-day');
    if (dayEl) this._onDayClick(dayEl.dataset.date, dayEl);
  };
  el.addEventListener('click', el._calClickHandler);
  // 月表示イベントのdragstart（日付間D&D移動用）
  el.querySelectorAll('.gb-cal-day-event[data-event-id]').forEach(evEl => {
    evEl.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('application/x-cal-event', evEl.dataset.eventId);
      e.dataTransfer.effectAllowed = 'move';
      evEl.style.opacity = '0.4';
    });
    evEl.addEventListener('dragend', () => { evEl.style.opacity = ''; });
  });
  // 月表示D&D（日セルへのドロップ）
  el.querySelectorAll('.gb-cal-day').forEach(dayEl => {
    dayEl.addEventListener('dragover', (e) => { e.preventDefault(); dayEl.style.outline = '2px solid var(--cal-accent, var(--accent))'; });
    dayEl.addEventListener('dragleave', () => { dayEl.style.outline = ''; });
    dayEl.addEventListener('drop', (e) => { e.preventDefault(); dayEl.style.outline = ''; this._onMonthDayDrop(e, dayEl.dataset.date); });
  });
};

CalendarComponent.prototype._eventIntersectsDay = function(ev, dateStr) {
  const range = _calEventRange(ev);
  if (!range) return false;
  const dayStart = new Date(dateStr + 'T00:00');
  const dayEnd = new Date(dayStart);
  dayEnd.setDate(dayEnd.getDate() + 1);
  return range.start < dayEnd && range.end > dayStart;
};

CalendarComponent.prototype._eventSegmentForDay = function(ev, dateStr) {
  const range = _calEventRange(ev);
  if (!range) return null;
  const dayStart = new Date(dateStr + 'T00:00');
  const dayEnd = new Date(dayStart);
  dayEnd.setDate(dayEnd.getDate() + 1);
  if (!(range.start < dayEnd && range.end > dayStart)) return null;
  const segStart = range.start > dayStart ? range.start : dayStart;
  const segEnd = range.end < dayEnd ? range.end : dayEnd;
  const startH = segStart.getHours() + segStart.getMinutes() / 60;
  let endH = segEnd.getHours() + segEnd.getMinutes() / 60;
  if (segEnd >= dayEnd) endH = 24;
  if (endH <= startH) endH = Math.min(24, startH + 0.25);
  return { dayStart, segStart, segEnd, startH, endH };
};

function _calIsDateOnlyValue(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(value || '').trim());
}

function _calParseDateValue(value) {
  const raw = String(value || '').trim();
  if (!raw) return null;
  if (_calIsDateOnlyValue(raw)) {
    const parts = raw.split('-').map(Number);
    return new Date(parts[0], parts[1] - 1, parts[2]);
  }
  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function _calDateAddDays(date, days) {
  const next = new Date(date);
  next.setDate(next.getDate() + days);
  return next;
}

function _calDateOnlyString(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function _calEventRange(ev) {
  if (!ev?.start) return null;
  const start = _calParseDateValue(ev.start);
  if (!start) return null;
  const startIsDate = _calIsDateOnlyValue(ev.start);
  const endIsDate = _calIsDateOnlyValue(ev.end);
  let end = ev.end ? _calParseDateValue(ev.end) : null;
  if (ev.all_day || startIsDate || endIsDate) {
    if (!end || end <= start) end = _calDateAddDays(start, 1);
    // 日付のみの終了日は「最終日を含む」扱い（保存慣例は包括的な終了日のため、表示境界は翌日0時）
    else if (endIsDate) end = _calDateAddDays(end, 1);
  } else if (!end) {
    end = new Date(start.getTime() + 3600000);
  }
  if (!end || Number.isNaN(end.getTime())) end = new Date(start.getTime() + 3600000);
  if (end <= start) end = new Date(start.getTime() + 15 * 60000);
  return { start, end };
}

function _calAllDayDateSpan(ev) {
  const range = _calEventRange(ev);
  if (!range) return 1;
  return Math.max(1, Math.round((range.end - range.start) / 86400000));
}

function _calRecurringInteractionBlocked(component, ev) {
  if (!ev?._recurrence_instance) return false;
  component._showStatus?.('繰り返し予定は元の予定から編集してください', true);
  return true;
}

// === 複数選択イベントのグループD&D移動: 日付演算ヘルパー ===
// サーバーが自動生成する予定のうち、書き戻し経路を持たないもの（シフト/休憩/勤怠）は
// グループ移動の「他の選択イベント」から除外する（ドラッグしたイベント自身はこの判定をしない）。
// production-task は _calApplyEventTimePatch 経由のタスク書き戻しに対応済みのため対象外にしない
// （制作管理UX改善計画 2026-08-04 §6-4 の残作業: 複数選択グループ移動）。
function _calGroupMoveSourceBlocked(ev) {
  return ['shift', 'shift-break', 'attendance'].includes(String(ev?.calendar_source || ''));
}

// 制作管理UX改善計画（2026-08-04）§6-4: production-task イベントの移動・リサイズは、汎用イベント
// 更新（/cal/events/{id}。自動生成された予定として409で拒否される）ではなく、タスクへの書き戻し
// （/production-management/task-schedule/update）として処理する。書き戻し時にサーバー側が
// 「シフト固定」を自動付与するため、失敗ロールバック機構（各呼び出し元の.catch）はそのまま使える
// （このヘルパーは apiPut と同様に成功時は結果を返し、失敗時は reject する）。
// シフト・勤怠など他の自動生成イベントは従来どおり409のままとする（このヘルパーを経由させない）。
function _calIsProductionTaskEvent(ev) {
  return String(ev?.calendar_source || '') === 'production-task';
}

function _calIsRenderListEvent(ev) {
  return String(ev?.calendar_source || '') === 'renderlist';
}

function _calIsManagedScheduleEvent(ev) {
  return _calIsProductionTaskEvent(ev) || _calIsRenderListEvent(ev);
}

async function _calApplyEventTimePatch(component, ev, patch) {
  if (!_calIsManagedScheduleEvent(ev)) return apiPut('/cal/events/' + ev.id, patch);
  const start = patch?.start || ev?.start || '';
  const end = patch?.end || ev?.end || '';
  if (_calIsRenderListEvent(ev)) {
    let metadata = {};
    try { metadata = JSON.parse(String(ev?.description || '{}')) || {}; } catch {}
    const external = String(ev?.external_id || '');
    const separator = external.indexOf(':');
    const taskId = separator >= 0 ? external.slice(separator + 1) : '';
    const parsedStart = new Date(start);
    if (!taskId || Number.isNaN(parsedStart.getTime())) throw new Error('RenderList予定の識別情報が不正です');
    const result = await apiPost('/renderlist-connector/schedule', {
      taskId,
      operation: 'set_planned_start',
      expectedScheduleRevision: Number(metadata.scheduleRevision || 0),
      plannedStartAt: parsedStart.toISOString(),
    });
    if (result?.ok === false) throw new Error(result?.message || 'RenderList予定を更新できませんでした');
    component?._showStatus?.('RenderListへ予定開始の変更を送信しました。予定時間は固定のままです');
    return result;
  }
  const result = await apiPost('/production-management/task-schedule/update', {
    event_id: String(ev?.id || ''), start, end,
  });
  if (result?.ok === false) throw new Error(result?.message || '予定を更新できませんでした');
  component?._showStatus?.('予定を固定しました。再計算でも動かなくなります');
  return result;
}

// fromValue（旧開始日時）から toDateStr（新しい日付）までの日数差を返す（時刻は無視）
function _calDateDayDelta(fromValue, toDateStr) {
  const fromDate = _calParseDateValue(fromValue);
  const toDate = _calParseDateValue(toDateStr);
  if (!fromDate || !toDate) return 0;
  const fromMid = new Date(fromDate.getFullYear(), fromDate.getMonth(), fromDate.getDate());
  const toMid = new Date(toDate.getFullYear(), toDate.getMonth(), toDate.getDate());
  return Math.round((toMid - fromMid) / 86400000);
}

// 日付/日時値を days 日シフトする（元の表記形式=日付のみ/日時を維持する）
function _calShiftValueByDays(component, value, days) {
  if (!value || !days) return value;
  const parsed = _calParseDateValue(value);
  if (!parsed) return value;
  const shifted = _calDateAddDays(parsed, days);
  return _calIsDateOnlyValue(value) ? _calDateOnlyString(shifted) : component._localDateTimeStr(shifted);
}

// 日時値を deltaMs ミリ秒シフトする（日付のみ値は呼び出し側で _calShiftValueByDays を使うこと）
function _calShiftValueByMs(component, value, deltaMs) {
  if (!value || !deltaMs) return value;
  const parsed = _calParseDateValue(value);
  if (!parsed) return value;
  return component._localDateTimeStr(new Date(parsed.getTime() + deltaMs));
}

// 月表示・終日帯ドロップ用: グループ内の他イベントを dayDelta 日シフトするパッチを作る
// （0日シフトや対象値なしは null を返し、呼び出し側でAPI呼び出しを省略させる＝変更なし扱い）
function _calDayShiftPatch(component, ev, dayDelta) {
  if (!dayDelta) return null;
  const patch = {};
  if (ev.start) patch.start = _calShiftValueByDays(component, ev.start, dayDelta);
  if (ev.end) patch.end = _calShiftValueByDays(component, ev.end, dayDelta);
  return Object.keys(patch).length ? patch : null;
}

// 週/日/複数日セルドロップ用: 他イベントを移動先へ合わせてシフトするパッチを作る
// （終日イベントは日単位、時刻付きイベントはミリ秒単位でシフトする。共に無変化は null＝対象外）
function _calWeekShiftPatch(component, ev, deltaMs) {
  if (ev.all_day) {
    const days = Math.round(deltaMs / 86400000);
    if (!days) return null;
    const patch = {};
    if (ev.start) patch.start = _calShiftValueByDays(component, ev.start, days);
    if (ev.end) patch.end = _calShiftValueByDays(component, ev.end, days);
    return Object.keys(patch).length ? patch : null;
  }
  if (!deltaMs) return null;
  const patch = {};
  if (ev.start) patch.start = _calShiftValueByMs(component, ev.start, deltaMs);
  if (ev.end) patch.end = _calShiftValueByMs(component, ev.end, deltaMs);
  return Object.keys(patch).length ? patch : null;
}

CalendarComponent.prototype._sanitizeEventColor = function(color) {
  const raw = String(color || '').trim();
  if (!raw) return 'var(--cal-event-bg, var(--cal-accent, var(--accent)))';
  if (/^#[0-9a-f]{3,8}$/i.test(raw)) return raw;
  if (/^rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}(?:\s*,\s*(?:0|1|0?\.\d+))?\s*\)$/i.test(raw)) return raw;
  if (/^var\(--[-_a-zA-Z0-9]+(?:\s*,\s*(?:#[0-9a-f]{3,8}|var\(--[-_a-zA-Z0-9]+\)))?\)$/i.test(raw)) return raw;
  return 'var(--cal-event-bg, var(--cal-accent, var(--accent)))';
};

CalendarComponent.prototype._eventSourceClass = function(ev) {
  const source = String(ev?.calendar_source || '');
  let cls = '';
  if (source === 'production-task') cls = ' gb-cal-production-task-event';
  else if (source === 'shift') cls = ' gb-cal-shift-event';
  else if (source === 'shift-break') cls = ' gb-cal-shift-break-event';
  else if (source === 'attendance') cls = ' gb-cal-attendance-event';
  // 保存未確定（タイムアウト後の再試行待ち）のイベントは破線枠+バッジで区別する
  if (ev?._saveState === 'unsaved') cls += ' gb-cal-event-unsaved';
  return cls;
};

CalendarComponent.prototype._eventTitleContentHtml = function(ev) {
  const source = String(ev?.calendar_source || '');
  const iconName = source === 'production-task' ? 'hammer' : source === 'shift' ? 'calendarClock' : source === 'shift-break' ? 'coffee' : source === 'attendance' ? 'clock' : '';
  const icon = iconName ? `<span class="gb-cal-event-source-icon">${lucide(iconName, 10)}</span>` : '';
  return `${icon}<span class="gb-cal-event-title">${esc(ev?.title || '')}</span>`;
};

function _calMonthGroupKey(ev, dateStr) {
  const source = String(ev?.calendar_source || '');
  const baseId = String(ev?.external_id || ev?.id || '').replace(/^shift:/, '').split(':break:')[0];
  if (source === 'shift' || source === 'shift-break') return `shift:${baseId || ev?.id || ''}:${dateStr}`;
  if (source === 'attendance') return `attendance:${ev?.user || ev?.external_id || ev?.id || ''}:${dateStr}`;
  return '';
}

function _calEventStableSlug(value) {
  const raw = String(value || '').trim().toLowerCase();
  const ascii = raw.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 48);
  let hash = 0;
  for (let i = 0; i < raw.length; i++) {
    hash = ((hash << 5) - hash + raw.charCodeAt(i)) | 0;
  }
  return `${ascii || 'event'}-${Math.abs(hash).toString(36)}`;
}

CalendarComponent.prototype._monthDisplayEvents = function(dateStr, events) {
  const rows = Array.isArray(events) ? events : [];
  const shiftWorkKeys = new Set(rows
    .filter(ev => String(ev?.calendar_source || '') === 'shift')
    .map(ev => _calMonthGroupKey(ev, dateStr)));
  const seenAttendance = new Set();
  return rows.filter(ev => {
    const source = String(ev?.calendar_source || '');
    if (source === 'shift-break' && shiftWorkKeys.has(_calMonthGroupKey(ev, dateStr))) return false;
    if (source === 'attendance') {
      const key = _calMonthGroupKey(ev, dateStr);
      if (seenAttendance.has(key)) return false;
      seenAttendance.add(key);
    }
    return true;
  });
};

CalendarComponent.prototype._eventCardMenuHtml = function(ev, context) {
  const base = [
    context || 'event',
    ev?.id || ev?.external_id || ev?.title || 'event',
  ].join('|');
  const e2eId = `calendar-event-more-${_calEventStableSlug(base)}`;
  return `<button type="button" class="gb-cal-event-more" data-cal-event-more data-e2e-id="${esc(e2eId)}" draggable="false" title="イベントメニュー" aria-label="イベントメニュー">${lucide('moreHorizontal', 10)}</button>`;
};

CalendarComponent.prototype._monthDayCell = function(dateStr, dayNum, isToday, isOther) {
  const dayEvents = this._events.filter(e => this._eventIntersectsDay(e, dateStr) && this._isCalVisible(e));
  const monthEvents = this._monthDisplayEvents(dateStr, dayEvents);
  const dayTasks = this._tasks.filter(t => t.due_date === dateStr);
  const dow = this._parseLocalDate(dateStr).getDay();
  let html = `<div class="gb-cal-day${isToday?' gb-cal-today':''}${isOther?' gb-cal-other-month':''}" data-date="${dateStr}" data-cal-dow="${dow}">`;
  html += `<div class="gb-cal-day-num">${dayNum}</div>`;
  monthEvents.forEach(e => {
    const avatars = typeof this._eventUserAvatarsHtml === 'function' ? this._eventUserAvatarsHtml(e, 14) : '';
    const summaryClass = ['shift', 'attendance'].includes(String(e?.calendar_source || '')) ? ' gb-cal-month-summary-event' : '';
    html += `<div class="gb-cal-day-event${summaryClass}${this._eventSourceClass(e)}" data-event-id="${e.id}" data-calendar-id="${esc(e.calendar_id||'_calendar')}" draggable="true" style="background:${this._sanitizeEventColor(e.color)};color:var(--cal-event-fg, #fff);position:relative;" title="${esc(e.title)}">${this._eventTitleContentHtml(e)}${this._eventCardMenuHtml(e, 'month-' + dateStr)}${avatars}</div>`;
  });
  dayTasks.forEach(t => {
    const pc = {urgent:'var(--red)',high:'var(--orange)',medium:'var(--blue)',low:'var(--cal-control-bg, var(--bg3))'}[t.priority] || 'var(--cal-control-bg, var(--bg3))';
    html += `<div class="gb-cal-day-event gb-cal-all-day-task" data-task-id="${t.id}" style="background:${pc};color:var(--cal-event-fg, #fff);" title="${esc(t.title)}">${lucide('checkSquare', 10)} ${esc(t.title)}</div>`;
  });
  return html + '</div>';
};

CalendarComponent.prototype._onDayClick = function(dateStr, anchorEl) {
  if (this._view === 'month') {
    if (typeof this._handleShiftCalendarDayClick === 'function' && this._handleShiftCalendarDayClick(dateStr, anchorEl)) return;
    this._openEventInPanel(null, dateStr + 'T00:00', dateStr + 'T23:59', true);
  } else {
    this._date = this._parseLocalDate(dateStr); this.setView('day');
  }
};

CalendarComponent.prototype._snapshotEventLocal = function(eventId) {
  const ev = (this._events || []).find(x => x.id === eventId);
  return ev ? JSON.parse(JSON.stringify(ev)) : null;
};

CalendarComponent.prototype._applyEventLocal = function(eventId, patch) {
  const ev = (this._events || []).find(x => x.id === eventId);
  if (!ev) return null;
  Object.assign(ev, patch || {});
  return ev;
};

CalendarComponent.prototype._restoreEventLocal = function(snapshot) {
  if (!snapshot?.id) return;
  const idx = (this._events || []).findIndex(x => x.id === snapshot.id);
  if (idx >= 0) this._events[idx] = snapshot;
};

// 選択中の複数イベントをまとめて移動する（グループD&D）。
// ドラッグしたイベントが2件以上の選択に含まれる場合のみ処理し、それ以外は false を返す
// （呼び出し側はこれまでどおり単一移動を行う）。ドラッグイベントは呼び出し側が計算した
// 従来パッチ（draggedApplyPatch=ローカル反映用、draggedApiPatch=サーバー送信用）をそのまま使い、
// 他の選択イベントは otherPatchFn(ev) が返すパッチ（null なら変更なし/対象外）を使う。
CalendarComponent.prototype._moveSelectedEventGroup = async function(draggedEv, draggedApplyPatch, draggedApiPatch, otherPatchFn) {
  const draggedId = draggedEv?.id;
  const selection = this._eventSelection ? this._eventSelection() : null;
  if (!draggedId || !selection || selection.size < 2 || !selection.has(draggedId)) return false;

  const targets = [{ id: draggedId, ev: draggedEv, applyPatch: draggedApplyPatch, apiPatch: draggedApiPatch }];
  let skipped = 0;
  (this._selectedEventRecords ? this._selectedEventRecords() : []).forEach(other => {
    if (!other || other.id === draggedId) return;
    if (other._recurrence_instance || _calGroupMoveSourceBlocked(other)) { skipped += 1; return; }
    const patch = otherPatchFn(other);
    if (patch && Object.keys(patch).length) targets.push({ id: other.id, ev: other, applyPatch: patch, apiPatch: patch });
  });

  const before = targets.map(t => this._snapshotEventLocal(t.id));
  // production-task予定はタスク側が正本で undo 対象外（_eventIsUndoable。コミット前レビュー
  // 指摘 #5 と同じ扱い）。グループ内に undo 可能なイベントが1件も無ければ偽の undo 記録を積まない。
  if (targets.some(t => this._eventIsUndoable(t.ev))) this._pushUndo('イベント移動');
  targets.forEach(t => this._applyEventLocal(t.id, t.applyPatch));
  this._render();

  // production-task予定は汎用更新（自動生成予定として409で拒否される）ではなく、タスクへの
  // 書き戻し（_calApplyEventTimePatch。分割区間なら event_id の part:N からサーバー側が対象
  // 区間を判定し、担当者固定409/区間陳腐化409をそれぞれハンドリングする）を経由させる。
  const results = await Promise.allSettled(targets.map(t => _calApplyEventTimePatch(this, t.ev, t.apiPatch)));
  let failed = 0;
  results.forEach((result, i) => {
    if (result.status !== 'rejected') return;
    failed += 1;
    this._restoreEventLocal(before[i]);
  });

  const notices = [];
  if (failed) notices.push(`${failed}件の移動に失敗`);
  if (skipped) notices.push(`${skipped}件は移動できないためスキップしました`);
  if (notices.length) this._showStatus(notices.join(' / '), true);

  await this._loadEvents();
  this._render();
  return true;
};

CalendarComponent.prototype._onMonthDayDrop = async function(e, dateStr) {
  const eventId = e.dataTransfer.getData('application/x-cal-event');
  if (!eventId) return;
  const ev = this._events.find(x => x.id === eventId);
  if (!ev) return;
  if (_calRecurringInteractionBlocked(this, ev)) return;
  const oldStart = ev.start || '', timePart = oldStart.includes('T') ? oldStart.substring(10) : 'T00:00';
  const newStart = dateStr + timePart;
  let newEnd = '';
  if (ev.end) {
    const dur = new Date(ev.end) - new Date(oldStart);
    newEnd = this._localDateTimeStr(new Date(new Date(newStart).getTime() + dur));
  }
  if (newStart === oldStart && (!ev.end || newEnd === ev.end)) return;
  const dayDelta = _calDateDayDelta(oldStart, dateStr);
  const grouped = await this._moveSelectedEventGroup(
    ev,
    { start: newStart, end: newEnd || ev.end || '' },
    { start: newStart, end: newEnd || undefined },
    other => _calDayShiftPatch(this, other, dayDelta)
  );
  if (grouped) return;
  const before = this._snapshotEventLocal(eventId);
  try {
    // production-task予定はタスク側が正本で undo 対象外（コミット前レビュー指摘 #5 と同じ扱い）。
    if (this._eventIsUndoable(ev)) this._pushUndo('イベント移動');
    this._applyEventLocal(eventId, { start: newStart, end: newEnd || ev.end || '' });
    this._render();
    // production-task予定は汎用更新（自動生成予定として409拒否）ではなく、タスクへの書き戻しを経由する
    // （制作管理UX改善計画 2026-08-04 §6-4 の残作業: 月表示セルへのドロップ）。
    await _calApplyEventTimePatch(this, ev, { start: newStart, end: newEnd || undefined });
    await this._loadEvents(); this._render();
  } catch (error) {
    this._restoreEventLocal(before);
    this._render();
    this._showStatus(error?.message ? ('イベント移動に失敗: ' + error.message) : 'イベント移動に失敗', true);
  }
};

// === 週表示 ===
CalendarComponent.prototype._timedEventSegmentsForDay = function(dateStr) {
  const segments = [];
  (this._events || []).forEach(ev => {
    if (!ev.start || ev.all_day || !this._isCalVisible(ev)) return;
    const seg = this._eventSegmentForDay(ev, dateStr);
    if (!seg) return;
    segments.push({
      ev,
      dateStr,
      segStart: seg.segStart,
      startH: seg.startH,
      endH: Math.max(seg.startH + 0.25, seg.endH),
    });
  });
  return segments.sort((a, b) => (a.startH - b.startH) || (b.endH - a.endH));
};

CalendarComponent.prototype._allDayEventsForDay = function(dateStr) {
  return (this._events || [])
    .filter(ev => ev?.all_day && this._isCalVisible(ev) && this._eventIntersectsDay(ev, dateStr))
    .sort((a, b) => String(a.start || '').localeCompare(String(b.start || '')) || String(a.title || '').localeCompare(String(b.title || '')));
};

CalendarComponent.prototype._allDayStripHtml = function(dateStrs) {
  const cols = Array.isArray(dateStrs) && dateStrs.length ? dateStrs : [];
  if (!cols.length) return '';
  let html = `<div class="gb-cal-all-day-strip" style="display:grid;grid-template-columns:60px repeat(${cols.length}, minmax(0,1fr));border-bottom:1px solid var(--cal-grid-line, var(--border));">`;
  html += '<div class="gb-cal-week-time" style="padding-top:6px;">終日</div>';
  cols.forEach(dateStr => {
    html += `<div class="gb-cal-all-day-cell" data-date="${dateStr}" style="min-height:30px;padding:2px;border-left:1px solid var(--cal-grid-line, var(--border));">`;
    this._allDayEventsForDay(dateStr).forEach(ev => {
      const avatars = typeof this._eventUserAvatarsHtml === 'function' ? this._eventUserAvatarsHtml(ev, 14) : '';
      html += `<div class="gb-cal-day-event gb-cal-all-day-event${this._eventSourceClass(ev)}" data-event-id="${esc(ev.id)}" data-calendar-id="${esc(ev.calendar_id||'_calendar')}" draggable="true" style="background:${this._sanitizeEventColor(ev.color)};color:var(--cal-event-fg, #fff);position:relative;margin:1px 0;" title="${esc(ev.title || '')}">${this._eventTitleContentHtml(ev)}${this._eventCardMenuHtml(ev, 'all-day-' + dateStr)}${avatars}</div>`;
    });
    html += '</div>';
  });
  return html + '</div>';
};

CalendarComponent.prototype._bindAllDayStripEvents = function(rootEl) {
  rootEl.querySelectorAll('.gb-cal-all-day-event[data-event-id]').forEach(evEl => {
    evEl.addEventListener('click', (e) => {
      const moreBtn = e.target.closest('[data-cal-event-more]');
      if (moreBtn) {
        e.preventDefault();
        e.stopPropagation();
        if (typeof this._showEventCardMenu === 'function') this._showEventCardMenu(moreBtn, evEl.dataset.eventId);
        return;
      }
      e.stopPropagation(); this._openEventInPanel(evEl.dataset.eventId);
    });
    evEl.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('application/x-cal-move', JSON.stringify({ id: evEl.dataset.eventId, startH: 0, allDay: true }));
      e.dataTransfer.effectAllowed = 'move';
      evEl.style.opacity = '0.4';
    });
    evEl.addEventListener('dragend', () => { evEl.style.opacity = ''; });
  });
  rootEl.querySelectorAll('.gb-cal-all-day-cell').forEach(cell => {
    cell.addEventListener('dragover', (e) => { e.preventDefault(); cell.style.background = 'rgba(86,156,214,0.12)'; });
    cell.addEventListener('dragleave', () => { cell.style.background = ''; });
    cell.addEventListener('drop', async (e) => {
      e.preventDefault(); cell.style.background = '';
      const d = e.dataTransfer.getData('application/x-cal-move');
      if (!d) return;
      const { id } = JSON.parse(d);
      const ev = this._events.find(x => x.id === id);
      if (!ev) return;
      if (_calRecurringInteractionBlocked(this, ev)) return;
      const dateStr = cell.dataset.date;
      const dayDelta = _calDateDayDelta(ev.start, dateStr);
      if (_calIsManagedScheduleEvent(ev)) {
        // タスク予定には終日という概念が無い（作業予定時間は時刻付きの区間で正本管理する）ため、
        // 終日帯へのドロップは全日化せず、月表示ドロップと同じ「時刻を保ったまま日付だけ移動」
        // として扱い、タスクへの書き戻し経路（_calApplyEventTimePatch）を経由する
        // （制作管理UX改善計画 2026-08-04 §6-4 の残作業: 終日帯へのドロップ）。
        const patch = _calDayShiftPatch(this, ev, dayDelta);
        if (!patch) return;
        const grouped = await this._moveSelectedEventGroup(ev, patch, patch, other => _calDayShiftPatch(this, other, dayDelta));
        if (grouped) return;
        const before = this._snapshotEventLocal(id);
        this._applyEventLocal(id, patch);
        this._render();
        try {
          await _calApplyEventTimePatch(this, ev, patch);
          await this._loadEvents(); this._render();
        } catch (error) {
          this._restoreEventLocal(before);
          this._render();
          this._showStatus(error?.message ? ('イベント移動に失敗: ' + error.message) : 'イベント移動に失敗', true);
        }
        return;
      }
      const spanDays = _calAllDayDateSpan(ev);
      const startDate = _calParseDateValue(dateStr);
      const endDate = spanDays <= 1 ? dateStr : _calDateOnlyString(_calDateAddDays(startDate, spanDays));
      const patch = { start: dateStr, end: endDate, all_day: 1 };
      const grouped = await this._moveSelectedEventGroup(ev, patch, patch, other => _calDayShiftPatch(this, other, dayDelta));
      if (grouped) return;
      const before = this._snapshotEventLocal(id);
      this._pushUndo('イベント移動');
      this._applyEventLocal(id, patch);
      this._render();
      apiPut('/cal/events/' + id, patch)
        .then(() => this._loadEvents())
        .then(() => this._render())
        .catch(() => {
          this._restoreEventLocal(before);
          this._render();
          this._showStatus('イベント移動に失敗', true);
        });
    });
  });
};

CalendarComponent.prototype._layoutTimedEventSegments = function(segments) {
  const out = [];
  let group = [];
  let groupEnd = -1;
  const flush = () => {
    if (!group.length) return;
    const laneEnds = [];
    group.forEach(item => {
      let lane = laneEnds.findIndex(end => end <= item.startH);
      if (lane < 0) lane = laneEnds.length;
      laneEnds[lane] = item.endH;
      item._overlapLane = lane;
    });
    const laneCount = Math.max(1, laneEnds.length);
    group.forEach(item => {
      const visibleLane = Math.min(item._overlapLane, 5);
      const visibleCount = Math.min(laneCount, 6);
      out.push({
        ...item,
        overlapLane: visibleLane,
        overlapCount: visibleCount,
      });
    });
    group = [];
    groupEnd = -1;
  };
  (segments || []).forEach(item => {
    if (!group.length || item.startH < groupEnd) {
      group.push(item);
      groupEnd = Math.max(groupEnd, item.endH);
    } else {
      flush();
      group.push(item);
      groupEnd = item.endH;
    }
  });
  flush();
  return out;
};

CalendarComponent.prototype._renderTimedEventSegmentsForDay = function(rootEl, dateStr) {
  const segments = this._layoutTimedEventSegments(this._timedEventSegmentsForDay(dateStr));
  segments.forEach(seg => {
    const cell = rootEl.querySelector(`.gb-cal-week-cell[data-date="${dateStr}"][data-hour="${Math.floor(seg.startH)}"]`);
    if (!cell) return;
    const card = this._createEventCard(seg.ev, seg.segStart, seg.startH, seg.endH, seg);
    cell.appendChild(card);
  });
};

CalendarComponent.prototype._renderWeek = function() {
  const el = this._contentEl;
  const start = new Date(this._date);
  start.setDate(start.getDate() - ((start.getDay() - this._startDay + 7) % 7));
  const today = this._localDateStr();
  const dayNames = this._getDayNames();
  const dateStrs = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(start); d.setDate(d.getDate() + i);
    dateStrs.push(this._localDateStr(d));
  }
  let html = '<div class="gb-cal-timed-view">' + this._allDayStripHtml(dateStrs) + '<div class="gb-cal-week"><div></div>';
  for (let i = 0; i < 7; i++) {
    const d = new Date(start); d.setDate(d.getDate() + i);
    const ds = this._localDateStr(d);
    const dow = d.getDay();
    html += `<div class="gb-cal-week-header" data-cal-dow="${dow}" data-date="${ds}"${ds===today?' data-today="1"':''}>${dayNames[i]} ${d.getDate()}</div>`;
  }
  for (let h = 0; h < 24; h++) {
    html += `<div class="gb-cal-week-time">${h}:00</div>`;
    for (let i = 0; i < 7; i++) {
      const d = new Date(start); d.setDate(d.getDate() + i);
      html += `<div class="gb-cal-week-cell" data-date="${this._localDateStr(d)}" data-hour="${h}"></div>`;
    }
  }
  html += '</div></div>';
  el.innerHTML = html;
  for (let i = 0; i < 7; i++) {
    const d = new Date(start); d.setDate(d.getDate() + i);
    this._renderTimedEventSegmentsForDay(el, this._localDateStr(d));
  }
  this._bindAllDayStripEvents(el);
  this._initWeekDrag(el);
  this._syncNowLineTimer();
};

// === 日表示 ===
CalendarComponent.prototype._renderDay = function() {
  const el = this._contentEl;
  const ds = this._localDateStr(this._date);
  let html = this._allDayStripHtml([ds]) + '<div class="gb-cal-week gb-cal-day-grid" style="grid-template-columns:60px minmax(0,1fr);">';
  for (let h = 0; h < 24; h++) {
    html += `<div class="gb-cal-week-time">${h}:00</div>`;
    html += `<div class="gb-cal-week-cell" data-date="${ds}" data-hour="${h}"></div>`;
  }
  html = '<div class="gb-cal-timed-view">' + html + '</div>';
  el.innerHTML = html;
  this._renderTimedEventSegmentsForDay(el, ds);
  this._bindAllDayStripEvents(el);
  this._initWeekDrag(el);
  this._syncNowLineTimer();
};

// === 複数日表示 ===
CalendarComponent.prototype._renderMultiDays = function() {
  const el = this._contentEl;
  const dateStrs = this._multiDayDateStrs();
  const today = this._localDateStr();
  const dayNames = ['日','月','火','水','木','金','土'];
  let html = '<div class="gb-cal-timed-view">' + this._allDayStripHtml(dateStrs) + `<div class="gb-cal-week gb-cal-multi-day-grid" style="grid-template-columns:60px repeat(${dateStrs.length}, minmax(96px,1fr));">`;
  html += '<div></div>';
  dateStrs.forEach(ds => {
    const d = this._parseLocalDate(ds);
    const dow = d.getDay();
    html += `<div class="gb-cal-week-header" data-cal-dow="${dow}" data-date="${ds}"${ds===today?' data-today="1"':''}>${dayNames[dow]} ${d.getMonth()+1}/${d.getDate()}</div>`;
  });
  for (let h = 0; h < 24; h++) {
    html += `<div class="gb-cal-week-time">${h}:00</div>`;
    dateStrs.forEach(ds => {
      html += `<div class="gb-cal-week-cell" data-date="${ds}" data-hour="${h}"></div>`;
    });
  }
  html += '</div></div>';
  el.innerHTML = html;
  dateStrs.forEach(ds => this._renderTimedEventSegmentsForDay(el, ds));
  this._bindAllDayStripEvents(el);
  this._initWeekDrag(el);
  this._syncNowLineTimer();
};

// === イベントカード生成 ===
CalendarComponent.prototype._createEventCard = function(ev, evStart, startH, endH, layout) {
  const card = document.createElement('div');
  card.className = 'gb-cal-week-event gb-cal-day-event' + this._eventSourceClass(ev);
  card.dataset.eventId = ev.id;
  card.dataset.calendarId = ev.calendar_id || '_calendar';
  card.style.background = this._sanitizeEventColor(ev.color);
  card.style.top = ((startH % 1) * 40) + 'px';
  card.style.height = Math.max(20, (endH - startH) * 40) + 'px';
  card.style.position = 'absolute';
  const lane = Math.max(0, layout?.overlapLane || 0);
  const count = Math.max(1, layout?.overlapCount || 1);
  const offset = lane * 12;
  const rightReserve = 18 + Math.max(0, count - lane - 1) * 12;
  card.style.left = (2 + offset) + 'px';
  card.style.right = rightReserve + 'px';
  card.style.zIndex = String(2 + lane);
  card.innerHTML = `${this._eventTitleContentHtml(ev)}${this._eventCardMenuHtml(ev, 'timed-' + (layout?.dateStr || '') + '-' + String(startH || 0))}${typeof this._eventUserAvatarsHtml === 'function' ? this._eventUserAvatarsHtml(ev, 14) : ''}`;
  card.title = ev.title + '\n' + (ev.start||'').substring(11,16) + '–' + (ev.end||'').substring(11,16);
  card.addEventListener('click', (e) => {
    const moreBtn = e.target.closest('[data-cal-event-more]');
    if (moreBtn) {
      e.preventDefault();
      e.stopPropagation();
      if (typeof this._showEventCardMenu === 'function') this._showEventCardMenu(moreBtn, ev.id);
      return;
    }
    e.stopPropagation(); this._openEventInPanel(ev.id);
  });
  // リサイズハンドル
  const resBot = document.createElement('div'); resBot.className = 'gb-cal-ev-resize-bottom';
  const resTop = document.createElement('div'); resTop.className = 'gb-cal-ev-resize-top';
  card.appendChild(resTop); card.appendChild(resBot);
  resBot.addEventListener('pointerdown', (e) => { if (!_calRecurringInteractionBlocked(this, ev)) this._handleResize(e, card, ev, evStart, startH, 'bottom'); });
  resTop.addEventListener('pointerdown', (e) => { if (!_calRecurringInteractionBlocked(this, ev)) this._handleResize(e, card, ev, evStart, startH, 'top'); });
  // D&D
  card.draggable = true;
  card.addEventListener('dragstart', (e) => {
    if (_calRecurringInteractionBlocked(this, ev)) { e.preventDefault(); return; }
    e.dataTransfer.setData('application/x-cal-move', JSON.stringify({ id: ev.id, startH, allDay: false }));
    e.dataTransfer.effectAllowed = 'move';
    card.style.opacity = '0.4';
  });
  card.addEventListener('dragend', () => { card.style.opacity = ''; });
  return card;
};

CalendarComponent.prototype._handleResize = function(e, card, ev, evStart, startH, direction) {
  e.stopPropagation(); e.preventDefault();
  const sy = e.clientY, origTop = parseFloat(card.style.top), origH = card.offsetHeight;
  // 15分刻み: 40px = 1時間、10px = 15分
  const snap15 = (px) => Math.round(px / 10) * 10;
  document.body.style.userSelect = 'none';
  const onMove = (e2) => {
    if (direction === 'bottom') card.style.height = Math.max(10, snap15(origH + e2.clientY - sy)) + 'px';
    else { const dy = snap15(e2.clientY - sy); card.style.top = (origTop + dy) + 'px'; card.style.height = Math.max(10, origH - dy) + 'px'; }
  };
  const snap15min = (h) => Math.round(h * 4) / 4; // 15分単位に丸め
  const onUp = () => {
    document.removeEventListener('pointermove', onMove); document.removeEventListener('pointerup', onUp);
    document.body.style.userSelect = ''; card.style.touchAction = '';
    // コミット前レビュー指摘 #5: production-task予定はタスク側が正本で undo 対象外
    // （_eventIsUndoable。_calApplyEventTimePatch がタスクへ書き戻す）。undo記録を積んでも
    // 元に戻せないため、偽のUndo記録を残さない。
    if (this._eventIsUndoable(ev)) this._pushUndo('イベントリサイズ');
    const minDurationMs = 15 * 60000;
    const originalStart = new Date(ev.start || evStart);
    const originalEnd = ev.end ? new Date(ev.end) : new Date(originalStart.getTime() + 3600000);
    if (direction === 'bottom') {
      const newEndH = snap15min(startH + card.offsetHeight / 40);
      const ne = new Date(evStart); ne.setHours(Math.floor(newEndH), (newEndH % 1) * 60);
      if (ne <= originalStart) ne.setTime(originalStart.getTime() + minDurationMs);
      _calApplyEventTimePatch(this, ev, { end: this._localDateTimeStr(ne) })
        .then(() => { this._loadEvents().then(() => this._render()); })
        .catch((error) => { this._showStatus?.(error?.message || '予定のリサイズに失敗しました', true); this._loadEvents().then(() => this._render()); });
    } else {
      const newStartH = snap15min(Math.floor(startH) + parseFloat(card.style.top) / 40);
      const ns = new Date(evStart); ns.setHours(Math.floor(newStartH), (newStartH % 1) * 60);
      if (ns >= originalEnd) ns.setTime(originalEnd.getTime() - minDurationMs);
      _calApplyEventTimePatch(this, ev, { start: this._localDateTimeStr(ns) })
        .then(() => { this._loadEvents().then(() => this._render()); })
        .catch((error) => { this._showStatus?.(error?.message || '予定のリサイズに失敗しました', true); this._loadEvents().then(() => this._render()); });
    }
  };
  card.style.touchAction = 'none';
  document.addEventListener('pointermove', onMove); document.addEventListener('pointerup', onUp);
};

// === 週ドラッグ選択 ===
CalendarComponent.prototype._initWeekDrag = function(el) {
  let dragging = false, startDate = '', startHour = 0, preview = null;
  const cells = el.querySelectorAll('.gb-cal-week-cell');
  const self = this;
  cells.forEach(cell => {
    cell.addEventListener('pointerdown', (e) => {
      if (e.target.closest('.gb-cal-week-event')) return;
      if (self._selectedCalendar?.()?.source === 'shift') {
        self._showStatus?.('シフトカレンダーは月表示で日付をクリックして追加してください', true);
        return;
      }
      e.preventDefault(); dragging = true;
      startDate = cell.dataset.date; startHour = parseInt(cell.dataset.hour);
      document.body.style.userSelect = 'none';
      preview = document.createElement('div'); preview.className = 'gb-cal-week-event';
      preview.style.cssText = 'background:var(--cal-event-bg, var(--cal-accent, var(--accent)));color:var(--cal-event-fg, var(--ui-accent-fg, var(--ui-fg-strong)));opacity:0.6;pointer-events:none;top:0;height:40px;left:2px;right:18px;';
      preview.textContent = `${startHour}:00 – ${startHour+1}:00`;
      cell.style.position = 'relative'; cell.appendChild(preview);
    });
    cell.addEventListener('pointermove', () => {
      if (!dragging || cell.dataset.date !== startDate) return;
      const curH = parseInt(cell.dataset.hour);
      const minH = Math.min(startHour, curH), maxH = Math.max(startHour, curH) + 1;
      if (preview?.parentElement) preview.remove();
      const anchor = el.querySelector(`.gb-cal-week-cell[data-date="${startDate}"][data-hour="${minH}"]`);
      if (anchor) { anchor.style.position = 'relative'; preview.style.top = '0'; preview.style.height = ((maxH-minH)*40) + 'px'; preview.textContent = `${minH}:00 – ${maxH}:00`; anchor.appendChild(preview); }
    });
    cell.addEventListener('pointerup', () => {
      if (!dragging) return;
      dragging = false; document.body.style.userSelect = '';
      if (preview) { preview.remove(); preview = null; }
      const endH = parseInt(cell.dataset.hour) + 1;
      const minH = Math.min(startHour, endH - 1), maxH = Math.max(startHour + 1, endH);
      let endStr;
      if (maxH >= 24) {
        // 「T24:00」は日時入力欄で扱えないため、翌日0:00として渡す（月末・年末も Date 演算で処理）
        const next = new Date(startDate + 'T00:00');
        next.setDate(next.getDate() + 1);
        endStr = `${next.getFullYear()}-${String(next.getMonth() + 1).padStart(2, '0')}-${String(next.getDate()).padStart(2, '0')}T00:00`;
      } else {
        endStr = startDate + 'T' + String(maxH).padStart(2, '0') + ':00';
      }
      self._openEventInPanel(null, startDate + 'T' + String(minH).padStart(2,'0') + ':00', endStr);
    });
    // D&Dドロップ受け入れ
    cell.addEventListener('dragover', (e) => { e.preventDefault(); cell.style.background = 'rgba(86,156,214,0.15)'; });
    cell.addEventListener('dragleave', () => { cell.style.background = ''; });
    cell.addEventListener('drop', async (e) => {
      e.preventDefault(); cell.style.background = '';
      const d = e.dataTransfer.getData('application/x-cal-move');
      if (!d) return;
      const { id, allDay } = JSON.parse(d);
      const ev = self._events.find(x => x.id === id);
      if (!ev) return;
      if (_calRecurringInteractionBlocked(self, ev)) return;
      const range = _calEventRange(ev);
      if (!range) return;
      const dur = allDay || ev.all_day ? 3600000 : Math.max(15 * 60000, range.end - range.start);
      const ns = new Date(cell.dataset.date + 'T' + String(parseInt(cell.dataset.hour)).padStart(2,'0') + ':00');
      const nextStart = self._localDateTimeStr(ns);
      const nextEnd = self._localDateTimeStr(new Date(ns.getTime()+dur));
      const patch = { start: nextStart, end: nextEnd, all_day: 0 };
      const deltaMs = ns.getTime() - range.start.getTime();
      const grouped = await self._moveSelectedEventGroup(ev, patch, patch, other => _calWeekShiftPatch(self, other, deltaMs));
      if (grouped) return;
      // コミット前レビュー指摘 #5: production-task予定は undo 対象外なので偽記録を積まない。
      if (self._eventIsUndoable(ev)) self._pushUndo('イベント移動');
      const before = self._snapshotEventLocal(id);
      self._applyEventLocal(id, patch);
      self._render();
      _calApplyEventTimePatch(self, ev, patch)
        .then(() => self._loadEvents())
        .then(() => self._render())
        .catch((error) => {
          self._restoreEventLocal(before);
          self._render();
          self._showStatus(error?.message ? ('イベント移動に失敗: ' + error.message) : 'イベント移動に失敗', true);
        });
    });
  });
  const cleanup = () => { if (dragging) { dragging = false; document.body.style.userSelect = ''; if (preview) { preview.remove(); preview = null; } } };
  if (el._calWeekCleanup) document.removeEventListener('pointerup', el._calWeekCleanup);
  el._calWeekCleanup = cleanup;
  document.addEventListener('pointerup', cleanup);
};

CalendarComponent.prototype._clearNowLineTimer = function() {
  if (this._nowLineTimer) clearInterval(this._nowLineTimer);
  this._nowLineTimer = null;
  this._contentEl?.querySelectorAll?.('.gb-cal-now-line').forEach(el => el.remove());
};

CalendarComponent.prototype._syncNowLineTimer = function() {
  if (!['week', 'multi', 'day'].includes(this._view)) {
    this._clearNowLineTimer?.();
    return;
  }
  this._updateNowLine();
  if (this._nowLineTimer) return;
  this._nowLineTimer = setInterval(() => this._updateNowLine(), 30000);
};

CalendarComponent.prototype._updateNowLine = function() {
  const root = this._contentEl;
  if (!root || !['week', 'multi', 'day'].includes(this._view)) return;
  root.querySelectorAll('.gb-cal-now-line').forEach(el => el.remove());
  const now = new Date();
  const dateStr = this._localDateStr(now);
  const hour = now.getHours();
  const cell = root.querySelector(`.gb-cal-week-cell[data-date="${dateStr}"][data-hour="${hour}"]`);
  if (!cell) return;
  const line = document.createElement('div');
  line.className = 'gb-cal-now-line';
  const rect = cell.getBoundingClientRect?.();
  const hourPx = Math.max(1, rect?.height || 40);
  line.style.top = ((now.getMinutes() / 60) * hourPx) + 'px';
  cell.appendChild(line);
};

// === ToDoリスト ===
CalendarComponent.prototype._renderTaskBoard = function() {
  this._clearNowLineTimer?.();
  const el = this._contentEl;
  const statuses = [['backlog','バックログ'],['todo','未着手'],['in_progress','進行中'],['review','レビュー'],['done','完了']];
  let html = '<div class="gb-cal-task-board">';
  statuses.forEach(([key, label]) => {
    const tasks = this._tasks.filter(t => t.status === key && !t.parent_id);
    html += `<div class="gb-cal-task-column"><div class="gb-cal-task-col-header"><span>${label}</span><span style="font-size:11px;color:var(--cal-muted-fg, var(--fg2));">${tasks.length}</span></div><div class="gb-cal-task-col-body">`;
    tasks.forEach(t => {
      const pc = t.priority || 'medium';
      html += `<div class="gb-cal-task-card" data-task-id="${t.id}"><div class="gb-cal-task-card-title">${esc(t.title)}</div><div class="gb-cal-task-card-meta"><span class="gb-cal-task-priority ${pc}">${pc}</span>`;
      if (t.due_date) html += `<span>〆 ${t.due_date.substring(5)}</span>`;
      if (t.assignee) html += `<span>${esc(t.assignee)}</span>`;
      html += '</div></div>';
    });
    html += `<div style="padding:4px;text-align:center;cursor:pointer;color:var(--cal-muted-fg, var(--fg2));font-size:12px;" data-add-task="${key}">+ 追加</div></div></div>`;
  });
  html += '</div>';
  el.innerHTML = html;
  if (el._calClickHandler) el.removeEventListener('click', el._calClickHandler);
  el._calClickHandler = (e) => {
    const card = e.target.closest('.gb-cal-task-card');
    if (card) { this._showTaskModal(card.dataset.taskId); return; }
    const add = e.target.closest('[data-add-task]');
    if (add) this._showTaskModal(null, add.dataset.addTask);
  };
  el.addEventListener('click', el._calClickHandler);
};

// === シフト表 ===
CalendarComponent.prototype._renderShiftView = async function(renderSeq) {
  const activeSeq = renderSeq || this._renderSeq;
  await this._loadShifts();
  if (this._view !== 'shifts' || activeSeq !== this._renderSeq) return;
  const el = this._contentEl, y = this._date.getFullYear(), m = this._date.getMonth();
  const dim = new Date(y, m+1, 0).getDate(), todayStr = this._localDateStr();
  const users = [...new Set(this._shifts.map(s => s.user).filter(Boolean))];
  if (!users.length) users.push(this._getUser());
  const mStart = `${y}-${String(m+1).padStart(2,'0')}-01`;
  const mEnd = `${y}-${String(m+1).padStart(2,'0')}-${String(dim).padStart(2,'0')}T23:59:59`;
  let timeEntries = [];
  try { timeEntries = await apiFetch('/cal/time?date_from=' + mStart + '&date_to=' + mEnd); } catch {}
  if (this._view !== 'shifts' || activeSeq !== this._renderSeq) return;
  let html = '<div style="overflow-x:auto;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
  html += `<span style="font-weight:bold;">${y}年${m+1}月 シフト表</span><button class="gb-cal-shift-add" style="font-size:12px;padding:3px 10px;">+ シフト追加</button></div>`;
  html += '<table style="width:100%;border-collapse:collapse;font-size:11px;"><tr><th style="padding:4px 8px;border:1px solid var(--cal-grid-line, var(--border));background:var(--cal-header-bg, var(--bg3));color:var(--cal-header-fg, var(--fg2));min-width:80px;">ユーザー</th>';
  for (let d = 1; d <= dim; d++) {
    const ds = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const dow = ['日','月','火','水','木','金','土'][new Date(y,m,d).getDay()];
    const isT = ds === todayStr, isW = [0,6].includes(new Date(y,m,d).getDay());
    html += `<th style="padding:2px 4px;border:1px solid var(--cal-grid-line, var(--border));background:${isT?'var(--cal-mini-selected-bg, var(--cal-accent, var(--accent)))':isW?'var(--cal-cell-hover-bg, var(--bg4))':'var(--cal-header-bg, var(--bg3))'};color:${isT?'var(--cal-mini-selected-fg, var(--ui-accent-fg, var(--ui-fg-strong)))':'var(--cal-header-fg, var(--fg))'};min-width:36px;text-align:center;">${d}<br><span style="font-size:9px;">${dow}</span></th>`;
  }
  html += '</tr>';
  users.forEach(user => {
    html += `<tr><td style="padding:4px 8px;border:1px solid var(--cal-grid-line, var(--border));background:var(--cal-sidebar-bg, var(--bg2));font-weight:bold;color:var(--cal-sidebar-fg, var(--fg));">${esc(user)}<br><span style="font-size:9px;color:var(--cal-muted-fg, var(--fg2));">予定</span></td>`;
    for (let d = 1; d <= dim; d++) {
      const ds = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const sh = this._shifts.find(s => s.user === user && s.date === ds);
      const tc = { work: 'var(--blue)', off: 'var(--cal-muted-fg, var(--fg2))', holiday: 'var(--green)' };
      const bg = sh ? (tc[sh.type] || 'var(--cal-muted-fg, var(--fg2))') : '';
      const txt = sh ? (sh.start_time ? sh.start_time.substring(0,5)+'-'+(sh.end_time||'').substring(0,5) : (sh.type==='off'?'休':sh.type==='holiday'?'祝':'')) : '';
      html += `<td class="gb-cal-shift-cell" data-user="${esc(user)}" data-date="${ds}" ${sh?`data-sid="${sh.id}"`:''}style="padding:2px;border:1px solid var(--cal-grid-line, var(--border));text-align:center;cursor:pointer;background:var(--cal-cell-bg, var(--bg));color:var(--cal-fg, var(--fg));${bg?'color:var(--cal-event-fg, #fff);background:'+bg:''}" title="${esc(sh?.note||'')}">${txt}</td>`;
    }
    html += '</tr>';
    html += `<tr><td style="padding:4px 8px;border:1px solid var(--cal-grid-line, var(--border));background:var(--cal-cell-bg, var(--bg));"><span style="font-size:9px;color:var(--cal-muted-fg, var(--fg2));">実績</span></td>`;
    for (let d = 1; d <= dim; d++) {
      const ds = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const de = timeEntries.filter(e => e.user === user && e.timestamp.startsWith(ds));
      const ci = de.find(e => e.type === 'clock_in'), co = de.filter(e => e.type === 'clock_out').pop();
      let breakMs = 0;
      let breakStart = null;
      de.forEach(row => {
        if (row.type === 'break_start') breakStart = row;
        else if (row.type === 'break_end' && breakStart) {
          breakMs += Math.max(0, new Date(row.timestamp) - new Date(breakStart.timestamp));
          breakStart = null;
        }
      });
      let at = '';
      if (ci && co) at = (Math.max(0, new Date(co.timestamp) - new Date(ci.timestamp) - breakMs) / 3600000).toFixed(1) + 'h';
      else if (ci) at = ci.timestamp.substring(11,16)+'-';
      const sh = this._shifts.find(s => s.user === user && s.date === ds);
      const cb = sh && sh.type === 'work' && !ci ? 'background:rgba(244,71,71,0.15);' : '';
      html += `<td style="padding:2px;border:1px solid var(--cal-grid-line, var(--border));text-align:center;font-size:10px;color:var(--cal-muted-fg, var(--fg2));background:var(--cal-cell-bg, var(--bg));${cb}">${at}</td>`;
    }
    html += '</tr>';
  });
  html += '</table></div>';
  el.innerHTML = html;
  el.querySelector('.gb-cal-shift-add')?.addEventListener('click', () => this._showShiftModal());
  el.querySelectorAll('.gb-cal-shift-cell').forEach(c => {
    c.addEventListener('click', () => this._showShiftModal(c.dataset.user, c.dataset.date, c.dataset.sid));
  });
};

CalendarComponent.prototype._loadShifts = async function() {
  const y = this._date.getFullYear(), m = this._date.getMonth() + 1;
  try { this._shifts = await apiFetch('/cal/shifts?month=' + y + '-' + String(m).padStart(2,'0')); } catch { this._shifts = []; }
};

// === ミニカレンダー ===
CalendarComponent.prototype._miniDateRange = function(startStr, endStr) {
  const start = this._parseLocalDate(startStr);
  const end = this._parseLocalDate(endStr);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) return [endStr].filter(Boolean);
  const dir = start <= end ? 1 : -1;
  const out = [];
  const cur = new Date(start);
  while ((dir > 0 && cur <= end) || (dir < 0 && cur >= end)) {
    out.push(this._localDateStr(cur));
    cur.setDate(cur.getDate() + dir);
  }
  return dir > 0 ? out : out.reverse();
};

CalendarComponent.prototype._onMiniDayClick = function(dateStr, event) {
  const previousDateStr = this._localDateStr(this._date);
  const selected = this._selectedMiniDates || new Set();
  if (event?.shiftKey) {
    const anchor = this._lastMiniDateStr || this._selectedMiniDateList()[0] || previousDateStr;
    this._selectedMiniDates = new Set(this._miniDateRange(anchor, dateStr));
  } else if (event?.ctrlKey || event?.metaKey) {
    if (!selected.size) selected.add(previousDateStr);
    if (selected.has(dateStr)) selected.delete(dateStr);
    else selected.add(dateStr);
    if (!selected.size) selected.add(dateStr);
    this._selectedMiniDates = selected;
    this._lastMiniDateStr = dateStr;
  } else {
    selected.clear();
    this._selectedMiniDates = selected;
    this._lastMiniDateStr = dateStr;
  }
  let focusDateStr = dateStr;
  const selectedList = this._selectedMiniDateList();
  if (selectedList.length > 1) {
    this._view = 'multi';
  } else if (selectedList.length === 1) {
    focusDateStr = selectedList[0];
    this._selectedMiniDates.clear();
  }
  this._date = this._parseLocalDate(focusDateStr);
  this._persistViewToTabState?.(this._view);
  const viewSel = this.el?.querySelector?.('.gb-cal-view-select');
  if (viewSel && viewSel.value !== this._view) viewSel.value = this._view;
  this._syncMultiDayControls?.();
  this._loadEvents().then(() => this._render());
  this._renderMiniCal();
};

CalendarComponent.prototype._renderMiniCal = function() {
  const y = this._date.getFullYear(), m = this._date.getMonth();
  this._miniTitleEl.textContent = `${y}年${m+1}月`;
  const rawFirst = new Date(y, m, 1).getDay();
  const firstDay = (rawFirst - this._startDay + 7) % 7;
  const dim = new Date(y, m+1, 0).getDate();
  const todayStr = this._localDateStr(), selStr = this._localDateStr(this._date);
  const selectedDates = new Set(this._selectedMiniDateList());
  let html = this._getDayNames().map(d => `<div style="font-size:10px;color:var(--cal-muted-fg, var(--fg2));padding:2px;">${d}</div>`).join('');
  for (let i = 0; i < firstDay; i++) html += '<div></div>';
  for (let d = 1; d <= dim; d++) {
    const ds = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const isSelected = selectedDates.size ? selectedDates.has(ds) : ds === selStr;
    const cls = [ds===todayStr?'gb-cal-today':'',isSelected?'gb-cal-selected':''].filter(Boolean).join(' ');
    html += `<div class="gb-cal-mini-day ${cls}" data-date="${ds}">${d}</div>`;
  }
  this._miniGridEl.innerHTML = html;
  this._miniGridEl.querySelectorAll('.gb-cal-mini-day').forEach(el => {
    el.addEventListener('click', (event) => this._onMiniDayClick(el.dataset.date, event));
  });
};

// === 今日のToDo ===
CalendarComponent.prototype._renderTodayTasks = function() {
  const todayStr = this._localDateStr();
  const tasks = this._tasks.filter(t => t.due_date === todayStr || (t.status !== 'done' && t.status !== 'backlog'));
  const el = this._todayTasksEl;
  if (!tasks.length) {
    el.innerHTML = '<div style="color:var(--cal-muted-fg, var(--fg2));">ToDoなし</div>';
  } else {
    el.innerHTML = tasks.slice(0, 10).map(t =>
      `<div class="gb-cal-today-task-item" data-task-id="${t.id}" style="padding:4px 0;border-bottom:1px solid var(--cal-grid-line, var(--border));cursor:pointer;">` +
      `<span class="gb-cal-task-priority ${t.priority||'medium'}" style="margin-right:4px;">${(t.priority||'M')[0].toUpperCase()}</span>${esc(t.title)}</div>`
    ).join('');
    el.querySelectorAll('.gb-cal-today-task-item').forEach(item => {
      item.addEventListener('click', () => this._showTaskModal(item.dataset.taskId));
    });
  }
  this._renderProductionTodayTasks?.(el, todayStr);
};

CalendarComponent.prototype._renderProductionTodayTasks = async function(container, todayStr) {
  if (!container || !window.MeldexProductionApi?.list) return;
  const seq = (this._productionTodaySeq || 0) + 1;
  this._productionTodaySeq = seq;
  container.querySelector('.gb-cal-production-today-section')?.remove();
  const user = String(this._getUser?.() || '').trim();
  if (!user) return;
  const plannedOnToday = (value) => {
    const text = String(value || '').trim();
    if (!text) return false;
    const [startRaw, endRaw] = text.includes('|') ? text.split('|', 2) : [text, text];
    const start = String(startRaw || '').slice(0, 10);
    const end = String(endRaw || startRaw || '').slice(0, 10);
    return start <= todayStr && todayStr <= (end || start);
  };
  try {
    const data = await window.MeldexProductionApi.list('タスクリスト', { limit: 1000 });
    if (this._productionTodaySeq !== seq) return;
    const rows = (data.rows || []).filter(row => {
      const props = row.properties || {};
      const assignees = String(props['担当者'] || '').split(/[,\n、]/).map(v => v.trim()).filter(Boolean);
      return assignees.includes(user) && plannedOnToday(props['作業予定日時']);
    }).slice(0, 8);
    if (!rows.length) return;
    const section = document.createElement('div');
    section.className = 'gb-cal-production-today-section';
    const heading = document.createElement('div');
    heading.className = 'gb-cal-production-today-heading';
    heading.textContent = '自分のタスク';
    section.appendChild(heading);
    rows.forEach(row => {
      const item = document.createElement('button');
      item.type = 'button';
      item.className = 'gb-cal-production-today-task';
      item.textContent = row.name || 'タスク';
      item.title = item.textContent;
      item.addEventListener('click', () => {
        if (row.path && typeof openPage === 'function') openPage(row.name || 'タスク', row.path);
      });
      section.appendChild(item);
    });
    container.appendChild(section);
  } catch {}
};

// === カレンダーリスト ===
CalendarComponent.prototype._renderCalendarList = function() {
  const container = this._calListEl;
  if (!container) return;
  container.innerHTML = '';
  this._ensureSelectedCalendar?.();
  this._calendars.forEach(c => {
    const row = document.createElement('div');
    row.className = 'gb-cal-calendar-row';
    row.dataset.calendarId = c.id;
    row.tabIndex = 0;
    row.classList.toggle('is-selected', this._selectedCalendarId === c.id);
    row.style.cssText = 'display:flex;align-items:center;gap:6px;padding:3px 0;cursor:pointer;';
    row.addEventListener('click', (e) => {
      if (e.target.closest('input,button,select,label')) return;
      this._selectCalendar?.(c.id);
    });
    row.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter' && e.key !== ' ') return;
      e.preventDefault();
      this._selectCalendar?.(c.id);
    });
    const cb = document.createElement('input');
    cb.type = 'checkbox'; cb.checked = this._visibleCalIds.has(c.id);
    cb.addEventListener('change', () => {
      if (cb.checked) this._visibleCalIds.add(c.id); else this._visibleCalIds.delete(c.id);
      if (!cb.checked && this._selectedCalendarId === c.id) this._selectedCalendarId = '';
      this._ensureSelectedCalendar?.();
      apiPut('/cal/calendars/' + c.id + '?_user=' + encodeURIComponent(this._getUser()), { visible: cb.checked ? 1 : 0 });
      this._renderCalendarList();
      this._render();
    });
    const dot = document.createElement('span');
    dot.style.cssText = `width:10px;height:10px;border-radius:50%;background:${c.color};flex-shrink:0;`;
    const label = document.createElement('span');
    label.textContent = c.name;
    label.style.cssText = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;';
    row.appendChild(cb); row.appendChild(dot); row.appendChild(label);
    container.appendChild(row);
  });
};

CalendarComponent.prototype._createCalendar = async function() {
  let idx = 1, name = '無題';
  const names = this._calendars.map(c => c.name);
  while (names.includes(name)) { idx++; name = '無題' + idx; }
  const calColor = (typeof MeldexThemeManager !== 'undefined' && typeof MeldexThemeManager.getThemeColorSet === 'function')
    ? (MeldexThemeManager.getThemeColorSet()[this._calendars.length % 8] || PALETTE_COLORS[this._calendars.length % PALETTE_COLORS.length])
    : PALETTE_COLORS[this._calendars.length % PALETTE_COLORS.length];
  await apiPost('/cal/calendars', { name, color: calColor, user: this._getUser() });
  await this._loadCalendars();
};

// === 打刻 ===
CalendarComponent.prototype._initClockPanel = function() {
  const cb = this.el.querySelector('.gb-cal-clock-toggle');
  if (cb) { cb.checked = this._clockEnabled; cb.addEventListener('change', () => this._toggleClockPanel(cb.checked)); }
  if (this._clockBtnsEl) this._clockBtnsEl.style.display = this._clockEnabled ? '' : 'none';
};

CalendarComponent.prototype._toggleClockPanel = function(on) {
  this._clockEnabled = on;
  localStorage.setItem('gb:clock-enabled', on ? 'true' : 'false');
  if (this._clockBtnsEl) this._clockBtnsEl.style.display = on ? '' : 'none';
  if (on) this._updateClockStatus();
};

CalendarComponent.prototype._clockAction = async function(type) {
  try {
    await apiPost('/cal/time', { type, user: this._getUser(), timestamp: this._localDateTimeStr(new Date()) });
    const labels = { clock_in: '出勤しました', clock_out: '退勤しました', break_start: '離席しました', break_end: '復帰しました' };
    this._showStatus(labels[type] || type);
    this._updateClockStatus();
  } catch { this._showStatus('打刻に失敗', true); }
};

CalendarComponent.prototype._updateClockStatus = async function() {
  const todayStr = this._localDateStr();
  try {
    const entries = await apiFetch('/cal/time?user=' + encodeURIComponent(this._getUser()) + '&date_from=' + todayStr);
    const last = entries[entries.length - 1];
    if (!last) { if (this._clockStatusEl) this._clockStatusEl.textContent = '未出勤'; return; }
    const labels = { clock_in: '出勤中', clock_out: '退勤済み', break_start: '離席中', break_end: '出勤中' };
    if (this._clockStatusEl) this._clockStatusEl.textContent = (labels[last.type] || last.type) + ' ' + last.timestamp.substring(11, 16);
  } catch {}
};

// === サイドバーリサイズ ===
CalendarComponent.prototype._toggleSidebar = function() {
  const rz = this.el.querySelector('.gb-cal-sidebar-resize');
  this._sidebarEl.classList.toggle('gb-cal-hidden');
  rz.style.display = this._sidebarEl.classList.contains('gb-cal-hidden') ? 'none' : '';
};

CalendarComponent.prototype._bindSidebarResize = function() {
  const handle = this.el.querySelector('.gb-cal-sidebar-resize');
  const sidebar = this._sidebarEl;
  if (!handle || !sidebar) return;
  let startX, startW;
  handle.addEventListener('pointerdown', (e) => {
    e.preventDefault(); startX = e.clientX; startW = sidebar.offsetWidth;
    handle.classList.add('gb-cal-active');
    document.body.style.cursor = 'col-resize'; document.body.style.userSelect = 'none';
    const onMove = (e2) => { sidebar.style.width = Math.max(120, Math.min(500, startW + e2.clientX - startX)) + 'px'; };
    const onUp = () => { handle.classList.remove('gb-cal-active'); document.body.style.cursor = ''; document.body.style.userSelect = ''; document.removeEventListener('pointermove', onMove); document.removeEventListener('pointerup', onUp); localStorage.setItem('gb:cal-sidebar-width', sidebar.offsetWidth); };
    document.addEventListener('pointermove', onMove); document.addEventListener('pointerup', onUp);
  });
  const saved = localStorage.getItem('gb:cal-sidebar-width');
  if (saved) sidebar.style.width = saved + 'px';
};

// === アラーム ===
CalendarComponent.prototype._checkAlarms = async function() {
  try {
    const alerts = await apiFetch('/cal/alerts?minutes_ahead=2&lookback_minutes=1440&user=' + encodeURIComponent(this._getUser()));
    alerts.forEach(ev => {
      const key = ev.id + ev._alert_time;
      if (this._alertedIds.has(key)) return;
      this._alertedIds.add(key);
      if ('Notification' in window && Notification.permission === 'granted') new Notification('Meldex カレンダー', { body: ev.title + '\n' + (ev.start||'').substring(11,16), icon: '/Meldex_icon.png' });
      this._showStatus('🔔 ' + ev.title);
    });
  } catch {}
};

// === 右パネル（イベント編集フォーム） ===
CalendarComponent.prototype._openEventInPanel = function(editId, defaultStart, defaultEnd, defaultAllDay) {
  const ev = editId ? this._events.find(e => e.id === editId) : null;
  if (ev && _calRecurringInteractionBlocked(this, ev)) return;
  // 親の詳細パネルに表示を委譲
  if (typeof _showCalEventInDetailPanel === 'function') {
    _showCalEventInDetailPanel(ev ? { ...ev } : null, this._calendars.map(c => ({ id: c.id, name: c.name })), defaultStart, defaultEnd, !!defaultAllDay, this);
    return;
  }
  // フォールバック: コンポーネント内の右パネルに表示
  const panel = this._rightPanelEl;
  panel.classList.add('gb-cal-open');
  const now = new Date();
  const sVal = ev ? ev.start.substring(0,16) : (defaultStart || this._localDateTimeStr(now));
  const eVal = ev ? (ev.end||'').substring(0,16) : (defaultEnd || this._localDateTimeStr(new Date(now.getTime()+3600000)));
  const isAllDay = ev ? ev.all_day : !!defaultAllDay;
  const calOpts = this._calendars.map(c => `<option value="${c.id}" ${ev?.calendar_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('');
  const _rp = CalendarComponent._recParse;
  panel.innerHTML = `<h3>${ev?'イベント編集':'新規イベント'}</h3>
<div class="field"><label>タイトル</label><input class="rp-ev-title" type="text" value="${esc(ev?.title||'')}" placeholder="イベント名"></div>
<div class="field"><label><input class="rp-ev-allday" type="checkbox" ${isAllDay?'checked':''}> 終日</label></div>
<div class="field"><label>開始</label><input class="rp-ev-start" type="datetime-local" value="${sVal}" ${isAllDay?'disabled style="opacity:0.4"':''}></div>
<div class="field"><label>終了</label><input class="rp-ev-end" type="datetime-local" value="${eVal}" ${isAllDay?'disabled style="opacity:0.4"':''}></div>
<div class="field"><label>カレンダー</label><select class="rp-ev-calendar gb-select" style="width:100%;">${calOpts}</select></div>
<div class="field"><label>色</label><button type="button" class="rp-ev-color gb-color-swatch gb-color-swatch--field" data-color="${esc(ev?.color||'#569cd6')}" title="イベント色"></button></div>
<div class="field"><label>場所</label><input class="rp-ev-location" type="text" value="${esc(ev?.location||'')}"></div>
<div class="field"><label>URL</label><input class="rp-ev-url" type="url" value="${esc(ev?.url||'')}" placeholder="https://..."></div>
<div class="field"><label>説明</label><textarea class="rp-ev-desc" rows="3">${esc(ev?.description||'')}</textarea></div>
<div class="field"><label>アラーム</label><select class="rp-ev-alert gb-select" style="width:100%;">
  <option value="-1" ${(ev?.alert_minutes??-1)===-1?'selected':''}>なし</option><option value="0" ${ev?.alert_minutes===0?'selected':''}>イベント時</option>
  <option value="5" ${ev?.alert_minutes===5?'selected':''}>5分前</option><option value="15" ${ev?.alert_minutes===15?'selected':''}>15分前</option>
  <option value="30" ${ev?.alert_minutes===30?'selected':''}>30分前</option><option value="60" ${ev?.alert_minutes===60?'selected':''}>1時間前</option>
</select></div>
<div class="btn-row">
  ${ev?'<button class="danger rp-ev-delete">削除</button>':''}
  <button class="rp-ev-cancel">キャンセル</button>
  <button class="primary rp-ev-save">${ev?'更新':'作成'}</button>
</div>`;
  panel.querySelector('.rp-ev-allday').addEventListener('change', function() {
    const s = panel.querySelector('.rp-ev-start'), e2 = panel.querySelector('.rp-ev-end');
    s.disabled = e2.disabled = this.checked; s.style.opacity = e2.style.opacity = this.checked ? '0.4' : '1';
  });
  const colorSwatch = panel.querySelector('.rp-ev-color');
  bindColorSwatch(colorSwatch, () => getColorSwatchValue(colorSwatch, ev?.color || '#569cd6'), (nextColor) => {
    setColorSwatchValue(colorSwatch, nextColor || '#569cd6');
  });
  panel.querySelector('.rp-ev-save').addEventListener('click', () => this._saveEventFromPanel(ev?.id || ''));
  panel.querySelector('.rp-ev-cancel').addEventListener('click', () => this._closeRightPanel());
  if (ev) panel.querySelector('.rp-ev-delete').addEventListener('click', () => this._deleteEventFromPanel(ev.id));
  setTimeout(() => panel.querySelector('.rp-ev-title')?.focus(), 50);
};

CalendarComponent.prototype._saveEventFromPanel = async function(editId) {
  const p = this._rightPanelEl;
  this._pushUndo(editId ? 'イベント編集' : 'イベント作成');
  const data = {
    title: p.querySelector('.rp-ev-title').value,
    start: p.querySelector('.rp-ev-start').value,
    end: p.querySelector('.rp-ev-end').value,
    all_day: p.querySelector('.rp-ev-allday').checked ? 1 : 0,
    color: getColorSwatchValue(p.querySelector('.rp-ev-color'), ''),
    location: p.querySelector('.rp-ev-location').value,
    url: p.querySelector('.rp-ev-url')?.value || '',
    description: p.querySelector('.rp-ev-desc').value,
    alert_minutes: parseInt(p.querySelector('.rp-ev-alert').value),
    calendar_id: p.querySelector('.rp-ev-calendar')?.value || '',
    user: this._getUser(),
  };
  try {
    if (editId) await apiPut('/cal/events/' + editId, data);
    else await apiPost('/cal/events', data);
    await this._loadEvents(); this._render();
    this._closeRightPanel();
    this._showStatus('イベントを保存しました');
  } catch { this._showStatus('保存に失敗', true); }
};

CalendarComponent.prototype._deleteEventFromPanel = async function(id) {
  if (typeof cfConfirm === 'function' && !await cfConfirm('このイベントを削除しますか？')) return;
  this._pushUndo('イベント削除');
  let calId = '';
  try {
    const evRef = (this._events || []).find(x => x.id === id);
    calId = evRef?.calendar_id || '';
  } catch (_) {}
  try {
    await apiFetch('/cal/events/' + id, { method: 'DELETE' });
    // Audit-P1 H-6: 紐付いたコメントを孤児化する（target_kind='calendar_event'）
    apiPost('/annotations/orphan-by-target', {
      target_kind: 'calendar_event',
      target_file: calId || '_calendar',
      item_id: id,
      cascade_container: true,
    }).catch(() => {});
    await this._loadEvents();
    this._render();
    this._closeRightPanel();
    this._showStatus('削除しました');
  } catch {}
};

CalendarComponent.prototype._closeRightPanel = function() {
  this._rightPanelEl.classList.remove('gb-cal-open');
};

CalendarComponent._recParse = function(ev) { try { return ev?.recurrence ? (typeof ev.recurrence === 'string' ? JSON.parse(ev.recurrence) : ev.recurrence) : {}; } catch { return {}; } };

// === ToDoモーダル ===
CalendarComponent.prototype._showTaskDialogModal = function(editId, defaultStatus) {
  const t = editId ? this._tasks.find(x => x.id === editId) : null;
  const sts = [['backlog','バックログ'],['todo','未着手'],['in_progress','進行中'],['review','レビュー'],['done','完了']];
  const pris = [['low','低'],['medium','中'],['high','高'],['urgent','緊急']];
  const content = document.createElement('div');
  content.innerHTML = `<div class="gb-cal-task-form">
<div class="gb-cal-task-form-wide" role="status" aria-live="polite" data-cal-task-status></div>
<div class="field gb-cal-task-form-wide"><label>タイトル</label><input class="tk-title" value="${esc(t?.title||'')}"></div>
<div class="field"><label>ステータス</label><select class="tk-status">${sts.map(([v,l])=>`<option value="${v}" ${(t?.status||defaultStatus||'todo')===v?'selected':''}>${l}</option>`).join('')}</select></div>
<div class="field"><label>優先度</label><select class="tk-priority">${pris.map(([v,l])=>`<option value="${v}" ${(t?.priority||'medium')===v?'selected':''}>${l}</option>`).join('')}</select></div>
<div class="field"><label>期限</label><input class="tk-due" type="date" value="${t?.due_date||''}"></div>
<div class="field"><label>担当者</label><input class="tk-assignee" value="${esc(t?.assignee||'')}"></div>
<div class="field"><label>見積(h)</label><input class="tk-est" type="number" step="0.5" value="${t?.estimated_hours||0}"></div>
<div class="field"><label>実績(h)</label><input class="tk-act" type="number" step="0.5" value="${t?.actual_hours||0}"></div>
<div class="field gb-cal-task-form-wide"><label>説明</label><textarea class="tk-desc" rows="3">${esc(t?.description||'')}</textarea></div>
</div>`;
  const cancelButton = document.createElement('button');
  cancelButton.type = 'button'; cancelButton.className = 'tk-cancel gb-btn gb-btn-sm'; cancelButton.textContent = 'キャンセル';
  const saveButton = document.createElement('button');
  saveButton.type = 'button'; saveButton.className = 'tk-save gb-btn gb-btn-sm gb-btn-primary primary'; saveButton.textContent = '保存';
  const deleteButton = t ? document.createElement('button') : null;
  if (deleteButton) {
    deleteButton.type = 'button'; deleteButton.className = 'tk-delete gb-btn gb-btn-sm gb-btn-danger danger'; deleteButton.textContent = '削除';
  }
  let busy = false;
  let deleteConfirmPending = false;
  const modalApi = window.GBUI.createModal({
    id: 'calendar-tool-todo',
    title: t ? 'ToDo編集' : '新規ToDo',
    body: [...content.childNodes],
    footer: [deleteButton, cancelButton, saveButton].filter(Boolean),
    variant: 'standard',
    geometryKey: 'calendar-tool-todo',
    minWidth: '0',
    initialFocus: '.tk-title',
    closeLabel: 'ToDo編集を閉じる',
    closeOnEsc: true,
    closeOnOverlay: true,
    onBeforeClose: () => !busy && !deleteConfirmPending,
  });
  const o = modalApi.overlay;
  const panel = modalApi.modal;
  modalApi.body.style.setProperty('overflow-x', 'hidden', 'important');
  modalApi.body.style.minWidth = '0';
  modalApi.body.style.overflowWrap = 'anywhere';
  o.dataset.e2eId = 'calendar-tool-todo-overlay';
  o._calendarClose = modalApi.close;
  panel.classList.add('gb-cal-task-modal');
  panel.dataset.e2eId = 'calendar-tool-todo-dialog';
  panel.style.cssText = _gbCalModalSizeStyle(450, 'overflow:hidden;');
  const form = panel.querySelector('.gb-cal-task-form');
  if (form) {
    form.style.display = 'grid';
    form.style.gridTemplateColumns = window.innerWidth <= 640 ? 'minmax(0,1fr)' : 'repeat(2,minmax(0,1fr))';
    form.style.gap = '12px';
    form.style.minWidth = '0';
  }
  panel.querySelectorAll('.gb-cal-task-form-wide').forEach(field => { field.style.gridColumn = '1 / -1'; });
  panel.querySelectorAll('.field').forEach(field => {
    field.style.display = 'grid';
    field.style.gap = '6px';
    field.style.minWidth = '0';
    const label = field.querySelector('label');
    if (label) label.style.display = 'block';
  });
  panel.querySelectorAll('.field input,.field select,.field textarea').forEach(control => {
    control.style.width = '100%';
    control.style.minWidth = '0';
    control.style.maxWidth = '100%';
    control.style.boxSizing = 'border-box';
  });
  const status = panel.querySelector('[data-cal-task-status]');
  const setBusy = (next) => {
    busy = next;
    panel.setAttribute('aria-busy', next ? 'true' : 'false');
    [saveButton, deleteButton, cancelButton].filter(Boolean).forEach(button => { button.disabled = next; });
  };
  const reloadTasks = async () => {
    await this._loadTasks();
    this._render();
    this._renderTodayTasks();
  };
  modalApi.open();
  cancelButton.addEventListener('click', () => modalApi.close('cancel'));
  saveButton.addEventListener('click', async () => {
    if (busy) return;
    const data = {
      title: panel.querySelector('.tk-title').value,
      status: panel.querySelector('.tk-status').value,
      priority: panel.querySelector('.tk-priority').value,
      due_date: panel.querySelector('.tk-due').value,
      assignee: panel.querySelector('.tk-assignee').value,
      estimated_hours: parseFloat(panel.querySelector('.tk-est').value) || 0,
      actual_hours: parseFloat(panel.querySelector('.tk-act').value) || 0,
      description: panel.querySelector('.tk-desc').value,
      user: this._getUser(),
    };
    setBusy(true);
    if (status) status.textContent = '保存中...';
    try {
      if (editId) await apiPut('/cal/tasks/' + encodeURIComponent(editId), data);
      else await apiPost('/cal/tasks', data);
    } catch {
      if (status) status.textContent = '保存に失敗しました。入力内容を保ったまま再試行できます。';
      this._showStatus('保存に失敗', true);
      if (modalApi.isOpen()) setBusy(false);
      return;
    }
    let undoFailed = false;
    try { this._pushUndo(editId ? 'ToDo編集' : 'ToDo作成'); }
    catch {
      undoFailed = true;
      this._showStatus('ToDoは保存しましたが、Undo履歴を記録できませんでした', true);
    }
    let reloadFailed = false;
    try { await reloadTasks(); }
    catch {
      reloadFailed = true;
      this._showStatus('ToDoは保存しましたが、表示を更新できませんでした。画面を再読み込みしてください', true);
    }
    if (!reloadFailed && !undoFailed) this._showStatus('ToDoを保存しました');
    setBusy(false);
    modalApi.close('saved');
  });
  deleteButton?.addEventListener('click', async () => {
    if (busy || deleteConfirmPending) return;
    deleteConfirmPending = true;
    setBusy(true);
    if (status) status.textContent = '削除を確認中...';
    let confirmed = false;
    try { confirmed = typeof cfConfirm !== 'function' || await cfConfirm('このToDoを削除しますか？'); }
    catch {
      if (status) status.textContent = '削除確認を表示できませんでした。もう一度お試しください。';
    } finally {
      deleteConfirmPending = false;
      if (!confirmed && modalApi.isOpen()) setBusy(false);
    }
    if (!confirmed) return;
    if (status) status.textContent = '削除中...';
    try {
      await apiFetch('/cal/tasks/' + encodeURIComponent(t.id), { method: 'DELETE' });
    } catch {
      if (status) status.textContent = '削除に失敗しました。もう一度お試しください。';
      this._showStatus('削除に失敗', true);
      if (modalApi.isOpen()) setBusy(false);
      return;
    }
    let undoFailed = false;
    try { this._pushUndo('ToDo削除'); }
    catch {
      undoFailed = true;
      this._showStatus('ToDoは削除しましたが、Undo履歴を記録できませんでした', true);
    }
    let reloadFailed = false;
    try { await reloadTasks(); }
    catch {
      reloadFailed = true;
      this._showStatus('ToDoは削除しましたが、表示を更新できませんでした。画面を再読み込みしてください', true);
    }
    if (!reloadFailed && !undoFailed) this._showStatus('削除しました');
    setBusy(false);
    modalApi.close('deleted');
  });
};
CalendarComponent.prototype._showTaskModal = CalendarComponent.prototype._showTaskDialogModal;

CalendarComponent.prototype._saveTask = async function(editId, overlay) {
  this._pushUndo(editId ? 'ToDo編集' : 'ToDo作成');
  const o = overlay;
  const data = {
    title: o.querySelector('.tk-title').value, status: o.querySelector('.tk-status').value,
    priority: o.querySelector('.tk-priority').value, due_date: o.querySelector('.tk-due').value,
    assignee: o.querySelector('.tk-assignee').value,
    estimated_hours: parseFloat(o.querySelector('.tk-est').value) || 0,
    actual_hours: parseFloat(o.querySelector('.tk-act').value) || 0,
    description: o.querySelector('.tk-desc').value, user: this._getUser(),
  };
  o.remove();
  try {
    if (editId) await apiPut('/cal/tasks/' + editId, data); else await apiPost('/cal/tasks', data);
    await this._loadTasks(); this._render(); this._renderTodayTasks();
    this._showStatus('ToDoを保存しました');
  } catch { this._showStatus('保存に失敗', true); }
};

CalendarComponent.prototype._deleteTask = async function(id) {
  if (typeof cfConfirm === 'function' && !await cfConfirm('このToDoを削除しますか？')) return false;
  this._pushUndo('ToDo削除');
  try {
    await apiFetch('/cal/tasks/' + id, { method: 'DELETE' });
    await this._loadTasks();
    this._render();
    this._renderTodayTasks();
    this._showStatus('削除しました');
    return true;
  } catch {
    return false;
  }
};

// スケジュールの予定・ToDo・制作タスク投影を同じ行モデルへ変換するガント表示。
CalendarComponent.prototype._ganttWindow = function() {
  const spanDays = this._ganttScale === 'month' ? 366 : this._ganttScale === 'week' ? 84 : 28;
  const start = new Date(this._date);
  start.setHours(0, 0, 0, 0);
  start.setDate(start.getDate() - Math.floor(spanDays / 4));
  const end = new Date(start);
  end.setDate(end.getDate() + spanDays);
  return { start, end, spanDays };
};

CalendarComponent.prototype._ganttEventEditReason = function(ev) {
  if (ev?._recurrence_instance) return '繰り返し予定は元の予定から編集してください';
  if (ev?.read_only || ev?.readonly) return '読み取り専用の予定です';
  if (['shift', 'shift-break', 'attendance'].includes(String(ev?.calendar_source || ''))) return '投影された予定は元データから編集してください';
  return '';
};

CalendarComponent.prototype._ganttDateValue = function(date, original, isEnd) {
  const value = new Date(date);
  if (_calIsDateOnlyValue(original)) {
    if (isEnd) value.setDate(value.getDate() - 1);
    return _calDateOnlyString(value);
  }
  return this._localDateTimeStr(value);
};

CalendarComponent.prototype._bindGanttEventDrag = function(bar, track, ev, range, win) {
  const reason = this._ganttEventEditReason(ev);
  if (reason) {
    bar.classList.add('is-readonly');
    bar.title = `${ev.title || ''}\n${reason}`;
    return;
  }
  const handles = bar.querySelectorAll('[data-gantt-resize]');
  const begin = (pointerEvent, mode) => {
    if (pointerEvent.button !== 0) return;
    pointerEvent.preventDefault();
    pointerEvent.stopPropagation();
    bar.setPointerCapture?.(pointerEvent.pointerId);
    const startX = pointerEvent.clientX;
    const originalStart = new Date(range.start);
    const originalEnd = new Date(range.end);
    const windowMs = win.end - win.start;
    const trackWidth = Math.max(1, track.getBoundingClientRect().width);
    let deltaDays = 0;
    const onMove = moveEvent => {
      deltaDays = Math.round(((moveEvent.clientX - startX) / trackWidth) * windowMs / 86400000);
      const deltaMs = deltaDays * 86400000;
      let nextStart = mode === 'end' ? originalStart : new Date(originalStart.getTime() + deltaMs);
      let nextEnd = mode === 'start' ? originalEnd : new Date(originalEnd.getTime() + deltaMs);
      if (nextEnd <= nextStart) {
        if (mode === 'start') nextStart = new Date(nextEnd.getTime() - 86400000);
        else nextEnd = new Date(nextStart.getTime() + 86400000);
      }
      const left = Math.max(0, Math.min(100, ((nextStart - win.start) / windowMs) * 100));
      const right = Math.max(left + 0.3, Math.min(100, ((nextEnd - win.start) / windowMs) * 100));
      bar.style.left = `${left}%`;
      bar.style.width = `${Math.max(0.6, right - left)}%`;
    };
    const onUp = async upEvent => {
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerup', onUp);
      document.removeEventListener('pointercancel', onUp);
      bar.releasePointerCapture?.(upEvent?.pointerId ?? pointerEvent.pointerId);
      if (!deltaDays) return;
      const deltaMs = deltaDays * 86400000;
      let nextStart = mode === 'end' ? originalStart : new Date(originalStart.getTime() + deltaMs);
      let nextEnd = mode === 'start' ? originalEnd : new Date(originalEnd.getTime() + deltaMs);
      if (nextEnd <= nextStart) {
        if (mode === 'start') nextStart = new Date(nextEnd.getTime() - 86400000);
        else nextEnd = new Date(nextStart.getTime() + 86400000);
      }
      const patch = {
        start: this._ganttDateValue(nextStart, ev.start, false),
        end: this._ganttDateValue(nextEnd, ev.end || ev.start, true),
      };
      if (this._eventIsUndoable(ev)) this._pushUndo(mode === 'move' ? 'ガントで予定を移動' : 'ガントで予定をリサイズ');
      try {
        await _calApplyEventTimePatch(this, ev, patch);
        await this._loadEvents();
        this._render();
      } catch (error) {
        this._showStatus?.('ガントの更新に失敗しました: ' + (error?.message || error), true);
        await this._loadEvents();
        this._render();
      }
    };
    document.addEventListener('pointermove', onMove);
    document.addEventListener('pointerup', onUp);
    document.addEventListener('pointercancel', onUp);
  };
  bar.addEventListener('pointerdown', event => {
    if (event.target.closest('[data-gantt-resize]')) return;
    begin(event, 'move');
  });
  handles.forEach(handle => handle.addEventListener('pointerdown', event => begin(event, handle.dataset.ganttResize)));
};

CalendarComponent.prototype._renderGantt = function() {
  const host = this._contentEl;
  const win = this._ganttWindow();
  const rangeMs = win.end - win.start;
  const calendarNames = new Map((this._calendars || []).map(calendar => [String(calendar.id), calendar.name || 'カレンダー']));
  const events = (this._events || []).filter(event => this._isCalVisible(event));
  const items = [];
  const unscheduled = [];
  events.forEach(event => {
    const range = _calEventRange(event);
    if (!range) { unscheduled.push({ kind: 'event', title: event.title || '無題', source: event }); return; }
    items.push({ kind: 'event', title: event.title || '無題', start: range.start, end: range.end, source: event,
      groupCalendar: calendarNames.get(String(event.calendar_id)) || 'カレンダー',
      groupSource: event.calendar_source === 'production-task'
        ? '制作タスク'
        : (event.calendar_source && event.calendar_source !== 'local' ? '外部・投影' : '予定') });
  });
  (this._tasks || []).forEach(task => {
    const due = task.due_date ? _calParseDateValue(task.due_date) : null;
    if (!due) { unscheduled.push({ kind: 'task', title: task.title || '無題ToDo', source: task }); return; }
    due.setHours(12, 0, 0, 0);
    items.push({ kind: 'task', title: task.title || '無題ToDo', start: due, end: due, source: task, groupCalendar: 'ToDo', groupSource: 'ToDo' });
  });
  const groupKey = item => this._ganttGroup === 'calendar' ? item.groupCalendar : this._ganttGroup === 'source' ? item.groupSource : '';
  items.sort((a, b) => groupKey(a).localeCompare(groupKey(b), 'ja') || a.start - b.start || a.title.localeCompare(b.title, 'ja'));

  host.innerHTML = `<div class="gb-cal-gantt-settings" data-e2e-id="schedule-gantt-settings">
    <span class="gb-cal-gantt-kind">${lucide('ganttChart', 14)} ガント</span>
    <label>目盛 <select class="gb-select gb-select-sm" data-gantt-setting="scale"><option value="day">日</option><option value="week">週</option><option value="month">月</option></select></label>
    <label>グループ <select class="gb-select gb-select-sm" data-gantt-setting="group"><option value="none">なし</option><option value="calendar">カレンダー</option><option value="source">種類</option></select></label>
    <span class="gb-cal-gantt-range">${esc(this._localDateStr(win.start))} – ${esc(this._localDateStr(new Date(win.end.getTime() - 86400000)))}</span>
  </div>`;
  const scaleSelect = host.querySelector('[data-gantt-setting="scale"]');
  const groupSelect = host.querySelector('[data-gantt-setting="group"]');
  scaleSelect.value = this._ganttScale;
  groupSelect.value = this._ganttGroup;
  scaleSelect.addEventListener('change', () => { this._ganttScale = scaleSelect.value; localStorage.setItem('gb:cal-gantt-scale', this._ganttScale); this._persistViewToTabState(this._view); this._render(); });
  groupSelect.addEventListener('change', () => { this._ganttGroup = groupSelect.value; localStorage.setItem('gb:cal-gantt-group', this._ganttGroup); this._persistViewToTabState(this._view); this._render(); });

  const chart = document.createElement('div');
  chart.className = 'gb-cal-gantt';
  chart.dataset.e2eId = 'schedule-gantt';
  // 日表示でも全日付をそのまま出すと、右サイドバーを開いた狭い作業幅で
  // ラベル同士が重なる。表示期間を最大10目盛ほどへ間引き、バーの座標と
  // 日単位の操作精度は変えずに見出しだけを読みやすく保つ。
  const tickDays = this._ganttScale === 'month'
    ? 30
    : this._ganttScale === 'week'
      ? 7
      : Math.max(1, Math.ceil(win.spanDays / 10));
  const header = document.createElement('div');
  header.className = 'gb-cal-gantt-row gb-cal-gantt-header';
  const headerLeft = document.createElement('div'); headerLeft.className = 'gb-cal-gantt-left'; headerLeft.textContent = '項目';
  const headerTrack = document.createElement('div'); headerTrack.className = 'gb-cal-gantt-track';
  for (let day = 0; day <= win.spanDays; day += tickDays) {
    const tickDate = new Date(win.start); tickDate.setDate(tickDate.getDate() + day);
    const tick = document.createElement('span'); tick.className = 'gb-cal-gantt-tick'; tick.style.left = `${(day / win.spanDays) * 100}%`;
    tick.textContent = this._ganttScale === 'month' ? `${tickDate.getFullYear()}/${tickDate.getMonth() + 1}` : `${tickDate.getMonth() + 1}/${tickDate.getDate()}`;
    headerTrack.appendChild(tick);
  }
  header.append(headerLeft, headerTrack); chart.appendChild(header);

  let previousGroup = null;
  items.forEach(item => {
    const group = groupKey(item);
    if (group && group !== previousGroup) {
      const groupRow = document.createElement('div'); groupRow.className = 'gb-cal-gantt-group'; groupRow.textContent = group; chart.appendChild(groupRow); previousGroup = group;
    }
    const row = document.createElement('div'); row.className = 'gb-cal-gantt-row';
    const left = document.createElement('button'); left.type = 'button'; left.className = 'gb-cal-gantt-left gb-cal-gantt-item-title'; left.textContent = item.title;
    left.addEventListener('click', () => item.kind === 'event' ? this._openEventInPanel(item.source.id) : this._showTaskModal(item.source.id));
    const track = document.createElement('div'); track.className = 'gb-cal-gantt-track';
    const todayPos = ((new Date().setHours(0,0,0,0) - win.start) / rangeMs) * 100;
    if (todayPos >= 0 && todayPos <= 100) { const todayLine = document.createElement('span'); todayLine.className = 'gb-cal-gantt-today'; todayLine.style.left = `${todayPos}%`; track.appendChild(todayLine); }
    const leftPct = Math.max(0, Math.min(100, ((item.start - win.start) / rangeMs) * 100));
    const endPct = Math.max(0, Math.min(100, ((item.end - win.start) / rangeMs) * 100));
    if (endPct >= 0 && leftPct <= 100 && item.end >= win.start && item.start <= win.end) {
      const bar = document.createElement('div');
      bar.className = item.kind === 'task' ? 'gb-cal-gantt-milestone' : 'gb-cal-gantt-bar';
      bar.style.left = `${leftPct}%`;
      if (item.kind === 'event') bar.style.width = `${Math.max(0.6, endPct - leftPct)}%`;
      bar.style.setProperty('--gantt-color', item.kind === 'task' ? 'var(--green)' : this._sanitizeEventColor(item.source.color));
      bar.title = `${item.title}\n${this._localDateStr(item.start)} – ${this._localDateStr(item.end)}`;
      if (item.kind === 'event') {
        bar.innerHTML = '<span data-gantt-resize="start" aria-hidden="true"></span><b></b><span data-gantt-resize="end" aria-hidden="true"></span>';
        this._bindGanttEventDrag(bar, track, item.source, { start: item.start, end: item.end }, win);
      }
      track.appendChild(bar);
    }
    row.append(left, track); chart.appendChild(row);
  });
  if (!items.length) { const empty = document.createElement('div'); empty.className = 'gb-cal-gantt-empty'; empty.textContent = '表示期間内の予定はありません'; chart.appendChild(empty); }
  host.appendChild(chart);
  if (unscheduled.length) {
    const section = document.createElement('div'); section.className = 'gb-cal-gantt-unscheduled';
    section.innerHTML = `<strong>未スケジュール (${unscheduled.length})</strong>`;
    unscheduled.forEach(item => { const button = document.createElement('button'); button.type = 'button'; button.textContent = item.title; button.addEventListener('click', () => item.kind === 'event' ? this._openEventInPanel(item.source.id) : this._showTaskModal(item.source.id)); section.appendChild(button); });
    host.appendChild(section);
  }
};

function _gbCalTransitionDialog(modalApi, reason, openNext) {
  if (!modalApi?.close?.(reason)) return false;
  const continueAfterRemoval = () => {
    if (modalApi.overlay?.isConnected) {
      setTimeout(continueAfterRemoval, 40);
      return;
    }
    openNext?.();
  };
  continueAfterRemoval();
  return true;
}

// === シフトモーダル ===
CalendarComponent.prototype._showShiftModal = function(user, date, editId) {
  const existing = editId ? this._shifts.find(s => s.id === editId) : null;
  const shiftType = existing?.type || 'work';
  const shiftDate = existing?.date || date || this._localDateStr(this._date);
  const startValue = shiftType === 'work' ? (existing?.start_time || '09:00') : '';
  const endValue = shiftType === 'work' ? (existing?.end_time || '18:00') : '';
  const shiftId = editId || this._newShiftId?.() || ('shift_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));
  const content = document.createElement('div');
  content.innerHTML = `<div id="sh-status" role="status" aria-live="polite"></div>
<div class="field"><label>ユーザー</label><input id="sh-user" class="sh-user" list="sh-user-candidates" value="${esc(user||existing?.user||this._getUser())}"><datalist id="sh-user-candidates"></datalist></div>
<div class="field"><label>日付</label><input id="sh-date" class="sh-date" type="date" value="${shiftDate}"></div>
<div style="display:flex;gap:8px;"><div class="field" style="flex:1;"><label>開始</label><input id="sh-start" class="sh-start" type="time" value="${startValue}"></div>
<div class="field" style="flex:1;"><label>終了</label><input id="sh-end" class="sh-end" type="time" value="${endValue}"></div></div>
<div class="field"><label>種別</label><select id="sh-type" class="sh-type"><option value="work" ${shiftType==='work'?'selected':''}>勤務</option><option value="off" ${shiftType==='off'?'selected':''}>休み</option><option value="holiday" ${shiftType==='holiday'?'selected':''}>祝日</option></select></div>
<div class="field"><label>メモ</label><textarea id="sh-note" class="sh-note" rows="3">${esc(existing?.note||'')}</textarea></div>`;
  const cancelButton = document.createElement('button');
  cancelButton.type = 'button'; cancelButton.id = 'sh-cancel'; cancelButton.className = 'sh-cancel gb-btn gb-btn-sm'; cancelButton.textContent = 'キャンセル';
  const saveButton = document.createElement('button');
  saveButton.type = 'button'; saveButton.id = 'sh-save'; saveButton.className = 'sh-save gb-btn gb-btn-sm gb-btn-primary primary'; saveButton.textContent = '保存';
  const deleteButton = existing ? document.createElement('button') : null;
  const historyButton = existing ? document.createElement('button') : null;
  if (deleteButton) {
    deleteButton.type = 'button'; deleteButton.id = 'sh-delete'; deleteButton.className = 'sh-delete gb-btn gb-btn-sm gb-btn-danger danger'; deleteButton.textContent = '削除';
  }
  if (historyButton) {
    historyButton.type = 'button'; historyButton.id = 'sh-history'; historyButton.className = 'sh-history gb-btn gb-btn-sm'; historyButton.textContent = '版を見る';
  }
  let busy = false, deleteConfirmPending = false;
  const modalApi = window.GBUI.createModal({
    id: 'calendar-tool-shift', title: existing ? 'シフト編集' : '新規シフト', body: [...content.childNodes],
    footer: [deleteButton, historyButton, cancelButton, saveButton].filter(Boolean), variant: 'standard', geometryKey: 'calendar-tool-shift',
    minWidth: '0', initialFocus: '#sh-user', closeLabel: 'シフト編集を閉じる', closeOnEsc: true, closeOnOverlay: true,
    onBeforeClose: () => !busy,
  });
  const o = modalApi.overlay, panel = modalApi.modal, status = panel.querySelector('#sh-status');
  o.classList.add('gb-cal-modal-overlay'); o.dataset.e2eId = 'calendar-tool-shift-overlay'; o._calendarClose = modalApi.close;
  panel.classList.add('gb-cal-modal'); panel.dataset.e2eId = 'calendar-tool-shift-dialog'; panel.style.cssText = _gbCalModalSizeStyle(350, 'overflow:hidden;');
  const setBusy = (next) => {
    busy = next; panel.setAttribute('aria-busy', next ? 'true' : 'false');
    [saveButton, deleteButton, historyButton].filter(Boolean).forEach(button => { button.disabled = next; });
  };
  modalApi.open();
  this._fillShiftUserCandidates?.(panel);
  const syncTimeState = () => {
    const isWork = o.querySelector('.sh-type')?.value === 'work';
    const start = o.querySelector('.sh-start');
    const end = o.querySelector('.sh-end');
    if (!start || !end) return;
    start.disabled = end.disabled = !isWork;
    start.style.opacity = end.style.opacity = isWork ? '1' : '0.45';
    if (isWork) {
      if (!start.value) start.value = '09:00';
      if (!end.value) end.value = '18:00';
    } else {
      start.value = '';
      end.value = '';
    }
  };
  panel.querySelector('.sh-type')?.addEventListener('change', syncTimeState);
  syncTimeState();
  saveButton.addEventListener('click', async () => {
    if (busy) return;
    if (!panel.querySelector('.sh-date')?.value) {
      await this._saveShift(editId, panel, shiftId);
      status.textContent = '日付を入力してください。';
      return;
    }
    setBusy(true); status.textContent = '保存中...';
    const saved = await this._saveShift(editId, panel, shiftId);
    if (saved) { setBusy(false); modalApi.close('saved'); return; }
    if (this._shiftMutationStateUnknown) {
      setBusy(false);
      status.textContent = '保存結果を確認できません。カレンダーを再読み込みしてください。';
      return;
    }
    status.textContent = '保存に失敗しました。入力内容を保ったまま再試行できます。';
    if (modalApi.isOpen()) setBusy(false);
  });
  cancelButton.addEventListener('click', () => modalApi.close('cancel'));
  historyButton?.addEventListener('click', event => {
    window.MeldexCalendarItemHistory?.open('shift', existing.id, {
      returnFocus: event.currentTarget,
      onRestored: async () => {
        await Promise.all([this._loadShifts(), this._loadEvents(), this._loadCalendars()]);
        this._renderCalendarList?.();
        this._render();
        modalApi.close('restored');
        this._showStatus('シフトを復元しました');
      },
    }).catch(error => {
      status.textContent = error?.message || 'シフトの版を開けませんでした。';
    });
  });
  deleteButton?.addEventListener('click', async () => {
    if (busy || deleteConfirmPending) return;
    deleteConfirmPending = true;
    let confirmed = false;
    try { confirmed = typeof cfConfirm !== 'function' || await cfConfirm('このシフトを削除しますか？'); }
    catch {} finally { deleteConfirmPending = false; }
    if (!confirmed) return;
    setBusy(true); status.textContent = '削除中...';
    const deleted = await this._deleteShift(existing.id, { skipConfirm: true });
    if (deleted) { setBusy(false); modalApi.close('deleted'); return; }
    if (this._shiftMutationStateUnknown) {
      setBusy(false);
      status.textContent = '削除結果を確認できません。カレンダーを再読み込みしてください。';
      return;
    }
    status.textContent = '削除に失敗しました。もう一度お試しください。';
    if (modalApi.isOpen()) setBusy(false);
  });
};

// シフトモーダルの「ユーザー」欄へ、正本スタッフ管理シート＋ワークスペースメンバーの
// 候補を <datalist> サジェストとして流し込む（表記ゆれ対策）。あくまで補助であり、
// 入力欄自体は free-text のまま（正本に無い未連携の人物も従来どおり直接入力できる）。
CalendarComponent.prototype._fillShiftUserCandidates = async function(o) {
  try {
    const datalist = o.querySelector('#sh-user-candidates');
    if (!datalist || typeof window.MeldexUserPicker?.getCandidates !== 'function') return;
    const candidates = await window.MeldexUserPicker.getCandidates();
    if (!datalist.isConnected) return; // 取得中にモーダルが閉じられていたら反映しない
    datalist.textContent = '';
    (candidates || []).forEach((c) => {
      const name = String(c?.name || '').trim();
      if (!name) return;
      const opt = document.createElement('option');
      opt.value = name;
      datalist.appendChild(opt);
    });
  } catch (e) {
    console.warn('シフトのユーザー候補取得に失敗しました', e);
  }
};

CalendarComponent.prototype._saveShift = async function(editId, o, fixedShiftId) {
  if (this._shiftMutationStateUnknown) {
    this._showStatus('前回のシフト保存結果を確認できません。カレンダーを再読み込みしてください', true);
    return false;
  }
  const type = o.querySelector('.sh-type').value;
  const date = o.querySelector('.sh-date').value;
  if (!date) {
    this._showStatus('日付を入力してください', true);
    o.querySelector('.sh-date')?.focus();
    return false;
  }
  const data = {
    user: o.querySelector('.sh-user').value.trim() || this._getUser(),
    date,
    start_time: type === 'work' ? (o.querySelector('.sh-start').value || '09:00') : '',
    end_time: type === 'work' ? (o.querySelector('.sh-end').value || '18:00') : '',
    type,
    note: o.querySelector('.sh-note').value,
  };
  const shiftId = editId || fixedShiftId || this._newShiftId?.() || ('shift_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));
  const snapshot = this._shiftMutationSnapshot?.();
  if (typeof this._upsertShiftOptimistic === 'function') {
    this._upsertShiftOptimistic({ id: shiftId, ...data, _optimistic: true }, { select: true });
    this._renderCalendarList?.();
    this._render();
  }
  let acknowledged = false;
  try {
    if (editId) await apiPut('/cal/shifts/' + encodeURIComponent(editId), data);
    else await apiPost('/cal/shifts', { id: shiftId, ...data });
    acknowledged = true;
    if (typeof this._upsertShiftOptimistic === 'function') {
      this._upsertShiftOptimistic({ id: shiftId, ...data, _optimistic: false }, { select: true });
      this._renderCalendarList?.();
      this._render();
      await this._refreshShiftStateAfterMutation?.();
    } else {
      await Promise.all([this._loadShifts(), this._loadEvents(), this._loadCalendars()]);
      this._renderCalendarList?.();
      this._render();
    }
    this._showStatus('シフトを保存しました');
    return true;
  } catch (error) {
    if (acknowledged) {
      console.error('保存済みシフトの再読込に失敗しました', error);
      this._showStatus('シフトは保存されましたが、再読み込みに失敗しました', true);
      return true;
    }
    const outcome = await this._reconcileShiftMutationAfterError?.(shiftId, editId ? 'update' : 'create', data);
    if (outcome === 'applied') {
      this._showStatus('シフトを保存しました');
      return true;
    }
    if (outcome === 'unknown') {
      this._showStatus('シフト保存結果を確認できません。カレンダーを再読み込みしてください', true);
      return false;
    }
    if (snapshot && typeof this._restoreShiftMutationSnapshot === 'function') this._restoreShiftMutationSnapshot(snapshot);
    this._showStatus('保存に失敗', true);
    return false;
  }
};

CalendarComponent.prototype._deleteShift = async function(id, options = {}) {
  if (this._shiftMutationStateUnknown) {
    this._showStatus('前回のシフト保存結果を確認できません。カレンダーを再読み込みしてください', true);
    return false;
  }
  if (!options.skipConfirm && typeof cfConfirm === 'function' && !await cfConfirm('このシフトを削除しますか？')) return false;
  const snapshot = this._shiftMutationSnapshot?.();
  if (typeof this._removeShiftOptimistic === 'function') {
    this._removeShiftOptimistic(id);
    this._renderCalendarList?.();
    this._render();
    let acknowledged = false;
    try {
      await apiFetch('/cal/shifts/' + encodeURIComponent(id), { method: 'DELETE' });
      acknowledged = true;
      await this._refreshShiftStateAfterMutation?.();
      this._showStatus('削除しました');
      return true;
    } catch (error) {
      if (acknowledged) {
        console.error('削除済みシフトの再読込に失敗しました', error);
        this._showStatus('シフトは削除されましたが、再読み込みに失敗しました', true);
        return true;
      }
      const outcome = await this._reconcileShiftMutationAfterError?.(id, 'delete');
      if (outcome === 'applied') {
        this._showStatus('削除しました');
        return true;
      }
      if (outcome === 'unknown') {
        this._showStatus('シフト削除結果を確認できません。カレンダーを再読み込みしてください', true);
        return false;
      }
      if (snapshot && typeof this._restoreShiftMutationSnapshot === 'function') this._restoreShiftMutationSnapshot(snapshot);
      this._showStatus('削除に失敗', true);
      return false;
    }
  }
  try {
    await apiFetch('/cal/shifts/' + encodeURIComponent(id), { method: 'DELETE' });
    await Promise.all([this._loadShifts(), this._loadEvents(), this._loadCalendars()]);
    this._renderCalendarList?.();
    this._render();
    this._showStatus('削除しました');
    return true;
  } catch {
    return false;
  }
};

// === テンプレートモーダル ===
CalendarComponent.prototype._showScheduleTemplateModal = async function(returnFocus) {
  const owner = returnFocus?.focus ? returnFocus : document.activeElement;
  let allTemplates = [], templates = [];
  const dl = ['日','月','火','水','木','金','土'];
  const addMin = (ts, min) => {
    const match = /^(\d{1,2}):(\d{2})$/.exec(String(ts || ''));
    if (!match) return '--:--';
    const duration = parseInt(min, 10);
    if (!Number.isFinite(duration)) return '--:--';
    const t = parseInt(match[1], 10) * 60 + parseInt(match[2], 10) + duration;
    return String(Math.floor(((t % 1440) + 1440) % 1440 / 60)).padStart(2,'0')+':'+String(((t % 60) + 60) % 60).padStart(2,'0');
  };
  const content = document.createElement('div');
  content.innerHTML = '<div id="tmpl-status" role="status" aria-live="polite"></div><div id="tmpl-list" class="tmpl-list"></div>';
  const createButton = document.createElement('button');
  createButton.type = 'button'; createButton.id = 'tmpl-create'; createButton.className = 'tmpl-create gb-btn gb-btn-sm'; createButton.textContent = '新規テンプレート';
  const closeButton = document.createElement('button');
  closeButton.type = 'button'; closeButton.id = 'tmpl-close'; closeButton.className = 'tmpl-close gb-btn gb-btn-sm'; closeButton.textContent = '閉じる';
  let busy = false, deleteConfirmPending = false;
  const modalApi = window.GBUI.createModal({
    id: 'calendar-tool-template-list', title: '週間テンプレート', body: [...content.childNodes], footer: [createButton, closeButton],
    variant: 'standard', geometryKey: 'calendar-tool-template-list', minWidth: '0', initialFocus: '#tmpl-create', returnFocus: owner,
    closeLabel: '週間テンプレートを閉じる', closeOnEsc: true, closeOnOverlay: true, onBeforeClose: () => !busy,
  });
  const o = modalApi.overlay, panel = modalApi.modal, list = panel.querySelector('#tmpl-list'), status = panel.querySelector('#tmpl-status');
  o.classList.add('gb-cal-modal-overlay'); o.dataset.e2eId = 'calendar-tool-template-list-overlay'; o._calendarClose = modalApi.close;
  panel.classList.add('gb-cal-modal'); panel.dataset.e2eId = 'calendar-tool-template-list-dialog'; panel.style.cssText = _gbCalModalSizeStyle(600, 'overflow:hidden;');
  const setBusy = (next) => {
    busy = next; panel.setAttribute('aria-busy', next ? 'true' : 'false');
    panel.querySelectorAll('button').forEach(button => { if (button !== closeButton) button.disabled = next; });
  };
  let firstLoad = true;
  const render = () => {
    if (!templates.length) {
      list.innerHTML = '<div style="color:var(--cal-muted-fg, var(--fg2));font-size:12px;padding:8px;">テンプレートがありません</div>';
      return;
    }
    list.innerHTML = templates.map(t => {
      const entries = (t.entries || []).map(e => `<div style="font-size:11px;color:var(--cal-muted-fg, var(--fg2));padding:1px 0;">${esc(dl[e.dayOfWeek] || '')} ${esc(e.startTime || '')}〜${esc(addMin(e.startTime,e.duration))} ${esc(e.title || '')}</div>`).join('');
      return `<div style="border:1px solid var(--cal-grid-line, var(--border));background:var(--cal-panel-bg, transparent);border-radius:4px;padding:8px;margin-bottom:8px;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;"><strong>${esc(t.name)}</strong><div><button type="button" class="tmpl-edit gb-btn gb-btn-sm" data-action="edit" data-tid="${esc(t.id)}">編集</button><button type="button" class="tmpl-del gb-btn gb-btn-sm" data-action="delete" data-tid="${esc(t.id)}" style="color:var(--red);">削除</button><button type="button" class="tmpl-gen gb-btn gb-btn-sm gb-btn-primary primary" data-action="generate" data-tid="${esc(t.id)}">一括生成</button></div></div>${entries}</div>`;
    }).join('');
  };
  const loadTemplates = async () => {
    createButton.disabled = true; status.textContent = '読み込み中...';
    try {
      allTemplates = await apiFetch('/cal/schedule-templates?user=' + encodeURIComponent(this._getUser()));
      templates = (allTemplates || []).filter(template => !(typeof this._isShiftScheduleTemplate === 'function' && this._isShiftScheduleTemplate(template)));
      status.textContent = ''; render();
    } catch {
      status.innerHTML = 'テンプレートを読み込めませんでした。<button id="tmpl-retry" type="button">再試行</button>';
      status.querySelector('#tmpl-retry')?.addEventListener('click', loadTemplates);
    } finally {
      createButton.disabled = false;
      if (firstLoad && modalApi.isOpen() && (document.activeElement === panel || !panel.contains(document.activeElement))) {
        try { createButton.focus({ preventScroll: true }); } catch { createButton.focus(); }
      }
      firstLoad = false;
    }
  };
  modalApi.open();
  closeButton.addEventListener('click', () => modalApi.close('close-button'));
  createButton.addEventListener('click', async () => {
    if (busy) return;
    setBusy(true); status.textContent = '作成中...';
    try {
      const id = await this._createTemplate(allTemplates);
      setBusy(false); _gbCalTransitionDialog(modalApi, 'created', () => this._editTemplate(id, owner));
    } catch {
      status.textContent = '作成に失敗しました。もう一度お試しください。';
      if (modalApi.isOpen()) setBusy(false);
    }
  });
  list.addEventListener('click', async event => {
    const button = event.target.closest('button[data-action]');
    if (!button || busy) return;
    const action = button.dataset.action, tid = button.dataset.tid;
    if (action === 'edit') { _gbCalTransitionDialog(modalApi, 'edit', () => this._editTemplate(tid, owner)); return; }
    if (action === 'delete') {
      if (deleteConfirmPending) return;
      deleteConfirmPending = true;
      let confirmed = false;
      try { confirmed = typeof cfConfirm !== 'function' || await cfConfirm('このテンプレートを削除しますか？'); }
      catch {} finally { deleteConfirmPending = false; }
      if (!confirmed) return;
      setBusy(true); status.textContent = '削除中...';
      try {
        await apiFetch('/cal/schedule-templates/' + encodeURIComponent(tid), { method: 'DELETE' });
        templates = templates.filter(template => String(template.id) !== String(tid)); status.textContent = ''; render();
      } catch { status.textContent = '削除に失敗しました。もう一度お試しください。'; }
      finally { if (modalApi.isOpen()) setBusy(false); }
      return;
    }
    if (action === 'generate') {
      setBusy(true);
      try {
        const generated = await this._generateFromTemplate(tid, null);
        if (generated) { setBusy(false); modalApi.close('generated'); }
      }
      finally { if (modalApi.isOpen()) setBusy(false); }
    }
  });
  await loadTemplates();
};

CalendarComponent.prototype._createTemplate = async function(knownTemplates) {
  const templates = Array.isArray(knownTemplates) ? knownTemplates : await apiFetch('/cal/schedule-templates?user=' + encodeURIComponent(this._getUser()));
  let idx = 1, name = '無題'; const names = templates.map(t => t.name);
  while (names.includes(name)) { idx++; name = '無題' + idx; }
  const res = await apiPost('/cal/schedule-templates', { name, entries: [], user: this._getUser() });
  return res.id;
};

CalendarComponent.prototype._editTemplate = async function(tid, returnFocus) {
  const owner = returnFocus?.focus ? returnFocus : document.activeElement;
  let templates = [];
  try { templates = await apiFetch('/cal/schedule-templates?user=' + encodeURIComponent(this._getUser())); }
  catch { this._showStatus('テンプレートの読み込みに失敗しました', true); this._showScheduleTemplateModal(owner); return; }
  const t = templates.find(x => String(x.id) === String(tid));
  if (!t) { this._showStatus('テンプレートが見つかりません', true); this._showScheduleTemplateModal(owner); return; }
  const dl = ['日','月','火','水','木','金','土'];
  const entryRow = (e) => `<div class="tmpl-entry" style="display:flex;gap:4px;align-items:center;margin-bottom:4px;font-size:12px;">
    <select data-field="dayOfWeek" class="gb-select gb-select-sm">${dl.map((d,i)=>`<option value="${i}" ${(e?.dayOfWeek??0)===i?'selected':''}>${d}</option>`).join('')}</select>
    <input type="time" data-field="startTime" value="${esc(e?.startTime||'09:00')}" style="padding:2px;background:var(--cal-input-bg, var(--bg));color:var(--cal-input-fg, var(--fg));border:1px solid var(--cal-control-border, var(--border));border-radius:3px;">
    <input type="number" data-field="duration" value="${esc(e?.duration||60)}" min="5" step="5" style="width:60px;padding:2px;background:var(--cal-input-bg, var(--bg));color:var(--cal-input-fg, var(--fg));border:1px solid var(--cal-control-border, var(--border));border-radius:3px;" title="分"><span style="color:var(--cal-muted-fg, var(--fg2));">分</span>
    <input type="text" data-field="title" value="${esc(e?.title||'')}" placeholder="タイトル" style="flex:1;padding:2px 4px;background:var(--cal-input-bg, var(--bg));color:var(--cal-input-fg, var(--fg));border:1px solid var(--cal-control-border, var(--border));border-radius:3px;">
    <button type="button" class="tmpl-entry-del" aria-label="エントリを削除" style="background:none;border:none;color:var(--red);cursor:pointer;display:flex;align-items:center;">${lucide('x', 14)}</button></div>`;
  let entriesHtml = (t.entries||[]).map(e => entryRow(e)).join('');
  const content = document.createElement('div');
  content.innerHTML = `<div id="tmpl-edit-status" role="status" aria-live="polite"></div>
    <div class="field"><label>名前</label><input id="tmpl-name" class="tmpl-name" type="text" value="${esc(t.name)}"></div>
    <div style="font-size:12px;color:var(--cal-muted-fg, var(--fg2));margin-bottom:4px;">エントリ（1週間分）</div>
    <div id="tmpl-entries" class="tmpl-entries">${entriesHtml}</div>
    <button id="tmpl-add-entry" type="button" class="tmpl-add-entry gb-btn gb-btn-sm">+ エントリ追加</button>`;
  const cancelButton = document.createElement('button');
  cancelButton.type = 'button'; cancelButton.id = 'tmpl-edit-cancel'; cancelButton.className = 'tmpl-edit-cancel gb-btn gb-btn-sm'; cancelButton.textContent = 'キャンセル';
  const saveButton = document.createElement('button');
  saveButton.type = 'button'; saveButton.id = 'tmpl-edit-save'; saveButton.className = 'tmpl-edit-save gb-btn gb-btn-sm gb-btn-primary primary'; saveButton.textContent = '保存';
  let busy = false;
  const modalApi = window.GBUI.createModal({
    id: 'calendar-tool-template-edit', title: `テンプレート編集: ${t.name}`, body: [...content.childNodes], footer: [cancelButton, saveButton],
    variant: 'standard', geometryKey: 'calendar-tool-template-edit', minWidth: '0', initialFocus: '#tmpl-name', returnFocus: owner,
    closeLabel: 'テンプレート編集を閉じる', closeOnEsc: true, closeOnOverlay: true, onBeforeClose: () => !busy,
  });
  const o = modalApi.overlay, panel = modalApi.modal, status = panel.querySelector('#tmpl-edit-status');
  o.classList.add('gb-cal-modal-overlay'); o.dataset.e2eId = 'calendar-tool-template-edit-overlay'; o._calendarClose = modalApi.close;
  panel.classList.add('gb-cal-modal'); panel.dataset.e2eId = 'calendar-tool-template-edit-dialog'; panel.style.cssText = _gbCalModalSizeStyle(550, 'overflow:hidden;');
  const setBusy = (next) => {
    busy = next; panel.setAttribute('aria-busy', next ? 'true' : 'false');
    [saveButton, panel.querySelector('#tmpl-add-entry')].forEach(button => { if (button) button.disabled = next; });
  };
  modalApi.open();
  panel.querySelector('#tmpl-add-entry').addEventListener('click', () => {
    panel.querySelector('#tmpl-entries').insertAdjacentHTML('beforeend', entryRow({}));
  });
  panel.querySelector('#tmpl-entries').addEventListener('click', event => {
    const button = event.target.closest('.tmpl-entry-del');
    if (button && !busy) button.closest('.tmpl-entry')?.remove();
  });
  cancelButton.addEventListener('click', () => {
    _gbCalTransitionDialog(modalApi, 'cancel', () => this._showScheduleTemplateModal(owner));
  });
  saveButton.addEventListener('click', async () => {
    if (busy) return;
    const name = panel.querySelector('.tmpl-name').value.trim() || '無題';
    const entries = [];
    panel.querySelectorAll('.tmpl-entries .tmpl-entry').forEach(row => {
      entries.push({ dayOfWeek: parseInt(row.querySelector('[data-field="dayOfWeek"]').value), startTime: row.querySelector('[data-field="startTime"]').value, duration: parseInt(row.querySelector('[data-field="duration"]').value) || 60, title: row.querySelector('[data-field="title"]').value.trim() });
    });
    setBusy(true); status.textContent = '保存中...';
    try {
      await apiPut('/cal/schedule-templates/' + encodeURIComponent(tid), { name, entries });
      this._showStatus('テンプレートを保存しました'); setBusy(false);
      _gbCalTransitionDialog(modalApi, 'saved', () => this._showScheduleTemplateModal(owner));
    } catch {
      status.textContent = '保存に失敗しました。入力内容を保ったまま再試行できます。'; this._showStatus('保存に失敗', true);
      if (modalApi.isOpen()) setBusy(false);
    }
  });
};

CalendarComponent.prototype._generateFromTemplate = async function(tid, overlay) {
  const templates = await apiFetch('/cal/schedule-templates?user=' + encodeURIComponent(this._getUser()));
  const t = templates.find(x => x.id === tid);
  if (!t || !t.entries?.length) { this._showStatus('エントリがありません', true); return false; }
  // cfPromptで週数を取得
  const weeksStr = await cfPrompt('何週間分生成しますか？', '4');
  const weeks = parseInt(weeksStr) || 0;
  if (weeks <= 0) return false;
  const entries = (t.entries || []).map(entry => {
    const match = /^(\d{1,2}):(\d{2})$/.exec(String(entry.startTime || ''));
    const dayOfWeek = parseInt(entry.dayOfWeek, 10);
    const duration = Math.max(5, parseInt(entry.duration, 10) || 60);
    if (!match || dayOfWeek < 0 || dayOfWeek > 6) return null;
    return {
      dayOfWeek,
      hour: parseInt(match[1], 10),
      minute: parseInt(match[2], 10),
      duration,
      title: entry.title || '無題',
    };
  });
  if (entries.some(entry => !entry)) {
    this._showStatus('テンプレートの時刻を確認してください', true);
    return false;
  }
  const startDate = new Date(this._date);
  startDate.setDate(startDate.getDate() - ((startDate.getDay() - this._startDay + 7) % 7));
  const calendarId = this._calendarIdForNewEvent();
  const createdIds = [];
  let count = 0;
  this._pushUndo('テンプレート一括生成');
  try {
    for (let w = 0; w < weeks; w++) {
      for (const entry of entries) {
        const d = new Date(startDate);
        d.setDate(d.getDate() + w * 7 + ((entry.dayOfWeek - this._startDay + 7) % 7));
        d.setHours(entry.hour, entry.minute, 0, 0);
        const endD = new Date(d.getTime() + entry.duration * 60000);
        const res = await apiPost('/cal/events', {
          title: entry.title,
          start: this._localDateTimeStr(d),
          end: this._localDateTimeStr(endD),
          calendar_id: calendarId,
          user: this._getUser(),
        });
        if (res?.id) createdIds.push(res.id);
        count++;
      }
    }
  } catch (e) {
    await Promise.all(createdIds.map(id => apiFetch('/cal/events/' + id, { method: 'DELETE' }).catch(() => {})));
    await this._loadEvents();
    this._render();
    this._showStatus('一括生成に失敗しました。作成済み分は取り消しました', true);
    return false;
  }
  if (typeof overlay?._calendarClose === 'function') overlay._calendarClose('generated');
  else overlay?.remove();
  await this._loadEvents(); this._render();
  this._showStatus(`${count}件のイベントを生成しました`);
  return true;
};

;

/* === gb-tool-calendar-todo-view.js === */
;
/* ==============================
   gb-tool-calendar-todo-view.js: ToDoのカレンダー終日帯表示
   gb-tool-calendar-views.js のプロトタイプ拡張
   ============================== */
(function() {
  if (typeof CalendarComponent === 'undefined') return;

  const STATUS_ORDER = { backlog: 0, todo: 1, in_progress: 2, review: 3, done: 4 };
  const PRIORITY_ORDER = { urgent: 0, high: 1, medium: 2, low: 3 };

  function _todoEsc(value) {
    return MeldexEscape.html(value);
  }

  function _todoIcon(name, size) {
    return typeof lucide === 'function' ? lucide(name, size || 10) : '';
  }

  function _todoDueDate(task) {
    return String(task?.due_date || '').trim().slice(0, 10);
  }

  function _todoPriorityStyle(task) {
    const priority = String(task?.priority || 'medium');
    if (priority === 'urgent') return { bg: 'var(--cal-task-priority-urgent-bg, var(--red))', fg: 'var(--cal-event-fg, var(--ui-fg-strong))' };
    if (priority === 'high') return { bg: 'var(--cal-task-priority-high-bg, var(--orange))', fg: 'var(--cal-event-fg, var(--ui-fg-strong))' };
    if (priority === 'medium') return { bg: 'var(--cal-task-priority-medium-bg, var(--blue))', fg: 'var(--cal-event-fg, var(--ui-fg-strong))' };
    return { bg: 'var(--cal-control-bg, var(--bg3))', fg: 'var(--cal-task-fg, var(--fg))' };
  }

  function _todoForDay(component, dateStr) {
    return (component?._tasks || [])
      .filter(task => task && !task.parent_id && _todoDueDate(task) === dateStr)
      .sort((a, b) =>
        ((STATUS_ORDER[a.status] ?? 99) - (STATUS_ORDER[b.status] ?? 99)) ||
        ((PRIORITY_ORDER[a.priority] ?? 99) - (PRIORITY_ORDER[b.priority] ?? 99)) ||
        String(a.title || '').localeCompare(String(b.title || ''))
      );
  }

  function _todoChipHtml(component, task) {
    const style = _todoPriorityStyle(task);
    const title = task?.title || '無題';
    return `<div class="gb-cal-day-event gb-cal-all-day-task" data-task-id="${_todoEsc(task?.id || '')}" style="background:${style.bg};color:${style.fg};" title="${_todoEsc(title)}">` +
      `<span class="gb-cal-event-source-icon">${_todoIcon('checkSquare', 10)}</span><span class="gb-cal-event-title">${_todoEsc(title)}</span></div>`;
  }

  CalendarComponent.prototype._todoForAllDayStrip = function(dateStr) {
    return _todoForDay(this, dateStr);
  };

  CalendarComponent.prototype._todoAllDayChipHtml = function(task) {
    return _todoChipHtml(this, task);
  };

  CalendarComponent.prototype._allDayStripHtml = function(dateStrs) {
    const cols = Array.isArray(dateStrs) && dateStrs.length ? dateStrs : [];
    if (!cols.length) return '';
    let html = `<div class="gb-cal-all-day-strip" style="display:grid;grid-template-columns:60px repeat(${cols.length}, minmax(0,1fr));border-bottom:1px solid var(--cal-grid-line, var(--border));">`;
    html += '<div class="gb-cal-week-time" style="padding-top:6px;">終日</div>';
    cols.forEach(dateStr => {
      html += `<div class="gb-cal-all-day-cell" data-date="${dateStr}" style="min-height:30px;padding:2px;border-left:1px solid var(--cal-grid-line, var(--border));">`;
      this._allDayEventsForDay(dateStr).forEach(ev => {
        const avatars = typeof this._eventUserAvatarsHtml === 'function' ? this._eventUserAvatarsHtml(ev, 14) : '';
        html += `<div class="gb-cal-day-event gb-cal-all-day-event${this._eventSourceClass(ev)}" data-event-id="${_todoEsc(ev.id)}" data-calendar-id="${_todoEsc(ev.calendar_id || '_calendar')}" draggable="true" style="background:${this._sanitizeEventColor(ev.color)};color:var(--cal-event-fg, #fff);position:relative;margin:1px 0;" title="${_todoEsc(ev.title || '')}">${this._eventTitleContentHtml(ev)}${this._eventCardMenuHtml()}${avatars}</div>`;
      });
      this._todoForAllDayStrip(dateStr).forEach(task => {
        if (task?.id) html += this._todoAllDayChipHtml(task);
      });
      html += '</div>';
    });
    return html + '</div>';
  };

  const _baseBindAllDayStripEvents = CalendarComponent.prototype._bindAllDayStripEvents;
  CalendarComponent.prototype._bindAllDayStripEvents = function(rootEl) {
    if (typeof _baseBindAllDayStripEvents === 'function') _baseBindAllDayStripEvents.call(this, rootEl);
    rootEl.querySelectorAll('.gb-cal-all-day-task[data-task-id]').forEach(taskEl => {
      taskEl.addEventListener('click', event => {
        event.stopPropagation();
        this._showTaskModal(taskEl.dataset.taskId);
      });
    });
  };
})();

;

/* === gb-tool-calendar-clock-view.js === */
;
/* ==============================
   gb-tool-calendar-clock-view.js: analog clock calendar views
   ============================== */

(() => {
  if (typeof CalendarComponent === 'undefined') return;

  const SIZE = 400;
  const CX = SIZE / 2;
  const CY = SIZE / 2;
  const OUTER_R = 178;
  const EVENT_OUTER_R = 154;
  const EVENT_INNER_R = 74;
  const CLOCK_EVENT_EDGE_MINUTES = 15;
  const CLOCK_DEFAULT_EVENT_MINUTES = 60;
  const CLOCK_DRAG_PX_THRESHOLD = 4;
  const CLOCK_EVENT_CARD_MIN_WIDTH = 8;
  const CLOCK_EVENT_CARD_LANE_OFFSET = 6;
  const CLOCK_EVENT_CHECK_SIZE = 8;

  function _clockEsc(value) {
    return MeldexEscape.html(value);
  }

  function _clockDate(value) {
    if (!value) return null;
    const raw = String(value);
    // 日付のみの値はUTCではなくローカル日付として解釈する（月/週ビューの解釈と揃える）
    const d = /^\d{4}-\d{2}-\d{2}$/.test(raw) ? new Date(raw + 'T00:00:00') : new Date(raw);
    return d && !Number.isNaN(d.getTime()) ? d : null;
  }

  function _clockPoint(angleDeg, radius) {
    const rad = (angleDeg - 90) * Math.PI / 180;
    return { x: CX + radius * Math.cos(rad), y: CY + radius * Math.sin(rad) };
  }

  function _clockSvgRelativePoint(svg, clientX, clientY) {
    const rect = svg.getBoundingClientRect();
    const x = ((clientX - rect.left) / Math.max(1, rect.width)) * SIZE - CX;
    const y = ((clientY - rect.top) / Math.max(1, rect.height)) * SIZE - CY;
    return { x, y, radius: Math.sqrt(x * x + y * y) };
  }

  function _clockDonutPath(startAngle, endAngle, outerR, innerR) {
    const span = Math.max(0, endAngle - startAngle);
    if (span >= 359.5) {
      return [
        `M ${CX} ${CY - outerR}`,
        `A ${outerR} ${outerR} 0 1 1 ${CX} ${CY + outerR}`,
        `A ${outerR} ${outerR} 0 1 1 ${CX} ${CY - outerR}`,
        `M ${CX} ${CY - innerR}`,
        `A ${innerR} ${innerR} 0 1 0 ${CX} ${CY + innerR}`,
        `A ${innerR} ${innerR} 0 1 0 ${CX} ${CY - innerR}`,
      ].join(' ');
    }
    const large = span > 180 ? 1 : 0;
    const so = _clockPoint(startAngle, outerR);
    const eo = _clockPoint(endAngle, outerR);
    const si = _clockPoint(startAngle, innerR);
    const ei = _clockPoint(endAngle, innerR);
    return [
      `M ${so.x} ${so.y}`,
      `A ${outerR} ${outerR} 0 ${large} 1 ${eo.x} ${eo.y}`,
      `L ${ei.x} ${ei.y}`,
      `A ${innerR} ${innerR} 0 ${large} 0 ${si.x} ${si.y}`,
      'Z',
    ].join(' ');
  }

  function _clockRoundedDonutPath(startAngle, endAngle, outerR, innerR, cornerRadius) {
    const span = Math.max(0, endAngle - startAngle);
    if (span <= 0 || span >= 359.5 || outerR <= innerR) return _clockDonutPath(startAngle, endAngle, outerR, innerR);
    const width = outerR - innerR;
    const spanArc = span * Math.PI / 180 * innerR;
    const radius = Math.max(0, Math.min(cornerRadius || 0, width / 2, spanArc / 3));
    if (radius < 0.5) return _clockDonutPath(startAngle, endAngle, outerR, innerR);
    const outerOffset = Math.min(span * 0.42, radius / outerR * 180 / Math.PI);
    const innerOffset = Math.min(span * 0.42, radius / innerR * 180 / Math.PI);
    const outerSpan = Math.max(0.1, span - outerOffset * 2);
    const innerSpan = Math.max(0.1, span - innerOffset * 2);
    const so0 = _clockPoint(startAngle, outerR - radius);
    const soCorner = _clockPoint(startAngle, outerR);
    const so1 = _clockPoint(startAngle + outerOffset, outerR);
    const eo1 = _clockPoint(endAngle - outerOffset, outerR);
    const eoCorner = _clockPoint(endAngle, outerR);
    const eo0 = _clockPoint(endAngle, outerR - radius);
    const ei0 = _clockPoint(endAngle, innerR + radius);
    const eiCorner = _clockPoint(endAngle, innerR);
    const ei1 = _clockPoint(endAngle - innerOffset, innerR);
    const si1 = _clockPoint(startAngle + innerOffset, innerR);
    const siCorner = _clockPoint(startAngle, innerR);
    const si0 = _clockPoint(startAngle, innerR + radius);
    return [
      `M ${so0.x.toFixed(2)} ${so0.y.toFixed(2)}`,
      `Q ${soCorner.x.toFixed(2)} ${soCorner.y.toFixed(2)} ${so1.x.toFixed(2)} ${so1.y.toFixed(2)}`,
      `A ${outerR.toFixed(2)} ${outerR.toFixed(2)} 0 ${outerSpan > 180 ? 1 : 0} 1 ${eo1.x.toFixed(2)} ${eo1.y.toFixed(2)}`,
      `Q ${eoCorner.x.toFixed(2)} ${eoCorner.y.toFixed(2)} ${eo0.x.toFixed(2)} ${eo0.y.toFixed(2)}`,
      `L ${ei0.x.toFixed(2)} ${ei0.y.toFixed(2)}`,
      `Q ${eiCorner.x.toFixed(2)} ${eiCorner.y.toFixed(2)} ${ei1.x.toFixed(2)} ${ei1.y.toFixed(2)}`,
      `A ${innerR.toFixed(2)} ${innerR.toFixed(2)} 0 ${innerSpan > 180 ? 1 : 0} 0 ${si1.x.toFixed(2)} ${si1.y.toFixed(2)}`,
      `Q ${siCorner.x.toFixed(2)} ${siCorner.y.toFixed(2)} ${si0.x.toFixed(2)} ${si0.y.toFixed(2)}`,
      'Z',
    ].join(' ');
  }

  function _clockArcPath(startAngle, endAngle, radius) {
    const span = Math.max(0.1, Math.min(359.5, endAngle - startAngle));
    const large = span > 180 ? 1 : 0;
    const start = _clockPoint(startAngle, radius);
    const end = _clockPoint(startAngle + span, radius);
    return `M ${start.x.toFixed(2)} ${start.y.toFixed(2)} A ${radius.toFixed(2)} ${radius.toFixed(2)} 0 ${large} 1 ${end.x.toFixed(2)} ${end.y.toFixed(2)}`;
  }

  function _clockRadialPath(angle, innerR, outerR) {
    const inner = _clockPoint(angle, innerR);
    const outer = _clockPoint(angle, outerR);
    return `M ${inner.x.toFixed(2)} ${inner.y.toFixed(2)} L ${outer.x.toFixed(2)} ${outer.y.toFixed(2)}`;
  }

  function _clockClamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function _clockSnapMinutes(minutes) {
    return _clockClamp(Math.round(minutes / CLOCK_EVENT_EDGE_MINUTES) * CLOCK_EVENT_EDGE_MINUTES, 0, 1440);
  }

  function _clockDateAtMinutes(dateStr, minutes) {
    const d = new Date(dateStr + 'T00:00:00');
    d.setMinutes(_clockClamp(minutes, 0, 1440));
    return d;
  }

  function _clockMinutesOfDay(date) {
    if (!date || Number.isNaN(date.getTime())) return 0;
    return date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60 + date.getMilliseconds() / 60000;
  }

  function _clockEventTitle(ev) {
    const start = String(ev.start || '').substring(11, 16);
    const end = String(ev.end || '').substring(11, 16);
    return `${ev.title || '無題'} ${start}${end ? ' - ' + end : ''}`;
  }

  function _clockShortText(value, maxChars) {
    const text = String(value || '').trim() || '無題';
    if (text.length <= maxChars) return text;
    return text.slice(0, Math.max(1, maxChars - 1)) + '…';
  }

  function _clockPrimaryUserName(component, ev) {
    const names = typeof component._eventUserNames === 'function' ? component._eventUserNames(ev) : [];
    return names[0] || '';
  }

  function _clockAvatarUrl(name) {
    return window.MeldexDataAccess?.team?.avatarUrl?.(name || 'anonymous', {}) || ('/api/team/avatar/' + encodeURIComponent(name || 'anonymous') + '?t=0');
  }

  function _clockAvatarInitial(name) {
    return (String(name || '?').trim().charAt(0).toUpperCase() || '?');
  }

  function _clockStableIdSuffix(value, fallback) {
    const raw = String(value ?? fallback ?? '').trim();
    const normalized = raw.replace(/[^a-zA-Z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 64);
    return normalized || String(fallback || 'item');
  }

  function _clockDateLabel(date) {
    const days = ['日', '月', '火', '水', '木', '金', '土'];
    return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日（${days[date.getDay()]}）`;
  }

  function _clockAssignEventSliceLanes(slices, mode) {
    const groups = new Map();
    (slices || []).forEach(slice => {
      const key = 'full';
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(slice);
    });
    groups.forEach(items => {
      let cluster = [];
      let clusterEnd = -1;
      const flush = () => {
        if (!cluster.length) return;
        const laneEnds = [];
        cluster.forEach(item => {
          let lane = laneEnds.findIndex(end => end <= item.start);
          if (lane < 0) lane = laneEnds.length;
          laneEnds[lane] = item.end;
          item.lane = lane;
        });
        const laneCount = Math.max(1, laneEnds.length);
        cluster.forEach(item => { item.laneCount = laneCount; });
        cluster = [];
        clusterEnd = -1;
      };
      items
        .slice()
        .sort((a, b) => (a.start - b.start) || (a.end - b.end))
        .forEach(item => {
          if (!cluster.length || item.start < clusterEnd) {
            cluster.push(item);
            clusterEnd = Math.max(clusterEnd, item.end);
          } else {
            flush();
            cluster.push(item);
            clusterEnd = item.end;
          }
        });
      flush();
    });
  }

  function _clockSameDate(a, b) {
    return a.getFullYear() === b.getFullYear()
      && a.getMonth() === b.getMonth()
      && a.getDate() === b.getDate();
  }

  function _clockRangeFromMinutes(startMin, endMin, defaultDuration = CLOCK_DEFAULT_EVENT_MINUTES, mode = 24) {
    let start = _clockClamp(_clockSnapMinutes(startMin), 0, 1440 - CLOCK_EVENT_EDGE_MINUTES);
    let end = _clockSnapMinutes(endMin);
    if (start >= 1080 && (end === 0 || (mode === 12 && end === 720))) end = 1440;
    if (end === start) {
      end = _clockClamp(start + defaultDuration, CLOCK_EVENT_EDGE_MINUTES, 1440);
    } else if (end < start) {
      [start, end] = [end, start];
    }
    if (end <= start) end = _clockClamp(start + CLOCK_EVENT_EDGE_MINUTES, CLOCK_EVENT_EDGE_MINUTES, 1440);
    return { start, end };
  }

  function _clockRangeIntervalsForMode(startMin, endMin, mode) {
    if (mode === 24) return [{ start: startMin, end: endMin, half: 0, period: 1440 }];
    const intervals = [];
    [[0, 720], [720, 1440]].forEach(([from, to]) => {
      const start = Math.max(startMin, from);
      const end = Math.min(endMin, to);
      if (end > start) intervals.push({ start: start - from, end: end - from, half: from >= 720 ? 1 : 0, period: 720 });
    });
    return intervals;
  }

  const baseRender = CalendarComponent.prototype._render;
  const baseDeactivate = CalendarComponent.prototype.deactivate;
  const baseDestroy = CalendarComponent.prototype.destroy;

  CalendarComponent.prototype._isAnalogClockView = function() {
    return this._view === 'clock12' || this._view === 'clock24';
  };

  CalendarComponent.prototype._clockActiveHalf = function() {
    return this._clock12Half === 1 ? 1 : 0;
  };

  CalendarComponent.prototype._render = function() {
    if (!this._isAnalogClockView()) {
      this._clearAnalogClockTimer?.();
      return baseRender.call(this);
    }
    ++this._renderSeq;
    const y = this._date.getFullYear();
    const m = this._date.getMonth() + 1;
    const d = this._date.getDate();
    const mode = this._view === 'clock24' ? 24 : 12;
    if (this._titleEl) this._titleEl.textContent = `${y}年${m}月${d}日 アナログ時計（${mode}時間）`;
    this._renderAnalogClockView(mode);
    this._clearNowLineTimer?.();
    if (this._contentEl && typeof CommentBadges !== 'undefined' && typeof CommentBadges.refreshCalendar === 'function') {
      try { CommentBadges.refreshCalendar(this._contentEl); } catch (_) {}
    }
  };

  CalendarComponent.prototype.deactivate = function() {
    this._clearAnalogClockTimer?.();
    baseDeactivate.call(this);
  };

  CalendarComponent.prototype.destroy = function() {
    this._clearAnalogClockTimer?.();
    baseDestroy.call(this);
  };

  CalendarComponent.prototype._clockTicksSvg = function(mode) {
    let html = '';
    if (mode === 24) {
      for (let i = 0; i < 48; i++) {
        const major = i % 2 === 0;
        const p1 = _clockPoint(i * 7.5, major ? 162 : 170);
        const p2 = _clockPoint(i * 7.5, OUTER_R);
        html += `<line class="gb-cal-clock-tick gb-cal-clock-tick-24${major ? ' major' : ''}" x1="${p1.x.toFixed(2)}" y1="${p1.y.toFixed(2)}" x2="${p2.x.toFixed(2)}" y2="${p2.y.toFixed(2)}"></line>`;
      }
      for (let h = 0; h < 24; h++) {
        const p = _clockPoint(h * 15, 141);
        html += `<text class="gb-cal-clock-label gb-cal-clock-label-24" x="${p.x.toFixed(2)}" y="${p.y.toFixed(2)}">${h}</text>`;
      }
      return html;
    }
    for (let i = 0; i < 60; i++) {
      const major = i % 5 === 0;
      const p1 = _clockPoint(i * 6, major ? 163 : 170);
      const p2 = _clockPoint(i * 6, OUTER_R);
      html += `<line class="gb-cal-clock-tick${major ? ' major' : ''}" x1="${p1.x.toFixed(2)}" y1="${p1.y.toFixed(2)}" x2="${p2.x.toFixed(2)}" y2="${p2.y.toFixed(2)}"></line>`;
    }
    if (mode === 12) {
      for (let h = 1; h <= 12; h++) {
        const p = _clockPoint(h * 30, 141);
        html += `<text class="gb-cal-clock-label" x="${p.x.toFixed(2)}" y="${p.y.toFixed(2)}">${h}</text>`;
      }
      return html;
    }
    return html;
  };

  CalendarComponent.prototype._clockEventIntervals = function(ev, dateStr, mode) {
    const dayStart = new Date(dateStr + 'T00:00:00');
    const dayEnd = new Date(dayStart.getTime());
    dayEnd.setDate(dayEnd.getDate() + 1);
    const rawStart = _clockDate(ev.start) || dayStart;
    const rawEnd = _clockDate(ev.end) || new Date(rawStart.getTime() + 60 * 60000);
    // 終日イベントは start==end の日付のみ形式になるため、空判定（end<=start）より先に処理する
    if (ev.all_day) {
      return mode === 24 ? [{ start: 0, end: 1440, half: 0 }] : [{ start: 0, end: 720, half: 0 }, { start: 0, end: 720, half: 1 }];
    }
    const start = rawStart < dayStart ? dayStart : rawStart;
    const end = rawEnd > dayEnd ? dayEnd : rawEnd;
    if (end <= start) return [];
    const startMin = rawStart < dayStart ? 0 : Math.max(0, Math.floor(_clockMinutesOfDay(start)));
    const endMin = rawEnd >= dayEnd ? 1440 : Math.min(1440, Math.ceil(_clockMinutesOfDay(end)));
    if (endMin - startMin >= 1439) {
      return mode === 24 ? [{ start: 0, end: 1440, half: 0 }] : [{ start: 0, end: 720, half: 0 }, { start: 0, end: 720, half: 1 }];
    }
    if (mode === 24) return [{ start: startMin, end: endMin }];
    const intervals = [];
    [[0, 720], [720, 1440]].forEach(([from, to]) => {
      const s = Math.max(startMin, from);
      const e = Math.min(endMin, to);
      if (e > s) intervals.push({ start: s - from, end: e - from, half: from >= 720 ? 1 : 0 });
    });
    return intervals;
  };

  CalendarComponent.prototype._clockEventSlices = function(mode, dateStr) {
    const period = mode === 24 ? 1440 : 720;
    const activeHalf = mode === 12 ? this._clockActiveHalf() : null;
    const events = (this._events || []).filter(ev => {
      if (!this._isCalVisible(ev)) return false;
      if (typeof this._eventIntersectsDay === 'function') return this._eventIntersectsDay(ev, dateStr);
      return String(ev.start || '').startsWith(dateStr);
    });
    const slices = [];
    events.forEach((ev, eventIndex) => {
      const color = this._sanitizeEventColor ? this._sanitizeEventColor(ev.color) : (ev.color || '#569cd6');
      this._clockEventIntervals(ev, dateStr, mode).forEach((interval, intervalIndex) => {
        if (mode === 12 && interval.half !== activeHalf) return;
        const start = Math.max(0, Math.min(period, interval.start));
        const end = Math.min(period, Math.max(start + 4, interval.end));
        slices.push({ ev, eventIndex, intervalIndex, color, start, end, half: interval.half || 0 });
      });
    });
    _clockAssignEventSliceLanes(slices, mode);
    slices.forEach(slice => {
        const startAngle = (slice.start / period) * 360;
        const endAngle = Math.min(360, (slice.end / period) * 360);
        const laneCount = Math.max(1, slice.laneCount || 1);
        const localLane = _clockClamp(slice.lane || 0, 0, laneCount - 1);
        const outerBase = EVENT_OUTER_R;
        const innerBase = EVENT_INNER_R;
        const usableWidth = Math.max(CLOCK_EVENT_CARD_MIN_WIDTH, outerBase - innerBase - 2);
        const laneOffset = laneCount > 1 ? Math.min(CLOCK_EVENT_CARD_LANE_OFFSET, Math.max(4, usableWidth * 0.14)) : 0;
        const outerReserve = localLane * laneOffset;
        const innerReserve = Math.max(0, laneCount - localLane - 1) * laneOffset;
        const inner = innerBase + 1 + innerReserve;
        const outer = Math.max(inner + CLOCK_EVENT_CARD_MIN_WIDTH, outerBase - 1 - outerReserve);
        const midRadius = (outer + inner) / 2;
        slice.period = period;
        slice.thickness = outer - inner;
        slice.outer = outer;
        slice.inner = inner;
        slice.path = _clockRoundedDonutPath(startAngle, endAngle, slice.outer, slice.inner, Math.min(3, slice.thickness / 3));
        slice.midAngle = ((slice.start + slice.end) / 2 / period) * 360;
        slice.midRadius = midRadius;
        slice.startAngle = startAngle;
        slice.endAngle = endAngle;
        void slice.eventIndex;
        void slice.intervalIndex;
    });
    return slices;
  };

  CalendarComponent.prototype._clockEventSlicesSvg = function(mode, dateStr) {
    let html = '';
    this._clockEventSlices(mode, dateStr)
      .slice()
      .sort((a, b) => (a.half - b.half) || (a.lane - b.lane) || (a.start - b.start) || (a.end - b.end))
      .forEach((slice, index) => {
      const clipId = `gb-cal-clock-clip-${String(slice.ev.id || index).replace(/[^a-zA-Z0-9_-]/g, '-')}-${index}`;
      const titlePathId = `${clipId}-title`;
      const avatarClipId = `${clipId}-avatar`;
      const userName = _clockPrimaryUserName(this, slice.ev);
      const avatarMaxRadius = Math.min(5.2, Math.max(2.4, (slice.thickness - 2) / 2));
      const avatarRadius = userName ? _clockClamp(slice.thickness * 0.18, 2.4, avatarMaxRadius) : 0;
      const avatarAnglePad = avatarRadius ? (avatarRadius / Math.max(1, slice.midRadius)) * 180 / Math.PI + 1.4 : 0;
      const selectAnglePad = (6 / Math.max(1, slice.midRadius)) * 180 / Math.PI + 1.4;
      const avatarAngle = avatarRadius ? Math.max(slice.startAngle + selectAnglePad + 0.5, slice.endAngle - avatarAnglePad) : slice.endAngle;
      const arcLength = Math.max(0, (slice.endAngle - slice.startAngle) / 360 * 2 * Math.PI * slice.midRadius);
      const titleChars = _clockClamp(Math.floor((arcLength - (avatarRadius ? 20 : 12)) / 3.7), 3, 34);
      const title = _clockShortText(slice.ev?.title || '無題', titleChars);
      const titleRadius = _clockClamp(slice.midRadius, slice.inner + 4, slice.outer - 4);
      const selectPoint = _clockPoint(Math.min(slice.endAngle - 0.5, slice.startAngle + selectAnglePad), Math.max(slice.inner + 7, slice.outer - 7));
      const avatarPoint = avatarRadius ? _clockPoint(avatarAngle, Math.min(slice.outer - avatarRadius - 2, slice.inner + avatarRadius + 2)) : null;
      const eventE2eId = `calendar-clock-event-${_clockStableIdSuffix(slice.ev?.id, index)}-${index}`;
      html += `<g class="gb-cal-clock-event" data-e2e-id="${_clockEsc(eventE2eId)}" data-clock-event-id="${_clockEsc(slice.ev.id)}" data-calendar-id="${_clockEsc(slice.ev.calendar_id || '_calendar')}" data-clock-start-min="${_clockEsc(slice.start)}" data-clock-end-min="${_clockEsc(slice.end)}" role="button" tabindex="0" aria-label="${_clockEsc(_clockEventTitle(slice.ev))}">`;
      html += `<clipPath id="${_clockEsc(clipId)}"><path d="${slice.path}"></path></clipPath>`;
      if (avatarPoint) html += `<clipPath id="${_clockEsc(avatarClipId)}"><circle cx="${avatarPoint.x.toFixed(2)}" cy="${avatarPoint.y.toFixed(2)}" r="${avatarRadius.toFixed(2)}"></circle></clipPath>`;
      html += `<path id="${_clockEsc(titlePathId)}" class="gb-cal-clock-event-label-path" d="${_clockArcPath(slice.startAngle + selectAnglePad * 1.8, Math.max(slice.startAngle + selectAnglePad * 2.2, slice.endAngle - avatarAnglePad * 2), titleRadius)}"></path>`;
      html += `<path class="gb-cal-clock-event-slice" data-e2e-id="${_clockEsc(eventE2eId)}-slice" d="${slice.path}" fill="${_clockEsc(slice.color)}" fill-rule="evenodd" data-event-id="${_clockEsc(slice.ev.id)}" data-calendar-id="${_clockEsc(slice.ev.calendar_id || '_calendar')}" data-clock-card-width="${slice.thickness.toFixed(2)}"><title>${_clockEsc(_clockEventTitle(slice.ev))}</title></path>`;
      html += `<g class="gb-cal-clock-event-text" clip-path="url(#${_clockEsc(clipId)})"><text class="gb-cal-clock-event-label"><textPath href="#${_clockEsc(titlePathId)}" startOffset="50%" text-anchor="middle">${_clockEsc(title)}</textPath></text>`;
      if (avatarPoint) html += `<g class="gb-cal-clock-event-avatar" data-clock-avatar-position="end-center" transform="translate(${avatarPoint.x.toFixed(2)} ${avatarPoint.y.toFixed(2)})"><circle class="gb-cal-clock-event-avatar-bg" r="${avatarRadius.toFixed(2)}"></circle><text class="gb-cal-clock-event-avatar-initial" y="0.25">${_clockEsc(_clockAvatarInitial(userName))}</text><image href="${_clockEsc(_clockAvatarUrl(userName))}" x="${(-avatarRadius).toFixed(2)}" y="${(-avatarRadius).toFixed(2)}" width="${(avatarRadius * 2).toFixed(2)}" height="${(avatarRadius * 2).toFixed(2)}" clip-path="url(#${_clockEsc(avatarClipId)})"></image></g>`;
      html += `</g>`;
      html += `<g class="gb-cal-clock-select-check" data-e2e-id="${_clockEsc(eventE2eId)}-select" data-clock-select="1" data-clock-select-position="start-outer" role="checkbox" aria-label="選択" aria-checked="false" transform="translate(${(selectPoint.x - CLOCK_EVENT_CHECK_SIZE / 2).toFixed(2)} ${(selectPoint.y - CLOCK_EVENT_CHECK_SIZE / 2).toFixed(2)})"><rect class="gb-cal-clock-select-box" width="${CLOCK_EVENT_CHECK_SIZE}" height="${CLOCK_EVENT_CHECK_SIZE}" rx="1.5"></rect><path class="gb-cal-clock-select-mark" d="M2 4.1 L3.5 5.6 L6.2 2.5"></path></g>`;
      html += `<path class="gb-cal-clock-resize-edge start" data-e2e-id="${_clockEsc(eventE2eId)}-resize-start" data-clock-resize="start" d="${_clockRadialPath(slice.startAngle, slice.inner, slice.outer)}"></path>`;
      html += `<path class="gb-cal-clock-resize-edge end" data-e2e-id="${_clockEsc(eventE2eId)}-resize-end" data-clock-resize="end" d="${_clockRadialPath(slice.endAngle, slice.inner, slice.outer)}"></path>`;
      html += `</g>`;
    });
    return html;
  };

  CalendarComponent.prototype._renderAnalogClockView = function(mode) {
    if (!this._contentEl) return;
    const dateStr = this._localDateStr(this._date);
    const selected = this._selectedCalendar?.();
    const dateLabel = _clockDateLabel(this._date);
    const activeHalf = this._clockActiveHalf();
    const halfToggle = mode === 12 ? `
          <div class="gb-cal-clock-half-toggle" data-e2e-id="calendar-clock-half-toggle" role="group" aria-label="午前午後切替">
            <button type="button" data-e2e-id="calendar-clock-half-am" data-clock-half="0" aria-label="午前を表示" aria-pressed="${activeHalf === 0 ? 'true' : 'false'}">午前</button>
            <button type="button" data-e2e-id="calendar-clock-half-pm" data-clock-half="1" aria-label="午後を表示" aria-pressed="${activeHalf === 1 ? 'true' : 'false'}">午後</button>
          </div>` : '';
    this._contentEl.innerHTML = `
      <div class="gb-cal-clock-view" data-e2e-id="calendar-clock-view" data-clock-mode="${mode}">
        <div class="gb-cal-clock-view-meta">
          <span>${_clockEsc(dateStr)}</span>
          <span>選択中: ${_clockEsc(selected?.name || 'なし')}</span>
        </div>
        <div class="gb-cal-clock-stage" data-e2e-id="calendar-clock-stage">
          ${halfToggle}
          <svg class="gb-cal-clock-svg" data-e2e-id="calendar-clock-create-surface" viewBox="0 0 ${SIZE} ${SIZE}" role="img" aria-label="アナログ時計 ${mode}時間。空いている時間をドラッグして予定を作成">
            <circle class="gb-cal-clock-face" cx="${CX}" cy="${CY}" r="${OUTER_R}"></circle>
            <text class="gb-cal-clock-date-label" x="24" y="34">${_clockEsc(dateLabel)}</text>
            <g class="gb-cal-clock-events">${this._clockEventSlicesSvg(mode, dateStr)}</g>
            <g class="gb-cal-clock-preview"></g>
            <g class="gb-cal-clock-ticks">${this._clockTicksSvg(mode)}</g>
            <line class="gb-cal-clock-hand gb-cal-clock-hour" data-clock-hand="hour" x1="${CX}" y1="${CY}" x2="${CX}" y2="${mode === 24 ? 112 : 102}"></line>
            <line class="gb-cal-clock-hand gb-cal-clock-minute" data-clock-hand="minute" x1="${CX}" y1="${CY}" x2="${CX}" y2="65"></line>
            <line class="gb-cal-clock-hand gb-cal-clock-second" data-clock-hand="second" x1="${CX}" y1="${CY + 18}" x2="${CX}" y2="54"></line>
            <circle class="gb-cal-clock-pin" cx="${CX}" cy="${CY}" r="5"></circle>
          </svg>
          <div class="gb-cal-clock-hover-card" data-e2e-id="calendar-clock-hover-card" hidden></div>
        </div>
      </div>`;
    this._bindAnalogClockInteractions(mode, dateStr);
    this._syncAnalogClockSelectionDom();
    this._syncAnalogClockTimer(mode);
  };

  CalendarComponent.prototype._bindAnalogClockInteractions = function(mode, dateStr) {
    const root = this._contentEl;
    if (!root) return;
    root.querySelectorAll('[data-clock-half]').forEach(button => {
      button.addEventListener('pointerdown', event => event.stopPropagation());
      button.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        this._clock12Half = button.dataset.clockHalf === '1' ? 1 : 0;
        this._hideClockHoverCard();
        this._render();
      });
    });
    root.querySelectorAll('.gb-cal-clock-event[data-clock-event-id]').forEach(item => {
      const eventId = item.dataset.clockEventId || '';
      const ev = (this._events || []).find(entry => entry.id === eventId);
      item.addEventListener('click', (event) => {
        if (this._clockSuppressCardClickUntil && Date.now() < this._clockSuppressCardClickUntil) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        if (event.target.closest?.('[data-clock-resize]')) return;
        event.preventDefault();
        event.stopPropagation();
        if (event.target.closest?.('[data-clock-select]')) {
          this._toggleEventSelection?.(eventId);
          this._syncAnalogClockSelectionDom();
          return;
        }
        if (event.shiftKey) this._selectAnalogClockEventRange(eventId);
        else if (event.ctrlKey || event.metaKey) this._toggleEventSelection?.(eventId);
        else {
          this._setSelectedEvents?.([eventId], eventId);
          this._openEventInPanel(eventId);
        }
        this._syncAnalogClockSelectionDom();
      });
      item.addEventListener('keydown', (event) => {
        if (event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        this._setSelectedEvents?.([eventId], eventId);
        this._syncAnalogClockSelectionDom();
        this._openEventInPanel(eventId);
      });
      item.addEventListener('pointerenter', (event) => {
        if (ev) this._showClockHoverCard(event, ev);
      });
      item.addEventListener('pointermove', (event) => {
        if (ev) this._showClockHoverCard(event, ev);
      });
      item.addEventListener('pointerleave', () => this._hideClockHoverCard());
      item.addEventListener('pointerdown', (event) => {
        if (event.target.closest?.('[data-clock-select], [data-clock-resize]')) return;
        this._hideClockHoverCard();
        this._startAnalogClockMove(event, item, mode, dateStr);
      });
      item.querySelectorAll('[data-clock-resize]').forEach(handle => {
        handle.addEventListener('click', (event) => {
          event.preventDefault();
          event.stopPropagation();
        });
        handle.addEventListener('pointerdown', (event) => {
          this._hideClockHoverCard();
          this._startAnalogClockResize(event, item, mode, dateStr, handle.dataset.clockResize);
        });
      });
    });
    this._bindAnalogClockOutsideClear(root.querySelector('.gb-cal-clock-stage'));
    this._bindAnalogClockCreateDrag(root.querySelector('.gb-cal-clock-svg'), mode, dateStr);
  };

  CalendarComponent.prototype._bindAnalogClockOutsideClear = function(stage) {
    const svg = stage?.querySelector?.('.gb-cal-clock-svg');
    if (!stage || !svg) return;
    stage.addEventListener('pointerdown', (event) => {
      if (event.button !== 0 || event.target.closest?.('.gb-cal-clock-event')) return;
      const outsideSvg = !svg.contains(event.target);
      const point = _clockSvgRelativePoint(svg, event.clientX, event.clientY);
      if (!outsideSvg && point.radius <= OUTER_R) return;
      this._setSelectedEvents?.([], '');
      this._syncAnalogClockSelectionDom();
      this._hideClockHoverCard();
    });
  };

  CalendarComponent.prototype._analogClockRenderedEventIds = function() {
    const ids = [];
    this._contentEl?.querySelectorAll?.('.gb-cal-clock-event[data-clock-event-id]').forEach(item => {
      const id = item.dataset.clockEventId || '';
      if (id && !ids.includes(id)) ids.push(id);
    });
    return ids;
  };

  CalendarComponent.prototype._selectAnalogClockEventRange = function(id) {
    const order = this._analogClockRenderedEventIds();
    const anchor = this._lastSelectedEventId || id;
    const a = order.indexOf(anchor), b = order.indexOf(id);
    if (a < 0 || b < 0) {
      this._setSelectedEvents?.([id], id);
      return;
    }
    const [from, to] = a < b ? [a, b] : [b, a];
    this._setSelectedEvents?.(order.slice(from, to + 1), id);
  };

  CalendarComponent.prototype._syncAnalogClockSelectionDom = function() {
    const sel = typeof this._eventSelection === 'function' ? this._eventSelection() : new Set();
    this._contentEl?.classList?.toggle?.('gb-cal-has-event-selection', sel.size > 0);
    this._contentEl?.querySelectorAll?.('.gb-cal-clock-event[data-clock-event-id]').forEach(item => {
      const selected = sel.has(item.dataset.clockEventId || '');
      item.classList.toggle('gb-cal-clock-event-selected', selected);
      const check = item.querySelector(':scope > .gb-cal-clock-select-check');
      if (check) check.setAttribute('aria-checked', selected ? 'true' : 'false');
    });
  };

  CalendarComponent.prototype._showClockHoverCard = function(event, ev) {
    const tip = this._contentEl?.querySelector?.('.gb-cal-clock-hover-card');
    const stage = this._contentEl?.querySelector?.('.gb-cal-clock-stage');
    if (!tip || !stage) return;
    const rect = stage.getBoundingClientRect();
    const start = String(ev.start || '').substring(11, 16);
    const end = String(ev.end || '').substring(11, 16);
    const timeLabel = `${start}${end ? ' - ' + end : ''}`;
    tip.innerHTML = `<div class="gb-cal-clock-hover-title">${_clockEsc(ev.title || '無題')}</div><div class="gb-cal-clock-hover-meta">${_clockEsc(timeLabel)}</div>`;
    tip.hidden = false;
    const left = _clockClamp(event.clientX - rect.left + 10, 6, Math.max(6, rect.width - 210));
    const top = _clockClamp(event.clientY - rect.top + 10, 6, Math.max(6, rect.height - 56));
    tip.style.left = `${left}px`;
    tip.style.top = `${top}px`;
  };

  CalendarComponent.prototype._hideClockHoverCard = function() {
    const tip = this._contentEl?.querySelector?.('.gb-cal-clock-hover-card');
    if (tip) tip.hidden = true;
  };

  CalendarComponent.prototype._clockMinutesFromPointer = function(event, mode, dateStr) {
    void dateStr;
    return this._clockMinutesFromClient(event.clientX, event.clientY, mode);
  };

  CalendarComponent.prototype._clockMinutesFromClient = function(clientX, clientY, mode) {
    const svg = this._contentEl?.querySelector?.('.gb-cal-clock-svg');
    if (!svg) return 0;
    const { x, y } = _clockSvgRelativePoint(svg, clientX, clientY);
    let angle = Math.atan2(y, x) * 180 / Math.PI + 90;
    if (angle < 0) angle += 360;
    const period = mode === 24 ? 1440 : 720;
    let minutes = Math.round((angle / 360) * period / 15) * 15;
    minutes = ((minutes % period) + period) % period;
    if (mode === 12) {
      minutes += this._clockActiveHalf() * 720;
    }
    return Math.max(0, Math.min(1439, minutes));
  };

  CalendarComponent.prototype._clockEditableRangeForEvent = function(ev, dateStr) {
    const dayStart = new Date(dateStr + 'T00:00:00');
    const dayEnd = new Date(dayStart.getTime());
    dayEnd.setDate(dayEnd.getDate() + 1);
    const rawStart = _clockDate(ev?.start) || dayStart;
    const rawEnd = _clockDate(ev?.end) || new Date(rawStart.getTime() + CLOCK_DEFAULT_EVENT_MINUTES * 60000);
    const start = rawStart < dayStart ? dayStart : rawStart;
    const end = rawEnd > dayEnd ? dayEnd : rawEnd;
    if (ev?.all_day || rawEnd - rawStart >= 1439 * 60000) {
      return { start: 0, end: 1440, rawStart, rawEnd };
    }
    const startMin = _clockClamp(Math.floor(_clockMinutesOfDay(start)), 0, 1439);
    // 翌日0:00で終わるイベントは _clockMinutesOfDay が 0 を返すため、表示側（_clockEventIntervals）と同じ 1440 補正を行う
    const endMin = rawEnd >= dayEnd ? 1440 : _clockClamp(Math.ceil(_clockMinutesOfDay(end)), startMin + CLOCK_EVENT_EDGE_MINUTES, 1440);
    return { start: startMin, end: endMin, rawStart, rawEnd };
  };

  CalendarComponent.prototype._setClockRangePreview = function(mode, startMin, endMin, variant = 'create') {
    const preview = this._contentEl?.querySelector?.('.gb-cal-clock-preview');
    if (!preview) return;
    const ranges = _clockRangeIntervalsForMode(startMin, endMin, mode);
    preview.innerHTML = ranges.map(range => {
      const outer = EVENT_OUTER_R;
      const inner = EVENT_INNER_R;
      const startAngle = (range.start / range.period) * 360;
      const endAngle = (range.end / range.period) * 360;
      const path = _clockDonutPath(startAngle, endAngle, outer, inner);
      return `<path class="gb-cal-clock-selection-preview ${variant}" d="${path}" fill-rule="evenodd"></path>`;
    }).join('');
  };

  CalendarComponent.prototype._clearClockRangePreview = function() {
    const preview = this._contentEl?.querySelector?.('.gb-cal-clock-preview');
    if (preview) preview.innerHTML = '';
  };

  CalendarComponent.prototype._bindAnalogClockCreateDrag = function(svg, mode, dateStr) {
    if (!svg) return;
    let drag = null;
    const cleanup = () => {
      if (!drag) return;
      try { svg.releasePointerCapture(drag.pointerId); } catch (_) {}
      document.body.style.userSelect = '';
      this._clearClockRangePreview();
      drag = null;
    };
    const finish = () => {
      if (!drag) return;
      const current = drag;
      cleanup();
      const range = _clockRangeFromMinutes(current.startMin, current.endMin, CLOCK_DEFAULT_EVENT_MINUTES, mode);
      this._openEventInPanel(null, this._localDateTimeStr(_clockDateAtMinutes(dateStr, range.start)), this._localDateTimeStr(_clockDateAtMinutes(dateStr, range.end)), false);
    };
    svg.addEventListener('pointerdown', (event) => {
      if (event.button !== 0 || event.target.closest?.('.gb-cal-clock-event, .gb-cal-clock-event-slice')) return;
      if (_clockSvgRelativePoint(svg, event.clientX, event.clientY).radius > OUTER_R) return;
      event.preventDefault();
      const startMin = this._clockMinutesFromPointer(event, mode, dateStr);
      drag = { startMin, endMin: startMin, x: event.clientX, y: event.clientY, pointerId: event.pointerId };
      if (event.isTrusted !== false) {
        try { svg.setPointerCapture(event.pointerId); } catch (_) {}
      }
      document.body.style.userSelect = 'none';
      this._setClockRangePreview(mode, startMin, Math.min(1440, startMin + CLOCK_DEFAULT_EVENT_MINUTES), 'create');
    });
    svg.addEventListener('pointermove', (event) => {
      if (!drag) return;
      event.preventDefault();
      drag.endMin = this._clockMinutesFromPointer(event, mode, dateStr);
      const range = _clockRangeFromMinutes(drag.startMin, drag.endMin, CLOCK_DEFAULT_EVENT_MINUTES, mode);
      this._setClockRangePreview(mode, range.start, range.end, 'create');
    });
    svg.addEventListener('pointerup', (event) => {
      if (!drag) return;
      event.preventDefault();
      finish();
    });
    svg.addEventListener('pointercancel', cleanup);
    svg.addEventListener('lostpointercapture', cleanup);
  };

  CalendarComponent.prototype._commitAnalogClockEventChange = function(eventId, patch, label) {
    const before = this._snapshotEventLocal?.(eventId);
    const sourceEvent = (this._events || []).find(item => item.id === eventId);
    this._pushUndo?.(label);
    this._applyEventLocal?.(eventId, patch);
    this._setSelectedEvents?.([eventId], eventId);
    this._render();
    (typeof _calApplyEventTimePatch === 'function' && sourceEvent ? _calApplyEventTimePatch(this, sourceEvent, patch) : apiPut('/cal/events/' + eventId, patch))
      .then(() => this._loadEvents())
      .then(() => this._render())
      .catch(() => {
        if (before) this._restoreEventLocal?.(before);
        this._render();
        this._showStatus?.(label + 'に失敗', true);
      });
  };

  CalendarComponent.prototype._startAnalogClockMove = function(event, card, mode, dateStr) {
    if (event.button !== 0) return;
    const eventId = card.dataset.eventId || card.dataset.clockEventId || '';
    const ev = (this._events || []).find(item => item.id === eventId);
    if (!ev || (typeof _calRecurringInteractionBlocked === 'function' && _calRecurringInteractionBlocked(this, ev))) return;
    event.preventDefault();
    event.stopPropagation();
    const range = this._clockEditableRangeForEvent(ev, dateStr);
    const rawDuration = range.end - range.start;
    const duration = ev.all_day || rawDuration >= 1439 ? CLOCK_DEFAULT_EVENT_MINUTES : _clockClamp(rawDuration, CLOCK_EVENT_EDGE_MINUTES, 1440);
    const downMin = this._clockMinutesFromClient(event.clientX, event.clientY, mode);
    const pointerOffset = _clockClamp(downMin - range.start, 0, Math.max(0, duration - CLOCK_EVENT_EDGE_MINUTES));
    const startX = event.clientX;
    const startY = event.clientY;
    let nextStart = range.start;
    let moved = false;
    document.body.style.userSelect = 'none';
    card.style.touchAction = 'none';
    const updatePreview = (clientX, clientY) => {
      const pointerMin = this._clockMinutesFromClient(clientX, clientY, mode);
      nextStart = _clockSnapMinutes(pointerMin - pointerOffset);
      nextStart = _clockClamp(nextStart, 0, Math.max(0, 1440 - duration));
      this._setClockRangePreview(mode, nextStart, nextStart + duration, 'move');
    };
    const onMove = (moveEvent) => {
      if (Math.abs(moveEvent.clientX - startX) >= CLOCK_DRAG_PX_THRESHOLD || Math.abs(moveEvent.clientY - startY) >= CLOCK_DRAG_PX_THRESHOLD) moved = true;
      updatePreview(moveEvent.clientX, moveEvent.clientY);
    };
    const cleanup = () => {
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerup', onUp);
      document.removeEventListener('pointercancel', onCancel);
      document.body.style.userSelect = '';
      card.style.touchAction = '';
      this._clearClockRangePreview();
    };
    const onCancel = () => {
      cleanup();
    };
    const onUp = () => {
      cleanup();
      if (!moved || nextStart === range.start) return;
      this._clockSuppressCardClickUntil = Date.now() + 300;
      const deltaMin = nextStart - range.start;
      // 跨日・複数日イベントは表示日内に切り詰めず、実際の開始/終了へ同じ移動量を適用する
      // （終日イベントの時間指定化は従来どおり）
      const patch = !ev.all_day && range.rawStart instanceof Date && range.rawEnd instanceof Date
        ? {
            start: this._localDateTimeStr(new Date(range.rawStart.getTime() + deltaMin * 60000)),
            end: this._localDateTimeStr(new Date(range.rawEnd.getTime() + deltaMin * 60000)),
            all_day: 0,
          }
        : {
            start: this._localDateTimeStr(_clockDateAtMinutes(dateStr, nextStart)),
            end: this._localDateTimeStr(_clockDateAtMinutes(dateStr, nextStart + duration)),
            all_day: 0,
          };
      this._commitAnalogClockEventChange(eventId, patch, 'イベント移動');
    };
    document.addEventListener('pointermove', onMove);
    document.addEventListener('pointerup', onUp);
    document.addEventListener('pointercancel', onCancel);
  };

  CalendarComponent.prototype._startAnalogClockResize = function(event, card, mode, dateStr, edge) {
    if (event.button !== 0) return;
    const eventId = card.dataset.eventId || card.dataset.clockEventId || '';
    const ev = (this._events || []).find(item => item.id === eventId);
    if (!ev || (typeof _calRecurringInteractionBlocked === 'function' && _calRecurringInteractionBlocked(this, ev))) return;
    event.preventDefault();
    event.stopPropagation();
    const range = this._clockEditableRangeForEvent(ev, dateStr);
    let nextStart = range.start;
    let nextEnd = range.end;
    let moved = false;
    document.body.style.userSelect = 'none';
    card.style.touchAction = 'none';
    const updatePreview = (clientX, clientY) => {
      let pointerMin = this._clockMinutesFromClient(clientX, clientY, mode);
      if (edge === 'end' && range.end === 1440 && (pointerMin === 0 || (mode === 12 && pointerMin === 720))) pointerMin = 1440;
      else if (edge === 'end' && pointerMin < nextStart) {
        // 通常イベントの終端を文字盤上端まで延ばした場合の補正（24:00／半日境界として扱う）
        if (pointerMin === 0) pointerMin = mode === 12 ? 720 : 1440;
        else if (mode === 12 && pointerMin === 720) pointerMin = 1440;
      }
      if (edge === 'start') {
        nextStart = _clockClamp(_clockSnapMinutes(pointerMin), 0, nextEnd - CLOCK_EVENT_EDGE_MINUTES);
      } else {
        nextEnd = _clockClamp(_clockSnapMinutes(pointerMin), nextStart + CLOCK_EVENT_EDGE_MINUTES, 1440);
      }
      this._setClockRangePreview(mode, nextStart, nextEnd, 'resize');
    };
    const startX = event.clientX;
    const startY = event.clientY;
    const onMove = (moveEvent) => {
      if (Math.abs(moveEvent.clientX - startX) >= CLOCK_DRAG_PX_THRESHOLD || Math.abs(moveEvent.clientY - startY) >= CLOCK_DRAG_PX_THRESHOLD) moved = true;
      updatePreview(moveEvent.clientX, moveEvent.clientY);
    };
    const cleanup = () => {
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerup', onUp);
      document.removeEventListener('pointercancel', onCancel);
      document.body.style.userSelect = '';
      card.style.touchAction = '';
      this._clearClockRangePreview();
    };
    const onCancel = () => {
      cleanup();
    };
    const onUp = () => {
      cleanup();
      if (!moved || (nextStart === range.start && nextEnd === range.end)) return;
      this._clockSuppressCardClickUntil = Date.now() + 300;
      const patch = edge === 'start'
        ? { start: this._localDateTimeStr(_clockDateAtMinutes(dateStr, nextStart)), all_day: 0 }
        : { end: this._localDateTimeStr(_clockDateAtMinutes(dateStr, nextEnd)), all_day: 0 };
      this._commitAnalogClockEventChange(eventId, patch, 'イベントリサイズ');
    };
    this._setClockRangePreview(mode, nextStart, nextEnd, 'resize');
    document.addEventListener('pointermove', onMove);
    document.addEventListener('pointerup', onUp);
    document.addEventListener('pointercancel', onCancel);
  };

  CalendarComponent.prototype._updateAnalogClockHands = function(mode) {
    const root = this._contentEl?.querySelector?.('.gb-cal-clock-svg');
    if (!root) return;
    const now = new Date();
    const hourAngle = mode === 24
      ? (now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600) * 15
      : ((now.getHours() % 12) + now.getMinutes() / 60 + now.getSeconds() / 3600) * 30;
    const minuteAngle = (now.getMinutes() + now.getSeconds() / 60) * 6;
    const secondAngle = now.getSeconds() * 6;
    root.querySelector('[data-clock-hand="hour"]')?.setAttribute('transform', `rotate(${hourAngle} ${CX} ${CY})`);
    root.querySelector('[data-clock-hand="minute"]')?.setAttribute('transform', `rotate(${minuteAngle} ${CX} ${CY})`);
    root.querySelector('[data-clock-hand="second"]')?.setAttribute('transform', `rotate(${secondAngle} ${CX} ${CY})`);
  };

  CalendarComponent.prototype._syncAnalogClockTimer = function(mode) {
    this._updateAnalogClockHands(mode);
    if (this._analogClockTimer) clearInterval(this._analogClockTimer);
    this._analogClockTimer = setInterval(() => this._updateAnalogClockHands(mode), 1000);
  };

  CalendarComponent.prototype._clearAnalogClockTimer = function() {
    if (this._analogClockTimer) clearInterval(this._analogClockTimer);
    this._analogClockTimer = null;
  };
})();

;

/* === gb-tool-calendar-sync.js === */
;
/* ==============================
   gb-tool-calendar-sync.js: Calendar external sync UI
   ============================== */

(() => {
  if (typeof CalendarComponent === 'undefined') return;

  function _calSyncEsc(value) {
    return MeldexEscape.html(value);
  }

  function _syncStatusLabel(connected, available = true) {
    if (!available) return '<span class="gb-cal-sync-status-unavailable">利用不可</span>';
    return connected ? '<span class="gb-cal-sync-status-connected">接続済み</span>' : '未接続';
  }

  function _syncCard(title, body, extraClass = '') {
    return `<div class="gb-cal-sync-card${extraClass ? ` ${extraClass}` : ''}">
      <div class="gb-cal-sync-card-title">${title}</div>
      ${body}
    </div>`;
  }

  // Google Calendar / Microsoft Calendar の自動定期同期（差分取得）の間隔。
  // Google ToDo（_ensureGoogleTasksAutoSync）と同じ5分間隔だが、あちらは既存の回帰テストが
  // 文字列一致で参照しているため定数を共有せず、この2系統専用の定数として1箇所にまとめる。
  const CAL_EXT_AUTO_SYNC_INTERVAL_MS = 5 * 60 * 1000;
  // 連続失敗がこの回数に達したら、次回モーダルを開いた時に状態表示を出す。
  const CAL_EXT_AUTO_SYNC_FAILURE_NOTICE_THRESHOLD = 2;

  function _calSyncIsDropboxMode() {
    try {
      return !!(window.MeldexRuntimeAdapter && typeof window.MeldexRuntimeAdapter.isDropboxMode === 'function' && window.MeldexRuntimeAdapter.isDropboxMode());
    } catch {
      return false;
    }
  }

  // iPhone購読用.icsの自動更新（gb-cal-ics-subscribe.js）を、Google/Microsoftカレンダーの
  // 自動同期サイクル成功後に便乗させる単一の呼び出し口。Cloud以外・未購読（有効フラグ無し）
  // では即bailする（autoRefreshIfEnabled内部のガード）ため、Desktopでは実質no-op。
  function _icsAutoRefreshOnSyncTick() {
    if (!_calSyncIsDropboxMode()) return;
    try {
      window.MeldexCalIcsSubscribe?.autoRefreshIfEnabled?.().catch((err) => {
        console.warn('[CalendarComponent] iPhone購読用.icsの自動更新に失敗:', err);
      });
    } catch (err) {
      console.warn('[CalendarComponent] iPhone購読用.icsの自動更新に失敗:', err);
    }
  }

  function _autoSyncStatusHtml(connected, failureCount) {
    if (!connected) return '';
    const notice = (failureCount || 0) >= CAL_EXT_AUTO_SYNC_FAILURE_NOTICE_THRESHOLD
      ? '<div class="gb-cal-sync-auto-status-error">自動同期が連続で失敗しています。手動で取得・送信してください。</div>'
      : '';
    return `<div class="gb-cal-sync-auto-status">自動同期: 5分ごと ${fieldHelp('接続中は5分ごとに新着・変更・削除を自動で同期します。Meldexを起動している間のみ実行されます。')}</div>${notice}`;
  }

  function _openHttpUrl(value) {
    try {
      const url = new URL(String(value || ''));
      if (url.protocol === 'https:' || url.protocol === 'http:') window.open(url.href, '_blank');
    } catch {}
  }

  function _googleTasksCallbackUrl() {
    const base = typeof API_BASE === 'string' ? API_BASE : '/api';
    try { return new URL(base + '/cal/sync/google/tasks/callback', window.location.origin).href; }
    catch { return window.location.origin + '/api/cal/sync/google/tasks/callback'; }
  }

  function _closeSyncOverlay(o) {
    if (typeof o?._gbCloseSyncModal === 'function') o._gbCloseSyncModal();
    else o?.remove?.();
  }

  // Cloud（Dropboxモード）向けの案内文・カード出し分け。gb-cal-cloud-sync.js /
  // gb-cal-oauth-browser.js / gb-cal-ics-subscribe.js が未実装の機能（Google ToDo・
  // iCal URL購読）はボタンごと非表示にする（行き止まりUI禁止。cloud-mobile-product
  // -quality-gate.md 準拠）。
  function _cloudGoogleAuthHelp() {
    return fieldHelp('Google Cloud Consoleで「OAuthクライアントID」（種類: ウェブアプリケーション）を作成し、'
      + `承認済みのリダイレクトURIに ${window.location.origin}/oauth-callback.html を追加してください。`
      + '認証情報はこの端末内の専用保存領域で管理され、Dropboxには平文で保存されません。');
  }

  function _cloudMicrosoftAuthHelp() {
    return fieldHelp('Microsoft Entra管理センターでアプリを登録し、プラットフォームを「シングルページアプリケーション(SPA)」にして、'
      + `リダイレクトURIに ${window.location.origin}/oauth-callback.html を追加してください。`
      + 'APIのアクセス許可に Calendars.ReadWrite / offline_access を追加してください。');
  }

  // triggerEl: このモーダルを開いた「外側の本来のトリガー要素」。省略時（外部からの
  // 新規オープン）は現在のフォーカス位置を採用する。_googleCalAuth 等が
  // 「閉じてすぐ作り直す」ため内部再生成する際は、直前のモーダルが保持していた
  // トリガー要素（o._gbSyncOpener）をそのまま引き継ぐ。再生成の瞬間の
  // document.activeElement は直前のモーダルごと消える内部要素（認証ボタン等）に
  // なっており、それを拾うと二度と外側へフォーカスを戻せなくなるため。
  CalendarComponent.prototype._showSyncModal = async function(triggerEl) {
    const opener = (triggerEl instanceof HTMLElement && triggerEl.isConnected)
      ? triggerEl
      : (document.activeElement instanceof HTMLElement ? document.activeElement : null);
    const cloud = _calSyncIsDropboxMode();
    const isAdmin = !!this._calUserIsAdmin?.();
    let syncStatus = {};
    if (isAdmin) {
      try { syncStatus = await apiFetch('/cal/sync/status'); } catch {}
    }
    const google = syncStatus.google || {};
    const googleTasks = syncStatus.googleTasks || {};
    const microsoft = syncStatus.microsoft || {};
    const icsEnabled = cloud && !!window.MeldexCalIcsSubscribe?.isAutoRefreshEnabled?.();
    const content = document.createElement('div');
    content.className = 'gb-cal-sync-content';
    content.innerHTML = `
      ${_syncCard('Google Calendar', `
        <div class="gb-cal-sync-status">ステータス: ${_syncStatusLabel(!!google.connected, !!google.available)}</div>
        ${!google.connected && google.available ? `
          <div class="field"><label>Client ID ${cloud ? _cloudGoogleAuthHelp() : ''}</label><input class="sync-gcal-id" type="text" placeholder="Google Cloud Console で取得"></div>
          <div class="field"><label>Client Secret</label><input class="sync-gcal-secret" type="password"></div>
          <button class="sync-gcal-auth gb-cal-sync-action primary" type="button">Googleにログイン</button>` : ''}
        ${google.connected ? '<div class="gb-cal-sync-actions"><button class="sync-gcal-pull gb-cal-sync-action" type="button">Googleから取得</button><button class="sync-gcal-push gb-cal-sync-action" type="button">Googleに送信</button></div>' : ''}
        ${_autoSyncStatusHtml(!!google.connected, this._googleCalAutoSyncFailures)}
      `, 'gb-cal-sync-admin-only')}
      ${_syncCard('Google ToDo', `
        <div class="gb-cal-sync-status">ステータス: ${_syncStatusLabel(!!googleTasks.connected, !!googleTasks.available)}</div>
        ${!googleTasks.connected && googleTasks.available !== false ? (cloud ? `
          <div class="field"><label>Client ID ${_cloudGoogleAuthHelp()}</label><input class="sync-gtask-id" type="text" placeholder="Google Cloud Console で取得"></div>
          <div class="field"><label>Client Secret</label><input class="sync-gtask-secret" type="password"></div>
          <button class="sync-gtask-auth gb-cal-sync-action primary" type="button">Google ToDoにログイン</button>` : `
          <div class="field"><label>Client ID</label><input class="sync-gtask-id" type="text" placeholder="Google Cloud Console で取得"></div>
          <button class="sync-gtask-auth gb-cal-sync-action primary" type="button">Google ToDoにログイン</button>
          <div class="sync-gtask-auth-status gb-cal-sync-status gb-cal-sync-auth-status"></div>`) : ''}
        ${googleTasks.connected ? '<div class="gb-cal-sync-actions"><button class="sync-gtask-sync gb-cal-sync-action" type="button">Google ToDoと同期</button></div>' : ''}
      `, 'gb-cal-sync-admin-only')}
      ${_syncCard('Microsoft Calendar', `
        <div class="gb-cal-sync-status">ステータス: ${_syncStatusLabel(!!microsoft.connected, !!microsoft.available)}</div>
        ${!microsoft.connected && microsoft.available ? `
          <div class="field"><label>Application (client) ID ${cloud ? _cloudMicrosoftAuthHelp() : ''}</label><input class="sync-ms-id" type="text" placeholder="Microsoft Entra のアプリID"></div>
          <div class="field"><label>Tenant</label><input class="sync-ms-tenant" type="text" value="${_calSyncEsc(microsoft.tenant || 'common')}"></div>
          <button class="sync-ms-auth gb-cal-sync-action primary" type="button">Microsoftにログイン</button>
          <div class="sync-ms-auth-status gb-cal-sync-status gb-cal-sync-auth-status"></div>` : ''}
        ${microsoft.connected ? '<div class="gb-cal-sync-actions"><button class="sync-ms-pull gb-cal-sync-action" type="button">Microsoftから取得</button><button class="sync-ms-push gb-cal-sync-action" type="button">Microsoftに送信</button></div>' : ''}
        ${_autoSyncStatusHtml(!!microsoft.connected, this._microsoftCalAutoSyncFailures)}
      `, 'gb-cal-sync-admin-only')}
      ${_syncCard('iCal / .ics', !isAdmin ? `
        <div class="gb-cal-sync-status">本人の.icsファイルをインポート・エクスポートできます。</div>
        <div class="gb-cal-sync-actions">
          <button class="sync-ical-import gb-cal-sync-action" type="button">.icsインポート</button>
          <button class="sync-ical-export gb-cal-sync-action" type="button">.icsエクスポート</button>
        </div>
      ` : cloud ? `
        <div class="gb-cal-sync-status">.icsファイルをインポート・エクスポートできます${fieldHelp('認証付きURLからの定期取り込みは、静的ホスティング(CORS制約)のため現時点では利用できません。取得したファイルを.icsインポートしてください。')}</div>
        <div class="gb-cal-sync-actions">
          <button class="sync-ical-import gb-cal-sync-action" type="button">.icsインポート</button>
          <button class="sync-ical-export gb-cal-sync-action" type="button">.icsエクスポート</button>
        </div>
      ` : `
        <div class="gb-cal-sync-status">.icsファイル、または認証付きのiCal URLから取り込めます。</div>
        <div class="field"><label>iCal URL</label><input class="sync-ical-url" type="url" placeholder="https://example.com/calendar.ics"></div>
        <div class="gb-cal-sync-split">
          <div class="field"><label>ユーザー名</label><input class="sync-ical-user" type="text"></div>
          <div class="field"><label>パスワード</label><input class="sync-ical-pass" type="password"></div>
        </div>
        <div class="gb-cal-sync-actions">
          <button class="sync-ical-url-import gb-cal-sync-action" type="button">URLから取得</button>
          <button class="sync-ical-import gb-cal-sync-action" type="button">.icsインポート</button>
          <button class="sync-ical-export gb-cal-sync-action" type="button">.icsエクスポート</button>
        </div>
      `)}
      ${cloud ? _syncCard('iPhoneの照会カレンダー', `
        <div class="gb-cal-sync-status">Meldexの予定をDropbox経由で読み取り専用購読できます${fieldHelp('iPhoneの「設定」→「カレンダー」→「アカウントを追加」→「照会（購読）カレンダーを追加」で、作成したURLを登録してください。URLを知っている人は誰でも閲覧できる公開リンクです。更新はMeldexでカレンダーを開いている間に反映されます（Google/Microsoftカレンダーの自動同期のタイミングに便乗するため、どちらも未接続の場合は自動更新されません。その場合は「購読用URLを作成」を押し直すと最新化されます）。双方向に同期したい場合はGoogle/Microsoftカレンダー連携をご利用ください。')}</div>
        <div class="gb-cal-sync-status">URLを知っている人は誰でも閲覧できる公開リンクです</div>
        <div class="sync-ics-result gb-cal-sync-status gb-cal-sync-auth-status">${icsEnabled ? '購読用ファイルの自動更新: Meldexでカレンダーを開いている間' : ''}</div>
        <div class="gb-cal-sync-actions"><button class="sync-ics-create gb-cal-sync-action primary" type="button">購読用URLを作成</button></div>
      `, 'gb-cal-sync-admin-only') : ''}
    `;
    if (!isAdmin) {
      content.querySelectorAll('.gb-cal-sync-admin-only').forEach((card) => card.remove());
    }
    const closeButton = document.createElement('button');
    closeButton.className = 'sync-close gb-btn gb-btn-quiet gb-cal-sync-action';
    closeButton.type = 'button';
    closeButton.textContent = '閉じる';
    closeButton.setAttribute('aria-label', 'カレンダー同期を閉じる');
    closeButton.dataset.e2eId = 'calendar-sync-close';
    const modalApi = window.GBUI.createModal({
      id: 'calendar-tool-sync',
      title: 'カレンダー同期',
      body: content,
      footer: closeButton,
      variant: 'mobile-sheet',
      extraClass: 'gb-cal-sync-modal',
      initialFocus: '.sync-gcal-id, .sync-gcal-pull, .sync-gtask-id, .sync-gtask-sync, .sync-close',
      closeLabel: 'カレンダー同期を閉じる',
      closeOnEsc: true,
      closeOnOverlay: true,
      // 外側の本来のトリガー要素を明示的に指定する。指定した要素が閉じる時点で
      // 接続済みなら、document.activeElement の暗黙キャプチャより優先される
      // （gb-ui.js の _restoreOpenerFocus 参照）。
      returnFocus: () => (opener && opener.isConnected) ? opener : null,
      onClose: () => {
        if (o._msPollTimer) clearTimeout(o._msPollTimer);
        if (o._gtaskPollTimer) clearTimeout(o._gtaskPollTimer);
      },
    });
    const o = modalApi.overlay;
    // 内部再生成（_googleCalAuth 等）が引き継げるよう、解決済みのトリガー要素を
    // overlay自身へ保持しておく。
    o._gbSyncOpener = opener;
    o.classList.add('gb-cal-modal-overlay');
    o.dataset.e2eId = 'calendar-sync-overlay';
    modalApi.modal.classList.add('gb-cal-modal');
    modalApi.modal.dataset.e2eId = 'calendar-sync-dialog';
    modalApi.body.classList.add('gb-cal-sync-body');
    modalApi.body.dataset.e2eId = 'calendar-sync-body';
    modalApi.footer.classList.add('gb-cal-sync-footer');
    const close = (reason = 'programmatic') => {
      if (o._msPollTimer) clearTimeout(o._msPollTimer);
      if (o._gtaskPollTimer) clearTimeout(o._gtaskPollTimer);
      modalApi.close(reason);
    };
    o._gbCloseSyncModal = close;
    closeButton.addEventListener('click', () => close('close-button'));
    modalApi.open();
    o.querySelector('.sync-gcal-auth')?.addEventListener('click', () => (cloud ? this._googleCalAuthCloud(o) : this._googleCalAuth(o)));
    o.querySelector('.sync-gcal-pull')?.addEventListener('click', () => this._googleCalPull(o));
    o.querySelector('.sync-gcal-push')?.addEventListener('click', () => this._googleCalPush());
    o.querySelector('.sync-gtask-auth')?.addEventListener('click', () => (cloud ? this._googleTasksAuthCloud(o) : this._googleTasksAuth(o)));
    o.querySelector('.sync-gtask-sync')?.addEventListener('click', () => this._googleTasksSync());
    o.querySelector('.sync-ms-auth')?.addEventListener('click', () => (cloud ? this._microsoftCalAuthCloud(o) : this._microsoftCalAuth(o)));
    o.querySelector('.sync-ms-pull')?.addEventListener('click', () => this._microsoftCalPull(o));
    o.querySelector('.sync-ms-push')?.addEventListener('click', () => this._microsoftCalPush());
    o.querySelector('.sync-ical-url-import')?.addEventListener('click', () => this._icalUrlImport(o));
    o.querySelector('.sync-ical-import')?.addEventListener('click', () => this._icalImport());
    o.querySelector('.sync-ical-export')?.addEventListener('click', () => this._icalExport());
    o.querySelector('.sync-ics-create')?.addEventListener('click', () => this._icsSubscribeCreate(o));
  };

  CalendarComponent.prototype._googleCalAuth = async function(o) {
    const id = o.querySelector('.sync-gcal-id')?.value.trim();
    const secret = o.querySelector('.sync-gcal-secret')?.value.trim();
    if (!id || !secret) { this._showStatus('Client IDとSecretを入力してください', true); return; }
    try {
      const res = await apiPost('/cal/sync/google/auth', { client_id: id, client_secret: secret });
      this._showStatus(res.message || 'Google認証成功');
      _closeSyncOverlay(o);
      this._showSyncModal(o._gbSyncOpener);
    } catch (e) {
      this._showStatus('Google認証失敗: ' + e.message, true);
    }
  };

  // Cloud（Dropboxモード）向けのGoogle認証。デスクトップ版はローカルサーバー
  // ポップアップ方式（run_local_server）だが、静的ホスティングにサーバーは無いため
  // ブラウザ完結のPKCEポップアップ（gb-cal-oauth-browser.js）を使う。ポップアップ
  // ブロッカー回避のため、クリックハンドラの中でawaitを挟む前に同期的に開く。
  CalendarComponent.prototype._googleCalAuthCloud = async function(o) {
    const id = o.querySelector('.sync-gcal-id')?.value.trim();
    const secret = o.querySelector('.sync-gcal-secret')?.value.trim();
    if (!id || !secret) { this._showStatus('Client IDとSecretを入力してください', true); return; }
    let popup;
    try {
      popup = window.MeldexCalOAuthBrowser.openBlankPopup('Google');
    } catch (e) {
      this._showStatus(e.message, true);
      return;
    }
    this._showStatus('Googleのログイン画面で認証してください...');
    try {
      const res = await window.MeldexCalCloudSync.authorizeGoogle({ clientId: id, clientSecret: secret, popup });
      this._showStatus(res.message || 'Google認証成功');
      _closeSyncOverlay(o);
      this._showSyncModal(o._gbSyncOpener);
    } catch (e) {
      this._showStatus('Google認証失敗: ' + e.message, true);
    }
  };

  CalendarComponent.prototype._googleCalPull = async function() {
    this._showStatus('Googleカレンダーから取得中...');
    try {
      const res = await apiPost('/cal/sync/google/pull', { user: this._getUser() });
      this._showStatus(`取得完了: ${res.imported}件インポート, ${res.updated}件更新`);
      await this._loadEvents();
      this._render();
    } catch (e) {
      this._showStatus('Google同期失敗: ' + e.message, true);
    }
  };

  CalendarComponent.prototype._googleCalPush = async function() {
    this._showStatus('Googleカレンダーに送信中...');
    try {
      const res = await apiPost('/cal/sync/google/push', { user: this._getUser() });
      if (res?.ok === false || (res.failed || 0) > 0) this._showStatus(`Google送信一部失敗: ${res.pushed || 0}件送信 / ${res.failed || 0}件失敗`, true);
      else this._showStatus(`送信完了: ${res.pushed}件プッシュ`);
    } catch (e) {
      this._showStatus('Google送信失敗: ' + e.message, true);
    }
  };

  // Google Calendar の自動定期同期（差分取得→ローカル変更の送信）。Google ToDoの
  // _ensureGoogleTasksAutoSync と同じライフサイクル（activate時に開始・deactivate/destroy時に停止・
  // 多重起動防止）。Cloud（Dropboxモード）も v0.7.138 以降は同じ5分間隔で動く
  // （gb-cal-cloud-sync.js が /cal/sync/google/pull|push を実装したため）。
  CalendarComponent.prototype._ensureGoogleCalAutoSync = function() {
    if (!this._calUserIsAdmin?.()) {
      this._clearGoogleCalAutoSync();
      return;
    }
    if (this._googleCalAutoTimer || this._destroyed || !this._active) return;
    this._googleCalAutoTimer = setInterval(() => this._googleCalAutoSync(), CAL_EXT_AUTO_SYNC_INTERVAL_MS);
    setTimeout(() => this._googleCalAutoSync(), 8000);
  };

  CalendarComponent.prototype._clearGoogleCalAutoSync = function() {
    if (this._googleCalAutoTimer) clearInterval(this._googleCalAutoTimer);
    this._googleCalAutoTimer = null;
  };

  CalendarComponent.prototype._googleCalAutoSync = async function() {
    if (!this._calUserIsAdmin?.() || this._destroyed || !this._active || this._googleCalAutoSyncing) return;
    this._googleCalAutoSyncing = true;
    let failed = false;
    try {
      const status = await apiFetch('/cal/sync/status');
      if (!status?.google?.connected) return;
      const user = this._getUser();
      try {
        const pullResult = await apiPost('/cal/sync/google/pull', { user, incremental: true });
        if (pullResult?.ok === false || (pullResult?.failed || 0) > 0) throw new Error('Google Calendar取得が一部失敗しました');
      } catch (e) {
        failed = true;
        console.warn('[CalendarComponent] Google Calendar自動取得に失敗:', e);
      }
      try {
        const pushResult = await apiPost('/cal/sync/google/push', { user });
        if (pushResult?.ok === false || (pushResult?.failed || 0) > 0) throw new Error('Google Calendar送信が一部失敗しました');
      } catch (e) {
        failed = true;
        console.warn('[CalendarComponent] Google Calendar自動送信に失敗:', e);
      }
      if (!failed) {
        await this._loadEvents();
        this._render();
        // コミット前レビュー指摘 #4: iPhone購読用.icsの自動更新は専用タイマーを別に張らず、
        // 既存の外部カレンダー自動同期サイクルに便乗する（未接続時はここへ到達しないため、
        // 「どちらも未接続なら5分毎の専用タイマーは張らない」実態と一致する）。有効フラグが
        // 立っていない場合・Cloud以外では即bailするため、Desktopや未購読時は何もしない。
        _icsAutoRefreshOnSyncTick();
      }
    } catch (e) {
      failed = true;
      console.warn('[CalendarComponent] Google Calendar自動同期に失敗:', e);
    } finally {
      this._googleCalAutoSyncFailures = failed ? (this._googleCalAutoSyncFailures || 0) + 1 : 0;
      this._googleCalAutoSyncing = false;
    }
  };

  // Cloud（Dropboxモード）向けのGoogle ToDo認証。デスクトップ版はリダイレクト+ポーリング方式
  // （ローカルAPIサーバーのコールバックルートへ戻る）だが、静的ホスティングにサーバーは
  // 無いため、Google Calendarと同じブラウザ完結PKCEポップアップ（gb-cal-oauth-browser.js）
  // を使う。カレンダー接続とは独立したトークンとして保存する（gb-cal-cloud-tasks.js参照。
  // スコープが異なるため、カレンダーの接続状態やトークンを流用しない）。
  CalendarComponent.prototype._googleTasksAuthCloud = async function(o) {
    const id = o.querySelector('.sync-gtask-id')?.value.trim();
    const secret = o.querySelector('.sync-gtask-secret')?.value.trim();
    if (!id || !secret) { this._showStatus('Client IDとSecretを入力してください', true); return; }
    let popup;
    try {
      popup = window.MeldexCalOAuthBrowser.openBlankPopup('Google');
    } catch (e) {
      this._showStatus(e.message, true);
      return;
    }
    this._showStatus('Googleのログイン画面で認証してください...');
    try {
      const res = await window.MeldexCalCloudTasks.authorizeGoogleTasks({ clientId: id, clientSecret: secret, popup });
      this._showStatus(res.message || 'Google ToDo認証成功');
      _closeSyncOverlay(o);
      this._showSyncModal(o._gbSyncOpener);
    } catch (e) {
      this._showStatus('Google ToDo認証失敗: ' + e.message, true);
    }
  };

  CalendarComponent.prototype._googleTasksAuth = async function(o) {
    const clientId = o.querySelector('.sync-gtask-id')?.value.trim();
    const statusEl = o.querySelector('.sync-gtask-auth-status');
    if (!clientId) { this._showStatus('Google ToDoのClient IDを入力してください', true); return; }
    if (o._gtaskPollTimer) clearTimeout(o._gtaskPollTimer);
    try {
      const res = await apiPost('/cal/sync/google/tasks/auth-url', { client_id: clientId, redirect_uri: _googleTasksCallbackUrl() });
      if (statusEl) statusEl.textContent = 'Googleログイン画面で接続を完了してください。';
      _openHttpUrl(res.auth_url);
      this._pollGoogleTasksAuth(o, Date.now() + 5 * 60 * 1000);
    } catch (e) {
      this._showStatus('Google ToDo認証開始に失敗: ' + e.message, true);
    }
  };

  CalendarComponent.prototype._pollGoogleTasksAuth = function(o, expiresAt) {
    if (!document.body.contains(o)) return;
    if (Date.now() > expiresAt) {
      this._showStatus('Google ToDo認証の待機時間が切れました', true);
      return;
    }
    const statusEl = o.querySelector('.sync-gtask-auth-status');
    o._gtaskPollTimer = setTimeout(async () => {
      try {
        const status = await apiFetch('/cal/sync/status');
        if (status?.googleTasks?.connected) {
          this._showStatus('Google ToDo認証成功');
          _closeSyncOverlay(o);
          this._showSyncModal(o._gbSyncOpener);
          return;
        }
        if (statusEl) statusEl.textContent = 'Googleログイン完了を待っています...';
        this._pollGoogleTasksAuth(o, expiresAt);
      } catch (e) {
        this._showStatus('Google ToDo認証確認に失敗: ' + e.message, true);
      }
    }, 3000);
  };

  CalendarComponent.prototype._googleTasksSync = async function(options = {}) {
    if (this._googleTasksSyncing) return;
    this._googleTasksSyncing = true;
    const progress = !options.silent ? window.MeldexOperationProgress?.begin?.({
      kind: 'calendar-sync',
      label: 'Google ToDoと同期しています',
      mode: 'indeterminate',
      showInTray: true,
      priority: 35,
    }) : null;
    try {
      if (!options.silent && !progress) this._showStatus('Google ToDoと同期中...');
      const res = await apiPost('/cal/sync/google/tasks/sync', { user: this._getUser(), automatic: !!options.silent });
      progress?.update?.({ phase: '表示を更新しています' });
      await this._loadTasks();
      this._render();
      this._renderTodayTasks();
      if (!options.silent) {
        const summary = `Google ToDo同期完了: ${res.imported || 0}件取得, ${res.pushed || 0}件送信, ${res.updated || 0}件更新`;
        if (progress) progress.succeed({ summary: summary });
        else this._showStatus(summary);
      }
    } catch (e) {
      if (!options.silent) {
        const message = 'Google ToDo同期失敗: ' + e.message;
        if (progress) progress.fail({ error: message });
        else this._showStatus(message, true);
      }
    } finally {
      this._googleTasksSyncing = false;
    }
  };

  CalendarComponent.prototype._ensureGoogleTasksAutoSync = function() {
    if (!this._calUserIsAdmin?.()) {
      this._clearGoogleTasksAutoSync();
      return;
    }
    if (this._googleTasksAutoTimer || this._destroyed || !this._active) return;
    this._googleTasksAutoTimer = setInterval(() => this._googleTasksAutoSync(), 5 * 60 * 1000);
    setTimeout(() => this._googleTasksAutoSync(), 5000);
  };

  CalendarComponent.prototype._clearGoogleTasksAutoSync = function() {
    if (this._googleTasksAutoTimer) clearInterval(this._googleTasksAutoTimer);
    this._googleTasksAutoTimer = null;
  };

  CalendarComponent.prototype._googleTasksAutoSync = async function() {
    if (!this._calUserIsAdmin?.() || this._destroyed || !this._active || this._googleTasksSyncing) return;
    try {
      const status = await apiFetch('/cal/sync/status');
      if (!status?.googleTasks?.connected) return;
      await this._googleTasksSync({ silent: true });
    } catch {}
  };

  CalendarComponent.prototype._microsoftCalAuth = async function(o) {
    const clientId = o.querySelector('.sync-ms-id')?.value.trim();
    const tenant = o.querySelector('.sync-ms-tenant')?.value.trim() || 'common';
    const statusEl = o.querySelector('.sync-ms-auth-status');
    if (!clientId) { this._showStatus('MicrosoftのApplication IDを入力してください', true); return; }
    if (o._msPollTimer) clearTimeout(o._msPollTimer);
    try {
      const res = await apiPost('/cal/sync/microsoft/device-code', { client_id: clientId, tenant });
      const code = _calSyncEsc(res.user_code || '');
      const uri = _calSyncEsc(res.verification_uri || '');
      if (statusEl) statusEl.innerHTML = `ブラウザで ${uri} を開き、コード <strong>${code}</strong> を入力してください。`;
      if (res.verification_uri) _openHttpUrl(res.verification_uri);
      this._pollMicrosoftAuth(o, { clientId, tenant, deviceCode: res.device_code, interval: Math.max(2, res.interval || 5), expiresAt: Date.now() + Math.max(60, res.expires_in || 900) * 1000 });
    } catch (e) {
      this._showStatus('Microsoft認証開始に失敗: ' + e.message, true);
    }
  };

  CalendarComponent.prototype._pollMicrosoftAuth = function(o, session) {
    if (!session || !session.deviceCode || !document.body.contains(o)) return;
    if (Date.now() > session.expiresAt) {
      this._showStatus('Microsoft認証コードの有効期限が切れました', true);
      return;
    }
    const statusEl = o.querySelector('.sync-ms-auth-status');
    o._msPollTimer = setTimeout(async () => {
      try {
        const res = await apiPost('/cal/sync/microsoft/token', {
          client_id: session.clientId,
          tenant: session.tenant,
          device_code: session.deviceCode,
        });
        if (res.pending) {
          if (statusEl) statusEl.textContent = res.message || 'Microsoftログイン完了を待っています...';
          session.interval = Math.max(session.interval, res.interval || session.interval);
          this._pollMicrosoftAuth(o, session);
          return;
        }
        this._showStatus('Microsoft認証成功');
        _closeSyncOverlay(o);
        this._showSyncModal(o._gbSyncOpener);
      } catch (e) {
        this._showStatus('Microsoft認証失敗: ' + e.message, true);
      }
    }, session.interval * 1000);
  };

  // Cloud（Dropboxモード）向けのMicrosoft認証。デスクトップ版はデバイスコード方式
  // （別画面でコード入力）だが、Cloudはブラウザ完結のSPA向けPKCEポップアップ
  // （gb-cal-oauth-browser.js。クライアントシークレット不要）を使う。
  CalendarComponent.prototype._microsoftCalAuthCloud = async function(o) {
    const clientId = o.querySelector('.sync-ms-id')?.value.trim();
    const tenant = o.querySelector('.sync-ms-tenant')?.value.trim() || 'common';
    if (!clientId) { this._showStatus('MicrosoftのApplication IDを入力してください', true); return; }
    let popup;
    try {
      popup = window.MeldexCalOAuthBrowser.openBlankPopup('Microsoft');
    } catch (e) {
      this._showStatus(e.message, true);
      return;
    }
    this._showStatus('Microsoftのログイン画面で認証してください...');
    try {
      const res = await window.MeldexCalCloudSync.authorizeMicrosoft({ clientId, tenant, popup });
      this._showStatus(res.message || 'Microsoft認証成功');
      _closeSyncOverlay(o);
      this._showSyncModal(o._gbSyncOpener);
    } catch (e) {
      this._showStatus('Microsoft認証失敗: ' + e.message, true);
    }
  };

  CalendarComponent.prototype._microsoftCalPull = async function() {
    this._showStatus('Microsoftカレンダーから取得中...');
    try {
      const res = await apiPost('/cal/sync/microsoft/pull', { user: this._getUser() });
      this._showStatus(`取得完了: ${res.imported}件インポート, ${res.updated}件更新`);
      await this._loadEvents();
      this._render();
    } catch (e) {
      this._showStatus('Microsoft同期失敗: ' + e.message, true);
    }
  };

  CalendarComponent.prototype._microsoftCalPush = async function() {
    this._showStatus('Microsoftカレンダーに送信中...');
    try {
      const res = await apiPost('/cal/sync/microsoft/push', { user: this._getUser() });
      if (res?.ok === false || (res.failed || 0) > 0) this._showStatus(`Microsoft送信一部失敗: ${res.pushed || 0}件送信 / ${res.failed || 0}件失敗`, true);
      else this._showStatus(`送信完了: ${res.pushed}件プッシュ`);
    } catch (e) {
      this._showStatus('Microsoft送信失敗: ' + e.message, true);
    }
  };

  // Microsoft Calendar の自動定期同期（差分取得→ローカル変更の送信）。Google Calendarの
  // _ensureGoogleCalAutoSync と同じライフサイクル・ガード方針。Cloud（Dropboxモード）も
  // v0.7.138 以降は同じ5分間隔で動く（gb-cal-cloud-sync.js 参照）。
  CalendarComponent.prototype._ensureMicrosoftCalAutoSync = function() {
    if (!this._calUserIsAdmin?.()) {
      this._clearMicrosoftCalAutoSync();
      return;
    }
    if (this._microsoftCalAutoTimer || this._destroyed || !this._active) return;
    this._microsoftCalAutoTimer = setInterval(() => this._microsoftCalAutoSync(), CAL_EXT_AUTO_SYNC_INTERVAL_MS);
    setTimeout(() => this._microsoftCalAutoSync(), 8000);
  };

  CalendarComponent.prototype._clearMicrosoftCalAutoSync = function() {
    if (this._microsoftCalAutoTimer) clearInterval(this._microsoftCalAutoTimer);
    this._microsoftCalAutoTimer = null;
  };

  CalendarComponent.prototype._microsoftCalAutoSync = async function() {
    if (!this._calUserIsAdmin?.() || this._destroyed || !this._active || this._microsoftCalAutoSyncing) return;
    this._microsoftCalAutoSyncing = true;
    let failed = false;
    try {
      const status = await apiFetch('/cal/sync/status');
      if (!status?.microsoft?.connected) return;
      const user = this._getUser();
      try {
        const pullResult = await apiPost('/cal/sync/microsoft/pull', { user, incremental: true });
        if (pullResult?.ok === false || (pullResult?.failed || 0) > 0) throw new Error('Microsoft Calendar取得が一部失敗しました');
      } catch (e) {
        failed = true;
        console.warn('[CalendarComponent] Microsoft Calendar自動取得に失敗:', e);
      }
      try {
        const pushResult = await apiPost('/cal/sync/microsoft/push', { user });
        if (pushResult?.ok === false || (pushResult?.failed || 0) > 0) throw new Error('Microsoft Calendar送信が一部失敗しました');
      } catch (e) {
        failed = true;
        console.warn('[CalendarComponent] Microsoft Calendar自動送信に失敗:', e);
      }
      if (!failed) {
        await this._loadEvents();
        this._render();
        // コミット前レビュー指摘 #4: Googleと同じく外部カレンダー自動同期サイクルに便乗して
        // iPhone購読用.icsを更新する。
        _icsAutoRefreshOnSyncTick();
      }
    } catch (e) {
      failed = true;
      console.warn('[CalendarComponent] Microsoft Calendar自動同期に失敗:', e);
    } finally {
      this._microsoftCalAutoSyncFailures = failed ? (this._microsoftCalAutoSyncFailures || 0) + 1 : 0;
      this._microsoftCalAutoSyncing = false;
    }
  };

  CalendarComponent.prototype._icalUrlImport = async function(o) {
    const url = o.querySelector('.sync-ical-url')?.value.trim();
    const username = o.querySelector('.sync-ical-user')?.value.trim();
    const password = o.querySelector('.sync-ical-pass')?.value;
    if (!url) { this._showStatus('iCal URLを入力してください', true); return; }
    this._showStatus('iCal URLから取得中...');
    try {
      const res = await apiPost('/cal/sync/ical/url-import', { url, username, password, user: this._getUser() });
      this._showStatus(`iCal取得完了: ${res.imported}件`);
      await this._loadEvents();
      this._render();
    } catch (e) {
      this._showStatus('iCal URL取得失敗: ' + e.message, true);
    }
  };

  CalendarComponent.prototype._icalImport = function() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.ics,.ical';
    input.addEventListener('change', async () => {
      const file = input.files[0];
      if (!file) return;
      const text = await file.text();
      try {
        const res = await apiPost('/cal/sync/ical/import', { ics: text, user: this._getUser() });
        this._showStatus(`iCalインポート完了: ${res.imported}件`);
        await this._loadEvents();
        this._render();
      } catch (e) {
        this._showStatus('インポート失敗: ' + e.message, true);
      }
    });
    input.click();
  };

  CalendarComponent.prototype._icalExport = async function() {
    const exportSave = window.MeldexExportSave || (typeof MeldexExportSave !== 'undefined' ? MeldexExportSave : null);
    const apiBase = typeof API_BASE !== 'undefined' ? API_BASE : '/api';
    if (!exportSave || typeof exportSave.saveUrl !== 'function') {
      this._showStatus('保存ダイアログを初期化できませんでした', true);
      return;
    }
    await exportSave.saveUrl(apiBase + '/cal/sync/ical/export?user=' + encodeURIComponent(this._getUser()), {
      filename: `calendar-${this._localDateStr(new Date())}.ics`,
      extension: '.ics',
      dialogTitle: 'iCal として保存',
      filetypes: [['iCalファイル', '*.ics'], ['すべてのファイル', '*.*']],
      okMessage: 'iCal を保存しました',
      errorMessage: 'iCal の保存に失敗しました',
    });
  };

  // iPhone向けICS購読リンクの作成（Cloud専用。gb-cal-ics-subscribe.js参照）。
  // Dropboxのsharing.writeスコープが無い既存接続では失敗するため、その場合は
  // ファイルパスを示した手動作成の案内へフォールバックする（行き止まりで終わらせない）。
  CalendarComponent.prototype._icsSubscribeCreate = async function(o) {
    const resultEl = o.querySelector('.sync-ics-result');
    if (!window.MeldexCalIcsSubscribe) {
      this._showStatus('購読機能を初期化できませんでした', true);
      return;
    }
    this._showStatus('購読用ファイルを作成しています...');
    try {
      const res = await window.MeldexCalIcsSubscribe.createSubscriptionLink();
      this._showStatus('購読用URLを作成しました');
      if (resultEl) {
        resultEl.innerHTML = `購読URL: <code class="sync-ics-url">${_calSyncEsc(res.webcalUrl)}</code> `
          + `<button class="sync-ics-copy gb-cal-sync-action" type="button">コピー</button>`;
        resultEl.querySelector('.sync-ics-copy')?.addEventListener('click', async () => {
          try {
            await navigator.clipboard.writeText(res.webcalUrl);
            this._showStatus('購読URLをコピーしました');
          } catch {
            this._showStatus('コピーに失敗しました。URLを選択して手動でコピーしてください', true);
          }
        });
      }
    } catch (e) {
      this._showStatus('購読用URLの作成に失敗: ' + e.message, true);
      if (resultEl) {
        const path = _calSyncEsc(e.manualPath || window.MeldexCalIcsSubscribe.ICS_RELATIVE_PATH);
        resultEl.innerHTML = `自動作成できませんでした。Dropbox上の <code>${path}</code> を右クリックして共有リンクを作成し、`
          + `そのURLをiPhoneの照会カレンダーへ登録してください${fieldHelp('Dropboxアプリまたはdropbox.comで対象ファイルを開き、「共有」→「リンクを作成」で取得できます。')}`;
      }
    }
  };

  const _calSyncOriginalRefreshAfterActivation = CalendarComponent.prototype._refreshAfterActivation;
  CalendarComponent.prototype._refreshAfterActivation = function(...args) {
    const result = _calSyncOriginalRefreshAfterActivation.apply(this, args);
    if (typeof this._ensureGoogleTasksAutoSync === 'function') this._ensureGoogleTasksAutoSync();
    if (typeof this._ensureGoogleCalAutoSync === 'function') this._ensureGoogleCalAutoSync();
    if (typeof this._ensureMicrosoftCalAutoSync === 'function') this._ensureMicrosoftCalAutoSync();
    return result;
  };

  const _calSyncOriginalDeactivate = CalendarComponent.prototype.deactivate;
  CalendarComponent.prototype.deactivate = function(...args) {
    if (typeof this._clearGoogleTasksAutoSync === 'function') this._clearGoogleTasksAutoSync();
    if (typeof this._clearGoogleCalAutoSync === 'function') this._clearGoogleCalAutoSync();
    if (typeof this._clearMicrosoftCalAutoSync === 'function') this._clearMicrosoftCalAutoSync();
    return _calSyncOriginalDeactivate.apply(this, args);
  };

  const _calSyncOriginalDestroy = CalendarComponent.prototype.destroy;
  CalendarComponent.prototype.destroy = function(...args) {
    if (typeof this._clearGoogleTasksAutoSync === 'function') this._clearGoogleTasksAutoSync();
    if (typeof this._clearGoogleCalAutoSync === 'function') this._clearGoogleCalAutoSync();
    if (typeof this._clearMicrosoftCalAutoSync === 'function') this._clearMicrosoftCalAutoSync();
    return _calSyncOriginalDestroy.apply(this, args);
  };
})();

