    displayFilters: bd.displayFilters,
    globalStyleDefaults: typeof bdCaptureGlobalStyleDefaults === 'function' ? bdCaptureGlobalStyleDefaults() : null,
    _numbering: bd._numbering || false,
    _bgColor: bd._bgColor || '',
