          await writeExport(store, join(root, 'Googleスライド', `${safe(row.name, 'Googleスライド')}_${String(row.id).slice(0, 12)}.pdf`), `${DRIVE}/files/${encodeURIComponent(row.id)}/export?mimeType=application%2Fpdf`);
