/* === gb-import-schedule-settings.js === */
;
// gb-import-schedule-settings.js — インポート定期実行の共通設定UI（周期・次回予定・前回結果）。
// WebClipper・インポート定期実行計画 2026-08-04「インターフェース」節で実装。
//
// Notion同期・Xブックマーク・外部取り込みセットの各設定画面は、それぞれの場所で
// 周期を編集できる（gb-notion-sync.js / gb-settings-x-bookmarks.js /
// gb-external-import.js。いずれも /api/import-schedules へ書き込みが委譲される）。
// 本モジュールは、それらを横断する「インポート予定」一覧を1画面にまとめ、
// 他の設定画面にUIを持たないXアカウント投稿の定期実行もここから登録できるように
// する（Meldex.html の編集はレーン外のため、既存の外部取り込み設定画面の末尾へ
// ランタイムでマウントする）。
(function () {
  'use strict';

  const CATEGORY_LABELS = {
    'notion-sync': 'Notion同期',
    'x-bookmarks': 'Xブックマーク',
    'x-account-posts': 'Xアカウント投稿',
    'external-import-set': '外部取り込み',
  };
  const USER_FACING_CATEGORIES = new Set(Object.keys(CATEGORY_LABELS));

  function icon(name, size) {
    return typeof lucide === 'function' ? lucide(name, size || 14) : '';
  }

  function apiReady() {
    return typeof apiFetch === 'function' && typeof apiPost === 'function';
  }

  function isCloudStaticScheduleSurface() {
    return window.MeldexRuntimeAdapter?.isPwaMode?.()
      || ['browser', 'dropbox', 'server'].includes(document.body?.dataset?.cloudMode || '');
  }

  async function confirmAction(message) {
    if (typeof cfConfirm === 'function') return await cfConfirm(message, { danger: true, okLabel: '削除' });
    if (typeof window !== 'undefined' && typeof window.confirm === 'function') return window.confirm(message);
    return false;
  }

  function categoryLabel(category) {
    return CATEGORY_LABELS[category] || '';
  }

  function statusLine(entry) {
    const parts = [];
    if (entry.next_run_display) parts.push(`次回予定: ${entry.next_run_display}`);
    else if (entry.enabled === false) parts.push('手動のみ');
    if (entry.last_run) {
      const label = entry.last_run.status === 'done' ? '成功'
        : (entry.last_run.status === 'error' ? '失敗' : entry.last_run.status);
      parts.push(`前回: ${label}`);
    } else {
      parts.push('前回: なし');
    }
    if (entry.needs_reselect) parts.push('元ファイルが見つからないため停止中。再選択が必要です。');
    else if (entry.needs_attention) parts.push('連続で失敗しています。');
    return parts.join(' / ');
  }

  async function loadSchedules() {
    if (!apiReady()) return [];
    const data = await apiFetch('/import-schedules', { silentError: true });
    return Array.isArray(data?.schedules)
      ? data.schedules.filter(entry => USER_FACING_CATEGORIES.has(String(entry?.category || '')))
      : [];
  }

  function textEl(tag, text, className) {
    const el = document.createElement(tag);
    if (className) el.className = className;
    el.textContent = text || '';
    return el;
  }

  function renderEntryCard(entry, onChanged) {
    const card = document.createElement('div');
    card.className = 'gb-section gb-section--boxed';
    card.style.marginTop = '8px';
    const stableId = String(entry.id).replace(/[^a-zA-Z0-9_-]+/g, '-');
    card.dataset.e2eId = `import-schedule-card-${stableId}`;

    const title = document.createElement('div');
    title.className = 'gb-section-title';
    title.textContent = `${categoryLabel(entry.category)}: ${entry.label || entry.id}`;
    card.appendChild(title);

    const status = textEl('div', statusLine(entry), 'gb-section-desc');
    status.dataset.e2eId = `import-schedule-status-${stableId}`;
    card.appendChild(status);

    const schedContainer = document.createElement('div');
    schedContainer.className = 'gb-section gb-section--boxed';
    schedContainer.style.cssText = 'margin-top:6px;padding:8px;';
    schedContainer.dataset.e2eId = `import-schedule-widget-${stableId}`;
    card.appendChild(schedContainer);

    if (window.MeldexScheduler) {
      window.MeldexScheduler.createWidget(schedContainer, entry.period, async (cfg) => {
        await savePeriod(entry, cfg);
        onChanged();
      });
    }

    const row = document.createElement('div');
    row.className = 'gb-field-row';
    row.style.justifyContent = 'flex-start';
    row.style.flexWrap = 'wrap';
    row.style.marginTop = '6px';

    const runBtn = document.createElement('button');
    runBtn.type = 'button';
    runBtn.className = 'gb-btn gb-btn-sm';
    runBtn.innerHTML = icon('play', 14) + ' 今すぐ実行';
    runBtn.dataset.e2eId = `import-schedule-run-${stableId}`;
    runBtn.setAttribute('aria-label', `${entry.label || entry.id}を今すぐ実行`);
    runBtn.addEventListener('click', async () => {
      runBtn.disabled = true;
      try {
        await apiPost(`/import-schedules/${encodeURIComponent(entry.id)}/run`, {}, { silentError: true });
        await window.MeldexImportProgress?.poll?.();
        status.textContent = '実行を開始しました。進み具合は画面の処理パネルで確認できます。';
      } catch (err) {
        status.textContent = '実行を開始できませんでした: ' + (err.userMessage || err.message || err);
      } finally {
        runBtn.disabled = false;
      }
    });
    row.appendChild(runBtn);

    const deleteBtn = document.createElement('button');
    deleteBtn.type = 'button';
    deleteBtn.className = 'gb-btn gb-btn-sm gb-btn-danger';
    deleteBtn.innerHTML = icon('trash2', 14) + ' 定期実行を削除';
    deleteBtn.dataset.e2eId = `import-schedule-delete-${stableId}`;
    deleteBtn.setAttribute('aria-label', `${entry.label || entry.id}の定期実行設定を削除`);
    deleteBtn.addEventListener('click', async () => {
      const ok = await confirmAction('この定期実行の設定を削除しますか？\n取り込み済みのデータは削除しません。');
      if (!ok) return;
      try {
        await apiFetch(`/import-schedules/${encodeURIComponent(entry.id)}`, { method: 'DELETE', silentError: true });
        onChanged();
      } catch (err) {
        status.textContent = '削除できませんでした: ' + (err.userMessage || err.message || err);
      }
    });
    row.appendChild(deleteBtn);
    card.appendChild(row);

    return card;
  }

  async function savePeriod(entry, period) {
    try {
      await apiPost(`/import-schedules/${encodeURIComponent(entry.id)}`, { period }, { method: 'PATCH', silentError: true });
    } catch (err) {
      if (err && err.status === 400 && entry.category === 'x-account-posts') {
        // 料金確認ゲート: 未承諾のまま有効化しようとした場合
        window.__gbImportScheduleCostNoticeError = err.userMessage || err.message || String(err);
      }
    }
  }

  function renderAddAccountPostsForm(container, onAdded) {
    const section = document.createElement('section');
    section.className = 'gb-section gb-section--boxed';
    section.dataset.e2eId = 'import-schedule-add-x-account-posts';

    const title = document.createElement('div');
    title.className = 'gb-section-title';
    title.innerHTML = `${icon('atSign', 14)} Xアカウント投稿の定期保存を追加`;
    section.appendChild(title);

    // 同意・料金に関わる開示はツールチップへ隠しきらず、可視のまま残す
    // （UI共通ルール: 同意・プライバシーに関わる開示は短い1文を可視で残す）。
    section.appendChild(textEl(
      'div',
      'X APIの利用量に応じて料金が発生する場合があります。定期実行は既定で無効です。',
      'gb-section-desc'
    ));

    const row = document.createElement('div');
    row.className = 'gb-field-row';
    row.style.flexWrap = 'wrap';

    const usernameInput = document.createElement('input');
    usernameInput.type = 'text';
    usernameInput.className = 'gb-input';
    usernameInput.placeholder = '@ユーザー名';
    usernameInput.setAttribute('aria-label', 'Xのユーザー名');
    usernameInput.dataset.e2eId = 'import-schedule-x-account-username';
    row.appendChild(usernameInput);

    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'gb-btn gb-btn-sm';
    addBtn.innerHTML = icon('plus', 14) + ' 追加';
    addBtn.dataset.e2eId = 'import-schedule-x-account-add';
    row.appendChild(addBtn);

    const message = textEl('div', '', 'gb-section-desc');
    message.setAttribute('role', 'status');
    message.setAttribute('aria-live', 'polite');

    addBtn.addEventListener('click', async () => {
      const username = usernameInput.value.trim().replace(/^@/, '');
      if (!username) {
        message.textContent = 'ユーザー名を入力してください。';
        return;
      }
      const existing = await loadSchedules();
      if (existing.some((entry) => entry.category === 'x-account-posts'
        && String(entry.target_ref?.username || '').toLowerCase() === username.toLowerCase())) {
        message.textContent = `@${username} はすでに一覧にあります。`;
        return;
      }
      addBtn.disabled = true;
      try {
        await apiPost('/import-schedules', {
          category: 'x-account-posts',
          target_ref: { username },
          label: `@${username}`,
          period: { type: 'off' },
        }, { silentError: true });
        usernameInput.value = '';
        message.textContent = '追加しました。定期実行はOFFです。';
        onAdded();
      } catch (err) {
        message.textContent = '追加できませんでした: ' + (err.userMessage || err.message || err);
      } finally {
        addBtn.disabled = false;
      }
    });

    section.appendChild(row);
    section.appendChild(message);
    container.appendChild(section);
  }

  async function refresh(root) {
    const list = root.querySelector('.import-schedule-list');
    if (!list) return;
    list.textContent = '読み込み中...';
    try {
      const schedules = await loadSchedules();
      list.textContent = '';
      if (!schedules.length) {
        list.appendChild(textEl('div', '定期実行はまだ設定されていません。', 'gb-section-desc'));
        return;
      }
      schedules.forEach((entry) => {
        list.appendChild(renderEntryCard(entry, () => refresh(root)));
      });
    } catch (err) {
      list.textContent = '';
      list.appendChild(textEl('div', '取得できませんでした: ' + (err.userMessage || err.message || err), 'gb-section-desc'));
    }
  }

  // render()/mount() は呼び出しのたびに一覧を再取得する（初回はDOM構築込み、
  // 2回目以降は既存のセクションへ refresh() のみ行う）。返り値は一覧の取得・
  // 描画が完了する Promise なので、呼び出し側は await して完了を待てる
  // （設定画面を開くたびに新しい定期実行が反映され、E2E等からも
  // 「カードが描画され終わっているか」を確実に待てるようにするため）。
  function render(container) {
    if (!container) return Promise.resolve();
    if (isCloudStaticScheduleSurface()) {
      container.querySelector('[data-e2e-id="import-schedule-settings-root"]')?.remove();
      delete container.dataset.importScheduleMounted;
      return Promise.resolve();
    }
    if (container.dataset.importScheduleMounted === '1') {
      const existing = container.querySelector('[data-e2e-id="import-schedule-settings-root"]');
      return existing ? refresh(existing) : Promise.resolve();
    }
    container.dataset.importScheduleMounted = '1';
    const section = document.createElement('section');
    section.className = 'gb-section gb-section--boxed';
    section.dataset.e2eId = 'import-schedule-settings-root';
    section.style.marginTop = '12px';
    section.innerHTML = `
      <div class="gb-section-title">${icon('calendarClock', 14)} インポート予定（定期実行）</div>
      <div class="gb-section-desc">Notion同期・Xブックマーク・外部取り込みの定期実行をまとめて確認・変更できます。定期実行は既定で無効です。</div>
    `;
    container.appendChild(section);

    renderAddAccountPostsForm(section, () => refresh(section));

    const list = document.createElement('div');
    list.className = 'import-schedule-list';
    list.dataset.e2eId = 'import-schedule-list';
    section.appendChild(list);

    return refresh(section);
  }

  // 既存の外部取り込み設定画面の末尾へランタイムでマウントする
  // （Meldex.html/Meldex-dev.html への新規コンテナ追加はレーン外のため）。
  function mount(hostContainerId) {
    const host = document.getElementById(hostContainerId || 'external-import-settings-container');
    return host ? render(host) : Promise.resolve();
  }

  window.MeldexImportScheduleSettings = {
    render, mount, refresh, isCloudStaticScheduleSurface,
    isUserFacingCategory: category => USER_FACING_CATEGORIES.has(String(category || '')),
  };
})();

;

/* === gb-import-progress.js === */
;
// 既存のインポート進捗APIをMeldexOperationProgressへ接続する互換ファサード。
// importジョブの再読込復元と、既存のbegin/update/finish呼び出しを共通状態へ統合する。
(function () {
  'use strict';

  const POLL_INTERVAL_MS = 1500;
  const CATEGORY = 'import';
  const KIND_LABELS = {
    'notion-sync': 'Notion同期',
    'x-bookmarks': 'Xブックマーク',
    'x-account-posts': 'Xアカウント投稿',
    'external-import': '外部取り込み',
    'pureref-import': 'PureRef取り込み',
    'enex-import': 'ENEX取り込み',
  };
  const restoredJobs = new Map();
  const foregroundStack = [];
  let pollTimer = null;

  function _progressApi() { return window.MeldexOperationProgress || null; }
  function _kindLabel(kind) { return KIND_LABELS[kind] || kind || 'インポート'; }
  function _apiAvailable() { return typeof apiFetch === 'function'; }

  function _jobLabel(job) {
    const kind = _kindLabel(job?.kind);
    return job?.label ? kind + ': ' + job.label : kind;
  }

  function _activeJobs(jobs) {
    const priority = { running: 0, cancelling: 1, queued: 2 };
    return jobs
      .filter(function (job) { return job.status === 'running' || job.status === 'cancelling' || job.status === 'queued'; })
      .sort(function (a, b) {
        const diff = (priority[a.status] ?? 9) - (priority[b.status] ?? 9);
        if (diff) return diff;
        return (a.started_at || a.queued_at || 0) - (b.started_at || b.queued_at || 0);
      });
  }

  function _syncJob(job) {
    const api = _progressApi();
    if (!api || !job?.id) return null;
    const jobId = String(job.id);
    let handle = api.findByPersistentJobId(jobId) || restoredJobs.get(jobId)?.handle;
    if (!handle) {
      handle = api.begin({
        id: 'job-' + jobId,
        kind: String(job.kind || 'import'),
        label: _jobLabel(job),
        phase: job.status === 'queued' ? '待機中' : String(job.progress?.phase || '準備中'),
        status: job.status,
        mode: Number(job.progress?.total) > 0 ? 'determinate' : 'indeterminate',
        processed: Number(job.progress?.processed) || 0,
        total: Number(job.progress?.total) || null,
        persistentJobId: jobId,
        background: true,
        showImmediately: true,
        priority: job.status === 'running' ? 20 : 10,
      });
    }
    const previous = handle.getState();
    const rawTotal = Number(job.progress?.total);
    let processed = Math.max(0, Number(job.progress?.processed) || 0);
    if (rawTotal > 0 && previous?.total === rawTotal) processed = Math.max(previous.processed || 0, processed);
    handle.update({
      label: _jobLabel(job),
      phase: job.status === 'queued' ? '待機中' : String(job.progress?.phase || '準備中'),
      status: job.status,
      mode: rawTotal > 0 ? 'determinate' : 'indeterminate',
      processed: processed,
      total: rawTotal > 0 ? rawTotal : null,
      currentItem: job.progress?.current_item || job.progress?.current || '',
      rate: job.progress?.rate,
      eta: job.progress?.eta_seconds ?? job.progress?.eta,
      persistentJobId: jobId,
    });
    restoredJobs.set(jobId, { handle: handle, misses: 0 });
    return handle;
  }

  async function _resolveMissingJob(jobId, entry) {
    try {
      const job = await apiFetch('/jobs/' + encodeURIComponent(jobId), { silentError: true });
      entry.misses = 0;
      if (job?.status === 'done') {
        entry.handle.succeed({ summary: job.result?.summary || '取り込みが完了しました' });
        restoredJobs.delete(jobId);
      } else if (job?.status === 'cancelled' || job?.status === 'canceled') {
        entry.handle.cancelled({ summary: '取り込みを中止しました' });
        restoredJobs.delete(jobId);
      } else if (job?.status === 'error') {
        entry.handle.fail({
          error: job.error || '取り込みに失敗しました',
          details: job.result?.failure_samples || job.error_detail?.failure_samples || [],
        });
        restoredJobs.delete(jobId);
      } else if (job) {
        _syncJob(job);
      }
    } catch (error) {
      entry.misses += 1;
      if (entry.misses < 2 || !/404/.test(String(error?.message || ''))) return;
      const status = entry.handle.getState()?.status;
      if (status === 'running' || status === 'queued' || status === 'cancelling') entry.handle.dispose();
      restoredJobs.delete(jobId);
    }
  }

  async function poll() {
    if (!_apiAvailable()) return;
    try {
      const data = await apiFetch('/jobs?category=' + encodeURIComponent(CATEGORY) + '&active_only=1', { silentError: true });
      const active = _activeJobs(Array.isArray(data?.jobs) ? data.jobs : []);
      const seen = new Set();
      active.forEach(function (job) {
        seen.add(String(job.id));
        _syncJob(job);
      });
      const missing = [];
      restoredJobs.forEach(function (entry, jobId) {
        if (!seen.has(jobId)) missing.push(_resolveMissingJob(jobId, entry));
      });
      await Promise.all(missing);
    } catch (_) {
      // 一時的なポーリング失敗では現役表示を消さず、次回復旧を待つ。
    }
  }

  function start() {
    if (pollTimer) return;
    poll();
    pollTimer = setInterval(poll, POLL_INTERVAL_MS);
  }

  function stop() {
    if (!pollTimer) return;
    clearInterval(pollTimer);
    pollTimer = null;
  }

  function beginOperation(label, total, options) {
    const api = _progressApi();
    if (!api) return null;
    const count = Number(total);
    const opts = options || {};
    const handle = api.begin({
      kind: String(opts.kind || 'foreground-operation'),
      label: String(label || '処理中'),
      mode: Number.isFinite(count) && count > 0 ? 'determinate' : 'indeterminate',
      total: Number.isFinite(count) && count > 0 ? count : null,
      processed: 0,
      origin: opts.origin || null,
      originPlacement: opts.originPlacement || 'after',
      background: false,
      delayMs: opts.delayMs,
      showInTray: opts.showInTray !== false,
      cancellable: !!opts.cancellable,
      cancel: opts.cancel,
      retry: opts.retry,
      priority: Number(opts.priority) || 30,
    });
    foregroundStack.push(handle);
    return handle;
  }

  function _resolveForeground(token) {
    if (token && typeof token.update === 'function') return token;
    if (typeof token === 'string') return _progressApi()?.get(token) || null;
    return foregroundStack[foregroundStack.length - 1] || null;
  }

  function updateOperation(processed, label, token) {
    const handle = _resolveForeground(token);
    if (!handle) return;
    const values = { processed: Math.max(0, Number(processed) || 0) };
    if (label) values.label = String(label);
    handle.update(values);
  }

  function finishOperation(token, options) {
    const handle = _resolveForeground(token);
    if (!handle) return;
    const index = foregroundStack.indexOf(handle);
    if (index >= 0) foregroundStack.splice(index, 1);
    handle.succeed(Object.assign({ dismissMs: 0 }, options || {}));
    poll();
  }

  function failOperation(error, token, options) {
    const handle = _resolveForeground(token);
    if (!handle) return;
    const index = foregroundStack.indexOf(handle);
    if (index >= 0) foregroundStack.splice(index, 1);
    handle.fail(Object.assign({ error: error }, options || {}));
  }

  function _init() {
    if (typeof _isTrayAnnotationHost === 'function' && _isTrayAnnotationHost()) return;
    start();
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _init, { once: true });
  else _init();

  window.MeldexImportProgress = {
    start: start,
    stop: stop,
    poll: poll,
    beginOperation: beginOperation,
    updateOperation: updateOperation,
    finishOperation: finishOperation,
    failOperation: failOperation,
  };
})();

;

/* === gb-global-tags.js === */
;
(function () {
  'use strict';

  // ====================================================================
  // グローバルタグ機能 (v2: タググループ対応)
  //   - API ラッパー (タグ / グループ / 対象ファイル別)
  //   - ファイル別タグ編集 UI (オプションパネル下部などに埋め込み)
  //   - タグ管理タブ本体は gb-tag-management.js 側で実装
  // ====================================================================

  let cache = [];
  let targetEditorSeq = 0;
  const targetTagsCache = new Map();
  const targetTagsLastResolved = new Map();
  const targetTagsLatestRequest = new Map();
  let targetTagsRequestSeq = 0;
  let targetEditorCatalogRefreshTimer = null;
  const TARGET_TAGS_CACHE_TTL_MS = 2000;
  const COMPACT_TAG_DISPLAY_LIMIT_KEY = 'meldex.compactTagDisplayLimit.v1';
  const DEFAULT_COMPACT_TAG_DISPLAY_LIMIT = 10;
  const MAX_COMPACT_TAG_DISPLAY_LIMIT = 999;
  let compactTagDisplayLimit = null;

  function normalizeCompactTagDisplayLimit(value) {
    const parsed = Number.parseInt(String(value ?? ''), 10);
    if (!Number.isFinite(parsed)) return DEFAULT_COMPACT_TAG_DISPLAY_LIMIT;
    return Math.max(1, Math.min(MAX_COMPACT_TAG_DISPLAY_LIMIT, parsed));
  }

  function getCompactTagDisplayLimit() {
    if (compactTagDisplayLimit != null) return compactTagDisplayLimit;
    try {
      compactTagDisplayLimit = normalizeCompactTagDisplayLimit(localStorage.getItem(COMPACT_TAG_DISPLAY_LIMIT_KEY));
    } catch {
      compactTagDisplayLimit = DEFAULT_COMPACT_TAG_DISPLAY_LIMIT;
    }
    return compactTagDisplayLimit;
  }

  function setCompactTagDisplayLimit(value) {
    const limit = normalizeCompactTagDisplayLimit(value);
    compactTagDisplayLimit = limit;
    try {
      localStorage.setItem(COMPACT_TAG_DISPLAY_LIMIT_KEY, String(limit));
    } catch (_) {
      // 端末内設定を保存できない環境でも、現在の画面には変更を反映する。
    }
    try {
      window.dispatchEvent(new CustomEvent('meldex:compact-tag-display-limit-changed', {
        detail: { limit },
      }));
    } catch (_) {
      // CustomEventを利用できない古い埋め込み環境でも設定値の保存は成功扱いにする。
    }
    return limit;
  }

  function icon(name, size) {
    return typeof lucide === 'function' ? lucide(name, size || 14) : '';
  }

  function tagColor(value) {
    const color = String(value || '').trim();
    return /^#[0-9a-f]{6}$/i.test(color) ? color : '';
  }

  function effectiveTagColor(tag, groupsById) {
    // タグの実効色 = 所属グループから親へ遡った色を優先し、
    // グループに色がなければタグ自身の色、最後にアクセント色を使う。
    const visited = new Set();
    const groupForId = groupId => (
      groupsById instanceof Map ? groupsById.get(groupId) : groupsById?.[groupId]
    );
    let groupId = tag?.group_id || null;
    while (groupId && groupForId(groupId) && !visited.has(groupId)) {
      visited.add(groupId);
      const group = groupForId(groupId);
      const groupColor = tagColor(group.color);
      if (groupColor) return groupColor;
      groupId = group.parent_id || null;
    }
    const own = tagColor(tag && tag.color);
    return own || 'var(--accent)';
  }

  function compareCatalogRows(a, b) {
    return Number(a?.sort_index || 0) - Number(b?.sort_index || 0)
      || String(a?.name || '').localeCompare(String(b?.name || ''), 'ja');
  }

  function groupOrderMap(groups) {
    const rows = Array.isArray(groups) ? groups : [];
    const byParent = new Map();
    rows.forEach(group => {
      const parentId = group?.parent_id || '';
      if (!byParent.has(parentId)) byParent.set(parentId, []);
      byParent.get(parentId).push(group);
    });
    byParent.forEach(siblings => siblings.sort(compareCatalogRows));
    const order = new Map();
    const visited = new Set();
    let index = 0;
    const visit = group => {
      const id = String(group?.id || '');
      if (!id || visited.has(id)) return;
      visited.add(id);
      order.set(id, index++);
      (byParent.get(id) || []).forEach(visit);
    };
    (byParent.get('') || []).forEach(visit);
    rows.filter(group => !visited.has(String(group?.id || '')))
      .sort(compareCatalogRows)
      .forEach(visit);
    return order;
  }

  function sortTagsByGroupOrder(tags, groups) {
    const rows = Array.isArray(tags) ? [...tags] : [];
    const order = groupOrderMap(groups);
    const uncategorizedRank = order.size + 1;
    return rows.sort((a, b) => {
      const aRank = order.has(String(a?.group_id || '')) ? order.get(String(a.group_id)) : uncategorizedRank;
      const bRank = order.has(String(b?.group_id || '')) ? order.get(String(b.group_id)) : uncategorizedRank;
      return aRank - bRank || compareCatalogRows(a, b);
    });
  }

  function setDataset(element, values) {
    Object.entries(values || {}).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') element.dataset[key] = String(value);
    });
  }

  function createTagChip(tag, options = {}) {
    const groupsById = options.groupsById || {};
    const displayName = String(options.label ?? tag?.name ?? '');
    const chip = document.createElement('span');
    chip.className = 'gb-tag-chip'
      + (options.compact ? ' gb-tag-chip--compact' : '')
      + (options.summary ? ' gb-tag-chip--summary' : '')
      + (options.onRemove ? ' gb-tag-chip--removable' : '')
      + (options.className ? ' ' + options.className : '');
    chip.style.setProperty('--gb-tag-color', options.summary ? 'var(--fg2)' : effectiveTagColor(tag, groupsById));
    chip.title = options.title || displayName;
    setDataset(chip, options.dataset);

    const label = document.createElement(typeof options.onActivate === 'function' ? 'button' : 'span');
    if (label.tagName === 'BUTTON') label.type = 'button';
    label.className = 'gb-tag-chip__label';
    label.textContent = displayName;
    label.title = options.labelTitle || options.title || displayName;
    if (options.ariaLabel) label.setAttribute('aria-label', options.ariaLabel);
    setDataset(label, options.labelDataset);
    if (typeof options.onActivate === 'function') {
      label.addEventListener('click', event => options.onActivate(event, tag));
    }
    chip.appendChild(label);

    const dictionaryScope = String(tag?._dictionary_scope || '');
    if (dictionaryScope === 'admin' || dictionaryScope === 'duplicate') {
      const badge = document.createElement('span');
      badge.className = `gb-tag-chip__scope gb-tag-chip__scope--${dictionaryScope}`;
      badge.tabIndex = 0;
      badge.setAttribute('role', 'button');
      const description = dictionaryScope === 'duplicate'
        ? '管理者タグと個人タグの完全一致。自分の分だけ外しても管理者タグは残ります'
        : '管理者タグ。メンバーは編集・削除できません';
      badge.textContent = dictionaryScope === 'duplicate' ? '重' : '管';
      badge.title = description;
      badge.setAttribute('aria-label', description);
      const explain = event => {
        if (event?.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;
        event?.preventDefault?.();
        event?.stopPropagation?.();
        if (typeof showStatus === 'function') showStatus(description);
      };
      badge.addEventListener('click', explain);
      badge.addEventListener('keydown', explain);
      chip.appendChild(badge);
      chip.classList.add(`gb-tag-chip--${dictionaryScope}`);
    } else if (tag?.origin?.scope === 'admin-copy' || tag?._tag_origin?.scope === 'admin-copy') {
      chip.title = options.title || `${displayName}（管理者辞書から個人辞書へコピー）`;
    }

    if (typeof options.onRemove === 'function') {
      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'gb-tag-chip__remove';
      remove.title = options.removeTitle || 'タグを外す';
      remove.setAttribute('aria-label', options.removeAriaLabel || `${displayName || 'タグ'}を外す`);
      setDataset(remove, options.removeDataset);
      remove.innerHTML = icon('x', 12) || '×';
      remove.disabled = !!options.removeDisabled;
      remove.addEventListener('click', async event => {
        event.stopPropagation();
        if (remove.disabled) return;
        remove.disabled = true;
        try {
          await options.onRemove(event, tag);
        } finally {
          if (remove.isConnected) remove.disabled = !!options.removeDisabled;
        }
      });
      chip.appendChild(remove);
    }
    return chip;
  }

  // ============================================================
  // API ラッパー (タグ)
  // ============================================================
  function normalizedSourceFolder(value) {
    return String(value || '').trim();
  }

  function sourceCacheKey(value) {
    return normalizedSourceFolder(value) || '__default__';
  }

  function sourceFolderForTarget(path) {
    return normalizedSourceFolder(window.MeldexAutoTagSourceFolder?.(path));
  }

  function withSourceQuery(path, sourceFolder) {
    const source = normalizedSourceFolder(sourceFolder);
    if (!source) return path;
    return path + (path.includes('?') ? '&' : '?') + 'source_folder=' + encodeURIComponent(source);
  }

  function withSourcePayload(payload, sourceFolder) {
    const source = normalizedSourceFolder(sourceFolder);
    return source ? { ...(payload || {}), source_folder: source } : { ...(payload || {}) };
  }

  async function loadTags(sourceFolder) {
    if (typeof apiFetch !== 'function') return { tags: [], groups: [] };
    const personal = await apiFetch(withSourceQuery('/global-tags', sourceFolder), { silentError: true, timeoutMs: 120000 });
    return window.MeldexAdminTagDictionary?.mergeWithPersonalCatalog
      ? window.MeldexAdminTagDictionary.mergeWithPersonalCatalog(personal)
      : personal;
  }

  // シートの共通タグ列など、大量のセル描画で同一データを繰り返し参照する用途向けの
  // 短期キャッシュ付きラッパー。タグ/グループの変更操作（作成・更新・削除）で即座に破棄される。
  const _tagsCatalogCache = new Map(); // source_folder -> { at: number, promise: Promise }
  const _tagsCatalogLastResolved = new Map(); // source_folder -> 直近で解決済みの値
  // 明示的な辞書更新で失効するため、通常のフォルダ切替では再取得しない。
  const TAGS_CATALOG_CACHE_TTL_MS = 5 * 60 * 1000;
  function invalidateTagsCatalogCache(sourceFolder) {
    if (arguments.length === 0) {
      _tagsCatalogCache.clear();
      _tagsCatalogLastResolved.clear();
      return;
    }
    const key = sourceCacheKey(sourceFolder);
    _tagsCatalogCache.delete(key);
  }
  function notifyTagsCatalogChanged(reason, result, sourceFolder) {
    try {
      window.dispatchEvent(new CustomEvent('meldex:tag-dictionary-changed', {
        detail: {
          reason: String(reason || ''),
          result: result || null,
          source_folder: normalizedSourceFolder(sourceFolder),
        },
      }));
    } catch {}
  }
  function notifyDictionaryChanged(reason, sourceFolder) {
    invalidateTagsCatalogCache(sourceFolder);
    notifyTagsCatalogChanged(reason || 'dictionary-sheet-updated', null, sourceFolder);
  }
  function publishTagsCatalogMutation(reason, result, sourceFolder) {
    const key = sourceCacheKey(sourceFolder);
    if (Array.isArray(result?.tags) && Array.isArray(result?.groups)) {
      _tagsCatalogLastResolved.set(key, result);
      _tagsCatalogCache.set(key, { at: Date.now(), promise: Promise.resolve(result) });
    } else _tagsCatalogCache.delete(key);
    notifyTagsCatalogChanged(reason, result, sourceFolder);
    return result;
  }
  function loadTagsCached(sourceFolder) {
    const key = sourceCacheKey(sourceFolder);
    const cached = _tagsCatalogCache.get(key);
    if (cached && (Date.now() - cached.at) < TAGS_CATALOG_CACHE_TTL_MS) {
      return cached.promise;
    }
    const promise = loadTags(sourceFolder).then(data => {
      _tagsCatalogLastResolved.set(key, data);
      return data;
    }).catch(err => {
      _tagsCatalogCache.delete(key);
      throw err;
    });
    _tagsCatalogCache.set(key, { at: Date.now(), promise });
    return promise;
  }
  // 同期参照用: 直近で解決済みのタグカタログ（未取得なら null）。フィルタ適用など
  // 「非同期を待てない場面で、できれば最新値を使いたい」用途向けのベストエフォート参照。
  function getCachedTagsSync(sourceFolder) {
    return _tagsCatalogLastResolved.get(sourceCacheKey(sourceFolder)) || null;
  }

  // 複数条件フィルタ向け: 共通タグ列の「含む/含まない」に入力された文字列がタグ名の
  // 完全一致であれば、保存値（タグID）に変換する。キャッシュ未取得やヒット無しの場合は
  // 入力をそのまま返す（IDそのものを直接入力した場合や、キャッシュ未温まりでも
  // クラッシュせず、単に一致しない = 0件として扱われるだけの安全側フォールバック）。
  function resolveCommonTagsFilterValueSync(dbPath, propName, rawValue) {
    const text = String(rawValue || '').trim();
    if (!text) return rawValue;
    try {
      const ptc = typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath)?.[propName] : null;
      if (!ptc || ptc.type !== 'common-tags') return rawValue;
    } catch { return rawValue; }
    const cached = getCachedTagsSync(sourceFolderForTarget(dbPath));
    const allTags = Array.isArray(cached?.tags) ? cached.tags : [];
    const match = allTags.find(tag => String(tag.name || '').trim().toLowerCase() === text.toLowerCase());
    return match ? String(match.id) : rawValue;
  }

  async function createTag(payload, sourceFolder) {
    const result = await apiPost('/global-tags', withSourcePayload(payload, sourceFolder), { silentError: true });
    return publishTagsCatalogMutation('tag-created', result, sourceFolder);
  }

  async function updateTag(tagId, payload, sourceFolder) {
    if (String(tagId || '').startsWith('admin:') && window.MeldexAdminTagDictionary?.updateTag) {
      const result = await window.MeldexAdminTagDictionary.updateTag(tagId, payload);
      invalidateTagsCatalogCache(sourceFolder);
      notifyTagsCatalogChanged('admin-tag-updated', result, sourceFolder);
      return result;
    }
    const result = await apiFetch('/global-tags/' + encodeURIComponent(tagId), {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(withSourcePayload(payload, sourceFolder)),
      silentError: true,
    });
    return publishTagsCatalogMutation('tag-updated', result, sourceFolder);
  }

  async function updateTagOrder(updates, sourceFolder) {
    const result = await apiFetch('/global-tags/order', {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(withSourcePayload({ updates }, sourceFolder)),
      silentError: true, timeoutMs: 120000,
    });
    return publishTagsCatalogMutation('tag-order-updated', result, sourceFolder);
  }

  async function deleteTag(tagId, sourceFolder) {
    if (String(tagId || '').startsWith('admin:') && window.MeldexAdminTagDictionary?.deleteTag) {
      const result = await window.MeldexAdminTagDictionary.deleteTag(tagId);
      invalidateTagsCatalogCache(sourceFolder);
      notifyTagsCatalogChanged('admin-tag-deleted', result, sourceFolder);
      return result;
    }
    const result = await apiFetch(withSourceQuery('/global-tags/' + encodeURIComponent(tagId), sourceFolder), { method: 'DELETE', silentError: true });
    return publishTagsCatalogMutation('tag-deleted', result, sourceFolder);
  }

  // ============================================================
  // API ラッパー (タググループ)
  // ============================================================
  async function loadGroups(sourceFolder) {
    if (typeof apiFetch !== 'function') return { groups: [], tags: [] };
    return apiFetch(withSourceQuery('/global-tag-groups', sourceFolder), { silentError: true });
  }

  async function createGroup(payload, sourceFolder) {
    const result = await apiPost('/global-tag-groups', withSourcePayload(payload, sourceFolder), { silentError: true });
    return publishTagsCatalogMutation('group-created', result, sourceFolder);
  }

  async function materializeExternalSuggestion(candidate, sourceFolder) {
    const result = await apiPost(
      '/external-tag-catalog/materialize',
      withSourcePayload(
        {
          kind: candidate?.kind,
          catalog_id: candidate?.catalog_id,
          candidate,
        },
        sourceFolder,
      ),
      { silentError: true },
    );
    return publishTagsCatalogMutation(
      'external-catalog-materialized',
      result,
      sourceFolder,
    );
  }

  async function updateGroup(groupId, payload, sourceFolder) {
    const result = await apiFetch('/global-tag-groups/' + encodeURIComponent(groupId), {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(withSourcePayload(payload, sourceFolder)),
      silentError: true,
    });
    return publishTagsCatalogMutation('group-updated', result, sourceFolder);
  }

  async function updateGroupOrder(updates, sourceFolder) {
    const result = await apiFetch('/global-tag-groups/order', {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(withSourcePayload({ updates }, sourceFolder)),
      silentError: true, timeoutMs: 120000,
    });
    return publishTagsCatalogMutation('group-order-updated', result, sourceFolder);
  }

  async function deleteGroup(groupId, sourceFolder) {
    const result = await apiFetch(withSourceQuery('/global-tag-groups/' + encodeURIComponent(groupId), sourceFolder), { method: 'DELETE', silentError: true });
    return publishTagsCatalogMutation('group-deleted', result, sourceFolder);
  }

  // ============================================================
  // API ラッパー (自動タグ辞書のプリセット所属 / 自動タグ付け)
  // ============================================================
  async function loadAutoTagPresets(sourceFolder) {
    if (typeof apiFetch !== 'function') return { preset_names: [], builtins: [] };
    return apiFetch(withSourceQuery('/auto-tag/presets', sourceFolder), { silentError: true });
  }

  async function installAutoTagPreset(presetId, payload, sourceFolder) {
    const result = await apiPost(
      '/auto-tag/presets/' + encodeURIComponent(presetId) + '/install',
      withSourcePayload(payload, sourceFolder),
      { silentError: true },
    );
    invalidateTagsCatalogCache(sourceFolder);
    notifyTagsCatalogChanged('preset-installed', result, sourceFolder);
    return result;
  }

  async function resolveTagDictionaryConflict(strategy, conflictId, sourceFolder) {
    const result = await apiPost(
      '/auto-tag/dictionary/resolve',
      withSourcePayload({
        strategy: String(strategy || ''),
        conflict_id: String(conflictId || ''),
      }, sourceFolder),
      { silentError: true },
    );
    invalidateTagsCatalogCache(sourceFolder);
    notifyTagsCatalogChanged('dictionary-conflict-resolved', result, sourceFolder);
    return result;
  }

  async function autoTag(payload) {
    if (window.MeldexAutoTagJobs?.start) {
      return window.MeldexAutoTagJobs.start(payload || {});
    }
    const result = await apiPost('/global-tags/auto-tag', payload || {}, { silentError: true });
    invalidateTagsCatalogCache(payload?.source_folder);
    return result;
  }

  // ============================================================
  // API ラッパー (対象ファイル別タグ)
  // ============================================================
  function normalizeTargetPath(path) {
    return String(path || '').trim();
  }

  function targetTagsUrl(path, sourceFolder) {
    return withSourceQuery(
      '/global-tags/target?path=' + encodeURIComponent(normalizeTargetPath(path)),
      sourceFolder,
    );
  }

  function targetTagsCacheKey(path, sourceFolder) {
    return sourceCacheKey(sourceFolder) + '\n' + normalizeTargetPath(path);
  }

  function invalidateTargetTagsCache(path, sourceFolder) {
    const targetPath = normalizeTargetPath(path);
    if (!targetPath) {
      targetTagsCache.clear();
      targetTagsLastResolved.clear();
      targetTagsLatestRequest.clear();
      return;
    }
    const resolvedSourceFolder = normalizedSourceFolder(sourceFolder) || sourceFolderForTarget(targetPath);
    const key = targetTagsCacheKey(targetPath, resolvedSourceFolder);
    targetTagsCache.delete(key);
    targetTagsLastResolved.delete(key);
    targetTagsLatestRequest.delete(key);
  }

  function primeTargetTagsCache(path, rows, options) {
    const targetPath = normalizeTargetPath(path);
    if (!targetPath) return null;
    const sourceFolder = normalizedSourceFolder(options?.sourceFolder) || sourceFolderForTarget(targetPath);
    const tags = Array.isArray(rows) ? rows : (Array.isArray(rows?.tags) ? rows.tags : []);
    const data = {
      ...(rows && !Array.isArray(rows) && typeof rows === 'object' ? rows : {}),
      tags,
      _provisional: true,
    };
    const key = targetTagsCacheKey(targetPath, sourceFolder);
    const existing = targetTagsLastResolved.get(key);
    if (existing && existing._provisional === false) return existing;
    targetTagsLastResolved.set(key, data);
    return data;
  }

  function getCachedTargetTagsSync(path, options) {
    const targetPath = normalizeTargetPath(path);
    if (!targetPath) return null;
    const sourceFolder = normalizedSourceFolder(options?.sourceFolder) || sourceFolderForTarget(targetPath);
    return targetTagsLastResolved.get(targetTagsCacheKey(targetPath, sourceFolder)) || null;
  }

  function refreshFolderTagsAfterTargetMutation(path) {
    try {
      if (typeof _folderInvalidateTagsForPath === 'function') _folderInvalidateTagsForPath(path);
      const cfg = typeof getFolderDisplayConfig === 'function' ? getFolderDisplayConfig() : {};
      const needsFolderRefresh = cfg.showTags !== false
        || (typeof _folderHasActiveTagFilter === 'function' && _folderHasActiveTagFilter(cfg));
      if (needsFolderRefresh && typeof _folderEnsureTags === 'function') {
        _folderEnsureTags(typeof _folderItems !== 'undefined' ? _folderItems : [], { rerender: true });
      }
    } catch (_) {}
  }

  function dispatchTargetTagsChanged(path, sourceFolder, data) {
    try {
      window.dispatchEvent(new CustomEvent('meldex:target-tags-changed', {
        detail: {
          path: normalizeTargetPath(path),
          sourceFolder: normalizedSourceFolder(sourceFolder) || sourceFolderForTarget(path),
          data: data || null,
        },
      }));
    } catch (_) {
      // CustomEventを利用できない古い埋め込み環境でもタグ更新自体は成功扱いにする。
    }
    refreshFolderTagsAfterTargetMutation(path);
  }

  function notifyTargetTagsChanged(path, sourceFolder) {
    invalidateTargetTagsCache(path, sourceFolder);
    dispatchTargetTagsChanged(path, sourceFolder, null);
  }

  function publishTargetTagsMutation(path, data, sourceFolder) {
    const targetPath = normalizeTargetPath(path);
    const resolvedSourceFolder = normalizedSourceFolder(sourceFolder) || sourceFolderForTarget(targetPath);
    const key = targetTagsCacheKey(targetPath, resolvedSourceFolder);
    const authoritative = { ...(data || {}), _provisional: false };
    const requestRevision = ++targetTagsRequestSeq;
    targetTagsLatestRequest.set(key, requestRevision);
    targetTagsLastResolved.set(key, authoritative);
    targetTagsCache.set(key, { at: Date.now(), promise: Promise.resolve(authoritative) });
    dispatchTargetTagsChanged(targetPath, resolvedSourceFolder, authoritative);
    return authoritative;
  }

  async function loadTargetTags(path, options) {
    if (typeof apiFetch !== 'function') return { tags: [] };
    const sourceFolder = normalizedSourceFolder(options?.sourceFolder) || sourceFolderForTarget(path);
    const key = targetTagsCacheKey(path, sourceFolder);
    const cached = targetTagsCache.get(key);
    if (!options?.force && cached && (Date.now() - cached.at) < TARGET_TAGS_CACHE_TTL_MS) {
      return cached.promise;
    }
    const requestRevision = ++targetTagsRequestSeq;
    targetTagsLatestRequest.set(key, requestRevision);
    const promise = apiFetch(targetTagsUrl(path, sourceFolder), { silentError: true })
      .then(data => window.MeldexAdminTagDictionary?.mergeTargetTags
        ? window.MeldexAdminTagDictionary.mergeTargetTags(path, data) : data)
      .then(data => {
        if (targetTagsLatestRequest.get(key) === requestRevision) {
          targetTagsLastResolved.set(key, { ...(data || {}), _provisional: false });
        }
        return data;
      })
      .catch(error => {
        if (targetTagsLatestRequest.get(key) === requestRevision) targetTagsCache.delete(key);
        throw error;
      });
    targetTagsCache.set(key, { at: Date.now(), promise });
    return promise;
  }

  async function addTargetTag(path, nameOrTag) {
    const sourceFolder = sourceFolderForTarget(path);
    const tag = nameOrTag && typeof nameOrTag === 'object' ? nameOrTag : null;
    const name = String(tag?.name || nameOrTag || '').trim();
    const scope = String(tag?._dictionary_scope || '');
    if ((scope === 'admin' || scope === 'duplicate') && window.MeldexAdminTagDictionary) {
      const result = await window.MeldexAdminTagDictionary.useTag(path, tag, sourceFolder);
      invalidateTagsCatalogCache(sourceFolder);
      notifyTargetTagsChanged(path, sourceFolder);
      return result;
    }
    const result = await apiPost('/global-tags/target', withSourcePayload({
      path: normalizeTargetPath(path),
      name,
    }, sourceFolder), { silentError: true });
    notifyTargetTagsChanged(path, sourceFolder);
    return result;
  }

  async function removeTargetTag(path, tag) {
    const scope = String(tag?._dictionary_scope || '');
    if (scope === 'admin' && window.MeldexAdminTagDictionary?.setAdminAssignment) {
      const result = await window.MeldexAdminTagDictionary.setAdminAssignment(path, tag, false);
      notifyTargetTagsChanged(path, sourceFolderForTarget(path));
      return result;
    }
    if (scope === 'duplicate') {
      const message = '自分の分だけ外します。管理者タグとしても付いているため表示は残ります。続けますか？';
      const accepted = typeof cfConfirm === 'function' ? await cfConfirm(message) : window.confirm(message);
      if (!accepted) return { ok: false, cancelled: true };
    }
    const tagKey = tag?.id || tag?.name || tag || '';
    const sourceFolder = sourceFolderForTarget(path);
    const result = await apiFetch(targetTagsUrl(path, sourceFolder) + '&tag=' + encodeURIComponent(tagKey), { method: 'DELETE', silentError: true });
    notifyTargetTagsChanged(path, sourceFolder);
    return result;
  }

  async function updateTargetTags(path, changes, options) {
    const targetPath = normalizeTargetPath(path);
    const sourceFolder = normalizedSourceFolder(options?.sourceFolder) || sourceFolderForTarget(targetPath);
    const result = await apiFetch('/global-tags/target', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(withSourcePayload({
        path: targetPath,
        add: Array.isArray(changes?.add) ? changes.add : [],
        remove: Array.isArray(changes?.remove) ? changes.remove : [],
      }, sourceFolder)),
      keepalive: true,
      silentError: true,
    });
    const merged = window.MeldexAdminTagDictionary?.mergeTargetTags
      ? await window.MeldexAdminTagDictionary.mergeTargetTags(targetPath, result)
      : result;
    return publishTargetTagsMutation(targetPath, merged, sourceFolder);
  }

  async function searchByTag(tag, sourceFolder) {
    const name = tag?.name || tag || '';
    if (!name) return { results: [] };
    return apiFetch(withSourceQuery('/global-tags/search?tag=' + encodeURIComponent(name), sourceFolder), { silentError: true });
  }

  function openTaggedTarget(item) {
    if (!item?.path) return;
    if (typeof openFolderItem === 'function') {
      openFolderItem(item);
      return;
    }
    if (item.type === 'folder' && typeof openFolder === 'function') openFolder(item.name || item.path, item.path);
    else if (typeof openSearchResult === 'function') openSearchResult(item.path, item.type || '');
  }

  // ============================================================
  // ファイル別タグ編集 UI (オプションパネルのファイル詳細などに埋め込み)
  // ============================================================
  async function refreshTargetTagOptions(datalist, targetPath, explicitSourceFolder) {
    if (!datalist) return;
    try {
      const sourceFolder = explicitSourceFolder == null
        ? sourceFolderForTarget(targetPath) : explicitSourceFolder;
      const data = await loadTagsCached(sourceFolder);
      cache = Array.isArray(data?.tags) ? data.tags : [];
      datalist.textContent = '';
      cache.forEach(tag => {
        const option = document.createElement('option');
        option.value = tag.name || '';
        datalist.appendChild(option);
      });
    } catch (_) {
      // 候補が取れなくても、タグの直接入力はそのまま使える。
    }
  }

  function buildTargetTagEditorUi(container, options) {
    const section = document.createElement('div');
    section.className = options?.boxed === false ? '' : 'gb-section gb-section--boxed';
    section.classList.add('gb-global-tags-target-editor');
    section.style.marginTop = options?.compact ? '8px' : '12px';

    const title = document.createElement('div');
    title.className = 'gb-section-title';
    title.innerHTML = icon('tags', 14) + ' タグ';
    section.appendChild(title);

    const chips = document.createElement('div');
    chips.style.cssText = 'display:flex;flex-wrap:wrap;gap:4px;margin-top:6px;';
    section.appendChild(chips);

    const row = document.createElement('div');
    row.className = 'gb-field-row';
    row.style.cssText = 'gap:4px;margin-top:6px;';
    const editorId = 'global-tags-target-editor-' + (++targetEditorSeq);
    const input = document.createElement('input');
    input.type = 'text';
    input.placeholder = 'タグ名';
    input.className = 'gb-input';
    input.style.minWidth = '0';
    input.style.flex = '1';
    input.dataset.e2eId = editorId + '-input';
    input.dataset.globalTagsRole = 'target-input';
    input.setAttribute('aria-label', 'タグ名');
    const datalist = document.createElement('datalist');
    datalist.id = editorId + '-options';
    input.setAttribute('list', datalist.id);
    const add = document.createElement('button');
    add.type = 'button';
    add.className = 'gb-btn gb-btn-sm';
    add.dataset.e2eId = editorId + '-add';
    add.dataset.globalTagsRole = 'target-add';
    add.setAttribute('aria-label', 'タグを追加');
    add.innerHTML = icon('plus', 14) + ' 追加';
    row.append(input, add);
    section.appendChild(row);
    section.appendChild(datalist);

    const msg = document.createElement('div');
    msg.className = 'gb-section-desc';
    msg.style.marginTop = '4px';
    section.appendChild(msg);

    const osSyncRow = document.createElement('div');
    osSyncRow.style.cssText = 'display:none;align-items:center;gap:6px;flex-wrap:wrap;margin-top:6px;';
    const osSync = document.createElement('button');
    osSync.type = 'button';
    osSync.className = 'gb-btn gb-btn-sm gb-btn-quiet';
    osSync.dataset.e2eId = editorId + '-os-sync';
    osSync.dataset.globalTagsRole = 'os-sync';
    osSync.setAttribute('aria-label', 'OSタグを再同期');
    osSync.innerHTML = icon('refreshCw', 14) + ' OSタグを再同期';
    const osSyncStatus = document.createElement('span');
    osSyncStatus.className = 'gb-section-desc';
    osSyncRow.append(osSync, osSyncStatus);
    section.appendChild(osSyncRow);
    container.appendChild(section);
    return { chips, input, datalist, add, msg, osSyncRow, osSync, osSyncStatus, compact: options?.compact === true };
  }

  function renderOsTagSyncState(ui, state) {
    if (!ui?.osSyncRow) return;
    const applicable = !!state?.applicable;
    ui.osSyncRow.style.display = applicable ? 'flex' : 'none';
    if (!applicable) return;
    ui.osSync.disabled = !!ui.mutationBlocked || !state?.supported;
    if (state?.warning) {
      ui.osSyncStatus.textContent = state.warning;
    } else if (state?.supported) {
      ui.osSyncStatus.textContent = state.mode === 'explicit-only'
        ? '必要なときだけWindowsの画像タグと照合します'
        : 'Windowsの画像タグと同期済み';
    } else {
      ui.osSyncStatus.textContent = 'この画像形式ではOSタグを利用できません';
    }
  }

  function renderTargetEditorTagsData(targetPath, ui, refresh, data) {
    const tags = Array.isArray(data?.tags) ? data.tags : [];
    const provisional = !!data?._provisional;
    ui.mutationBlocked = provisional || !!data?.mutation_blocked;
    ui.input.disabled = ui.mutationBlocked;
    ui.add.disabled = ui.mutationBlocked;
    ui.chips.textContent = '';
    const cachedCatalog = getCachedTagsSync(sourceFolderForTarget(targetPath));
    const groups = Array.isArray(cachedCatalog?.groups) ? cachedCatalog.groups : [];
    const groupsById = Object.fromEntries(groups.map(group => [group.id, group]));
    const orderedTags = sortTagsByGroupOrder(tags, groups);
    if (!orderedTags.length) {
      const empty = document.createElement('span');
      empty.className = 'gb-section-desc';
      empty.textContent = 'タグはありません。';
      ui.chips.appendChild(empty);
    }
    const blockedReason = provisional
      ? '編集状態を確認しています'
      : (data?.warning || 'タグ辞書の同期競合を解消してからタグを編集してください。');
    orderedTags.forEach(tag => ui.chips.appendChild(targetTagChip(
      targetPath,
      tag,
      refresh,
      message => { ui.msg.textContent = message; },
      groupsById,
      ui.mutationBlocked,
      blockedReason,
      ui.compact,
    )));
    ui.msg.textContent = provisional
      ? '編集状態を確認しています...'
      : (ui.mutationBlocked ? blockedReason : '');
    renderOsTagSyncState(ui, provisional ? null : data?.os_sync);
    if (!cachedCatalog && !ui.catalogRefreshPending) {
      ui.catalogRefreshPending = true;
      loadTagsCached(sourceFolderForTarget(targetPath)).then(() => {
        ui.catalogRefreshPending = false;
        if (ui.chips.isConnected) renderTargetEditorTagsData(targetPath, ui, refresh, data);
      }).catch(() => {
        ui.catalogRefreshPending = false;
      });
    }
  }

  async function refreshTargetEditorTags(targetPath, ui, refresh, options) {
    const revision = (ui.refreshRevision || 0) + 1;
    ui.refreshRevision = revision;
    const immediate = options?.force ? null : getCachedTargetTagsSync(targetPath);
    if (immediate) renderTargetEditorTagsData(targetPath, ui, refresh, immediate);
    else ui.msg.textContent = 'タグを読み込んでいます...';
    try {
      const data = await loadTargetTags(targetPath, options);
      if (revision !== ui.refreshRevision || !ui.chips.isConnected) return;
      renderTargetEditorTagsData(targetPath, ui, refresh, data);
    } catch (err) {
      if (revision !== ui.refreshRevision || !ui.msg.isConnected) return;
      renderTargetEditorError(ui.msg, 'タグを読み込めませんでした', err, () => refresh({ force: true }));
    }
  }

  function renderTargetEditorError(host, label, error, retry) {
    if (!host) return;
    host.replaceChildren();
    const text = document.createElement('span');
    text.textContent = label + ': ' + (error?.userMessage || error?.message || error);
    host.appendChild(text);
    if (typeof retry !== 'function') return;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'gb-btn gb-btn-xs gb-btn-quiet';
    button.style.marginLeft = '6px';
    button.textContent = '再試行';
    button.setAttribute('aria-label', 'タグを再読み込み');
    button.dataset.e2eId = 'target-tag-editor-retry';
    button.addEventListener('click', () => retry());
    host.appendChild(button);
  }

  // OSタグ再同期(POST /global-tags/target/sync)はNAS/DropboxプレースホルダーへのCOM
  // 呼び出しで数秒〜十数秒かかり得るため、バックグラウンドジョブとして実行される
  // （常に job_id を含む応答を返す）。gb-import-job-progress.js の runBackgroundJob が
  // 読み込まれていればそれで進捗ポーリングし、単独アプリ等で未読込の場合は最小限の
  // フォールバックで /api/jobs/{id} を自前ポーリングする（単純な1回のapiPostでは
  // ジョブ受付情報だけを最終結果と取り違えてしまうため、フォールバックでも
  // ポーリングは省略できない）。
  async function runOsTagSyncJob(payload, onProgress) {
    if (typeof runBackgroundJob === 'function') {
      return runBackgroundJob('/global-tags/target/sync', payload, {
        onProgress(progress) {
          if (!onProgress) return;
          onProgress(typeof formatJobProgress === 'function'
            ? formatJobProgress(progress, { defaultPhase: 'OSタグを照合しています' })
            : (progress?.message || progress?.phase || 'OSタグを照合しています...'));
        },
      });
    }
    const started = await apiPost('/global-tags/target/sync', payload, { silentError: true });
    const jobId = String(started?.job_id || '');
    if (!jobId) return started;
    const pollIntervalMs = 1000;
    const maxPolls = 120; // 約2分
    for (let i = 0; i < maxPolls; i += 1) {
      const job = await apiFetch('/jobs/' + encodeURIComponent(jobId), { silentError: true });
      if (onProgress) onProgress(job?.progress?.message || job?.progress?.phase || 'OSタグを照合しています...');
      if (job.status === 'done') return job.result || {};
      if (job.status === 'error') throw new Error(job.error || 'OSタグの再同期に失敗しました');
      if (job.status === 'cancelled' || job.status === 'canceled') throw new Error('OSタグの再同期を中止しました');
      await new Promise(resolve => setTimeout(resolve, pollIntervalMs));
    }
    const timeoutError = new Error('OSタグの再同期に時間がかかっています。しばらくしてから再度お試しください。');
    timeoutError.name = 'LongRunningJobError';
    throw timeoutError;
  }

  function bindTargetTagEditor(targetPath, ui, refresh) {
    const addCurrent = async () => {
      if (ui.mutationBlocked) return;
      const name = ui.input.value.trim();
      if (!name) return;
      ui.add.disabled = true;
      try {
        await addTargetTag(targetPath, name);
        ui.input.value = '';
        await refresh();
        await refreshTargetTagOptions(ui.datalist, targetPath);
        if (window.MeldexTagManagement && typeof window.MeldexTagManagement.refresh === 'function') {
          window.MeldexTagManagement.refresh();
        }
      } catch (err) {
        renderTargetEditorError(ui.msg, 'タグを追加できませんでした', err, refresh);
      } finally {
        ui.add.disabled = !!ui.mutationBlocked;
      }
    };
    ui.add.addEventListener('click', addCurrent);
    ui.input.addEventListener('keydown', event => {
      if (event.key === 'Enter') addCurrent();
    });
    ui.osSync.addEventListener('click', async () => {
      if (ui.mutationBlocked) return;
      ui.osSync.disabled = true;
      ui.osSyncStatus.textContent = 'OSタグを照合しています...';
      const sourceFolder = sourceFolderForTarget(targetPath);
      try {
        invalidateTargetTagsCache(targetPath, sourceFolder);
        const data = await runOsTagSyncJob(
          withSourcePayload({ path: normalizeTargetPath(targetPath) }, sourceFolder),
          message => { ui.osSyncStatus.textContent = message; },
        );
        renderOsTagSyncState(ui, data?.os_sync);
        notifyTargetTagsChanged(targetPath, sourceFolder);
        await refresh({ force: true });
      } catch (err) {
        const reason = err && err.name === 'LongRunningJobError'
          ? '処理に時間がかかっています。しばらくしてから再度お試しください。'
          : (err.userMessage || err.message || err);
        ui.osSyncStatus.textContent = 'OSタグを再同期できませんでした: ' + reason;
      } finally {
        ui.osSync.disabled = !!ui.mutationBlocked;
      }
    });
  }

  function renderTargetTagEditor(container, path, options) {
    if (!container) return;
    const targetPath = normalizeTargetPath(path || container.dataset.globalTagsTargetPath);
    container.textContent = '';
    if (!targetPath) return;
    const ui = buildTargetTagEditorUi(container, options);
    const refresh = options => refreshTargetEditorTags(targetPath, ui, refresh, options);
    bindTargetTagEditor(targetPath, ui, refresh);
    refreshTargetTagOptions(ui.datalist, targetPath);
    refresh();
  }

  function targetTagChip(path, tag, refresh, onError, groupsById, mutationBlocked, blockedReason, compact) {
    const displayName = tag.name || '';
    const targetKey = normalizeTargetPath(path);
    const tagKey = String(tag?.id || tag?.name || 'tag');
    return createTagChip(tag, {
      compact: compact === true,
      groupsById: groupsById || {},
      labelTitle: 'このタグの項目を検索',
      ariaLabel: (displayName || 'タグ') + 'の項目を検索',
      labelDataset: {
        e2eId: `global-tags-target-search:${targetKey}:${tagKey}`,
        globalTagsRole: 'target-search',
      },
      onActivate() {
        if (window.MeldexTagManagement && typeof window.MeldexTagManagement.showSearchForTag === 'function') {
          window.MeldexTagManagement.showSearchForTag(tag);
        } else {
          searchByTag(tag, sourceFolderForTarget(path));
        }
      },
      removeDisabled: !!mutationBlocked,
      removeTitle: mutationBlocked
        ? (blockedReason || 'タグ辞書の同期競合を解消してから編集してください')
        : 'タグを外す',
      removeDataset: {
        e2eId: `global-tags-target-remove:${targetKey}:${tagKey}`,
        globalTagsRole: 'target-remove',
      },
      async onRemove() {
        try {
          await removeTargetTag(path, tag);
          await refresh();
        } catch (err) {
          if (typeof onError === 'function') onError('タグを外せませんでした: ' + (err.userMessage || err.message || err));
        }
      },
    });
  }

  function hydrateTargetEditors(root) {
    const scope = root || document;
    scope.querySelectorAll?.('[data-global-tags-target-path]').forEach(el => {
      if (el.dataset.globalTagsHydrated === '1') return;
      el.dataset.globalTagsHydrated = '1';
      renderTargetTagEditor(el, el.dataset.globalTagsTargetPath || '', { compact: true });
    });
  }

  // ============================================================
  // 汎用タグエディタ（get/set コールバック対象向け）
  //   ボードのカード・シートの行・クイックメモなど、ファイルパスを持たず
  //   データ本体へタグID配列を直接埋め込む対象向け。表示は buildTargetTagEditorUi を共用する。
  //   options: { getIds(): string[], setIds(ids: string[]): Promise<void>|void,
  //     onChange?(): void, compact?: boolean, boxed?: boolean, readOnly?: boolean, sourceFolder?: string }
  // ============================================================
  function renderInlineTagEditor(container, options) {
    if (!container) return;
    if (typeof options?.getIds !== 'function' || typeof options?.setIds !== 'function') return;
    container.textContent = '';
    const ui = buildTargetTagEditorUi(container, options);
    const refresh = () => refreshInlineTagEditorTags(options, ui, refresh);
    bindInlineTagEditor(options, ui, refresh);
    refreshTargetTagOptions(ui.datalist, '', options.sourceFolder);
    refresh();
  }

  async function refreshInlineTagEditorTags(options, ui, refresh) {
    ui.msg.textContent = 'タグを読み込んでいます...';
    try {
      const data = await loadTagsCached(options.sourceFolder);
      const allTags = Array.isArray(data?.tags) ? data.tags : [];
      ui.mutationBlocked = options.readOnly === true || !!data?.mutation_blocked;
      ui.input.disabled = ui.mutationBlocked;
      ui.add.disabled = ui.mutationBlocked;
      const groups = Array.isArray(data?.groups) ? data.groups : [];
      const groupsById = Object.fromEntries(groups.map(g => [g.id, g]));
      const idSet = new Set((options.getIds() || []).map(id => String(id)));
      const tags = sortTagsByGroupOrder(
        allTags.filter(tag => idSet.has(String(tag.id))),
        groups,
      );
      ui.chips.textContent = '';
      if (!tags.length) {
        const empty = document.createElement('span');
        empty.className = 'gb-section-desc';
        empty.textContent = 'タグはありません。';
        ui.chips.appendChild(empty);
      }
      tags.forEach(tag => ui.chips.appendChild(inlineTagChip(
        tag,
        options,
        refresh,
        message => { ui.msg.textContent = message; },
        groupsById,
        ui.mutationBlocked,
      )));
      ui.msg.textContent = ui.mutationBlocked
        ? (options.readOnly === true
          ? 'このトピックは読み取り専用です。'
          : (data?.warning || 'タグ辞書の同期競合を解消してからタグを編集してください。'))
        : '';
    } catch (err) {
      ui.msg.textContent = 'タグを読み込めませんでした: ' + (err.userMessage || err.message || err);
    }
  }

  function inlineTagChip(tag, options, refresh, onError, groupsById, mutationBlocked) {
    const displayName = tag.name || '';
    const tagKey = String(tag?.id || tag?.name || 'tag');
    return createTagChip(tag, {
      groupsById: groupsById || {},
      labelTitle: 'このタグの項目を検索',
      ariaLabel: (displayName || 'タグ') + 'の項目を検索',
      labelDataset: {
        e2eId: `global-tags-inline-search:${tagKey}`,
        globalTagsRole: 'inline-search',
      },
      onActivate() {
        if (window.MeldexTagManagement && typeof window.MeldexTagManagement.showSearchForTag === 'function') {
          window.MeldexTagManagement.showSearchForTag(tag);
        } else {
          searchByTag(tag);
        }
      },
      removeDisabled: !!mutationBlocked,
      removeTitle: mutationBlocked
        ? 'タグ辞書の同期競合を解消してから編集してください'
        : 'タグを外す',
      removeDataset: {
        e2eId: `global-tags-inline-remove:${tagKey}`,
        globalTagsRole: 'inline-remove',
      },
      async onRemove() {
        try {
          const nextIds = (options.getIds() || []).filter(id => String(id) !== String(tag.id));
          await Promise.resolve(options.setIds(nextIds));
          if (typeof options.onChange === 'function') options.onChange();
          await refresh();
        } catch (err) {
          if (typeof onError === 'function') onError('タグを外せませんでした: ' + (err.userMessage || err.message || err));
          await refresh();
        }
      },
    });
  }

  if (typeof window.addEventListener === 'function') {
    window.addEventListener('meldex:tag-dictionary-changed', () => {
      clearTimeout(targetEditorCatalogRefreshTimer);
      targetEditorCatalogRefreshTimer = setTimeout(() => {
        document.querySelectorAll('[data-global-tags-target-path]').forEach(container => {
          renderTargetTagEditor(container, container.dataset.globalTagsTargetPath || '', { compact: true });
        });
      }, 80);
    });
  }

  function bindInlineTagEditor(options, ui, refresh) {
    const addCurrent = async () => {
      if (ui.mutationBlocked) return;
      const name = ui.input.value.trim();
      if (!name) return;
      try {
        const data = await loadTagsCached(options.sourceFolder);
        const allTags = Array.isArray(data?.tags) ? data.tags : [];
        let tag = allTags.find(t => String(t.name || '').trim().toLowerCase() === name.toLowerCase());
        if (!tag) {
          try {
            const created = await createTag({ name }, options.sourceFolder);
            tag = created?.tag || null;
          } catch (createErr) {
            // 競合(同名タグが既に作成済み)などで失敗した場合は再取得してフォールバック
            const retryData = await loadTagsCached(options.sourceFolder);
            tag = (Array.isArray(retryData?.tags) ? retryData.tags : []).find(t => String(t.name || '').trim().toLowerCase() === name.toLowerCase());
            if (!tag) throw createErr;
          }
        }
        if (!tag?.id) return;
        const ids = new Set((options.getIds() || []).map(id => String(id)));
        ids.add(String(tag.id));
        await Promise.resolve(options.setIds([...ids]));
        ui.input.value = '';
        if (typeof options.onChange === 'function') options.onChange();
        await refresh();
        await refreshTargetTagOptions(ui.datalist, '', options.sourceFolder);
        if (window.MeldexTagManagement && typeof window.MeldexTagManagement.refresh === 'function') {
          window.MeldexTagManagement.refresh();
        }
      } catch (err) {
        ui.msg.textContent = 'タグを追加できませんでした: ' + (err.userMessage || err.message || err);
      }
    };
    ui.add.addEventListener('click', addCurrent);
    ui.input.addEventListener('keydown', event => {
      if (event.key === 'Enter') addCurrent();
    });
  }

  // ============================================================
  // エクスポート
  // ============================================================
  window.renderGlobalTagTargetEditor = renderTargetTagEditor;
  window.hydrateGlobalTagTargetEditors = hydrateTargetEditors;
  window.searchGlobalTagTargets = searchByTag;
  window.renderInlineTagEditor = renderInlineTagEditor;

  // タグ管理タブやファイル別エディタから使う API/ユーティリティ群を一括公開
  window.MeldexGlobalTags = {
    // タグ
    loadTags,
    loadTagsCached,
    getCachedTagsSync,
    resolveCommonTagsFilterValueSync,
    invalidateTagsCatalogCache,
    notifyDictionaryChanged,
    createTag,
    updateTag,
    updateTagOrder,
    deleteTag,
    // グループ
    loadGroups,
    createGroup,
    materializeExternalSuggestion,
    updateGroup,
    updateGroupOrder,
    deleteGroup,
    // プリセット / 自動タグ
    loadAutoTagPresets,
    installAutoTagPreset,
    resolveTagDictionaryConflict,
    autoTag,
    // 対象ファイル別
    loadTargetTags,
    primeTargetTagsCache,
    getCachedTargetTagsSync,
    invalidateTargetTagsCache,
    addTargetTag,
    removeTargetTag,
    updateTargetTags,
    searchByTag,
    openTaggedTarget,
    // コンパクト表示
    getCompactTagDisplayLimit,
    setCompactTagDisplayLimit,
    // 色
    tagColor,
    effectiveTagColor,
    groupOrderMap,
    sortTagsByGroupOrder,
    createTagChip,
  };
})();

;

/* === gb-tag-preset-management.js === */
;
/* タグ辞書のプリセット絞り込み・同梱プリセット導入UI。 */
(function () {
  'use strict';

  function filteredTags(state) {
    const selected = new Set(
      (state.selectedPresetNames || []).map(name => String(name).toLocaleLowerCase('ja')),
    );
    const query = String(state.filterText || '').trim().toLocaleLowerCase('ja');
    const matches = (state.tags || []).filter(tag => {
      if (selected.size && !(tag.presets || []).some(name => selected.has(String(name).toLocaleLowerCase('ja')))) {
        return false;
      }
      if (!query) return true;
      return [tag.name, ...(tag.aliases || []), ...(tag.presets || [])]
        .some(value => String(value || '').toLocaleLowerCase('ja').includes(query));
    });
    return {
      all: matches,
      visible: matches,
    };
  }

  function renderPresetControls(options) {
    const { state, onFilterInput, onPresetToggle } = options;
    const fragment = document.createDocumentFragment();
    const search = document.createElement('input');
    search.type = 'search';
    search.className = 'gb-input gb-tag-management-filter';
    search.placeholder = 'タグ名・別名・プリセットを検索';
    search.value = state.filterText || '';
    search.dataset.e2eId = 'tag-management-filter';
    search.setAttribute('aria-label', 'タグ辞書を検索');
    search.addEventListener('compositionstart', () => {
      search.dataset.composing = '1';
    });
    search.addEventListener('compositionend', event => {
      delete search.dataset.composing;
      onFilterInput(search, event);
    });
    search.addEventListener('input', event => {
      if (event.isComposing || search.dataset.composing === '1') return;
      onFilterInput(search, event);
    });

    const details = document.createElement('details');
    details.className = 'gb-tag-management-presets';
    details.dataset.e2eId = 'tag-management-preset-filter-section';
    details.open = !!state.presetFiltersOpen;
    const summary = document.createElement('summary');
    const selectedNames = state.selectedPresetNames || [];
    summary.textContent = selectedNames.length
      ? `タグ一覧の絞り込み（${selectedNames.join('＋')}）`
      : `タグ一覧の絞り込み（全${(state.presetNames || []).length}プリセット）`;
    summary.title = 'タグ一覧の表示だけを絞り込みます。自動タグ付けで使うプリセットは、下の自動タグ付け欄で選びます。';
    details.appendChild(summary);
    const list = document.createElement('div');
    list.style.cssText = 'display:flex;flex-wrap:wrap;gap:4px;padding:6px 0;';
    list.setAttribute('role', 'group');
    list.setAttribute('aria-label', 'タグ一覧をプリセットで絞り込み');
    if (!(state.presetNames || []).length) {
      const empty = document.createElement('span');
      empty.className = 'gb-section-desc';
      empty.textContent = 'プリセット所属はまだありません';
      list.appendChild(empty);
    }
    (state.presetNames || []).forEach((name, index) => {
      const label = document.createElement('label');
      label.className = 'at-preset-option';
      const input = document.createElement('input');
      input.type = 'checkbox';
      input.checked = (state.selectedPresetNames || []).includes(name);
      input.dataset.e2eId = `tag-management-preset-filter-${index + 1}`;
      input.addEventListener('change', () => onPresetToggle(name, input.checked));
      label.append(input, document.createTextNode(name));
      list.appendChild(label);
    });
    details.appendChild(list);
    details.addEventListener('toggle', () => {
      state.presetFiltersOpen = details.open;
    });
    fragment.appendChild(details);
    fragment.appendChild(search);
    return fragment;
  }

  function renderBuiltinPresets(options) {
    const { state, textButton, safeKeyPart, onInstall } = options;
    const section = document.createElement('section');
    section.className = 'gb-tag-management-builtins';
    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'gb-tag-management-builtins-toggle';
    toggle.dataset.e2eId = 'tag-management-builtins-toggle';
    toggle.textContent = '同梱プリセットを導入・更新';
    toggle.setAttribute('aria-label', '同梱プリセットを導入・更新');
    const list = document.createElement('div');
    list.className = 'gb-tag-management-builtin-list';
    list.style.cssText = 'display:flex;flex-direction:column;gap:6px;padding-top:6px;';
    const setOpen = open => {
      state.builtinPresetsOpen = !!open;
      list.hidden = !state.builtinPresetsOpen;
      toggle.setAttribute('aria-expanded', state.builtinPresetsOpen ? 'true' : 'false');
    };
    toggle.addEventListener('click', () => setOpen(!state.builtinPresetsOpen));
    (state.builtinPresets || []).forEach(item => {
      const row = document.createElement('div');
      row.className = 'gb-section gb-section--boxed';
      row.style.cssText = 'padding:7px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 8px;';
      const text = document.createElement('div');
      const counts = `${Number(item.installed_tag_count || 0).toLocaleString('ja-JP')} / ${Number(item.bundled_tag_count || 0).toLocaleString('ja-JP')}タグ`;
      const runtimeNote = item.local_only
        ? '・ローカル画像AI向け（CLIの1,000件上限を超えます）'
        : '';
      const name = document.createElement('strong');
      name.textContent = String(item.name || '');
      const summaryText = document.createElement('small');
      summaryText.style.cssText = 'display:block;color:var(--fg2);';
      summaryText.textContent = String(item.summary || '');
      const countText = document.createElement('small');
      countText.textContent = counts + runtimeNote;
      text.append(name, summaryText, countText);
      const button = textButton(
        item.installed ? '更新' : '導入',
        item.installed ? 'refresh-cw' : 'download',
        () => onInstall(item),
        `tag-management-install-preset-${safeKeyPart(item.id)}`,
      );
      button.disabled = !item.available || !!state.installingPresetId;
      if (state.installingPresetId === item.id) button.textContent = '処理中…';
      row.append(text, button);
      list.appendChild(row);
    });
    section.append(toggle, list);
    setOpen(state.builtinPresetsOpen);
    return section;
  }

  function renderFilterSummary(state, filtered) {
    const summary = document.createElement('div');
    summary.className = 'gb-section-desc';
    summary.style.cssText = 'padding:0 2px 7px;';
    const selected = (state.selectedPresetNames || []).length
      ? `・${state.selectedPresetNames.join('＋')}`
      : '・全プリセット';
    summary.textContent = `${filtered.all.length.toLocaleString('ja-JP')} / ${(state.tags || []).length.toLocaleString('ja-JP')}タグ${selected}`;
    return summary;
  }

  async function installBuiltinPreset(item, options) {
    const { state, render, refresh, reportError } = options;
    if (!item?.id || state.installingPresetId) return;
    state.installingPresetId = item.id;
    render();
    try {
      const startPath = '/auto-tag/presets/' + encodeURIComponent(item.id) + '/install';
      const result = typeof runBackgroundJob === 'function'
        ? await runBackgroundJob(startPath, {}, {
          onProgress(progress) {
            if (typeof showStatus === 'function' && progress?.message) showStatus(progress.message);
          },
        })
        : await window.MeldexGlobalTags?.installAutoTagPreset?.(item.id, {});
      window.MeldexGlobalTags?.invalidateTagsCatalogCache?.();
      window.invalidateAutoTagBundleCache?.();
      await refresh(false);
      if (typeof showStatus === 'function') {
        showStatus(result?.message || `「${item.name}」を自動タグ辞書へ統合しました`);
      }
    } catch (error) {
      reportError(error, `「${item.name}」を導入できませんでした`);
    } finally {
      state.installingPresetId = '';
      render();
    }
  }

  async function runAutoTagForFolder(path, options) {
    const { confirmAsync, api, refresh, reportError } = options;
    if (!path) {
      if (typeof showStatus === 'function') showStatus('フォルダを開いてから実行してください', true);
      return;
    }
    if (!await confirmAsync('現在のフォルダ内のファイルへ自動タグ付けを実行しますか？\n設定で選んだAI・モデルと自動タグ辞書を使います。')) return;
    try {
      if (typeof showStatus === 'function') showStatus('自動タグ付けをバックグラウンドで開始します…');
      const result = await api().autoTag({ path, recursive: false });
      if (result?.background || result?.job_id) {
        if (typeof showStatus === 'function') showStatus('自動タグ付けをバックグラウンドで開始しました');
      } else if (result?.stopped) {
        if (typeof showStatus === 'function') showStatus('自動タグ付けを中断しました: ' + (result.warning || result.reason || ''), true);
      } else if (typeof showStatus === 'function') {
        showStatus((result?.total || 0) + '件に自動タグ付けしました');
      }
      await refresh(false);
      if (typeof renderFolderGrid === 'function') renderFolderGrid();
    } catch (error) {
      reportError(error, '自動タグ付けに失敗しました');
    }
  }

  function updateAutoTagTargetLabel(target, targets, path, recursive) {
    target.dataset.tagAutoTargetLabel = '1';
    if (targets.length > 1) {
      const recursiveCount = targets.filter(item => item.recursive).length;
      target.textContent = `選択項目: ${targets.length.toLocaleString('ja-JP')}件`
        + (recursiveCount ? `（フォルダ${recursiveCount.toLocaleString('ja-JP')}件は配下も対象）` : '');
      const previewPaths = targets.slice(0, 20).map(item => item.path);
      target.title = previewPaths.join('\n')
        + (targets.length > previewPaths.length ? `\nほか${(targets.length - previewPaths.length).toLocaleString('ja-JP')}件` : '');
      return;
    }
    target.textContent = (recursive ? 'フォルダ内すべて: ' : '対象: ') + path;
    target.title = path;
  }

  function normalizeAutoTagTargetPath(value) {
    let current = value;
    for (let depth = 0; depth < 3; depth += 1) {
      if (typeof current === 'string') return current.trim();
      if (!current || typeof current !== 'object') return '';
      const next = current.path ?? current.absolute_path ?? current.absolutePath
        ?? current.full_path ?? current.fullPath ?? current.value;
      if (next === current) return '';
      current = next;
    }
    return typeof current === 'string' ? current.trim() : '';
  }

  function renderAutoTagExecutionSection(options = {}) {
    if (window.isAutoTagRuntimeAvailable?.() !== true) return null;
    const seen = new Set();
    const targets = (Array.isArray(options.targets) && options.targets.length
      ? options.targets
      : [{ path: options.path, recursive: options.recursive }])
      .map(item => ({
        path: normalizeAutoTagTargetPath(item),
        recursive: typeof item === 'object' ? !!item?.recursive : false,
      }))
      .filter(item => {
        if (!item.path || seen.has(item.path)) return false;
        seen.add(item.path);
        return true;
      });
    const firstTarget = targets[0] || { path: '', recursive: false };
    const path = firstTarget.path;
    const recursive = firstTarget.recursive;
    let targetHash = 2166136261;
    targets.forEach(item => {
      const value = item.path + (item.recursive ? '\u0001' : '\u0000');
      for (let index = 0; index < value.length; index += 1) {
        targetHash ^= value.charCodeAt(index);
        targetHash = Math.imul(targetHash, 16777619);
      }
    });
    const targetSignature = `${targets.length}:${(targetHash >>> 0).toString(16)}:${options.mutationBlocked ? 'blocked' : 'ready'}`;
    const section = options.existing || document.createElement('section');
    section.className = 'gb-tag-auto-run-section';
    section.dataset.tagAutoRunSection = '1';
    section.dataset.e2eId = 'tag-auto-run-section';
    section.style.cssText = 'padding:0 0 8px;';
    if (
      !options.force
      && section.dataset.targetSignature === targetSignature
    ) {
      return section;
    }
    section.dataset.targetPath = path;
    section.dataset.recursive = recursive ? '1' : '0';
    section.dataset.targetSignature = targetSignature;
    const existingHost = section.querySelector?.('[data-tag-auto-run-host]');
    const existingTarget = section.querySelector?.('[data-tag-auto-target-label]');
    if (!options.force && path && !options.mutationBlocked && existingHost && existingTarget) {
      updateAutoTagTargetLabel(existingTarget, targets, path, recursive);
      window.updateAutoTagRunPanelTargets?.(existingHost, path, {
        recursive,
        targets,
        label: options.label || (targets.length > 1 ? `${targets.length}件の選択項目` : ''),
      });
      return section;
    }
    section.replaceChildren();
    if (!path) {
      const empty = document.createElement('div');
      empty.className = 'gb-section-desc';
      empty.style.padding = '8px 4px';
      empty.textContent = '自動タグ付けするファイルまたはフォルダを選択してください。';
      section.appendChild(empty);
      return section;
    }
    if (options.mutationBlocked) {
      const blocked = document.createElement('div');
      blocked.className = 'gb-section-desc';
      blocked.style.cssText = 'padding:8px;color:var(--warning,#d8a22e);';
      blocked.textContent = options.mutationWarning
        || 'タグ辞書の同期競合を解消してから自動タグ付けを実行してください。';
      section.appendChild(blocked);
      return section;
    }
    const target = document.createElement('div');
    target.className = 'gb-section-desc';
    target.style.cssText = 'padding:6px 4px 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
    updateAutoTagTargetLabel(target, targets, path, recursive);
    const host = document.createElement('div');
    host.dataset.tagAutoRunHost = '1';
    host.dataset.e2eId = 'tag-auto-run-host';
    section.append(target, host);
    queueMicrotask(() => window.renderAutoTagRunPanel?.(host, path, {
      recursive,
      targets,
      label: options.label || (targets.length > 1 ? `${targets.length}件の選択項目` : ''),
    }));
    return section;
  }

  window.MeldexTagPresetUI = {
    filteredTags,
    renderPresetControls,
    renderBuiltinPresets,
    renderFilterSummary,
    installBuiltinPreset,
    runAutoTagForFolder,
    renderAutoTagExecutionSection,
    normalizeAutoTagTargetPath,
  };
})();

