      + tagsHtml
      + '<div data-file-embedded-groups></div>'
      + '</div>'
      + (info.kind === 'folder' ? `<div data-duplicate-folder-setting data-path="${escapeHtml(filePath)}"></div>` : '')
      + '</div>';
