    if (!el || el.nodeType !== 1) return null;
    const tag = el.tagName;
    if (tag === 'LI') {
      if (el.classList && el.classList.contains('note-checklist-item')) return 'checklist';
      return el.parentElement && el.parentElement.tagName === 'OL' ? 'ol' : 'ul';
    }
