    if (vertical) {
      const contentTop = er.top + padTop * z;
      _handle.style.top = (Math.max(2, contentTop - 22) / z) + 'px';
      _handle.style.left = (blockRect.left / z) + 'px';
      return;
    }
    _handle.style.top = (blockRect.top / z) + 'px';
    const contentLeft = er.left + padLeft * z;
