    const currentTypeId = nbt.getBlockTypeId(info);
    const rect = blockEl.getBoundingClientRect();
    // 工程7-3: 「対象行の下へ」開く
    const anchorRect = { top: rect.bottom, bottom: rect.bottom, left: rect.left, right: rect.right };
    // 計画書§2.3: メニュー表示中も対象行のハイライトを途切れさせない。
