      if (note.querySelector(`:scope > .ann-tail-handle[data-tail-handle="${which}"]`)) return;
      const handle = document.createElement('span');
      handle.className = 'ann-tail-handle';
      handle.dataset.tailHandle = which;
      note.appendChild(handle);
