/* === gb-detail-tab-dnd.js === */
;
/* gb-detail-tab-dnd.js: オプションパネル内タブの並べ替え */
(function (global) {
  const STORAGE_KEY = 'detail-tab-order';
  const ORDER_VERSION_KEY = 'detail-tab-order-version';
  const ORDER_VERSION = 'info-last-v1';
  const INFO_TAB_ID = 'note-editor';
  const DEFAULT_ORDER = [
    'db-property-settings',
    'calendar-today',
    'calendar-settings',
    'calendar-production',
    'board-card',
    'board-line',
    'board-note',
    'board-card-style',
    'board-line-style',
    'board-depth-style',
    'sn2-roles',
    'file-style',
    'publish',
    'sn2-theme',
    'sn2-ruby',
    'sn2-rowset',
    'backlinks',
    'shortcuts',
    INFO_TAB_ID,
  ];
  let _draggedTabId = '';

  function _readStoredOrder() {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      const ids = Array.isArray(parsed) ? parsed.filter(id => typeof id === 'string' && id) : [];
      if (localStorage.getItem(ORDER_VERSION_KEY) === ORDER_VERSION) return ids;
      const migrated = ids.filter(id => id !== INFO_TAB_ID);
      if (ids.includes(INFO_TAB_ID)) migrated.push(INFO_TAB_ID);
      if (ids.length) localStorage.setItem(STORAGE_KEY, JSON.stringify(migrated));
      localStorage.setItem(ORDER_VERSION_KEY, ORDER_VERSION);
      return migrated;
    } catch {
      return [];
    }
  }

  function _tabId(tab) {
    return tab?.dataset?.detailTab || '';
  }

  function _cssEscape(value) {
    return global.MeldexEscape.cssIdent(value);
  }

  function _tabs(bar) {
    return [...(bar?.querySelectorAll?.('.detail-tab[data-detail-tab]') || [])];
  }

  function _orderedIds(bar) {
    const ids = _tabs(bar).map(_tabId).filter(Boolean);
    const known = new Set(ids);
    const ordered = [];
    for (const id of [..._readStoredOrder(), ...DEFAULT_ORDER]) {
      if (known.has(id) && !ordered.includes(id)) ordered.push(id);
    }
    for (const id of ids) {
      if (!ordered.includes(id)) ordered.push(id);
    }
    return ordered;
  }

  function _saveOrder(bar) {
    const ids = _tabs(bar).map(_tabId).filter(Boolean);
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(ids)); } catch {}
  }

  function _clearIndicators(bar) {
    _tabs(bar).forEach(tab => tab.classList.remove('drag-over-left', 'drag-over-right', 'dragging'));
  }

  function applyOrder(bar) {
    if (!bar) return;
    const tabs = _tabs(bar);
    const currentIds = tabs.map(_tabId).filter(Boolean);
    const orderedIds = _orderedIds(bar);
    if (currentIds.join('\n') === orderedIds.join('\n')) return;
    const byId = new Map(tabs.map(tab => [_tabId(tab), tab]));
    for (const id of orderedIds) {
      const tab = byId.get(id);
      if (tab) bar.appendChild(tab);
    }
  }

  function _insertDragged(bar, dragged, target, insertBefore) {
    if (!bar || !dragged || !target || dragged === target) return false;
    const reference = insertBefore ? target : target.nextSibling;
    if (reference === dragged) return false;
    bar.insertBefore(dragged, reference);
    _saveOrder(bar);
    return true;
  }

  function _bindTab(bar, tab) {
    if (!bar || !tab || tab.dataset.detailTabDndBound === '1') return;
    tab.dataset.detailTabDndBound = '1';
    tab.draggable = true;

    tab.addEventListener('dragstart', event => {
      const id = _tabId(tab);
      if (!id || tab.hidden) {
        event.preventDefault();
        return;
      }
      _draggedTabId = id;
      event.dataTransfer?.setData('application/x-detail-tab-id', id);
      if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move';
      tab.classList.add('dragging');
    });

    tab.addEventListener('dragend', () => {
      _draggedTabId = '';
      _clearIndicators(bar);
    });

    tab.addEventListener('dragover', event => {
      const draggedId = _draggedTabId;
      if (!draggedId || tab.hidden) return;
      event.preventDefault();
      _tabs(bar).forEach(el => el.classList.remove('drag-over-left', 'drag-over-right'));
      const rect = tab.getBoundingClientRect();
      const isLeft = event.clientX < rect.left + rect.width / 2;
      tab.classList.toggle('drag-over-left', isLeft);
      tab.classList.toggle('drag-over-right', !isLeft);
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
    });

    tab.addEventListener('dragleave', () => tab.classList.remove('drag-over-left', 'drag-over-right'));

    tab.addEventListener('drop', event => {
      const draggedId = _draggedTabId || event.dataTransfer?.getData('application/x-detail-tab-id') || '';
      if (!draggedId || tab.hidden) return;
      event.preventDefault();
      const dragged = bar.querySelector(`.detail-tab[data-detail-tab="${_cssEscape(draggedId)}"]`);
      const insertBefore = tab.classList.contains('drag-over-left');
      _insertDragged(bar, dragged, tab, insertBefore);
      _draggedTabId = '';
      _clearIndicators(bar);
    });
  }

  function bind(bar) {
    if (!bar) return;
    applyOrder(bar);
    _tabs(bar).forEach(tab => _bindTab(bar, tab));
    if (bar.dataset.detailTabDndObserver === '1') return;
    bar.dataset.detailTabDndObserver = '1';
    const observer = new MutationObserver(() => {
      applyOrder(bar);
      _tabs(bar).forEach(tab => _bindTab(bar, tab));
    });
    observer.observe(bar, { childList: true });
  }

  global.GBDetailTabDnd = { bind, applyOrder, saveOrder: _saveOrder };

  function _bindExisting() {
    const bar = document.getElementById('detail-tab-bar');
    if (bar) bind(bar);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _bindExisting, { once: true });
  } else {
    _bindExisting();
  }
})(window);

;

/* === gb-detail-panel.js === */
;
/* gb-detail-panel.part01.js */
/**
 * Meldex Detail Panel
 * 詳細パネル、分割ビュー、カレンダーフォーム
 */

// ==============================
// 詳細パネル タブ切替（gb-scenario-rules.js から移設）
// ==============================
let _currentDetailTab = null;
let _detailSyncSeq = 0;

function _normalizeDetailTab(tab) {
  const validTabs = new Set([
    'note-editor',
    'db-property-settings',
    'db-tree',
    'calendar-today',
    'calendar-settings',
    'calendar-production',
    'board-card',
    'board-line',
    'board-note',
    'board-card-style',
    'board-line-style',
    'board-depth-style',
    'board-group-style',
    'backlinks',
    'publish',
    'sn2-main',
    'sn2-roles',
    'sn2-theme',
    'sn2-ruby',
    'sn2-rowset',
    'file-style',
    'shortcuts',
  ]);
  return validTabs.has(tab) ? tab : null;
}

// 作業パネル再アクティブ時、ユーザーが選んでいた詳細タブ (file-style / backlinks や
// 対象タイプの主要タブ) を保持する。互換性が無い場合のみ defaultTab にフォールバック。
function _resolveDetailTabForType(type, defaultTab) {
  const cur = (typeof _currentDetailTab !== 'undefined') ? _currentDetailTab : null;
  const publishTypes = new Set(['page', 'database', 'calendar', 'csv', 'scriptnote']);
  if (cur === 'publish' && publishTypes.has(type)) return cur;
  const compatible = {
    page: ['publish'],
    folder: [],
    database: ['db-property-settings', 'db-tree', 'publish'],
    board: ['board-card', 'board-line', 'board-note', 'board-card-style', 'board-line-style', 'board-depth-style', 'board-group-style'],
    calendar: ['calendar-today', 'calendar-settings', 'calendar-production', 'publish'],
    csv: ['publish'],
    scriptnote: ['sn2-main', 'sn2-roles', 'sn2-theme', 'sn2-ruby', 'sn2-rowset', 'publish'],
  };
  const valid = compatible[type] || [];
  if (valid.includes(cur)) return cur;
  return defaultTab;
}

function switchDetailTab(tab) {
  if (typeof _detailSyncSeq !== 'undefined') {
    _detailSyncSeq++;
  }
  tab = _normalizeDetailTab(tab);
  _currentDetailTab = tab;
  const bar = document.getElementById('detail-tab-bar');
  if (!bar) return;
  bar.querySelectorAll('.gb-inner-tab, .detail-tab').forEach(t => {
    const tabId = t.dataset.detailTab || '';
    const active = !t.hidden && t.dataset.detailTab === tab;
    if (tabId) {
      t.setAttribute('role', 'tab');
      t.setAttribute('aria-controls', _detailTabPanelId(tabId));
      if (!t.dataset.e2eId) t.dataset.e2eId = 'detail-tab-' + tabId;
    }
    t.classList.toggle('gb-inner-tab-active', active);
    t.classList.toggle('active', active);
    t.setAttribute('aria-selected', active ? 'true' : 'false');
    // 旧経路 (_applyScopedDetailTab) が付与したインライン style を除去
    t.style.borderBottomColor = '';
    t.style.color = '';
    t.style.fontWeight = '';
  });
  ['note-editor', 'db-property-settings', 'db-tree', 'sn2-main', 'calendar-today', 'calendar-settings', 'calendar-production', 'board-card', 'board-line', 'board-note', 'board-card-style', 'board-line-style', 'board-depth-style', 'board-group-style', 'file-style', 'backlinks', 'publish', 'shortcuts'].forEach(id => {
    const el = document.getElementById('detail-tab-' + id);
    if (!el) return;
    // 台本タブ(sn2-*)は共通コンテナ detail-tab-sn2-main を使用
    const isSn2 = tab && tab.startsWith('sn2-');
    const show = id === tab || (id === 'sn2-main' && isSn2);
    el.hidden = !show;
    // 旧経路の style.display 残留をクリア
    el.style.display = '';
  });
  // 単独アプリが後から足すタブ（ファイル情報・公開・バックリンク等）の中身も畳む。
  // これらは standalone-parity-adapter.js が独自に開閉しており、本体のタブへ
  // 切り替えた時に両方見えたままになるため。
  if (tab) {
    document.querySelectorAll('[id^="detail-tab-standalone-"]').forEach(el => { el.hidden = true; });
  }
  // 空状態プレースホルダー: どのタブもアクティブでない場合のみ表示
  const emptyEl = document.getElementById('detail-tab-empty');
  if (emptyEl) emptyEl.hidden = !!tab;
  // §12.5 バックリンク: タブに切り替わった瞬間に現在の選択対象で一覧取得。
  // OptionTargetContext（計画書§11.1）を単一の情報源として使う。固定優先順位の
  // フォールバック（currentEntityPath || currentPagePath || currentFilePath）は
  // フォルダパネルの一般ファイル選択で currentFilePath が誰からも更新されず、
  // 古い選択対象を表示し続ける不具合があったため廃止した（ファイル参照整合性
  // 計画 Phase 5）。
  if (tab === 'backlinks' && window.GbBacklinks) {
    const container = document.getElementById('detail-tab-backlinks');
    const ctx = window.GBOptionTargetContext ? window.GBOptionTargetContext.get() : _legacyBacklinksTargetFallback();
    window.GbBacklinks.render(ctx, container);
  }
  if (tab === 'publish' && typeof renderPublishDetailTab === 'function') {
    renderPublishDetailTab();
  }
  if (tab === 'shortcuts' && typeof renderShortcutsDetailTab === 'function') renderShortcutsDetailTab();
  try {
    document.dispatchEvent(new CustomEvent('meldex:detail-tab-switched', { detail: { tab } }));
  } catch {}
}

// ==============================
// 詳細パネル（独立パネル、位置選択可能）
// ==============================
function _getDetailPanelCfg() {
  try { return JSON.parse(localStorage.getItem('detail-panel-cfg') || '{}'); } catch { return {}; }
}
function _saveDetailPanelCfg(cfg) {
  localStorage.setItem('detail-panel-cfg', JSON.stringify(cfg));
}

function _detailPanelEl(pos) { return document.getElementById('detail-panel-' + pos); }

function _detailTabPanelId(tab) {
  return tab && String(tab).startsWith('sn2-') ? 'detail-tab-sn2-main' : 'detail-tab-' + tab;
}

function _detailTabButtonHtml(tab, className, label) {
  return `<button type="button" role="tab" class="gb-inner-tab detail-tab ${className}" data-detail-tab="${tab}" hidden data-e2e-id="detail-tab-${tab}" aria-selected="false" aria-controls="${_detailTabPanelId(tab)}" data-action="switchDetailTab('${tab}')">${label}</button>`;
}

function _detailTabShellHtml() {
  return `
    <div class="gb-context-target-header" data-context-target-header="1">
      <div class="gb-context-target-header__caption">対象</div>
      <div class="gb-context-target-header__name">ファイルが選択されていません</div>
    </div>
    <nav id="detail-tab-bar" class="gb-tabbar" role="tablist" aria-label="オプションパネルのタブ">
      ${_detailTabButtonHtml('db-property-settings', 'detail-tab-db-property-settings', '列設定')}
      ${_detailTabButtonHtml('db-tree', 'detail-tab-db-tree', 'ツリー')}
      ${_detailTabButtonHtml('calendar-today', 'detail-tab-calendar', '今日')}
      ${_detailTabButtonHtml('calendar-settings', 'detail-tab-calendar detail-tab-calendar-settings', 'スケジュール設定')}
      ${_detailTabButtonHtml('calendar-production', 'detail-tab-calendar detail-tab-calendar-production', '制作管理')}
      ${_detailTabButtonHtml('board-card', 'detail-tab-board detail-tab-board-card', 'トピック')}
      ${_detailTabButtonHtml('board-line', 'detail-tab-board detail-tab-board-line', 'ライン')}
      ${_detailTabButtonHtml('board-note', 'detail-tab-board-note', 'ノート')}
      ${_detailTabButtonHtml('publish', 'detail-tab-publish', '公開')}
      ${_detailTabButtonHtml('board-card-style', 'detail-tab-board-style detail-tab-board-card-style', 'トピックスタイル')}
      ${_detailTabButtonHtml('board-line-style', 'detail-tab-board-style detail-tab-board-line-style', 'ラインスタイル')}
      ${_detailTabButtonHtml('board-depth-style', 'detail-tab-board-style detail-tab-board-depth-style', '階層別スタイル')}
      ${_detailTabButtonHtml('board-group-style', 'detail-tab-board-style detail-tab-board-group-style', 'グループスタイル')}
    </nav>
    <!-- moved to independent right-rail panels; hosts remain for legacy split compatibility -->
    <div id="detail-tab-note-editor" class="gb-panel-body" hidden></div>
    <div id="detail-tab-db-property-settings" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-db-tree" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-sn2-main" class="gb-panel-body" hidden></div>
    <div id="detail-tab-calendar-today" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-calendar-settings" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-calendar-production" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-board-card" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-board-line" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-board-card-style" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-board-line-style" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-board-depth-style" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-board-group-style" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-board-note" class="gb-panel-body" hidden>
      <div id="board-note-editable" class="gb-contenteditable-body" contenteditable="true"></div>
    </div>
    <div id="detail-tab-file-style" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-backlinks" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-publish" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-shortcuts" class="gb-panel-body-scroll" hidden></div>
    <div id="detail-tab-empty" class="gb-empty-placeholder">選択中の項目がありません</div>`;
}

// ショートカットキータブの中身は gb-detail-shortcuts-tab.js（showShortcutsDetailTab /
// renderShortcutsDetailTab を公開）が担当する。読み込まれていない環境でも
// タブ表示だけで落ちないよう、呼び出し側は typeof で確認する。

function _ensureDetailTabShell(el) {
  if (!el || el.id !== 'rp-detail') return;
  const existingBar = el.querySelector('#detail-tab-bar');
  if (existingBar) {
    if (window.GBDetailTabDnd?.bind) window.GBDetailTabDnd.bind(existingBar);
    _bindDetailTabBarClicks(existingBar);
    if (typeof showShortcutsDetailTab === 'function') showShortcutsDetailTab();
    return;
  }
  el.innerHTML = _detailTabShellHtml();
  const bar = el.querySelector('#detail-tab-bar');
  if (window.GBDetailTabDnd?.bind) window.GBDetailTabDnd.bind(bar);
  _bindDetailTabBarClicks(bar);
  if (typeof showShortcutsDetailTab === 'function') showShortcutsDetailTab();
}

// タブの data-action は gb-events.js の共通ディスパッチャに依存するが、
// 単独アプリの一部（シナリオ・タイマー）はそれを読み込んでいない。
// 新設のショートカットキータブはどのアプリでも動く必要があるため、
// ボタン自身にも直接クリックを結びつける（既存タブの結線には手を入れない）。
function _bindDetailTabBarClicks(bar) {
  if (!bar) return;
  bar.querySelectorAll('[data-detail-tab="shortcuts"]').forEach(button => {
    if (button.dataset.shortcutTabBound === '1') return;
    button.dataset.shortcutTabBound = '1';
    button.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      switchDetailTab('shortcuts');
    });
  });
}

function _openDetailRightPanel() {
  const rpDetail = document.getElementById('rp-detail');
  if (!rpDetail) return false;
  _ensureDetailTabShell(rpDetail);
  const cfg = _getDetailPanelCfg();
  cfg.visible = true;
  _saveDetailPanelCfg(cfg);
  if (typeof openRightPanelTab === 'function') openRightPanelTab('detail');
  else if (typeof switchRightTab === 'function') switchRightTab('detail');
  return true;
}

// v5.0: ペインシステムの#rp-detailを優先し、なければ旧detail-panelにフォールバック
function _resolveDetailEl(opts) {
  if (opts && opts.modal) {
    const content = document.createElement('div');
    content.className = 'detail-legacy-modal-content';
    let headerObserver = null;
    let busy = false;
    let modalApi = null;
    modalApi = window.GBUI.createModal({
      id: 'detail-legacy-modal',
      title: 'オプション',
      body: content,
      variant: 'standard',
      geometryKey: 'detail-legacy-modal',
      minWidth: '0',
      initialFocus: () => content.querySelector('input, select, textarea, button') || content,
      closeLabel: '詳細パネルを閉じる',
      closeOnEsc: true,
      closeOnOverlay: true,
      resizable: true,
      onBeforeClose: () => !modalApi?.isBusy?.(),
      onClose: () => headerObserver?.disconnect(),
    });
    const { overlay, modal } = modalApi;
    overlay.classList.add('modal-overlay');
    overlay.dataset.e2eId = 'detail-legacy-modal-overlay';
    overlay._detailLegacyModalApi = modalApi;
    modal.classList.add('modal', 'detail-legacy-modal-dialog');
    modal.dataset.e2eId = 'detail-legacy-modal';
    modal._detailLegacyModalApi = modalApi;
    modal.style.cssText = 'width:min(560px,calc(100vw - 24px));max-width:100%;max-height:min(80vh,720px);overflow:hidden;';
    modalApi.body.style.cssText = 'min-width:0;overflow-x:hidden;';
    content.dataset.e2eId = 'detail-legacy-modal-content';
    content.tabIndex = -1;
    content.style.cssText = 'min-width:0;min-height:0;max-width:100%;overflow-x:hidden;overflow-y:auto;display:flex;flex-direction:column;';
    content._detailLegacyModalApi = modalApi;
    const commonClose = modalApi.header.querySelector('.gb-modal-close');
    if (commonClose) commonClose.dataset.e2eId = 'detail-panel-close';
    modalApi.isBusy = () => busy;
    modalApi.setBusy = (next) => {
      busy = !!next;
      const ariaBusy = busy ? 'true' : 'false';
      modal.setAttribute('aria-busy', ariaBusy);
      content.setAttribute('aria-busy', ariaBusy);
      content.querySelectorAll('#dp-cal-save').forEach(button => { button.disabled = busy; });
    };
    // 既存のカレンダーイベントフォームは返却要素へ owner component を載せ、
    // 保存時には closest('.modal') で外側を参照する。互換用の旧 .modal をbodyへ
    // 二重適用せず、値だけ共通シェル本体へ透過させる。
    Object.defineProperty(content, '_calComponent', {
      configurable: true,
      get: () => modal._calComponent || null,
      set: value => { modal._calComponent = value; },
    });
    // カレンダーの実入口は従来の詳細パネル用ヘッダーをbodyへ後挿入する。
    // 共通modalではタイトルと閉じる操作が既にあるため、タイトルだけouterへ同期し、
    // 二重ヘッダーを表示しない。
    headerObserver = new MutationObserver(() => {
      const legacyHeader = content.querySelector(':scope > .dp-detail-header');
      if (!legacyHeader) return;
      const legacyTitle = legacyHeader.querySelector('.dp-detail-title')?.textContent?.trim();
      const commonTitle = modal.querySelector(':scope > .gb-modal-header .gb-modal-title');
      if (legacyTitle && commonTitle) commonTitle.textContent = legacyTitle;
      legacyHeader.remove();
      const eventForm = content.querySelector(':scope > .dp-event-form');
      if (eventForm) eventForm.style.cssText += 'min-width:0;max-width:100%;overflow-x:hidden;';
    });
    headerObserver.observe(content, { childList: true });
    modalApi.open();
    return content;
  }
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  if (rpDetail && !opts?.legacyPanel) return rpDetail;
  const cfg = _getDetailPanelCfg();
  const pos = cfg.position || 'right';
  cfg.visible = true;
  _saveDetailPanelCfg(cfg);
  const el = _detailPanelEl(pos);
  if (el) return el;
  return null;
}

async function showDetailPanel(contentHtml) {
  const el = _resolveDetailEl();
  if (!el) return;
  _ensureDetailTabShell(el);
  // #rp-detail にタブ構造がある場合はエディタタブの中身だけ書き換え
  const noteEditor = el.querySelector('#detail-tab-note-editor');
  if (noteEditor) {
    if (!await _dpSavePending()) return;
    if (typeof showDbTabs === 'function') showDbTabs(false);
    if (typeof showNoteTabs === 'function') showNoteTabs(true);
    if (typeof switchDetailTab === 'function') {
      switchDetailTab(_resolveDetailTabForType('page', 'note-editor'));
    }
    // 残留 dp-editable を削除（自動保存タイマーもクリア）
    _removeStaleDpEditables(el);
    noteEditor.innerHTML = '';
    const body = document.createElement('div');
    // gap なしで content をそのまま流す (gb-panel-body-scroll は Section 用で gap あり)
    body.style.cssText = 'flex:1;overflow-y:auto;padding:var(--ui-space-4);min-height:0;';
    body.innerHTML = contentHtml;
    noteEditor.appendChild(body);
    return;
  }
  // 旧レイアウト（タブなし）
  if (!await _dpSavePending()) return;
  _removeStaleDpEditables(el);
  el.innerHTML = '';
  const cfg = _getDetailPanelCfg();
  const pos = cfg.position || 'right';
  // ヘッダー（位置変更ボタン+閉じるボタン）
  const header = document.createElement('div');
  header.style.cssText = 'display:flex;align-items:center;padding:4px 8px;border-bottom:1px solid var(--border);flex-shrink:0;gap:4px;';
  header.innerHTML = `<span style="font-size:12px;font-weight:bold;flex:1;">オプション</span>
    <button type="button" class="gb-btn gb-btn-xs gb-btn-icon" data-action="_hideDetailPanel()" aria-label="オプションパネルを閉じる" title="閉じる" data-e2e-id="legacy-detail-panel-close">${lucide('x', 12)}</button>`;
  el.appendChild(header);
  // コンテンツ
  const body = document.createElement('div');
  body.style.cssText = 'flex:1;overflow-y:auto;padding:8px;';
  body.innerHTML = contentHtml;
  el.appendChild(body);
}

function _hideDetailPanel() {
  const cfg = _getDetailPanelCfg();
  cfg.visible = false;
  _saveDetailPanelCfg(cfg);
  ['top','bottom','left','right'].forEach(p => { const el = _detailPanelEl(p); if (el) el.style.display = 'none'; });
  // v5.0: モーダルオーバーレイで表示された場合はモーダルを閉じる
  const modals = document.querySelectorAll('[data-e2e-id="detail-legacy-modal-overlay"]');
  modals.forEach(overlay => {
    if (!overlay.querySelector('#dp-cal-title')) return;
    if (overlay._detailLegacyModalApi?.close) overlay._detailLegacyModalApi.close('detail-hidden');
    else overlay.remove();
  });
}

function toggleOptionPanel() {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail && typeof toggleRightPanelTab === 'function') {
    const panel = document.getElementById('right-panel');
    const activeTab = document.querySelector('.rp-tab.active')?.dataset.rpTab;
    const willOpen = !(panel?.classList.contains('open') && activeTab === 'detail');
    const cfg = _getDetailPanelCfg();
    cfg.visible = willOpen;
    _saveDetailPanelCfg(cfg);
    _ensureDetailTabShell(rpDetail);
    toggleRightPanelTab('detail');
    return;
  }
  const cfg = _getDetailPanelCfg();
  cfg.visible = cfg.visible !== true;
  _saveDetailPanelCfg(cfg);
}

function toggleDetailPanel() {
  return toggleOptionPanel();
}

// GBOptionTargetContext が読み込まれていない環境（一部の単独アプリ）向けの
// 最終フォールバック。新しい render() 契約 {targets, selectionRevision} の
// 形に合わせて包み直すだけで、フォールバック優先順位そのものは変えない。
function _legacyBacklinksTargetFallback() {
  const s = (typeof state !== 'undefined') ? state : null;
  const path = (s && (s.currentEntityPath || s.currentPagePath || s.currentFilePath)) || '';
  return { targets: path ? [{ path, kind: 'file' }] : [], selectionRevision: 0, origin: 'legacy-fallback' };
}

function _refreshBacklinksIfActive() {
  if (_currentDetailTab !== 'backlinks' || !window.GbBacklinks) return;
  const container = document.getElementById('detail-tab-backlinks');
  const ctx = window.GBOptionTargetContext ? window.GBOptionTargetContext.get() : _legacyBacklinksTargetFallback();
  window.GbBacklinks.render(ctx, container);
}

function _clearBacklinksTabIfHidden() {
  if (_currentDetailTab !== 'backlinks') return;
  const visible = [...document.querySelectorAll('.detail-tab-backlinks')].some(t => !t.hidden);
  if (!visible) switchDetailTab(null);
}

function showFileInfoTab(visible) {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  document.querySelectorAll('.detail-tab-note-editor').forEach(t => {
    t.hidden = !visible;
  });
  if (!visible && _currentDetailTab === 'note-editor') switchDetailTab(null);
}

function renderFileInfoDetailTab(filePath, preloadedMeta, options) {
  const normalizedPath = String(filePath || '').trim();
  if (!normalizedPath) return Promise.resolve(false);
  const rpDetail = document.getElementById('rp-detail');
  if (!rpDetail) return Promise.resolve(false);
  _ensureDetailTabShell(rpDetail);
  showFileInfoTab(true);
  const host = rpDetail.querySelector('#detail-tab-note-editor');
  if (!host || !window.MeldexFileInfoPanel?.renderInto) return Promise.resolve(false);
  return window.MeldexFileInfoPanel.renderInto(host, normalizedPath, {
    ...(options || {}),
    preloadedMeta,
  });
}

function showNoteTabs(visible) {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  const dbVisible = [...document.querySelectorAll('.detail-tab-db-property-settings')].some(t => !t.hidden);
  showFileInfoTab(visible);
  // バックリンクタブもノート/DB文脈で表示
  document.querySelectorAll('.detail-tab-backlinks').forEach(t => {
    t.hidden = !(visible || dbVisible);
  });
  _clearBacklinksTabIfHidden();
  if (visible) _refreshBacklinksIfActive();
}

function showDbTabs(visible) {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  const noteVisible = [...document.querySelectorAll('.detail-tab-note-editor')].some(t => !t.hidden);
  document.querySelectorAll('.detail-tab-db-property-settings').forEach(t => {
    t.hidden = !visible;
  });
  const treeVisible = visible && typeof _dbTreeIsCurrentView === 'function' && _dbTreeIsCurrentView();
  document.querySelectorAll('.detail-tab-db-tree').forEach(t => {
    t.hidden = !treeVisible;
  });
  // バックリンクタブも DB 文脈で表示（showNoteTabs と重複してよい；上書き）
  document.querySelectorAll('.detail-tab-backlinks').forEach(t => {
    t.hidden = !(visible || noteVisible);
  });
  if ((!visible && _currentDetailTab === 'db-property-settings')
      || (!treeVisible && _currentDetailTab === 'db-tree')) {
    switchDetailTab(null);
  }
  _clearBacklinksTabIfHidden();
  if (visible) {
    const container = document.getElementById('detail-tab-db-property-settings');
    const s = (typeof state !== 'undefined') ? state : null;
    const sel = s?.selectedColumn;
    if (container && !container.innerHTML.trim() && typeof renderDbPropertySettingsPanel === 'function') {
      renderDbPropertySettingsPanel(s?.currentDbPath || '', sel?.propName || '', container);
    }
    _refreshBacklinksIfActive();
  }
}

// ボード内のカード/ライン/スタイル管理 タブの個別表示切替。
// visibility は { card, line, cardStyle, lineStyle, depthStyle, groupStyle } を取り、未指定は既存状態を維持する
// (undefined → そのまま、true/false で明示切替)。古い (boolean) 形式での呼び出しは主要な
// card/line タブにのみ適用し、スタイル管理系は boolean 時のみ追従 (ボード非表示時は全て隠す)。
function showBoardTabs(visibility) {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  const norm = (typeof visibility === 'boolean')
    ? {
        card: visibility, line: visibility,
        cardStyle: visibility, lineStyle: visibility, depthStyle: visibility, groupStyle: visibility,
      }
    : (visibility || {});
  const map = {
    card: '.detail-tab-board-card',
    line: '.detail-tab-board-line',
    cardStyle: '.detail-tab-board-card-style',
    lineStyle: '.detail-tab-board-line-style',
    depthStyle: '.detail-tab-board-depth-style',
    groupStyle: '.detail-tab-board-group-style',
  };
  Object.entries(map).forEach(([key, sel]) => {
    if (norm[key] === undefined) return;
    document.querySelectorAll(sel).forEach(t => { t.hidden = !norm[key]; });
  });
  // 現在のタブが隠された場合はクリアする
  if (_currentDetailTab === 'board-card' && norm.card === false) switchDetailTab(null);
  if (_currentDetailTab === 'board-line' && norm.line === false) switchDetailTab(null);
  if (_currentDetailTab === 'board-card-style' && norm.cardStyle === false) switchDetailTab(null);
  if (_currentDetailTab === 'board-line-style' && norm.lineStyle === false) switchDetailTab(null);
  if (_currentDetailTab === 'board-depth-style' && norm.depthStyle === false) switchDetailTab(null);
  if (_currentDetailTab === 'board-group-style' && norm.groupStyle === false) switchDetailTab(null);
}

function setBoardDetailTabContent(contents) {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  const map = {
    card: 'detail-tab-board-card',
    line: 'detail-tab-board-line',
    cardStyle: 'detail-tab-board-card-style',
    lineStyle: 'detail-tab-board-line-style',
    depthStyle: 'detail-tab-board-depth-style',
    groupStyle: 'detail-tab-board-group-style',
  };
  Object.entries(map).forEach(([key, id]) => {
    if (!Object.prototype.hasOwnProperty.call(contents || {}, key)) return;
    const el = document.getElementById(id);
    if (el) el.innerHTML = contents[key] || '';
  });
}

function clearBoardDetailTabContent() {
  // カード/ライン タブに加え、スタイル管理タブ 4 つも stale データを捨てる。
  // ボード切替時に前ボードの style 一覧/選択が残らないようにするため。
  setBoardDetailTabContent({ card: '', line: '', cardStyle: '', lineStyle: '', depthStyle: '', groupStyle: '' });
}

function clearBoardDetailTabs() {
  clearBoardDetailTabContent();
  showBoardTabs(false);
}

// ファイルテーマ タブ（全エディタ共通）の表示切替
function showFileStyleTab(visible) {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  document.querySelectorAll('.detail-tab-file-style').forEach(t => { t.hidden = !visible; });
  if (!visible) {
    document.querySelectorAll('#detail-tab-file-style').forEach(el => {
      delete el.dataset.fileStyleContext;
      el.removeAttribute('data-calendar-style');
    });
  }
  if (!visible && _currentDetailTab === 'file-style') {
    switchDetailTab(null);
  }
}

function renderPublishDetailTab() {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  const el = document.getElementById('detail-tab-publish');
  if (!el) return;
  if (typeof renderPublishSettingsPanel !== 'function') {
    el.innerHTML = '<div class="gb-section-desc" style="padding:var(--ui-space-4);">公開設定を読み込めませんでした</div>';
    return;
  }
  el.innerHTML = `<div style="padding:var(--ui-space-4);">${renderPublishSettingsPanel()}</div>`;
  if (typeof bindPublishSettingsPanel === 'function') bindPublishSettingsPanel(el);
  if (typeof replaceIcons === 'function') replaceIcons(el);
}

function showPublishDetailTab(visible) {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail) _ensureDetailTabShell(rpDetail);
  document.querySelectorAll('.detail-tab-publish').forEach(t => { t.hidden = !visible; });
  if (!visible && _currentDetailTab === 'publish') {
    switchDetailTab(null);
  }
  if (visible) renderPublishDetailTab();
}

