/* --- カスタムテンプレート管理 --- */

const CUSTOM_DB_TEMPLATES_KEY = 'customDbTemplates';

function _dbTemplateStorageKey(prefix, dbPath) {
  const fileId = typeof _pathToFileId === 'function' ? _pathToFileId(dbPath) : '';
  return prefix + (fileId || dbPath || '');
}

function _dbTemplateStorageKeys(dbPath, includeEntityTemplates) {
  const keys = [_dbTemplateStorageKey('dbViewConfig:', dbPath)];
  if (includeEntityTemplates) keys.push(_dbTemplateStorageKey('entityTemplates:', dbPath));
  return keys;
}

function _captureDbTemplateStorage(keys) {
  if (typeof captureLocalStorageSettings !== 'function') return null;
  if (typeof isLocalStorageSettingsHistorySuppressed === 'function'
    && isLocalStorageSettingsHistorySuppressed()) return null;
  return captureLocalStorageSettings(keys);
}

function _refreshDbTemplateHistoryUi(dbPath) {
  if (typeof document !== 'undefined') {
    document.querySelectorAll('[data-db-template-modal]').forEach(el => el.remove());
  }
  if (dbPath && typeof selectDatabase === 'function') {
    Promise.resolve(selectDatabase(dbPath)).catch(() => {});
  }
}

function _dbTemplateViewConfigStorageKey(dbPath) {
  return typeof getDbViewConfigStorageKey === 'function'
    ? getDbViewConfigStorageKey(dbPath)
    : _dbTemplateStorageKey('dbViewConfig:', dbPath);
}

function _dbTemplateConfigFromSnapshot(snapshot, dbPath) {
  const key = _dbTemplateViewConfigStorageKey(dbPath);
  const raw = snapshot?.storage && Object.prototype.hasOwnProperty.call(snapshot.storage, key)
    ? snapshot.storage[key]
    : null;
  if (!raw) return {};
  try { return JSON.parse(raw) || {}; } catch { return {}; }
}

function _dbTemplatePropertyTypesFromSnapshot(snapshot, dbPath) {
  const cfg = _dbTemplateConfigFromSnapshot(snapshot, dbPath);
  return _cloneTemplateData(cfg.propertyTypes || {});
}

function _setDbTemplateMetadataPropertyTypes(dbPath, propertyTypes) {
  const nextTypes = _cloneTemplateData(propertyTypes || {});
  const targetMetadata = typeof _ptMetadataForDbPath === 'function'
    ? _ptMetadataForDbPath(dbPath)
    : ((typeof state !== 'undefined' && state.currentDbPath === dbPath) ? state.dbMetadata : null);
  if (targetMetadata) {
    targetMetadata.property_types = nextTypes;
    if (typeof state !== 'undefined' && state.currentDbPath === dbPath) state.dbMetadata = targetMetadata;
  }
}

function _restoreDbTemplateBackendPropertyTypes(dbPath, snapshot) {
  if (_dbTemplateProductionSchemaLocked(dbPath)) {
    // 表示設定の履歴は戻してよいが、過去snapshotの列型を制作管理へ戻すと
    // relation/date/user契約が壊れる。localStorage側にも現在の型を戻して揃える。
    const currentTypes = _dbTemplateCurrentPropertyTypes(dbPath);
    const cfg = getDbViewConfig(dbPath);
    cfg.propertyTypes = _cloneTemplateData(currentTypes);
    saveDbViewConfig(dbPath, cfg, { skipHistory: true, skipBackend: true });
    _setDbTemplateMetadataPropertyTypes(dbPath, currentTypes);
    if (typeof showProductionManagementSchemaLockedStatus === 'function') {
      showProductionManagementSchemaLockedStatus();
    }
    _refreshDbTemplateHistoryUi(dbPath);
    return Promise.resolve(false);
  }
  const propertyTypes = _dbTemplatePropertyTypesFromSnapshot(snapshot, dbPath);
  _setDbTemplateMetadataPropertyTypes(dbPath, propertyTypes);
  return _saveDbTemplatePropertyTypesToBackend(dbPath, propertyTypes)
    .then(() => _refreshDbTemplateHistoryUi(dbPath))
    .catch(e => {
      console.warn('シートテンプレート履歴復元のプロパティ型保存に失敗:', e);
      if (typeof showStatus === 'function') showStatus('テンプレート履歴の復元に失敗: ' + (e.message || e), true);
      _refreshDbTemplateHistoryUi(dbPath);
    });
}

function _dbTemplateHistoryRestoreHandler(dbPath) {
  if (!dbPath) return null;
  return (_keys, snapshot) => {
    return _restoreDbTemplateBackendPropertyTypes(dbPath, snapshot);
  };
}

function _pushDbTemplateStorageHistory(label, beforeSnapshot, keys, detail, dbPath) {
  if (!beforeSnapshot || typeof pushLocalStorageSettingsHistory !== 'function'
    || typeof captureLocalStorageSettings !== 'function') return false;
  return pushLocalStorageSettingsHistory(
    label || 'シートテンプレート: 設定変更',
    beforeSnapshot,
    captureLocalStorageSettings(keys),
    detail || '',
    _dbTemplateHistoryRestoreHandler(dbPath || '')
  );
}

function _confirmDbTemplate(message) {
  if (typeof cfConfirm === 'function') return cfConfirm(message);
  return Promise.resolve(window.confirm(message));
}

function getCustomTemplates() {
  try { return JSON.parse(localStorage.getItem(CUSTOM_DB_TEMPLATES_KEY)) || []; }
  catch { return []; }
}

function saveCustomTemplates(templates, options = {}) {
  const before = options.skipHistory ? null : _captureDbTemplateStorage([CUSTOM_DB_TEMPLATES_KEY]);
  try {
    localStorage.setItem(CUSTOM_DB_TEMPLATES_KEY, JSON.stringify(templates));
    if (!options.skipHistory) {
      _pushDbTemplateStorageHistory(
        options.label || 'シートテンプレート: カスタムテンプレート変更',
        before,
        [CUSTOM_DB_TEMPLATES_KEY],
        options.detail || '',
        ''
      );
    }
    return true;
  } catch (e) {
    showStatus('カスタムテンプレートの保存に失敗: ' + (e.message || e), true);
    return false;
  }
}

function _cloneTemplateData(v) {
  return v == null ? v : JSON.parse(JSON.stringify(v));
}

function _dbTemplateNormalizePath(path) {
  return String(path || '').replace(/\\/g, '/').replace(/\/+$/, '');
}

function _dbTemplateSiblingDbPath(dbPath, sheetName) {
  const path = _dbTemplateNormalizePath(dbPath);
  const cleanName = String(sheetName || '').trim().replace(/[\\/]+/g, '・');
  if (!path || !cleanName) return cleanName;
  const slash = path.lastIndexOf('/');
  return (slash >= 0 ? path.slice(0, slash + 1) : '') + cleanName;
}

function _resolveDbTemplatePropertyTypeForPath(typeConfig, dbPath, templateName = '') {
  const out = _cloneTemplateData(typeConfig || {});
  if (!out || (out.type !== 'relation' && out.type !== 'multi-relation')) return out;
  const targetSheet = out.relationTemplate || out.relationSheet || '';
  if (targetSheet) {
    const currentPath = _dbTemplateNormalizePath(dbPath);
    const isSelfReference = String(templateName || '') === String(targetSheet || '');
    const targetPath = isSelfReference ? currentPath : _dbTemplateNormalizePath(_dbTemplateSiblingDbPath(dbPath, targetSheet));
    out.relationDb = isSelfReference || targetPath === currentPath ? '' : targetPath;
    delete out.relationTemplate;
    delete out.relationSheet;
  }
  return out;
}

function _dbTemplateViewLabel(mode) {
  const found = (typeof VIEW_TYPES !== 'undefined' ? VIEW_TYPES : []).find(vt => vt.mode === mode);
  return found?.label || (mode === 'pivot' ? 'テーブル' : String(mode || 'ビュー'));
}

function _dbTemplateNormalizeViewMode(mode) {
  if (typeof _normalizeDbViewModeValue === 'function') return _normalizeDbViewModeValue(mode);
  const value = String(mode || '').trim();
  return ['pivot', 'tree', 'gallery', 'kanban', 'calendar', 'timeline', 'gantt', 'chart', 'graph', 'form'].includes(value)
    ? value
    : 'pivot';
}

function _normalizeDbTemplateView(view, cfg, index) {
  if (typeof _normalizeSavedDbViewForV2 === 'function') {
    return _normalizeSavedDbViewForV2(view, cfg, index);
  }
  return view;
}

function _ensureDbTemplateSavedViewsForModes(cfg, modes) {
  if (!Array.isArray(cfg.savedViews)) cfg.savedViews = [];
  const requested = (Array.isArray(modes) && modes.length ? modes : ['pivot'])
    .map(mode => _dbTemplateNormalizeViewMode(mode));
  if (cfg.savedViews.length === 0) {
    const mode = requested[0] || 'pivot';
    cfg.savedViews.push(_normalizeDbTemplateView({ name: _dbTemplateViewLabel(mode), viewMode: mode }, cfg, 0));
  }
  const existingModes = new Set(cfg.savedViews.map(view => view?.viewMode || 'pivot'));
  requested.forEach(mode => {
    if (existingModes.has(mode)) return;
    cfg.savedViews.push(_normalizeDbTemplateView({ name: _dbTemplateViewLabel(mode), viewMode: mode }, cfg, cfg.savedViews.length));
    existingModes.add(mode);
  });
  if (!Number.isInteger(cfg.currentViewIdx) || cfg.currentViewIdx < 0 || cfg.currentViewIdx >= cfg.savedViews.length) {
    cfg.currentViewIdx = 0;
  }
}

function _applyDbTemplateViewFields(cfg, template, overwrite) {
  _ensureDbTemplateSavedViewsForModes(cfg, template.enabledModes || ['pivot']);
  (cfg.savedViews || []).forEach(view => {
    if (!view || typeof view !== 'object') return;
    if (!Array.isArray(view.colOrder)) view.colOrder = [];
    if (template.colOrder) {
      template.colOrder.forEach(col => {
        if (!view.colOrder.includes(col)) view.colOrder.push(col);
      });
    }
    if (!view.colWidths || typeof view.colWidths !== 'object' || Array.isArray(view.colWidths)) view.colWidths = {};
    if (template.colWidths) {
      Object.entries(template.colWidths).forEach(([k, v]) => {
        if (!view.colWidths[k] || overwrite) view.colWidths[k] = v;
      });
    }
    if (!view.countTypes || typeof view.countTypes !== 'object' || Array.isArray(view.countTypes)) view.countTypes = {};
    if (template.countTypes) {
      Object.entries(template.countTypes).forEach(([k, v]) => {
        if (!view.countTypes[k] || overwrite) view.countTypes[k] = v;
      });
    }
  });
}

function _saveDbTemplatePropertyTypesToBackend(dbPath, propertyTypes) {
  _dbTemplateAssertProductionPropertyTypesUnchanged(dbPath, propertyTypes);
  if (typeof apiPut !== 'function') {
    _setDbTemplateMetadataPropertyTypes(dbPath, propertyTypes);
    return Promise.resolve(true);
  }
  const nextTypes = _cloneTemplateData(propertyTypes || {});
  return apiPut('/db-metadata?path=' + encodeURIComponent(dbPath), { property_types: nextTypes })
    .then(() => {
      _setDbTemplateMetadataPropertyTypes(dbPath, nextTypes);
      return true;
    });
}

function getAllTemplates() {
  return [...BUILTIN_DB_TEMPLATES, ...getCustomTemplates()];
}

/* --- テンプレート適用 --- */

/**
 * DBにテンプレートを適用する（加算方式: 既存設定を破壊しない）
 * @param {string} dbPath - DBフォルダパス
 * @param {object} template - テンプレートオブジェクト
 * @param {object} opts - { overwrite: false }
 * @returns {{ applied: string[], skipped: string[] }} 適用結果
 */
function applyDbTemplate(dbPath, template, opts) {
  const overwrite = opts?.overwrite || false;
  const productionSchemaLocked = _dbTemplateProductionSchemaLocked(dbPath);
  const originalConfig = getDbViewConfig(dbPath);
  const backendTypes = typeof getPropertyTypes === 'function' ? _cloneTemplateData(getPropertyTypes(dbPath) || {}) : {};
  if (Object.keys(backendTypes).length > 0) {
    originalConfig.propertyTypes = _cloneTemplateData(backendTypes);
    saveDbViewConfig(dbPath, originalConfig, { skipHistory: true });
  }
  const c = _cloneTemplateData(originalConfig) || {};
  if (Object.keys(backendTypes).length > 0) c.propertyTypes = backendTypes;
  const applied = [];
  const skipped = [];
  const historyKeys = _dbTemplateStorageKeys(dbPath, !!(template.entityTemplates && template.entityTemplates.length > 0));
  const historyBefore = opts?.skipHistory ? null : _captureDbTemplateStorage(historyKeys);

  // 1. プロパティ型を設定
  if (!c.propertyTypes) c.propertyTypes = {};
  template.properties.forEach(p => {
    const reservedLegacy = productionSchemaLocked
      && window.MeldexProductionSchemaMigration?.reservedLegacyPropertyForPath?.(dbPath, p.name);
    if (reservedLegacy || (c.propertyTypes[p.name] && (productionSchemaLocked || !overwrite))) {
      skipped.push(p.name);
    } else {
      c.propertyTypes[p.name] = _resolveDbTemplatePropertyTypeForPath(p.type, dbPath, template.name);
      applied.push(p.name);
    }
  });

  // 2. 列順序（既存の末尾に追加）
  if (!c.colOrder) c.colOrder = [];
  if (template.colOrder) {
    template.colOrder.forEach(col => {
      if (!c.colOrder.includes(col)) c.colOrder.push(col);
    });
  }

  // 3. 列幅（未設定のみ）
  if (!c.colWidths) c.colWidths = {};
  if (template.colWidths) {
    Object.entries(template.colWidths).forEach(([k, v]) => {
      if (!c.colWidths[k] || overwrite) c.colWidths[k] = v;
    });
  }

  // 4. 旧ビュータイプ候補（旧形式テンプレート互換）
  if (template.enabledModes) {
    if (!c.enabledModes) {
      c.enabledModes = [...template.enabledModes];
    } else {
      template.enabledModes.forEach(m => {
        if (!c.enabledModes.includes(m)) c.enabledModes.push(m);
      });
    }
  }

  // 5. フッター集計タイプ
  if (!c.countTypes) c.countTypes = {};
  if (template.countTypes) {
    Object.entries(template.countTypes).forEach(([k, v]) => {
      if (!c.countTypes[k] || overwrite) c.countTypes[k] = v;
    });
  }
  const usedSavedViewsPath = typeof _applyDbTemplateSavedViews === 'function'
    && _applyDbTemplateSavedViews(c, template, overwrite);
  if (!usedSavedViewsPath) {
    _applyDbTemplateViewFields(c, template, overwrite);
  }
  const viewsResult = c._dbTemplateViewsResult || null;
  delete c._dbTemplateViewsResult;

  // 5.5 エントリレイアウト（typeofガード: 未ロード環境ではレイアウト無しの従来動作）
  if (typeof _applyDbTemplateEntityLayouts === 'function') {
    _applyDbTemplateEntityLayouts(c, template, overwrite);
  }
  const entityLayoutsResult = c._dbTemplateEntityLayoutsResult || null;
  delete c._dbTemplateEntityLayoutsResult;

  // 6. エントリテンプレート（別のlocalStorageキー）
  let existingEntityTemplates = null;
  let nextEntityTemplates = null;
  let backendSavePromise = Promise.resolve(false);
  if (template.entityTemplates && template.entityTemplates.length > 0) {
    existingEntityTemplates = getEntityTemplates(dbPath);
    nextEntityTemplates = _cloneTemplateData(existingEntityTemplates) || [];
    const existingNames = nextEntityTemplates.map(t => t.name);
    template.entityTemplates.forEach(et => {
      if (!existingNames.includes(et.name)) {
        nextEntityTemplates.push(et);
      }
    });
  }

  try {
    if (nextEntityTemplates) saveEntityTemplates(dbPath, nextEntityTemplates);
    saveDbViewConfig(dbPath, c);
    backendSavePromise = _saveDbTemplatePropertyTypesToBackend(dbPath, c.propertyTypes)
      .then(result => {
        if (!opts?.skipHistory) {
          _pushDbTemplateStorageHistory(
            'シートテンプレート: 適用',
            historyBefore,
            historyKeys,
            template.name || '',
            dbPath
          );
        }
        return result;
      })
      .catch(e => {
        try { saveDbViewConfig(dbPath, originalConfig, { skipHistory: true }); } catch {}
        if (nextEntityTemplates) {
          try { saveEntityTemplates(dbPath, existingEntityTemplates || []); } catch {}
        }
        _setDbTemplateMetadataPropertyTypes(dbPath, originalConfig.propertyTypes || {});
        throw e;
      });
  } catch (e) {
    if (nextEntityTemplates) {
      try { saveEntityTemplates(dbPath, existingEntityTemplates || []); } catch {}
    }
    throw e;
  }

  return { applied, skipped, viewsResult, entityLayoutsResult, backendSavePromise };
}

/**
 * 現在のDB設定からテンプレートオブジェクトを生成する
 */
function exportDbAsTemplate(dbPath) {
  const c = getDbViewConfig(dbPath);
  const pt = typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath) : (c.propertyTypes || {});
  const properties = Object.entries(pt).map(([name, type]) => ({ name, type }));
  const currentColOrder = typeof getColOrder === 'function' ? getColOrder(dbPath) : null;
  const currentColWidths = typeof getColWidths === 'function' ? getColWidths(dbPath) : null;
  const currentCountTypes = typeof getCountTypes === 'function' ? getCountTypes(dbPath) : null;
  const hasSavedViews = Array.isArray(c.savedViews) && c.savedViews.length > 0;
  const savedViewModes = hasSavedViews
    ? [...new Set(c.savedViews.map(view => _dbTemplateNormalizeViewMode(view?.viewMode || 'pivot')))]
    : null;

  return {
    id: 'custom-' + Date.now(),
    name: '',
    tier: 0,
    description: '',
    icon: 'file',
    properties,
    colOrder: hasSavedViews ? (Array.isArray(currentColOrder) ? currentColOrder : []) : (c.colOrder || []),
    colWidths: hasSavedViews ? (currentColWidths || {}) : (currentColWidths && Object.keys(currentColWidths).length ? currentColWidths : (c.colWidths || {})),
    enabledModes: savedViewModes && savedViewModes.length ? savedViewModes : (c.enabledModes || ['pivot']),
    entityTemplates: getEntityTemplates(dbPath),
    countTypes: hasSavedViews ? (currentCountTypes || {}) : (currentCountTypes && Object.keys(currentCountTypes).length ? currentCountTypes : (c.countTypes || {})),
    savedViews: typeof exportDbTemplateSavedViews === 'function' ? exportDbTemplateSavedViews(c) : null,
    entityLayouts: typeof exportDbTemplateEntityLayouts === 'function' ? exportDbTemplateEntityLayouts(c) : null,
  };
}

function _dbTemplateProductionSchemaLocked(dbPath) {
  return typeof isProductionManagementSheetPath === 'function'
    && isProductionManagementSheetPath(dbPath);
}

function _dbTemplateCurrentPropertyTypes(dbPath) {
  const metadata = typeof _ptMetadataForDbPath === 'function' ? _ptMetadataForDbPath(dbPath) : null;
  const backendTypes = metadata?.property_types;
  if (backendTypes && typeof backendTypes === 'object' && Object.keys(backendTypes).length) {
    return _cloneTemplateData(backendTypes);
  }
  return typeof getPropertyTypes === 'function'
    ? _cloneTemplateData(getPropertyTypes(dbPath) || {})
    : {};
}

function _dbTemplateAssertProductionPropertyTypesUnchanged(dbPath, nextTypes) {
  if (!_dbTemplateProductionSchemaLocked(dbPath)) return;
  const currentTypes = _dbTemplateCurrentPropertyTypes(dbPath);
  const candidateTypes = nextTypes && typeof nextTypes === 'object' ? nextTypes : {};
  for (const [name, typeConfig] of Object.entries(currentTypes)) {
    if (!Object.prototype.hasOwnProperty.call(candidateTypes, name)
      || JSON.stringify(candidateTypes[name] || {}) !== JSON.stringify(typeConfig || {})) {
      throw new Error(`制作管理に必要な列「${name}」の種類・設定はテンプレートから変更できません`);
    }
  }
  for (const name of Object.keys(candidateTypes)) {
    if (window.MeldexProductionSchemaMigration?.reservedLegacyPropertyForPath?.(dbPath, name)) {
      throw new Error(`制作管理では旧名称列「${name}」を追加できません。トピック名を使用してください`);
    }
  }
}
/**
 * テンプレートを適用する
 */
async function _doApplyTemplate(dbPath, tmpl, overlayEl, triggerEl = null) {
  if (overlayEl?._dbTemplateBusy) return false;
  if (overlayEl) overlayEl._dbTemplateBusy = true;
  overlayEl?._dbTemplateSetBusy?.(true);
  let result;
  try {
    result = applyDbTemplate(dbPath, tmpl);
    if (result.backendSavePromise) await result.backendSavePromise;
  } catch (e) {
    showStatus('テンプレート適用に失敗: ' + (e.message || e), true);
    if (overlayEl) overlayEl._dbTemplateBusy = false;
    overlayEl?._dbTemplateSetBusy?.(false);
    return false;
  }
  _closeDbTemplateOverlay(overlayEl, triggerEl || overlayEl?._dbTemplateTrigger || null, { reason: 'applied' });

  let msg = 'テンプレート「' + tmpl.name + '」を適用しました';
  if (result.skipped.length > 0) {
    msg += '（' + result.skipped.length + '件スキップ: 既存の列）';
  }
  if (result.viewsResult && (result.viewsResult.added || result.viewsResult.skipped)) {
    msg += `（ビュー${result.viewsResult.added || 0}件追加`;
    if (result.viewsResult.skipped) msg += `/${result.viewsResult.skipped}件スキップ`;
    msg += '）';
  }
  if (result.entityLayoutsResult && (result.entityLayoutsResult.added || result.entityLayoutsResult.skipped)) {
    msg += `（トピックレイアウト${result.entityLayoutsResult.added || 0}件追加`;
    if (result.entityLayoutsResult.skipped) msg += `/${result.entityLayoutsResult.skipped}件スキップ（同名）`;
    msg += '）';
  }
  showStatus(msg);

  // DB再読み込み
  if (typeof selectDatabase === 'function') {
    try {
      await Promise.resolve(selectDatabase(dbPath));
    } catch (error) {
      showStatus('テンプレートは適用済みですが、シートの再読み込みに失敗しました: ' + (error?.message || error), true);
    }
  }
  return true;
}

/* --- テンプレートプレビューモーダル（モバイル: 重ねモーダルとして継続使用） --- */

function showTemplatePreviewModal(tmpl, dbPath, parentOverlay, triggerEl = null, opts = {}) {
  const trigger = _dbTemplateTrigger(triggerEl);
  const seq = Date.now().toString(36) + '-' + Math.floor(Math.random() * 1000).toString(36);
  const descId = `db-template-preview-desc-${seq}`;
  const body = document.createElement('div');
  body.className = 'db-template-preview-content';

  const desc = document.createElement('p');
  desc.id = descId;
  desc.textContent = tmpl.description;
  desc.className = 'db-template-description';
  body.appendChild(desc);

  // ビュー一覧（savedViews があれば詳細表示、無ければ旧形式の推奨ビュー表示）
  body.appendChild(_buildDbTemplateViewsSummarySection(tmpl));

  if (Array.isArray(tmpl.entityLayouts) && tmpl.entityLayouts.length) {
    const layoutsDiv = document.createElement('div');
    layoutsDiv.className = 'db-template-mode-summary';
    layoutsDiv.textContent = 'トピックレイアウト: ' + tmpl.entityLayouts.map(l => l?.name || 'レイアウト').join(', ');
    body.appendChild(layoutsDiv);
  }

  // プロパティ一覧テーブル（デスクトップのプレビューペインと共通の構築関数を使用）
  body.appendChild(_buildDbTemplatePropTable(tmpl));

  // ボタン（カード側の操作ボタン廃止に伴い、カスタムテンプレートの編集/削除もここへ集約）
  const cancelBtn = document.createElement('button');
  _setupDbTemplateButton(cancelBtn, 'gb-btn gb-btn-sm', 'db-template-preview-back');
  cancelBtn.textContent = '戻る';
  const applyBtn = document.createElement('button');
  _setupDbTemplateButton(applyBtn, 'gb-btn gb-btn-sm gb-btn-primary primary', 'db-template-preview-apply');
  applyBtn.textContent = '適用';
  applyBtn.addEventListener('click', async () => {
    const applied = await _doApplyTemplate(dbPath, tmpl, overlay, trigger);
    if (applied) {
      _closeDbTemplateOverlay(parentOverlay, parentOverlay?._dbTemplateTrigger || trigger, { reason: 'applied' });
    }
  });
  const footerButtons = [cancelBtn];
  if (tmpl.tier === 0) {
    const editBtn = document.createElement('button');
    _setupDbTemplateButton(editBtn, 'gb-btn gb-btn-sm', 'db-template-preview-edit', 'カスタムテンプレート「' + (tmpl.name || '') + '」を編集');
    editBtn.textContent = '編集';
    editBtn.addEventListener('click', () => {
      const editTrigger = parentOverlay?._dbTemplateTrigger || trigger;
      _closeDbTemplateOverlay(overlay, editTrigger, { restoreFocus: false });
      _closeDbTemplateOverlay(parentOverlay, editTrigger, { restoreFocus: false });
      showEditTemplateModal(tmpl, dbPath, editTrigger);
    });
    footerButtons.push(editBtn);

    const delBtn = document.createElement('button');
    _setupDbTemplateButton(delBtn, 'gb-btn gb-btn-sm gb-btn-danger', 'db-template-preview-delete', 'カスタムテンプレート「' + (tmpl.name || '') + '」を削除');
    delBtn.textContent = '削除';
    delBtn.addEventListener('click', async () => {
      const deleted = await _deleteDbCustomTemplateWithConfirm(tmpl, opts.onChanged, delBtn);
      if (deleted) {
        _closeDbTemplateOverlay(overlay, parentOverlay?._dbTemplateTrigger || trigger, { restoreFocus: false });
      }
    });
    footerButtons.push(delBtn);
  }
  footerButtons.push(applyBtn);
  let busy = false;
  const releaseOverflowLock = _lockDbTemplateHorizontalOverflow();
  const modalApi = window.GBUI.createModal({
    id: `db-template-preview-${seq}`,
    title: tmpl.name,
    body,
    footer: footerButtons,
    variant: 'standard',
    extraClass: 'db-template-preview-modal',
    geometryKey: 'db-template-preview',
    minWidth: '0',
    initialFocus: cancelBtn,
    returnFocus: trigger || undefined,
    closeLabel: 'テンプレートプレビューを閉じる',
    onBeforeClose: reason => !busy || reason === 'applied' || reason === 'superseded',
    onClose: () => {
      releaseOverflowLock();
      // スマホの重ね下シートを閉じた直後は、親ギャラリーの再有効化が
      // MutationObserverの次周期になる。親カードが再び操作可能になった時点でも
      // フォーカスを補完し、戻る先を本文や背面toolbarへ流さない。
      requestAnimationFrame(() => _focusDbTemplateTrigger(trigger));
      setTimeout(() => _focusDbTemplateTrigger(trigger), 60);
    },
  });
  const overlay = modalApi.overlay;
  const modal = modalApi.modal;
  modal.classList.add('modal', 'db-template-modal');
  overlay.classList.add('modal-overlay');
  overlay.dataset.dbTemplateModal = 'preview';
  overlay.style.zIndex = '130';
  overlay._dbTemplateTrigger = trigger;
  overlay._dbTemplateClose = modalApi.close;
  overlay._dbTemplateSetBusy = (next) => {
    busy = !!next;
    modal.setAttribute('aria-busy', busy ? 'true' : 'false');
    [...footerButtons, modalApi.header.querySelector('.gb-modal-close')].filter(Boolean)
      .forEach(control => { control.disabled = busy; });
  };
  modal.dataset.e2eId = 'db-template-preview-dialog';
  modal.setAttribute('aria-describedby', descId);
  modalApi.footer.classList.add('db-template-footer');
  const closeBtn = modalApi.header.querySelector('.gb-modal-close');
  if (closeBtn) closeBtn.dataset.e2eId = 'db-template-preview-close';
  cancelBtn.addEventListener('click', () => modalApi.close('back'));
  _setDbTemplateModalSize(modal, { maxWidth: 500, maxHeight: 680, heightRatio: 0.74, minHeight: 360 });
  modalApi.open();
}
/* ==============================
   gb-db-template-views.js: シートテンプレートのビュー包含
   savedViews（フィルタ/ソート/型別設定を含む）のサニタイズ・エクスポート・マージ適用を担当する。
   gb-db-templates.part01.js の applyDbTemplate / exportDbAsTemplate から
   typeof ガード付きで呼び出される（本ファイル未ロード時は旧来の enabledModes のみのパスへ
   自動フォールバックする＝ロールバック・部分連結ハーネスの両方に対して安全）。
   ============================== */

/* --- typeSpecific のサブホワイトリスト --- */

function _sanitizeDbTemplateTimelineTypeSpecific(timeline) {
  const src = (timeline && typeof timeline === 'object') ? timeline : {};
  const out = {};
  ['timeProp', 'endProp', 'rowProp', 'scale', 'direction', 'calendarSystemId'].forEach((key) => {
    if (src[key]) out[key] = src[key];
  });
  const stepMinutes = Number(src.timeStepMinutes);
  if (Number.isFinite(stepMinutes) && Math.round(stepMinutes) !== 1) out.timeStepMinutes = Math.round(stepMinutes);
  if (Array.isArray(src.calendarSystems) && src.calendarSystems.length) {
    out.calendarSystems = _cloneTemplateData(src.calendarSystems);
  }
  if (Array.isArray(src.cardProps) && src.cardProps.length) {
    out.cardProps = _cloneTemplateData(src.cardProps);
  }
  const thumbCount = Number(src.cardImageThumbCount);
  if (Number.isFinite(thumbCount) && Math.round(thumbCount) !== 3) out.cardImageThumbCount = Math.round(thumbCount);
  const lineCount = Number(src.cardPropLineCount);
  if (Number.isFinite(lineCount) && Math.round(lineCount) !== 1) out.cardPropLineCount = Math.round(lineCount);
  if (src.colWidths && typeof src.colWidths === 'object' && !Array.isArray(src.colWidths) && Object.keys(src.colWidths).length) {
    out.colWidths = _cloneTemplateData(src.colWidths);
  }
  return out;
}

function _sanitizeDbTemplateTypeSpecific(typeSpecific) {
  const src = (typeSpecific && typeof typeSpecific === 'object') ? typeSpecific : {};
  const out = {};
  if (src.pivot && typeof src.pivot === 'object' && src.pivot.groupBy) {
    out.pivot = { groupBy: src.pivot.groupBy };
  }
  if (src.tree && typeof src.tree === 'object' && Object.keys(src.tree).length) {
    out.tree = _cloneTemplateData(src.tree);
  }
  if (src.kanban && typeof src.kanban === 'object' && src.kanban.groupBy && src.kanban.groupBy !== '_status') {
    out.kanban = { groupBy: src.kanban.groupBy };
  }
  if (src.calendar?.mapping && typeof src.calendar.mapping === 'object' && Object.keys(src.calendar.mapping).length) {
    out.calendar = { mapping: _cloneTemplateData(src.calendar.mapping) };
  }
  if (src.chart && typeof src.chart === 'object' && Object.keys(src.chart).length) {
    out.chart = _cloneTemplateData(src.chart);
  }
  if (src.graph && typeof src.graph === 'object' && Object.keys(src.graph).length) {
    out.graph = _cloneTemplateData(src.graph);
  }
  if (src.form?.formConfig != null) {
    out.form = { formConfig: _cloneTemplateData(src.form.formConfig) };
  }
  if (src.timeline && typeof src.timeline === 'object') {
    const timeline = _sanitizeDbTemplateTimelineTypeSpecific(src.timeline);
    if (Object.keys(timeline).length) out.timeline = timeline;
  }
  return out;
}

/* --- savedView 単体のサニタイズ --- */

/**
 * 保存済みビュー1件をテンプレート保存用にホワイトリスト方式でサニタイズする。
 * 除外: manualOrder（実データ依存のエントリ順）、filter（実行時のクイックフィルタ状態）、
 *       timeline.rowHeights / displayStart / displayEnd（実データ依存の表示状態）
 */
function _sanitizeDbTemplateSavedView(view) {
  if (!view || typeof view !== 'object') return null;
  const out = {};
  out.name = String(view.name || '').trim() || 'ビュー';
  out.viewMode = _dbTemplateNormalizeViewMode(view.viewMode);
  if (Array.isArray(view.hiddenCols) && view.hiddenCols.length) out.hiddenCols = _cloneTemplateData(view.hiddenCols);
  if (Array.isArray(view.pinnedCols) && view.pinnedCols.length) out.pinnedCols = _cloneTemplateData(view.pinnedCols);
  if (Array.isArray(view.colOrder) && view.colOrder.length) out.colOrder = _cloneTemplateData(view.colOrder);
  if (view.colWidths && typeof view.colWidths === 'object' && !Array.isArray(view.colWidths) && Object.keys(view.colWidths).length) {
    out.colWidths = _cloneTemplateData(view.colWidths);
  }
  if (view.countTypes && typeof view.countTypes === 'object' && !Array.isArray(view.countTypes) && Object.keys(view.countTypes).length) {
    out.countTypes = _cloneTemplateData(view.countTypes);
  }
  if (Array.isArray(view.advancedFilters) && view.advancedFilters.length) out.advancedFilters = _cloneTemplateData(view.advancedFilters);
  if (view.columnValueFilters && typeof view.columnValueFilters === 'object' && Object.keys(view.columnValueFilters).length) {
    out.columnValueFilters = _cloneTemplateData(view.columnValueFilters);
  }
  if (view.sortConfig != null) out.sortConfig = _cloneTemplateData(view.sortConfig);
  if (view.conditionalFormat) out.conditionalFormat = true;
  if (view.conditionalColors && typeof view.conditionalColors === 'object' && Object.keys(view.conditionalColors).length) {
    out.conditionalColors = _cloneTemplateData(view.conditionalColors);
  }
  if (view.showFooter) out.showFooter = true;
  if (view.entityColumnPinned === false) out.entityColumnPinned = false;
  if (view.thumbnailSize && view.thumbnailSize !== 'small') out.thumbnailSize = view.thumbnailSize;
  const typeSpecific = _sanitizeDbTemplateTypeSpecific(view.typeSpecific);
  if (Object.keys(typeSpecific).length) out.typeSpecific = typeSpecific;
  return out;
}

/**
 * 現在のビュー設定から、テンプレートへ保存する savedViews 配列を生成する。
 * ビューが無い（または全て空相当）場合は null を返す。
 */
function exportDbTemplateSavedViews(cfg) {
  if (!cfg || !Array.isArray(cfg.savedViews) || !cfg.savedViews.length) return null;
  const sanitized = cfg.savedViews
    .map((view) => _sanitizeDbTemplateSavedView(view))
    .filter(Boolean);
  return sanitized.length ? sanitized : null;
}

/* --- savedViews のマージ適用 --- */

function _dbTemplateSavedViewKey(view) {
  return String(view?.name || '') + ' ' + String(view?.viewMode || 'pivot');
}

function _dbTemplateAppendLegacyViewFields(view, template, overwrite) {
  if (!view || typeof view !== 'object') return;
  if (!Array.isArray(view.colOrder)) view.colOrder = [];
  if (template.colOrder) {
    template.colOrder.forEach((col) => {
      if (!view.colOrder.includes(col)) view.colOrder.push(col);
    });
  }
  if (!view.colWidths || typeof view.colWidths !== 'object' || Array.isArray(view.colWidths)) view.colWidths = {};
  if (template.colWidths) {
    Object.entries(template.colWidths).forEach(([k, v]) => {
      if (!view.colWidths[k] || overwrite) view.colWidths[k] = v;
    });
  }
  if (!view.countTypes || typeof view.countTypes !== 'object' || Array.isArray(view.countTypes)) view.countTypes = {};
  if (template.countTypes) {
    Object.entries(template.countTypes).forEach(([k, v]) => {
      if (!view.countTypes[k] || overwrite) view.countTypes[k] = v;
    });
  }
}

/**
 * テンプレートの savedViews を現在の設定へマージ適用する（加算方式）。
 * - name+viewMode が一致する既存ビューはスキップ（overwrite 時はフィールドを上書き）
 * - name のみ一致する場合は「名前 2」のように連番で一意化して追加
 * - colOrder/colWidths/countTypes の旧形式フィールドの追補は、
 *   適用前から存在していたビューにのみ行う（新規追加ビューはテンプレート側の値をそのまま使う）
 * @returns {boolean} savedViews パスを使ったか（false の場合は呼び出し元が旧パスへフォールバックする）
 */
function _applyDbTemplateSavedViews(cfg, template, overwrite) {
  if (!template || !Array.isArray(template.savedViews)) return false;
  if (!Array.isArray(cfg.savedViews)) cfg.savedViews = [];
  const existingViews = cfg.savedViews.slice();
  const existingByKey = new Map();
  const existingNames = new Set();
  existingViews.forEach((view) => {
    if (!view) return;
    existingByKey.set(_dbTemplateSavedViewKey(view), view);
    existingNames.add(String(view.name || ''));
  });

  let added = 0;
  let skipped = 0;
  template.savedViews.forEach((rawView) => {
    const sanitized = _sanitizeDbTemplateSavedView(rawView);
    if (!sanitized) return;
    const key = _dbTemplateSavedViewKey(sanitized);
    const existing = existingByKey.get(key);
    if (existing) {
      skipped++;
      if (overwrite) {
        const name = existing.name;
        const viewMode = existing.viewMode;
        Object.assign(existing, _cloneTemplateData(sanitized));
        existing.name = name;
        existing.viewMode = viewMode;
        const idx = cfg.savedViews.indexOf(existing);
        cfg.savedViews[idx] = _normalizeDbTemplateView(existing, cfg, idx);
      }
      return;
    }
    let uniqueName = sanitized.name;
    let suffix = 2;
    while (existingNames.has(uniqueName)) {
      uniqueName = sanitized.name + ' ' + suffix;
      suffix++;
    }
    sanitized.name = uniqueName;
    existingNames.add(uniqueName);
    const normalized = _normalizeDbTemplateView(sanitized, cfg, cfg.savedViews.length);
    cfg.savedViews.push(normalized);
    existingByKey.set(_dbTemplateSavedViewKey(normalized), normalized);
    added++;
  });

  // 旧形式フィールド（テンプレート直下の colOrder/colWidths/countTypes）の追補は
  // 「適用前から存在していたビュー」だけに行う。新規追加ビューはテンプレートの
  // savedViews 側にすでに完全な情報を持つため、二重適用しない。
  existingViews.forEach((view) => _dbTemplateAppendLegacyViewFields(view, template, overwrite));

  if (!Number.isInteger(cfg.currentViewIdx) || cfg.currentViewIdx < 0 || cfg.currentViewIdx >= cfg.savedViews.length) {
    cfg.currentViewIdx = 0;
  }
  cfg._dbTemplateViewsResult = { added, skipped };
  return true;
}
/* gb-db-template-entity-layouts.js: シートテンプレートの entityLayouts（エントリレイアウト）
   サニタイズ / エクスポート / マージ適用 / 画像の選択同梱。
   gb-db-template-views.js（savedViews）と同じ「専用ファイル + typeofガード +
   未ロード時は entityLayouts 無しの旧経路へ自動フォールバック」の型に合わせる。 */
'use strict';

/* レイアウト1件をテンプレートへ持ち出せる形に正規化する。
   正規化は gb-db-entity-layout.js の共通関数へ委譲（未ロード環境ではシャローコピー）。 */
function _dbTemplateSanitizeEntityLayout(layout) {
  if (!layout || typeof layout !== 'object' || Array.isArray(layout)) return null;
  if (typeof _elNormalizeLayout === 'function') return _elNormalizeLayout(JSON.parse(JSON.stringify(layout)));
  return JSON.parse(JSON.stringify(layout));
}

/* エクスポート: cfg.entityLayouts をサニタイズして返す（無ければ null）。
   アップロード画像は既定でパス参照のみ（バイナリ同梱は embedDbTemplateEntityLayoutImages で
   ユーザーが明示選択したセルだけ dataUri を付ける。localStorage容量への配慮）。 */
function exportDbTemplateEntityLayouts(cfg) {
  const layouts = Array.isArray(cfg?.entityLayouts) ? cfg.entityLayouts : [];
  const sanitized = layouts.map(_dbTemplateSanitizeEntityLayout).filter(Boolean);
  return sanitized.length ? sanitized : null;
}

/* テンプレート内の「アップロード画像を使う画像セル」を列挙する（作成モーダルの同梱チェックリスト用） */
function listDbTemplateEntityLayoutUploadImages(template) {
  const out = [];
  (Array.isArray(template?.entityLayouts) ? template.entityLayouts : []).forEach(layout => {
    (Array.isArray(layout?.cells) ? layout.cells : []).forEach(cell => {
      if (cell?.type === 'image' && cell.image?.source === 'upload' && (cell.image.path || cell.image.url)) {
        out.push({
          layoutName: String(layout.name || ''),
          cellId: String(cell.id || ''),
          path: String(cell.image.path || ''),
          cell,
        });
      }
    });
  });
  return out;
}

const DB_TEMPLATE_IMAGE_EMBED_MAX_BYTES = 500 * 1024;

/* 選択されたセルの画像を dataUri としてテンプレートへ同梱する。
   500KBを超える画像は同梱せずスキップ（localStorageの容量保護）。 */
async function embedDbTemplateEntityLayoutImages(template, selectedCellIds) {
  const selected = new Set(Array.isArray(selectedCellIds) ? selectedCellIds : []);
  const result = { embedded: 0, skipped: 0 };
  if (!selected.size) return result;
  for (const item of listDbTemplateEntityLayoutUploadImages(template)) {
    if (!selected.has(item.cellId)) continue;
    try {
      const url = (typeof fileRawUrl === 'function' && item.path) ? fileRawUrl(item.path) : (item.cell.image.url || '');
      if (!url) { result.skipped += 1; continue; }
      const res = await fetch(url);
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const blob = await res.blob();
      if (blob.size > DB_TEMPLATE_IMAGE_EMBED_MAX_BYTES) {
        result.skipped += 1;
        continue;
      }
      const dataUri = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error || new Error('read error'));
        reader.readAsDataURL(blob);
      });
      item.cell.image = { ...item.cell.image, dataUri };
      result.embedded += 1;
    } catch {
      result.skipped += 1;
    }
  }
  return result;
}

/* 適用: 既存レイアウトと名前が一致するものは加算スキップ（savedViewsの方針に合わせる。
   overwrite 時は同名の中身を置き換える）。追加分は id をすべて振り直し、タブ順の末尾へ足す。
   結果は cfg._dbTemplateEntityLayoutsResult = { added, skipped } に格納する。 */
function _applyDbTemplateEntityLayouts(cfg, template, overwrite) {
  const incoming = Array.isArray(template?.entityLayouts) ? template.entityLayouts : [];
  if (incoming.length === 0) return false;
  const genId = (prefix) => (typeof _elGenId === 'function'
    ? _elGenId(prefix)
    : prefix + '-' + Date.now().toString(36) + '-' + Math.floor(Math.random() * 1679616).toString(36));
  const state = typeof _elNormalizeState === 'function'
    ? _elNormalizeState(cfg)
    : {
      layouts: Array.isArray(cfg.entityLayouts) ? cfg.entityLayouts : [],
      tabOrder: Array.isArray(cfg.entityTabOrder) && cfg.entityTabOrder.length ? cfg.entityTabOrder : ['columns'],
      currentTab: cfg.currentEntityTab || 'columns',
    };
  let added = 0;
  let skipped = 0;
  incoming.forEach(raw => {
    const layout = _dbTemplateSanitizeEntityLayout(raw);
    if (!layout) return;
    const existing = state.layouts.find(l => String(l?.name || '') === layout.name);
    if (existing) {
      if (!overwrite) {
        skipped += 1;
        return;
      }
      // overwrite: 同名レイアウトの中身を置き換える（idとタブ位置は既存を維持）
      existing.canvasSize = layout.canvasSize;
      existing.theme = layout.theme;
      existing.cells = (layout.cells || []).map(cell => ({ ...cell, id: genId('cell') }));
      added += 1;
      return;
    }
    const clone = JSON.parse(JSON.stringify(layout));
    clone.id = genId('el');
    clone.cells = (clone.cells || []).map(cell => ({ ...cell, id: genId('cell') }));
    state.layouts.push(clone);
    state.tabOrder.push(clone.id);
    added += 1;
  });
  cfg.entityLayouts = state.layouts;
  cfg.entityTabOrder = state.tabOrder;
  cfg.currentEntityTab = state.currentTab;
  cfg._dbTemplateEntityLayoutsResult = { added, skipped };
  return true;
}
/* ==============================
   gb-db-template-gallery-ui.js: シートテンプレートギャラリー（刷新UI）
   検索付きヘッダー + Tierチップ行 + カードグリッド/プレビューペインの2ペイン構成。
   モーダル共通プラミング（開閉・フォーカス復帰・サイズ調整）と、
   プロパティ表・ビュー一覧のプレビュー描画を担当する。
   モバイルでは重ねプレビューモーダル（gb-db-templates.part02.js の showTemplatePreviewModal）を
   引き続き使用する。

   設計意図（UI共通ルールとの整合、2026-08-19 UI統一）:
   - カードは「クリックで選択のみ」。適用/編集/削除はデスクトップ=プレビューペイン、
     モバイル=重ねプレビューモーダルへ集約し、同じ操作ボタンを二重表示しない。
   - 説明文はカードへ常時表示せず data-gb-tooltip（ホバー/フォーカス/長押し）へ集約する。
     選択後のプレビュー（ペイン/重ねモーダル）は詳細表示面なので説明文を可視のまま残す。
   - Tierチップは .gb-btn 系を基底にし、フィルタ選択状態だけ pill 形状+accent の
     修飾クラス（.template-tier-btn）で表現する。
   - プレビューペイン付き2ペイン構成は「一覧と詳細の分離」（ビュータブ等と同じ
     選択→詳細操作パターン）を1モーダル内で成立させるための意図的な専用レイアウト。
   ============================== */

/* --- トリガー・フォーカス復帰ヘルパー --- */

function _dbTemplateTrigger(triggerEl = null) {
  if (triggerEl && typeof triggerEl.focus === 'function') return triggerEl;
  const active = typeof document !== 'undefined' ? document.activeElement : null;
  return active && typeof active.focus === 'function' ? active : null;
}

function _focusDbTemplateTrigger(triggerEl) {
  if (!triggerEl || typeof triggerEl.focus !== 'function' || !triggerEl.isConnected) return;
  try {
    triggerEl.focus({ preventScroll: true });
  } catch {
    try { triggerEl.focus(); } catch {}
  }
}

/* --- モーダル共通プラミング --- */

function _cleanupDbTemplateOverlay(overlay) {
  if (!overlay || typeof overlay._dbTemplateCleanup !== 'function') return;
  overlay._dbTemplateCleanup();
}

function _isTopDbTemplateOverlay(overlay) {
  if (!overlay?.isConnected) return false;
  const overlays = Array.from(document.querySelectorAll('.modal-overlay[data-db-template-modal]'))
    .filter(el => el.isConnected);
  return overlays[overlays.length - 1] === overlay;
}

function _closeDbTemplateOverlay(overlay, triggerEl = null, options = {}) {
  if (!overlay || !overlay.isConnected) return;
  if (typeof overlay._dbTemplateClose === 'function') {
    overlay._dbTemplateClose(options.reason || 'programmatic');
    return;
  }
  _cleanupDbTemplateOverlay(overlay);
  overlay.remove();
  if (options.restoreFocus === false) return;
  const trigger = triggerEl || overlay._dbTemplateTrigger || null;
  _focusDbTemplateTrigger(trigger);
  setTimeout(() => _focusDbTemplateTrigger(trigger), 0);
  setTimeout(() => _focusDbTemplateTrigger(trigger), 60);
}

function _bindDbTemplateDismiss(overlay, triggerEl = null) {
  if (!overlay) return;
  const onPointerDown = (e) => {
    if (e.target !== overlay) return;
    _closeDbTemplateOverlay(overlay, triggerEl);
  };
  const onKeyDown = (e) => {
    if (e.key !== 'Escape' || !overlay.isConnected) return;
    // アイコンピッカー表示中はEscapeをピッカー側に譲り、テンプレートモーダルを誤って閉じない
    if (document.querySelector('.gb-icon-picker')) return;
    if (!_isTopDbTemplateOverlay(overlay)) return;
    e.preventDefault();
    e.stopPropagation();
    _closeDbTemplateOverlay(overlay, triggerEl);
  };
  overlay.addEventListener('pointerdown', onPointerDown);
  document.addEventListener('keydown', onKeyDown, true);
  overlay._dbTemplateCleanup = () => {
    overlay.removeEventListener('pointerdown', onPointerDown);
    document.removeEventListener('keydown', onKeyDown, true);
    overlay._dbTemplateCleanup = null;
  };
}

function _dbTemplateViewportSize() {
  const zoom = typeof _getZoom === 'function'
    ? Math.max(0.1, _getZoom() || 1)
    : Math.max(0.1, parseFloat(document.documentElement?.style?.zoom || '') || 1);
  const width = (window.visualViewport?.width || window.innerWidth || document.documentElement?.clientWidth || 800) / zoom;
  const height = (window.visualViewport?.height || window.innerHeight || document.documentElement?.clientHeight || 600) / zoom;
  return { width, height };
}

function _isDbTemplateMobileSheetMode() {
  return document.body?.dataset?.cloudMobile === '1'
    || document.body?.dataset?.mobileUi === '1'
    || document.body?.dataset?.mobileUiLocal === '1'
    || window.MeldexCloudMobileState?.mobile === true;
}

function _setDbTemplateModalSize(modal, opts = {}) {
  if (!modal || _isDbTemplateMobileSheetMode()) return;
  const viewport = _dbTemplateViewportSize();
  const usableWidth = Math.max(260, viewport.width - 32);
  const usableHeight = Math.max(220, viewport.height - 24);
  const maxWidth = Math.max(260, opts.maxWidth || 500);
  modal.style.width = Math.round(Math.min(maxWidth, usableWidth)) + 'px';
  if (!opts.heightRatio && !opts.maxHeight) return;
  let targetHeight = opts.heightRatio ? viewport.height * opts.heightRatio : usableHeight;
  if (opts.maxHeight) targetHeight = Math.min(targetHeight, opts.maxHeight);
  targetHeight = Math.min(targetHeight, usableHeight);
  if (opts.minHeight) targetHeight = Math.max(Math.min(opts.minHeight, usableHeight), targetHeight);
  modal.style.height = Math.round(targetHeight) + 'px';
}

function _showDbTemplateOverlay(overlay, modal, triggerEl = null, focusTarget = null) {
  if (!overlay || !modal) return;
  overlay._dbTemplateTrigger = triggerEl || null;
  _bindDbTemplateDismiss(overlay, triggerEl);
  document.body.appendChild(overlay);
  if (typeof GBModalShell !== 'undefined' && GBModalShell?.enhanceAll) GBModalShell.enhanceAll();
  requestAnimationFrame(() => {
    try {
      (focusTarget || modal)?.focus?.({ preventScroll: true });
    } catch {
      try { (focusTarget || modal)?.focus?.(); } catch {}
    }
  });
}

function _setupDbTemplateButton(button, className, e2eId, ariaLabel = '') {
  if (!button) return button;
  button.type = 'button';
  if (className) button.className = className;
  if (e2eId) button.dataset.e2eId = e2eId;
  if (ariaLabel) button.setAttribute('aria-label', ariaLabel);
  return button;
}

async function _deleteDbCustomTemplateWithConfirm(tmpl, onDeleted, actionButton = null) {
  if (actionButton?.dataset.dbTemplateBusy === '1') return false;
  if (actionButton) {
    actionButton.dataset.dbTemplateBusy = '1';
    actionButton.disabled = true;
  }
  try {
    let confirmed = false;
    try {
      confirmed = await _confirmDbTemplate('カスタムテンプレート「' + tmpl.name + '」を削除しますか？');
    } catch (error) {
      showStatus('カスタムテンプレートの削除確認を表示できませんでした: ' + (error?.message || error), true);
      return false;
    }
    if (!confirmed) return false;
    const customs = getCustomTemplates().filter(c => c.id !== tmpl.id);
    let saved = false;
    try {
      saved = await Promise.resolve(saveCustomTemplates(customs, { label: 'シートテンプレート: カスタムテンプレート削除', detail: tmpl.name }));
    } catch (error) {
      showStatus('カスタムテンプレートの削除に失敗しました: ' + (error?.message || error), true);
      return false;
    }
    if (!saved) return false;
    if (typeof onDeleted === 'function') {
      try {
        await Promise.resolve(onDeleted());
      } catch (error) {
        showStatus('カスタムテンプレートは削除しましたが、一覧を更新できませんでした。画面を再読み込みしてください: ' + (error?.message || error), true);
      }
    }
    return true;
  } finally {
    if (actionButton?.isConnected) {
      delete actionButton.dataset.dbTemplateBusy;
      actionButton.disabled = false;
    }
  }
}

let _dbTemplateOverflowLockDepth = 0;
let _dbTemplatePreviousRootOverflowX = '';
let _dbTemplatePreviousBodyOverflowX = '';
let _dbTemplateLockedScrollers = [];
function _lockDbTemplateHorizontalOverflow() {
  if (_dbTemplateOverflowLockDepth === 0) {
    _dbTemplatePreviousRootOverflowX = document.documentElement.style.overflowX;
    _dbTemplatePreviousBodyOverflowX = document.body.style.overflowX;
    document.documentElement.style.overflowX = 'hidden';
    document.body.style.overflowX = 'hidden';
    _dbTemplateLockedScrollers = Array.from(document.querySelectorAll('#pivot-view, .pivot-view'))
      .map(element => ({ element, overflowX: element.style.overflowX }));
    _dbTemplateLockedScrollers.forEach(({ element }) => { element.style.overflowX = 'hidden'; });
  }
  _dbTemplateOverflowLockDepth += 1;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    _dbTemplateOverflowLockDepth = Math.max(0, _dbTemplateOverflowLockDepth - 1);
    if (_dbTemplateOverflowLockDepth === 0) {
      document.documentElement.style.overflowX = _dbTemplatePreviousRootOverflowX;
      document.body.style.overflowX = _dbTemplatePreviousBodyOverflowX;
      _dbTemplateLockedScrollers.forEach(({ element, overflowX }) => {
        if (element?.isConnected) element.style.overflowX = overflowX;
      });
      _dbTemplateLockedScrollers = [];
    }
  };
}

/* --- アイコン表示 --- */

/**
 * テンプレートアイコン（生Lucide名 or spec文字列）を描画する。
 * GBIconAssets 未ロード環境では lucide() へフォールバックする。
 */
function _dbTemplateIconHtml(icon, size) {
  const spec = icon || 'file';
  if (typeof GBIconAssets !== 'undefined' && GBIconAssets?.render) {
    return GBIconAssets.render(spec, size);
  }
  return typeof lucide === 'function' ? lucide(spec, size) : '';
}

/* --- プロパティ表（デスクトップのプレビューペイン・モバイルの重ねモーダルで共用） --- */

function _typeLabel(type) {
  const labels = {
    text: 'テキスト', number: '数値', select: 'セレクト', 'multi-select': 'マルチセレクト',
    'common-tags': '共通タグ', checkbox: 'チェックボックス', date: '日時', url: 'URL', link: 'リンク',
    relation: 'リレーション', 'multi-relation': 'マルチリレーション', formula: '数式', furigana: 'ふりがな',
  };
  return labels[type] || type;
}

function _buildDbTemplatePropTable(tmpl) {
  const table = document.createElement('table');
  table.className = 'db-template-prop-table';
  const thead = document.createElement('thead');
  thead.innerHTML = '<tr><th style="text-align:left;padding:4px 8px;border-bottom:1px solid var(--border)">列</th>'
    + '<th style="text-align:left;padding:4px 8px;border-bottom:1px solid var(--border)">型</th>'
    + '<th style="text-align:left;padding:4px 8px;border-bottom:1px solid var(--border)">オプション</th></tr>';
  table.appendChild(thead);

  const tbody = document.createElement('tbody');
  (tmpl.properties || []).forEach(p => {
    const tr = document.createElement('tr');
    const tdName = document.createElement('td');
    tdName.textContent = p.name;
    tdName.className = 'db-template-prop-name';
    tr.appendChild(tdName);

    const tdType = document.createElement('td');
    tdType.textContent = _typeLabel(p.type.type);
    tdType.className = 'db-template-prop-type';
    tr.appendChild(tdType);

    const tdOpts = document.createElement('td');
    tdOpts.className = 'db-template-prop-options';
    if (p.type.options && p.type.options.length > 0) {
      tdOpts.textContent = p.type.options.join(', ');
    } else if (p.type.type === 'relation' || p.type.type === 'multi-relation') {
      const target = p.type.relationTemplate || p.type.relationDb || (p.type.relationDb === '' ? '自シート' : '');
      const reverse = p.type.bidirectionalProp ? ' / 逆: ' + p.type.bidirectionalProp : '';
      tdOpts.textContent = target ? target + reverse : '(リレーション先を要設定)';
    }
    tr.appendChild(tdOpts);
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  return table;
}

/* --- ビュー一覧（プレビューペイン・重ねモーダルで共用） --- */

const DB_TEMPLATE_VIEW_MODE_LABELS = { pivot: 'テーブル', tree: 'ツリー', gallery: 'ギャラリー', kanban: 'カンバン', timeline: 'タイムライン', gantt: 'ガント', chart: 'チャート' };

function _dbTemplateViewIcon(mode) {
  const found = (typeof VIEW_TYPES !== 'undefined' ? VIEW_TYPES : []).find(vt => vt.mode === mode);
  return found?.icon || 'table';
}

function _dbTemplateViewSummaryParts(view) {
  const parts = [];
  const filterCount = Array.isArray(view?.advancedFilters) ? view.advancedFilters.length : 0;
  if (filterCount > 0) parts.push(`フィルタ${filterCount}件`);
  if (view?.sortConfig) parts.push('並べ替えあり');
  const groupBy = view?.typeSpecific?.pivot?.groupBy || view?.typeSpecific?.kanban?.groupBy;
  if (groupBy) parts.push('グループ: ' + groupBy);
  return parts;
}

/**
 * テンプレートのビュー一覧セクションを構築する。
 * savedViews があれば各ビューの詳細（モード・名前・フィルタ/ソート/グループ概要）を、
 * 無ければ旧形式の「推奨ビュー: …」表示にフォールバックする。
 */
function _buildDbTemplateViewsSummarySection(tmpl) {
  const wrap = document.createElement('div');
  wrap.className = 'db-template-views-summary';
  if (Array.isArray(tmpl.savedViews) && tmpl.savedViews.length) {
    const title = document.createElement('div');
    title.className = 'db-template-views-summary-title';
    title.textContent = 'ビュー';
    wrap.appendChild(title);
    const list = document.createElement('ul');
    list.className = 'db-template-views-summary-list';
    tmpl.savedViews.forEach(view => {
      const li = document.createElement('li');
      li.className = 'db-template-views-summary-item';
      const iconSpan = document.createElement('span');
      iconSpan.className = 'db-template-views-summary-icon';
      iconSpan.innerHTML = _dbTemplateIconHtml(_dbTemplateViewIcon(view?.viewMode), 14);
      li.appendChild(iconSpan);
      const nameSpan = document.createElement('span');
      nameSpan.className = 'db-template-views-summary-name';
      nameSpan.textContent = view?.name || _dbTemplateViewLabel(view?.viewMode);
      li.appendChild(nameSpan);
      const parts = _dbTemplateViewSummaryParts(view);
      if (parts.length) {
        const detail = document.createElement('span');
        detail.className = 'db-template-views-summary-detail';
        detail.textContent = parts.join(' / ');
        li.appendChild(detail);
      }
      list.appendChild(li);
    });
    wrap.appendChild(list);
  } else if (Array.isArray(tmpl.enabledModes) && tmpl.enabledModes.length) {
    const modeDiv = document.createElement('div');
    modeDiv.className = 'db-template-mode-summary';
    modeDiv.textContent = '推奨ビュー: ' + tmpl.enabledModes.map(m => DB_TEMPLATE_VIEW_MODE_LABELS[m] || _dbTemplateViewLabel(m)).join(', ');
    wrap.appendChild(modeDiv);
  }
  return wrap;
}

/* --- テンプレートカード --- */

/**
 * テンプレートカードを構築する。
 * デスクトップ: クリック/Enter/Space でプレビューペインを更新（重ねモーダルは開かない）。
 * モバイル: クリック/Enter/Space で重ねプレビューモーダル（showTemplatePreviewModal）を開く。
 */
function _buildTemplateCard(tmpl, dbPath, ctx = {}) {
  const card = document.createElement('div');
  card.className = 'template-card' + (ctx.selected ? ' is-selected' : '');
  card.dataset.e2eId = 'db-template-card';
  card.dataset.templateId = tmpl.id;
  card.tabIndex = 0;
  card.setAttribute('role', 'button');
  card.setAttribute('aria-label', 'テンプレート「' + (tmpl.name || '') + '」を確認');
  if (!ctx.mobile) card.setAttribute('aria-pressed', ctx.selected ? 'true' : 'false');

  const titleRow = document.createElement('div');
  titleRow.className = 'template-card-title-row';
  const icon = document.createElement('span');
  icon.innerHTML = _dbTemplateIconHtml(tmpl.icon, 18);
  icon.className = 'template-card-icon';
  titleRow.appendChild(icon);
  const name = document.createElement('span');
  name.textContent = tmpl.name;
  name.className = 'template-card-name';
  titleRow.appendChild(name);
  if (tmpl.tier > 0) {
    const badge = document.createElement('span');
    badge.textContent = 'T' + tmpl.tier;
    badge.className = 'template-card-badge';
    titleRow.appendChild(badge);
  }
  card.appendChild(titleRow);

  // 説明文はカードへ常時表示せず、ツールチップ（ホバー/フォーカス/長押し）へ集約する
  if (tmpl.description) card.dataset.gbTooltip = tmpl.description;

  const meta = document.createElement('div');
  meta.className = 'template-card-meta';
  const propCount = (tmpl.properties || []).length;
  const viewCount = Array.isArray(tmpl.savedViews) && tmpl.savedViews.length
    ? tmpl.savedViews.length
    : (Array.isArray(tmpl.enabledModes) ? tmpl.enabledModes.length : 0);
  meta.textContent = propCount + '列 · ' + viewCount + 'ビュー';
  card.appendChild(meta);

  const activate = () => {
    if (ctx.mobile) {
      showTemplatePreviewModal(tmpl, dbPath, ctx.overlay, card, { onChanged: ctx.onChanged });
    } else if (typeof ctx.onSelect === 'function') {
      ctx.onSelect();
    }
  };
  card.addEventListener('click', activate);
  card.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    e.preventDefault();
    activate();
  });

  return card;
}

/* --- デスクトップ用プレビューペイン --- */

function _renderDbTemplatePreviewPane(pane, tmpl, dbPath, ctx = {}) {
  if (!pane) return;
  pane.innerHTML = '';
  pane.dataset.templateId = tmpl.id;

  const header = document.createElement('div');
  header.className = 'db-template-preview-pane-header';
  const icon = document.createElement('span');
  icon.className = 'db-template-preview-pane-icon';
  icon.innerHTML = _dbTemplateIconHtml(tmpl.icon, 22);
  header.appendChild(icon);
  const name = document.createElement('span');
  name.className = 'db-template-preview-pane-name';
  name.textContent = tmpl.name;
  header.appendChild(name);
  pane.appendChild(header);

  if (tmpl.description) {
    const desc = document.createElement('p');
    desc.className = 'db-template-description';
    desc.textContent = tmpl.description;
    pane.appendChild(desc);
  }

  pane.appendChild(_buildDbTemplateViewsSummarySection(tmpl));

  const propScroll = document.createElement('div');
  propScroll.className = 'db-template-preview-pane-props';
  propScroll.appendChild(_buildDbTemplatePropTable(tmpl));
  pane.appendChild(propScroll);

  if (Array.isArray(tmpl.entityTemplates) && tmpl.entityTemplates.length) {
    const entityDiv = document.createElement('div');
    entityDiv.className = 'db-template-preview-pane-entities';
    entityDiv.textContent = 'トピック雛形: ' + tmpl.entityTemplates.map(e => e.name).join(', ');
    pane.appendChild(entityDiv);
  }

  if (Array.isArray(tmpl.entityLayouts) && tmpl.entityLayouts.length) {
    const layoutsDiv = document.createElement('div');
    layoutsDiv.className = 'db-template-preview-pane-entities';
    layoutsDiv.textContent = 'トピックレイアウト: ' + tmpl.entityLayouts.map(l => l?.name || 'レイアウト').join(', ');
    pane.appendChild(layoutsDiv);
  }

  const actions = document.createElement('div');
  actions.className = 'db-template-preview-pane-actions';
  const applyBtn = document.createElement('button');
  _setupDbTemplateButton(applyBtn, 'gb-btn gb-btn-sm gb-btn-primary primary', 'db-template-preview-pane-apply', 'テンプレート「' + (tmpl.name || '') + '」を適用');
  applyBtn.textContent = '適用';
  applyBtn.addEventListener('click', () => {
    _doApplyTemplate(dbPath, tmpl, ctx.overlay, ctx.overlay?._dbTemplateTrigger || applyBtn);
  });
  actions.appendChild(applyBtn);

  if (tmpl.tier === 0) {
    const editBtn = document.createElement('button');
    _setupDbTemplateButton(editBtn, 'gb-btn gb-btn-sm', 'db-template-preview-pane-edit', 'カスタムテンプレート「' + (tmpl.name || '') + '」を編集');
    editBtn.textContent = '編集';
    editBtn.addEventListener('click', () => {
      _closeDbTemplateOverlay(ctx.overlay, ctx.overlay?._dbTemplateTrigger || editBtn, { restoreFocus: false });
      showEditTemplateModal(tmpl, dbPath, ctx.overlay?._dbTemplateTrigger || editBtn);
    });
    actions.appendChild(editBtn);

    const delBtn = document.createElement('button');
    _setupDbTemplateButton(delBtn, 'gb-btn gb-btn-sm gb-btn-danger', 'db-template-preview-pane-delete', 'カスタムテンプレート「' + (tmpl.name || '') + '」を削除');
    delBtn.textContent = '削除';
    delBtn.addEventListener('click', async () => {
      await _deleteDbCustomTemplateWithConfirm(tmpl, ctx.onDeleted, delBtn);
    });
    actions.appendChild(delBtn);
  }
  pane.appendChild(actions);
}

/* --- テンプレートギャラリーモーダル本体 --- */

/**
 * テンプレートギャラリーモーダルを表示する。
 * ヘッダー（タイトル+検索+閉じる）→ Tierチップ行 → 本体（カードグリッド+プレビューペイン）→ フッター。
 * モバイルではプレビューペインを出さず、カード選択で重ねプレビューモーダルを開く。
 */
function showTemplateGalleryModal(dbPath, triggerEl = null) {
  const trigger = _dbTemplateTrigger(triggerEl);
  const seq = Date.now().toString(36) + '-' + Math.floor(Math.random() * 1000).toString(36);
  const descId = `db-template-gallery-desc-${seq}`;
  const isMobile = _isDbTemplateMobileSheetMode();
  const content = document.createElement('div');
  content.className = 'db-template-modal-content';
  content.style.cssText = 'display:flex;flex-direction:column;min-height:0;height:100%;';

  // 検索
  const searchInput = document.createElement('input');
  searchInput.type = 'search';
  searchInput.className = 'gb-input db-template-search-input';
  searchInput.dataset.e2eId = 'db-template-search-input';
  searchInput.placeholder = 'テンプレートを検索';
  searchInput.setAttribute('aria-label', 'テンプレートを検索（名前・説明・列名）');
  searchInput.style.flex = '0 0 auto';
  content.appendChild(searchInput);
  const desc = document.createElement('div');
  desc.id = descId;
  desc.className = 'gb-visually-hidden';
  desc.textContent = 'シートに適用するテンプレートを選ぶダイアログ';
  content.appendChild(desc);

  // Tierチップ行（旧: 左サイドバー）
  const tierRow = document.createElement('div');
  tierRow.className = 'db-template-tier-row';
  tierRow.style.flex = '0 0 auto';
  tierRow.setAttribute('role', 'group');
  tierRow.setAttribute('aria-label', 'テンプレート種別');
  let currentTier = 'all';
  const tierFilters = [
    { key: 'all', label: 'すべて' },
    { key: '1', label: '基本' },
    { key: '2', label: '標準' },
    { key: '3', label: 'ジャンル別' },
    { key: 'custom', label: 'カスタム' },
  ];
  tierFilters.forEach(tf => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = tf.label;
    btn.className = 'gb-btn gb-btn-sm template-tier-btn' + (tf.key === 'all' ? ' active' : '');
    btn.dataset.tier = tf.key;
    btn.dataset.e2eId = `db-template-tier-${tf.key}`;
    btn.setAttribute('aria-pressed', tf.key === 'all' ? 'true' : 'false');
    btn.addEventListener('click', () => {
      currentTier = tf.key;
      tierRow.querySelectorAll('.template-tier-btn').forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-pressed', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-pressed', 'true');
      renderTemplateCards();
    });
    tierRow.appendChild(btn);
  });
  content.appendChild(tierRow);

  // 本体: カードグリッド + プレビューペイン
  const body = document.createElement('div');
  body.className = 'db-template-body';
  body.style.overflowX = 'hidden';
  const cardCol = document.createElement('div');
  cardCol.className = 'db-template-card-col';
  const grid = document.createElement('div');
  grid.className = 'template-grid';
  grid.dataset.e2eId = 'db-template-grid';
  grid.style.overflowX = 'hidden';
  cardCol.appendChild(grid);
  body.appendChild(cardCol);

  let previewPane = null;
  if (!isMobile) {
    previewPane = document.createElement('div');
    previewPane.className = 'db-template-preview-pane';
    previewPane.dataset.e2eId = 'db-template-preview-pane';
    body.appendChild(previewPane);
  }
  content.appendChild(body);

  // フッター: カスタムテンプレート作成
  const createBtn = document.createElement('button');
  _setupDbTemplateButton(createBtn, 'gb-btn gb-btn-sm', 'db-template-create-open');
  createBtn.textContent = '+ 現在のシートからテンプレート作成';
  createBtn.addEventListener('click', () => {
    _closeDbTemplateOverlay(overlay, trigger, { restoreFocus: false, reason: 'create' });
    showCreateTemplateModal(dbPath, trigger);
  });
  const cancelBtn = document.createElement('button');
  _setupDbTemplateButton(cancelBtn, 'gb-btn gb-btn-sm', 'db-template-gallery-cancel');
  cancelBtn.textContent = '閉じる';
  let busy = false;
  const releaseOverflowLock = _lockDbTemplateHorizontalOverflow();
  const modalApi = window.GBUI.createModal({
    id: `db-template-gallery-${seq}`,
    title: 'シートテンプレート',
    body: content,
    footer: [createBtn, cancelBtn],
    variant: 'standard',
    extraClass: 'db-template-gallery-modal',
    geometryKey: 'db-template-gallery',
    minWidth: '0',
    initialFocus: dialog => dialog,
    returnFocus: trigger || undefined,
    closeLabel: 'シートテンプレートを閉じる',
    onBeforeClose: reason => !busy || reason === 'applied' || reason === 'superseded',
    onClose: releaseOverflowLock,
  });
  const overlay = modalApi.overlay;
  const modal = modalApi.modal;
  modal.classList.add('modal', 'db-template-modal');
  overlay.classList.add('modal-overlay');
  overlay.dataset.dbTemplateModal = 'gallery';
  overlay.style.zIndex = '120';
  overlay._dbTemplateTrigger = trigger;
  overlay._dbTemplateClose = modalApi.close;
  overlay._dbTemplateSetBusy = (next) => {
    busy = !!next;
    modal.setAttribute('aria-busy', busy ? 'true' : 'false');
    modal.querySelectorAll('button, input').forEach(control => { control.disabled = busy; });
  };
  modal.dataset.e2eId = 'db-template-gallery-dialog';
  modal.setAttribute('aria-describedby', descId);
  modalApi.body.style.cssText = 'display:flex;flex-direction:column;min-height:0;overflow:hidden;';
  modalApi.footer.classList.add('db-template-footer');
  const closeBtn = modalApi.header.querySelector('.gb-modal-close');
  if (closeBtn) closeBtn.dataset.e2eId = 'db-template-gallery-close';
  cancelBtn.addEventListener('click', () => modalApi.close('cancel'));
  _setDbTemplateModalSize(modal, { maxWidth: 1040, maxHeight: 820, heightRatio: 0.85, minHeight: 480 });
  modalApi.open();

  let searchQuery = '';
  let selectedTemplateId = '';

  searchInput.addEventListener('input', () => {
    searchQuery = searchInput.value.trim();
    renderTemplateCards();
  });

  function matchesSearch(tmpl, query) {
    if (!query) return true;
    const q = query.toLowerCase();
    if ((tmpl.name || '').toLowerCase().includes(q)) return true;
    if ((tmpl.description || '').toLowerCase().includes(q)) return true;
    return (tmpl.properties || []).some(p => (p.name || '').toLowerCase().includes(q));
  }

  function selectTemplate(tmpl) {
    selectedTemplateId = tmpl.id;
    grid.querySelectorAll('.template-card').forEach(cardEl => {
      const isSelected = cardEl.dataset.templateId === tmpl.id;
      cardEl.classList.toggle('is-selected', isSelected);
      cardEl.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });
    if (previewPane) {
      _renderDbTemplatePreviewPane(previewPane, tmpl, dbPath, {
        overlay,
        onDeleted: () => renderTemplateCards(),
      });
    }
  }

  function renderTemplateCards() {
    grid.innerHTML = '';
    const templates = getAllTemplates();
    const filtered = templates.filter(t => {
      if (currentTier === 'custom') { if (t.tier !== 0) return false; }
      else if (currentTier !== 'all' && t.tier !== Number(currentTier)) return false;
      return matchesSearch(t, searchQuery);
    });

    if (filtered.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'db-template-empty';
      empty.dataset.e2eId = 'db-template-empty';
      empty.textContent = searchQuery
        ? '該当するテンプレートがありません'
        : (currentTier === 'custom' ? 'カスタムテンプレートはまだありません' : 'テンプレートがありません');
      grid.appendChild(empty);
      if (previewPane) {
        previewPane.innerHTML = '';
        delete previewPane.dataset.templateId;
        const hint = document.createElement('div');
        hint.className = 'db-template-preview-empty';
        hint.textContent = 'テンプレートを選ぶとここにプレビューが表示されます';
        previewPane.appendChild(hint);
      }
      return;
    }

    filtered.forEach(tmpl => {
      const card = _buildTemplateCard(tmpl, dbPath, {
        overlay,
        mobile: isMobile,
        selected: tmpl.id === selectedTemplateId,
        onSelect: () => selectTemplate(tmpl),
        onChanged: () => renderTemplateCards(),
      });
      grid.appendChild(card);
    });

    if (!isMobile) {
      const target = filtered.find(t => t.id === selectedTemplateId) || filtered[0];
      if (target) selectTemplate(target);
    }
  }

  renderTemplateCards();
}
/* ==============================
   gb-db-template-editor-ui.js: カスタムテンプレートの作成・編集
   名前/説明に加えてアイコンを共通アイコンポップアップ（GBIconAssets.openPicker）で設定できる。
   作成・編集は同一のフォームモーダルを mode: 'create' | 'edit' で共用する。
   ============================== */

/**
 * アイコンspecを保存用に正規化する。
 * Lucide選択時は生名（旧版の lucide('lucide:x') 空SVG化を避けるため）、
 * Noto選択時は 'noto:HEX' のまま保存する。
 */
function _dbTemplateIconSpecForSave(spec) {
  const normalized = (typeof GBIconAssets !== 'undefined' && GBIconAssets?.normalizeSpec)
    ? GBIconAssets.normalizeSpec(spec)
    : String(spec || '');
  if (!normalized) return 'file';
  return normalized.toLowerCase().startsWith('lucide:') ? normalized.slice(7) : normalized;
}

function _dbTemplateOpenIconPicker(anchorEl, currentIcon, onSelect) {
  if (typeof GBIconAssets === 'undefined' || typeof GBIconAssets.openPicker !== 'function') return;
  GBIconAssets.openPicker({
    title: 'テンプレートアイコンを選択',
    anchorEl,
    current: currentIcon,
    allowReset: true,
    resetLabel: '既定に戻す',
    onSelect: (spec) => onSelect(_dbTemplateIconSpecForSave(spec)),
    onReset: () => onSelect('file'),
  });
}

/**
 * アイコン設定欄を構築する。GBIconAssets 未ロード環境ではボタンを出さず
 * 既定アイコンのまま進める（行き止まりUI禁止）。
 */
function _buildDbTemplateIconField(initialIcon) {
  const field = document.createElement('div');
  field.className = 'field gb-field db-template-icon-field';
  const label = document.createElement('div');
  label.className = 'gb-label';
  label.textContent = 'アイコン';
  field.appendChild(label);

  let currentIcon = initialIcon || 'file';
  const hasIconPicker = typeof GBIconAssets !== 'undefined' && typeof GBIconAssets.openPicker === 'function';

  if (!hasIconPicker) {
    const fallback = document.createElement('div');
    fallback.className = 'db-template-icon-fallback';
    fallback.innerHTML = _dbTemplateIconHtml(currentIcon, 18);
    field.appendChild(fallback);
    return { field, getIcon: () => currentIcon };
  }

  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'gb-btn gb-btn-sm db-template-icon-button';
  button.dataset.e2eId = 'db-template-icon-button';
  button.setAttribute('aria-label', 'テンプレートアイコンを選択');
  // gb-dropdown-dismiss.js の「外側クリックで閉じる」対象から自身を除外し、
  // 開いた直後に自分自身のクリックでピッカーが閉じてしまわないようにする
  button.setAttribute('aria-haspopup', 'dialog');
  const iconPreview = document.createElement('span');
  iconPreview.className = 'db-template-icon-button-preview';
  const labelSpan = document.createElement('span');
  labelSpan.className = 'db-template-icon-button-label';
  labelSpan.textContent = 'アイコンを選ぶ';
  button.append(iconPreview, labelSpan);
  const updateButton = () => {
    iconPreview.innerHTML = _dbTemplateIconHtml(currentIcon, 18);
  };
  updateButton();
  button.addEventListener('click', () => {
    _dbTemplateOpenIconPicker(button, currentIcon, (nextIcon) => {
      currentIcon = nextIcon;
      updateButton();
    });
  });
  field.appendChild(button);
  return { field, getIcon: () => currentIcon };
}

/**
 * カスタムテンプレートの作成/編集フォームモーダル本体（両モード共用）。
 * @param {object} options - { mode: 'create'|'edit', dbPath, triggerEl, initialName, initialDescription,
 *   initialIcon, previewText, editNote, onSave(fields): boolean|void }
 */
function _showDbTemplateFormModal(options) {
  const trigger = _dbTemplateTrigger(options.triggerEl);
  const mode = options.mode === 'edit' ? 'edit' : 'create';
  const seq = Date.now().toString(36) + '-' + Math.floor(Math.random() * 1000).toString(36);
  const descId = `db-template-${mode}-desc-${seq}`;
  const nameId = `db-template-name-${seq}`;
  const detailId = `db-template-desc-${seq}`;

  const modalDesc = document.createElement('div');
  modalDesc.id = descId;
  modalDesc.className = 'gb-visually-hidden';
  modalDesc.textContent = mode === 'edit'
    ? 'カスタムテンプレートの名前・説明・アイコンを編集するダイアログ'
    : '現在のシート設定をカスタムテンプレートとして保存するダイアログ';
  const body = document.createElement('div');
  body.className = 'modal-body';
  body.appendChild(modalDesc);

  const iconField = _buildDbTemplateIconField(options.initialIcon);
  body.appendChild(iconField.field);

  // 名前入力
  const nameField = document.createElement('div');
  nameField.className = 'field gb-field';
  const nameLabel = document.createElement('label');
  nameLabel.className = 'gb-label';
  nameLabel.htmlFor = nameId;
  nameLabel.textContent = 'テンプレート名';
  nameField.appendChild(nameLabel);
  const nameInput = document.createElement('input');
  nameInput.id = nameId;
  nameInput.className = 'gb-input';
  nameInput.dataset.e2eId = 'db-template-name-input';
  nameInput.type = 'text';
  nameInput.placeholder = '例: キャラシート（カスタム）';
  nameInput.value = options.initialName || '';
  nameField.appendChild(nameInput);
  body.appendChild(nameField);

  // 説明入力
  const descField = document.createElement('div');
  descField.className = 'field gb-field';
  const descLabel = document.createElement('label');
  descLabel.className = 'gb-label';
  descLabel.htmlFor = detailId;
  descLabel.textContent = '説明';
  descField.appendChild(descLabel);
  const descInput = document.createElement('input');
  descInput.id = detailId;
  descInput.className = 'gb-input';
  descInput.dataset.e2eId = 'db-template-desc-input';
  descInput.type = 'text';
  descInput.placeholder = 'テンプレートの説明';
  descInput.value = options.initialDescription || '';
  descField.appendChild(descInput);
  body.appendChild(descField);

  // プロパティ/ビューのプレビュー概要
  const preview = document.createElement('div');
  preview.className = 'db-template-create-preview';
  preview.textContent = options.previewText || '';
  body.appendChild(preview);

  // 追加コンテンツの差し込み口（エントリレイアウトの画像同梱チェックリスト等）
  if (options.extraBody instanceof HTMLElement) body.appendChild(options.extraBody);

  if (mode === 'edit') {
    const note = document.createElement('div');
    note.className = 'db-template-edit-note';
    note.dataset.e2eId = 'db-template-edit-note';
    if (options.editNote) {
      note.textContent = options.editNote;
    } else {
      note.innerHTML = `名前・説明・アイコンのみ編集できます ${fieldHelp('列とビューは保存時点の内容のまま変更されません')}`;
    }
    body.appendChild(note);
  }
  // ボタン
  const cancelBtn = document.createElement('button');
  _setupDbTemplateButton(cancelBtn, 'gb-btn gb-btn-sm', 'db-template-' + mode + '-cancel');
  cancelBtn.textContent = 'キャンセル';
  const saveBtn = document.createElement('button');
  _setupDbTemplateButton(saveBtn, 'gb-btn gb-btn-sm gb-btn-primary primary', 'db-template-' + mode + '-save');
  saveBtn.textContent = '保存';
  let busy = false;
  let modalApi = null;
  const releaseOverflowLock = _lockDbTemplateHorizontalOverflow();
  const setBusy = (next) => {
    busy = !!next;
    if (!modalApi) return;
    modalApi.modal.setAttribute('aria-busy', busy ? 'true' : 'false');
    [cancelBtn, saveBtn, modalApi.header.querySelector('.gb-modal-close')].filter(Boolean)
      .forEach(control => { control.disabled = busy; });
  };
  saveBtn.addEventListener('click', async () => {
    if (busy) return;
    const name = nameInput.value.trim();
    if (!name) { showStatus('名前を入力してください', true); return; }
    setBusy(true);
    try {
      const result = await Promise.resolve(options.onSave({
        name,
        description: descInput.value.trim(),
        icon: iconField.getIcon(),
      }));
      if (result === false) return;
      modalApi.close('saved');
    } catch (error) {
      showStatus('カスタムテンプレートの保存に失敗: ' + (error?.message || error), true);
    } finally {
      if (modalApi.isOpen()) setBusy(false);
    }
  });
  modalApi = window.GBUI.createModal({
    id: `db-template-${mode}-${seq}`,
    title: mode === 'edit' ? 'カスタムテンプレート編集' : 'カスタムテンプレート作成',
    body,
    footer: [cancelBtn, saveBtn],
    variant: 'standard',
    extraClass: `db-template-${mode}-modal`,
    geometryKey: `db-template-${mode}`,
    minWidth: '0',
    initialFocus: nameInput,
    returnFocus: trigger || undefined,
    closeLabel: mode === 'edit' ? 'カスタムテンプレート編集を閉じる' : 'カスタムテンプレート作成を閉じる',
    onBeforeClose: reason => !busy || reason === 'saved' || reason === 'superseded',
    onClose: releaseOverflowLock,
  });
  const overlay = modalApi.overlay;
  const modal = modalApi.modal;
  modal.classList.add('modal', 'db-template-modal');
  overlay.classList.add('modal-overlay');
  overlay.dataset.dbTemplateModal = mode;
  overlay.style.zIndex = '120';
  overlay._dbTemplateTrigger = trigger;
  overlay._dbTemplateClose = modalApi.close;
  modal.dataset.e2eId = 'db-template-' + mode + '-dialog';
  modal.setAttribute('aria-describedby', descId);
  modalApi.footer.classList.add('db-template-footer');
  const closeBtn = modalApi.header.querySelector('.gb-modal-close');
  if (closeBtn) closeBtn.dataset.e2eId = `db-template-${mode}-close`;
  cancelBtn.addEventListener('click', () => modalApi.close('cancel'));
  _setDbTemplateModalSize(modal, { maxWidth: 500, maxHeight: 560, heightRatio: 0.66, minHeight: 400 });
  modalApi.open();
}

/**
 * 現在のシートからカスタムテンプレートを作成するダイアログを開く。
 */
function showCreateTemplateModal(dbPath, triggerEl = null) {
  const exported = exportDbAsTemplate(dbPath);
  if (exported.properties.length === 0) {
    showStatus('このシートには列タイプが設定されていません', true);
    return;
  }

  const viewCount = Array.isArray(exported.savedViews) ? exported.savedViews.length : 0;
  const layoutCount = Array.isArray(exported.entityLayouts) ? exported.entityLayouts.length : 0;
  const previewText = '含まれる列: ' + exported.properties.map(p => p.name).join(', ')
    + (viewCount ? `（ビュー${viewCount}件を含む）` : '')
    + (layoutCount ? `（トピックレイアウト${layoutCount}件を含む）` : '');

  // エントリレイアウト内のアップロード画像は「指定したものだけ」テンプレートへ同梱する（既定OFF）。
  // 同梱しない画像はパス参照のままになり、テンプレート適用先では画像の再設定が必要になる。
  const uploadImages = typeof listDbTemplateEntityLayoutUploadImages === 'function'
    ? listDbTemplateEntityLayoutUploadImages(exported)
    : [];
  let extraBody = null;
  if (uploadImages.length) {
    extraBody = document.createElement('div');
    extraBody.className = 'db-template-image-embed';
    extraBody.dataset.e2eId = 'db-template-image-embed';
    const head = document.createElement('div');
    head.className = 'db-template-image-embed-head';
    head.innerHTML = 'テンプレートへ同梱する画像 ' + (typeof fieldHelp === 'function'
      ? fieldHelp('チェックした画像はテンプレート自体に埋め込まれ、適用先でもそのまま表示されます（1枚500KBまで）。チェックしない画像は元ファイルの場所を参照するだけになり、適用先では画像の再設定が必要です')
      : '');
    extraBody.appendChild(head);
    uploadImages.forEach(item => {
      const row = document.createElement('label');
      row.className = 'db-template-image-embed-row';
      const check = document.createElement('input');
      check.type = 'checkbox';
      check.dataset.cellId = item.cellId;
      check.dataset.e2eId = 'db-template-image-embed-check';
      row.appendChild(check);
      const span = document.createElement('span');
      const fileName = String(item.path || '').split(/[\\/]/).pop() || '(画像)';
      span.textContent = (item.layoutName ? item.layoutName + ': ' : '') + fileName;
      row.appendChild(span);
      extraBody.appendChild(row);
    });
  }

  _showDbTemplateFormModal({
    mode: 'create',
    dbPath,
    triggerEl,
    initialName: '',
    initialDescription: '',
    initialIcon: exported.icon || 'file',
    previewText,
    extraBody,
    onSave: async ({ name, description, icon }) => {
      exported.name = name;
      exported.description = description;
      exported.icon = icon;
      if (extraBody && typeof embedDbTemplateEntityLayoutImages === 'function') {
        const selectedIds = Array.from(extraBody.querySelectorAll('input[type="checkbox"][data-cell-id]'))
          .filter(check => check.checked)
          .map(check => check.dataset.cellId);
        const embedResult = await embedDbTemplateEntityLayoutImages(exported, selectedIds);
        if (embedResult.skipped > 0) {
          showStatus(`同梱できなかった画像が${embedResult.skipped}件あります（500KB超またはアクセス不可）。パス参照のまま保存します`, true);
        }
      }
      const customs = getCustomTemplates();
      customs.push(exported);
      if (!saveCustomTemplates(customs, { label: 'シートテンプレート: カスタムテンプレート作成', detail: name })) return false;
      showStatus('カスタムテンプレート「' + name + '」を保存しました');
    },
  });
}

/**
 * 既存のカスタムテンプレートの名前・説明・アイコンを編集するダイアログを開く。
 * プロパティ・ビューは保存時点のスナップショットのまま変更しない。
 */
function showEditTemplateModal(tmpl, dbPath, triggerEl = null) {
  if (!tmpl || tmpl.tier !== 0) return;
  const propCount = (tmpl.properties || []).length;
  const viewCount = Array.isArray(tmpl.savedViews) ? tmpl.savedViews.length : 0;
  const previewText = `列${propCount}件` + (viewCount ? ` / ビュー${viewCount}件` : '');

  _showDbTemplateFormModal({
    mode: 'edit',
    dbPath,
    triggerEl,
    initialName: tmpl.name || '',
    initialDescription: tmpl.description || '',
    initialIcon: tmpl.icon || 'file',
    previewText,
    onSave: ({ name, description, icon }) => {
      const customs = getCustomTemplates();
      const idx = customs.findIndex(c => c.id === tmpl.id);
      if (idx < 0) { showStatus('カスタムテンプレートが見つかりません', true); return false; }
      customs[idx] = { ...customs[idx], name, description, icon };
      if (!saveCustomTemplates(customs, { label: 'シートテンプレート: カスタムテンプレート編集', detail: name })) return false;
      showStatus('カスタムテンプレート「' + name + '」を更新しました');
    },
  });
}

;

/* === gb-db-aggregate.js === */
;
/* ==============================
   gb-db-aggregate.js: 拡張集計エンジン
   プロパティ型に応じた集計タイプ（SUM/AVG/MIN/MAX等）を提供
   ============================== */

/* --- 集計タイプレジストリ --- */
const AGGREGATION_TYPES = {
  // 全型共通
  none:              { label: '-',          appliesTo: '*' },
  count:             { label: '件数',       appliesTo: '*' },
  unique:            { label: 'ユニーク',   appliesTo: '*' },
  empty:             { label: '空',         appliesTo: '*' },
  not_empty:         { label: '非空',       appliesTo: '*' },
  percent_empty:     { label: '空%',        appliesTo: '*' },
  percent_not_empty: { label: '非空%',      appliesTo: '*' },

  // number / formula / rollup 専用
  sum:     { label: '合計',   appliesTo: ['number', 'formula', 'rollup'] },
  average: { label: '平均',   appliesTo: ['number', 'formula', 'rollup'] },
  min:     { label: '最小',   appliesTo: ['number', 'formula', 'rollup'] },
  max:     { label: '最大',   appliesTo: ['number', 'formula', 'rollup'] },
  median:  { label: '中央値', appliesTo: ['number', 'formula', 'rollup'] },
  range:   { label: '範囲',   appliesTo: ['number', 'formula', 'rollup'] },

  // date 専用
  earliest:   { label: '最古', appliesTo: ['date'] },
  latest:     { label: '最新', appliesTo: ['date'] },
  date_range: { label: '期間', appliesTo: ['date'] },

  // checkbox 専用
  percent_checked: { label: 'チェック%', appliesTo: ['checkbox'] },
};

/**
 * プロパティ型に対して使用可能な集計タイプ一覧を返す
 * @param {string} propType - プロパティ型 ('text','number','date','select','checkbox','formula'等)
 * @returns {Array<{key:string, label:string}>}
 */
function getAggregationTypesForProperty(propType) {
  const type = propType || 'text';
  const result = [];
  for (const [key, def] of Object.entries(AGGREGATION_TYPES)) {
    if (def.appliesTo === '*' || (Array.isArray(def.appliesTo) && def.appliesTo.includes(type))) {
      result.push({ key, label: def.label });
    }
  }
  return result;
}

/**
 * プロパティ型が未設定の場合、値から型を推定する
 * @returns {string} 推定された型 ('number','date','checkbox','text')
 */
function inferPropertyType(propName, entitiesMap, entityNames, filterMode) {
  let numCount = 0, dateCount = 0, boolCount = 0, total = 0;
  const sampleSize = Math.min(entityNames.length, 200);
  for (let i = 0; i < entityNames.length && total < sampleSize; i++) {
    const entity = entitiesMap[entityNames[i]];
    if (!entity) continue;
    const vals = filterValues(entity[propName] || [], undefined, filterMode);
    if (vals.length === 0) continue;
    const v = vals[0].value;
    total++;
    if (/^\d{4}-\d{2}-\d{2}/.test(v)) { dateCount++; continue; }
    if (_toStrictNumber(v) !== null) { numCount++; continue; }
    if (_isCheckboxLikeValue(v)) { boolCount++; continue; }
  }
  if (total === 0) return 'text';
  if (boolCount / total > 0.8) return 'checkbox';
  if (numCount / total > 0.8) return 'number';
  if (dateCount / total > 0.8) return 'date';
  return 'text';
}

/* --- 値抽出ヘルパー --- */

function _toStrictNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value !== 'string') return null;
  const text = value.trim();
  if (!text) return null;
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(text)) return null;
  const num = Number(text);
  return Number.isFinite(num) ? num : null;
}

function _normalizeCheckboxText(value) {
  return String(value).trim().toLowerCase();
}

function _isCheckedValue(value) {
  if (value === true || value === 1) return true;
  if (typeof value !== 'string') return false;
  return ['true', '1', 'on', 'yes', 'はい'].includes(_normalizeCheckboxText(value));
}

function _isCheckboxLikeValue(value) {
  if (typeof value === 'boolean') return true;
  if (value === 0 || value === 1) return true;
  if (typeof value !== 'string') return false;
  return ['true', 'false', '1', '0', 'on', 'off', 'yes', 'no', 'はい', 'いいえ'].includes(_normalizeCheckboxText(value));
}

/**
 * エントリ群から数値の配列を抽出する
 */
function extractNumericValues(propName, entitiesMap, entityNames, ptc, propTypes, filterMode) {
  const nums = [];
  entityNames.forEach(en => {
    if (ptc && ptc.type === 'formula' && ptc.formula) {
      const result = formulaEvalForEntity(ptc.formula, entitiesMap[en], { propTypes });
      if (!result.error) {
        const n = _toStrictNumber(result.value);
        if (n !== null) nums.push(n);
      }
    } else {
      if (!entitiesMap[en]) return;
      const vals = filterValues(entitiesMap[en][propName] || [], undefined, filterMode);
      vals.forEach(v => {
        const n = _toStrictNumber(v.value);
        if (n !== null) nums.push(n);
      });
    }
  });
  return nums;
}

function _isRollupAggregationProperty(ptc) {
  return ptc && ptc.type === 'rollup';
}

function _aggregationValueIsPresent(value) {
  if (value === undefined || value === null) return false;
  const text = String(value).trim();
  return text !== '' && text !== '-';
}

async function _extractRollupComputedValues(propName, entitiesMap, entityNames, ptc, propTypes, filterMode, sourceDbPath) {
  if (!_isRollupAggregationProperty(ptc) || typeof calcRollupColumn !== 'function') return null;
  const rollupValues = await calcRollupColumn(
    entitiesMap,
    entityNames,
    ptc,
    propTypes,
    sourceDbPath || (typeof state !== 'undefined' ? state.currentDbPath : ''),
    filterMode
  );
  return entityNames.map(name => rollupValues.has(name) ? rollupValues.get(name) : undefined);
}

function _calcComputedValueAggregation(values, type, ptc) {
  if (type === 'none') return '';
  const presentValues = values.filter(_aggregationValueIsPresent);
  if (type === 'count') return presentValues.length;
  if (type === 'unique') return new Set(presentValues.map(v => String(v))).size;
  if (type === 'empty') return values.length - presentValues.length;
  if (type === 'not_empty') return presentValues.length;
  if (type === 'percent_empty' || type === 'percent_not_empty') {
    const denom = values.length;
    if (denom === 0) return '0%';
    const emptyCount = values.length - presentValues.length;
    if (type === 'percent_empty') return Math.round((emptyCount / denom) * 100) + '%';
    return Math.round((presentValues.length / denom) * 100) + '%';
  }
  if (['sum', 'average', 'min', 'max', 'median', 'range'].includes(type)) {
    const nums = presentValues.map(_toStrictNumber).filter(n => n !== null);
    if (nums.length === 0) return '-';
    return formatAggregationResult(_calcNumeric(nums, type), type, ptc);
  }
  if (['earliest', 'latest', 'date_range'].includes(type)) {
    const dates = presentValues.map(value => {
      const text = String(value || '').trim();
      return (typeof parseLocalDate === 'function') ? parseLocalDate(text) : new Date(text);
    }).filter(d => !isNaN(d.getTime()));
    if (dates.length === 0) return '-';
    return _calcDate(dates, type);
  }
  return '';
}

/**
 * エントリ群からDateの配列を抽出する
 */
function extractDateValues(propName, entitiesMap, entityNames, filterMode) {
  const dates = [];
  entityNames.forEach(en => {
    if (!entitiesMap[en]) return;
    const vals = filterValues(entitiesMap[en][propName] || [], undefined, filterMode);
    vals.forEach(v => {
      const raw = String(v.value ?? '');
      const parts = raw.includes('|') ? raw.split('|') : [raw];
      parts.map(part => part.trim()).filter(Boolean).forEach(part => {
        const d = (typeof parseLocalDate === 'function') ? parseLocalDate(part) : new Date(part);
        if (!isNaN(d.getTime())) dates.push(d);
      });
    });
  });
  return dates;
}

/**
 * エントリ群からチェックボックスの集計を返す
 */
function extractCheckboxStats(propName, entitiesMap, entityNames, filterMode) {
  // 値が存在するエントリのみ分母に含める（未入力はカウント外）
  let checked = 0, total = 0;
  entityNames.forEach(en => {
    if (!entitiesMap[en]) return;
    const vals = filterValues(entitiesMap[en][propName] || [], undefined, filterMode);
    if (vals.length === 0) return;
    total++;
    if (_isCheckedValue(vals[0].value)) checked++;
  });
  return { checked, total };
}

/* --- メイン集計関数 --- */

/**
 * 集計を計算する（calcColumnCountの拡張版）
 * @param {string} propName - プロパティ名
 * @param {object} entitiesMap - エントリデータマップ
 * @param {string[]} entityNames - エントリ名一覧
 * @param {string} type - 集計タイプキー
 * @param {object} ptc - プロパティ型設定 {type, formula, ...}
 * @returns {string|number} 集計結果
 */
function calcAggregation(propName, entitiesMap, entityNames, type, ptc, propTypes, filterMode) {
  if (type === 'none') return '';

  // 基本4種は既存のcalcColumnCountに委譲
  if (['count', 'unique', 'empty', 'not_empty'].includes(type)) {
    return calcColumnCount(propName, entitiesMap, entityNames, type, ptc, propTypes, filterMode);
  }

  const total = entityNames.length;
  if (total === 0) return '';

  // 実際の型を取得（未設定なら推定）
  const resolvedType = ptc?.type || inferPropertyType(propName, entitiesMap, entityNames, filterMode);

  // パーセント系
  if (type === 'percent_empty' || type === 'percent_not_empty') {
    const emptyCount = calcColumnCount(propName, entitiesMap, entityNames, 'empty', ptc, propTypes, filterMode);
    const notEmptyCount = calcColumnCount(propName, entitiesMap, entityNames, 'not_empty', ptc, propTypes, filterMode);
    const denom = Number(emptyCount) + Number(notEmptyCount);
    if (denom === 0) return '0%';
    if (type === 'percent_empty') return Math.round((emptyCount / denom) * 100) + '%';
    return Math.round((notEmptyCount / denom) * 100) + '%';
  }

  // チェックボックスパーセント
  if (type === 'percent_checked') {
    const stats = extractCheckboxStats(propName, entitiesMap, entityNames, filterMode);
    if (stats.total === 0) return '0%';
    return Math.round((stats.checked / stats.total) * 100) + '%';
  }

  // 数値系集計
  if (['sum', 'average', 'min', 'max', 'median', 'range'].includes(type)) {
    const nums = extractNumericValues(propName, entitiesMap, entityNames, ptc, propTypes, filterMode);
    if (nums.length === 0) return '-';
    return formatAggregationResult(_calcNumeric(nums, type), type, ptc);
  }

  // 日付系集計
  if (['earliest', 'latest', 'date_range'].includes(type)) {
    const dates = extractDateValues(propName, entitiesMap, entityNames, filterMode);
    if (dates.length === 0) return '-';
    return _calcDate(dates, type);
  }

  return '';
}

async function calcAggregationAsync(propName, entitiesMap, entityNames, type, ptc, propTypes, filterMode, options = {}) {
  if (!_isRollupAggregationProperty(ptc)) {
    return calcAggregation(propName, entitiesMap, entityNames, type, ptc, propTypes, filterMode);
  }
  const values = await _extractRollupComputedValues(
    propName,
    entitiesMap,
    entityNames,
    ptc,
    propTypes,
    filterMode,
    options.sourceDbPath || options.dbPath
  );
  if (!values) return calcAggregation(propName, entitiesMap, entityNames, type, ptc, propTypes, filterMode);
  return _calcComputedValueAggregation(values, type, ptc);
}

/**
 * 数値集計の計算コア
 */
function _calcNumeric(nums, type) {
  switch (type) {
    case 'sum':     return nums.reduce((a, b) => a + b, 0);
    case 'average': return nums.reduce((a, b) => a + b, 0) / nums.length;
    case 'min':     return nums.reduce((a, b) => a < b ? a : b);
    case 'max':     return nums.reduce((a, b) => a > b ? a : b);
    case 'median': {
      const sorted = [...nums].sort((a, b) => a - b);
      const mid = Math.floor(sorted.length / 2);
      return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
    }
    case 'range': {
      const mn = nums.reduce((a, b) => a < b ? a : b);
      const mx = nums.reduce((a, b) => a > b ? a : b);
      return mx - mn;
    }
    default:        return 0;
  }
}

/**
 * 日付集計の計算コア
 */
function _calcDate(dates, type) {
  dates.sort((a, b) => a - b);
  const earliest = dates[0];
  const latest = dates[dates.length - 1];

  if (type === 'earliest') return _formatDate(earliest);
  if (type === 'latest') return _formatDate(latest);

  // date_range: 期間を日数で表示
  const dayMs = 1000 * 60 * 60 * 24;
  const diffDays = Math.round((_aggregateDateUtc(latest) - _aggregateDateUtc(earliest)) / dayMs);
  if (diffDays < 1) return '同日';
  const range = _calendarDateRangeParts(earliest, latest);
  if (range.years < 1) return diffDays + '日';
  const years = range.years;
  const remaining = range.days;
  if (remaining === 0) return years + '年';
  return years + '年' + remaining + '日';
}

function _addYearsClamped(date, years) {
  const parts = _aggregateDateParts(date);
  const year = parts.year + years;
  const lastDay = new Date(Date.UTC(year, parts.month, 0)).getUTCDate();
  return _dateFromAggregateParts({
    year,
    month: parts.month,
    day: Math.min(parts.day, lastDay),
  });
}

function _calendarDateRangeParts(start, end) {
  const startParts = _aggregateDateParts(start);
  const endParts = _aggregateDateParts(end);
  let years = endParts.year - startParts.year;
  let anchor = _addYearsClamped(start, years);
  if (_aggregateDateUtc(anchor) > _aggregateDateUtc(end)) {
    years -= 1;
    anchor = _addYearsClamped(start, years);
  }
  const dayMs = 1000 * 60 * 60 * 24;
  const days = Math.max(0, Math.round((_aggregateDateUtc(end) - _aggregateDateUtc(anchor)) / dayMs));
  return { years: Math.max(0, years), days };
}

function _aggregateDateParts(d) {
  const text = _formatDate(d);
  const m = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return { year: d.getFullYear(), month: d.getMonth() + 1, day: d.getDate() };
  return {
    year: parseInt(m[1], 10),
    month: parseInt(m[2], 10),
    day: parseInt(m[3], 10),
  };
}

function _dateFromAggregateParts(parts) {
  const text = `${parts.year}-${String(parts.month).padStart(2, '0')}-${String(parts.day).padStart(2, '0')}`;
  return typeof parseLocalDate === 'function' ? parseLocalDate(text) : new Date(parts.year, parts.month - 1, parts.day);
}

function _aggregateDateUtc(d) {
  const parts = _aggregateDateParts(d);
  return Date.UTC(parts.year, parts.month - 1, parts.day);
}

/**
 * 日付を YYYY-MM-DD 形式でフォーマット
 */
function _formatDate(d) {
  if (typeof formatLocalDate === 'function') return formatLocalDate(d);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

/**
 * 集計結果をフォーマットする
 * @param {number} value - 計算結果
 * @param {string} type - 集計タイプ
 * @param {object} ptc - プロパティ型設定
 * @returns {string}
 */
function formatAggregationResult(value, type, ptc) {
  if (typeof value !== 'number') return String(value);

  // 整数ならそのまま、小数なら2桁まで
  const formatted = Number.isInteger(value) ? String(value) : value.toFixed(2);

  // 単位があれば付与
  if (ptc?.unit) return formatted + ptc.unit;

  return formatted;
}

;

/* === gb-db-chart.js === */
;
/* ==============================
   gb-db-chart.js: SVGチャートエンジン + チャートビューモード
   外部依存なし。SVGプリミティブでbar/pie/lineチャートを描画。
   ============================== */

/* --- カラーパレット --- */
const CHART_PALETTES = {
  default: ['#569cd6','#4ec9b0','#ce9178','#dcdcaa','#c586c0','#9cdcfe','#d7ba7d','#608b4e','#d16969','#b5cea8','#6a9955','#d4d4d4'],
  warm:    ['#d16969','#ce9178','#dcdcaa','#d7ba7d','#c586c0','#e06c75','#d19a66','#e5c07b','#f0a0a0','#cc7832','#e2b86b','#cf8e6d'],
  cool:    ['#569cd6','#4ec9b0','#9cdcfe','#6a9955','#b5cea8','#608b4e','#61afef','#56b6c2','#98c379','#7ec8e3','#5c6bc0','#00897b'],
};
const CHART_THEME_ACCENT_FALLBACK = '#569cd6';

/* --- SVGプリミティブ --- */

function _svgNS() { return 'http://www.w3.org/2000/svg'; }

function svgCreate(tag, attrs) {
  const el = document.createElementNS(_svgNS(), tag);
  if (attrs) Object.entries(attrs).forEach(([k, v]) => el.setAttribute(k, v));
  return el;
}

function svgRect(x, y, w, h, fill, rx) {
  return svgCreate('rect', { x, y, width: w, height: h, fill, rx: rx || 0 });
}

function svgLine(x1, y1, x2, y2, stroke, sw) {
  return svgCreate('line', { x1, y1, x2, y2, stroke, 'stroke-width': sw || 1 });
}

function svgText(x, y, text, opts) {
  const el = svgCreate('text', {
    x, y,
    fill: opts?.fill || 'var(--fg2)',
    'font-size': opts?.fontSize || '12',
    'text-anchor': opts?.anchor || 'middle',
    'dominant-baseline': opts?.baseline || 'auto',
  });
  if (opts?.transform) el.setAttribute('transform', opts.transform);
  el.textContent = text;
  return el;
}

function svgPath(d, fill, stroke) {
  const attrs = { d };
  if (fill) attrs.fill = fill;
  if (stroke) attrs.stroke = stroke;
  return svgCreate('path', attrs);
}

function svgGroup(x, y) {
  return svgCreate('g', { transform: 'translate(' + x + ',' + y + ')' });
}

/* --- チャート設定の取得/保存 --- */

function getChartConfig(dbPath, options = {}) {
  return getCurrentDbViewTypeSpecific(dbPath, 'chart', { ctx: options.ctx || null }) || {
    chartType: 'bar',
    xProperty: '',
    yAggregation: 'count',
    yProperty: null,
    showLabels: true,
    showLegend: true,
    palette: 'single',
    singleColor: '',
  };
}

function setChartConfig(dbPath, config, options = {}) {
  const chartConfig = { ...(config || {}) };
  delete chartConfig.propertyTypes;
  const label = options.historyLabel || options.label || '';
  setCurrentDbViewTypeSpecific(dbPath, 'chart', chartConfig, {
    ctx: options.ctx || null,
    historyLabel: label,
    detail: options.detail || '',
    skipHistory: options.skipHistory === true || !label,
  });
}

function _chartNumericProps(allProps, propTypes) {
  return allProps.filter(p => {
    const pt = propTypes[p]?.type;
    return pt === 'number' || pt === 'formula' || pt === 'rollup';
  });
}

function _normalizeChartConfig(config, allProps, dbPath) {
  const next = { ...(config || {}) };
  const propTypes = next.propertyTypes || (typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath) : {});
  next.showLabels = next.showLabels !== false;
  next.showLegend = next.showLegend !== false;
  if (next.palette !== 'single' && next.palette !== 'themeAccent' && !CHART_PALETTES[next.palette]) next.palette = 'single';
  next.singleColor = _chartNormalizeHexColor(next.singleColor) || '';
  if (!allProps.includes(next.xProperty)) next.xProperty = allProps[0] || '';
  const numProps = _chartNumericProps(allProps, propTypes);
  const numericAggs = ['sum', 'average', 'min', 'max', 'median'];
  if (!numericAggs.includes(next.yAggregation)) next.yAggregation = 'count';
  if (next.yAggregation !== 'count') {
    if (!numProps.length) {
      next.yAggregation = 'count';
      next.yProperty = null;
    } else if (!numProps.includes(next.yProperty)) {
      next.yProperty = numProps[0];
    }
  } else {
    next.yProperty = null;
  }
  next.propertyTypes = propTypes;
  return next;
}

function _chartNormalizeHexColor(value) {
  const text = String(value || '').trim();
  if (/^#[0-9a-f]{6}$/i.test(text)) return text;
  if (/^#[0-9a-f]{3}$/i.test(text)) {
    return '#' + text.slice(1).split('').map(ch => ch + ch).join('');
  }
  return '';
}

function _chartColorToHex(value, fallback = CHART_THEME_ACCENT_FALLBACK) {
  const hex = _chartNormalizeHexColor(value);
  if (hex) return hex;
  const match = String(value || '').match(/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/i);
  if (!match) return fallback;
  const toHex = (n) => Math.max(0, Math.min(255, Number(n) || 0)).toString(16).padStart(2, '0');
  return '#' + toHex(match[1]) + toHex(match[2]) + toHex(match[3]);
}

function _chartThemeAccentColor() {
  try {
    const cs = getComputedStyle(document.documentElement);
    return _chartColorToHex(cs.getPropertyValue('--accent') || '', CHART_THEME_ACCENT_FALLBACK);
  } catch {
    return CHART_THEME_ACCENT_FALLBACK;
  }
}

function _chartPaletteColors(chartConfig) {
  if (chartConfig?.palette === 'single') return [_chartNormalizeHexColor(chartConfig.singleColor) || _chartThemeAccentColor()];
  if (chartConfig?.palette === 'themeAccent') return [_chartThemeAccentColor()];
  return CHART_PALETTES[chartConfig?.palette] || CHART_PALETTES.default;
}

/* --- データ準備 --- */

/**
 * pivotDataからチャート用データを準備する
 * @returns {{ labels: string[], values: number[], colors: string[], total: number }}
 */
function prepareChartData(pivotData, chartConfig, dbPathOverride, options = {}) {
  if (!pivotData || !pivotData.entities) return { labels: [], values: [], colors: [], total: 0 };

  const entities = pivotData.entities;
  const dbPath = dbPathOverride || state.currentDbPath;
  const filterMode = options.filter ?? options.ctx?.filter;
  const entityNames = _chartFilteredEntityNames(pivotData, dbPath, options.ctx || null);
  const allProps = _collectChartProperties(entities, pivotData, dbPath);
  chartConfig = _normalizeChartConfig(chartConfig, allProps, dbPath);
  const xProp = chartConfig.xProperty;
  const yAgg = chartConfig.yAggregation || 'count';
  const palette = _chartPaletteColors(chartConfig);

  if (!xProp) return { labels: [], values: [], colors: [], total: 0 };

  // X軸プロパティの値でグルーピング
  const groups = Object.create(null);
  entityNames.forEach(en => {
    const vals = filterValues(entities[en][xProp] || [], undefined, filterMode);
    const key = vals.length > 0 ? String(vals[0].value ?? '') : '(空)';
    if (!Object.prototype.hasOwnProperty.call(groups, key)) groups[key] = [];
    groups[key].push(en);
  });

  const labels = _chartSortedLabels(Object.keys(groups));
  const values = [];

  if (yAgg === 'count') {
    // 各グループのエントリ数
    labels.forEach(label => values.push(groups[label].length));
  } else if (chartConfig.yProperty && ['sum', 'average', 'min', 'max', 'median'].includes(yAgg)) {
    // Y軸プロパティの集計
    const propTypes = chartConfig.propertyTypes || getPropertyTypes(dbPath);
    const yPtc = propTypes[chartConfig.yProperty] || null;
    labels.forEach(label => {
      const groupEntities = groups[label];
      // グループ内エントリだけのサブマップ
      const subMap = {};
      groupEntities.forEach(en => { subMap[en] = entities[en]; });
      const result = calcAggregation(chartConfig.yProperty, subMap, groupEntities, yAgg, yPtc, propTypes, filterMode);
      values.push(typeof result === 'number' ? result : parseFloat(result) || 0);
    });
  } else {
    labels.forEach(label => values.push(groups[label].length));
  }

  const colors = labels.map((_, i) => palette[i % palette.length]);
  const total = values.reduce((a, b) => a + b, 0);

  return { labels, values, colors, total };
}

async function prepareChartDataAsync(pivotData, chartConfig, dbPathOverride, options = {}) {
  if (!pivotData || !pivotData.entities) return { labels: [], values: [], colors: [], total: 0 };

  const entities = pivotData.entities;
  const dbPath = dbPathOverride || state.currentDbPath;
  const filterMode = options.filter ?? options.ctx?.filter;
  const entityNames = _chartFilteredEntityNames(pivotData, dbPath, options.ctx || null);
  const allProps = _collectChartProperties(entities, pivotData, dbPath);
  chartConfig = _normalizeChartConfig(chartConfig, allProps, dbPath);
  const propTypes = chartConfig.propertyTypes || getPropertyTypes(dbPath);
  const xProp = chartConfig.xProperty;
  const xPtc = propTypes?.[xProp] || null;
  const yAgg = chartConfig.yAggregation || 'count';
  const palette = _chartPaletteColors(chartConfig);

  if (!xProp) return { labels: [], values: [], colors: [], total: 0 };

  let rollupXValues = null;
  if (xPtc?.type === 'rollup' && typeof calcRollupColumn === 'function') {
    rollupXValues = await calcRollupColumn(entities, entityNames, xPtc, propTypes, dbPath, filterMode);
  }

  const groups = Object.create(null);
  entityNames.forEach(en => {
    let key = '';
    if (rollupXValues) {
      const rollupValue = rollupXValues.has(en) ? rollupXValues.get(en) : '';
      key = rollupValue == null || String(rollupValue).trim() === '' || String(rollupValue).trim() === '-' ? '(空)' : String(rollupValue);
    } else {
      const vals = filterValues(entities[en][xProp] || [], undefined, filterMode);
      key = vals.length > 0 ? String(vals[0].value ?? '') : '(空)';
    }
    if (!Object.prototype.hasOwnProperty.call(groups, key)) groups[key] = [];
    groups[key].push(en);
  });

  const labels = _chartSortedLabels(Object.keys(groups));
  const values = [];

  if (yAgg === 'count') {
    labels.forEach(label => values.push(groups[label].length));
  } else if (chartConfig.yProperty && ['sum', 'average', 'min', 'max', 'median'].includes(yAgg)) {
    const yPtc = propTypes[chartConfig.yProperty] || null;
    for (const label of labels) {
      const groupEntities = groups[label];
      const subMap = {};
      groupEntities.forEach(en => { subMap[en] = entities[en]; });
      const result = typeof calcAggregationAsync === 'function'
        ? await calcAggregationAsync(chartConfig.yProperty, subMap, groupEntities, yAgg, yPtc, propTypes, filterMode, { dbPath, sourceDbPath: dbPath })
        : calcAggregation(chartConfig.yProperty, subMap, groupEntities, yAgg, yPtc, propTypes, filterMode);
      values.push(typeof result === 'number' ? result : parseFloat(result) || 0);
    }
  } else {
    labels.forEach(label => values.push(groups[label].length));
  }

  const colors = labels.map((_, i) => palette[i % palette.length]);
  const total = values.reduce((a, b) => a + b, 0);

  return { labels, values, colors, total };
}

/* --- 棒グラフ --- */

function renderBarChart(data, w, h, options = {}) {
  if (data.labels.length === 0) {
    const svg = svgCreate('svg', { width: w, height: h, viewBox: '0 0 ' + w + ' ' + h });
    svg.appendChild(svgText(w / 2, h / 2, 'データなし', { fill: 'var(--fg2)', fontSize: '14' }));
    return svg;
  }

  const margin = { top: 20, right: 20, bottom: 80, left: 60 };
  const barCount = data.labels.length;
  const minBarW = 20;
  const barGap = 4;
  // コンテンツ幅: カテゴリ数が多い場合はSVG幅を拡張
  const neededCw = barCount * (minBarW + barGap) + barGap;
  const cw = Math.max(w - margin.left - margin.right, neededCw);
  const actualW = cw + margin.left + margin.right;
  const ch = h - margin.top - margin.bottom;

  const svg = svgCreate('svg', { width: actualW, height: h, viewBox: '0 0 ' + actualW + ' ' + h });
  const g = svgGroup(margin.left, margin.top);
  svg.appendChild(g);

  const scale = _chartValueScale(data.values);
  const barW = Math.max(minBarW, (cw - barGap * (barCount + 1)) / barCount);
  const showLabels = options.showLabels !== false;

  // Y軸グリッド線
  const gridSteps = _calcGridStepsRange(scale.min, scale.max);
  gridSteps.forEach(v => {
    const y = _chartValueToY(v, scale, ch);
    g.appendChild(svgLine(0, y, cw, y, 'var(--bg4)', 0.5));
    g.appendChild(svgText(-8, y + 4, _formatAxisVal(v), { anchor: 'end', fontSize: '11', fill: 'var(--fg2)' }));
  });

  // X軸ベースライン
  const zeroY = _chartValueToY(0, scale, ch);
  g.appendChild(svgLine(0, zeroY, cw, zeroY, 'var(--bg4)', 1));

  // バー描画
  data.labels.forEach((label, i) => {
    const x = barGap + i * (barW + barGap);
    const valY = _chartValueToY(data.values[i], scale, ch);
    const y = Math.min(valY, zeroY);
    const barH = Math.max(1, Math.abs(zeroY - valY));

    const rect = svgRect(x, y, barW, barH, data.colors[i], 3);
    const title = svgCreate('title');
    title.textContent = label + ': ' + _formatDisplayVal(data.values[i]);
    rect.appendChild(title);
    g.appendChild(rect);

    // 値ラベル
    if (showLabels && barH > 16 && data.values[i] >= 0) {
      g.appendChild(svgText(x + barW / 2, y - 4, _formatDisplayVal(data.values[i]), {
        fontSize: '11', fill: 'var(--fg)', anchor: 'middle',
      }));
    } else if (showLabels && barH > 16) {
      g.appendChild(svgText(x + barW / 2, y + barH + 12, _formatDisplayVal(data.values[i]), {
        fontSize: '11', fill: 'var(--fg)', anchor: 'middle',
      }));
    }

    // X軸ラベル（回転）
    const truncLabel = label.length > 12 ? label.slice(0, 11) + '…' : label;
    g.appendChild(svgText(x + barW / 2, ch + 8, truncLabel, {
      fontSize: '11', fill: 'var(--fg2)', anchor: 'end',
      transform: 'rotate(-40,' + (x + barW / 2) + ',' + (ch + 8) + ')',
    }));
  });

  return svg;
}

/* --- 円グラフ --- */

function renderPieChart(data, w, h, options = {}) {
  const svg = svgCreate('svg', { width: w, height: h, viewBox: '0 0 ' + w + ' ' + h });
  const positiveItems = data.labels.map((label, i) => ({
    label,
    value: data.values[i],
    color: data.colors[i],
  })).filter(item => item.value > 0);
  const positiveTotal = positiveItems.reduce((sum, item) => sum + item.value, 0);
  if (data.labels.length === 0 || positiveTotal === 0) {
    svg.appendChild(svgText(w / 2, h / 2, data.labels.length ? '正の値がありません' : 'データなし', { fill: 'var(--fg2)', fontSize: '14' }));
    return svg;
  }

  const showLabels = options.showLabels !== false;
  const showLegend = options.showLegend !== false;
  const cx = showLegend ? w * 0.4 : w / 2;
  const cy = h / 2;
  const r = Math.min(cx - 30, cy - 30);
  const legendX = cx + r + 40;

  if (positiveItems.length === 1) {
    const item = positiveItems[0];
    const circle = svgCreate('circle', { cx, cy, r, fill: item.color });
    const title = svgCreate('title');
    title.textContent = item.label + ': ' + _formatDisplayVal(item.value) + ' (100%)';
    circle.appendChild(title);
    svg.appendChild(circle);
    if (showLabels) {
      svg.appendChild(svgText(cx, cy, '100%', {
        fontSize: '11', fill: '#fff', anchor: 'middle', baseline: 'central',
      }));
    }
    if (showLegend) {
      svg.appendChild(svgRect(legendX, 14, 12, 12, item.color, 2));
      const truncLabel = item.label.length > 16 ? item.label.slice(0, 15) + '…' : item.label;
      svg.appendChild(svgText(legendX + 18, 24, truncLabel + ' (' + _formatDisplayVal(item.value) + ')', {
        fontSize: '11', fill: 'var(--fg2)', anchor: 'start',
      }));
    }
    return svg;
  }

  let startAngle = -Math.PI / 2;

  positiveItems.forEach(item => {
    const ratio = item.value / positiveTotal;
    const endAngle = startAngle + ratio * 2 * Math.PI;
    const largeArc = ratio > 0.5 ? 1 : 0;

    const x1 = cx + r * Math.cos(startAngle);
    const y1 = cy + r * Math.sin(startAngle);
    const x2 = cx + r * Math.cos(endAngle);
    const y2 = cy + r * Math.sin(endAngle);

    const d = 'M ' + cx + ' ' + cy + ' L ' + x1 + ' ' + y1 +
      ' A ' + r + ' ' + r + ' 0 ' + largeArc + ' 1 ' + x2 + ' ' + y2 + ' Z';
    const slice = svgPath(d, item.color);
    const title = svgCreate('title');
    title.textContent = item.label + ': ' + _formatDisplayVal(item.value) + ' (' + Math.round(ratio * 100) + '%)';
    slice.appendChild(title);
    svg.appendChild(slice);

    // スライスラベル（5%以上のみ）
    if (showLabels && ratio >= 0.05) {
      const midAngle = startAngle + (endAngle - startAngle) / 2;
      const lx = cx + r * 0.65 * Math.cos(midAngle);
      const ly = cy + r * 0.65 * Math.sin(midAngle);
      svg.appendChild(svgText(lx, ly, Math.round(ratio * 100) + '%', {
        fontSize: '11', fill: '#fff', anchor: 'middle', baseline: 'central',
      }));
    }

    startAngle = endAngle;
  });

  // 凡例
  if (showLegend) {
    const legendMaxItems = Math.min(positiveItems.length, Math.floor((h - 20) / 22));
    positiveItems.slice(0, legendMaxItems).forEach((item, i) => {
      const ly = 20 + i * 22;
      svg.appendChild(svgRect(legendX, ly - 6, 12, 12, item.color, 2));
      const truncLabel = item.label.length > 16 ? item.label.slice(0, 15) + '…' : item.label;
      svg.appendChild(svgText(legendX + 18, ly + 4, truncLabel + ' (' + _formatDisplayVal(item.value) + ')', {
        fontSize: '11', fill: 'var(--fg2)', anchor: 'start',
      }));
    });
  }

  return svg;
}

/* --- 折れ線グラフ --- */

function renderLineChart(data, w, h, options = {}) {
  const svg = svgCreate('svg', { width: w, height: h, viewBox: '0 0 ' + w + ' ' + h });
  if (data.labels.length === 0) {
    svg.appendChild(svgText(w / 2, h / 2, 'データなし', { fill: 'var(--fg2)', fontSize: '14' }));
    return svg;
  }

  const margin = { top: 20, right: 20, bottom: 80, left: 60 };
  const cw = w - margin.left - margin.right;
  const ch = h - margin.top - margin.bottom;
  const g = svgGroup(margin.left, margin.top);
  svg.appendChild(g);

  const scale = _chartValueScale(data.values);
  const n = data.labels.length;
  const showLabels = options.showLabels !== false;

  // Y軸グリッド線
  const gridSteps = _calcGridStepsRange(scale.min, scale.max);
  gridSteps.forEach(v => {
    const y = _chartValueToY(v, scale, ch);
    g.appendChild(svgLine(0, y, cw, y, 'var(--bg4)', 0.5));
    g.appendChild(svgText(-8, y + 4, _formatAxisVal(v), { anchor: 'end', fontSize: '11', fill: 'var(--fg2)' }));
  });

  // X軸ベースライン
  g.appendChild(svgLine(0, _chartValueToY(0, scale, ch), cw, _chartValueToY(0, scale, ch), 'var(--bg4)', 1));

  // データポイントの座標計算
  const points = data.labels.map((_, i) => {
    const x = n === 1 ? cw / 2 : (i / (n - 1)) * cw;
    const y = _chartValueToY(data.values[i], scale, ch);
    return { x, y };
  });

  // ライン描画
  if (points.length > 1) {
    const pathD = points.map((p, i) => (i === 0 ? 'M' : 'L') + ' ' + p.x + ' ' + p.y).join(' ');
    const line = svgPath(pathD, 'none', data.colors[0]);
    line.setAttribute('stroke-width', '2');
    line.setAttribute('fill', 'none');
    g.appendChild(line);
  }

  // ドット描画
  points.forEach((p, i) => {
    const circle = svgCreate('circle', { cx: p.x, cy: p.y, r: 4, fill: data.colors[0] });
    const title = svgCreate('title');
    title.textContent = data.labels[i] + ': ' + _formatDisplayVal(data.values[i]);
    circle.appendChild(title);
    g.appendChild(circle);
    if (showLabels) {
      g.appendChild(svgText(p.x, Math.max(10, p.y - 10), _formatDisplayVal(data.values[i]), {
        fontSize: '11', fill: 'var(--fg)', anchor: 'middle',
      }));
    }
  });

  // X軸ラベル
  const labelStep = Math.max(1, Math.ceil(n / 15));
  data.labels.forEach((label, i) => {
    if (i % labelStep !== 0 && i !== n - 1) return;
    const x = n === 1 ? cw / 2 : (i / (n - 1)) * cw;
    const truncLabel = label.length > 10 ? label.slice(0, 9) + '…' : label;
    g.appendChild(svgText(x, ch + 8, truncLabel, {
      fontSize: '11', fill: 'var(--fg2)', anchor: 'end',
      transform: 'rotate(-40,' + x + ',' + (ch + 8) + ')',
    }));
  });

  return svg;
}

/* --- ユーティリティ --- */

/** スタックオーバーフロー安全な最大値（spread演算子の代替） */
function _safeMax(arr, defaultVal) {
  if (arr.length === 0) return defaultVal || 0;
  let max = arr[0];
  for (let i = 1; i < arr.length; i++) { if (arr[i] > max) max = arr[i]; }
  return max;
}

function _safeMin(arr, defaultVal) {
  if (arr.length === 0) return defaultVal || 0;
  let min = arr[0];
  for (let i = 1; i < arr.length; i++) { if (arr[i] < min) min = arr[i]; }
  return min;
}

function _chartValueScale(values) {
  if (!values.length) return { min: 0, max: 1, range: 1 };
  let min = Math.min(0, _safeMin(values, 0));
  let max = Math.max(0, _safeMax(values, 0));
  if (min === max) {
    max = min + 1;
    min = Math.min(0, min);
  }
  return { min, max, range: max - min || 1 };
}

function _chartValueToY(value, scale, height) {
  return height - ((value - scale.min) / scale.range) * height;
}

function _calcGridStepsRange(minVal, maxVal) {
  const steps = [];
  const range = maxVal - minVal || 1;
  for (let i = 0; i <= 5; i++) {
    steps.push(minVal + (range * i / 5));
  }
  if (minVal < 0 && maxVal > 0) steps.push(0);
  return [...new Set(steps.map(v => Number(v.toFixed(6))))].sort((a, b) => a - b);
}

function _calcGridSteps(maxVal) {
  if (maxVal <= 0) return [0];
  const rawStep = maxVal / 5;
  const magnitude = Math.pow(10, Math.floor(Math.log10(rawStep)));
  const normalized = rawStep / magnitude;
  let step;
  if (normalized <= 1) step = magnitude;
  else if (normalized <= 2) step = 2 * magnitude;
  else if (normalized <= 5) step = 5 * magnitude;
  else step = 10 * magnitude;

  const steps = [];
  for (let v = 0; v <= maxVal; v += step) {
    if (v > 0) steps.push(v);
  }
  return steps;
}

function _formatAxisVal(v) {
  const sign = v < 0 ? '-' : '';
  const abs = Math.abs(v);
  if (abs >= 1000000) return sign + (abs / 1000000).toFixed(1) + 'M';
  if (abs >= 1000) return sign + (abs / 1000).toFixed(1) + 'K';
  return Number.isInteger(v) ? String(v) : v.toFixed(1);
}

function _formatDisplayVal(v) {
  if (typeof v !== 'number') return String(v);
  return Number.isInteger(v) ? String(v) : v.toFixed(2);
}

function _chartLabelSortValue(label) {
  const text = String(label ?? '').trim();
  if (!text || text === '(空)') return null;
  if (/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(text)) {
    const n = Number(text);
    if (Number.isFinite(n)) return { type: 'number', value: n };
  }
  if (/^\d{4}[-/]\d{2}(?:[-/]\d{2})?/.test(text)) {
    const d = typeof parseLocalDate === 'function' ? parseLocalDate(text) : new Date(text);
    if (!Number.isNaN(d.getTime())) return { type: 'date', value: d.getTime() };
  }
  return null;
}

function _chartSortedLabels(labels) {
  return [...labels].sort((a, b) => {
    const av = _chartLabelSortValue(a);
    const bv = _chartLabelSortValue(b);
    if (av && bv && av.type === bv.type && av.value !== bv.value) return av.value - bv.value;
    if (av && !bv) return -1;
    if (!av && bv) return 1;
    return String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' });
  });
}

/* --- メインレンダラ --- */

/**
 * チャートビューを描画する
 */
async function renderChart(ctx) {
  ctx = ctx || _currentPaneState();
  const container = typeof _dbViewSurfaceEl === 'function'
    ? _dbViewSurfaceEl(ctx, '.chart-view', 'chart-view')
    : ((ctx?.containerEl ? ctx.containerEl.querySelector('.chart-view') : null) || document.getElementById('chart-view') || document.querySelector('.chart-view'));
  if (!container) return;
  if (!_chartIsActiveView(ctx, container)) {
    _disconnectChartResizeObserver(container);
    return;
  }
  container.style.display = 'flex';
  container.innerHTML = '';

  const dbPath = ctx.dbPath || state.currentDbPath;
  const pivotData = ctx.pivotData || state.pivotData;
  if (!dbPath || !pivotData) {
    _disconnectChartResizeObserver(container);
    container.textContent = 'シートを選択してください';
    return;
  }

  let config = getChartConfig(dbPath, { ctx });
  const entities = pivotData.entities || {};
  if (Object.keys(entities).length === 0) {
    if (typeof _dbRenderEmptyStateWithCreate === 'function') {
      _dbRenderEmptyStateWithCreate(container, 'barChart2', 'トピックがありません', 'トピックを追加するとチャートが表示されます', ctx);
    } else {
      renderEmptyState(container, 'barChart2', 'トピックがありません', 'トピックを追加するとチャートが表示されます');
    }
    return;
  }
  const allProps = _collectChartProperties(entities, pivotData, dbPath);

  config = _normalizeChartConfig(config, allProps, dbPath);
  const savedConfig = getChartConfig(dbPath, { ctx });
  const configForSave = { ...config };
  delete configForSave.propertyTypes;
  if (JSON.stringify(configForSave) !== JSON.stringify(savedConfig)) {
    setChartConfig(dbPath, config, { ctx });
  }

  // 設定バー
  const bar = _buildChartSettingsBar(dbPath, config, allProps, ctx);
  container.appendChild(bar);

  // チャート描画エリア
  const chartArea = document.createElement('div');
  chartArea.className = 'chart-area';
  chartArea.style.overflowX = 'auto';
  chartArea.style.overflowY = 'hidden';
  container.appendChild(chartArea);

  // チャート描画（containerのサイズを使用 — chartAreaは新規要素でサイズ未確定のため）
  const data = typeof prepareChartDataAsync === 'function'
    ? await prepareChartDataAsync(pivotData, config, dbPath, { ctx, filter: ctx?.filter })
    : prepareChartData(pivotData, config, dbPath, { ctx, filter: ctx?.filter });
  if (!_chartIsActiveView(ctx, container)) {
    _disconnectChartResizeObserver(container);
    return;
  }
  const containerRect = container.getBoundingClientRect();
  const w = Math.max(containerRect.width - 32 || 600, 400);  // padding分を差し引く
  const h = Math.max(containerRect.height - 80 || 400, 300);  // settings bar分を差し引く

  let svg;
  const renderOptions = {
    showLabels: config.showLabels !== false,
    showLegend: config.showLegend !== false,
  };
  switch (config.chartType) {
    case 'pie':  svg = renderPieChart(data, w, h, renderOptions); break;
    case 'line': svg = renderLineChart(data, w, h, renderOptions); break;
    default:     svg = renderBarChart(data, w, h, renderOptions); break;
  }
  chartArea.appendChild(svg);

  // ResizeObserverでリサイズ時に再描画（containerを監視 — chartAreaは毎回再生成されるため）
  if (container._resizeTimer) clearTimeout(container._resizeTimer);
  if (container._resizeObs) container._resizeObs.disconnect();
  let resizeTimer = null;
  let lastW = containerRect.width, lastH = containerRect.height;
  if (typeof ResizeObserver !== 'function') return;
  container._resizeObs = new ResizeObserver(entries => {
    if (!_chartIsActiveView(ctx, container)) {
      _disconnectChartResizeObserver(container);
      return;
    }
    const entry = entries[0];
    if (!entry) return;
    const newW = entry.contentRect.width, newH = entry.contentRect.height;
    // サイズが実際に変化した場合のみ再描画（無限ループ防止）
    if (Math.abs(newW - lastW) < 2 && Math.abs(newH - lastH) < 2) return;
    lastW = newW; lastH = newH;
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => renderChart(ctx), 200);
    container._resizeTimer = resizeTimer;
  });
  container._resizeObs.observe(container);
}

function _renderChartForDbPanels(dbPath, preferredCtx) {
  const targets = typeof _dbPaneContextsForPath === 'function'
    ? _dbPaneContextsForPath(dbPath)
    : [preferredCtx || (typeof _currentPaneState === 'function' ? _currentPaneState() : null)].filter(Boolean);
  if (preferredCtx && !targets.includes(preferredCtx)) targets.unshift(preferredCtx);
  (targets.length ? targets : [preferredCtx]).forEach(targetCtx => renderChart(targetCtx));
}

function _disconnectChartResizeObserver(container) {
  if (!container) return;
  if (container._resizeTimer) {
    clearTimeout(container._resizeTimer);
    container._resizeTimer = null;
  }
  if (container._resizeObs) {
    container._resizeObs.disconnect();
    container._resizeObs = null;
  }
}

function _chartIsActiveView(ctx, container) {
  const c = ctx || (typeof _currentPaneState === 'function' ? _currentPaneState() : null);
  const dbPath = c?.dbPath || (typeof state !== 'undefined' ? state.currentDbPath : '');
  if (!dbPath) return false;
  if (typeof _dbCurrentViewModeForContext === 'function') {
    try { return _dbCurrentViewModeForContext(c, dbPath) === 'chart'; } catch {}
  }
  if (typeof getCurrentViewMode === 'function') {
    try { return getCurrentViewMode(dbPath, { ctx: c }) === 'chart'; } catch {}
  }
  if (c && c.viewMode) return c.viewMode === 'chart';
  return !container || container.style.display !== 'none';
}

/**
 * チャートで使用可能なプロパティ一覧を収集
 */
function _chartPropertyAllowed(propName) {
  return !!propName && !String(propName).startsWith('_');
}

function _collectChartProperties(entities, pivotData, dbPath) {
  const propSet = new Set();
  const add = (propName) => {
    if (_chartPropertyAllowed(propName)) propSet.add(propName);
  };
  const props = Array.isArray(pivotData) ? pivotData : (pivotData?.properties || []);
  props.forEach(add);
  const propTypes = pivotData?.propertyTypes || (typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath) : {});
  Object.keys(propTypes || {}).forEach(add);
  Object.values(entities).forEach(entData => {
    Object.keys(entData).forEach(k => {
      add(k);
    });
  });
  const names = [...propSet];
  return typeof filterDeletedDbProperties === 'function' ? filterDeletedDbProperties(dbPath, names) : names;
}

function _chartFilteredEntityNames(pivotData, dbPath, ctx) {
  const entities = pivotData?.entities || {};
  let names = Object.keys(entities);
  const advFilters = typeof getAdvancedFilters === 'function' ? getAdvancedFilters(dbPath, { ctx }) : [];
  const filterMode = ctx?.filter;
  if (Array.isArray(advFilters) && advFilters.length > 0 && typeof _dbEntityPassesAdvancedFilters === 'function') {
    names = names.filter(name => _dbEntityPassesAdvancedFilters(entities[name], advFilters, filterMode));
  }
  const columnValueFilters = typeof getColumnValueFilters === 'function'
    ? getColumnValueFilters(dbPath, { ctx })
    : {};
  if (typeof _dbEntityPassesColumnValueFilters === 'function' && Object.keys(columnValueFilters).length) {
    names = names.filter(name => _dbEntityPassesColumnValueFilters(
      name,
      entities[name],
      columnValueFilters,
      dbPath,
      ctx,
      filterMode,
    ));
  }
  return names;
}

/**
 * チャート設定バーを構築
 */
function _buildChartSettingsBar(dbPath, config, allProps, ctx) {
  const bar = document.createElement('div');
  bar.className = 'chart-settings-bar';
  const chartScope = 'chart-' + ((ctx && ctx.paneId) || 'main');

  // チャートタイプ
  bar.appendChild(_chartLabel('タイプ'));
  const typeSelect = _chartSelect([
    { key: 'bar', label: '棒グラフ' },
    { key: 'pie', label: '円グラフ' },
    { key: 'line', label: '折れ線' },
  ], config.chartType, chartScope + '-type', 'チャートタイプ');
  typeSelect.addEventListener('change', () => {
    config.chartType = typeSelect.value;
    setChartConfig(dbPath, config, { ctx, label: 'シート表示: チャート設定', detail: 'タイプ' });
    _renderChartForDbPanels(dbPath, ctx);
  });
  bar.appendChild(typeSelect);

  // X軸プロパティ
  bar.appendChild(_chartLabel('X軸'));
  const xSelect = _chartSelect(
    allProps.map(p => ({ key: p, label: p })),
    config.xProperty,
    chartScope + '-x-property',
    'チャートX軸の列'
  );
  xSelect.addEventListener('change', () => {
    config.xProperty = xSelect.value;
    setChartConfig(dbPath, config, { ctx, label: 'シート表示: チャート設定', detail: 'X軸' });
    _renderChartForDbPanels(dbPath, ctx);
  });
  bar.appendChild(xSelect);

  // Y軸集計
  bar.appendChild(_chartLabel('Y軸'));
  const yAggOptions = [{ key: 'count', label: '件数' }];
  // 数値プロパティがあれば追加集計を表示
  const propTypes = config.propertyTypes || getPropertyTypes(dbPath);
  const numericAggs = [
    { key: 'sum', label: '合計' },
    { key: 'average', label: '平均' },
    { key: 'min', label: '最小' },
    { key: 'max', label: '最大' },
    { key: 'median', label: '中央値' },
  ];
  const numProps = _chartNumericProps(allProps, propTypes);
  const hasNumeric = numProps.length > 0;
  if (hasNumeric) numericAggs.forEach(a => yAggOptions.push(a));

  const yAggSelect = _chartSelect(yAggOptions, config.yAggregation, chartScope + '-y-aggregation', 'チャートY軸集計');
  yAggSelect.addEventListener('change', () => {
    config.yAggregation = yAggSelect.value;
    config.yProperty = config.yAggregation === 'count' ? null : (numProps.includes(config.yProperty) ? config.yProperty : (numProps[0] || null));
    setChartConfig(dbPath, config, { ctx, label: 'シート表示: チャート設定', detail: 'Y軸' });
    _renderChartForDbPanels(dbPath, ctx);
  });
  bar.appendChild(yAggSelect);

  // Y軸プロパティ（集計がcount以外の場合）
  if (config.yAggregation !== 'count' && hasNumeric) {
    bar.appendChild(_chartLabel('対象'));
    const yPropSelect = _chartSelect(
      numProps.map(p => ({ key: p, label: p })),
      config.yProperty || numProps[0] || '',
      chartScope + '-y-property',
      'チャートY軸対象の列'
    );
    yPropSelect.addEventListener('change', () => {
      config.yProperty = yPropSelect.value;
      setChartConfig(dbPath, config, { ctx, label: 'シート表示: チャート設定', detail: '対象' });
      _renderChartForDbPanels(dbPath, ctx);
    });
    bar.appendChild(yPropSelect);
  }

  // パレット選択
  bar.appendChild(_chartLabel('配色'));
  const paletteSelect = _chartSelect([
    { key: 'single', label: '単色' },
    { key: 'themeAccent', label: 'テーマカラー' },
    { key: 'default', label: 'デフォルト' },
    { key: 'warm', label: 'ウォーム' },
    { key: 'cool', label: 'クール' },
  ], config.palette || 'single', chartScope + '-palette', 'チャート配色');
  paletteSelect.addEventListener('change', () => {
    config.palette = paletteSelect.value;
    if (config.palette === 'single' && !_chartNormalizeHexColor(config.singleColor)) config.singleColor = _chartThemeAccentColor();
    setChartConfig(dbPath, config, { ctx, label: 'シート表示: チャート設定', detail: '配色' });
    _renderChartForDbPanels(dbPath, ctx);
  });
  bar.appendChild(paletteSelect);
  if ((config.palette || 'single') === 'single') {
    const singleColor = document.createElement('input');
    singleColor.type = 'color';
    singleColor.className = 'chart-color-input';
    singleColor.value = _chartNormalizeHexColor(config.singleColor) || _chartThemeAccentColor();
    singleColor.dataset.e2eId = chartScope + '-single-color';
    singleColor.setAttribute('aria-label', 'チャート単色カラー');
    singleColor.title = '単色カラー';
    singleColor.addEventListener('change', () => {
      config.palette = 'single';
      config.singleColor = _chartNormalizeHexColor(singleColor.value) || _chartThemeAccentColor();
      setChartConfig(dbPath, config, { ctx, label: 'シート表示: チャート設定', detail: '単色カラー' });
      _renderChartForDbPanels(dbPath, ctx);
    });
    bar.appendChild(singleColor);
  }

  const labelsToggle = _chartCheckbox('値ラベル', config.showLabels !== false, chartScope + '-show-labels', 'チャート値ラベル表示');
  labelsToggle.input.addEventListener('change', () => {
    config.showLabels = labelsToggle.input.checked;
    setChartConfig(dbPath, config, { ctx, label: 'シート表示: チャート設定', detail: '値ラベル' });
    _renderChartForDbPanels(dbPath, ctx);
  });
  bar.appendChild(labelsToggle.el);

  if (config.chartType === 'pie') {
    const legendToggle = _chartCheckbox('凡例', config.showLegend !== false, chartScope + '-show-legend', 'チャート凡例表示');
    legendToggle.input.addEventListener('change', () => {
      config.showLegend = legendToggle.input.checked;
      setChartConfig(dbPath, config, { ctx, label: 'シート表示: チャート設定', detail: '凡例' });
      _renderChartForDbPanels(dbPath, ctx);
    });
    bar.appendChild(legendToggle.el);
  }

  return bar;
}

function _chartLabel(text) {
  const span = document.createElement('span');
  span.className = 'chart-label';
  span.textContent = text;
  return span;
}

function _chartSelect(options, selectedValue, e2eId = '', label = '') {
  const sel = document.createElement('select');
  sel.className = 'chart-select';
  if (e2eId) sel.dataset.e2eId = e2eId;
  if (label) sel.setAttribute('aria-label', label);
  options.forEach(opt => {
    const o = document.createElement('option');
    o.value = opt.key;
    o.textContent = opt.label;
    if (opt.key === selectedValue) o.selected = true;
    sel.appendChild(o);
  });
  return sel;
}

function _chartCheckbox(text, checked, e2eId = '', label = '') {
  const wrap = document.createElement('label');
  wrap.className = 'chart-check';
  const input = document.createElement('input');
  input.type = 'checkbox';
  input.checked = !!checked;
  if (e2eId) input.dataset.e2eId = e2eId;
  if (label) input.setAttribute('aria-label', label);
  const span = document.createElement('span');
  span.textContent = text;
  wrap.appendChild(input);
  wrap.appendChild(span);
  return { el: wrap, input };
}

;

/* === gb-db-entity-layout.js === */
;
/* gb-db-entity-layout.js: エントリレイアウト（シートのエントリ編集画面の自由配置レイアウト）
   - データモデルと永続化: view_config 内の entityLayouts / entityTabOrder / currentEntityTab。
     ビュー設定と同じ getDbViewConfig/saveDbViewConfig（localStorage即時 + デバウンスPUT）に乗せる。
     バックエンドは view_config の中身を不透明に素通しするため、デスクトップ/Cloud/単独版の
     どの保存経路でも追加改修なしで永続化される（2026-08-19 実装時に確認済み）。
   - 「列一覧 ⇄ エントリレイアウト」タブ行: D&D並べ替え・リネーム・複製・削除・追加。
     エントリを開いた直後は entityTabOrder の先頭タブを表示する（並び順=初期表示、2026-08-13確定）。
   - キャンバス描画は gb-db-entity-layout-canvas.js、セル内容は gb-db-entity-layout-cells.js が担当。
   - 旧バージョン互換: すべて追加のみのフィールド。旧版は view_config 内の未知キーを温存したまま
     無視して読み込める（既存の entityPropsCollapsed 等と同じ扱い）。 */
'use strict';

const EL_COLUMNS_TAB_ID = 'columns';
const EL_DEFAULT_CANVAS_W = 1000;
const EL_DEFAULT_CANVAS_H = 700;
const EL_CANVAS_MIN = 200;
const EL_CANVAS_MAX = 8000;
const EL_CELL_TYPES = ['field', 'label', 'image', 'divider', 'chart'];
const EL_CELL_MIN_SIZE = 24;

function _elGenId(prefix) {
  return (prefix || 'el') + '-' + Date.now().toString(36) + '-' + Math.floor(Math.random() * 1679616).toString(36);
}

function _elIsObj(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function _elClampNum(value, min, max, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, Math.round(n)));
}

// セル1件を正規化する。未知の追加フィールド（style等）はそのまま温存する。
function _elNormalizeCell(cell, canvasW, canvasH) {
  const src = _elIsObj(cell) ? cell : {};
  const out = { ...src };
  out.id = typeof src.id === 'string' && src.id ? src.id : _elGenId('cell');
  // 未知のセル種別は温存する（新しい版で作られたデータを旧版が黙って壊さない前方互換ルール。
  // 描画側 _elBuildCellContent が種別名のプレースホルダを出す）
  out.type = typeof src.type === 'string' && src.type ? src.type : 'field';
  out.w = _elClampNum(src.w, EL_CELL_MIN_SIZE, EL_CANVAS_MAX, 220);
  out.h = _elClampNum(src.h, EL_CELL_MIN_SIZE, EL_CANVAS_MAX, 90);
  // x/y はキャンバスサイズでクランプしない（キャンバスを一時的に縮めても座標を
  // 恒久的に失わないため。表示は overflow:hidden で切れるだけで、拡げれば戻る）
  out.x = _elClampNum(src.x, 0, EL_CANVAS_MAX, 20);
  out.y = _elClampNum(src.y, 0, EL_CANVAS_MAX, 20);
  if (out.type === 'field') out.prop = String(src.prop || '');
  if (!_elIsObj(out.style)) out.style = {};
  return globalThis.MeldexDbTopicLayoutStyle?.normalizeCellStyleContract
    ? globalThis.MeldexDbTopicLayoutStyle.normalizeCellStyleContract(out)
    : out;
}

// レイアウト1件を正規化する。未知の追加フィールドは温存する。
function _elNormalizeLayout(layout) {
  const src = _elIsObj(layout) ? layout : {};
  const out = { ...src };
  out.id = typeof src.id === 'string' && src.id ? src.id : _elGenId('el');
  out.name = String(src.name || '').trim() || 'レイアウト';
  const size = _elIsObj(src.canvasSize) ? src.canvasSize : {};
  out.canvasSize = {
    w: _elClampNum(size.w, EL_CANVAS_MIN, EL_CANVAS_MAX, EL_DEFAULT_CANVAS_W),
    h: _elClampNum(size.h, EL_CANVAS_MIN, EL_CANVAS_MAX, EL_DEFAULT_CANVAS_H),
  };
  out.cells = (Array.isArray(src.cells) ? src.cells : [])
    .map(cell => _elNormalizeCell(cell, out.canvasSize.w, out.canvasSize.h));
  if (!_elIsObj(out.theme)) out.theme = null;
  return out;
}

/* view_config からエントリレイアウト状態を取り出して正規化する（cfgは変更しない）。
   tabOrder は「'columns' をちょうど1つ + 実在するレイアウトidをちょうど1つずつ」に補正する。 */
function _elNormalizeState(cfg) {
  const config = _elIsObj(cfg) ? cfg : {};
  const layouts = (Array.isArray(config.entityLayouts) ? config.entityLayouts : [])
    .filter(_elIsObj)
    .map(_elNormalizeLayout);
  const knownIds = new Set(layouts.map(l => l.id));
  const rawOrder = Array.isArray(config.entityTabOrder) ? config.entityTabOrder : [];
  const tabOrder = [];
  rawOrder.forEach(id => {
    const key = String(id || '');
    if (key === EL_COLUMNS_TAB_ID && !tabOrder.includes(EL_COLUMNS_TAB_ID)) tabOrder.push(EL_COLUMNS_TAB_ID);
    else if (knownIds.has(key) && !tabOrder.includes(key)) tabOrder.push(key);
  });
  if (!tabOrder.includes(EL_COLUMNS_TAB_ID)) tabOrder.unshift(EL_COLUMNS_TAB_ID);
  layouts.forEach(l => { if (!tabOrder.includes(l.id)) tabOrder.push(l.id); });
  let currentTab = String(config.currentEntityTab || '');
  if (currentTab !== EL_COLUMNS_TAB_ID && !knownIds.has(currentTab)) currentTab = tabOrder[0];
  return { layouts, tabOrder, currentTab };
}

// 「レイアウト」「レイアウト 2」…の形式で重複しない既定名を作る
function _elMakeNewLayoutName(layouts) {
  const names = new Set((layouts || []).map(l => String(l?.name || '')));
  const base = 'レイアウト';
  if (!names.has(base)) return base;
  let n = 2;
  while (names.has(base + ' ' + n)) n += 1;
  return base + ' ' + n;
}

// 複製時の既定名（savedViews の複製と同じ「名前 2」方式）
function _elMakeDuplicateName(sourceName, layouts) {
  const names = new Set((layouts || []).map(l => String(l?.name || '')));
  const base = String(sourceName || 'レイアウト').replace(/\s+\d+$/, '') || 'レイアウト';
  let n = 2;
  while (names.has(base + ' ' + n)) n += 1;
  return base + ' ' + n;
}

function _elGetState(dbPath) {
  if (!dbPath || typeof getDbViewConfig !== 'function') return null;
  return _elNormalizeState(getDbViewConfig(dbPath) || {});
}

// Cloud/mobile の権限・容量状態は、画面を開いた後にも変化する。描画時 options だけでなく
// grid の現在状態も毎回見ることで、切替前に開いたポップアップや遅延 callback からの
// 書き込みを止める。
function _elCanMutateGrid(grid, options) {
  return options?.readOnly !== true && grid?.__MeldexRuntimeReadOnly !== true;
}

/* 状態を読み出し→mutator適用→view_configへ書き戻して保存する。
   mutator(state) が false を返した場合は保存しない。
   label があれば localStorage スナップショット方式の取り消し履歴（ビュー設定と共通の仕組み）に載る。 */
function _elMutateState(dbPath, label, detail, mutator, options = {}) {
  if (!dbPath || typeof getDbViewConfig !== 'function' || typeof saveDbViewConfig !== 'function') return null;
  const cfg = getDbViewConfig(dbPath) || {};
  const state = _elNormalizeState(cfg);
  if (typeof mutator === 'function' && mutator(state, cfg) === false) return null;
  const normalized = _elNormalizeState({
    entityLayouts: state.layouts,
    entityTabOrder: state.tabOrder,
    currentEntityTab: state.currentTab,
  });
  cfg.entityLayouts = normalized.layouts;
  cfg.entityTabOrder = normalized.tabOrder;
  cfg.currentEntityTab = normalized.currentTab;
  saveDbViewConfig(dbPath, cfg, {
    historyLabel: label || '',
    historyDetail: detail || '',
    skipHistory: options.skipHistory === true || !label,
    ctx: options.ctx,
    // 取り消し/やり直しで localStorage が巻き戻った後、開いているエントリ画面を再描画する
    onRestore: typeof options.onRestore === 'function' ? options.onRestore : undefined,
    // エントリ画面（フルページタブ）の履歴スコープは共通('')のため、シートの
    // 'db:'スコープに積むとエントリ画面から Ctrl+Z が届かない。共通スコープへ積めば
    // エントリ画面からもシートタブ（スコープ→共通のフォールバック）からも取り消せる
    historyScope: '',
  });
  return normalized;
}

// タブ操作用: 再描画クロージャを取り消し復元時にも安全に呼べる形へ包む
function _elRestoreOption(grid, rerender) {
  return {
    onRestore: () => {
      if (grid?.isConnected && typeof rerender === 'function') rerender();
    },
  };
}

/* --- セッション内状態（描画先コンテナ単位）---
   「エントリを開いた時は並び順の先頭タブ」を実現するため、選択タブは描画先コンテナ+エントリ単位の
   セッション状態として持ち、同一エントリの再描画時のみ維持する。編集モードも同様にセッション限定。 */
const _elSessionByGrid = new WeakMap();

function _elSession(grid, entityPath) {
  let session = _elSessionByGrid.get(grid);
  if (!session || session.entityPath !== entityPath) {
    session = { entityPath, tab: null, editMode: false };
    _elSessionByGrid.set(grid, session);
  }
  return session;
}

function _elResolveActiveTab(grid, entityPath, state, options) {
  const session = _elSession(grid, entityPath);
  if (session.tab === EL_COLUMNS_TAB_ID) return EL_COLUMNS_TAB_ID;
  if (session.tab && state.layouts.some(l => l.id === session.tab)) return session.tab;
  // 幅の狭い面（右サイドバー・モバイルドロワー）では、レイアウトが並び順先頭でも
  // 初期表示は列一覧にする（1000px基準のキャンバスが極小に縮んで読めなくなるため）。
  // タブを押せばレイアウトへ切り替えられる。
  const narrowSurface = options?.surface === 'right-sidebar'
    || grid?.classList?.contains?.('cloud-mobile-side-drawer-props-grid');
  if (narrowSurface) return EL_COLUMNS_TAB_ID;
  return state.tabOrder[0] || EL_COLUMNS_TAB_ID;
}

function _elSelectTab(grid, entityPath, dbPath, tabId, rerender, options = {}) {
  const session = _elSession(grid, entityPath);
  session.tab = tabId;
  // currentEntityTab は「直近に選択していたタブ」の記憶。初期表示の決定には使わない（並び順先頭が優先）
  // 閲覧専用面の表示切替はセッション内だけに留め、共有 view_config を書き換えない。
  if (_elCanMutateGrid(grid, options)) {
    _elMutateState(dbPath, '', '', (state) => { state.currentTab = tabId; }, { skipHistory: true });
  }
  if (typeof rerender === 'function') rerender();
}

/* --- タブ操作 --- */

function _elAddLayout(grid, entityPath, dbPath, rerender) {
  if (!_elCanMutateGrid(grid)) return;
  let newId = '';
  _elMutateState(dbPath, 'トピックレイアウト: 追加', '', (state) => {
    const layout = _elNormalizeLayout({ name: _elMakeNewLayoutName(state.layouts) });
    newId = layout.id;
    state.layouts.push(layout);
    state.tabOrder.push(layout.id);
    state.currentTab = layout.id;
  }, _elRestoreOption(grid, rerender));
  if (!newId) return;
  const session = _elSession(grid, entityPath);
  session.tab = newId;
  session.editMode = true; // 空のレイアウトは編集モードで開き、すぐセルを置ける状態にする
  if (typeof showStatus === 'function') showStatus('トピックレイアウトを追加しました');
  if (typeof rerender === 'function') rerender();
}

async function _elRenameLayout(grid, entityPath, dbPath, layoutId, rerender) {
  if (!_elCanMutateGrid(grid)) return;
  const state = _elGetState(dbPath);
  const layout = state?.layouts.find(l => l.id === layoutId);
  if (!layout) return;
  const input = typeof cfPrompt === 'function'
    ? await cfPrompt('トピックレイアウト名', layout.name, { okLabel: '変更' })
    : null;
  if (input == null) return;
  if (!_elCanMutateGrid(grid)) return;
  const name = String(input).trim();
  if (!name) {
    if (typeof showStatus === 'function') showStatus('名前を入力してください', true);
    return;
  }
  _elMutateState(dbPath, 'トピックレイアウト: 名前変更', layout.name + ' → ' + name, (st) => {
    const target = st.layouts.find(l => l.id === layoutId);
    if (!target) return false;
    target.name = name;
  }, _elRestoreOption(grid, rerender));
  if (typeof rerender === 'function') rerender();
}

async function _elDuplicateLayout(grid, entityPath, dbPath, layoutId, rerender) {
  if (!_elCanMutateGrid(grid)) return;
  const state = _elGetState(dbPath);
  const source = state?.layouts.find(l => l.id === layoutId);
  if (!source) return;
  const defaultName = _elMakeDuplicateName(source.name, state.layouts);
  const input = typeof cfPrompt === 'function'
    ? await cfPrompt('複製後のレイアウト名', defaultName, { okLabel: '複製' })
    : defaultName;
  if (input == null) return;
  if (!_elCanMutateGrid(grid)) return;
  const name = String(input).trim();
  if (!name) {
    if (typeof showStatus === 'function') showStatus('名前を入力してください', true);
    return;
  }
  let newId = '';
  _elMutateState(dbPath, 'トピックレイアウト: 複製', source.name + ' → ' + name, (st) => {
    const src = st.layouts.find(l => l.id === layoutId);
    if (!src) return false;
    const clone = _elNormalizeLayout(JSON.parse(JSON.stringify(src)));
    clone.id = _elGenId('el');
    clone.name = name;
    clone.cells = clone.cells.map(cell => ({ ...cell, id: _elGenId('cell') }));
    newId = clone.id;
    const insertAt = st.tabOrder.indexOf(layoutId);
    st.layouts.push(clone);
    st.tabOrder.splice(insertAt >= 0 ? insertAt + 1 : st.tabOrder.length, 0, clone.id);
    st.currentTab = clone.id;
  }, _elRestoreOption(grid, rerender));
  if (!newId) return;
  _elSession(grid, entityPath).tab = newId;
  if (typeof showStatus === 'function') showStatus('トピックレイアウトを複製しました: ' + name);
  if (typeof rerender === 'function') rerender();
}

async function _elDeleteLayout(grid, entityPath, dbPath, layoutId, rerender) {
  if (!_elCanMutateGrid(grid)) return;
  const state = _elGetState(dbPath);
  const layout = state?.layouts.find(l => l.id === layoutId);
  if (!layout) return;
  // 削除は確認ダイアログ必須（プロジェクト共通ルール）。取り消し履歴からも復元できる。
  const confirmed = typeof cfConfirm === 'function'
    ? await cfConfirm('トピックレイアウト「' + layout.name + '」を削除しますか？')
    : false;
  if (!confirmed) return;
  if (!_elCanMutateGrid(grid)) return;
  _elMutateState(dbPath, 'トピックレイアウト: 削除', layout.name, (st) => {
    const idx = st.layouts.findIndex(l => l.id === layoutId);
    if (idx < 0) return false;
    st.layouts.splice(idx, 1);
    st.tabOrder = st.tabOrder.filter(id => id !== layoutId);
    if (st.currentTab === layoutId) st.currentTab = st.tabOrder[0] || EL_COLUMNS_TAB_ID;
  }, _elRestoreOption(grid, rerender));
  const session = _elSession(grid, entityPath);
  if (session.tab === layoutId) session.tab = null; // 次描画で並び順先頭タブへ戻す
  if (typeof showStatus === 'function') showStatus('トピックレイアウトを削除しました: ' + layout.name);
  if (typeof rerender === 'function') rerender();
}

function _elReorderTabs(grid, dbPath, fromId, toId, placeAfter, rerender) {
  if (!_elCanMutateGrid(grid)) return;
  if (!fromId || !toId || fromId === toId) return;
  _elMutateState(dbPath, 'トピックレイアウト: タブ並べ替え', '', (st) => {
    const order = st.tabOrder.filter(id => id !== fromId);
    const targetIdx = order.indexOf(toId);
    if (targetIdx < 0) return false;
    order.splice(placeAfter ? targetIdx + 1 : targetIdx, 0, fromId);
    st.tabOrder = order;
  }, _elRestoreOption(grid, rerender));
  if (typeof rerender === 'function') rerender();
}

/* --- タブメニュー（名前変更 / 複製 / 削除）--- */

function _elCloseTabMenus() {
  document.querySelectorAll('.el-tab-menu').forEach(el => {
    if (typeof el._cleanup === 'function') el._cleanup();
    el.remove();
  });
}

function _elShowTabMenu(anchorBtn, grid, entityPath, dbPath, layoutId, rerender) {
  const items = [
    { key: 'rename', label: '名前を変更', icon: 'pencil', run: () => _elRenameLayout(grid, entityPath, dbPath, layoutId, rerender) },
    { key: 'duplicate', label: '複製', icon: 'copy', run: () => _elDuplicateLayout(grid, entityPath, dbPath, layoutId, rerender) },
    { key: 'delete', label: '削除', icon: 'trash', danger: true, run: () => _elDeleteLayout(grid, entityPath, dbPath, layoutId, rerender) },
  ];
  _elShowActionMenu(anchorBtn, items, 'entity-layout-tab-menu');
}

/* 書き出しメニュー（HTML / PNG）。実体は既存の書き出しエンジンへ委譲する。
   複数の面（メイン/サブパネル/右サイドバー）で同時にレイアウトを開いていても、
   押されたタブ行の面が書き出されるよう、対象の grid を書き出しエンジンへ引き渡す。 */
function _elShowExportMenu(anchorBtn, grid, context) {
  window.__meldexEntityLayoutExportRoot = grid || anchorBtn?.closest?.('.entity-props-grid-container') || null;
  const items = [
    {
      key: 'export-html', label: 'HTMLとして保存', icon: 'fileText',
      run: () => {
        if (typeof MeldexExportHtml !== 'undefined' && MeldexExportHtml?.exportCurrentView) {
          MeldexExportHtml.exportCurrentView('entity-layout');
        } else if (typeof showStatus === 'function') showStatus('HTML書き出しを利用できません', true);
      },
    },
    {
      key: 'export-png', label: '画像（PNG）として保存', icon: 'image',
      run: () => {
        if (typeof MeldexExportImage !== 'undefined' && MeldexExportImage?.exportCurrentView) {
          MeldexExportImage.exportCurrentView('entity-layout');
        } else if (typeof showStatus === 'function') showStatus('画像書き出しを利用できません', true);
      },
    },
  ];
  if (globalThis.MeldexDbTopicLayoutStyle && context?.layoutId) {
    items.push(
      { key: 'export-template', label: 'トピックレイアウトを保存', icon: 'save', run: () => _elDownloadTopicLayoutTemplate(context) },
      { key: 'import-template', label: 'トピックレイアウトを読み込む', icon: 'upload', run: () => _elChooseTopicLayoutTemplate(context) },
      { key: 'save-shared-template', label: '共有テンプレートへ保存', icon: 'library', run: () => _elSaveTopicLayoutToSharedLibrary(context) },
      { key: 'load-shared-template', label: '共有テンプレートから読み込む', icon: 'folderOpen', run: () => _elLoadTopicLayoutFromSharedLibrary(context) },
    );
  }
  _elShowActionMenu(anchorBtn, items, 'entity-layout-export-menu');
}

function _elTopicLayoutColumns(dbPath, pivotData) {
  const data = pivotData || state?.pivotData || {};
  const types = typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath) || {} : {};
  return (Array.isArray(data.properties) ? data.properties : []).map(name => ({
    id: String(types[name]?.id || types[name]?.columnId || ''), name: String(name),
  }));
}

function _elDownloadTopicLayoutTemplate(context) {
  const layout = _elGetState(context.dbPath)?.layouts.find(item => item.id === context.layoutId);
  if (!layout) return;
  const api = globalThis.MeldexDbTopicLayoutStyle;
  const template = api.exportTemplate(layout, _elTopicLayoutColumns(context.dbPath, context.pivotData));
  const blob = new Blob([JSON.stringify(template, null, 2)], { type: 'application/json' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = layout.name.replace(/[\\/:*?"<>|]+/g, '_') + api.TEMPLATE_EXTENSION;
  link.click();
  setTimeout(() => URL.revokeObjectURL(link.href), 0);
}

function _elChooseTopicLayoutTemplate(context) {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = '.json,.meldex-topic-layout.json,application/json';
  input.addEventListener('change', async () => {
    const file = input.files?.[0];
    if (!file) return;
    try {
      const template = JSON.parse(await file.text());
      let imported = null;
      _elMutateState(context.dbPath, 'トピックレイアウト: 読み込み', file.name, state => {
        imported = globalThis.MeldexDbTopicLayoutStyle.importTemplate(template, state.layouts, _elTopicLayoutColumns(context.dbPath, context.pivotData));
        if (!imported.added) return false;
        state.layouts.push(imported.layout);
        state.tabOrder.push(imported.layout.id);
        state.currentTab = imported.layout.id;
      }, _elRestoreOption(context.grid, context.rerender));
      if (!imported?.added) {
        if (typeof showStatus === 'function') showStatus('同名のトピックレイアウトが既にあります', true);
        return;
      }
      const unresolved = imported.mappings.filter(item => item.match === 'unresolved').length;
      if (typeof showStatus === 'function') showStatus(unresolved ? `読み込みました（未割り当ての列: ${unresolved}件）` : 'トピックレイアウトを読み込みました');
      context.rerender?.();
    } catch (error) {
      if (typeof showStatus === 'function') showStatus('トピックレイアウトを読み込めません: ' + (error?.message || error), true);
    }
  });
  input.click();
}

async function _elSaveTopicLayoutToSharedLibrary(context) {
  const api = globalThis.MeldexDbTopicLayoutStyle;
  const layout = _elGetState(context.dbPath)?.layouts.find(item => item.id === context.layoutId);
  if (!api || !layout) return;
  try {
    const template = api.exportTemplate(layout, _elTopicLayoutColumns(context.dbPath, context.pivotData));
    const result = api.saveSharedTemplateToLibrary
      ? await api.saveSharedTemplateToLibrary(template)
      : api.saveSharedTemplate(template);
    if (typeof showStatus === 'function') {
      const message = !result.saved
        ? '同名の共有テンプレートが既にあります'
        : result.shared === false
          ? '共有先を利用できないため、この端末に保存しました'
          : '共有テンプレートへ保存しました';
      showStatus(message, !result.saved || result.shared === false);
    }
  } catch (error) {
    if (typeof showStatus === 'function') showStatus('共有テンプレートへ保存できません: ' + (error?.message || error), true);
  }
}

async function _elLoadTopicLayoutFromSharedLibrary(context) {
  const api = globalThis.MeldexDbTopicLayoutStyle;
  const library = api?.loadSharedTemplateLibrary
    ? await api.loadSharedTemplateLibrary()
    : { source: 'device-cache', templates: api?.loadSharedTemplates?.() || [] };
  const templates = library.templates || [];
  if (!templates.length) {
    if (typeof showStatus === 'function') showStatus('保存済みの共有テンプレートはありません', true);
    return;
  }
  const choices = templates.map(item => String(item.layout?.name || '')).filter(Boolean);
  const selected = typeof cfPrompt === 'function'
    ? await cfPrompt('読み込む共有テンプレート名', choices[0], { okLabel: '読み込む', description: choices.join(' / ') })
    : choices[0];
  if (selected == null) return;
  const template = templates.find(item => String(item.layout?.name || '') === String(selected).trim());
  if (!template) {
    if (typeof showStatus === 'function') showStatus('指定した共有テンプレートが見つかりません', true);
    return;
  }
  let imported = null;
  _elMutateState(context.dbPath, 'トピックレイアウト: 共有テンプレート読込', template.layout.name, layoutState => {
    imported = api.importTemplate(template, layoutState.layouts, _elTopicLayoutColumns(context.dbPath, context.pivotData));
    if (!imported.added) return false;
    layoutState.layouts.push(imported.layout);
    layoutState.tabOrder.push(imported.layout.id);
    layoutState.currentTab = imported.layout.id;
  }, _elRestoreOption(context.grid, context.rerender));
  if (!imported?.added) {
    if (typeof showStatus === 'function') showStatus('同名のトピックレイアウトが既にあります', true);
    return;
  }
  _elSession(context.grid, context.entityPath).tab = imported.layout.id;
  context.rerender?.();
}

function _elShowActionMenu(anchorBtn, items, menuE2eId) {
  _elCloseTabMenus();
  const menu = document.createElement('div');
  menu.className = 'gb-context-menu el-tab-menu';
  menu.dataset.e2eId = menuE2eId;
  menu.setAttribute('role', 'menu');
  items.forEach(item => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'el-tab-menu-item' + (item.danger ? ' danger' : '');
    btn.dataset.e2eId = 'entity-layout-tab-menu-' + item.key;
    btn.setAttribute('role', 'menuitem');
    btn.innerHTML = (typeof lucide === 'function' ? lucide(item.icon, 13) : '') + '<span>' + item.label + '</span>';
    btn.addEventListener('click', () => {
      close();
      item.run();
    });
    menu.appendChild(btn);
  });
  document.body.appendChild(menu);
  const cleanupFns = [];
  menu._cleanup = () => { cleanupFns.splice(0).forEach(off => off()); };
  const close = () => {
    menu._cleanup();
    menu.remove();
    if (typeof focusMeldexDropdownTrigger === 'function') focusMeldexDropdownTrigger(anchorBtn);
    else { try { anchorBtn?.focus?.(); } catch { /* ignore */ } }
  };
  if (typeof positionPopup === 'function') {
    positionPopup(menu, anchorBtn.getBoundingClientRect(), { gap: 4 });
  } else if (typeof clampPopupToViewport === 'function') {
    const rect = anchorBtn.getBoundingClientRect();
    menu.style.left = rect.left + 'px';
    menu.style.top = (rect.bottom + 4) + 'px';
    clampPopupToViewport(menu);
  }
  setTimeout(() => {
    const onPointerDown = (ev) => {
      if (!menu.contains(ev.target) && ev.target !== anchorBtn && !anchorBtn.contains(ev.target)) close();
    };
    const onKeyDown = (ev) => {
      if (ev.key === 'Escape') { ev.preventDefault(); ev.stopPropagation(); close(); }
    };
    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKeyDown, true);
    cleanupFns.push(() => document.removeEventListener('pointerdown', onPointerDown));
    cleanupFns.push(() => document.removeEventListener('keydown', onKeyDown, true));
  }, 0);
  requestAnimationFrame(() => { try { menu.querySelector('button')?.focus({ preventScroll: true }); } catch { /* ignore */ } });
}

/* --- タブ行の構築 ---
   renderEntityPropsGridInto から呼ばれる。dbPath が無い（シート配下でない）エントリでは null を返し、
   従来どおり列一覧のみの表示になる。戻り値: { el, activeTab }。 */
function _elBuildTabBar(grid, data, entityPath, options, dbPath, rerender) {
  if (!dbPath) return null;
  const state = _elGetState(dbPath);
  if (!state) return null;
  // 再描画のたびに、前回の描画に紐付いたポップアップ・メニュー・ResizeObserverを確実に始末する
  // （取り消し復元や候補値追加の自動再描画で grid が作り直されても、古い layout への
  // 書き込みポップアップや監視が残らないようにする）
  _elCloseTabMenus();
  if (typeof _elCloseEditPopups === 'function') _elCloseEditPopups();
  if (grid._elViewportObserver) {
    try { grid._elViewportObserver.disconnect(); } catch { /* ignore */ }
    grid._elViewportObserver = null;
  }
  const activeTab = _elResolveActiveTab(grid, entityPath, state, options);
  const session = _elSession(grid, entityPath);
  const readOnly = options?.readOnly === true;

  const bar = document.createElement('div');
  bar.className = 'el-tabbar';
  bar.dataset.e2eId = 'entity-layout-tabbar';

  const tabs = document.createElement('div');
  tabs.className = 'el-tabs';
  tabs.setAttribute('role', 'tablist');
  tabs.setAttribute('aria-label', 'トピックの表示切替');
  bar.appendChild(tabs);

  const tabDefs = state.tabOrder.map(id => (
    id === EL_COLUMNS_TAB_ID
      ? { id, name: '列一覧' }
      : { id, name: state.layouts.find(l => l.id === id)?.name || 'レイアウト' }
  ));
  tabDefs.forEach(def => {
    const tab = document.createElement('button');
    tab.type = 'button';
    tab.className = 'el-tab' + (def.id === activeTab ? ' active' : '');
    tab.dataset.e2eId = 'entity-layout-tab';
    tab.dataset.tabId = def.id;
    tab.setAttribute('role', 'tab');
    tab.setAttribute('aria-selected', def.id === activeTab ? 'true' : 'false');
    tab.tabIndex = def.id === activeTab ? 0 : -1;
    tab.draggable = !readOnly;
    const label = document.createElement('span');
    label.className = 'el-tab-label';
    label.textContent = def.name;
    tab.appendChild(label);
    tab.addEventListener('click', () => {
      _elCloseTabMenus();
      if (def.id !== activeTab) _elSelectTab(grid, entityPath, dbPath, def.id, rerender, { readOnly });
    });
    tab.addEventListener('keydown', (e) => {
      if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) return;
      const allTabs = Array.from(tabs.querySelectorAll('.el-tab'));
      const currentIdx = allTabs.indexOf(tab);
      if (currentIdx < 0 || allTabs.length < 2) return;
      e.preventDefault();
      let nextIdx = currentIdx;
      if (e.key === 'Home') nextIdx = 0;
      else if (e.key === 'End') nextIdx = allTabs.length - 1;
      else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') nextIdx = (currentIdx - 1 + allTabs.length) % allTabs.length;
      else nextIdx = (currentIdx + 1) % allTabs.length;
      const nextTab = allTabs[nextIdx];
      session.pendingTabFocus = nextTab?.dataset?.tabId || '';
      nextTab?.click?.();
    });
    if (def.id !== EL_COLUMNS_TAB_ID && !readOnly) {
      tab.addEventListener('dblclick', (e) => {
        e.preventDefault();
        _elRenameLayout(grid, entityPath, dbPath, def.id, rerender);
      });
    }
    // D&D並べ替え（「列一覧」タブも並べ替え対象。先頭に置いたタブが初期表示になる）
    tab.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/x-el-tab', def.id);
      e.dataTransfer.effectAllowed = 'move';
      tab.classList.add('dragging');
    });
    tab.addEventListener('dragend', () => {
      tab.classList.remove('dragging');
      tabs.querySelectorAll('.el-tab').forEach(t => t.classList.remove('el-drop-before', 'el-drop-after'));
    });
    tab.addEventListener('dragover', (e) => {
      if (!e.dataTransfer.types.includes('text/x-el-tab')) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      const rect = tab.getBoundingClientRect();
      const after = e.clientX > rect.left + rect.width / 2;
      tab.classList.toggle('el-drop-before', !after);
      tab.classList.toggle('el-drop-after', after);
    });
    tab.addEventListener('dragleave', () => {
      tab.classList.remove('el-drop-before', 'el-drop-after');
    });
    tab.addEventListener('drop', (e) => {
      if (!e.dataTransfer.types.includes('text/x-el-tab')) return;
      e.preventDefault();
      const fromId = e.dataTransfer.getData('text/x-el-tab');
      const rect = tab.getBoundingClientRect();
      const after = e.clientX > rect.left + rect.width / 2;
      _elReorderTabs(grid, dbPath, fromId, def.id, after, rerender);
    });
    tabs.appendChild(tab);
  });

  if (!readOnly) {
    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'el-tab-add gb-btn gb-btn-sm gb-btn-icon';
    addBtn.dataset.e2eId = 'entity-layout-add';
    addBtn.title = 'トピックレイアウトを追加';
    addBtn.setAttribute('aria-label', 'トピックレイアウトを追加');
    addBtn.innerHTML = typeof lucide === 'function' ? lucide('plus', 14) : '+';
    addBtn.addEventListener('click', () => {
      _elCloseTabMenus();
      _elAddLayout(grid, entityPath, dbPath, rerender);
    });
    // tablist（.el-tabs）の外に置く: スマホ幅の共通タブドロップダウン化が
    // [role=tablist] を丸ごと隠すため、中に置くと追加手段が消える（2026-08-20レビュー指摘）
    bar.appendChild(addBtn);
  }

  // アクティブなレイアウトタブ用の操作（書き出し + 編集モード切替 + タブメニュー）
  if (activeTab !== EL_COLUMNS_TAB_ID) {
    const actions = document.createElement('div');
    actions.className = 'el-tab-actions';

    const exportBtn = document.createElement('button');
    exportBtn.type = 'button';
    exportBtn.className = 'el-export-btn gb-btn gb-btn-sm gb-btn-icon';
    exportBtn.dataset.e2eId = 'entity-layout-export-btn';
    exportBtn.title = 'レイアウトを書き出し';
    exportBtn.setAttribute('aria-label', 'レイアウトを書き出し');
    exportBtn.setAttribute('aria-haspopup', 'menu');
    exportBtn.innerHTML = typeof lucide === 'function' ? lucide('download', 14) : '↓';
    exportBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      _elShowExportMenu(exportBtn, grid, { grid, entityPath, dbPath, layoutId: activeTab, rerender, pivotData: data });
    });
    actions.appendChild(exportBtn);

    const editBtn = document.createElement('button');
    if (readOnly) session.editMode = false;
    editBtn.type = 'button';
    editBtn.className = 'el-edit-toggle gb-btn gb-btn-sm gb-btn-icon' + (session.editMode ? ' active' : '');
    editBtn.dataset.e2eId = 'entity-layout-edit-toggle';
    const editLabel = session.editMode ? 'レイアウト編集を終了' : 'レイアウトを編集';
    editBtn.title = editLabel;
    editBtn.setAttribute('aria-label', editLabel);
    editBtn.setAttribute('aria-pressed', session.editMode ? 'true' : 'false');
    editBtn.innerHTML = typeof lucide === 'function' ? lucide(session.editMode ? 'check' : 'pencil', 14) : '編';
    editBtn.addEventListener('click', () => {
      _elCloseTabMenus();
      session.editMode = !session.editMode;
      if (typeof rerender === 'function') rerender();
    });
    if (!readOnly) actions.appendChild(editBtn);

    const menuBtn = document.createElement('button');
    menuBtn.type = 'button';
    menuBtn.className = 'el-tab-menu-btn gb-btn gb-btn-sm gb-btn-icon';
    menuBtn.dataset.e2eId = 'entity-layout-tab-menu-btn';
    menuBtn.title = 'レイアウトの操作';
    menuBtn.setAttribute('aria-label', 'レイアウトの操作');
    menuBtn.setAttribute('aria-haspopup', 'menu');
    menuBtn.innerHTML = typeof lucide === 'function' ? lucide('moreHorizontal', 14) : '…';
    menuBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      _elShowTabMenu(menuBtn, grid, entityPath, dbPath, activeTab, rerender);
    });
    if (!readOnly) actions.appendChild(menuBtn);
    bar.appendChild(actions);
  }

  if (session.pendingTabFocus) {
    const focusTabId = session.pendingTabFocus;
    session.pendingTabFocus = '';
    requestAnimationFrame(() => {
      const focusTab = Array.from(tabs.querySelectorAll('.el-tab'))
        .find(candidate => candidate.dataset.tabId === focusTabId);
      try { focusTab?.focus({ preventScroll: true }); } catch { /* ignore */ }
    });
  }

  return { el: bar, activeTab };
}

/* --- 公開API --- */
if (typeof window !== 'undefined') {
  window.GBEntityLayout = {
    COLUMNS_TAB_ID: EL_COLUMNS_TAB_ID,
    buildTabBar: _elBuildTabBar,
    renderLayoutBody: (grid, data, entityPath, options, dbPath, layoutId, rerender) => {
      if (typeof _elRenderLayoutBody === 'function') {
        _elRenderLayoutBody(grid, data, entityPath, options, dbPath, layoutId, rerender);
      }
    },
    getState: _elGetState,
    mutateState: _elMutateState,
    session: _elSession,
  };
}

;

/* === gb-db-entity-layout-canvas.js === */
;
/* gb-db-entity-layout-canvas.js: エントリレイアウトの自由配置キャンバス描画。
   - デザイン基準サイズ（layout.canvasSize）でセルを絶対配置し、表示コンテナ幅へ
     transform: scale() で等比フィットさせる（要望8。ResizeObserverで追従）。
   - 編集モード: セルのドラッグ移動・右下ハンドルでのリサイズ・選択・削除、
     「列を配置」メニュー、キャンバスサイズ設定。
   - ボードのキャンバスエンジン（gb-canvas-engine*）はグローバル状態と強く結合しているため
     直接流用せず、ドラッグ/リサイズの考え方だけを踏襲した軽量実装とする（計画書2.4節）。
   セル内容の描画は gb-db-entity-layout-cells.js の _elBuildCellContent が担当する。 */
'use strict';

const EL_DRAG_SNAP = 5;

function _elZoomFactor() {
  return typeof _getZoom === 'function' ? Math.max(0.1, Number(_getZoom()) || 1) : 1;
}

function _elSnap(value) {
  return Math.round(value / EL_DRAG_SNAP) * EL_DRAG_SNAP;
}

/* レイアウト本体を grid コンテナへ描画する（renderEntityPropsGridInto から委譲される）。 */
function _elRenderLayoutBody(grid, data, entityPath, options, dbPath, layoutId, rerender) {
  const state = _elGetState(dbPath);
  const layout = state?.layouts.find(l => l.id === layoutId);
  const host = document.createElement('div');
  host.className = 'el-host';
  host.dataset.e2eId = 'entity-layout-host';
  grid.appendChild(host);
  if (!layout) {
    const missing = document.createElement('div');
    missing.className = 'el-empty-hint';
    missing.textContent = 'このトピックレイアウトは見つかりませんでした';
    host.appendChild(missing);
    return;
  }
  const session = _elSession(grid, entityPath);
  const editMode = !!session.editMode;
  const safeRerender = () => {
    if (grid.isConnected && typeof rerender === 'function') rerender();
  };
  const ctx = {
    grid, data, entityPath, options, dbPath, layout, editMode,
    readOnly: options?.readOnly === true,
    rerender: safeRerender,
    propTypes: options?.propTypes
      || (typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath) : null)
      || {},
    persist(label, detail, mutator) {
      if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(grid, options)) return null;
      return _elMutateState(dbPath, label, detail, (st, cfg) => {
        const target = st.layouts.find(l => l.id === layoutId);
        if (!target) return false;
        return mutator(target, st, cfg);
      }, { onRestore: safeRerender });
    },
  };

  if (editMode) host.appendChild(_elBuildEditToolbar(ctx));

  const viewport = document.createElement('div');
  viewport.className = 'el-viewport' + (editMode ? ' el-editing' : '');
  viewport.dataset.e2eId = 'entity-layout-viewport';
  host.appendChild(viewport);

  const canvas = document.createElement('div');
  canvas.className = 'el-canvas';
  canvas.style.width = layout.canvasSize.w + 'px';
  canvas.style.height = layout.canvasSize.h + 'px';
  viewport.appendChild(canvas);
  if (typeof _elApplyLayoutTheme === 'function') _elApplyLayoutTheme(canvas, layout);

  layout.cells.forEach(cell => {
    canvas.appendChild(_elBuildCellElement(cell, ctx, canvas));
  });

  if (layout.cells.length === 0) {
    const hint = document.createElement('div');
    hint.className = 'el-empty-hint';
    hint.dataset.e2eId = 'entity-layout-empty-hint';
    hint.textContent = editMode
      ? '「列を配置」からセルを追加してください'
      : 'セルがありません（鉛筆ボタンからレイアウトを編集できます）';
    canvas.appendChild(hint);
  }

  // 等比フィット: コンテナ幅に合わせて縮小/拡大し、高さは縦横比に追従させる
  const applyScale = () => {
    if (!viewport.isConnected) return;
    const width = viewport.clientWidth;
    if (!width) return;
    const scale = width / layout.canvasSize.w;
    canvas.style.transform = 'scale(' + scale + ')';
    canvas.dataset.elScale = String(scale);
    canvas.style.setProperty('--el-inverse-scale', String(scale > 0 ? 1 / scale : 1));
    viewport.style.height = Math.ceil(layout.canvasSize.h * scale) + 'px';
  };
  applyScale();
  if (typeof ResizeObserver === 'function') {
    const observer = new ResizeObserver(() => applyScale());
    observer.observe(viewport);
    // 解放はタブ行の再構築時（_elBuildTabBar）に grid 経由で行う
    grid._elViewportObserver = observer;
  }

  // 長文の自動フィット（要望10）: レイアウト確定後にセルごとへ適用する
  requestAnimationFrame(() => {
    if (!canvas.isConnected || typeof _elAutoFitCellText !== 'function') return;
    layout.cells.forEach(cell => {
      const cellEl = canvas.querySelector('.el-cell[data-cell-id="' + cell.id + '"]');
      if (cellEl) _elAutoFitCellText(cellEl, cell);
    });
  });

  // 編集モード: 何もない場所のクリックで選択解除
  if (editMode) {
    canvas.addEventListener('pointerdown', (e) => {
      if (e.target === canvas) _elClearCellSelection(canvas);
    });
  }
}

function _elClearCellSelection(canvas) {
  canvas.querySelectorAll('.el-cell.el-selected').forEach(el => el.classList.remove('el-selected'));
}

function _elSelectCellElement(canvas, cellEl) {
  _elClearCellSelection(canvas);
  cellEl.classList.add('el-selected');
}

/* セル1件のDOMを構築する（枠 + 内容 + 編集モードの操作チローム） */
function _elBuildCellElement(cell, ctx, canvas) {
  const el = document.createElement('div');
  el.className = 'el-cell el-cell-' + cell.type;
  el.dataset.cellId = cell.id;
  el.dataset.e2eId = 'entity-layout-cell';
  el.style.left = cell.x + 'px';
  el.style.top = cell.y + 'px';
  el.style.width = cell.w + 'px';
  el.style.height = cell.h + 'px';

  const content = typeof _elBuildCellContent === 'function'
    ? _elBuildCellContent(cell, ctx, canvas)
    : null;
  if (content) el.appendChild(content);
  if (typeof _elApplyCellStyle === 'function') _elApplyCellStyle(el, cell, ctx);

  if (!ctx.editMode) return el;

  // --- 以下は編集モード専用のチローム ---
  el.classList.add('el-editable');
  el.tabIndex = 0;
  el.setAttribute('role', 'group');
  const typeLabel = cell.type === 'field' ? (cell.prop || '列')
    : cell.type === 'label' ? (cell.text || '見出し')
      : cell.type === 'image' ? '画像'
        : cell.type === 'divider' ? '罫線'
          : cell.type === 'chart' ? 'チャート' : cell.type;
  el.setAttribute('aria-label', typeLabel + 'のレイアウトセル');
  // フォーカスだけでも選択状態にして、ホバーを使えないキーボード操作から
  // 設定・削除ボタンへ Tab で到達できるようにする。
  el.addEventListener('focus', () => _elSelectCellElement(canvas, el));

  // 見出しセルはダブルクリックでテキストを直接編集する
  if (cell.type === 'label') {
    el.addEventListener('dblclick', (e) => {
      e.preventDefault();
      e.stopPropagation();
      _elBeginLabelEdit(el, cell, ctx);
    });
  }

  const settingsBtn = document.createElement('button');
  settingsBtn.type = 'button';
  settingsBtn.className = 'el-cell-settings';
  settingsBtn.dataset.e2eId = 'entity-layout-cell-settings';
  const settingsLabel = cell.type === 'image' ? '画像の設定'
    : cell.type === 'divider' ? '罫線の色' : 'セルの書式';
  settingsBtn.title = settingsLabel;
  settingsBtn.setAttribute('aria-label', settingsLabel);
  settingsBtn.setAttribute('aria-haspopup', 'dialog');
  settingsBtn.innerHTML = typeof lucide === 'function' ? lucide('settings2', 12) : '⚙';
  settingsBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    _elSelectCellElement(canvas, el);
    if (typeof _elOpenCellSettings === 'function') _elOpenCellSettings(settingsBtn, cell, ctx, el);
  });
  settingsBtn.addEventListener('pointerdown', (e) => e.stopPropagation());
  el.appendChild(settingsBtn);

  const removeBtn = document.createElement('button');
  removeBtn.type = 'button';
  removeBtn.className = 'el-cell-remove';
  removeBtn.dataset.e2eId = 'entity-layout-cell-remove';
  removeBtn.title = 'セルを削除';
  removeBtn.setAttribute('aria-label', 'セルを削除');
  removeBtn.innerHTML = typeof lucide === 'function' ? lucide('x', 12) : '×';
  // セル削除は配置の編集操作（データ自体は消えない）なので確認は出さず、取り消し履歴で戻せるようにする
  removeBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    ctx.persist('トピックレイアウト: セル削除', '', (layout) => {
      const idx = layout.cells.findIndex(c => c.id === cell.id);
      if (idx < 0) return false;
      layout.cells.splice(idx, 1);
    });
    ctx.rerender();
  });
  el.appendChild(removeBtn);

  const resizeHandle = document.createElement('div');
  resizeHandle.className = 'el-cell-resize';
  resizeHandle.dataset.e2eId = 'entity-layout-cell-resize';
  resizeHandle.setAttribute('aria-hidden', 'true');
  el.appendChild(resizeHandle);

  el.addEventListener('keydown', (e) => {
    if (e.target !== el) return;
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      _elSelectCellElement(canvas, el);
      settingsBtn.focus({ preventScroll: true });
    }
  });

  el.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    if (e.target === removeBtn || removeBtn.contains(e.target)) return;
    if (el.classList.contains('el-label-editing')) return; // 見出しテキスト編集中はドラッグしない
    const resizing = e.target === resizeHandle;
    e.preventDefault();
    e.stopPropagation();
    _elSelectCellElement(canvas, el);
    _elBeginCellPointerOp(e, el, cell, ctx, canvas, resizing ? 'resize' : 'move');
  });

  return el;
}

/* 見出しセルのインラインテキスト編集。blur/Enterで確定、Escapeで取消。 */
function _elBeginLabelEdit(el, cell, ctx) {
  if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
  if (el.classList.contains('el-label-editing')) return;
  el.classList.add('el-label-editing');
  const body = el.querySelector('.el-label-text');
  if (!body) { el.classList.remove('el-label-editing'); return; }
  const original = String(cell.text || '');
  const input = document.createElement('textarea');
  input.className = 'el-label-input';
  input.dataset.e2eId = 'entity-layout-label-input';
  input.value = original;
  input.setAttribute('aria-label', '見出しのテキスト');
  body.replaceChildren(input);
  let finished = false;
  const finish = (commit) => {
    if (finished) return;
    // 動的に閲覧専用へ切り替わった間は入力DOMを残す。解除後に確定/取消できるため、
    // blurを契機に下書きを捨てたり、古い権限で保存したりしない。
    if (commit && typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
    finished = true;
    const next = String(input.value || '').trim();
    el.classList.remove('el-label-editing');
    if (commit && next !== original) {
      _elPersistCellPatch(ctx, cell, 'トピックレイアウト: 見出し編集', (target) => { target.text = next; });
    }
    ctx.rerender();
  };
  input.addEventListener('blur', () => finish(true));
  input.addEventListener('keydown', (e) => {
    if (e.isComposing || e.keyCode === 229) return;
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); finish(true); } else if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      finish(false);
    }
  });
  requestAnimationFrame(() => { try { input.focus({ preventScroll: true }); input.select(); } catch { /* ignore */ } });
}

/* ドラッグ移動 / リサイズの共通処理。ポインタ差分を zoom とフィットスケールで
   デザイン基準pxへ換算し、スナップとキャンバス境界クランプを掛けて反映する。
   確定（pointerup）時に1回だけ永続化し、取り消し履歴にも1操作として載せる。 */
function _elBeginCellPointerOp(e, el, cell, ctx, canvas, mode) {
  const scale = Number(canvas.dataset.elScale) || 1;
  const zoom = _elZoomFactor();
  const factor = scale * zoom;
  const start = { x: cell.x, y: cell.y, w: cell.w, h: cell.h, clientX: e.clientX, clientY: e.clientY };
  const canvasW = ctx.layout.canvasSize.w;
  const canvasH = ctx.layout.canvasSize.h;
  let latest = { x: cell.x, y: cell.y, w: cell.w, h: cell.h };
  let moved = false;
  el.classList.add('el-dragging');
  try { el.setPointerCapture(e.pointerId); } catch { /* ignore */ }

  const onMove = (ev) => {
    const dx = (ev.clientX - start.clientX) / factor;
    const dy = (ev.clientY - start.clientY) / factor;
    if (!moved && Math.abs(dx) < 2 && Math.abs(dy) < 2) return;
    moved = true;
    if (mode === 'move') {
      const x = Math.max(0, Math.min(canvasW - start.w, _elSnap(start.x + dx)));
      const y = Math.max(0, Math.min(canvasH - start.h, _elSnap(start.y + dy)));
      latest = { ...latest, x, y };
      el.style.left = x + 'px';
      el.style.top = y + 'px';
    } else {
      const w = Math.max(EL_CELL_MIN_SIZE, Math.min(canvasW - start.x, _elSnap(start.w + dx)));
      const h = Math.max(EL_CELL_MIN_SIZE, Math.min(canvasH - start.y, _elSnap(start.h + dy)));
      latest = { ...latest, w, h };
      el.style.width = w + 'px';
      el.style.height = h + 'px';
    }
  };
  const onUp = (ev) => {
    el.removeEventListener('pointermove', onMove);
    el.removeEventListener('pointerup', onUp);
    el.removeEventListener('pointercancel', onUp);
    el.classList.remove('el-dragging');
    try { el.releasePointerCapture(ev.pointerId); } catch { /* ignore */ }
    if (!moved) return;
    const changed = latest.x !== start.x || latest.y !== start.y || latest.w !== start.w || latest.h !== start.h;
    if (!changed) return;
    const persisted = ctx.persist(
      mode === 'move' ? 'トピックレイアウト: セル移動' : 'トピックレイアウト: セルサイズ変更',
      '',
      (layout) => {
        const target = layout.cells.find(c => c.id === cell.id);
        if (!target) return false;
        target.x = latest.x;
        target.y = latest.y;
        target.w = latest.w;
        target.h = latest.h;
      }
    );
    if (!persisted) {
      el.style.left = start.x + 'px';
      el.style.top = start.y + 'px';
      el.style.width = start.w + 'px';
      el.style.height = start.h + 'px';
      return;
    }
    cell.x = latest.x; cell.y = latest.y; cell.w = latest.w; cell.h = latest.h;
    // サイズ変更は文字の自動フィットとチャートの描画サイズに影響するため再描画で追従させる
    if (mode === 'resize') ctx.rerender();
  };
  el.addEventListener('pointermove', onMove);
  el.addEventListener('pointerup', onUp);
  el.addEventListener('pointercancel', onUp);
}

/* --- 編集ツールバー --- */

function _elCloseEditPopups() {
  document.querySelectorAll('.el-edit-popup').forEach(el => {
    if (typeof el._cleanup === 'function') el._cleanup();
    el.remove();
  });
}

function _elAttachPopupCommon(popup, anchorBtn) {
  document.body.appendChild(popup);
  const cleanupFns = [];
  popup._cleanup = () => { cleanupFns.splice(0).forEach(off => off()); };
  const close = () => {
    popup._cleanup();
    popup.remove();
    if (typeof focusMeldexDropdownTrigger === 'function') focusMeldexDropdownTrigger(anchorBtn);
    else { try { anchorBtn?.focus?.(); } catch { /* ignore */ } }
  };
  if (typeof positionPopup === 'function') {
    positionPopup(popup, anchorBtn.getBoundingClientRect(), { gap: 4 });
  } else if (typeof clampPopupToViewport === 'function') {
    const rect = anchorBtn.getBoundingClientRect();
    popup.style.left = rect.left + 'px';
    popup.style.top = (rect.bottom + 4) + 'px';
    clampPopupToViewport(popup);
  }
  setTimeout(() => {
    const onPointerDown = (ev) => {
      if (!popup.contains(ev.target) && ev.target !== anchorBtn && !anchorBtn.contains(ev.target)) close();
    };
    const onKeyDown = (ev) => {
      if (ev.key === 'Escape') { ev.preventDefault(); ev.stopPropagation(); close(); }
    };
    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKeyDown, true);
    cleanupFns.push(() => document.removeEventListener('pointerdown', onPointerDown));
    cleanupFns.push(() => document.removeEventListener('keydown', onKeyDown, true));
  }, 0);
  return close;
}

// 新しいセルの初期位置: 既存セルと重なりにくいよう段々に流し込む
function _elNextCellPosition(layout, w, h) {
  const step = 30;
  const maxX = Math.max(0, layout.canvasSize.w - w);
  const maxY = Math.max(0, layout.canvasSize.h - h);
  const n = layout.cells.length;
  return {
    x: Math.min(maxX, 20 + (n % 8) * step),
    y: Math.min(maxY, 20 + n * step % Math.max(step, maxY)),
  };
}

function _elAddCell(ctx, partialCell, statusLabel) {
  const w = partialCell.w || 220;
  const h = partialCell.h || 90;
  ctx.persist('トピックレイアウト: セル追加', statusLabel || '', (layout) => {
    const pos = _elNextCellPosition(layout, w, h);
    layout.cells.push(_elNormalizeCell({ ...partialCell, ...pos, w, h }, layout.canvasSize.w, layout.canvasSize.h));
  });
  ctx.rerender();
}

// 「列を配置」メニュー: シートの列一覧から選んで field セルを追加する（同じ列の複数配置も可）
function _elShowFieldPickerMenu(anchorBtn, ctx) {
  _elCloseEditPopups();
  const menu = document.createElement('div');
  menu.className = 'gb-context-menu el-edit-popup el-field-picker';
  menu.dataset.e2eId = 'entity-layout-field-picker';
  menu.setAttribute('role', 'menu');
  const props = Object.keys(ctx.data?.properties || {});
  if (props.length === 0) {
    const empty = document.createElement('div');
    empty.className = 'el-field-picker-empty';
    empty.textContent = '配置できる列がありません';
    menu.appendChild(empty);
  }
  props.forEach(propName => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'el-tab-menu-item';
    btn.dataset.e2eId = 'entity-layout-field-pick';
    btn.dataset.propName = propName;
    btn.setAttribute('role', 'menuitem');
    const iconHtml = typeof _elPropIconHtml === 'function' ? _elPropIconHtml(propName, ctx.propTypes, 13) : '';
    btn.innerHTML = iconHtml + '<span></span>';
    btn.querySelector('span').textContent = propName;
    btn.addEventListener('click', () => {
      close();
      _elAddCell(ctx, { type: 'field', prop: propName }, propName);
    });
    menu.appendChild(btn);
  });
  const close = _elAttachPopupCommon(menu, anchorBtn);
}

// キャンバスサイズ設定ポップアップ（デザイン基準サイズを変更する）
function _elShowCanvasSizePopup(anchorBtn, ctx) {
  _elCloseEditPopups();
  const popup = document.createElement('div');
  popup.className = 'gb-context-menu el-edit-popup el-canvas-size-popup';
  popup.dataset.e2eId = 'entity-layout-canvas-size-popup';

  const title = document.createElement('div');
  title.className = 'el-popup-title';
  title.textContent = 'キャンバスサイズ';
  popup.appendChild(title);

  const makeRow = (labelText, value, e2eId) => {
    const row = document.createElement('label');
    row.className = 'el-popup-row';
    const span = document.createElement('span');
    span.textContent = labelText;
    row.appendChild(span);
    const input = document.createElement('input');
    input.type = 'number';
    input.min = String(EL_CANVAS_MIN);
    input.max = String(EL_CANVAS_MAX);
    input.step = '10';
    input.value = String(value);
    input.dataset.e2eId = e2eId;
    row.appendChild(input);
    popup.appendChild(row);
    return input;
  };
  const wInput = makeRow('幅 (px)', ctx.layout.canvasSize.w, 'entity-layout-canvas-w');
  const hInput = makeRow('高さ (px)', ctx.layout.canvasSize.h, 'entity-layout-canvas-h');

  const applyBtn = document.createElement('button');
  applyBtn.type = 'button';
  applyBtn.className = 'gb-btn gb-btn-sm gb-btn-primary primary';
  applyBtn.dataset.e2eId = 'entity-layout-canvas-size-apply';
  applyBtn.textContent = '適用';
  applyBtn.addEventListener('click', () => {
    const w = _elClampNum(wInput.value, EL_CANVAS_MIN, EL_CANVAS_MAX, ctx.layout.canvasSize.w);
    const h = _elClampNum(hInput.value, EL_CANVAS_MIN, EL_CANVAS_MAX, ctx.layout.canvasSize.h);
    close();
    ctx.persist('トピックレイアウト: キャンバスサイズ', w + 'x' + h, (layout) => {
      layout.canvasSize = { w, h };
    });
    ctx.rerender();
  });
  popup.appendChild(applyBtn);

  const close = _elAttachPopupCommon(popup, anchorBtn);
  popup.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); applyBtn.click(); }
  });
  requestAnimationFrame(() => { try { wInput.focus({ preventScroll: true }); wInput.select(); } catch { /* ignore */ } });
}

/* 編集ツールバー本体。セル種別の追加ボタン群は _elEditToolbarExtraItems（cells側、
   Phase C/D で見出し・画像・チャート等を追加）から拡張できる形にしておく。 */
function _elBuildEditToolbar(ctx) {
  const bar = document.createElement('div');
  bar.className = 'el-edit-toolbar';
  bar.dataset.e2eId = 'entity-layout-edit-toolbar';

  const fieldBtn = document.createElement('button');
  fieldBtn.type = 'button';
  fieldBtn.className = 'gb-btn gb-btn-sm';
  fieldBtn.dataset.e2eId = 'entity-layout-add-field';
  fieldBtn.setAttribute('aria-haspopup', 'menu');
  fieldBtn.innerHTML = (typeof lucide === 'function' ? lucide('plus', 13) : '+') + '<span>列を配置</span>';
  fieldBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    _elShowFieldPickerMenu(fieldBtn, ctx);
  });
  bar.appendChild(fieldBtn);

  if (typeof _elEditToolbarExtraItems === 'function') {
    _elEditToolbarExtraItems(ctx).forEach(btn => bar.appendChild(btn));
  }

  const sizeBtn = document.createElement('button');
  sizeBtn.type = 'button';
  sizeBtn.className = 'gb-btn gb-btn-sm';
  sizeBtn.dataset.e2eId = 'entity-layout-canvas-size-btn';
  sizeBtn.setAttribute('aria-haspopup', 'dialog');
  sizeBtn.innerHTML = (typeof lucide === 'function' ? lucide('slidersHorizontal', 13) : '⚙') + '<span>キャンバスサイズ</span>';
  sizeBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    _elShowCanvasSizePopup(sizeBtn, ctx);
  });
  bar.appendChild(sizeBtn);

  return bar;
}

;

/* === gb-db-entity-layout-cells.js === */
;
/* gb-db-entity-layout-cells.js: エントリレイアウトのセル内容の描画とセル設定UI。
   - field: 列キャプション（ユーザー設定アイコン or 列タイプアイコン + 列名）+ 値（列一覧と同じ
     既存の値エディタ createTypedValueElement / createValueElement を共通ヘルパー経由で再利用）。
   - label: 自由テキスト（編集モードでダブルクリックすると直接編集）。
   - divider: 罫線（縦横はセルの縦横比で自動判定。色は設定で変更可）。
   - image: アップロード画像（/media/upload、シートの添付フォルダへ保存）または
     アイコンセット（GBIconAssets の Lucide/Noto絵文字）。HTML書き出しの embedImages() と
     噛み合うよう、常に <img> タグとして描画する（アイコンはSVGデータURIへラスタライズ）。
   - セルの文字書式は既存の汎用書式ポップアップ（openFormatPopup）をそのまま流用する。
   - 配色テーマ: レイアウト単位の --el-* ローカルCSS変数。未設定時は Meldex 現在のテーマへ
     追従する（var() フォールバック）。ユーザーが色を選んだトークンだけ固定される。
   - 編集モード中はセル内容を不活性にし、ドラッグ操作と値編集が競合しないようにする（CSS側）。
   chart セルは Phase D で追加する。 */
'use strict';

/* 列のキャプション用アイコンHTML。ユーザーが列に設定したアイコン（property_types[prop].icon、
   GBIconAssets の spec 文字列）があればそれを優先し、無ければ列タイプのアイコンを出す。 */
function _elPropIconHtml(propName, propTypes, size) {
  const px = size || 14;
  const userIcon = propTypes?.[propName]?.icon;
  if (userIcon && typeof GBIconAssets !== 'undefined' && GBIconAssets?.render) {
    return '<span class="el-prop-icon" aria-hidden="true">' + GBIconAssets.render(userIcon, px) + '</span>';
  }
  if (typeof lucide === 'function' && typeof getPropertyTypeIcon === 'function') {
    return '<span class="el-prop-icon" aria-hidden="true">'
      + lucide(getPropertyTypeIcon(propTypes?.[propName]?.type), px) + '</span>';
  }
  return '';
}

/* field セル: 列キャプション + 値エディタ。値の描画は列一覧（renderEntityPropsGridInto）と
   同じ共通ヘルパー renderEntityPropValuesInto を使い、見た目と編集挙動を揃える。 */
function _elBuildFieldCellContent(cell, ctx) {
  const wrap = document.createElement('div');
  wrap.className = 'el-cell-content';
  const propName = String(cell.prop || '');

  const caption = document.createElement('div');
  caption.className = 'el-cell-caption';
  caption.innerHTML = _elPropIconHtml(propName, ctx.propTypes, 13);
  const captionText = document.createElement('span');
  captionText.className = 'el-cell-caption-text';
  captionText.textContent = propName || '(列未設定)';
  caption.appendChild(captionText);
  wrap.appendChild(caption);

  const body = document.createElement('div');
  body.className = 'el-cell-body cell-values';
  if (propName && ctx.data?.properties && Object.prototype.hasOwnProperty.call(ctx.data.properties, propName)) {
    if (typeof renderEntityPropValuesInto === 'function') {
      renderEntityPropValuesInto(body, propName, ctx.data, ctx.entityPath, ctx.propTypes, { readOnly: ctx.readOnly === true });
    } else {
      const values = Array.isArray(ctx.data.properties[propName]) ? ctx.data.properties[propName] : [];
      values.forEach(val => {
        const div = document.createElement('div');
        div.className = 'cell-value';
        div.textContent = val?.value != null ? String(val.value) : '';
        body.appendChild(div);
      });
    }
  } else if (propName) {
    const missing = document.createElement('div');
    missing.className = 'el-cell-missing';
    missing.textContent = 'この列はシートにありません: ' + propName;
    body.appendChild(missing);
  }
  wrap.appendChild(body);
  globalThis.MeldexDbTopicLayoutStyle?.applyCaptionMode?.(caption, captionText, body, cell, propName || '未設定の列');
  return wrap;
}

/* label セル: 固定テキスト（見出し・キャプション）。編集はダブルクリック（canvas側で配線）。 */
function _elBuildLabelCellContent(cell, ctx) {
  const wrap = document.createElement('div');
  wrap.className = 'el-cell-content el-cell-label-content';
  const body = document.createElement('div');
  body.className = 'el-cell-body el-label-text';
  body.textContent = String(cell.text || '');
  if (!cell.text && ctx.editMode) {
    body.classList.add('el-label-empty');
    body.textContent = 'ダブルクリックで編集';
  }
  wrap.appendChild(body);
  return wrap;
}

/* divider セル: 罫線。横長なら水平線、縦長なら垂直線として描く。 */
function _elBuildDividerCellContent(cell, ctx) {
  const wrap = document.createElement('div');
  wrap.className = 'el-cell-content el-cell-divider-content';
  const line = document.createElement('div');
  line.className = 'el-divider-line ' + (cell.w >= cell.h ? 'el-divider-h' : 'el-divider-v');
  if (cell.lineColor) line.style.background = cell.lineColor;
  wrap.appendChild(line);
  return wrap;
}

/* アイコンspecを <img src> 用のSVGデータURIへラスタライズする。
   色は描画時点のキャンバス実効色（テーマ）を焼き込む（書き出しでもそのまま使えるようにするため）。 */
function _elIconDataUri(spec, color) {
  if (typeof GBIconAssets === 'undefined' || !GBIconAssets?.parseSpec) return '';
  const parsed = GBIconAssets.parseSpec(spec);
  const esc = MeldexEscape.xml;
  if (parsed?.type === 'noto') {
    const emoji = parsed.emoji || (GBIconAssets.codeToEmoji ? GBIconAssets.codeToEmoji(parsed.code) : '') || '?';
    const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">'
      + '<text x="64" y="78" text-anchor="middle" dominant-baseline="middle" '
      + 'font-family="Meldex Noto Emoji, Noto Color Emoji, Segoe UI Emoji, Apple Color Emoji, sans-serif" '
      + 'font-size="100">' + esc(emoji) + '</text></svg>';
    return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  }
  if (parsed?.type === 'lucide' && typeof lucide === 'function') {
    let markup = lucide(parsed.name, 96) || '';
    if (!markup) return '';
    if (!markup.includes('xmlns=')) markup = markup.replace('<svg ', '<svg xmlns="http://www.w3.org/2000/svg" ');
    // 単体SVG化すると currentColor が黒へ落ちるため、実効色を明示的に焼き込む
    markup = markup.replace(/currentColor/g, esc(color || '#9aa0a6'));
    return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(markup);
  }
  return '';
}

/* image セル: source 'upload'（シート添付フォルダの画像）/ 'icon'（アイコンセット）。
   いずれも <img> として描画する（HTML書き出しの embedImages() 対象にするため。背景画像方式は使わない）。 */
function _elBuildImageCellContent(cell, ctx, canvasEl) {
  const wrap = document.createElement('div');
  wrap.className = 'el-cell-content el-cell-image-content';
  const image = _elIsObj(cell.image) ? cell.image : {};
  let src = '';
  if (image.source === 'icon' && image.spec) {
    const effectiveFg = image.color
      || (canvasEl ? getComputedStyle(canvasEl).color : '') || '#9aa0a6';
    src = _elIconDataUri(image.spec, effectiveFg);
  } else if (typeof image.dataUri === 'string' && image.dataUri.startsWith('data:')) {
    // テンプレートへ同梱された画像（gb-db-template-entity-layouts.js）。パスが無くてもそのまま表示できる
    src = image.dataUri;
  } else if (image.path || image.url) {
    src = (typeof fileRawUrl === 'function' && image.path) ? fileRawUrl(image.path) : (image.url || '');
  }
  if (!src) {
    const empty = document.createElement('div');
    empty.className = 'el-cell-placeholder';
    empty.textContent = ctx.editMode ? '画像未設定（歯車ボタンで選択）' : '';
    wrap.appendChild(empty);
    return wrap;
  }
  const img = document.createElement('img');
  img.className = 'el-cell-image';
  if (window.MeldexRuntimeAdapter?.isBrowserDataMode?.() && window.MeldexPwaFileUrl?.applyToElement) {
    window.MeldexPwaFileUrl.applyToElement(img, src);
  } else {
    img.src = src;
  }
  img.alt = String(image.alt || cell.type || '');
  img.draggable = false;
  img.style.objectFit = image.fit === 'cover' ? 'cover' : 'contain';
  wrap.appendChild(img);
  window.MeldexImageLoading?.track?.(img, { host: wrap, label: '画像を読み込んでいます', allowDetached: true });
  return wrap;
}

/* セル内容のディスパッチ。未実装タイプはタイプ名のプレースホルダを出す
   （通常は到達しない。テンプレート適用等で先行データが来ても壊れないための保険）。 */
function _elBuildCellContent(cell, ctx, canvasEl) {
  if (cell.type === 'field') return _elBuildFieldCellContent(cell, ctx);
  if (cell.type === 'label') return _elBuildLabelCellContent(cell, ctx);
  if (cell.type === 'divider') return _elBuildDividerCellContent(cell, ctx);
  if (cell.type === 'image') return _elBuildImageCellContent(cell, ctx, canvasEl);
  if (cell.type === 'chart' && typeof _elBuildChartCellContent === 'function') {
    return _elBuildChartCellContent(cell, ctx, canvasEl);
  }
  const placeholder = document.createElement('div');
  placeholder.className = 'el-cell-content el-cell-placeholder';
  placeholder.textContent = cell.type;
  return placeholder;
}

/* --- セルの見た目（書式）の適用 --- */

/* cell.style（openFormatPopup と同じプロパティ名で保存）をセル要素へ反映する。 */
function _elApplyCellStyle(el, cell, ctx) {
  const s = _elIsObj(cell.style) ? cell.style : {};
  if (s.bgColor) el.style.background = s.bgColor;
  if (s.textColor) el.style.color = s.textColor;
  if (s.fontSize) el.style.fontSize = _elClampNum(s.fontSize, 6, 200, 13) + 'px';
  if (s.fontFamily) el.style.fontFamily = s.fontFamily;
  if (s.fontWeight) el.style.fontWeight = s.fontWeight;
  if (s.fontStyle) el.style.fontStyle = s.fontStyle;
  const deco = [];
  if (s.underline) deco.push('underline');
  if (s.strike) deco.push('line-through');
  if (deco.length) el.style.textDecoration = deco.join(' ');
  if (Number(s.textStrokeWidth) > 0) {
    el.style.webkitTextStroke = Number(s.textStrokeWidth) + 'px ' + (s.textStrokeColor || 'currentColor');
  }
  if (s.textAlign) el.style.textAlign = s.textAlign;
  globalThis.MeldexDbTopicLayoutStyle?.applyCellStyle?.(el, cell, { editMode: ctx?.editMode === true });
}

/* 長文の自動フィット（要望10）: セルに収まらない場合、切り詰めずにフォントサイズを
   段階的に縮小して収める。下限(8px)でも収まらない場合はスクロール（CSS側のoverflow）が最終手段。 */
function _elAutoFitCellText(el, cell) {
  if (cell.style?.autoFit === false) return;
  if (cell.type !== 'field' && cell.type !== 'label') return;
  const body = el.querySelector('.el-cell-body');
  if (!body || !body.isConnected || body.clientHeight === 0) return;
  body.style.fontSize = '';
  const base = parseFloat(getComputedStyle(body).fontSize) || 13;
  let size = base;
  let guard = 60;
  while (guard-- > 0 && size > 8
    && (body.scrollHeight > body.clientHeight + 1 || body.scrollWidth > body.clientWidth + 1)) {
    size -= 1;
    body.style.fontSize = size + 'px';
  }
}

/* --- セル設定（書式ポップアップ / 画像ソース / 罫線色） --- */

const EL_FORMAT_FIELDS = [
  'textColor', 'fontSize', 'fontFamily', 'bold', 'italic', 'underline',
  'textStrokeColor', 'textStrokeWidth', 'bgColor', 'textAlign',
];

function _elOpenCellFormatPopup(anchorEl, cell, ctx, cellEl) {
  if (typeof openFormatPopup !== 'function') {
    if (typeof showStatus === 'function') showStatus('書式設定を利用できません', true);
    return;
  }
  const values = { ..._elIsObj(cell.style) ? cell.style : {} };
  // カラーパレットのドラッグは中間色ごとに onChange が飛ぶため、永続化（+取り消し履歴）は
  // 300msのデバウンスで1回にまとめる。画面への反映だけライブで行う。
  let persistTimer = null;
  const flushPersist = () => {
    persistTimer = null;
    if (!ctx.grid?.isConnected) return;
    const drawer = ctx.grid.closest?.('#cloud-mobile-side-drawer');
    if (drawer && !drawer.classList.contains('open')) return;
    const blocked = (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options))
      || (typeof _cellUiRuntimeReadOnly === 'function' && _cellUiRuntimeReadOnly(ctx.grid));
    if (blocked) {
      // 表示中に容量停止へ変わった場合も、ライブ反映済みの書式下書きを捨てない。
      // 同じ画面で解除された時だけ保存を再開し、画面を閉じた場合は破棄する。
      persistTimer = setTimeout(flushPersist, 120);
      return;
    }
    const snapshot = { ..._elIsObj(cell.style) ? cell.style : {} };
    _elPersistCellPatch(ctx, cell, 'トピックレイアウト: セル書式', (target) => {
      target.style = snapshot;
    });
  };
  openFormatPopup(anchorEl, {
    fields: EL_FORMAT_FIELDS,
    values,
    onReset: () => {
      if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
      if (persistTimer) { clearTimeout(persistTimer); persistTimer = null; }
      _elPersistCellPatch(ctx, cell, 'トピックレイアウト: セル書式リセット', (target) => { target.style = {}; });
      ctx.rerender();
    },
    onChange: (prop, value) => {
      if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
      if (value === '' || value == null || value === false) delete cell.style?.[prop];
      else { if (!_elIsObj(cell.style)) cell.style = {}; cell.style[prop] = value; }
      // ポップアップを開いたまま即時反映（再描画はしない）
      if (cellEl?.isConnected) {
        cellEl.removeAttribute('style');
        cellEl.style.left = cell.x + 'px';
        cellEl.style.top = cell.y + 'px';
        cellEl.style.width = cell.w + 'px';
        cellEl.style.height = cell.h + 'px';
        _elApplyCellStyle(cellEl, cell, ctx);
        _elAutoFitCellText(cellEl, cell);
      }
      if (persistTimer) clearTimeout(persistTimer);
      persistTimer = setTimeout(flushPersist, 300);
    },
  });
}

/* セル1件へのパッチを永続化する共通ヘルパー */
function _elPersistCellPatch(ctx, cell, label, mutator) {
  if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return null;
  return ctx.persist(label, cell.type, (layout) => {
    const target = layout.cells.find(c => c.id === cell.id);
    if (!target) return false;
    mutator(target);
  });
}

/* 画像ソースを切り替えるときは、以前テンプレートへ同梱された dataUri を持ち越さない。
   dataUri は表示時に path/url より優先されるため、残すとアップロード後も古い画像が出続ける。 */
function _elMergeImagePatch(currentImage, imagePatch) {
  const next = { ..._elIsObj(currentImage) ? currentImage : {}, ..._elIsObj(imagePatch) ? imagePatch : {} };
  if (Object.prototype.hasOwnProperty.call(imagePatch || {}, 'source')
    && !Object.prototype.hasOwnProperty.call(imagePatch || {}, 'dataUri')) {
    delete next.dataUri;
  }
  return next;
}

/* 画像セルのソース設定ポップアップ（アップロード / アイコン / 表示方法） */
function _elShowImageCellPopup(anchorBtn, ctx, existingCell) {
  _elCloseEditPopups();
  const popup = document.createElement('div');
  popup.className = 'gb-context-menu el-edit-popup el-image-popup';
  popup.dataset.e2eId = 'entity-layout-image-popup';

  const title = document.createElement('div');
  title.className = 'el-popup-title';
  title.textContent = existingCell ? '画像セルの設定' : '画像セルを追加';
  popup.appendChild(title);

  const applyImage = (imagePatch) => {
    if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
    if (existingCell) {
      _elPersistCellPatch(ctx, existingCell, 'トピックレイアウト: 画像変更', (target) => {
        target.image = _elMergeImagePatch(target.image, imagePatch);
      });
    } else {
      _elAddCell(ctx, { type: 'image', w: 180, h: 180, image: { fit: 'contain', ...imagePatch } }, '画像');
      return;
    }
    ctx.rerender();
  };

  const uploadBtn = document.createElement('button');
  uploadBtn.type = 'button';
  uploadBtn.className = 'el-tab-menu-item';
  uploadBtn.dataset.e2eId = 'entity-layout-image-upload';
  uploadBtn.innerHTML = (typeof lucide === 'function' ? lucide('image', 13) : '') + '<span>画像をアップロード</span>';
  uploadBtn.addEventListener('click', () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/png,image/jpeg,image/gif,image/webp';
    input.addEventListener('change', async () => {
      const file = input.files && input.files[0];
      if (!file) return;
      if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
      close();
      try {
        const meta = await _elUploadLayoutImage(file, ctx);
        if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
        applyImage({ source: 'upload', path: meta.path || '', url: meta.url || '', spec: '', alt: meta.filename || file.name });
        if (typeof showStatus === 'function') showStatus('画像を設定しました');
      } catch (error) {
        if (typeof showStatus === 'function') showStatus('画像のアップロードに失敗しました: ' + (error?.message || error), true);
      }
    });
    input.click();
  });
  popup.appendChild(uploadBtn);

  const iconBtn = document.createElement('button');
  iconBtn.type = 'button';
  iconBtn.className = 'el-tab-menu-item';
  iconBtn.dataset.e2eId = 'entity-layout-image-icon';
  iconBtn.innerHTML = (typeof lucide === 'function' ? lucide('palette', 13) : '') + '<span>アイコンから選ぶ</span>';
  iconBtn.addEventListener('click', () => {
    if (typeof GBIconAssets === 'undefined' || !GBIconAssets?.openPicker) return;
    close();
    GBIconAssets.openPicker({
      anchorEl: anchorBtn,
      title: '画像セルのアイコン',
      current: existingCell?.image?.spec || '',
      onSelect: (spec) => {
        applyImage({ source: 'icon', spec: spec || '', path: '', url: '' });
      },
    });
  });
  popup.appendChild(iconBtn);

  if (existingCell) {
    const fitBtn = document.createElement('button');
    fitBtn.type = 'button';
    fitBtn.className = 'el-tab-menu-item';
    fitBtn.dataset.e2eId = 'entity-layout-image-fit';
    const cover = existingCell.image?.fit === 'cover';
    fitBtn.innerHTML = (typeof lucide === 'function' ? lucide('maximize', 13) : '') + '<span>'
      + (cover ? '全体を表示（余白あり）に切替' : 'セル全体に敷き詰めに切替') + '</span>';
    fitBtn.addEventListener('click', () => {
      close();
      applyImage({ fit: cover ? 'contain' : 'cover' });
    });
    popup.appendChild(fitBtn);
  }

  const close = _elAttachPopupCommon(popup, anchorBtn);
}

/* レイアウト用画像のアップロード。画像型列と同じ /media/upload（sheet_pathスコープ）を使い、
   シートの添付フォルダへ保存する。 */
async function _elUploadLayoutImage(file, ctx) {
  const fd = new FormData();
  fd.append('file', file);
  if (ctx.dbPath) fd.append('sheet_path', ctx.dbPath);
  const headers = typeof _attachmentUploadHeaders === 'function' ? _attachmentUploadHeaders() : undefined;
  const base = typeof API_BASE !== 'undefined' ? API_BASE : '/api';
  const res = await fetch(base + '/media/upload', { method: 'POST', body: fd, headers });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const meta = await res.json();
  if (!meta || meta.ok === false) throw new Error(meta?.error || 'アップロードに失敗しました');
  return meta;
}

/* 罫線セルの色設定 */
function _elShowDividerColorPopup(anchorBtn, ctx, cell) {
  if (typeof openColorPalette !== 'function') return;
  openColorPalette(anchorBtn, cell.lineColor || '', (color) => {
    if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
    _elPersistCellPatch(ctx, cell, 'トピックレイアウト: 罫線の色', (target) => {
      if (color) target.lineColor = color;
      else delete target.lineColor;
    });
    ctx.rerender();
  });
}

/* セルの設定入口（歯車ボタン）。タイプ別に適切な設定UIを開く。 */
function _elOpenCellSettings(anchorBtn, cell, ctx, cellEl) {
  if (cell.type === 'image') {
    _elShowImageCellPopup(anchorBtn, ctx, cell);
    return;
  }
  if (cell.type === 'divider') {
    _elShowDividerColorPopup(anchorBtn, ctx, cell);
    return;
  }
  if (cell.type === 'chart') {
    if (typeof _elShowChartCellPopup === 'function') _elShowChartCellPopup(anchorBtn, ctx, cell);
    return;
  }
  if (globalThis.MeldexDbTopicLayoutStyle?.createStyleControls) {
    _elShowTopicLayoutCellStylePopup(anchorBtn, cell, ctx, cellEl);
  } else {
    _elOpenCellFormatPopup(anchorBtn, cell, ctx, cellEl);
  }
}

function _elShowTopicLayoutCellStylePopup(anchorBtn, cell, ctx, cellEl) {
  _elCloseEditPopups();
  const popup = document.createElement('div');
  popup.className = 'gb-context-menu el-edit-popup topic-layout-cell-style-popup';
  popup.dataset.e2eId = 'topic-layout-cell-style-popup';
  const title = document.createElement('div');
  title.className = 'el-popup-title';
  title.textContent = 'セルの枠・背景・キャプション';
  popup.appendChild(title);
  let latest = globalThis.MeldexDbTopicLayoutStyle.normalizeCellStyleContract(cell);
  popup.appendChild(globalThis.MeldexDbTopicLayoutStyle.createStyleControls(document, latest, (next) => {
    latest = next;
    Object.assign(cell, next);
    if (cellEl?.isConnected) _elApplyCellStyle(cellEl, cell, ctx);
    const caption = cellEl?.querySelector?.('.el-cell-caption');
    const captionText = cellEl?.querySelector?.('.el-cell-caption-text');
    const body = cellEl?.querySelector?.('.el-cell-body');
    globalThis.MeldexDbTopicLayoutStyle.applyCaptionMode(caption, captionText, body, cell, cell.prop || '列');
  }));
  const textStyleBtn = document.createElement('button');
  textStyleBtn.type = 'button';
  textStyleBtn.className = 'gb-btn gb-btn-sm';
  textStyleBtn.textContent = '文字書式を開く';
  popup.appendChild(textStyleBtn);
  const close = _elAttachPopupCommon(popup, anchorBtn);
  const persist = () => {
    _elPersistCellPatch(ctx, cell, 'トピックレイアウト: セルの見た目', (target) => {
      target.frameStyle = latest.frameStyle;
      target.background = latest.background;
      target.captionMode = latest.captionMode;
    });
  };
  popup.addEventListener('change', persist);
  textStyleBtn.addEventListener('click', () => { close(); _elOpenCellFormatPopup(anchorBtn, cell, ctx, cellEl); });
}

/* --- レイアウト単位の配色テーマ（要望9） --- */

const EL_THEME_TOKENS = [
  { key: 'bg', label: '背景色', cssVar: '--el-bg', fallback: '--bg2' },
  { key: 'fg', label: '文字色', cssVar: '--el-fg', fallback: '--fg' },
  { key: 'fg2', label: '補助文字色', cssVar: '--el-fg2', fallback: '--fg2' },
  { key: 'accent', label: 'アクセント色', cssVar: '--el-accent', fallback: '--accent' },
  { key: 'border', label: '枠線色', cssVar: '--el-border', fallback: '--border' },
];

function _elShowThemePopup(anchorBtn, ctx) {
  _elCloseEditPopups();
  const popup = document.createElement('div');
  popup.className = 'gb-context-menu el-edit-popup el-theme-popup';
  popup.dataset.e2eId = 'entity-layout-theme-popup';

  const title = document.createElement('div');
  title.className = 'el-popup-title';
  title.textContent = 'レイアウトの配色';
  popup.appendChild(title);

  const rootStyle = getComputedStyle(document.documentElement);
  EL_THEME_TOKENS.forEach(token => {
    const row = document.createElement('div');
    row.className = 'el-popup-row';
    const label = document.createElement('span');
    label.textContent = token.label;
    row.appendChild(label);
    const swatch = document.createElement('button');
    swatch.type = 'button';
    swatch.className = 'el-theme-swatch';
    swatch.dataset.e2eId = 'entity-layout-theme-' + token.key;
    swatch.setAttribute('aria-label', token.label + 'を選択');
    const current = () => ctx.layout.theme?.[token.key]
      || rootStyle.getPropertyValue(token.fallback).trim() || '#888888';
    swatch.style.background = current();
    swatch.addEventListener('click', () => {
      if (typeof openColorPalette !== 'function') return;
      openColorPalette(swatch, current(), (color) => {
        if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
        if (!color) return;
        swatch.style.background = color;
        ctx.persist('トピックレイアウト: 配色', token.label, (layout) => {
          if (!_elIsObj(layout.theme)) layout.theme = {};
          layout.theme[token.key] = color;
        });
        // 開いたまま即時反映
        const canvas = ctx.grid?.querySelector?.('.el-canvas');
        if (canvas) canvas.style.setProperty(token.cssVar, color);
        if (!_elIsObj(ctx.layout.theme)) ctx.layout.theme = {};
        ctx.layout.theme[token.key] = color;
      });
    });
    row.appendChild(swatch);
    popup.appendChild(row);
  });

  const resetBtn = document.createElement('button');
  resetBtn.type = 'button';
  resetBtn.className = 'gb-btn gb-btn-sm';
  resetBtn.dataset.e2eId = 'entity-layout-theme-reset';
  resetBtn.textContent = 'アプリのテーマに合わせる';
  resetBtn.addEventListener('click', () => {
    if (typeof _elCanMutateGrid === 'function' && !_elCanMutateGrid(ctx.grid, ctx.options)) return;
    close();
    ctx.persist('トピックレイアウト: 配色リセット', '', (layout) => { layout.theme = null; });
    ctx.rerender();
  });
  popup.appendChild(resetBtn);

  const close = _elAttachPopupCommon(popup, anchorBtn);
}

/* レイアウト単位の配色テーマ（Phase C で編集UIを実装）。theme が保存されていれば
   キャンバスルートへスコープしたローカルCSS変数として適用する。 */
function _elApplyLayoutTheme(canvas, layout) {
  const theme = layout?.theme;
  if (!theme || typeof theme !== 'object') return;
  const map = { bg: '--el-bg', fg: '--el-fg', fg2: '--el-fg2', accent: '--el-accent', border: '--el-border' };
  Object.entries(map).forEach(([key, cssVar]) => {
    const value = theme[key];
    if (typeof value === 'string' && value) canvas.style.setProperty(cssVar, value);
  });
}

/* 編集ツールバーへ追加するセル種別ボタン（見出し/罫線/画像 + 配色。チャートは Phase D）。 */
function _elEditToolbarExtraItems(ctx) {
  const items = [];
  const make = (e2eId, icon, label, onClick, popup) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'gb-btn gb-btn-sm';
    btn.dataset.e2eId = e2eId;
    if (popup) btn.setAttribute('aria-haspopup', popup);
    btn.innerHTML = (typeof lucide === 'function' ? lucide(icon, 13) : '') + '<span>' + label + '</span>';
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      onClick(btn);
    });
    items.push(btn);
    return btn;
  };
  make('entity-layout-add-label', 'heading', '見出し', () => {
    _elAddCell(ctx, { type: 'label', text: '見出し', w: 200, h: 40 }, '見出し');
  });
  make('entity-layout-add-divider', 'minus', '罫線', () => {
    _elAddCell(ctx, { type: 'divider', w: 300, h: 24 }, '罫線');
  });
  make('entity-layout-add-image', 'image', '画像', (btn) => {
    _elShowImageCellPopup(btn, ctx, null);
  }, 'dialog');
  if (typeof _elShowChartCellPopup === 'function') {
    make('entity-layout-add-chart', 'barChart2', 'チャート', (btn) => {
      _elShowChartCellPopup(btn, ctx, null);
    }, 'dialog');
  }
  make('entity-layout-theme-btn', 'palette', '配色', (btn) => {
    _elShowThemePopup(btn, ctx);
  }, 'dialog');
  return items;
}

;

/* === gb-db-entity-layout-chart.js === */
;
/* gb-db-entity-layout-chart.js: エントリレイアウトの chart セル（棒/円/折れ線/レーダー）。
   - bar/pie/line: 既存チャートエンジン（gb-db-chart.js の renderBarChart/renderPieChart/
     renderLineChart。いずれもサイズ引数式でコンテナ非依存）をセルサイズで再利用する。
     データはチャートビューと同じ集計（prepareChartDataAsync）を、/pivot をその場で
     取得して通す（エントリ画面ではシート全体のデータを持っていないため）。
   - radar: このエントリの数値列（数式列も formulaEvalForEntity で評価可）を軸にした
     レーダーチャートを、既存のSVGプリミティブ（svgCreate/svgText等）で新規描画する。
   - 設定UIはセルの歯車ボタン（_elOpenCellSettings 経由）と編集ツールバーの「チャート」から開く。 */
'use strict';

const EL_CHART_TYPES = [
  { type: 'bar', label: '棒グラフ' },
  { type: 'pie', label: '円グラフ' },
  { type: 'line', label: '折れ線' },
  { type: 'radar', label: 'レーダー' },
];

const EL_CHART_AGGREGATIONS = [
  { value: 'count', label: '件数' },
  { value: 'sum', label: '合計' },
  { value: 'average', label: '平均' },
  { value: 'min', label: '最小' },
  { value: 'max', label: '最大' },
  { value: 'median', label: '中央値' },
];

/* /pivot の短期キャッシュ（同一レイアウト内の複数チャートセルで重複取得しないため） */
const _elPivotCache = new Map();
const EL_PIVOT_CACHE_MS = 10000;

function _elFetchPivotData(dbPath) {
  const key = String(dbPath || '');
  const cached = _elPivotCache.get(key);
  const now = Date.now();
  if (cached && now - cached.at < EL_PIVOT_CACHE_MS) return cached.promise;
  const promise = Promise.resolve(
    typeof apiFetch === 'function' ? apiFetch('/pivot?path=' + encodeURIComponent(key)) : null
  ).catch((error) => {
    _elPivotCache.delete(key);
    throw error;
  });
  _elPivotCache.set(key, { at: now, promise });
  return promise;
}

/* 最新の列タイプ定義。マウント時に固定された ctx.propTypes ではなく、その場の
   getPropertyTypes を優先する（設定パネルで直前に追加・変更した列も候補へ出すため）。 */
function _elChartPropTypes(ctx) {
  if (typeof getPropertyTypes === 'function') {
    const fresh = getPropertyTypes(ctx.dbPath);
    if (fresh && Object.keys(fresh).length) return { ...ctx.propTypes, ...fresh };
  }
  return ctx.propTypes || {};
}

/* このエントリの列値を数値として解決する（レーダーの軸値）。数式列は実行時評価。 */
function _elEntityNumericValue(propName, ctx) {
  const ptc = _elChartPropTypes(ctx)[propName];
  if (ptc?.type === 'formula' && typeof formulaEvalForEntity === 'function') {
    try {
      // formulaEvalForEntity は { value, error } を返す（他の全呼び出し元と同じ受け方にする）
      const result = formulaEvalForEntity(ptc.formula, ctx.data?.properties || {}, {
        propTypes: ctx.propTypes,
        dbPath: ctx.dbPath,
      });
      if (result?.error) return 0;
      const n = Number(result?.value);
      return Number.isFinite(n) ? n : 0;
    } catch {
      return 0;
    }
  }
  const rawValues = ctx.data?.properties?.[propName] || [];
  const values = typeof filterValues === 'function' ? filterValues(rawValues) : rawValues;
  const raw = values[0]?.value;
  const n = parseFloat(String(raw ?? '').replace(/[,\s]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

/* レーダーチャートの描画（axes: [{label, value, max}]）。
   既存チャートエンジンと同じSVGプリミティブを使い、目盛リング・スポーク・多角形を描く。 */
function _elRenderRadarChart(axes, w, h, options = {}) {
  const svg = svgCreate('svg', { width: w, height: h, viewBox: '0 0 ' + w + ' ' + h });
  const list = (axes || []).filter(a => a && a.label);
  const accent = typeof _chartThemeAccentColor === 'function' ? _chartThemeAccentColor() : '#7c9cff';
  const fg2 = options.mutedColor || 'rgba(128,128,128,0.55)';
  if (list.length < 3) {
    svg.appendChild(svgText(w / 2, h / 2, '軸を3つ以上選んでください', { fill: fg2, fontSize: 12, anchor: 'middle' }));
    return svg;
  }
  const cx = w / 2;
  const cy = h / 2;
  const labelMargin = options.showLabels === false ? 8 : 22;
  const radius = Math.max(20, Math.min(w, h) / 2 - labelMargin);
  const angleAt = (i) => (Math.PI * 2 * i) / list.length - Math.PI / 2;
  const pointAt = (i, ratio) => [cx + Math.cos(angleAt(i)) * radius * ratio, cy + Math.sin(angleAt(i)) * radius * ratio];

  // 目盛リング（25/50/75/100%）とスポーク
  [0.25, 0.5, 0.75, 1].forEach(ratio => {
    const points = list.map((_a, i) => pointAt(i, ratio).map(v => Math.round(v * 10) / 10).join(',')).join(' ');
    svg.appendChild(svgCreate('polygon', { points, fill: 'none', stroke: fg2, 'stroke-width': ratio === 1 ? 1 : 0.5, opacity: ratio === 1 ? 0.8 : 0.45 }));
  });
  list.forEach((_a, i) => {
    const [x, y] = pointAt(i, 1);
    svg.appendChild(svgLine(cx, cy, x, y, fg2, 0.5));
  });

  // 値の多角形
  const valuePoints = list.map((axis, i) => {
    const max = Number(axis.max) > 0 ? Number(axis.max) : 1;
    const ratio = Math.max(0, Math.min(1, Number(axis.value || 0) / max));
    return pointAt(i, ratio).map(v => Math.round(v * 10) / 10).join(',');
  }).join(' ');
  svg.appendChild(svgCreate('polygon', {
    points: valuePoints,
    fill: accent,
    'fill-opacity': 0.28,
    stroke: accent,
    'stroke-width': 2,
    'stroke-linejoin': 'round',
    class: 'el-radar-polygon',
  }));

  // 軸ラベル（値付き）。SVGの左右端で見切れないよう描画位置をクランプする
  if (options.showLabels !== false) {
    list.forEach((axis, i) => {
      const [rawX, y] = pointAt(i, 1.06 + 10 / radius);
      const anchor = Math.abs(rawX - cx) < radius * 0.25 ? 'middle' : (rawX < cx ? 'end' : 'start');
      const label = String(axis.label).slice(0, 8) + (options.showValues === false ? '' : ' ' + (Math.round(Number(axis.value || 0) * 10) / 10));
      const approxWidth = label.length * 6.5;
      let x = rawX;
      if (anchor === 'end') x = Math.max(approxWidth, rawX);
      else if (anchor === 'start') x = Math.min(w - approxWidth, rawX);
      else x = Math.max(approxWidth / 2, Math.min(w - approxWidth / 2, rawX));
      svg.appendChild(svgText(x, y + 3, label, { fill: 'currentColor', fontSize: 10, anchor }));
    });
  }
  return svg;
}

/* chart セルの内容を描画する。radar は同期、bar/pie/line は /pivot 取得後に差し込む。 */
function _elBuildChartCellContent(cell, ctx, canvasEl) {
  const wrap = document.createElement('div');
  wrap.className = 'el-cell-content el-cell-chart-content';
  const cfg = _elIsObj(cell.chart) ? cell.chart : {};
  const w = Math.max(80, cell.w - 16);
  const h = Math.max(60, cell.h - 16);

  if (!cfg.chartType) {
    const empty = document.createElement('div');
    empty.className = 'el-cell-placeholder';
    empty.textContent = ctx.editMode ? 'チャート未設定（歯車ボタンで設定）' : '';
    wrap.appendChild(empty);
    return wrap;
  }

  if (cfg.chartType === 'radar') {
    const rawAxes = (Array.isArray(cfg.axes) ? cfg.axes : []).map(axis => ({
      prop: String(axis?.prop || ''),
      label: axis?.label || String(axis?.prop || ''),
      explicitMax: Number(axis?.max) > 0 ? Number(axis.max) : 0,
      value: _elEntityNumericValue(String(axis?.prop || ''), ctx),
    }));
    // 最大値の優先順位: 軸ごとの指定 > レイアウト共通の指定 > 全軸の実測最大（共通スケールで偏りを防ぐ）
    const sharedMax = Number(cfg.axisMax) > 0 ? Number(cfg.axisMax) : 0;
    const autoMax = Math.max(1, ...rawAxes.map(a => a.value));
    const axes = rawAxes.map(axis => ({
      label: axis.label,
      value: axis.value,
      max: axis.explicitMax || sharedMax || autoMax,
    }));
    wrap.appendChild(_elRenderRadarChart(axes, w, h, { showLabels: cfg.showLabels !== false }));
    return wrap;
  }

  const loading = document.createElement('div');
  loading.className = 'el-cell-placeholder';
  loading.textContent = '読み込み中…';
  wrap.appendChild(loading);
  const chartConfig = {
    chartType: cfg.chartType,
    xProperty: cfg.xProperty || '',
    yAggregation: cfg.yAggregation || 'count',
    yProperty: cfg.yProperty || '',
    showLabels: cfg.showLabels !== false,
    showLegend: cfg.showLegend !== false,
    palette: cfg.palette || 'default',
  };
  _elFetchPivotData(ctx.dbPath)
    .then(async (pivotData) => {
      if (!wrap.isConnected) return;
      if (!pivotData) {
        loading.textContent = 'チャートを読み込めませんでした';
        return;
      }
      const data = typeof prepareChartDataAsync === 'function'
        ? await prepareChartDataAsync(pivotData, chartConfig, ctx.dbPath, {})
        : prepareChartData(pivotData, chartConfig, ctx.dbPath, {});
      if (!wrap.isConnected) return;
      wrap.replaceChildren();
      if (!data || !Array.isArray(data.labels) || data.labels.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'el-cell-placeholder';
        empty.textContent = 'データがありません（歯車ボタンで列を設定）';
        wrap.appendChild(empty);
        return;
      }
      let svg = null;
      if (chartConfig.chartType === 'pie' && typeof renderPieChart === 'function') svg = renderPieChart(data, w, h, chartConfig);
      else if (chartConfig.chartType === 'line' && typeof renderLineChart === 'function') svg = renderLineChart(data, w, h, chartConfig);
      else if (typeof renderBarChart === 'function') svg = renderBarChart(data, w, h, chartConfig);
      if (svg) wrap.appendChild(svg);
    })
    .catch(() => {
      if (!wrap.isConnected) return;
      loading.textContent = 'チャートを読み込めませんでした';
    });
  return wrap;
}

/* --- chart セルの設定ポップアップ --- */

function _elNumericChartProps(ctx) {
  const types = _elChartPropTypes(ctx);
  return Object.keys(ctx.data?.properties || {})
    .concat(Object.keys(types))
    .filter((prop, index, list) => list.indexOf(prop) === index)
    // rollup はエントリ画面にその場の再計算経路が無く、保存済みの古い生値を拾ってしまうため
    // レーダー軸候補には含めない（number と formula のみ）
    .filter(prop => ['number', 'formula'].includes(types[prop]?.type));
}

function _elAllChartProps(ctx) {
  const types = _elChartPropTypes(ctx);
  return Object.keys(ctx.data?.properties || {})
    .concat(Object.keys(types))
    .filter((prop, index, list) => list.indexOf(prop) === index);
}

function _elShowChartCellPopup(anchorBtn, ctx, existingCell) {
  _elCloseEditPopups();
  const popup = document.createElement('div');
  popup.className = 'gb-context-menu el-edit-popup el-chart-popup';
  popup.dataset.e2eId = 'entity-layout-chart-popup';

  const title = document.createElement('div');
  title.className = 'el-popup-title';
  title.textContent = existingCell ? 'チャートの設定' : 'チャートセルを追加';
  popup.appendChild(title);

  const current = _elIsObj(existingCell?.chart) ? existingCell.chart : {};

  const typeRow = document.createElement('label');
  typeRow.className = 'el-popup-row';
  const typeLabel = document.createElement('span');
  typeLabel.textContent = '種類';
  typeRow.appendChild(typeLabel);
  const typeSelect = document.createElement('select');
  typeSelect.className = 'gb-input';
  typeSelect.dataset.e2eId = 'entity-layout-chart-type';
  EL_CHART_TYPES.forEach(item => {
    const option = document.createElement('option');
    option.value = item.type;
    option.textContent = item.label;
    typeSelect.appendChild(option);
  });
  typeSelect.value = current.chartType || 'bar';
  typeRow.appendChild(typeSelect);
  popup.appendChild(typeRow);

  const body = document.createElement('div');
  body.className = 'el-chart-popup-body';
  popup.appendChild(body);

  const buildBody = () => {
    body.replaceChildren();
    if (typeSelect.value === 'radar') {
      const hint = document.createElement('div');
      hint.className = 'el-popup-hint';
      hint.textContent = '軸にする数値列（3つ以上）';
      body.appendChild(hint);
      const numericProps = _elNumericChartProps(ctx);
      if (numericProps.length === 0) {
        const none = document.createElement('div');
        none.className = 'el-popup-hint';
        none.textContent = '数値・数式の列がありません';
        body.appendChild(none);
      }
      const selected = new Set((Array.isArray(current.axes) ? current.axes : []).map(a => a?.prop));
      numericProps.forEach(prop => {
        const row = document.createElement('label');
        row.className = 'el-chart-axis-row';
        const check = document.createElement('input');
        check.type = 'checkbox';
        check.checked = selected.has(prop);
        check.dataset.prop = prop;
        check.dataset.e2eId = 'entity-layout-chart-axis';
        row.appendChild(check);
        const span = document.createElement('span');
        span.textContent = prop;
        row.appendChild(span);
        body.appendChild(row);
      });
      const maxRow = document.createElement('label');
      maxRow.className = 'el-popup-row';
      const maxLabel = document.createElement('span');
      maxLabel.textContent = '最大値（空欄で自動）';
      maxRow.appendChild(maxLabel);
      const maxInput = document.createElement('input');
      maxInput.type = 'number';
      maxInput.min = '1';
      maxInput.dataset.e2eId = 'entity-layout-chart-axis-max';
      maxInput.value = current.axisMax > 0 ? String(current.axisMax) : '';
      maxRow.appendChild(maxInput);
      body.appendChild(maxRow);
      return;
    }
    const makeSelectRow = (labelText, e2eId, options, value) => {
      const row = document.createElement('label');
      row.className = 'el-popup-row';
      const span = document.createElement('span');
      span.textContent = labelText;
      row.appendChild(span);
      const select = document.createElement('select');
      select.className = 'gb-input';
      select.dataset.e2eId = e2eId;
      options.forEach(([optionValue, optionLabel]) => {
        const option = document.createElement('option');
        option.value = optionValue;
        option.textContent = optionLabel;
        select.appendChild(option);
      });
      select.value = value;
      row.appendChild(select);
      body.appendChild(row);
      return select;
    };
    const allProps = _elAllChartProps(ctx);
    const xSelect = makeSelectRow('横軸の列', 'entity-layout-chart-x',
      allProps.map(prop => [prop, prop]), current.xProperty || allProps[0] || '');
    const aggSelect = makeSelectRow('集計', 'entity-layout-chart-agg',
      EL_CHART_AGGREGATIONS.map(item => [item.value, item.label]), current.yAggregation || 'count');
    const numericProps = _elNumericChartProps(ctx);
    const ySelect = makeSelectRow('値の列（件数以外）', 'entity-layout-chart-y',
      [['', '（未選択）']].concat(numericProps.map(prop => [prop, prop])), current.yProperty || '');
    body._collect = () => ({
      xProperty: xSelect.value,
      yAggregation: aggSelect.value,
      yProperty: ySelect.value,
    });
  };
  typeSelect.addEventListener('change', buildBody);
  buildBody();

  const applyBtn = document.createElement('button');
  applyBtn.type = 'button';
  applyBtn.className = 'gb-btn gb-btn-sm gb-btn-primary primary';
  applyBtn.dataset.e2eId = 'entity-layout-chart-apply';
  applyBtn.textContent = existingCell ? '適用' : '追加';
  applyBtn.addEventListener('click', () => {
    const chartType = typeSelect.value;
    const chart = { chartType };
    if (chartType === 'radar') {
      chart.axes = Array.from(body.querySelectorAll('input[type="checkbox"][data-prop]'))
        .filter(check => check.checked)
        .map(check => ({ prop: check.dataset.prop }));
      const axisMax = parseFloat(body.querySelector('[data-e2e-id="entity-layout-chart-axis-max"]')?.value || '');
      if (Number.isFinite(axisMax) && axisMax > 0) chart.axisMax = axisMax;
      if (chart.axes.length < 3) {
        if (typeof showStatus === 'function') showStatus('レーダーには数値列を3つ以上選んでください', true);
        return;
      }
    } else {
      const collected = typeof body._collect === 'function' ? body._collect() : {};
      chart.xProperty = collected.xProperty || '';
      chart.yAggregation = collected.yAggregation || 'count';
      chart.yProperty = collected.yProperty || '';
      if (!chart.xProperty) {
        if (typeof showStatus === 'function') showStatus('横軸の列を選んでください', true);
        return;
      }
    }
    close();
    if (existingCell) {
      _elPersistCellPatch(ctx, existingCell, 'トピックレイアウト: チャート設定', (target) => {
        target.chart = chart;
      });
      ctx.rerender();
    } else {
      _elAddCell(ctx, { type: 'chart', w: 320, h: 240, chart }, 'チャート');
    }
  });
  popup.appendChild(applyBtn);

  const close = _elAttachPopupCommon(popup, anchorBtn);
}

;

/* === gb-db-rollup.js === */
;
/* ==============================
   gb-db-rollup.js: ロールアッププロパティ＋リレーション解決キャッシュ
   リレーション先DBの値を集計するプロパティ型を提供
   ============================== */

/* --- リレーション解決キャッシュ --- */
const _rollupCache = new Map();
let _rollupRelationLoadSeq = 0;

/**
 * リレーション先DBのpivotDataを取得（キャッシュ付き）
 */
async function fetchRelatedDbData(dbPath) {
  if (!dbPath) return null;
  const cached = _rollupCache.get(dbPath);
  const fresh = typeof _dbCacheIsFresh === 'function'
    ? _dbCacheIsFresh(cached, 'rollup')
    : cached && Date.now() - cached.timestamp < 30000;
  if (fresh) {
    return cached.data;
  }
  try {
    const data = await apiFetch('/pivot?path=' + encodeURIComponent(dbPath));
    _rollupCache.set(dbPath, { data, timestamp: Date.now() });
    return data;
  } catch (e) {
    return null;
  }
}

/**
 * キャッシュをクリアする
 */
function clearRollupCache(dbPath) {
  if (dbPath) _rollupCache.delete(dbPath);
  else _rollupCache.clear();
}

/* --- リレーション解決 --- */

/**
 * エントリのリレーション値を解決し、参照先エントリ名の配列を返す
 */
function resolveRelationNames(entityName, entitiesMap, relationPropName, propTypes, sourceDbPath, filterMode) {
  const ptc = propTypes?.[relationPropName];
  if (!ptc || (ptc.type !== 'relation' && ptc.type !== 'multi-relation')) return { names: [], refs: [], targetDbPath: null };

  // リレーションセルと同じ解決規則を使い、作品フォルダー相対パスも同じ参照先へ揃える
  const effectiveSourcePath = sourceDbPath || state.currentDbPath || '';
  const targetDbPath = typeof _dbResolveRelationDbPath === 'function'
    ? _dbResolveRelationDbPath(effectiveSourcePath, ptc)
    : ((ptc.relationDb === '' || ptc.relationDb == null) ? effectiveSourcePath : ptc.relationDb);
  if (!targetDbPath) return { names: [], refs: [], targetDbPath: null };

  const rawVals = entitiesMap[entityName]?.[relationPropName] || [];
  const vals = filterValues(rawVals, undefined, filterMode);
  const refs = [];
  vals.forEach((v, filteredIndex) => {
    if (!v.value) return;
    const sourceIndex = rawVals.indexOf(v);
    const candidateIndex = sourceIndex >= 0 ? sourceIndex : filteredIndex;
    const addRef = (name) => {
      if (!name) return;
      refs.push({
        name,
        status: v.status || '採用',
        candidateIndex,
      });
    };
    // multi-relationの場合、カンマ区切りの可能性
    if (ptc.type === 'multi-relation') {
      v.value.split(',').forEach(n => addRef(n.trim()));
    } else {
      addRef(v.value.trim());
    }
  });
  return { names: refs.map(ref => ref.name), refs, targetDbPath };
}

function _rollupIdToNameMap(targetData) {
  const map = new Map();
  Object.entries(targetData?.entities || {}).forEach(([name, props]) => {
    if (props?._id) map.set(String(props._id), name);
  });
  return map;
}

function _rollupResolveEntityNames(names, targetData) {
  const idToName = _rollupIdToNameMap(targetData);
  return names.map(n => idToName.get(String(n)) || n);
}

function _rollupEffectiveAggregation(rollupConfig) {
  return rollupConfig?.aggregation || 'values';
}

function _rollupValuesResult(relationProp, targetDbPath, groups) {
  const normalizedGroups = (groups || []).map(group => ({
    relationId: String(group?.relationId || ''),
    relationName: String(group?.relationName || group?.relationId || '—'),
    relationStatus: String(group?.relationStatus || '採用'),
    relationCandidateIndex: Number.isInteger(group?.relationCandidateIndex) ? group.relationCandidateIndex : 0,
    values: Array.isArray(group?.values) && group.values.length
      ? group.values.map(value => String(value == null || value === '' ? '—' : value))
      : ['—'],
  }));
  const text = normalizedGroups.length
    ? normalizedGroups.flatMap(group => group.values).join('\n')
    : '—';
  return {
    kind: 'rollup-values',
    relationProp: relationProp || '',
    targetDbPath: targetDbPath || '',
    groups: normalizedGroups,
    text,
    toString() { return this.text; },
  };
}

function _rollupSplitDisplayValue(value, propType) {
  const text = String(value == null ? '' : value);
  if (!text.trim()) return [];
  const byLine = text.split(/\r?\n/).map(part => part.trim()).filter(Boolean);
  if (!['multi-select', 'multi-user', 'multi-relation'].includes(propType)) return byLine;
  return byLine.flatMap(part => part.split(',').map(item => item.trim()).filter(Boolean));
}

function _rollupImageDisplayStrings(rawValue) {
  try {
    const parsed = typeof rawValue === 'string' ? JSON.parse(rawValue) : rawValue;
    const items = Array.isArray(parsed) ? parsed : [parsed];
    return items.map(item => {
      if (typeof item === 'string') return item;
      return item?.caption || item?.name || item?.filename || item?.path || item?.url || '';
    }).filter(Boolean);
  } catch {
    return _rollupSplitDisplayValue(rawValue, 'text');
  }
}

async function _rollupResolveTargetRelationStrings(values, targetPtc, targetDbPath) {
  const relationDbPath = typeof _dbResolveRelationDbPath === 'function'
    ? _dbResolveRelationDbPath(targetDbPath, targetPtc)
    : ((targetPtc?.relationDb === '' || targetPtc?.relationDb == null) ? targetDbPath : targetPtc?.relationDb);
  if (!relationDbPath) return values;
  const relationData = await fetchRelatedDbData(relationDbPath);
  if (!relationData?.entities) return values;
  const idToName = _rollupIdToNameMap(relationData);
  return values.map(value => idToName.get(String(value)) || value);
}

async function _rollupTargetDisplayStrings(entityData, targetProp, targetPtc, targetPropTypes, targetDbPath, filterMode) {
  if (!entityData) return ['—'];

  const metadataSource = typeof _dbPropertyMetadataSource === 'function'
    ? _dbPropertyMetadataSource(targetPtc)
    : (['created', 'modified', 'modified_by'].includes(targetPtc?.source) ? targetPtc.source : '');
  if (metadataSource) {
    const sourceValue = entityData['_' + metadataSource];
    if (sourceValue == null || sourceValue === '') return ['—'];
    if ((metadataSource === 'created' || metadataSource === 'modified')
        && typeof _formatDateDisplay === 'function') {
      return [_formatDateDisplay(String(sourceValue), targetPtc)];
    }
    return [String(sourceValue)];
  }

  if (targetPtc?.type === 'formula' && targetPtc.formula && typeof formulaEvalForEntity === 'function') {
    const result = formulaEvalForEntity(targetPtc.formula, entityData, { propTypes: targetPropTypes, dbPath: targetDbPath });
    return result?.error || result?.value == null || result.value === '' ? ['—'] : [String(result.value)];
  }

  const rawValues = Array.isArray(entityData[targetProp]) ? entityData[targetProp] : [];
  const filtered = typeof filterValues === 'function'
    ? filterValues(rawValues, undefined, filterMode)
    : rawValues;
  let displayValues = [];
  filtered.forEach(item => {
    const rawValue = item?.value;
    if (targetPtc?.type === 'image') displayValues.push(..._rollupImageDisplayStrings(rawValue));
    else displayValues.push(..._rollupSplitDisplayValue(rawValue, targetPtc?.type || 'text'));
  });
  if (!displayValues.length) return ['—'];

  if (targetPtc?.type === 'relation' || targetPtc?.type === 'multi-relation') {
    displayValues = await _rollupResolveTargetRelationStrings(displayValues, targetPtc, targetDbPath);
  } else if (targetPtc?.type === 'date' && typeof _formatDateDisplay === 'function') {
    displayValues = displayValues.map(value => _formatDateDisplay(value, targetPtc));
  }
  return displayValues.length ? displayValues : ['—'];
}

async function _rollupBuildValuesResult(refs, targetData, targetDbPath, relationProp, targetProp, filterMode) {
  const names = refs.map(ref => ref.name);
  const targetNames = _rollupResolveEntityNames(names, targetData);
  const targetPropTypes = getPropertyTypes(targetDbPath);
  const targetPtc = targetPropTypes?.[targetProp] || null;
  const groups = [];

  for (let idx = 0; idx < names.length; idx++) {
    const relationId = names[idx];
    const relationName = targetNames[idx] || relationId;
    const values = await _rollupTargetDisplayStrings(
      targetData?.entities?.[relationName],
      targetProp,
      targetPtc,
      targetPropTypes,
      targetDbPath,
      filterMode
    );
    groups.push({
      relationId,
      relationName,
      relationStatus: refs[idx]?.status || '採用',
      relationCandidateIndex: refs[idx]?.candidateIndex || 0,
      values,
    });
  }
  return _rollupValuesResult(relationProp, targetDbPath, groups);
}

/* --- ロールアップ計算 --- */

/**
 * 1エントリのロールアップ値を計算する
 */
async function calcRollupValue(entityName, entitiesMap, rollupConfig, propTypes, sourceDbPath, filterMode) {
  const { relationProp, targetProp } = rollupConfig;
  const aggregation = _rollupEffectiveAggregation(rollupConfig);
  const { names, refs, targetDbPath } = resolveRelationNames(entityName, entitiesMap, relationProp, propTypes, sourceDbPath, filterMode);
  if (names.length === 0 || !targetDbPath) {
    return aggregation === 'count'
      ? 0
      : (aggregation === 'values' ? _rollupValuesResult(relationProp, targetDbPath, []) : '-');
  }

  const targetData = await fetchRelatedDbData(targetDbPath);
  if (!targetData || !targetData.entities) {
    return aggregation === 'values'
      ? _rollupValuesResult(relationProp, targetDbPath, refs.map(ref => ({
          relationId: ref.name,
          relationName: ref.name,
          relationStatus: ref.status,
          relationCandidateIndex: ref.candidateIndex,
          values: ['—'],
        })))
      : '-';
  }

  if (aggregation === 'values') {
    return _rollupBuildValuesResult(refs, targetData, targetDbPath, relationProp, targetProp, filterMode);
  }

  const targetNames = _rollupResolveEntityNames(names, targetData);

  // countの場合はリレーション先エントリ数を返す
  if (aggregation === 'count') {
    return targetNames.filter(n => targetData.entities[n]).length;
  }

  // 参照先エントリのサブセットで集計
  const subMap = {};
  const subNames = [];
  targetNames.forEach(n => {
    if (targetData.entities[n]) {
      subMap[n] = targetData.entities[n];
      subNames.push(n);
    }
  });

  if (subNames.length === 0) return '-';

  const targetPropTypes = getPropertyTypes(targetDbPath);
  const targetPtc = targetPropTypes?.[targetProp] || null;

  return calcAggregation(targetProp, subMap, subNames, aggregation, targetPtc, targetPropTypes, filterMode);
}

/**
 * DB全体のロールアップ値を一括計算（バッチ最適化）
 * @returns {Promise<Map<string, string|number>>} entityName → 集計値
 */
async function calcRollupColumn(entitiesMap, entityNames, rollupConfig, propTypes, sourceDbPath, filterMode) {
  const { relationProp, targetProp } = rollupConfig;
  const aggregation = _rollupEffectiveAggregation(rollupConfig);
  const results = new Map();

  // 参照先DBを1回だけ取得
  const sampleEntity = entityNames[0];
  if (!sampleEntity) return results;
  const { targetDbPath } = resolveRelationNames(sampleEntity, entitiesMap, relationProp, propTypes, sourceDbPath, filterMode);
  if (!targetDbPath) {
    entityNames.forEach(en => results.set(
      en,
      aggregation === 'values' ? _rollupValuesResult(relationProp, '', []) : '-'
    ));
    return results;
  }

  const targetData = await fetchRelatedDbData(targetDbPath);
  if (!targetData || !targetData.entities) {
    entityNames.forEach(en => results.set(
      en,
      aggregation === 'values' ? _rollupValuesResult(relationProp, targetDbPath, []) : '-'
    ));
    return results;
  }

  const targetPropTypes = getPropertyTypes(targetDbPath);
  const targetPtc = targetPropTypes?.[targetProp] || null;

  for (const en of entityNames) {
    const { names, refs } = resolveRelationNames(en, entitiesMap, relationProp, propTypes, sourceDbPath, filterMode);
    if (names.length === 0) {
      results.set(
        en,
        aggregation === 'count'
          ? 0
          : (aggregation === 'values' ? _rollupValuesResult(relationProp, targetDbPath, []) : '-')
      );
      continue;
    }

    if (aggregation === 'values') {
      results.set(en, await _rollupBuildValuesResult(refs, targetData, targetDbPath, relationProp, targetProp, filterMode));
      continue;
    }

    const targetNames = _rollupResolveEntityNames(names, targetData);

    if (aggregation === 'count') {
      results.set(en, targetNames.filter(n => targetData.entities[n]).length);
      continue;
    }

    const subMap = {};
    const subNames = [];
    targetNames.forEach(n => {
      if (targetData.entities[n]) {
        subMap[n] = targetData.entities[n];
        subNames.push(n);
      }
    });

    if (subNames.length === 0) {
      results.set(en, '-');
      continue;
    }

    const val = calcAggregation(targetProp, subMap, subNames, aggregation, targetPtc, targetPropTypes, filterMode);
    results.set(en, val);
  }

  return results;
}

/* --- UI: ロールアッププロパティ型設定 --- */

/**
 * プロパティ型モーダル内のロールアップ設定HTMLを生成
 */
function buildRollupOptionsHtml(current, dbProperties, propTypes, root) {
  // リレーション型プロパティのみフィルタ
  const relationProps = dbProperties.filter(p => {
    const pt = propTypes?.[p];
    return pt && (pt.type === 'relation' || pt.type === 'multi-relation');
  });

  const initialTargetType = current?.targetProp ? propTypes?.[current.targetProp]?.type : '';
  const aggOptions = _rollupAggregationOptionsForType(initialTargetType);

  // リレーション列が1つも無いシートでは、空のドロップダウンを出すと
  // 「選べないのに理由が分からない」状態になるため、その場で理由を出す。
  const hasRelationProps = relationProps.length > 0;

  let html = '<div class="field"><label>リレーション列</label>';
  html += '<select id="rollup-relation-prop"' + (hasRelationProps ? '' : ' disabled') + '>';
  if (!hasRelationProps) {
    html += '<option value="">リレーション列がありません</option>';
  } else {
    html += '<option value="">選択...</option>';
    relationProps.forEach(p => {
      const sel = current?.relationProp === p ? ' selected' : '';
      html += '<option value="' + esc(p) + '"' + sel + '>' + esc(p) + '</option>';
    });
  }
  html += '</select>';
  if (!hasRelationProps) {
    html += '<div class="pt-hint">先にリレーション列を作ると、その参照先を集計できます。</div>';
  }
  html += '</div>';

  html += '<div class="field"><label>参照先の列</label>';
  html += '<select id="rollup-target-prop"><option value="">'
       + (current?.relationProp ? '読み込み中...' : 'リレーション列を選ぶと表示されます')
       + '</option></select></div>';

  html += '<div class="field"><label>表示方法</label>';
  html += '<select id="rollup-aggregation" data-current="' + esc(current?.aggregation || 'values') + '">';
  aggOptions.forEach(a => {
    const sel = (current?.aggregation || 'values') === a.key ? ' selected' : '';
    html += '<option value="' + a.key + '"' + sel + '>' + a.label + '</option>';
  });
  html += '</select></div>';

  // 初期ロード: 既存設定があれば参照先プロパティをロード
  if (current?.relationProp) {
    setTimeout(() => onRollupRelationChange(current.relationProp, current.targetProp, root), 100);
  }

  return html;
}

/**
 * リレーションプロパティ選択時に参照先DBのプロパティ一覧を動的取得
 */
async function onRollupRelationChange(relationPropName, preselect, root) {
  const scope = typeof _ptResolveRoot === 'function' ? _ptResolveRoot(root) : (root || document);
  const sel = typeof _ptGet === 'function' ? _ptGet('rollup-target-prop', scope) : document.getElementById('rollup-target-prop');
  if (!sel) return;
  const seq = (scope._rollupRelationLoadSeq || 0) + 1;
  scope._rollupRelationLoadSeq = seq;
  _rollupRelationLoadSeq++;
  sel.innerHTML = '<option value="">読み込み中...</option>';

  const dbPath = (typeof _ptState === 'function' ? _ptState(scope).dbPath : '') || state.currentDbPath;
  const propTypes = getPropertyTypes(dbPath);
  const ptc = propTypes?.[relationPropName];
  if (!ptc) {
    if (seq !== scope._rollupRelationLoadSeq) return;
    sel.innerHTML = '<option value="">(リレーション先未設定)</option>';
    _rollupSetAggregationOptionsForType('', 'values', scope);
    return;
  }
  const _relDb = typeof _dbResolveRelationDbPath === 'function'
    ? _dbResolveRelationDbPath(dbPath, ptc)
    : ((ptc.relationDb === '' || ptc.relationDb == null) ? dbPath : ptc.relationDb);
  const targetData = await fetchRelatedDbData(_relDb);
  if (seq !== scope._rollupRelationLoadSeq || sel !== (typeof _ptGet === 'function' ? _ptGet('rollup-target-prop', scope) : document.getElementById('rollup-target-prop'))) return;
  if (!targetData || !targetData.properties) {
    sel.innerHTML = '<option value="">(取得失敗)</option>';
    _rollupSetAggregationOptionsForType('', 'values', scope);
    return;
  }

  const targetPropTypes = _rollupTargetPropertyTypes(_relDb, targetData);
  const targetProps = Array.from(new Set([
    ...(Array.isArray(targetData.properties) ? targetData.properties : []),
    ...Object.keys(targetPropTypes || {}),
    ...(preselect ? [preselect] : []),
  ])).filter(p => p && !String(p).startsWith('_'));
  sel.innerHTML = '';
  targetProps.forEach(p => {
    const o = document.createElement('option');
    o.value = p;
    o.textContent = p;
    if (preselect === p) o.selected = true;
    sel.appendChild(o);
  });
  if (preselect && !targetProps.includes(preselect) && sel.options.length) sel.selectedIndex = 0;
  sel.onchange = () => {
    const pt = targetPropTypes?.[sel.value]?.type || '';
    const aggSel = typeof _ptGet === 'function' ? _ptGet('rollup-aggregation', scope) : document.getElementById('rollup-aggregation');
    _rollupSetAggregationOptionsForType(pt, aggSel?.value || 'values', scope);
  };
  const selectedType = targetPropTypes?.[sel.value]?.type || '';
  const aggSel = typeof _ptGet === 'function' ? _ptGet('rollup-aggregation', scope) : document.getElementById('rollup-aggregation');
  _rollupSetAggregationOptionsForType(selectedType, aggSel?.dataset.current || 'values', scope);
}

/**
 * ロールアップ設定を収集して返す
 */
function collectRollupConfig(root) {
  const scope = typeof _ptResolveRoot === 'function' ? _ptResolveRoot(root) : (root || document);
  const get = (id) => typeof _ptGet === 'function' ? _ptGet(id, scope) : document.getElementById(id);
  const relationProp = get('rollup-relation-prop')?.value || '';
  const targetProp = get('rollup-target-prop')?.value || '';
  const aggregation = get('rollup-aggregation')?.value || 'values';
  return { type: 'rollup', relationProp, targetProp, aggregation };
}

function _rollupAggregationOptionsForType(propType) {
  const valuesOption = { key: 'values', label: '文字列' };
  if (typeof getAggregationTypesForProperty === 'function') {
    return [
      valuesOption,
      ...getAggregationTypesForProperty(propType || 'text').filter(a => a.key !== 'none' && a.key !== 'values'),
    ];
  }
  return [
    valuesOption,
    { key: 'count', label: '件数' },
    { key: 'unique', label: 'ユニーク' },
    { key: 'empty', label: '空' },
    { key: 'not_empty', label: '非空' },
  ];
}

function _rollupTargetPropertyTypes(dbPath, targetData) {
  if (targetData?.property_types) return targetData.property_types;
  if (targetData?.propertyTypes) return targetData.propertyTypes;
  const localTypes = getDbViewConfig(dbPath).propertyTypes || {};
  if (Object.keys(localTypes).length) return localTypes;
  return typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath) : {};
}

function _rollupSetAggregationOptionsForType(propType, preferred, root) {
  const scope = typeof _ptResolveRoot === 'function' ? _ptResolveRoot(root) : (root || document);
  const aggSel = typeof _ptGet === 'function' ? _ptGet('rollup-aggregation', scope) : document.getElementById('rollup-aggregation');
  if (!aggSel) return;
  const options = _rollupAggregationOptionsForType(propType);
  const nextValue = options.some(a => a.key === preferred) ? preferred : 'values';
  aggSel.innerHTML = '';
  options.forEach(a => {
    const o = document.createElement('option');
    o.value = a.key;
    o.textContent = a.label;
    if (a.key === nextValue) o.selected = true;
    aggSel.appendChild(o);
  });
  aggSel.dataset.current = aggSel.value || nextValue;
  aggSel.onchange = () => { aggSel.dataset.current = aggSel.value; };
}

;

/* === gb-db-graph.js === */
;
/* ==============================
   gb-db-graph.js: リレーショングラフビュー
   エントリ間のリレーションをSVGノードグラフで可視化
   ============================== */

/* --- グラフ設定 --- */

function getGraphConfig(dbPath, options = {}) {
  return getCurrentDbViewTypeSpecific(dbPath, 'graph', { ctx: options.ctx || null }) || {
    colorProperty: '',
    showExternalNodes: true,
    layout: 'force',
    showLabels: true,
    showEdgeLabels: false,
  };
}

function setGraphConfig(dbPath, config, options = {}) {
  const label = options.historyLabel || options.label || '';
  setCurrentDbViewTypeSpecific(dbPath, 'graph', config || {}, {
    ctx: options.ctx || null,
    historyLabel: label,
    detail: options.detail || '',
    skipHistory: options.skipHistory === true || !label,
  });
}

function _graphPropertyAllowed(propName) {
  return !!propName && !String(propName).startsWith('_');
}

function _collectGraphProperties(pivotData, dbPath) {
  const entities = pivotData?.entities || {};
  if (typeof _collectChartProperties === 'function') {
    return _collectChartProperties(entities, pivotData, dbPath);
  }
  const propSet = new Set();
  const add = (propName) => {
    if (_graphPropertyAllowed(propName)) propSet.add(propName);
  };
  (pivotData?.properties || []).forEach(add);
  const propTypes = pivotData?.propertyTypes || (typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath) : {});
  Object.keys(propTypes || {}).forEach(add);
  Object.values(entities).forEach(entData => {
    Object.keys(entData || {}).forEach(add);
  });
  const names = [...propSet];
  return typeof filterDeletedDbProperties === 'function' ? filterDeletedDbProperties(dbPath, names) : names;
}

/* --- データ準備 --- */

function _graphNodeKey(dbPath, entityName) {
  return `${dbPath || ''}::${entityName || ''}`;
}

function _graphEntityPathForDb(pivotData, dbPath, entityName) {
  if (!dbPath || !entityName) return '';
  return pivotData?.new_format ? `${dbPath}/${entityName}.md` : `${dbPath}/${entityName}`;
}

function _graphRelationRawValues(entityData, propName, ptc, filterMode) {
  const rawVals = entityData?.[propName] || [];
  const vals = typeof filterValues === 'function' ? filterValues(rawVals, undefined, filterMode) : rawVals;
  const rawNames = [];
  vals.forEach(v => {
    if (!v?.value) return;
    if (ptc.type === 'multi-relation') {
      String(v.value).split(',').forEach(n => { const t = n.trim(); if (t) rawNames.push(t); });
    } else {
      const t = String(v.value).trim();
      if (t) rawNames.push(t);
    }
  });
  return rawNames;
}

function _graphOwn(obj, key) {
  return !!obj && Object.prototype.hasOwnProperty.call(obj, key);
}

function _graphParseMsrValue(value) {
  if (typeof _parseMsrValue === 'function') return _parseMsrValue(value);
  return String(value || '').split(',').map(s => s.trim()).filter(Boolean).map(s => {
    const sep = s.indexOf('::');
    if (sep < 0) return { db: '', id: s };
    return { db: s.substring(0, sep), id: s.substring(sep + 2) };
  });
}

async function _graphResolveMsrTargets(entityData, propName, filterMode) {
  const vals = typeof filterValues === 'function' ? filterValues(entityData?.[propName] || [], undefined, filterMode) : (entityData?.[propName] || []);
  const rawEntries = [];
  vals.forEach(v => _graphParseMsrValue(v?.value || '').forEach(entry => rawEntries.push(entry)));
  const targets = [];
  for (const entry of rawEntries) {
    const targetDbPath = entry.db || '';
    const raw = entry.id || '';
    if (!targetDbPath || !raw) continue;
    const map = typeof _getRelationMap === 'function' ? await _getRelationMap(targetDbPath) : null;
    const mappedName = _graphOwn(map?.idToName, raw) ? map.idToName[raw] : raw;
    const name = String(mappedName || raw);
    targets.push({
      name,
      dbPath: targetDbPath,
      pivotData: { new_format: !!map?.new_format },
      known: _graphOwn(map?.entities, name),
    });
  }
  return targets;
}

async function _graphResolveRelationTargets(rawValues, sourceDbPath, ptc, entityIdToName) {
  const targetDbPath = (ptc.relationDb === '' || ptc.relationDb == null) ? sourceDbPath : ptc.relationDb;
  if (!targetDbPath) return [];
  if (targetDbPath === sourceDbPath) {
    return rawValues.map(raw => ({
      name: entityIdToName.get(raw) || raw,
      dbPath: targetDbPath,
      pivotData: null,
      known: true,
    }));
  }
  const map = typeof _getRelationMap === 'function' ? await _getRelationMap(targetDbPath) : null;
  return rawValues.map(raw => {
    const mappedName = _graphOwn(map?.idToName, raw) ? map.idToName[raw] : raw;
    const name = String(mappedName || raw);
    return {
      name,
      dbPath: targetDbPath,
      pivotData: { new_format: !!map?.new_format },
      known: _graphOwn(map?.entities, name),
    };
  });
}

/**
 * pivotDataからグラフノード・エッジを構築する
 */
async function buildGraphData(pivotData, dbPath, graphConfig, options = {}) {
  const entities = pivotData.entities || {};
  let entityNames = Object.keys(entities);
  const filterMode = options.filter ?? options.ctx?.filter;
  const advFilters = typeof getAdvancedFilters === 'function' ? getAdvancedFilters(dbPath, { ctx: options.ctx || null }) : [];
  if (Array.isArray(advFilters) && advFilters.length > 0 && typeof _dbEntityPassesAdvancedFilters === 'function') {
    entityNames = entityNames.filter(name => _dbEntityPassesAdvancedFilters(entities[name], advFilters, filterMode));
  }
  const columnValueFilters = typeof getColumnValueFilters === 'function'
    ? getColumnValueFilters(dbPath, { ctx: options.ctx || null })
    : {};
  if (typeof _dbEntityPassesColumnValueFilters === 'function' && Object.keys(columnValueFilters).length) {
    entityNames = entityNames.filter(name => _dbEntityPassesColumnValueFilters(
      name,
      entities[name],
      columnValueFilters,
      dbPath,
      options.ctx || null,
      filterMode,
    ));
  }
  const propTypes = getPropertyTypes(dbPath);
  const nodes = [];
  const edges = [];
  const nodeMap = new Map();
  const visibleEntitySet = new Set(entityNames);
  const entityIdToName = new Map();
  entityNames.forEach(name => {
    const id = entities[name]?._id;
    if (id) entityIdToName.set(String(id), name);
  });

  // ノード作成
  entityNames.forEach(name => {
    const node = {
      id: _graphNodeKey(dbPath, name), x: 0, y: 0, vx: 0, vy: 0,
      color: _getNodeColor(name, entities[name], graphConfig.colorProperty, filterMode),
      label: name, entityName: name, dbPath, isExternal: false,
      entityPath: _graphEntityPathForDb(pivotData, dbPath, name),
    };
    nodes.push(node);
    nodeMap.set(node.id, node);
  });

  // エッジ作成（リレーション型プロパティから）
  const externalNodes = new Map();
  for (const propName of Object.keys(propTypes)) {
    const ptc = propTypes[propName];
    if (!ptc || !['relation', 'multi-relation', 'multi-source-relation'].includes(ptc.type)) continue;

    for (const en of entityNames) {
      const targets = ptc.type === 'multi-source-relation'
        ? await _graphResolveMsrTargets(entities[en], propName, filterMode)
        : await _graphResolveRelationTargets(_graphRelationRawValues(entities[en], propName, ptc, filterMode), dbPath, ptc, entityIdToName);
      targets.forEach(target => {
        const targetName = target.name;
        const resolvedTargetDbPath = target.dbPath || dbPath || '';
        if (resolvedTargetDbPath === dbPath && !visibleEntitySet.has(targetName)) return;
        const targetKey = _graphNodeKey(resolvedTargetDbPath, targetName);
        edges.push({
          source: _graphNodeKey(dbPath, en),
          target: targetKey,
          label: propName,
          color: '#dcdcaa',
        });
        // 外部ノード（現在のDBに存在しない場合）
        if (!nodeMap.has(targetKey) && graphConfig.showExternalNodes) {
          if (!externalNodes.has(targetKey)) {
            const extNode = {
              id: targetKey, x: 0, y: 0, vx: 0, vy: 0,
              color: '#3e3e3e', label: targetName,
              entityName: targetName,
              dbPath: resolvedTargetDbPath,
              isExternal: true,
              entityPath: target.known ? _graphEntityPathForDb(target.pivotData, resolvedTargetDbPath, targetName) : '',
            };
            externalNodes.set(targetKey, extNode);
          }
        }
      });
    }
  }

  // 外部ノードを追加
  externalNodes.forEach(node => { nodes.push(node); nodeMap.set(node.id, node); });

  return { nodes, edges };
}

function _getNodeColor(name, entityData, colorProp, filterMode) {
  if (!colorProp || !entityData || !entityData[colorProp]) return '#569cd6';
  const vals = filterValues(entityData[colorProp] || [], undefined, filterMode);
  if (vals.length === 0) return '#569cd6';
  const v = vals[0].value;
  // ステータス色
  const statusColors = { '掲載済み': '#608b4e', '採用': '#569cd6', '案': '#ce9178', 'ボツ': '#3e3e3e' };
  return statusColors[v] || _hashColor(v);
}

function _hashColor(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = ((h << 5) - h + str.charCodeAt(i)) | 0;
  const hue = Math.abs(h) % 360;
  return 'hsl(' + hue + ',55%,55%)';
}

/* --- Force-Directed レイアウト --- */

function layoutForceDirected(nodes, edges, w, h, iterations) {
  iterations = iterations || 100;
  const n = nodes.length;
  if (n === 0) return;

  const area = w * h;
  const k = 0.6 * Math.sqrt(area / n);

  // 初期位置（円形配置）
  nodes.forEach((node, i) => {
    const angle = (2 * Math.PI * i) / n;
    node.x = w / 2 + (w * 0.35) * Math.cos(angle);
    node.y = h / 2 + (h * 0.35) * Math.sin(angle);
  });

  // エッジのインデックスマップ
  const edgeIndex = edges.map(e => ({
    si: nodes.findIndex(n => n.id === e.source),
    ti: nodes.findIndex(n => n.id === e.target),
  })).filter(e => e.si >= 0 && e.ti >= 0);

  let temperature = w / 10;

  for (let iter = 0; iter < iterations; iter++) {
    // 反発力
    for (let i = 0; i < n; i++) {
      nodes[i].vx = 0; nodes[i].vy = 0;
      for (let j = 0; j < n; j++) {
        if (i === j) continue;
        const dx = nodes[i].x - nodes[j].x;
        const dy = nodes[i].y - nodes[j].y;
        const dist = Math.max(Math.sqrt(dx * dx + dy * dy), 1);
        const force = (k * k) / dist;
        nodes[i].vx += (dx / dist) * force;
        nodes[i].vy += (dy / dist) * force;
      }
    }
    // 引力
    edgeIndex.forEach(({ si, ti }) => {
      const dx = nodes[ti].x - nodes[si].x;
      const dy = nodes[ti].y - nodes[si].y;
      const dist = Math.max(Math.sqrt(dx * dx + dy * dy), 1);
      const force = (dist * dist) / k;
      const fx = (dx / dist) * force;
      const fy = (dy / dist) * force;
      nodes[si].vx += fx; nodes[si].vy += fy;
      nodes[ti].vx -= fx; nodes[ti].vy -= fy;
    });
    // 位置更新
    nodes.forEach(node => {
      const disp = Math.sqrt(node.vx * node.vx + node.vy * node.vy);
      if (disp > 0) {
        const capped = Math.min(disp, temperature);
        node.x += (node.vx / disp) * capped;
        node.y += (node.vy / disp) * capped;
      }
      node.x = Math.max(30, Math.min(w - 30, node.x));
      node.y = Math.max(30, Math.min(h - 30, node.y));
    });
    temperature *= 0.95;
  }
}

/* --- Hierarchical レイアウト --- */

function layoutHierarchical(nodes, edges, w, h) {
  if (nodes.length === 0) return;
  const nodeMap = new Map();
  nodes.forEach(n => nodeMap.set(n.id, n));

  // 入次数を計算
  const inDeg = new Map();
  nodes.forEach(n => inDeg.set(n.id, 0));
  edges.forEach(e => {
    if (inDeg.has(e.target)) inDeg.set(e.target, inDeg.get(e.target) + 1);
  });

  // BFS層分け
  const layers = [];
  const visited = new Set();
  let queue = nodes.filter(n => inDeg.get(n.id) === 0).map(n => n.id);
  if (queue.length === 0) queue = [nodes[0].id]; // 循環グラフ対策

  while (queue.length > 0) {
    const layer = [];
    queue.forEach(id => { if (!visited.has(id)) { visited.add(id); layer.push(id); } });
    if (layer.length === 0) break;
    layers.push(layer);
    const nextQueue = [];
    layer.forEach(id => {
      edges.forEach(e => {
        if (e.source === id && !visited.has(e.target)) nextQueue.push(e.target);
      });
    });
    queue = nextQueue;
  }
  // 未訪問ノードを最後の層に追加
  nodes.forEach(n => { if (!visited.has(n.id)) layers[layers.length - 1].push(n.id); });

  // 位置割り当て
  const layerH = h / (layers.length + 1);
  layers.forEach((layer, li) => {
    const layerW = w / (layer.length + 1);
    layer.forEach((id, ni) => {
      const node = nodeMap.get(id);
      if (node) { node.x = layerW * (ni + 1); node.y = layerH * (li + 1); }
    });
  });
}

/* --- SVG レンダリング --- */

function renderGraphSvg(nodes, edges, w, h, config) {
  const svg = svgCreate('svg', { width: w, height: h, viewBox: '0 0 ' + w + ' ' + h });
  if (nodes.length === 0) {
    svg.appendChild(svgText(w / 2, h / 2, 'リレーションなし', { fill: 'var(--fg2)', fontSize: '14' }));
    return svg;
  }

  const nodeMap = new Map();
  nodes.forEach(n => nodeMap.set(n.id, n));

  // transform group（パン＆ズーム用）
  const g = svgCreate('g', { class: 'graph-transform' });
  svg.appendChild(g);

  // エッジ描画
  edges.forEach(e => {
    const src = nodeMap.get(e.source);
    const tgt = nodeMap.get(e.target);
    if (!src || !tgt) return;
    const path = svgLine(src.x, src.y, tgt.x, tgt.y, e.color || '#555', 1.5);
    path.setAttribute('stroke-opacity', '0.6');
    g.appendChild(path);

    // 矢印（エッジの終端に小さい三角形）
    const dx = tgt.x - src.x, dy = tgt.y - src.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist > 40) {
      const nx = dx / dist, ny = dy / dist;
      const ax = tgt.x - nx * 22, ay = tgt.y - ny * 22;
      const arrowSize = 6;
      const px = -ny * arrowSize, py = nx * arrowSize;
      const d = `M${ax + px},${ay + py} L${tgt.x - nx * 18},${tgt.y - ny * 18} L${ax - px},${ay - py}`;
      const arrow = svgPath(d, e.color || '#555');
      arrow.setAttribute('fill-opacity', '0.7');
      g.appendChild(arrow);
    }

    // エッジラベル
    if (config.showEdgeLabels && e.label) {
      const mx = (src.x + tgt.x) / 2, my = (src.y + tgt.y) / 2;
      g.appendChild(svgText(mx, my - 4, e.label, { fontSize: '9', fill: 'var(--fg2)', anchor: 'middle' }));
    }
  });

  // ノード描画
  nodes.forEach(node => {
    const r = node.isExternal ? 14 : 20;
    const unresolvedExternal = node.isExternal && !node.entityPath;
    const circle = svgCreate('circle', { cx: node.x, cy: node.y, r, fill: node.color, cursor: unresolvedExternal ? 'not-allowed' : 'pointer' });
    if (node.isExternal) {
      circle.setAttribute('stroke', '#666');
      circle.setAttribute('stroke-width', '2');
      circle.setAttribute('stroke-dasharray', '4,2');
    }
    const title = svgCreate('title');
    title.textContent = node.label + (unresolvedExternal ? ' (参照先未解決)' : node.isExternal ? ' (外部DB)' : '');
    circle.appendChild(title);
    circle.dataset.nodeId = node.id;
    circle.dataset.entityName = node.entityName || node.label || node.id;
    circle.dataset.dbPath = node.dbPath || '';
    circle.dataset.entityPath = node.entityPath || '';
    circle.dataset.isExternal = node.isExternal ? '1' : '0';
    g.appendChild(circle);

    if (config.showLabels) {
      const truncLabel = node.label.length > 10 ? node.label.slice(0, 9) + '…' : node.label;
      g.appendChild(svgText(node.x, node.y + r + 14, truncLabel, {
        fontSize: '11', fill: 'var(--fg)', anchor: 'middle',
      }));
    }
  });

  return svg;
}

/* --- パン＆ズーム --- */

function addGraphPanZoom(svg, container) {
  const g = svg.querySelector('.graph-transform');
  if (!g) return;

  let scale = 1, tx = 0, ty = 0;
  let dragging = false, startX = 0, startY = 0;

  const updateTransform = () => {
    g.setAttribute('transform', `translate(${tx},${ty}) scale(${scale})`);
  };

  // 前回のwheelリスナーを除去（リーク防止）
  if (container._graphWheelHandler) {
    container.removeEventListener('wheel', container._graphWheelHandler);
  }
  container._graphWheelHandler = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    scale = Math.max(0.2, Math.min(5, scale * delta));
    updateTransform();
  };
  container.addEventListener('wheel', container._graphWheelHandler, { passive: false });

  svg.addEventListener('pointerdown', (e) => {
    if (e.target.closest('circle')) return; // ノードクリックは別処理
    dragging = true; startX = e.clientX - tx; startY = e.clientY - ty;
    svg.setPointerCapture(e.pointerId);
  });
  svg.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    tx = e.clientX - startX; ty = e.clientY - startY;
    updateTransform();
  });
  svg.addEventListener('pointerup', (e) => {
    dragging = false;
    svg.releasePointerCapture(e.pointerId);
  });
}

/* --- 設定バー --- */

function _buildGraphSettingsBar(dbPath, config, allProps, ctx) {
  const bar = document.createElement('div');
  bar.className = 'chart-settings-bar'; // チャートと同じスタイル再利用
  const graphScope = 'graph-' + ((ctx && ctx.paneId) || 'main');

  bar.appendChild(_chartLabel('レイアウト'));
  const layoutSel = _chartSelect([
    { key: 'force', label: '力学モデル' },
    { key: 'hierarchical', label: '階層' },
  ], config.layout, graphScope + '-layout', 'グラフレイアウト');
  layoutSel.addEventListener('change', () => {
    config.layout = layoutSel.value;
    setGraphConfig(dbPath, config, { ctx, label: 'シート表示: グラフ設定', detail: 'レイアウト' });
    _renderGraphForDbPanels(dbPath, ctx);
  });
  bar.appendChild(layoutSel);

  bar.appendChild(_chartLabel('色分け'));
  const colorOpts = [{ key: '', label: 'なし' }].concat(allProps.map(p => ({ key: p, label: p })));
  const colorSel = _chartSelect(colorOpts, config.colorProperty || '', graphScope + '-color-property', 'グラフ色分けの列');
  colorSel.addEventListener('change', () => {
    config.colorProperty = colorSel.value;
    setGraphConfig(dbPath, config, { ctx, label: 'シート表示: グラフ設定', detail: '色分け' });
    _renderGraphForDbPanels(dbPath, ctx);
  });
  bar.appendChild(colorSel);

  // ラベル表示トグル
  const labelCb = document.createElement('label');
  labelCb.style.cssText = 'display:flex;align-items:center;gap:4px;font-size:12px;color:var(--fg2);margin-left:12px;cursor:pointer;';
  const cb = document.createElement('input');
  cb.type = 'checkbox';
  cb.dataset.e2eId = graphScope + '-show-labels';
  cb.setAttribute('aria-label', 'グラフラベル表示');
  cb.checked = config.showLabels;
  cb.addEventListener('change', () => {
    config.showLabels = cb.checked;
    setGraphConfig(dbPath, config, { ctx, label: 'シート表示: グラフ設定', detail: 'ラベル' });
    _renderGraphForDbPanels(dbPath, ctx);
  });
  labelCb.appendChild(cb);
  labelCb.appendChild(document.createTextNode('ラベル'));
  bar.appendChild(labelCb);

  // 外部ノード表示トグル
  const extCb = document.createElement('label');
  extCb.style.cssText = 'display:flex;align-items:center;gap:4px;font-size:12px;color:var(--fg2);margin-left:8px;cursor:pointer;';
  const ecb = document.createElement('input');
  ecb.type = 'checkbox';
  ecb.dataset.e2eId = graphScope + '-show-external-nodes';
  ecb.setAttribute('aria-label', 'グラフ外部ノード表示');
  ecb.checked = config.showExternalNodes;
  ecb.addEventListener('change', () => {
    config.showExternalNodes = ecb.checked;
    setGraphConfig(dbPath, config, { ctx, label: 'シート表示: グラフ設定', detail: '外部ノード' });
    _renderGraphForDbPanels(dbPath, ctx);
  });
  extCb.appendChild(ecb);
  extCb.appendChild(document.createTextNode('外部ノード'));
  bar.appendChild(extCb);

  return bar;
}

/* --- メインレンダラ --- */

async function renderGraph(ctx) {
  ctx = ctx || _currentPaneState();
  const container = typeof _dbViewSurfaceEl === 'function'
    ? _dbViewSurfaceEl(ctx, '.graph-view', 'graph-view')
    : ((ctx?.containerEl ? ctx.containerEl.querySelector('.graph-view') : null) || document.getElementById('graph-view') || document.querySelector('.graph-view'));
  if (!container) return;
  if (!_graphIsActiveView(ctx, container)) {
    _disconnectGraphResizeObserver(container);
    return;
  }
  container.style.display = 'flex';
  const renderSeq = (container._graphRenderSeq || 0) + 1;
  container._graphRenderSeq = renderSeq;
  container.innerHTML = '';

  const dbPath = ctx.dbPath || state.currentDbPath;
  const pivotData = ctx.pivotData || state.pivotData;
  if (!dbPath || !pivotData) {
    _disconnectGraphResizeObserver(container);
    container.textContent = 'シートを選択してください';
    return;
  }

  const entities = pivotData.entities || {};
  if (Object.keys(entities).length === 0) {
    _disconnectGraphResizeObserver(container);
    if (typeof _dbRenderEmptyStateWithCreate === 'function') {
      _dbRenderEmptyStateWithCreate(container, 'share2', 'データがありません', 'トピックを追加するとグラフが表示されます', ctx);
    } else {
      renderEmptyState(container, 'share2', 'データがありません', 'トピックを追加するとグラフが表示されます');
    }
    return;
  }

  const config = getGraphConfig(dbPath, { ctx });
  const allProps = _collectGraphProperties(pivotData, dbPath);

  // 設定バー
  const bar = _buildGraphSettingsBar(dbPath, config, allProps, ctx);
  container.appendChild(bar);

  // グラフエリア
  const graphArea = document.createElement('div');
  graphArea.style.cssText = 'flex:1;overflow:hidden;position:relative;';
  container.appendChild(graphArea);

  // データ構築＆レイアウト
  const { nodes, edges } = await buildGraphData(pivotData, dbPath, config, { ctx, filter: ctx?.filter });
  if (container._graphRenderSeq !== renderSeq) return;
  const rect = container.getBoundingClientRect();
  const w = Math.max(rect.width || 600, 400);
  const h = Math.max(rect.height - 40 || 400, 300);
  if (nodes.length === 0) {
    const empty = document.createElement('div');
    empty.style.cssText = 'height:100%;display:flex;align-items:center;justify-content:center;color:var(--fg2);font-size:14px;';
    empty.textContent = '表示するトピックがありません';
    graphArea.appendChild(empty);
    _observeGraphResize(container, ctx, rect);
    return;
  }

  if (config.layout === 'hierarchical') layoutHierarchical(nodes, edges, w, h);
  else layoutForceDirected(nodes, edges, w, h);

  const svg = renderGraphSvg(nodes, edges, w, h, config);
  graphArea.appendChild(svg);
  _observeGraphResize(container, ctx, rect);

  // パン＆ズーム
  addGraphPanZoom(svg, graphArea);

  // ノードクリック
  svg.addEventListener('click', (e) => {
    const circle = e.target.closest('circle[data-node-id]');
    if (!circle) return;
    const nodeName = circle.dataset.entityName || circle.dataset.nodeId;
    const nodeDbPath = circle.dataset.dbPath;
    const entityPath = circle.dataset.entityPath;
    const isExt = circle.dataset.isExternal === '1';
    if (entityPath) {
      if (typeof openEntityInSplit === 'function') openEntityInSplit(entityPath, nodeName);
      else selectEntity(entityPath);
    } else if (isExt) {
      if (typeof showStatus === 'function') showStatus('参照先トピックが見つかりません: ' + nodeName, true);
    } else {
      const fallbackPath = _entityPath(nodeDbPath || dbPath, nodeName);
      if (typeof openEntityInSplit === 'function') openEntityInSplit(fallbackPath, nodeName);
      else selectEntity(fallbackPath);
    }
  });
  svg.addEventListener('dblclick', (e) => {
    const circle = e.target.closest('circle[data-node-id]');
    if (!circle) return;
    e.stopPropagation();
    const nodeName = circle.dataset.entityName || circle.dataset.nodeId;
    const nodeDbPath = circle.dataset.dbPath || dbPath;
    const isExt = circle.dataset.isExternal === '1';
    const entityPath = circle.dataset.entityPath;
    if (isExt && !entityPath) {
      if (typeof showStatus === 'function') showStatus('参照先トピックが見つかりません: ' + nodeName, true);
      return;
    }
    const resolvedPath = entityPath || _entityPath(nodeDbPath, nodeName);
    if (typeof _navPushWithViewState === 'function') _navPushWithViewState(ctx, nodeName);
    selectEntity(resolvedPath);
  });
}

function _renderGraphForDbPanels(dbPath, preferredCtx) {
  const targets = typeof _dbPaneContextsForPath === 'function'
    ? _dbPaneContextsForPath(dbPath)
    : [preferredCtx || (typeof _currentPaneState === 'function' ? _currentPaneState() : null)].filter(Boolean);
  if (preferredCtx && !targets.includes(preferredCtx)) targets.unshift(preferredCtx);
  (targets.length ? targets : [preferredCtx]).forEach(targetCtx => renderGraph(targetCtx));
}

function _observeGraphResize(container, ctx, initialRect) {
  if (!container || typeof ResizeObserver !== 'function') return;
  if (container._graphResizeTimer) clearTimeout(container._graphResizeTimer);
  if (container._graphResizeObs) container._graphResizeObs.disconnect();
  let resizeTimer = null;
  let lastW = initialRect?.width || container.getBoundingClientRect().width;
  let lastH = initialRect?.height || container.getBoundingClientRect().height;
  container._graphResizeObs = new ResizeObserver(entries => {
    if (!_graphIsActiveView(ctx, container)) {
      _disconnectGraphResizeObserver(container);
      return;
    }
    const entry = entries[0];
    if (!entry) return;
    const newW = entry.contentRect.width;
    const newH = entry.contentRect.height;
    if (Math.abs(newW - lastW) < 2 && Math.abs(newH - lastH) < 2) return;
    lastW = newW;
    lastH = newH;
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => renderGraph(ctx), 200);
    container._graphResizeTimer = resizeTimer;
  });
  container._graphResizeObs.observe(container);
}

function _disconnectGraphResizeObserver(container) {
  if (!container) return;
  if (container._graphResizeTimer) {
    clearTimeout(container._graphResizeTimer);
    container._graphResizeTimer = null;
  }
  if (container._graphResizeObs) {
    container._graphResizeObs.disconnect();
    container._graphResizeObs = null;
  }
}

function _graphIsActiveView(ctx, container) {
  const c = ctx || (typeof _currentPaneState === 'function' ? _currentPaneState() : null);
  const dbPath = c?.dbPath || (typeof state !== 'undefined' ? state.currentDbPath : '');
  if (!dbPath) return false;
  if (typeof _dbCurrentViewModeForContext === 'function') {
    try { return _dbCurrentViewModeForContext(c, dbPath) === 'graph'; } catch {}
  }
  if (typeof getCurrentViewMode === 'function') {
    try { return getCurrentViewMode(dbPath, { ctx: c }) === 'graph'; } catch {}
  }
  if (c && c.viewMode) return c.viewMode === 'graph';
  return !container || container.style.display !== 'none';
}

;

/* === gb-db-validate.js === */
;
/* ==============================
   gb-db-validate.js: 整合性検証エンジン
   DB間の矛盾・不整合をルールベースで自動検出
   ============================== */

/* --- ルール永続化 --- */

function getValidationRules(dbPath) {
  const fid = _pathToFileId(dbPath);
  if (fid) {
    try {
      const v = localStorage.getItem('validationRules:' + fid);
      if (v) {
        const parsed = JSON.parse(v);
        return Array.isArray(parsed) ? parsed : [];
      }
    } catch {}
  }
  try {
    const parsed = JSON.parse(localStorage.getItem('validationRules:' + dbPath));
    return Array.isArray(parsed) ? parsed : [];
  }
  catch { return []; }
}

function setValidationRules(dbPath, rules) {
  const fid = _pathToFileId(dbPath);
  localStorage.setItem('validationRules:' + (fid || dbPath), JSON.stringify(rules));
}

/* --- バリデーション実行 --- */

/**
 * 全ルールを実行し結果を返す
 */
async function runValidation(dbPath, pivotData, propTypes) {
  const savedRules = getValidationRules(dbPath);
  const rules = Array.isArray(savedRules) ? savedRules.filter(r => r && r.enabled !== false) : [];
  if (rules.length === 0) return [];

  const entitiesMap = pivotData.entities || {};
  const entityNames = Object.keys(entitiesMap);
  const results = [];

  for (const rule of rules) {
    let ruleResults = [];
    try {
      switch (rule.type) {
        case 'range_check':
          ruleResults = _validateRangeCheck(rule, entitiesMap, entityNames, dbPath, propTypes);
          break;
        case 'reference_exists':
          ruleResults = await _validateReferenceExists(rule, entitiesMap, entityNames, dbPath, propTypes);
          break;
        case 'cross_db_range':
          ruleResults = await _validateCrossDbRange(rule, entitiesMap, entityNames, dbPath, propTypes);
          break;
        case 'required':
          ruleResults = _validateRequired(rule, entitiesMap, entityNames, dbPath);
          break;
      }
    } catch (e) {
      ruleResults = [{
        ruleId: rule.id, ruleLabel: rule.label || rule.type || '不明なルール', severity: 'error',
        entityName: '(ルール)', entityPath: '',
        message: 'ルール実行に失敗: ' + (e.message || e),
        property: '',
      }];
    }
    results.push(...ruleResults);
  }

  // エラーを先にソート
  results.sort((a, b) => (a.severity === 'error' ? 0 : 1) - (b.severity === 'error' ? 0 : 1));
  return results;
}

/* --- 各バリデーター --- */

function _validationValues(values, options = {}) {
  const list = Array.isArray(values) ? values : [];
  if (options.allStatuses) return list;
  return list.filter(v => {
    const status = v?.status || '採用';
    return status === '採用' || status === '掲載済み';
  });
}

function _validationRelationNames(entityData, relationProperty, ptc) {
  const vals = _validationValues(entityData?.[relationProperty]);
  const names = [];
  vals.forEach(v => {
    if (!v?.value) return;
    if (ptc?.type === 'multi-relation') {
      String(v.value).split(',').forEach(n => { const t = n.trim(); if (t) names.push(t); });
    } else {
      const t = String(v.value).trim();
      if (t) names.push(t);
    }
  });
  return names;
}

function _validationRuleError(rule, message, property = '') {
  return {
    ruleId: rule.id,
    ruleLabel: rule.label || rule.type || '不明なルール',
    severity: 'error',
    entityName: '(ルール)',
    entityPath: '',
    message,
    property,
  };
}

function _validationComparable(rawValue, ptc) {
  const raw = rawValue == null ? '' : String(rawValue).trim();
  if (!raw) return { ok: false, display: raw };
  const type = ptc?.type || '';
  const dateCandidate = type === 'date' || /^\d{4}[-/]\d{2}[-/]\d{2}/.test(raw);
  if (dateCandidate) {
    const parsed = typeof _dbDateParseValue === 'function' ? _dbDateParseValue(raw) : null;
    const dateRaw = parsed?.range ? parsed.start : (parsed?.start || raw);
    const comparable = typeof _dbDateGetComparableValue === 'function' ? _dbDateGetComparableValue(dateRaw) : dateRaw;
    const d = typeof parseLocalDate === 'function' ? parseLocalDate(comparable) : new Date(comparable);
    if (!Number.isNaN(d.getTime())) return { ok: true, value: d.getTime(), display: comparable };
    return { ok: false, display: raw };
  }
  const normalized = raw.replace(/,/g, '');
  if (/^[+-]?(?:\d+|\d*\.\d+)$/.test(normalized)) {
    const n = Number(normalized);
    if (Number.isFinite(n)) return { ok: true, value: n, display: raw };
  }
  if (type === 'number') return { ok: false, display: raw };
  return { ok: true, value: raw, display: raw };
}

function _validationCompare(left, right, operator) {
  const bothNumbers = typeof left === 'number' && typeof right === 'number';
  const cmp = bothNumbers ? (left - right) : String(left).localeCompare(String(right), undefined, { numeric: true, sensitivity: 'base' });
  switch (operator) {
    case '>=': return cmp >= 0;
    case '<=': return cmp <= 0;
    case '>':  return cmp > 0;
    case '<':  return cmp < 0;
    case '==': return bothNumbers ? left === right : String(left) === String(right);
    case '!=': return bothNumbers ? left !== right : String(left) !== String(right);
  }
  return true;
}

function _validateRangeCheck(rule, entitiesMap, entityNames, dbPath, propTypes) {
  const results = [];
  const { property, operator, compareProperty } = rule.config || {};
  if (!property || !operator || !compareProperty) return results;
  const ptc1 = propTypes?.[property];
  const ptc2 = propTypes?.[compareProperty];

  entityNames.forEach(en => {
    const vals1 = _validationValues(entitiesMap[en][property] || [], { allStatuses: true });
    const vals2 = _validationValues(entitiesMap[en][compareProperty] || [], { allStatuses: true });
    if (vals1.length === 0 || vals2.length === 0) return;
    vals1.forEach(val1 => {
      vals2.forEach(val2 => {
        const v1 = _validationComparable(val1.value, ptc1);
        const v2 = _validationComparable(val2.value, ptc2);
        if (!v1.ok || !v2.ok) return;
        const pass = _validationCompare(v1.value, v2.value, operator);
        if (!pass) {
          results.push({
            ruleId: rule.id, ruleLabel: rule.label, severity: 'error',
            entityName: en, entityPath: _entityPath(dbPath, en),
            message: property + '(' + v1.display + ') ' + operator + ' ' + compareProperty + '(' + v2.display + '): 条件不一致',
            property,
          });
        }
      });
    });
  });
  return results;
}

function _buildValidationRelationTargetIndex(targetEntities) {
  const names = new Set();
  const ids = new Map();
  Object.entries(targetEntities || {}).forEach(([name, entity]) => {
    names.add(name);
    const entityId = entity?._id;
    if (entityId) ids.set(String(entityId), name);
  });
  return { names, ids };
}

function _resolveValidationTargetName(rawNameOrId, targetIndex) {
  const token = String(rawNameOrId || '').trim();
  if (!token) return '';
  if (targetIndex.names.has(token)) return token;
  return targetIndex.ids.get(token) || '';
}

async function _validateReferenceExists(rule, entitiesMap, entityNames, dbPath, propTypes) {
  const results = [];
  const { relationProperty } = rule.config || {};
  if (!relationProperty) return results;

  const ptc = propTypes?.[relationProperty];
  if (!ptc) return results;
  // 自己参照: relationDb が未設定または '' の場合は現在のDBを指す
  const _relDb = (ptc.relationDb === '' || ptc.relationDb == null) ? dbPath : ptc.relationDb;
  if (!_relDb) return results;

  const targetData = await fetchRelatedDbData(_relDb);
  if (!targetData || !targetData.entities) {
    return [_validationRuleError(rule, relationProperty + ': 参照先シートを読み込めません: ' + _relDb, relationProperty)];
  }

  const targetIndex = _buildValidationRelationTargetIndex(targetData.entities);

  entityNames.forEach(en => {
    const names = _validationRelationNames(entitiesMap[en], relationProperty, ptc);
    names.forEach(nameOrId => {
      const targetName = _resolveValidationTargetName(nameOrId, targetIndex);
      if (!targetName) {
        results.push({
          ruleId: rule.id, ruleLabel: rule.label, severity: 'error',
          entityName: en, entityPath: _entityPath(dbPath, en),
          message: relationProperty + ': 「' + nameOrId + '」は参照先シートに存在しません',
          property: relationProperty,
        });
      }
    });
  });
  return results;
}

async function _validateCrossDbRange(rule, entitiesMap, entityNames, dbPath, propTypes) {
  const results = [];
  const { property, operator, targetDb, targetProperty, matchRelation } = rule.config || {};
  if (!property || !operator || !targetDb || !targetProperty || !matchRelation) return results;

  const targetData = await fetchRelatedDbData(targetDb);
  if (!targetData || !targetData.entities) {
    return [_validationRuleError(rule, '参照先シートを読み込めません: ' + targetDb, targetProperty)];
  }
  const targetIndex = _buildValidationRelationTargetIndex(targetData.entities);
  const sourcePtc = propTypes?.[property];

  entityNames.forEach(en => {
    const names = _validationRelationNames(entitiesMap[en], matchRelation, propTypes?.[matchRelation]);
    if (names.length === 0) return;

    const vals = _validationValues(entitiesMap[en][property] || []);
    if (vals.length === 0) return;

    names.forEach(targetNameOrId => {
      const targetName = _resolveValidationTargetName(targetNameOrId, targetIndex);
      if (!targetName) {
        results.push({
          ruleId: rule.id, ruleLabel: rule.label, severity: 'error',
          entityName: en, entityPath: _entityPath(dbPath, en),
          message: matchRelation + ': 「' + targetNameOrId + '」は参照先シートに存在しません',
          property: matchRelation,
        });
        return;
      }
      const targetEntity = targetData.entities[targetName];
      if (!targetEntity) return;
      const targetVals = _validationValues(targetEntity[targetProperty] || []);
      if (targetVals.length === 0) return;
      vals.forEach(val1 => {
        targetVals.forEach(val2 => {
          const v1 = _validationComparable(val1.value, sourcePtc);
          const v2 = _validationComparable(val2.value, null);
          if (!v1.ok || !v2.ok) return;
          const pass = _validationCompare(v1.value, v2.value, operator);
          if (!pass) {
            results.push({
              ruleId: rule.id, ruleLabel: rule.label, severity: 'error',
              entityName: en, entityPath: _entityPath(dbPath, en),
              message: property + '(' + v1.display + ') ' + operator + ' ' + targetName + '.' + targetProperty + '(' + v2.display + '): 他シート条件不一致',
              property,
            });
          }
        });
      });
    });
  });
  return results;
}

function _validateRequired(rule, entitiesMap, entityNames, dbPath) {
  const results = [];
  const { property, statusFilter } = rule.config || {};
  if (!property) return results;

  entityNames.forEach(en => {
    // ステータスフィルタ: 対象エントリのみ
    if (statusFilter) {
      const mainStatus = typeof getEntityMainStatus === 'function' ? getEntityMainStatus(entitiesMap[en]) : '';
      if (mainStatus !== statusFilter) return;
    }
    const vals = _validationValues(entitiesMap[en][property] || []);
    const hasValue = vals.some(v => v?.value != null && String(v.value).trim() !== '');
    if (!hasValue) {
      results.push({
        ruleId: rule.id, ruleLabel: rule.label, severity: 'warning',
        entityName: en, entityPath: _entityPath(dbPath, en),
        message: property + ' が空です（' + (statusFilter || '全') + 'トピック）',
        property,
      });
    }
  });
  return results;
}

/* --- UI: 検証結果モーダル --- */

function _validationOpenAfterClose(modalApi, reason, openNext) {
  modalApi.close(reason);
  const continueWhenClosed = () => {
    if (modalApi.overlay.isConnected) {
      setTimeout(continueWhenClosed, 30);
      return;
    }
    openNext();
  };
  continueWhenClosed();
}

function showValidationResults(results, dbPath, dialogFlow) {
  const flow = dialogFlow || { returnFocus: document.activeElement };
  const errors = results.filter(r => r.severity === 'error').length;
  const warnings = results.filter(r => r.severity === 'warning').length;
  const body = document.createElement('div');
  body.className = 'gb-validation-results-content';

  if (results.length === 0) {
    const ok = document.createElement('div');
    ok.style.cssText = 'text-align:center;padding:40px;color:var(--fg2);font-size:14px;';
    ok.textContent = '問題は見つかりませんでした';
    body.appendChild(ok);
  } else {
    const list = document.createElement('div');
    list.className = 'gb-validation-results-list';
    list.style.cssText = 'flex:1;overflow-y:auto;';
    results.forEach(r => {
      const item = document.createElement('div');
      item.className = 'gb-validation-result-item';
      item.style.cssText = 'padding:8px 12px;border-bottom:1px solid var(--bg4);cursor:pointer;';
      item.addEventListener('mouseenter', () => { item.style.background = 'var(--bg4)'; });
      item.addEventListener('mouseleave', () => { item.style.background = ''; });

      const icon = r.severity === 'error'
        ? `<span style="color:var(--red);">${lucide('circleX', 14)}</span>`
        : `<span style="color:#e6a700;">${lucide('circleAlert', 14)}</span>`;
      const header = document.createElement('div');
      header.style.cssText = 'font-size:13px;font-weight:bold;display:flex;align-items:center;gap:4px;';
      header.innerHTML = icon + ' ' + esc(r.entityName) + ' — ' + esc(r.ruleLabel);
      item.appendChild(header);

      const msg = document.createElement('div');
      msg.style.cssText = 'font-size:12px;color:var(--fg2);margin-top:2px;';
      msg.textContent = r.message;
      item.appendChild(msg);

      item.addEventListener('click', () => {
        modalApi.close('select-result');
        if (r.entityPath) selectEntity(r.entityPath);
      });
      list.appendChild(item);
    });
    body.appendChild(list);
  }

  // フッター
  const rulesBtn = document.createElement('button');
  rulesBtn.type = 'button';
  rulesBtn.className = 'gb-btn gb-btn-sm';
  rulesBtn.textContent = 'ルール管理';
  rulesBtn.dataset.e2eId = 'validation-results-rules';
  rulesBtn.addEventListener('click', () => {
    _validationOpenAfterClose(modalApi, 'open-rules', () => showValidationRulesModal(dbPath, flow));
  });
  const closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'gb-btn gb-btn-sm';
  closeBtn.textContent = '閉じる';
  closeBtn.setAttribute('aria-label', '検証結果を閉じる');
  closeBtn.dataset.e2eId = 'validation-results-close';
  closeBtn.addEventListener('click', () => modalApi.close('close-button'));

  const modalApi = window.GBUI.createModal({
    id: 'validation-results-dialog',
    title: '検証結果: ' + errors + ' エラー / ' + warnings + ' 警告',
    body,
    footer: [rulesBtn, closeBtn],
    variant: 'standard',
    extraClass: 'gb-validation-results-modal',
    geometryKey: 'validation-results',
    initialFocus: '[data-e2e-id="validation-results-close"]',
    returnFocus: () => flow.returnFocus,
  });
  modalApi.overlay.classList.add('modal-overlay');
  modalApi.overlay._validationModalApi = modalApi;
  modalApi.modal.classList.add('modal');
  modalApi.modal.dataset.e2eId = 'validation-results-dialog';
  modalApi.footer.classList.add('gb-validation-footer');
  modalApi.open();
}

/* --- UI: ルール管理モーダル --- */

function showValidationRulesModal(dbPath, dialogFlow) {
  const flow = dialogFlow || { returnFocus: document.activeElement };

  const rules = getValidationRules(dbPath);
  const list = document.createElement('div');
  list.className = 'gb-validation-rules-list';
  list.style.cssText = 'flex:1;overflow-y:auto;';

  if (rules.length === 0) {
    list.innerHTML = '<div style="padding:20px;text-align:center;color:var(--fg2);">ルールなし</div>';
  } else {
    rules.forEach((rule, i) => {
      const item = document.createElement('div');
      item.className = 'gb-validation-rule-row';
      item.style.cssText = 'display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--bg4);';

      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.className = 'gb-validation-rule-check';
      cb.dataset.e2eId = 'validation-rule-' + (rule.id || i) + '-enabled';
      cb.setAttribute('aria-label', (rule.label || rule.type || 'ルール') + 'を有効化');
      cb.checked = rule.enabled !== false;
      cb.addEventListener('change', () => {
        rules[i].enabled = cb.checked;
        setValidationRules(dbPath, rules);
      });
      item.appendChild(cb);

      const label = document.createElement('span');
      label.className = 'gb-validation-rule-label';
      label.style.cssText = 'flex:1;font-size:13px;';
      label.textContent = rule.label || rule.type;
      item.appendChild(label);

      const typeBadge = document.createElement('span');
      typeBadge.className = 'gb-validation-rule-type';
      typeBadge.style.cssText = 'font-size:10px;background:var(--bg4);padding:1px 6px;border-radius:8px;color:var(--fg2);';
      typeBadge.textContent = rule.type;
      item.appendChild(typeBadge);

      const editBtn = document.createElement('button');
      editBtn.type = 'button';
      editBtn.className = 'gb-btn gb-btn-xs';
      editBtn.textContent = '編集';
      editBtn.dataset.e2eId = 'validation-rule-' + (rule.id || i) + '-edit';
      editBtn.setAttribute('aria-label', (rule.label || rule.type || 'ルール') + 'を編集');
      editBtn.style.cssText = 'font-size:11px;padding:1px 6px;';
      editBtn.addEventListener('click', () => {
        _validationOpenAfterClose(modalApi, 'edit-rule', () => {
          showValidationRuleEditor(dbPath, { ...rule, config: { ...(rule.config || {}) } }, flow);
        });
      });
      item.appendChild(editBtn);

      const delBtn = document.createElement('button');
      delBtn.type = 'button';
      delBtn.className = 'gb-btn gb-btn-xs gb-btn-danger';
      delBtn.textContent = '削除';
      delBtn.dataset.e2eId = 'validation-rule-' + (rule.id || i) + '-delete';
      delBtn.setAttribute('aria-label', (rule.label || rule.type || 'ルール') + 'を削除');
      delBtn.style.cssText = 'font-size:11px;padding:1px 6px;';
      delBtn.addEventListener('click', async () => {
        const ok = typeof cfConfirm === 'function'
          ? await cfConfirm('この検証ルールを削除しますか？', { danger: true, okLabel: '削除' })
          : (typeof confirm === 'function' ? confirm('この検証ルールを削除しますか？') : true);
        if (!ok) return;
        rules.splice(i, 1);
        setValidationRules(dbPath, rules);
        _validationOpenAfterClose(modalApi, 'delete-rule', () => showValidationRulesModal(dbPath, flow));
      });
      item.appendChild(delBtn);

      list.appendChild(item);
    });
  }

  // 新規ルール追加
  const addBtn = document.createElement('button');
  addBtn.type = 'button';
  addBtn.className = 'gb-btn gb-btn-sm gb-btn-primary';
  addBtn.textContent = '+ 新規ルール';
  addBtn.dataset.e2eId = 'validation-add-rule';
  addBtn.addEventListener('click', () => {
    _validationOpenAfterClose(modalApi, 'add-rule', () => showValidationRuleEditor(dbPath, null, flow));
  });
  const closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'gb-btn gb-btn-sm';
  closeBtn.textContent = '閉じる';
  closeBtn.setAttribute('aria-label', 'ルール管理を閉じる');
  closeBtn.dataset.e2eId = 'validation-rules-close';
  closeBtn.addEventListener('click', () => modalApi.close('close-button'));

  const modalApi = window.GBUI.createModal({
    id: 'validation-rules-dialog',
    title: 'バリデーションルール',
    body: list,
    footer: [addBtn, closeBtn],
    variant: 'standard',
    extraClass: 'gb-validation-rules-modal',
    geometryKey: 'validation-rules',
    initialFocus: '[data-e2e-id="validation-add-rule"]',
    returnFocus: () => flow.returnFocus,
  });
  modalApi.overlay.classList.add('modal-overlay');
  modalApi.overlay._validationModalApi = modalApi;
  modalApi.modal.classList.add('modal');
  modalApi.modal.dataset.e2eId = 'validation-rules-dialog';
  modalApi.footer.classList.add('gb-validation-footer');
  modalApi.open();
}

/* --- UI: ルール編集モーダル --- */

function showValidationRuleEditor(dbPath, existingRule, dialogFlow) {
  const flow = dialogFlow || { returnFocus: document.activeElement };
  const rule = existingRule || { id: 'rule-' + Date.now(), type: 'range_check', label: '', enabled: true, config: {} };
  const body = document.createElement('div');
  body.className = 'gb-validation-editor-content';

  // ルール名
  const nameField = document.createElement('div');
  nameField.className = 'field';
  nameField.innerHTML = '<label>ルール名</label>';
  const nameInput = document.createElement('input');
  nameInput.type = 'text';
  nameInput.id = 'vr-rule-name';
  nameInput.dataset.e2eId = 'validation-editor-name';
  nameInput.value = rule.label;
  nameInput.placeholder = '例: 回収話 >= 仕込み話';
  nameField.appendChild(nameInput);
  body.appendChild(nameField);

  // ルールタイプ
  const typeField = document.createElement('div');
  typeField.className = 'field';
  typeField.innerHTML = '<label>タイプ</label>';
  const typeSel = document.createElement('select');
  typeSel.id = 'vr-rule-type';
  typeSel.dataset.e2eId = 'validation-editor-type';
  typeSel.setAttribute('aria-label', 'バリデーションルールタイプ');
  [
    { key: 'range_check', label: '列間の比較' },
    { key: 'reference_exists', label: 'リレーション先の存在確認' },
    { key: 'cross_db_range', label: '他シートの列との比較' },
    { key: 'required', label: '必須列' },
  ].forEach(opt => {
    const o = document.createElement('option');
    o.value = opt.key; o.textContent = opt.label;
    if (opt.key === rule.type) o.selected = true;
    typeSel.appendChild(o);
  });
  typeField.appendChild(typeSel);
  body.appendChild(typeField);

  // 設定エリア
  const configDiv = document.createElement('div');
  configDiv.id = 'vr-config';
  body.appendChild(configDiv);

  const props = state.pivotData ? state.pivotData.properties : [];
  const operators = [
    { key: '>=', label: '>=' }, { key: '<=', label: '<=' },
    { key: '>', label: '>' }, { key: '<', label: '<' },
    { key: '==', label: '==' }, { key: '!=', label: '!=' },
  ];

  function renderConfig() {
    const type = typeSel.value;
    configDiv.innerHTML = '';
    if (type === 'range_check') {
      configDiv.innerHTML = _fieldSelect('列1', 'vr-prop1', props, rule.config.property) +
        _fieldSelect('比較演算子', 'vr-op', operators.map(o => o.key), rule.config.operator) +
        _fieldSelect('列2', 'vr-prop2', props, rule.config.compareProperty);
    } else if (type === 'reference_exists') {
      const relProps = props.filter(p => { const pt = getPropertyTypes(dbPath)?.[p]; return pt && (pt.type === 'relation' || pt.type === 'multi-relation'); });
      configDiv.innerHTML = _fieldSelect('リレーション列', 'vr-relprop', relProps, rule.config.relationProperty);
    } else if (type === 'cross_db_range') {
      configDiv.innerHTML = _fieldSelect('列', 'vr-prop1', props, rule.config.property) +
        _fieldSelect('演算子', 'vr-op', operators.map(o => o.key), rule.config.operator) +
        '<div class="field"><label>参照先シートパス</label><input id="vr-targetdb" type="text" value="' + esc(rule.config.targetDb || '') + '" placeholder="例: ストーリー/アーク"></div>' +
        '<div class="field"><label>参照先の列</label><input id="vr-targetprop" type="text" value="' + esc(rule.config.targetProperty || '') + '"></div>' +
        _fieldSelect('マッチリレーション', 'vr-matchrel', props, rule.config.matchRelation);
    } else if (type === 'required') {
      configDiv.innerHTML = _fieldSelect('列', 'vr-prop1', props, rule.config.property) +
        '<div class="field"><label>対象ステータス（空=全て）</label><input id="vr-status" type="text" value="' + esc(rule.config.statusFilter || '') + '" placeholder="例: 採用"></div>';
    }
  }
  typeSel.addEventListener('change', renderConfig);
  renderConfig();

  // ボタン
  const cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'gb-btn gb-btn-sm';
  cancelBtn.textContent = 'キャンセル';
  cancelBtn.dataset.e2eId = 'validation-editor-cancel';
  cancelBtn.addEventListener('click', () => {
    _validationOpenAfterClose(modalApi, 'cancel', () => showValidationRulesModal(dbPath, flow));
  });
  const saveBtn = document.createElement('button');
  saveBtn.type = 'button';
  saveBtn.textContent = '保存';
  saveBtn.className = 'gb-btn gb-btn-sm gb-btn-primary primary';
  saveBtn.dataset.e2eId = 'validation-editor-save';
  saveBtn.addEventListener('click', () => {
    rule.label = nameInput.value.trim();
    rule.type = typeSel.value;
    rule.config = _collectRuleConfig(rule.type);
    const errors = _validationRuleConfigErrors(rule.type, rule.config, rule.label);
    if (errors.length) {
      if (typeof showStatus === 'function') showStatus(errors[0], true);
      return;
    }
    const rules = getValidationRules(dbPath);
    const idx = rules.findIndex(r => r.id === rule.id);
    if (idx >= 0) rules[idx] = rule; else rules.push(rule);
    setValidationRules(dbPath, rules);
    _validationOpenAfterClose(modalApi, 'save', () => showValidationRulesModal(dbPath, flow));
    showStatus('ルールを保存しました');
  });

  const modalApi = window.GBUI.createModal({
    id: 'validation-rule-editor-dialog',
    title: existingRule ? 'ルール編集' : '新規ルール',
    body,
    footer: [cancelBtn, saveBtn],
    variant: 'standard',
    extraClass: 'gb-validation-rule-editor',
    geometryKey: 'validation-rule-editor',
    initialFocus: '#vr-rule-name',
    returnFocus: () => flow.returnFocus,
  });
  modalApi.overlay.classList.add('modal-overlay');
  modalApi.overlay._validationModalApi = modalApi;
  modalApi.overlay.style.zIndex = '130';
  modalApi.modal.classList.add('modal');
  modalApi.modal.dataset.e2eId = 'validation-rule-editor-dialog';
  modalApi.footer.classList.add('gb-validation-footer', 'gb-validation-editor-footer');
  modalApi.open();
}

function _validationRuleConfigErrors(type, config, label) {
  const cfg = config || {};
  const errors = [];
  if (!String(label || '').trim()) errors.push('ルール名を入力してください');
  if (type === 'range_check') {
    if (!cfg.property) errors.push('列1を選択してください');
    if (!cfg.operator) errors.push('比較演算子を選択してください');
    if (!cfg.compareProperty) errors.push('列2を選択してください');
  } else if (type === 'reference_exists') {
    if (!cfg.relationProperty) errors.push('リレーション列を選択してください');
  } else if (type === 'cross_db_range') {
    if (!cfg.property) errors.push('列を選択してください');
    if (!cfg.operator) errors.push('演算子を選択してください');
    if (!String(cfg.targetDb || '').trim()) errors.push('参照先シートパスを入力してください');
    if (!String(cfg.targetProperty || '').trim()) errors.push('参照先の列を入力してください');
    if (!cfg.matchRelation) errors.push('マッチリレーションを選択してください');
  } else if (type === 'required') {
    if (!cfg.property) errors.push('列を選択してください');
  }
  return errors;
}

function _fieldSelect(label, id, options, selected) {
  let html = '<div class="field"><label>' + esc(label) + '</label><select id="' + id + '">';
  html += '<option value="">選択...</option>';
  options.forEach(o => {
    const val = typeof o === 'string' ? o : (o.key || String(o));
    html += '<option value="' + esc(val) + '"' + (val === selected ? ' selected' : '') + '>' + esc(val) + '</option>';
  });
  html += '</select></div>';
  return html;
}

function _collectRuleConfig(type) {
  if (type === 'range_check') {
    return {
      property: document.getElementById('vr-prop1')?.value || '',
      operator: document.getElementById('vr-op')?.value || '>=',
      compareProperty: document.getElementById('vr-prop2')?.value || '',
    };
  } else if (type === 'reference_exists') {
    return { relationProperty: document.getElementById('vr-relprop')?.value || '' };
  } else if (type === 'cross_db_range') {
    return {
      property: document.getElementById('vr-prop1')?.value || '',
      operator: document.getElementById('vr-op')?.value || '>=',
      targetDb: (document.getElementById('vr-targetdb')?.value || '').trim(),
      targetProperty: (document.getElementById('vr-targetprop')?.value || '').trim(),
      matchRelation: document.getElementById('vr-matchrel')?.value || '',
    };
  } else if (type === 'required') {
    return {
      property: document.getElementById('vr-prop1')?.value || '',
      statusFilter: (document.getElementById('vr-status')?.value || '').trim(),
    };
  }
  return {};
}

/* --- ツールバーハンドラ --- */

async function onValidateClick() {
  const dbPath = state.currentDbPath;
  if (!dbPath || !state.pivotData) { showStatus('シートを選択してください', true); return; }
  showStatus('検証中...');
  const propTypes = getPropertyTypes(dbPath);
  let validationData = state.pivotData;
  try {
    validationData = await apiFetch('/pivot?path=' + encodeURIComponent(dbPath));
  } catch (e) {
    showStatus('検証データの取得に失敗: ' + (e.message || e), true);
    return;
  }
  const results = await runValidation(dbPath, validationData, propTypes);
  showValidationResults(results, dbPath);
  const errorCount = results.filter(r => r.severity === 'error').length;
  const warningCount = results.filter(r => r.severity === 'warning').length;
  if (errorCount > 0) showStatus(errorCount + '件のエラーを検出');
  else if (warningCount > 0) showStatus(warningCount + '件の警告を検出');
  else showStatus('検証完了 — 問題なし');
}

;

/* === gb-db-actions.js === */
;
/* ==============================
   gb-db-actions.js: DBアクションボタン + バックリンク集約表示
   依存: gb-database.js, gb-editor.js, meldex-core.js
   ============================== */

function _padDbActionDatePart(n) {
  return String(n).padStart(2, '0');
}

function _formatDbActionDate(date, includeTime) {
  const d = date instanceof Date ? date : new Date(date);
  if (isNaN(d.getTime())) return '';
  const base = `${d.getFullYear()}-${_padDbActionDatePart(d.getMonth() + 1)}-${_padDbActionDatePart(d.getDate())}`;
  if (!includeTime) return base;
  return `${base}T${_padDbActionDatePart(d.getHours())}:${_padDbActionDatePart(d.getMinutes())}:${_padDbActionDatePart(d.getSeconds())}`;
}

// === テンプレート変数展開 ===
function _expandTemplate(template, entryName, properties) {
  if (!template || typeof template !== 'string') return template || '';
  const propMap = properties && typeof properties === 'object' ? properties : {};
  const propNames = Object.keys(propMap).sort((a, b) => b.length - a.length);
  const propValue = (propName) => {
    const vals = propMap[propName];
    if (!Array.isArray(vals)) return '';
    const adopted = vals.find(v => v.status === '採用' || v.status === '掲載済み');
    const picked = adopted || vals[0];
    return picked?.value == null ? '' : String(picked.value);
  };
  let result = '';
  for (let i = 0; i < template.length;) {
    if (template[i] !== '$') {
      result += template[i++];
      continue;
    }
    if (template.startsWith('$entry_name', i)) { result += entryName || ''; i += '$entry_name'.length; continue; }
    if (template.startsWith('$user', i)) { result += typeof getUsername === 'function' ? getUsername() : 'anonymous'; i += '$user'.length; continue; }
    if (template.startsWith('$today', i)) { result += _formatDbActionDate(new Date(), false); i += '$today'.length; continue; }
    if (template.startsWith('$now', i)) { result += _formatDbActionDate(new Date(), true); i += '$now'.length; continue; }
    if (template.startsWith('$prop:', i)) {
      const start = i + '$prop:'.length;
      let end = start;
      while (end < template.length && template[end] !== '$' && !/\s/.test(template[end])) end++;
      const token = template.slice(start, end);
      const propName = propNames.find(name => token === name || token.startsWith(name));
      if (propName) {
        result += propValue(propName) + token.slice(propName.length);
      }
      i = end;
      continue;
    }
    result += template[i++];
  }
  return result;
}

function _safeDbActionIconName(iconName) {
  const name = String(iconName || '').trim();
  return /^[A-Za-z][A-Za-z0-9-]{0,48}$/.test(name) ? name : '';
}

function _dbActionValueTarget(path) {
  return String(path || '').toLowerCase().endsWith('.md')
    ? { entry_path: path }
    : { folder_path: path };
}

function _normalizeDbActionPath(path) {
  const parts = String(path || '').replace(/\\/g, '/').split('/');
  const out = [];
  parts.forEach(part => {
    if (!part || part === '.') return;
    if (part === '..') out.pop();
    else out.push(part);
  });
  return out.join('/');
}

function _resolveDbActionRelativePath(baseDbPath, relativePath) {
  const raw = String(relativePath || '').trim().replace(/\\/g, '/');
  if (!raw) return String(baseDbPath || '');
  if (/^[A-Za-z]:\//.test(raw) || raw.startsWith('/')) return raw;
  const dbPath = String(baseDbPath || '').replace(/\\/g, '/').replace(/\/+$/, '');
  const dbParent = dbPath.replace(/\/[^/]*$/, '');
  const base = raw.startsWith('./') || raw.startsWith('../') ? dbPath : dbParent;
  return _normalizeDbActionPath((base ? base + '/' : '') + raw);
}

function _dbActionBaseDbPath(entityPath) {
  if (typeof _dbPathFromEntityPath === 'function') {
    const fromEntityPath = _dbPathFromEntityPath(entityPath);
    if (fromEntityPath) return fromEntityPath;
  }
  const fallbackEntity = state.currentEntityPath || '';
  if (fallbackEntity && typeof _dbPathFromEntityPath === 'function') {
    const fromCurrentEntity = _dbPathFromEntityPath(fallbackEntity);
    if (fromCurrentEntity) return fromCurrentEntity;
  }
  return state.currentDbPath || '';
}

async function _getDbActionMetadata(dbPath) {
  if (!dbPath) return { actions: [], backlinks: [] };
  if (state.currentDbPath === dbPath && state.dbMetadata) return state.dbMetadata;
  try {
    return await apiFetch('/db-metadata?path=' + encodeURIComponent(dbPath));
  } catch {
    return { actions: [], backlinks: [] };
  }
}

async function _refreshDbActionPanels(dbPath, preferredCtx = null) {
  if (!dbPath || typeof selectDatabase !== 'function') return;
  const targets = [];
  const add = (ctx) => {
    if (!ctx || targets.includes(ctx)) return;
    if (!ctx.dbPath || ctx.dbPath === dbPath) targets.push(ctx);
  };
  add(preferredCtx);
  if (typeof getAllPanes === 'function') {
    try {
      Object.values(getAllPanes() || {}).forEach(ctx => {
        if (ctx?.dbPath === dbPath) add(ctx);
      });
    } catch {}
  }
  if (state.currentDbPath === dbPath) add(typeof _currentPaneState === 'function' ? _currentPaneState() : null);
  if (!targets.length && state.currentDbPath === dbPath) {
    await selectDatabase(dbPath, undefined, { silent: true });
    return;
  }
  for (const ctx of targets) {
    await selectDatabase(dbPath, ctx, { silent: true });
  }
}

let _dbActionModalSeq = 0;

function _dbActionFocusTrigger(triggerEl) {
  try { triggerEl?.focus?.({ preventScroll: true }); } catch { triggerEl?.focus?.(); }
}

// === エントリ詳細にアクションボタンを表示 ===
async function _renderEntityActions(data, entityPath) {
  const container = document.getElementById('entity-freetext');
  if (!container) return;
  container.parentElement.querySelector('.db-action-bar')?.remove();

  const dbPath = _dbActionBaseDbPath(entityPath);
  const meta = await _getDbActionMetadata(dbPath);
  if (state.currentEntityPath && state.currentEntityPath !== entityPath) return;
  if (!meta || !meta.actions || meta.actions.length === 0) return;

  let bar = container.parentElement.querySelector('.db-action-bar');
  bar = document.createElement('div');
  bar.className = 'db-action-bar';
  bar.style.cssText = 'padding:8px 0;display:flex;gap:8px;flex-wrap:wrap;';

  meta.actions.forEach((action, actionIndex) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'db-action-btn';
    btn.dataset.e2eId = `entity-db-action-${actionIndex}`;
    btn.setAttribute('aria-label', (action.label || 'アクション') + 'を実行');
    btn.title = action.label || 'アクション';
    const safeIcon = _safeDbActionIconName(action.icon);
    if (safeIcon && typeof lucide === 'function') btn.innerHTML = lucide(safeIcon, 14);
    const label = document.createElement('span');
    label.textContent = action.label || 'アクション';
    btn.appendChild(label);
    btn.addEventListener('click', () => _showDbActionModal(action, data, entityPath, btn));
    bar.appendChild(btn);
  });

  container.parentElement.insertBefore(bar, container);
}

// === アクションモーダル表示 ===
function _showDbActionModal(action, data, entityPath, triggerEl = null) {
  const entryName = data.entity || '';
  const properties = data.properties || {};
  const seq = ++_dbActionModalSeq;
  const descId = `db-action-modal-desc-${seq}`;

  let html = `<p id="${descId}" style="margin:0 0 12px;color:var(--fg2);font-size:12px;">必要な項目を入力して実行してください。</p>`;

  // エントリ本文（操作手順等）をプレビュー表示
  if (data.page_content) {
    html += `<div style="background:var(--bg2);border:1px solid var(--border);border-radius:4px;padding:8px;margin-bottom:12px;font-size:13px;max-height:200px;overflow-y:auto;">${mdToHtml(data.page_content)}</div>`;
  }

  // auto_copy のプレビュー
  if (action.auto_copy) {
    html += '<div style="font-size:12px;color:var(--fg2);margin-bottom:8px;">自動コピー項目:</div>';
    html += '<table style="font-size:12px;width:100%;margin-bottom:12px;">';
    for (const [key, tmpl] of Object.entries(action.auto_copy)) {
      const val = _expandTemplate(tmpl, entryName, properties);
      html += `<tr><td style="padding:2px 8px 2px 0;color:var(--fg2);">${esc(key)}</td><td>${esc(val)}</td></tr>`;
    }
    html += '</table>';
  }

  // input_fields
  if (action.input_fields && action.input_fields.length > 0) {
    html += '<div style="font-size:12px;color:var(--fg2);margin-bottom:4px;">入力項目:</div>';
    action.input_fields.forEach((field, i) => {
      const fieldId = `db-action-field-${seq}-${i}`;
      html += `<div style="margin-bottom:8px;"><label for="${fieldId}" style="font-size:12px;color:var(--fg2);">${esc(field.property)}${field.required ? ' *' : ''}</label>`;
      if (field.type === 'select' && field.options) {
        html += `<select id="${fieldId}" data-field-index="${i}" data-e2e-id="db-action-field-${i}" class="gb-select" style="width:100%;">`;
        html += '<option value="">-- 選択 --</option>';
        field.options.forEach(opt => { html += `<option value="${esc(opt)}">${esc(opt)}</option>`; });
        html += '</select>';
      } else {
        html += `<input id="${fieldId}" data-field-index="${i}" data-e2e-id="db-action-field-${i}" type="text" class="gb-input" placeholder="${esc(field.placeholder || '')}" style="width:100%;box-sizing:border-box;">`;
      }
      html += '</div>';
    });
  }

  const body = document.createElement('div');
  body.innerHTML = html;
  const cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'gb-btn gb-btn-sm modal-cancel';
  cancelBtn.dataset.e2eId = 'db-action-modal-cancel';
  cancelBtn.textContent = 'キャンセル';
  const execBtn = document.createElement('button');
  execBtn.type = 'button';
  execBtn.className = 'gb-btn gb-btn-sm gb-btn-primary primary modal-exec';
  execBtn.dataset.e2eId = 'db-action-modal-exec';
  execBtn.textContent = '実行';
  let busy = false;
  const modalApi = window.GBUI.createModal({
    id: `db-action-dialog-${seq}`,
    title: action.label || 'アクション実行',
    body,
    footer: [cancelBtn, execBtn],
    variant: 'standard',
    extraClass: 'db-action-modal',
    geometryKey: 'db-action',
    initialFocus: '[data-field-index="0"], [data-e2e-id="db-action-modal-exec"]',
    returnFocus: triggerEl || undefined,
    onBeforeClose: reason => !busy || reason === 'complete' || reason === 'superseded',
    onClose: () => _dbActionFocusTrigger(triggerEl),
  });
  const el = modalApi.overlay;
  el.classList.add('modal-overlay');
  el.dataset.dbActionModal = '1';
  modalApi.modal.style.width = 'min(500px, calc(100vw - 32px))';
  modalApi.modal.style.maxWidth = 'calc(100vw - 32px)';
  modalApi.modal.setAttribute('aria-describedby', descId);
  const closeBtn = modalApi.header.querySelector('.gb-modal-close');
  if (closeBtn) closeBtn.dataset.e2eId = 'db-action-modal-close-icon';
  cancelBtn.addEventListener('click', () => modalApi.close('cancel'));
  modalApi.open();

  execBtn.addEventListener('click', async () => {
    if (busy) return;
    // バリデーション
    const inputValues = {};
    if (action.input_fields) {
      for (let i = 0; i < action.input_fields.length; i++) {
        const field = action.input_fields[i];
        const input = el.querySelector('[data-field-index="' + i + '"]');
        const val = input ? input.value.trim() : '';
        if (field.required && !val) {
          showStatus(field.property + ' は必須です', true);
          input?.focus();
          return;
        }
        inputValues[field.property] = val;
      }
    }
    busy = true;
    cancelBtn.disabled = true;
    execBtn.disabled = true;
    if (closeBtn) closeBtn.disabled = true;
    try {
      await _executeDbAction(action, data, entityPath, inputValues);
      modalApi.close('complete');
    } finally {
      busy = false;
      if (modalApi.isOpen()) {
        cancelBtn.disabled = false;
        execBtn.disabled = false;
        if (closeBtn) closeBtn.disabled = false;
      }
    }
  });
}

// === アクション実行 ===
async function _executeDbAction(action, data, entityPath, inputValues) {
  const entryName = data.entity || '';
  const properties = data.properties || {};

  // target_db パス解決（現在のDB相対）
  const dbPath = _dbActionBaseDbPath(entityPath);
  const targetDb = _resolveDbActionRelativePath(dbPath, action.target_db || '');

  // エントリ名テンプレート展開 + サニタイズ
  let newEntryName = _expandTemplate(action.entry_name || entryName, entryName, properties);
  newEntryName = newEntryName.replace(/[\\/:*?"<>|]/g, '_');
  const valueWrites = [];
  if (action.auto_copy) {
    for (const [propName, tmpl] of Object.entries(action.auto_copy)) {
      const val = _expandTemplate(tmpl, entryName, properties);
      if (val) valueWrites.push({ property: propName, value: val });
    }
  }
  for (const [propName, val] of Object.entries(inputValues || {})) {
    if (val) valueWrites.push({ property: propName, value: val });
  }

  let newEntityPath = '';
  try {
    // エントリ作成
    const created = await apiPost('/entity/create', { parent_path: targetDb, name: newEntryName });

    // auto_copy プロパティ設定
    // /api/value は entry_path (新形式 .md) または folder_path (旧形式) を期待する。
    // create_entity は新旧形式どちらでも path を返す。未返却時だけ従来推定にフォールバックする。
    newEntityPath = (created && (created.path || created.entry_path))
      || (targetDb + '/' + newEntryName + '.md');
    // §12.1 Phase 0: autoFillOnCreate 適用（R8: auto_copy で指定されるプロパティはスキップ）
    if (typeof _autoFillOnCreate === 'function'
        && (typeof _shouldRunFrontendAutoFillOnCreate !== 'function' || _shouldRunFrontendAutoFillOnCreate(created))) {
      const overrides = {};
      for (const k of Object.keys(action.auto_copy || {})) overrides[k] = true;
      try { await _autoFillOnCreate(targetDb, newEntityPath, overrides); } catch {}
    }
    // auto_copy / input_fields プロパティ設定
    for (const item of valueWrites) {
      await apiPost('/value', { ..._dbActionValueTarget(newEntityPath), property: item.property, value: item.value, status: '採用', note: '' });
    }

    showStatus((action.label || 'アクション') + ' 完了: ' + newEntryName);
    await _refreshDbActionPanels(targetDb);
  } catch (e) {
    if (newEntityPath) {
      try { await apiPost('/outliner/delete', { path: newEntityPath }); } catch {}
    }
    showStatus('アクション失敗: ' + (e.message || e), true);
  }
}

// === エントリ詳細にバックリンク表示 ===
async function _renderEntityBacklinks(data, entityPath) {
  const container = document.getElementById('entity-freetext');
  if (!container) return;
  const parent = container.parentElement;

  // 既存のバックリンクセクションを除去
  parent.querySelectorAll('.db-backlinks-section').forEach(s => s.remove());

  const dbPath = _dbActionBaseDbPath(entityPath);
  const meta = await _getDbActionMetadata(dbPath);
  if (state.currentEntityPath && state.currentEntityPath !== entityPath) return;
  if (!meta || !meta.backlinks || meta.backlinks.length === 0) return;

  const entryName = data.entity || '';
  const properties = data.properties || {};

  for (const bl of meta.backlinks) {
    const sourceDb = _resolveDbActionRelativePath(dbPath, bl.source_db || '');
    const matchValue = _expandTemplate(bl.match_value || '', entryName, properties);

    try {
      const result = await apiFetch('/backlinks?source_db=' + encodeURIComponent(sourceDb)
        + '&match_property=' + encodeURIComponent(bl.match_property || '')
        + '&match_value=' + encodeURIComponent(matchValue));

      // エントリが切り替わっていたら描画をスキップ（race condition防止）
      if (state.currentEntityPath !== entityPath) return;

      const section = document.createElement('div');
      section.className = 'db-backlinks-section';
      section.style.cssText = 'margin-top:12px;border-top:1px solid var(--border);padding-top:8px;';

      const entries = Array.isArray(result?.entries) ? result.entries : [];
      let header = `<div style="font-size:13px;font-weight:bold;color:var(--fg2);margin-bottom:6px;">${esc(bl.label || 'バックリンク')} (${entries.length})</div>`;
      section.innerHTML = header;

      if (entries.length === 0) {
        section.innerHTML += '<div style="font-size:12px;color:var(--fg2);padding:4px 0;">(なし)</div>';
      } else {
        const displayProps = bl.display_properties || [];
        let tableHtml = '<table style="font-size:12px;width:100%;border-collapse:collapse;">';
        tableHtml += '<thead><tr>';
        displayProps.forEach(p => { tableHtml += `<th style="text-align:left;padding:3px 6px;border-bottom:1px solid var(--border);color:var(--fg2);">${esc(p)}</th>`; });
        tableHtml += '</tr></thead><tbody>';
        entries.forEach(entry => {
          tableHtml += '<tr>';
          displayProps.forEach(p => {
            tableHtml += `<td style="padding:3px 6px;border-bottom:1px solid var(--border);">${esc(entry[p] || '')}</td>`;
          });
          tableHtml += '</tr>';
        });
        tableHtml += '</tbody></table>';
        section.innerHTML += tableHtml;
      }

      parent.appendChild(section);
    } catch (e) { console.warn('backlinks fetch failed:', bl.source_db, e); }
  }
}

// === ピボットにバックリンク集約列を追加 ===
async function _appendBacklinkSummaryColumns(ctx) {
  const dbPath = ctx?.dbPath || state.currentDbPath || '';
  const meta = ctx?.dbMetadata || await _getDbActionMetadata(dbPath);
  if (!meta || !meta.backlinks) return;

  const backlinkDefs = meta.backlinks.filter(bl => bl.summary_property);
  if (backlinkDefs.length === 0) return;

  const tableId = ctx?.tableId || 'pivot-table';
  const table = _paneEl(ctx, '#' + tableId) || (!ctx ? document.getElementById('pivot-table') : null);
  if (!table) return;
  const renderToken = ctx?._renderToken;
  table.querySelectorAll('[data-backlink-summary="true"]').forEach(el => el.remove());

  for (const bl of backlinkDefs) {
    const sourceDb = _resolveDbActionRelativePath(dbPath, bl.source_db || '');
    try {
      const result = await apiFetch('/backlinks/summary?source_db=' + encodeURIComponent(sourceDb)
        + '&match_property=' + encodeURIComponent(bl.match_property || '')
        + '&summary_property=' + encodeURIComponent(bl.summary_property || ''));
      if (ctx && renderToken && ctx._renderToken !== renderToken) return;

      const summary = result.summary || {};
      // ピボットテーブルに列を追加
      // ヘッダーに列追加
      const thead = table.querySelector('thead tr');
      if (!thead) continue;
      const th = document.createElement('th');
      th.dataset.backlinkSummary = 'true';
      th.textContent = bl.label || bl.summary_property;
      th.style.cssText = 'padding:4px 8px;font-size:12px;white-space:nowrap;';
      thead.appendChild(th);

      // 各行に集約データ追加
      const rows = table.querySelectorAll('tbody tr[data-entity-name]');
      rows.forEach(row => {
        const nameCell = row.querySelector('.entity-name-label');
        const entityName = nameCell ? nameCell.textContent.trim() : '';
        const td = document.createElement('td');
        td.dataset.backlinkSummary = 'true';
        td.style.cssText = 'padding:4px 8px;font-size:12px;';
        const counts = summary[entityName];
        if (counts) {
          td.innerHTML = Object.entries(counts)
            .map(([val, cnt]) => `<span style="margin-right:6px;">${esc(val)}:${cnt}</span>`)
            .join('');
        } else {
          td.innerHTML = '<span style="color:var(--fg2);">(未着手)</span>';
        }
        row.appendChild(td);
      });

      // tfoot にも空セル追加
      const tfoot = table.querySelector('tfoot tr');
      if (tfoot) {
        const td = document.createElement('td');
        td.dataset.backlinkSummary = 'true';
        td.style.cssText = 'padding:4px 8px;';
        tfoot.appendChild(td);
      }
    } catch (e) { console.warn('backlink summary failed:', bl.source_db, e); }
  }
}

;

/* === gb-db-search.js === */
;
/* ==============================
   gb-db-search.js: シート横断キーワード検索
   全シートのエントリ名+プロパティ値をフリーワードで横断検索
   ============================== */

/**
 * シート横断検索を実行する
 * @param {string} query - 検索キーワード
 * @param {string} scope - 特定シートパス（空=全シート）
 * @returns {Promise<object>} シート検索レスポンス
 */
async function doDbSearch(query, scope) {
  if (!query) return { entities: [] };
  const params = new URLSearchParams({ q: query });
  if (scope) {
    params.set('scope', scope);
  }
  return await apiFetch('/sheet-search?' + params.toString());
}

/* --- 現在のシート内検索/置換バー --- */

let _dbFindState = {
  bar: null,
  ctx: null,
  dbPath: '',
  query: '',
  matches: [],
  index: -1,
};

function _dbFindCssEscape(value) {
  return MeldexEscape.cssIdent(value);
}

function _dbFindCurrentCtx() {
  return (typeof _currentPaneState === 'function' ? _currentPaneState() : null) || {};
}

function _dbFindData(ctx, dbPath) {
  if (ctx?.dbPath === dbPath && ctx.pivotData) return ctx.pivotData;
  if (state.currentDbPath === dbPath && state.pivotData) return state.pivotData;
  return ctx?.pivotData || state.pivotData || null;
}

function _dbFindRoot(ctx) {
  return (typeof _paneEl === 'function' && (_paneEl(ctx, '.pivot-view') || _paneEl(ctx, '#db-view-container')))
    || document.getElementById('pivot-view')
    || document.getElementById('db-view-container')
    || document.body;
}

function _positionDbFindBar() {
  const bar = _dbFindState.bar;
  if (!bar) return;
  const root = _dbFindRoot(_dbFindState.ctx);
  const rect = root.getBoundingClientRect?.() || { top: 0, right: document.documentElement.clientWidth };
  const width = bar.offsetWidth || 420;
  const top = Math.max(8, rect.top + 8);
  const left = Math.max(8, rect.right - width - 16);
  bar.style.top = top + 'px';
  bar.style.left = left + 'px';
  bar.style.right = '';
  if (typeof clampPopupToViewport === 'function') clampPopupToViewport(bar);
}

function _dbFindRegex(query) {
  const escaped = String(query || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return escaped ? new RegExp(escaped, 'gi') : null;
}

function _dbFindValueRef(dbPath, entityName, propName, val, rawIndex, pivotData) {
  return {
    file: val?.file || _entityPath(dbPath, entityName, pivotData),
    property: val?.property || propName,
    candidate_index: val?.candidate_index != null ? val.candidate_index : rawIndex,
    value: val?.value,
    status: val?.status,
  };
}

function _dbFindVisibleProps(dbPath, pivotData) {
  let props = Array.isArray(pivotData?.properties) ? pivotData.properties : [];
  if (typeof filterDeletedDbProperties === 'function') props = filterDeletedDbProperties(dbPath, props);
  const hidden = typeof getHiddenCols === 'function'
    ? getHiddenCols(dbPath, { ctx: _dbFindState.ctx })
    : [];
  return props.filter(propName => !hidden.includes(propName));
}

function _dbFindCollectMatches(query, ctx, dbPath) {
  const pivotData = _dbFindData(ctx, dbPath);
  const entities = pivotData?.entities || {};
  const props = _dbFindVisibleProps(dbPath, pivotData);
  const needle = String(query || '').toLowerCase();
  if (!needle) return [];
  const matches = [];
  const propTypes = typeof getPropertyTypes === 'function' ? getPropertyTypes(dbPath, ctx) : {};
  const advFilters = typeof getAdvancedFilters === 'function' ? getAdvancedFilters(dbPath, { ctx }) : [];
  const columnValueFilters = typeof getColumnValueFilters === 'function' ? getColumnValueFilters(dbPath, { ctx }) : {};
  const entityNames = typeof _dbSortedEntityNames === 'function'
    ? _dbSortedEntityNames(pivotData, dbPath, ctx, {
        applyAdvancedFilters: true,
        propTypes,
        advFilters,
        columnValueFilters,
        filterMode: ctx?.filter,
      })
    : Object.keys(entities);
  entityNames.forEach(entityName => {
    const entityText = String(entityName || '');
    let pos = 0;
    while ((pos = entityText.toLowerCase().indexOf(needle, pos)) >= 0) {
      matches.push({ kind: 'entity', entityName, text: entityText, start: pos, end: pos + query.length });
      pos += query.length;
    }
    const entityData = entities[entityName] || {};
    props.forEach(propName => {
      const rawValues = Array.isArray(entityData[propName]) ? entityData[propName] : [];
      const values = typeof filterValues === 'function' ? filterValues(rawValues, undefined, ctx?.filter) : rawValues;
      values.forEach(val => {
        const text = _dbSearchValueText(val?.value);
        if (!text) return;
        let valuePos = 0;
        while ((valuePos = text.toLowerCase().indexOf(needle, valuePos)) >= 0) {
          const rawIndex = Math.max(0, rawValues.indexOf(val));
          matches.push({
            kind: 'value',
            entityName,
            propName,
            text,
            start: valuePos,
            end: valuePos + query.length,
            valObj: _dbFindValueRef(dbPath, entityName, propName, val, rawIndex, pivotData),
          });
          valuePos += query.length;
        }
      });
    });
  });
  return matches;
}

function _dbFindClearCurrentMark() {
  document.querySelectorAll('.db-find-current-cell').forEach(el => el.classList.remove('db-find-current-cell'));
  document.querySelectorAll('mark.db-find-current-text').forEach(mark => {
    const parent = mark.parentNode;
    mark.replaceWith(document.createTextNode(mark.textContent || ''));
    parent?.normalize?.();
  });
}

function _dbFindCellForMatch(match) {
  const root = _dbFindRoot(_dbFindState.ctx);
  const row = root.querySelector(`tbody tr[data-entity-name="${_dbFindCssEscape(match.entityName)}"]`)
    || document.querySelector(`tbody tr[data-entity-name="${_dbFindCssEscape(match.entityName)}"]`);
  if (!row) return null;
  if (match.kind === 'entity') return row.querySelector('.col-entity') || row.firstElementChild;
  return row.querySelector(`td[data-prop-name="${_dbFindCssEscape(match.propName)}"]`);
}

function _dbFindEnsureMatchRendered(match) {
  const ctx = _dbFindState.ctx;
  if (!ctx || !match?.entityName || _dbFindCellForMatch(match)) return false;
  if (typeof _dbRevealVirtualEntityRow === 'function' && _dbRevealVirtualEntityRow(ctx, match.entityName)) return true;
  return false;
}

function _dbFindOccurrenceInCell(match) {
  const index = _dbFindState.index;
  let occurrence = 0;
  for (let i = 0; i < index; i++) {
    const candidate = _dbFindState.matches[i];
    if (candidate.kind !== match.kind || candidate.entityName !== match.entityName) continue;
    if (match.kind === 'value' && candidate.propName !== match.propName) continue;
    occurrence++;
  }
  return occurrence;
}

function _dbFindMarkText(cell, query, occurrence) {
  const needle = String(query || '').toLocaleLowerCase('ja');
  if (!cell || !needle) return null;
  const walker = document.createTreeWalker(cell, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement;
      if (!parent || !node.nodeValue) return NodeFilter.FILTER_REJECT;
      if (parent.closest('mark.db-find-current-text,button,input,textarea,select,script,style')) {
        return NodeFilter.FILTER_REJECT;
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  let remaining = Math.max(0, Number(occurrence) || 0);
  let node;
  while ((node = walker.nextNode())) {
    const text = String(node.nodeValue || '');
    const lower = text.toLocaleLowerCase('ja');
    let offset = 0;
    while (offset <= lower.length - needle.length) {
      const found = lower.indexOf(needle, offset);
      if (found < 0) break;
      if (remaining > 0) {
        remaining--;
        offset = found + Math.max(1, needle.length);
        continue;
      }
      const before = text.slice(0, found);
      const matchText = text.slice(found, found + needle.length);
      const after = text.slice(found + needle.length);
      const mark = document.createElement('mark');
      mark.className = 'db-find-current-text';
      mark.textContent = matchText;
      mark.setAttribute('aria-current', 'true');
      const fragment = document.createDocumentFragment();
      if (before) fragment.appendChild(document.createTextNode(before));
      fragment.appendChild(mark);
      if (after) fragment.appendChild(document.createTextNode(after));
      node.replaceWith(fragment);
      return mark;
    }
  }
  return null;
}

function _dbFindRevealCell(match) {
  const cell = match ? _dbFindCellForMatch(match) : null;
  if (!cell) return false;
  cell.classList.add('db-find-current-cell');
  const mark = _dbFindMarkText(cell, _dbFindState.query, _dbFindOccurrenceInCell(match));
  (mark || cell).scrollIntoView({ behavior: 'auto', block: 'center', inline: 'center' });
  if (typeof setActiveCell === 'function' && match.kind === 'value') setActiveCell(cell, { scroll: false });
  return true;
}

function _dbFindRevealWhenRendered(match, attempt = 0) {
  const current = _dbFindState.matches[_dbFindState.index];
  if (!current || current !== match || !_dbFindState.bar?.isConnected) return;
  if (_dbFindRevealCell(match)) return;
  if (attempt < 40) setTimeout(() => _dbFindRevealWhenRendered(match, attempt + 1), attempt < 5 ? 0 : 30);
}

function _dbFindUpdateStatus() {
  const count = _dbFindState.bar?.querySelector?.('[data-db-find-count]');
  if (!count) return;
  const total = _dbFindState.matches.length;
  count.textContent = total ? `${_dbFindState.index + 1}/${total}` : '0/0';
}

function _dbFindShowCurrent() {
  _dbFindClearCurrentMark();
  const match = _dbFindState.matches[_dbFindState.index];
  if (match && _dbFindEnsureMatchRendered(match)) _dbFindRevealWhenRendered(match);
  else if (match && !_dbFindRevealCell(match)) _dbFindRevealWhenRendered(match);
  _dbFindUpdateStatus();
}

function _dbFindRun(direction = 1) {
  const input = _dbFindState.bar?.querySelector?.('[data-db-find-query]');
  const query = String(input?.value || '');
  const sameQuery = query === _dbFindState.query && _dbFindState.matches.length > 0;
  if (!query) {
    _dbFindState.query = '';
    _dbFindState.matches = [];
    _dbFindState.index = -1;
    _dbFindClearCurrentMark();
    _dbFindUpdateStatus();
    return;
  }
  if (!sameQuery) {
    _dbFindState.query = query;
    _dbFindState.matches = _dbFindCollectMatches(query, _dbFindState.ctx, _dbFindState.dbPath);
    _dbFindState.index = direction >= 0 ? 0 : _dbFindState.matches.length - 1;
  } else {
    _dbFindState.index = (_dbFindState.index + (direction >= 0 ? 1 : -1) + _dbFindState.matches.length) % _dbFindState.matches.length;
  }
  if (!_dbFindState.matches.length) _dbFindState.index = -1;
  _dbFindShowCurrent();
}

function closeDbFindReplace() {
  _dbFindClearCurrentMark();
  _dbFindState.bar?.remove?.();
  window.removeEventListener('resize', _positionDbFindBar);
  _dbFindState = { bar: null, ctx: null, dbPath: '', query: '', matches: [], index: -1 };
}

function _setDbFindMode(mode) {
  const replaceMode = String(mode || '').toLowerCase() === 'replace';
  _dbFindState.bar?.classList.toggle('replace-open', replaceMode);
}

function openDbFindReplace(mode = 'find') {
  const ctx = _dbFindCurrentCtx();
  const dbPath = ctx?.dbPath || state.currentDbPath || '';
  if (!dbPath) return false;
  if (_dbFindState.bar) {
    _dbFindState.ctx = ctx;
    _dbFindState.dbPath = dbPath;
    _setDbFindMode(mode);
    _positionDbFindBar();
    _dbFindState.bar.querySelector('[data-db-find-query]')?.focus();
    return true;
  }

  const bar = document.createElement('div');
  bar.className = 'db-find-bar';
  bar.innerHTML = `
    <textarea data-db-find-query rows="1" placeholder="検索..."></textarea>
    <span data-db-find-count class="db-find-count">0/0</span>
    <button type="button" data-db-find-prev title="前へ">↑</button>
    <button type="button" data-db-find-next title="次へ">↓</button>
    <textarea data-db-find-replace rows="1" placeholder="置換..."></textarea>
    <button type="button" data-db-find-replace-one title="置換">置換</button>
    <button type="button" data-db-find-replace-all title="全置換">全置換</button>
    <button type="button" data-db-find-close title="検索を閉じる">×</button>
  `;
  document.body.appendChild(bar);
  _dbFindState = { bar, ctx, dbPath, query: '', matches: [], index: -1 };
  _setDbFindMode(mode);
  _positionDbFindBar();

  const queryInput = bar.querySelector('[data-db-find-query]');
  const replaceInput = bar.querySelector('[data-db-find-replace]');
  const autoResize = (ta) => {
    const lines = String(ta.value || '').split('\n').length;
    ta.rows = Math.min(Math.max(1, lines), 5);
    ta.classList.toggle('multiline', lines > 1);
  };
  let queryComposing = false;
  queryInput.addEventListener('input', () => {
    autoResize(queryInput);
    if (!queryInput.value) _dbFindRun(1);
  });
  queryInput.addEventListener('compositionstart', () => { queryComposing = true; });
  queryInput.addEventListener('compositionend', () => {
    queryComposing = false;
    autoResize(queryInput);
    _dbFindRun(1);
  });
  replaceInput.addEventListener('input', () => autoResize(replaceInput));
  queryInput.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { e.preventDefault(); closeDbFindReplace(); return; }
    if ((e.ctrlKey || e.metaKey) && String(e.key || '').toLowerCase() === 'h') { e.preventDefault(); _setDbFindMode('replace'); return; }
    if (e.key === 'Enter') {
      if (queryComposing || e.isComposing || e.keyCode === 229) return;
      e.preventDefault();
      _dbFindRun(e.shiftKey ? -1 : 1);
    }
  });
  replaceInput.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { e.preventDefault(); closeDbFindReplace(); return; }
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); _dbFindReplaceCurrent(); }
  });
  bar.querySelector('[data-db-find-prev]').addEventListener('click', () => _dbFindRun(-1));
  bar.querySelector('[data-db-find-next]').addEventListener('click', () => _dbFindRun(1));
  bar.querySelector('[data-db-find-replace-one]').addEventListener('click', () => _dbFindReplaceCurrent());
  bar.querySelector('[data-db-find-replace-all]').addEventListener('click', () => _dbFindReplaceAll());
  bar.querySelector('[data-db-find-close]').addEventListener('click', () => closeDbFindReplace());
  window.addEventListener('resize', _positionDbFindBar, { passive: true });
  setTimeout(() => queryInput.focus(), 0);
  return true;
}

async function _dbFindRefreshAfterChange(preferredIndex = 0) {
  const { dbPath, ctx, query } = _dbFindState;
  if (typeof selectDatabase === 'function') {
    await selectDatabase(dbPath, ctx, {
      silent: true,
      skipRecent: true,
      skipNavPush: true,
      skipSaveLastView: true,
    });
  } else if (typeof renderPivot === 'function') {
    renderPivot(ctx);
  }
  _dbFindState.matches = _dbFindCollectMatches(query, ctx, dbPath);
  _dbFindState.index = _dbFindState.matches.length ? Math.min(Math.max(0, preferredIndex), _dbFindState.matches.length - 1) : -1;
  _dbFindShowCurrent();
}

async function _dbFindRenameEntity(match, nextName) {
  const dbPath = _dbFindState.dbPath;
  const ctx = _dbFindState.ctx;
  const pivotData = _dbFindData(ctx, dbPath);
  const cleanName = String(nextName || '').trim();
  if (!cleanName) throw new Error('トピック名を空にはできません');
  if (cleanName !== match.entityName && pivotData?.entities && Object.prototype.hasOwnProperty.call(pivotData.entities, cleanName)) {
    throw new Error('同じトピック名が既にあります: ' + cleanName);
  }
  await window.GbDbEntryIdentity.rename({
    dbPath,
    oldName: match.entityName,
    newName: cleanName,
    path: _entityPath(dbPath, match.entityName, pivotData),
    ctx,
    entryId: pivotData?.entities?.[match.entityName]?._id || '',
  });
  if (typeof _dbUndoRename === 'function') _dbUndoRename(dbPath, match.entityName, cleanName, ctx);
}

async function _dbFindReplaceCurrent() {
  const query = String(_dbFindState.bar?.querySelector?.('[data-db-find-query]')?.value || '');
  if (query !== _dbFindState.query || !_dbFindState.matches.length) _dbFindRun(1);
  const match = _dbFindState.matches[_dbFindState.index];
  if (!match) return;
  const replacement = String(_dbFindState.bar?.querySelector?.('[data-db-find-replace]')?.value || '');
  const nextText = match.text.slice(0, match.start) + replacement + match.text.slice(match.end);
  try {
    if (match.kind === 'entity') {
      await _dbFindRenameEntity(match, nextText);
    } else {
      const oldValue = String(match.valObj.value ?? '');
      await _apiPutValue(match.valObj, { new_value: nextText, __source: 'sheet-find-replace' });
      if (typeof _dbUndoValue === 'function') {
        _dbUndoValue('シート置換: ' + match.propName, match.valObj, oldValue, nextText, undefined, undefined, {
          dbPath: _dbFindState.dbPath,
          ctx: _dbFindState.ctx,
        });
      }
    }
    await _dbFindRefreshAfterChange(_dbFindState.index);
  } catch (e) {
    if (typeof showStatus === 'function') showStatus(e?.message || '置換に失敗しました', true);
  }
}

async function _dbFindReplaceAll() {
  const queryInput = _dbFindState.bar?.querySelector?.('[data-db-find-query]');
  const query = String(queryInput?.value || '');
  if (!_dbFindRegex(query)) return;
  if (query !== _dbFindState.query || !_dbFindState.matches.length) _dbFindRun(1);
  const replacement = String(_dbFindState.bar?.querySelector?.('[data-db-find-replace]')?.value || '');
  const matches = _dbFindCollectMatches(query, _dbFindState.ctx, _dbFindState.dbPath);
  const valueTasks = new Map();
  const entityTasks = new Map();

  matches.forEach(match => {
    if (match.kind === 'entity') {
      entityTasks.set(match.entityName, match.text.replace(_dbFindRegex(query), replacement));
      return;
    }
    const key = [match.valObj.file, match.valObj.property, match.valObj.candidate_index].join('\n');
    if (!valueTasks.has(key)) {
      const oldValue = String(match.valObj.value ?? '');
      valueTasks.set(key, { match, oldValue, nextValue: oldValue.replace(_dbFindRegex(query), replacement) });
    }
  });

  let count = 0;
  try {
    const pivotData = _dbFindData(_dbFindState.ctx, _dbFindState.dbPath);
    const entityNames = new Set(Object.keys(pivotData?.entities || {}));
    const plannedEntityNames = new Set();
    for (const [oldName, rawNewName] of entityTasks.entries()) {
      const newName = String(rawNewName || '').trim();
      if (!newName) throw new Error('トピック名を空にはできません');
      if (oldName === newName) continue;
      if (plannedEntityNames.has(newName)) throw new Error('置換後のトピック名が重複します: ' + newName);
      if (entityNames.has(newName)) throw new Error('同じトピック名が既にあります: ' + newName);
      plannedEntityNames.add(newName);
    }
    for (const item of valueTasks.values()) {
      if (item.oldValue === item.nextValue) continue;
      await _apiPutValue(item.match.valObj, { new_value: item.nextValue, __source: 'sheet-find-replace-all' });
      if (typeof _dbUndoValue === 'function') {
        _dbUndoValue('シート全置換: ' + item.match.propName, item.match.valObj, item.oldValue, item.nextValue, undefined, undefined, {
          dbPath: _dbFindState.dbPath,
          ctx: _dbFindState.ctx,
        });
      }
      count++;
    }
    for (const [oldName, newName] of entityTasks.entries()) {
      if (oldName === newName) continue;
      await _dbFindRenameEntity({ kind: 'entity', entityName: oldName, text: oldName }, newName);
      count++;
    }
    await _dbFindRefreshAfterChange(0);
    if (typeof showStatus === 'function') showStatus(count + '件置換しました');
  } catch (e) {
    if (typeof showStatus === 'function') showStatus(e?.message || '全置換に失敗しました', true);
  }
}

if (typeof window !== 'undefined') {
  window.openDbFindReplace = openDbFindReplace;
  window.closeDbFindReplace = closeDbFindReplace;
}

/* --- 検索モーダル --- */

/**
 * シート横断検索モーダルを表示
 */
function showDbSearchModal(options) {
  const opts = options || {};
  const preferredScope = opts.scope === 'current' ? (state.currentDbPath || '') : (opts.scope || '');
  const returnFocus = typeof opts.returnFocus === 'function'
    ? opts.returnFocus
    : (opts.returnFocus?.isConnected ? opts.returnFocus : null);
  const body = document.createElement('div');
  body.className = 'gb-db-search-body';

  // ヘッダー
  const header = document.createElement('div');
  header.className = 'gb-db-search-controls';

  const input = document.createElement('input');
  input.type = 'text';
  input.dataset.e2eId = 'db-search-input';
  input.placeholder = 'シート横断検索...（トピック名・列の値）';

  const scopeSelect = document.createElement('select');
  scopeSelect.dataset.e2eId = 'db-search-scope';
  const optAll = document.createElement('option');
  optAll.value = '';
  optAll.textContent = '全シート';
  scopeSelect.appendChild(optAll);
  // 既知のDBを列挙（フォルダツリーのルートから探索）
  _populateDbScopeOptions(scopeSelect);
  if (preferredScope && !Array.from(scopeSelect.options).some(opt => opt.value === preferredScope)) {
    const optCurrent = document.createElement('option');
    optCurrent.value = preferredScope;
    optCurrent.textContent = '現在のシート';
    scopeSelect.insertBefore(optCurrent, scopeSelect.options[1] || null);
  }
  if (preferredScope) {
    scopeSelect.value = preferredScope;
  }

  header.appendChild(input);
  header.appendChild(scopeSelect);
  body.appendChild(header);

  // 結果エリア
  const resultArea = document.createElement('div');
  resultArea.className = 'gb-db-search-results';
  resultArea.dataset.e2eId = 'db-search-results';
  resultArea.innerHTML = '<div style="text-align:center;padding:40px;color:var(--fg2);">キーワードを入力してEnterで検索</div>';
  body.appendChild(resultArea);

  // フッター
  const statusSpan = document.createElement('span');
  statusSpan.className = 'gb-db-search-status';
  statusSpan.dataset.e2eId = 'db-search-status';
  const exportBtn = document.createElement('button');
  exportBtn.type = 'button';
  exportBtn.className = 'gb-btn gb-btn-sm';
  exportBtn.dataset.e2eId = 'db-search-export';
  exportBtn.textContent = 'CSVエクスポート';
  const setExportVisible = visible => {
    exportBtn.dataset.dbSearchExportVisible = visible ? '1' : '0';
    exportBtn.style.display = visible ? '' : 'none';
    const compact = window.matchMedia?.('(max-width: 600px)')?.matches === true;
    statusSpan.style.display = compact && !visible ? 'none' : '';
    closeBtn.style.flex = compact && !visible ? '1 1 100%' : '';
    closeBtn.style.width = compact && !visible ? '100%' : '';
  };
  exportBtn.addEventListener('click', () => _exportDbSearchCsv(lastResults));
  const closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'gb-btn gb-btn-sm';
  closeBtn.dataset.e2eId = 'db-search-close';
  closeBtn.textContent = '閉じる';
  setExportVisible(false);

  let lastResults = [];
  let searchSeq = 0;
  const modalApi = window.GBUI.createModal({
    id: 'database-cross-sheet-search-dialog',
    title: 'シート横断検索',
    body,
    footer: [statusSpan, exportBtn, closeBtn],
    variant: 'standard',
    extraClass: 'gb-db-search-modal',
    geometryKey: 'database-cross-sheet-search',
    initialFocus: '[data-e2e-id="db-search-input"]',
    returnFocus: returnFocus || undefined,
    onClose: () => { searchSeq += 1; },
  });
  const overlay = modalApi.overlay;
  modalApi.footer.classList.add('gb-db-search-footer');
  overlay.classList.add('modal-overlay');
  overlay.dataset.dbSearchDialog = '1';
  const headerClose = modalApi.header.querySelector('.gb-modal-close');
  if (headerClose) headerClose.dataset.e2eId = 'db-search-close-icon';
  closeBtn.addEventListener('click', () => modalApi.close('close-button'));

  // 検索実行
  async function doSearch() {
    const q = input.value.trim();
    const seq = ++searchSeq;
    if (!q) {
      lastResults = [];
      setExportVisible(false);
      resultArea.innerHTML = '<div style="text-align:center;padding:40px;color:var(--fg2);">キーワードを入力してEnterで検索</div>';
      statusSpan.textContent = '';
      return;
    }
    lastResults = [];
    setExportVisible(false);
    statusSpan.textContent = '検索中...';
    resultArea.innerHTML = '';
    try {
      const data = await doDbSearch(q, scopeSelect.value);
      if (seq !== searchSeq) return;
      lastResults = data.entities || [];
      _renderDbSearchResults(resultArea, lastResults, q, entry => {
        modalApi.close('result-select');
        if (entry.db_path) {
          selectDatabase(entry.db_path).then(() => {
            if (entry.path && typeof selectEntity === 'function') selectEntity(entry.path);
          });
        }
      });
      statusSpan.textContent = lastResults.length + '件（' + (data.total_dbs_scanned || '?') + 'シート検索）';
      setExportVisible(lastResults.length > 0);
    } catch (e) {
      if (seq !== searchSeq) return;
      lastResults = [];
      setExportVisible(false);
      resultArea.innerHTML = '<div style="text-align:center;padding:20px;color:var(--red,#d16969);">検索エラー</div>';
      statusSpan.textContent = 'エラー';
    }
  }

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && !e.isComposing) doSearch();
  });
  modalApi.open();
}

/* --- 結果描画 --- */

function _renderDbSearchResults(container, results, query, onSelect) {
  if (results.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--fg2);">一致するトピックなし</div>';
    return;
  }

  const qLower = query.toLowerCase();

  results.forEach(entry => {
    const item = document.createElement('div');
    item.className = 'db-search-result';
    item.dataset.e2eId = 'db-search-result';
    item.tabIndex = 0;

    // エントリ名 + シート名
    const titleRow = document.createElement('div');
    titleRow.className = 'gb-db-search-result-title';
    const nameSpan = document.createElement('span');
    nameSpan.className = 'gb-db-search-result-name';
    nameSpan.style.cssText = 'font-weight:bold;font-size:13px;';
    nameSpan.innerHTML = _highlightMatch(entry.name, qLower);
    titleRow.appendChild(nameSpan);
    const dbBadge = document.createElement('span');
    dbBadge.className = 'gb-db-search-result-badge';
    dbBadge.style.cssText = 'font-size:10px;background:var(--bg4);color:var(--fg2);padding:1px 6px;border-radius:8px;';
    dbBadge.textContent = (entry.root_name ? entry.root_name + '/' : '') + entry.db_name;
    titleRow.appendChild(dbBadge);
    item.appendChild(titleRow);

    // マッチしたプロパティプレビュー
    const props = entry.matched_props || {};
    const propKeys = Object.keys(props).slice(0, 5);
    if (propKeys.length > 0) {
      const propDiv = document.createElement('div');
      propDiv.className = 'gb-db-search-result-props';
      propDiv.style.cssText = 'font-size:11px;color:var(--fg2);margin-top:4px;line-height:1.5;';
      propKeys.forEach(pn => {
        const vals = props[pn] || [];
        const valTexts = vals.slice(0, 3).map(v => _dbSearchValueText(v?.value)).filter(v => v !== '');
        if (valTexts.length > 0) {
          const line = document.createElement('div');
          line.innerHTML = '<b>' + esc(pn) + ':</b> ' + _highlightMatch(valTexts.join(', '), qLower);
          propDiv.appendChild(line);
        }
      });
      item.appendChild(propDiv);
    }

    // クリック → 遷移
    const activate = () => {
      if (typeof onSelect === 'function') onSelect(entry);
    };
    item.addEventListener('click', activate);
    item.addEventListener('keydown', event => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      activate();
    });

    container.appendChild(item);
  });
}

function _highlightMatch(text, qLower) {
  const raw = String(text == null ? '' : text);
  const needle = String(qLower == null ? '' : qLower).toLowerCase();
  if (!needle) return esc(raw);
  const lower = raw.toLowerCase();
  let pos = 0;
  let out = '';
  while (pos < raw.length) {
    const idx = lower.indexOf(needle, pos);
    if (idx < 0) break;
    out += esc(raw.slice(pos, idx));
    out += '<span style="background:var(--accent);color:var(--ui-accent-fg, var(--ui-fg-strong));padding:0 2px;border-radius:2px;">'
      + esc(raw.slice(idx, idx + needle.length))
      + '</span>';
    pos = idx + needle.length;
  }
  out += esc(raw.slice(pos));
  return out;
}

function _dbSearchValueText(value) {
  if (value == null) return '';
  if (Array.isArray(value)) return value.map(v => _dbSearchValueText(v)).join(', ');
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

function _dbSearchCsvSafeValue(value) {
  const text = _dbSearchValueText(value);
  return /^[\s]*[=+\-@]/.test(text) ? "'" + text : text;
}

function _dbSearchCsvCell(value) {
  const text = _dbSearchCsvSafeValue(value);
  return '"' + text.replace(/"/g, '""') + '"';
}

/* --- DBスコープ選択肢を列挙 --- */

function _populateDbScopeOptions(select) {
  // フォルダツリーのツリーからDB型ノードを収集（_nodeDataベース）
  const seen = new Set();
  document.querySelectorAll('#outliner-tree .tree-node').forEach(node => {
    const nd = node._nodeData;
    if (!nd || nd.type !== 'database' || !nd.path) return;
    if (seen.has(nd.path)) return;
    seen.add(nd.path);
    const opt = document.createElement('option');
    opt.value = nd.path;
    opt.textContent = nd.name || nd.path.split('/').pop();
    select.appendChild(opt);
  });
}

/* --- CSVエクスポート --- */

async function _exportDbSearchCsv(results) {
  if (!results || results.length === 0) return;

  // 全プロパティ名を収集
  const allProps = new Set();
  results.forEach(entry => {
    Object.keys(entry.matched_props || {}).forEach(p => allProps.add(p));
  });
  const propList = [...allProps];

  // CSV生成
  const rows = [];
  const header = ['トピック名', 'シート名', 'ルート', ...propList];
  rows.push(header.map(h => _dbSearchCsvCell(h)).join(','));

  results.forEach(entry => {
    const row = [
      entry.name,
      entry.db_name,
      entry.root_name || '',
    ];
    propList.forEach(p => {
      const vals = (entry.matched_props || {})[p] || [];
      row.push(vals.map(v => _dbSearchValueText(v?.value)).join('; '));
    });
    rows.push(row.map(v => _dbSearchCsvCell(v)).join(','));
  });

  if (typeof MeldexExportSave === 'undefined' || typeof MeldexExportSave.saveText !== 'function') {
    showStatus('保存ダイアログを初期化できませんでした', true);
    return;
  }
  await MeldexExportSave.saveText(rows.join('\n'), {
    filename: 'db-search-results.csv',
    extension: '.csv',
    dialogTitle: '検索結果CSVとして保存',
    filetypes: [['CSVファイル', '*.csv'], ['すべてのファイル', '*.*']],
    bom: true,
    okMessage: '検索結果CSVを保存しました',
    errorMessage: '検索結果CSVの保存に失敗しました',
  });
}

;

/* === gb-sheet-archive.js === */
;
/* ==============================
   gb-sheet-archive.js: sheet archive management
   ============================== */

let _sheetArchiveModalState = null;

function _sheetArchiveCurrentPath(explicitPath) {
  if (explicitPath) return explicitPath;
  if (typeof state !== 'undefined' && state?.currentDbPath) return state.currentDbPath;
  if (typeof getCurrentFilePath === 'function') return getCurrentFilePath();
  return '';
}

function _sheetArchiveNum(root, selector, fallback) {
  const value = Number(root.querySelector(selector)?.value);
  return Number.isFinite(value) && value >= 0 ? Math.floor(value) : fallback;
}

function _sheetArchiveText(value) {
  return String(value == null ? '' : value);
}

function _sheetArchiveBytes(value) {
  const bytes = Number(value || 0);
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1).replace(/\.0$/, '') + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1).replace(/\.0$/, '') + ' MB';
}

function _sheetArchiveButton(label, className) {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = className || 'gb-btn gb-btn-sm';
  btn.textContent = label;
  return btn;
}

function _sheetArchiveSetStatus(text, isError) {
  const el = _sheetArchiveModalState?.statusEl;
  if (!el) return;
  el.textContent = text || '';
  el.style.color = isError ? 'var(--red,#d16969)' : 'var(--fg2)';
}

function _sheetArchiveBeginBusy() {
  const st = _sheetArchiveModalState;
  if (!st) return;
  st.busyDepth = Number(st.busyDepth || 0) + 1;
  st.modal?.setAttribute('aria-busy', 'true');
  const controls = [
    ...(st.actionControls || []),
    ...(st.modal?.querySelectorAll('button') || []),
  ].filter(control => control.id !== 'sheet-archive-close' && control.dataset.e2eId !== 'sheet-archive-header-close');
  [...new Set(controls)].forEach(control => { control.disabled = true; });
}

function _sheetArchiveEndBusy() {
  const st = _sheetArchiveModalState;
  if (!st) return;
  st.busyDepth = Math.max(0, Number(st.busyDepth || 0) - 1);
  if (st.busyDepth) return;
  st.modal?.removeAttribute('aria-busy');
  const controls = [
    ...(st.actionControls || []),
    ...(st.modal?.querySelectorAll('button') || []),
  ].filter(control => control.id !== 'sheet-archive-close' && control.dataset.e2eId !== 'sheet-archive-header-close');
  [...new Set(controls)].forEach(control => { control.disabled = false; });
}

async function _sheetArchiveLoad(keepStatus = false) {
  const st = _sheetArchiveModalState;
  if (!st?.path) return;
  _sheetArchiveBeginBusy();
  try {
    const [status, policyRes] = await Promise.all([
      apiFetch('/sheet-archive/status?path=' + encodeURIComponent(st.path)),
      apiFetch('/sheet-archive/policy?path=' + encodeURIComponent(st.path)),
    ]);
    st.status = status;
    st.policy = policyRes.policy || status.policy || {};
    _sheetArchiveRenderStatus();
    if (!keepStatus) _sheetArchiveSetStatus('');
  } catch (error) {
    _sheetArchiveSetStatus(error?.message || 'アーカイブ情報を読み込めませんでした', true);
  } finally {
    _sheetArchiveEndBusy();
  }
}

function _sheetArchiveRenderStatus() {
  const st = _sheetArchiveModalState;
  if (!st) return;
  const status = st.status || {};
  const policy = st.policy || {};
  st.summaryEl.textContent =
    '表示中 ' + Number(status.active_count || 0).toLocaleString('ja-JP') +
    ' 件 / アーカイブ ' + Number(status.archived_entries || 0).toLocaleString('ja-JP') + ' 件';
  st.maxInput.value = Number(policy.max_active_entries || 0);
  st.daysInput.value = Number(policy.older_than_days || 0);
  st.limitInput.value = Number(policy.batch_limit || 500);
  _sheetArchiveRenderArchives(status.archives || []);
}

function _sheetArchiveRenderArchives(archives) {
  const st = _sheetArchiveModalState;
  if (!st) return;
  st.archiveList.innerHTML = '';
  if (!archives.length) {
    const empty = document.createElement('div');
    empty.className = 'gb-section-desc';
    empty.textContent = 'まだアーカイブはありません';
    st.archiveList.appendChild(empty);
    return;
  }
  archives.forEach((archive, index) => {
    const row = document.createElement('div');
    row.className = 'gb-field-row';
    row.style.cssText = 'align-items:center;border-bottom:1px solid var(--border);padding:6px 0;';

    const info = document.createElement('div');
    info.style.cssText = 'flex:1;min-width:0;';
    const title = document.createElement('div');
    title.style.cssText = 'font-size:13px;color:var(--fg);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
    title.textContent = _sheetArchiveText(archive.id);
    const meta = document.createElement('div');
    meta.className = 'gb-section-desc';
    meta.textContent = Number(archive.count || 0).toLocaleString('ja-JP') + '件 / ' + _sheetArchiveBytes(archive.bytes) + ' / ' + _sheetArchiveText(archive.created_at || '');
    info.appendChild(title);
    info.appendChild(meta);

    const restore = _sheetArchiveButton('復元');
    restore.dataset.e2eId = `sheet-archive-restore-${index}`;
    restore.addEventListener('click', () => _sheetArchiveRestore(archive.id));
    row.appendChild(info);
    row.appendChild(restore);
    st.archiveList.appendChild(row);
  });
}

function _sheetArchiveRenderCandidates(candidates, total) {
  const st = _sheetArchiveModalState;
  if (!st) return;
  st.candidateList.innerHTML = '';
  const head = document.createElement('div');
  head.className = 'gb-section-desc';
  head.textContent = Number(total || candidates.length || 0).toLocaleString('ja-JP') + '件が候補です';
  st.candidateList.appendChild(head);
  candidates.slice(0, 20).forEach(item => {
    const row = document.createElement('div');
    row.className = 'gb-field-row';
    row.style.cssText = 'border-bottom:1px solid var(--border);padding:4px 0;';
    const name = document.createElement('span');
    name.style.cssText = 'flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
    name.textContent = item.name || item.file_name || item.id;
    const meta = document.createElement('span');
    meta.className = 'gb-section-desc';
    meta.textContent = item.modified || item.updated || item.created || '';
    row.appendChild(name);
    row.appendChild(meta);
    st.candidateList.appendChild(row);
  });
}

async function _sheetArchiveSavePolicy() {
  const st = _sheetArchiveModalState;
  if (!st) return;
  const body = {
    path: st.path,
    max_active_entries: _sheetArchiveNum(st.modal, '[data-sheet-archive-max]', 0),
    older_than_days: _sheetArchiveNum(st.modal, '[data-sheet-archive-days]', 0),
    batch_limit: _sheetArchiveNum(st.modal, '[data-sheet-archive-limit]', 500),
  };
  _sheetArchiveBeginBusy();
  try {
    const res = await apiPut('/sheet-archive/policy', body);
    st.policy = res.policy || body;
    _sheetArchiveSetStatus('アーカイブ条件を保存しました');
  } catch (error) {
    _sheetArchiveSetStatus(error?.message || 'アーカイブ条件を保存できませんでした', true);
  } finally {
    _sheetArchiveEndBusy();
  }
}

async function _sheetArchivePreviewCandidates() {
  const st = _sheetArchiveModalState;
  if (!st) return;
  const params = new URLSearchParams({
    path: st.path,
    max_active_entries: String(_sheetArchiveNum(st.modal, '[data-sheet-archive-max]', 0)),
    older_than_days: String(_sheetArchiveNum(st.modal, '[data-sheet-archive-days]', 0)),
    limit: String(_sheetArchiveNum(st.modal, '[data-sheet-archive-limit]', 500)),
  });
  _sheetArchiveSetStatus('候補を確認しています...');
  _sheetArchiveBeginBusy();
  try {
    const res = await apiFetch('/sheet-archive/candidates?' + params.toString());
    _sheetArchiveRenderCandidates(res.candidates || [], res.candidate_count || 0);
    _sheetArchiveSetStatus('');
  } catch (error) {
    _sheetArchiveSetStatus(error?.message || '候補確認に失敗しました', true);
  } finally {
    _sheetArchiveEndBusy();
  }
}

async function _sheetArchiveRun() {
  const st = _sheetArchiveModalState;
  if (!st) return;
  const ok = typeof cfConfirm === 'function'
    ? await cfConfirm('候補のトピックをアーカイブへ移します。元データは削除されず、検索と復元ができます。実行しますか？')
    : confirm('候補のトピックをアーカイブへ移します。実行しますか？');
  if (!ok) return;
  const body = {
    path: st.path,
    max_active_entries: _sheetArchiveNum(st.modal, '[data-sheet-archive-max]', 0),
    older_than_days: _sheetArchiveNum(st.modal, '[data-sheet-archive-days]', 0),
    limit: _sheetArchiveNum(st.modal, '[data-sheet-archive-limit]', 500),
  };
  _sheetArchiveSetStatus('アーカイブしています...');
  _sheetArchiveBeginBusy();
  try {
    const res = await apiPost('/sheet-archive/archive', body);
    _sheetArchiveSetStatus(Number(res.archived || 0).toLocaleString('ja-JP') + '件をアーカイブしました');
    await _sheetArchiveLoad(true);
    if (typeof selectDatabase === 'function') selectDatabase(st.path);
  } catch (error) {
    _sheetArchiveSetStatus(error?.message || 'アーカイブに失敗しました', true);
  } finally {
    _sheetArchiveEndBusy();
  }
}

async function _sheetArchiveRestore(archiveId) {
  const st = _sheetArchiveModalState;
  if (!st || !archiveId) return;
  const ok = typeof cfConfirm === 'function'
    ? await cfConfirm('このアーカイブのトピックを表示中のシートへ戻します。同名トピックは復元せず残します。')
    : confirm('このアーカイブのトピックを表示中のシートへ戻します。');
  if (!ok) return;
  _sheetArchiveSetStatus('復元しています...');
  _sheetArchiveBeginBusy();
  try {
    const res = await apiPost('/sheet-archive/restore', { path: st.path, archive_id: archiveId, limit: _sheetArchiveNum(st.modal, '[data-sheet-archive-limit]', 500) });
    const conflicts = Array.isArray(res.conflicts) ? res.conflicts.length : 0;
    _sheetArchiveSetStatus(Number(res.restored || 0).toLocaleString('ja-JP') + '件を復元しました' + (conflicts ? '（重複 ' + conflicts + '件）' : ''));
    await _sheetArchiveLoad(true);
    if (typeof selectDatabase === 'function') selectDatabase(st.path);
  } catch (error) {
    _sheetArchiveSetStatus(error?.message || '復元に失敗しました', true);
  } finally {
    _sheetArchiveEndBusy();
  }
}

async function _sheetArchiveSearch() {
  const st = _sheetArchiveModalState;
  if (!st) return;
  const q = st.searchInput.value.trim();
  st.searchResults.innerHTML = '';
  if (!q) return;
  _sheetArchiveSetStatus('アーカイブを検索しています...');
  _sheetArchiveBeginBusy();
  try {
    const params = new URLSearchParams({ path: st.path, q, limit: '50' });
    const res = await apiFetch('/sheet-archive/search?' + params.toString());
    const results = res.results || [];
    if (!results.length) {
      const empty = document.createElement('div');
      empty.className = 'gb-section-desc';
      empty.textContent = '一致するアーカイブはありません';
      st.searchResults.appendChild(empty);
    }
    results.forEach((item, index) => {
      const row = document.createElement('div');
      row.className = 'gb-field-row';
      row.style.cssText = 'align-items:flex-start;border-bottom:1px solid var(--border);padding:6px 0;';
      const info = document.createElement('div');
      info.style.cssText = 'flex:1;min-width:0;';
      const title = document.createElement('div');
      title.style.cssText = 'font-size:13px;color:var(--fg);font-weight:600;';
      title.textContent = item.name || item.file_name;
      const text = document.createElement('div');
      text.className = 'gb-section-desc';
      text.textContent = item.text || item.archive_id || '';
      info.appendChild(title);
      info.appendChild(text);
      const restore = _sheetArchiveButton('この件を復元');
      restore.dataset.e2eId = `sheet-archive-search-restore-${index}`;
      restore.addEventListener('click', () => _sheetArchiveRestoreOne(item));
      row.appendChild(info);
      row.appendChild(restore);
      st.searchResults.appendChild(row);
    });
    _sheetArchiveSetStatus(results.length + '件見つかりました');
  } catch (error) {
    _sheetArchiveSetStatus(error?.message || 'アーカイブ検索に失敗しました', true);
  } finally {
    _sheetArchiveEndBusy();
  }
}

async function _sheetArchiveRestoreOne(item) {
  const st = _sheetArchiveModalState;
  if (!st || !item?.archive_id) return;
  _sheetArchiveBeginBusy();
  try {
    const res = await apiPost('/sheet-archive/restore', {
      path: st.path,
      archive_id: item.archive_id,
      entry_names: [item.file_name || item.name],
      limit: 1,
    });
    _sheetArchiveSetStatus(Number(res.restored || 0).toLocaleString('ja-JP') + '件を復元しました');
    await _sheetArchiveLoad(true);
    if (typeof selectDatabase === 'function') selectDatabase(st.path);
  } catch (error) {
    _sheetArchiveSetStatus(error?.message || '復元に失敗しました', true);
  } finally {
    _sheetArchiveEndBusy();
  }
}

function showSheetArchiveModal(path) {
  const sheetPath = _sheetArchiveCurrentPath(path);
  if (!sheetPath) {
    if (typeof showStatus === 'function') showStatus('シートを開いてから実行してください', true);
    return;
  }
  if (_sheetArchiveModalState?.modalApi?.isOpen?.()) return _sheetArchiveModalState.overlay;
  if (typeof window.GBUI?.createModal !== 'function') {
    throw new Error('共通ダイアログを初期化できませんでした。');
  }
  document.querySelectorAll('.modal-overlay[data-sheet-archive]').forEach(el => el.remove());

  const body = document.createElement('div');
  body.className = 'gb-sheet-archive-body';
  body.dataset.e2eId = 'sheet-archive-body';

  const summary = document.createElement('div');
  summary.className = 'gb-section-desc';
  summary.dataset.e2eId = 'sheet-archive-summary';
  summary.textContent = '読み込み中...';

  const condition = document.createElement('section');
  condition.className = 'gb-section gb-section--boxed';
  condition.innerHTML = `
    <div class="gb-section-title">アーカイブ条件</div>
    <label class="gb-field-row"><span class="gb-label">表示に残す件数</span><input id="sheet-archive-max" data-sheet-archive-max data-e2e-id="sheet-archive-max" type="number" min="0" class="gb-input" style="width:110px;"><span class="gb-section-desc">0で件数条件なし</span></label>
    <label class="gb-field-row"><span class="gb-label">対象期間</span><input id="sheet-archive-days" data-sheet-archive-days data-e2e-id="sheet-archive-days" type="number" min="0" class="gb-input" style="width:110px;"><span class="gb-section-desc">日前より古いもの（0で期間条件なし）</span></label>
    <label class="gb-field-row"><span class="gb-label">1回の処理件数</span><input id="sheet-archive-limit" data-sheet-archive-limit data-e2e-id="sheet-archive-limit" type="number" min="1" class="gb-input" style="width:110px;"></label>
  `;
  const actionRow = document.createElement('div');
  actionRow.className = 'gb-field-row';
  actionRow.style.justifyContent = 'flex-start';
  const saveBtn = _sheetArchiveButton('条件を保存');
  saveBtn.dataset.e2eId = 'sheet-archive-save-policy';
  const previewBtn = _sheetArchiveButton('候補を確認');
  previewBtn.dataset.e2eId = 'sheet-archive-preview';
  const runBtn = _sheetArchiveButton('候補をアーカイブ', 'gb-btn gb-btn-sm gb-btn-primary');
  runBtn.dataset.e2eId = 'sheet-archive-run';
  actionRow.appendChild(saveBtn);
  actionRow.appendChild(previewBtn);
  actionRow.appendChild(runBtn);
  condition.appendChild(actionRow);

  const candidateList = document.createElement('div');
  candidateList.dataset.e2eId = 'sheet-archive-candidates';
  candidateList.style.cssText = 'max-height:160px;overflow:auto;';
  condition.appendChild(candidateList);

  const search = document.createElement('section');
  search.className = 'gb-section gb-section--boxed';
  const searchTitle = document.createElement('div');
  searchTitle.className = 'gb-section-title';
  searchTitle.textContent = 'アーカイブ検索';
  const searchRow = document.createElement('div');
  searchRow.className = 'gb-field-row';
  const searchInput = document.createElement('input');
  searchInput.type = 'text';
  searchInput.className = 'gb-input';
  searchInput.dataset.e2eId = 'sheet-archive-search-input';
  searchInput.placeholder = 'アーカイブ内を検索';
  searchInput.style.flex = '1';
  const searchBtn = _sheetArchiveButton('検索');
  searchBtn.dataset.e2eId = 'sheet-archive-search';
  searchRow.appendChild(searchInput);
  searchRow.appendChild(searchBtn);
  const searchResults = document.createElement('div');
  searchResults.dataset.e2eId = 'sheet-archive-search-results';
  searchResults.style.cssText = 'max-height:180px;overflow:auto;';
  search.appendChild(searchTitle);
  search.appendChild(searchRow);
  search.appendChild(searchResults);

  const archiveSection = document.createElement('section');
  archiveSection.className = 'gb-section gb-section--boxed';
  const archiveTitle = document.createElement('div');
  archiveTitle.className = 'gb-section-title';
  archiveTitle.textContent = '保存済みアーカイブ';
  const archiveList = document.createElement('div');
  archiveList.dataset.e2eId = 'sheet-archive-list';
  archiveList.style.cssText = 'max-height:190px;overflow:auto;';
  archiveSection.appendChild(archiveTitle);
  archiveSection.appendChild(archiveList);

  body.appendChild(summary);
  body.appendChild(condition);
  body.appendChild(search);
  body.appendChild(archiveSection);

  const footer = document.createElement('div');
  footer.className = 'gb-sheet-archive-footer';
  const statusEl = document.createElement('div');
  statusEl.className = 'gb-section-desc';
  statusEl.dataset.e2eId = 'sheet-archive-status';
  statusEl.style.cssText = 'flex:1;min-width:0;';
  const closeBtn = _sheetArchiveButton('閉じる');
  closeBtn.id = 'sheet-archive-close';
  closeBtn.dataset.e2eId = 'sheet-archive-close';
  footer.appendChild(statusEl);
  footer.appendChild(closeBtn);

  let modalApi = null;
  modalApi = window.GBUI.createModal({
    id: 'sheet-archive',
    title: 'シートアーカイブ管理',
    body,
    footer,
    variant: 'mobile-sheet',
    extraClass: 'gb-sheet-archive-modal',
    geometryKey: 'sheet-archive',
    initialFocus: '#sheet-archive-close',
    closeOnEsc: true,
    closeOnOverlay: true,
    onBeforeClose: () => Number(_sheetArchiveModalState?.busyDepth || 0) === 0,
    onClose: () => {
      if (_sheetArchiveModalState?.modalApi === modalApi) _sheetArchiveModalState = null;
    },
  });
  const overlay = modalApi.overlay;
  const modal = modalApi.modal;
  overlay.classList.add('modal-overlay', 'gb-sheet-archive-overlay');
  overlay.dataset.sheetArchive = '1';
  overlay.dataset.e2eId = 'sheet-archive-overlay';
  modal.dataset.e2eId = 'sheet-archive-dialog';
  const headerClose = modalApi.header.querySelector('.gb-modal-close');
  if (headerClose) headerClose.dataset.e2eId = 'sheet-archive-header-close';
  closeBtn.addEventListener('click', () => modalApi.close('button'));

  _sheetArchiveModalState = {
    modalApi,
    overlay,
    modal,
    path: sheetPath,
    summaryEl: summary,
    statusEl,
    maxInput: condition.querySelector('[data-sheet-archive-max]'),
    daysInput: condition.querySelector('[data-sheet-archive-days]'),
    limitInput: condition.querySelector('[data-sheet-archive-limit]'),
    candidateList,
    archiveList,
    searchInput,
    searchResults,
    closeBtn,
    busyDepth: 0,
    actionControls: [
      condition.querySelector('[data-sheet-archive-max]'),
      condition.querySelector('[data-sheet-archive-days]'),
      condition.querySelector('[data-sheet-archive-limit]'),
      saveBtn,
      previewBtn,
      runBtn,
      searchInput,
      searchBtn,
    ],
  };

  saveBtn.addEventListener('click', _sheetArchiveSavePolicy);
  previewBtn.addEventListener('click', _sheetArchivePreviewCandidates);
  runBtn.addEventListener('click', _sheetArchiveRun);
  searchBtn.addEventListener('click', _sheetArchiveSearch);
  searchInput.addEventListener('keydown', ev => {
    if (ev.key === 'Enter' && !ev.isComposing) _sheetArchiveSearch();
  });
  modalApi.open();
  _sheetArchiveLoad();
  return overlay;
}

if (typeof window !== 'undefined') {
  window.showSheetArchiveModal = showSheetArchiveModal;
}

;

/* === gb-chat-custom-instructions-sheet.js === */
;
/* Custom instructions through Sheet form */

const CHAT_CUSTOM_INSTRUCTIONS_DB_NAME = 'カスタムインストラクション';
const CHAT_CUSTOM_INSTRUCTIONS_ROLE = 'chat-custom-instructions';

function _chatCustomInstructionPropertyTypes() {
  return {
    設定名: { type: 'text' },
    利用範囲: { type: 'select', options: ['全体', '現在のソースフォルダ'] },
    私について: { type: 'long-text' },
    '作品・ジャンル・読者': { type: 'long-text' },
    回答方針: { type: 'long-text' },
    '口調・文体': { type: 'long-text' },
    '好み・避けたいこと': { type: 'long-text' },
    必ず確認してほしいこと: { type: 'long-text' },
    その他の指示: { type: 'long-text' },
  };
}

function _chatCustomInstructionFormConfig() {
  return {
    id: 'meldex-chat-custom-instructions-form',
    fields: ['設定名', '利用範囲', '私について', '作品・ジャンル・読者', '回答方針', '口調・文体', '好み・避けたいこと', '必ず確認してほしいこと', 'その他の指示'],
    required: ['利用範囲'],
    descriptions: {
      利用範囲: 'Meldex全体で使う指示か、現在のソースフォルダだけで使う指示かを選びます。',
      私について: '役割、創作ジャンル、作業スタイル、前提知識など。',
      '作品・ジャンル・読者': '扱っている作品、ジャンル、想定読者、媒体、制約など。',
      回答方針: '提案時に重視してほしい観点、確認の深さ、避けたい判断など。',
      '口調・文体': '返答の文体、呼び方、説明の粒度、箇条書きの好みなど。',
      '好み・避けたいこと': '好きな方向性、避けたい表現、NG例など。',
      必ず確認してほしいこと: '毎回チェックしてほしい整合性、世界観、制約、作業ルールなど。',
      その他の指示: '上の項目に入らない常時指示。',
    },
    placeholders: {
      設定名: '例: 長期連載プロット相談用',
      私について: '例: 長編作品や企画の構成を作っています。',
      回答方針: '例: まず矛盾やリスクを指摘し、その後で代案を出してください。',
    },
    labels: {},
    submitLabel: 'カスタムインストラクションに反映',
    successMessage: 'カスタムインストラクションに反映しました。',
    headerTitle: 'チャット用カスタムインストラクション',
    headerDescription: 'チャットで常に考慮してほしい前提や応答方針を項目別に入力します。',
    mode: 'answer',
    entityNameProp: '設定名',
    customInstructionsRelay: true,
  };
}

function _chatCustomInstructionViewConfig() {
  return {
    currentViewIdx: 0,
    propertyTypes: _chatCustomInstructionPropertyTypes(),
    savedViews: [
      { name: '入力フォーム', viewMode: 'form', typeSpecific: { form: { formConfig: _chatCustomInstructionFormConfig() } } },
    ],
  };
}

function _chatCustomInstructionDbNotePath(dbPath) {
  const name = String(dbPath || CHAT_CUSTOM_INSTRUCTIONS_DB_NAME).split('/').pop() || CHAT_CUSTOM_INSTRUCTIONS_DB_NAME;
  return String(dbPath || CHAT_CUSTOM_INSTRUCTIONS_DB_NAME).replace(/\/$/, '') + '/' + name + '.md';
}

async function _readChatCustomInstructionNote(dbPath) {
  try {
    const res = await apiFetch('/file?path=' + encodeURIComponent(_chatCustomInstructionDbNotePath(dbPath)), { silentError: true });
    return String(res?.content || '');
  } catch (_) {
    return '';
  }
}

function _chatCustomInstructionOwnsNoteContent(content) {
  const match = String(content || '').match(/^---\s*\r?\n([\s\S]*?)\r?\n---/);
  if (!match) return false;
  const fm = match[1];
  const escapedCategory = CHAT_CUSTOM_INSTRUCTIONS_DB_NAME.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const hasSettingsType = /^type:\s*settings-db\s*$/m.test(fm);
  const hasRole = new RegExp(`(^roles:\\s*\\[[^\\]]*${CHAT_CUSTOM_INSTRUCTIONS_ROLE}[^\\]]*\\]\\s*$)|(^\\s*-\\s*${CHAT_CUSTOM_INSTRUCTIONS_ROLE}\\s*$)`, 'm').test(fm);
  const hasCategory = new RegExp(`^category:\\s*["']?${escapedCategory}["']?\\s*$`, 'm').test(fm);
  return hasSettingsType && (hasRole || hasCategory);
}

async function _chatCustomInstructionNoteExists(dbPath) {
  try {
    await apiFetch('/file?path=' + encodeURIComponent(_chatCustomInstructionDbNotePath(dbPath)));
    return true;
  } catch (_) {
    return false;
  }
}

async function _findChatCustomInstructionSheet() {
  try {
    const dbs = await apiFetch('/databases', { silentError: true });
    for (const item of Array.isArray(dbs) ? dbs : []) {
      const path = String(item?.path || '').trim();
      const name = String(item?.name || path.split('/').pop() || '').trim();
      if (!path || !name.startsWith(CHAT_CUSTOM_INSTRUCTIONS_DB_NAME)) continue;
      const note = await _readChatCustomInstructionNote(path);
      if (_chatCustomInstructionOwnsNoteContent(note)) return path;
    }
  } catch (_) {}
  return '';
}

function _applyChatCustomInstructionViewConfig(dbPath) {
  try {
    const key = typeof getDbViewConfigStorageKey === 'function'
      ? getDbViewConfigStorageKey(dbPath)
      : 'dbViewConfig:' + dbPath;
    const current = JSON.parse(localStorage.getItem(key) || '{}') || {};
    const defaults = _chatCustomInstructionViewConfig();
    const formView = defaults.savedViews[0];
    const currentViews = Array.isArray(current.savedViews) ? current.savedViews.slice() : [];
    const formIndex = currentViews.findIndex(view =>
      view?.viewMode === 'form'
      && (view?.typeSpecific?.form?.formConfig?.id === formView.typeSpecific.form.formConfig.id || view?.name === formView.name)
    );
    const savedViews = formIndex >= 0
      ? currentViews.map((view, index) => index === formIndex ? { ...view, name: formView.name, viewMode: formView.viewMode, typeSpecific: formView.typeSpecific } : view)
      : [formView, ...currentViews];
    const rawIdx = Number.isInteger(current.currentViewIdx) ? current.currentViewIdx : 0;
    const nextIdx = formIndex < 0 && currentViews.length ? rawIdx + 1 : rawIdx;
    localStorage.setItem(key, JSON.stringify({
      ...current,
      propertyTypes: defaults.propertyTypes,
      savedViews,
      currentViewIdx: nextIdx >= 0 && nextIdx < savedViews.length ? nextIdx : 0,
    }));
  } catch (_) {}
}

async function _saveChatCustomInstructionMetadata(dbPath) {
  await apiPut('/db-metadata?path=' + encodeURIComponent(dbPath), {
    type: 'settings-db',
    category: CHAT_CUSTOM_INSTRUCTIONS_DB_NAME,
    roles: [CHAT_CUSTOM_INSTRUCTIONS_ROLE],
    property_types: _chatCustomInstructionPropertyTypes(),
  });
}

async function _chatCustomInstructionCreateSheet() {
  const res = await apiPost('/outliner/add', { type: 'database', label: CHAT_CUSTOM_INSTRUCTIONS_DB_NAME, parent: '' });
  return res?.node?.path || CHAT_CUSTOM_INSTRUCTIONS_DB_NAME;
}

async function _chatCustomInstructionPathType(dbPath) {
  try {
    const res = await apiFetch('/check-type?path=' + encodeURIComponent(dbPath), { silentError: true });
    return String(res?.type || '');
  } catch (_) {
    return '';
  }
}

async function ensureChatCustomInstructionSheet() {
  const settingsOverlay = document.querySelector('.modal-overlay[data-settings-modal="1"]');
  if (settingsOverlay?.getAttribute('aria-busy') === 'true') return '';
  let dbPath = CHAT_CUSTOM_INSTRUCTIONS_DB_NAME;
  let metadataSaved = false;
  const pathType = await _chatCustomInstructionPathType(dbPath);
  const existingNote = pathType === 'database' ? await _readChatCustomInstructionNote(dbPath) : '';
  if (pathType && pathType !== 'unknown' && pathType !== 'database') {
    dbPath = await _findChatCustomInstructionSheet() || await _chatCustomInstructionCreateSheet();
  } else if (pathType === 'database' && !_chatCustomInstructionOwnsNoteContent(existingNote)) {
    dbPath = await _findChatCustomInstructionSheet() || await _chatCustomInstructionCreateSheet();
  }
  if (!await _chatCustomInstructionNoteExists(dbPath)) {
    try {
      await _saveChatCustomInstructionMetadata(dbPath);
      metadataSaved = true;
    } catch (_) {
      dbPath = await _chatCustomInstructionCreateSheet();
    }
  }
  if (!metadataSaved) await _saveChatCustomInstructionMetadata(dbPath);
  _applyChatCustomInstructionViewConfig(dbPath);
  if (settingsOverlay) {
    if (typeof window.closeSettingsModalWithReason !== 'function') return '';
    const settingsClosed = await window.closeSettingsModalWithReason(
      'settings-transition:chat-custom-instructions',
      settingsOverlay,
    );
    if (!settingsClosed) return '';
  }
  if (typeof refreshOutliner === 'function') refreshOutliner();
  if (typeof selectDatabase === 'function') await selectDatabase(dbPath, undefined, { silent: true });
  if (typeof showStatus === 'function') showStatus('カスタムインストラクション入力フォームを開きました');
  return dbPath;
}

function _chatCustomInstructionSection(label, value) {
  const text = String(value || '').trim();
  return text ? `【${label}】\n${text}` : '';
}

function _setChatCustomInstructionValue(key, value) {
  const text = String(value || '').trim();
  if (text) localStorage.setItem(key, text);
  else localStorage.removeItem(key);
}

async function applyChatCustomInstructionsFromForm(fields, cfg, options = {}) {
  const data = fields || {};
  const about = [
    _chatCustomInstructionSection('私について', data['私について']),
    _chatCustomInstructionSection('作品・ジャンル・読者', data['作品・ジャンル・読者']),
    _chatCustomInstructionSection('好み・避けたいこと', data['好み・避けたいこと']),
  ].filter(Boolean).join('\n\n');
  const instructions = [
    _chatCustomInstructionSection('回答方針', data['回答方針']),
    _chatCustomInstructionSection('口調・文体', data['口調・文体']),
    _chatCustomInstructionSection('必ず確認してほしいこと', data['必ず確認してほしいこと']),
    _chatCustomInstructionSection('その他の指示', data['その他の指示']),
  ].filter(Boolean).join('\n\n');
  const wantsSource = String(data['利用範囲'] || '').trim() === '現在のソースフォルダ';
  const source = typeof _chatSourceFolderValue === 'function' ? _chatSourceFolderValue() : '';
  if (wantsSource && !source) {
    if (!options?.silent && typeof showStatus === 'function') showStatus('ソースフォルダを選択してから反映してください', true);
    return { ok: false, scope: 'source', error: 'source-folder-required', formConfig: cfg || null };
  }
  const suffix = wantsSource && source ? ':' + encodeURIComponent(source) : '';
  if (options?.validateOnly) {
    return { ok: true, scope: suffix ? 'source' : 'global', formConfig: cfg || null };
  }
  _setChatCustomInstructionValue('chat-custom-about' + suffix, about);
  _setChatCustomInstructionValue('chat-custom-instructions' + suffix, instructions);
  if (typeof showStatus === 'function') {
    showStatus(suffix ? 'ソースフォルダ用カスタムインストラクションを反映しました' : '全体用カスタムインストラクションを反映しました');
  }
  return { ok: true, scope: suffix ? 'source' : 'global', formConfig: cfg || null };
}

window.ensureChatCustomInstructionSheet = ensureChatCustomInstructionSheet;
window.applyChatCustomInstructionsFromForm = applyChatCustomInstructionsFromForm;

;

/* === gb-chat-skills-sheet.js === */
;
/* gb-chat-skills-sheet.js
 * スキル管理パネル（一覧・作成・編集・削除）
 * サーバー側の隠しフォルダに保存される、再利用可能なチャット向け指示（スキル）を、
 * カスタムインストラクションと同じ操作感（モーダル + フォーム）で管理できるようにする。
 * バックエンド: GET/POST/PUT/DELETE /skills, GET /skills/detail（source_folder スコープ）
 */
(function () {
  'use strict';

  const state = {
    overlay: null,
    modalApi: null,
    restoreFocus: null,
    view: 'list', // 'list' | 'form'
    items: [],
    loadError: '',
    form: null,
  };

  function skEsc(value) {
    return MeldexEscape.html(value);
  }

  function skIcon(name, size) {
    return typeof lucide === 'function' ? lucide(name, size || 14) : '';
  }

  // CLIチャット/カスタムインストラクションと同じ経路で「現在のソースフォルダ」を取得する
  function skSourceFolder() {
    return typeof _chatSourceFolderValue === 'function' ? String(_chatSourceFolderValue() || '') : '';
  }

  function skConfirm(message) {
    if (typeof cfConfirm === 'function') return cfConfirm(message);
    return Promise.resolve(window.confirm(message));
  }

  // triggers はサーバーから配列 or 改行区切り文字列のどちらでも返り得るため、常に配列へ正規化する
  function skTriggersToArray(value) {
    if (Array.isArray(value)) return value.map(v => String(v ?? '').trim()).filter(Boolean);
    return String(value || '').split('\n').map(v => v.trim()).filter(Boolean);
  }

  function skTriggersToTextareaValue(value) {
    return skTriggersToArray(value).join('\n');
  }

  function skTriggerPillsHtml(triggers) {
    const list = skTriggersToArray(triggers);
    if (!list.length) return '';
    const shown = list.slice(0, 3);
    const restCount = list.length - shown.length;
    const pills = shown.map(t => `<span class="gb-pill">${skEsc(t)}</span>`).join('');
    const more = restCount > 0 ? `<span class="gb-pill">+${restCount}</span>` : '';
    return `<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px;">${pills}${more}</div>`;
  }

  /* ---------- モーダルの開閉 ---------- */

  function closeSkillsModal(reason = 'programmatic') {
    if (state.modalApi?.isOpen?.()) return state.modalApi.close(reason);
    return false;
  }

  function ensureSkillsModal() {
    if (state.modalApi?.isOpen?.()) return state.overlay;
    if (typeof window.GBUI?.createModal !== 'function') {
      throw new Error('共通ダイアログを初期化できませんでした。');
    }
    state.restoreFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const root = document.createElement('div');
    root.id = 'skills-panel-root';
    root.className = 'gb-chat-skills-root';
    root.dataset.skRoot = '';
    const modalApi = window.GBUI.createModal({
      id: 'chat-skills',
      title: 'スキル',
      body: root,
      variant: 'mobile-sheet',
      extraClass: 'gb-chat-skills-modal',
      geometryKey: 'chat-skills',
      initialFocus: '[data-e2e-id="skills-panel-close"]',
      returnFocus: state.restoreFocus || undefined,
      closeOnEsc: true,
      closeOnOverlay: true,
      onBeforeClose: () => !state.form?.saving,
      onClose: () => {
        if (state.modalApi !== modalApi) return;
        state.overlay = null;
        state.modalApi = null;
        state.restoreFocus = null;
      },
    });
    modalApi.overlay.classList.add('modal-overlay', 'gb-chat-skills-overlay');
    modalApi.overlay.dataset.chatSkillsModal = '1';
    modalApi.overlay.dataset.e2eId = 'skills-panel-overlay';
    modalApi.modal.dataset.e2eId = 'skills-panel-dialog';
    const title = modalApi.header.querySelector('.gb-modal-title');
    if (title) title.dataset.skTitle = '';
    const closeButton = modalApi.header.querySelector('.gb-modal-close');
    if (closeButton) {
      closeButton.id = 'skills-panel-close';
      closeButton.dataset.skClose = '';
      closeButton.dataset.e2eId = 'skills-panel-close';
    }
    state.overlay = modalApi.overlay;
    state.modalApi = modalApi;
    modalApi.open();
    return modalApi.overlay;
  }

  /* ---------- 描画: 一覧 / フォームの切り替え ---------- */

  function renderRoot() {
    const root = state.overlay?.querySelector('[data-sk-root]');
    if (!root) return;
    const titleEl = state.overlay.querySelector('[data-sk-title]');
    if (state.view === 'form') {
      if (titleEl) titleEl.textContent = state.form?.mode === 'edit' ? 'スキルを編集' : '新規スキルを作成';
      renderFormView(root);
    } else {
      if (titleEl) titleEl.textContent = 'スキル';
      renderListView(root);
    }
  }

  function renderListView(root) {
    root.innerHTML = `
      <section class="gb-section gb-section--boxed" style="margin-bottom:10px;">
        <div class="gb-field-row" style="justify-content:space-between;">
          <div class="gb-section-desc" style="margin:0;">チャットが話題に応じて自動で参照する指示をまとめます ${fieldHelp('名前・説明・トリガー・本文で1つのスキルを構成します。依頼内容が説明やトリガーに合う時だけ、チャットが本文を読み込んで参照します', { e2eId: 'skills-overview-help' })}</div>
          <button type="button" class="gb-btn gb-btn-sm gb-btn-primary" data-sk-create data-e2e-id="skills-create">${skIcon('plus', 14)} 新規作成</button>
        </div>
      </section>
      <div data-sk-alert aria-live="polite"></div>
      <div data-sk-list data-e2e-id="skills-list"><div class="gb-section-desc">読み込み中...</div></div>
    `;
    root.querySelector('[data-sk-create]')?.addEventListener('click', () => openCreateForm());
    loadSkillsList(root);
  }

  async function loadSkillsList(root) {
    const listEl = root.querySelector('[data-sk-list]');
    const alertEl = root.querySelector('[data-sk-alert]');
    if (!listEl) return;
    const sourceFolder = skSourceFolder();
    if (!sourceFolder) {
      state.items = [];
      state.loadError = '';
      if (alertEl) alertEl.innerHTML = '<div class="gb-section-desc">フォルダツリーで対象フォルダを選択すると、そのフォルダのスキルを表示できます。</div>';
      listEl.innerHTML = '';
      return;
    }
    if (alertEl) alertEl.innerHTML = '';
    listEl.innerHTML = '<div class="gb-section-desc">読み込み中...</div>';
    try {
      const res = await apiFetch('/skills?source_folder=' + encodeURIComponent(sourceFolder));
      state.items = Array.isArray(res?.skills) ? res.skills : [];
      state.loadError = '';
    } catch (err) {
      state.items = [];
      state.loadError = String(err?.message || err || '読み込みに失敗しました');
    }
    // 読み込み中に閉じられている/別画面に移動している場合は反映しない
    if (state.view !== 'list' || !root.isConnected) return;
    renderSkillRows(root);
  }

  function renderSkillRows(root) {
    const listEl = root.querySelector('[data-sk-list]');
    const alertEl = root.querySelector('[data-sk-alert]');
    if (!listEl) return;
    if (state.loadError && alertEl) {
      alertEl.innerHTML = `<div class="gb-section-desc" style="color:var(--red);">読み込みに失敗しました: ${skEsc(state.loadError)}</div>`;
    }
    if (!state.items.length) {
      listEl.innerHTML = state.loadError ? '' : '<div class="gb-section-desc">スキルはまだありません。「新規作成」から追加できます。</div>';
      return;
    }
    listEl.innerHTML = state.items.map((item, index) => `
      <div class="gb-skills-row" data-sk-index="${index}" style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding:10px;border:1px solid var(--border);border-radius:6px;margin-bottom:8px;background:var(--bg2);">
        <div style="min-width:0;flex:1;">
          <div style="font-weight:600;overflow-wrap:anywhere;">${skEsc(item.name)}</div>
          ${item.description ? `<div style="color:var(--fg2);font-size:12px;margin-top:2px;overflow-wrap:anywhere;">${skEsc(item.description)}</div>` : ''}
          ${skTriggerPillsHtml(item.triggers)}
        </div>
        <div style="display:flex;gap:6px;flex-shrink:0;">
          <button type="button" class="gb-btn gb-btn-sm" data-sk-edit data-e2e-id="skills-row-edit-${index}" aria-label="スキル「${skEsc(item.name)}」を編集">${skIcon('pencil', 14)} 編集</button>
          <button type="button" class="gb-btn gb-btn-sm gb-btn-danger" data-sk-delete data-e2e-id="skills-row-delete-${index}" aria-label="スキル「${skEsc(item.name)}」を削除">${skIcon('trash2', 14)} 削除</button>
        </div>
      </div>
    `).join('');
    listEl.querySelectorAll('[data-sk-index]').forEach(row => {
      const idx = Number(row.dataset.skIndex);
      const item = state.items[idx];
      if (!item) return;
      row.querySelector('[data-sk-edit]')?.addEventListener('click', () => openEditForm(item));
      row.querySelector('[data-sk-delete]')?.addEventListener('click', () => confirmDeleteSkill(item));
    });
  }

  /* ---------- 作成・編集フォーム ---------- */

  function openCreateForm() {
    state.view = 'form';
    state.form = {
      mode: 'create',
      originalName: '',
      name: '',
      description: '',
      triggersText: '',
      body: '',
      truncated: false,
      loadingDetail: false,
      saving: false,
    };
    renderRoot();
  }

  async function openEditForm(item) {
    const sourceFolder = skSourceFolder();
    if (!sourceFolder) {
      showStatus('フォルダツリーで対象フォルダを選択してください', true);
      return;
    }
    state.view = 'form';
    state.form = {
      mode: 'edit',
      originalName: item.name,
      name: item.name,
      description: item.description || '',
      triggersText: skTriggersToTextareaValue(item.triggers),
      body: '',
      truncated: false,
      loadingDetail: true,
      saving: false,
    };
    renderRoot();
    try {
      const res = await apiFetch('/skills/detail?source_folder=' + encodeURIComponent(sourceFolder) + '&name=' + encodeURIComponent(item.name));
      // 読み込み中に別のスキルへ切り替えた/一覧へ戻った場合は結果を反映しない
      if (!state.form || state.form.mode !== 'edit' || state.form.originalName !== item.name) return;
      if (res?.error) {
        showStatus(res.error, true);
        state.view = 'list';
        state.form = null;
        renderRoot();
        return;
      }
      state.form.name = res.name || item.name;
      state.form.description = res.description || '';
      state.form.triggersText = skTriggersToTextareaValue(res.triggers);
      state.form.body = res.content || '';
      state.form.truncated = !!res.truncated;
      state.form.loadingDetail = false;
      renderRoot();
    } catch {
      if (!state.form || state.form.mode !== 'edit' || state.form.originalName !== item.name) return;
      state.form.loadingDetail = false;
      renderRoot();
    }
  }

  function renderFormView(root) {
    const form = state.form;
    if (!form) {
      state.view = 'list';
      renderListView(root);
      return;
    }
    const disabledAttr = (form.loadingDetail || form.saving) ? ' disabled' : '';
    const truncatedWarning = form.truncated
      ? '<div class="gb-section-desc" style="color:var(--red);margin-bottom:8px;">本文が長いため一部だけ読み込みました。このまま保存すると省略された内容は失われます。</div>'
      : '';
    root.innerHTML = `
      ${form.loadingDetail ? '<div class="gb-section-desc" style="margin-bottom:8px;">読み込み中...</div>' : ''}
      ${truncatedWarning}
      <div class="field gb-field">
        <label class="gb-label" for="sk-form-name">名前</label>
        <input id="sk-form-name" type="text" class="gb-input" data-e2e-id="skills-form-name" placeholder="例: プロット構成レビュー" value="${skEsc(form.name)}"${disabledAttr}>
      </div>
      <div class="field gb-field">
        <label class="gb-label" for="sk-form-description">説明 ${fieldHelp('どんな時に使うスキルかを短く書きます。チャットがこの説明を見て、本文を読み込むかどうかを判断します', { e2eId: 'skills-description-help' })}</label>
        <textarea id="sk-form-description" class="gb-textarea" rows="2" data-e2e-id="skills-form-description" placeholder="例: 長編プロットの構成をレビューするときの観点"${disabledAttr}>${skEsc(form.description)}</textarea>
      </div>
      <div class="field gb-field">
        <label class="gb-label" for="sk-form-triggers">トリガー ${fieldHelp('このスキルを参照してほしい話題やキーワードを1行に1つずつ入力します', { e2eId: 'skills-triggers-help' })}</label>
        <textarea id="sk-form-triggers" class="gb-textarea" rows="3" data-e2e-id="skills-form-triggers" placeholder="例:&#10;プロット&#10;構成レビュー"${disabledAttr}>${skEsc(form.triggersText)}</textarea>
      </div>
      <div class="field gb-field">
        <label class="gb-label" for="sk-form-body">本文 ${fieldHelp('チャットが参照する指示の本文です。Markdown形式で書けます', { e2eId: 'skills-body-help' })}</label>
        <textarea id="sk-form-body" class="gb-textarea" data-e2e-id="skills-form-body" style="min-height:280px;font-family:var(--font-mono, monospace);"${disabledAttr}>${skEsc(form.body)}</textarea>
      </div>
      <div class="gb-field-row" style="justify-content:flex-end;">
        <button type="button" class="gb-btn gb-btn-sm" data-sk-cancel data-e2e-id="skills-form-cancel"${disabledAttr}>キャンセル</button>
        <button type="button" class="gb-btn gb-btn-sm gb-btn-primary" data-sk-save data-e2e-id="skills-form-save"${disabledAttr}>${skIcon('check', 14)} 保存</button>
      </div>
    `;
    root.querySelector('[data-sk-cancel]')?.addEventListener('click', () => {
      state.view = 'list';
      state.form = null;
      renderRoot();
    });
    root.querySelector('[data-sk-save]')?.addEventListener('click', () => saveForm(root));
  }

  async function saveForm(root) {
    const form = state.form;
    if (!form || form.saving || form.loadingDetail) return;
    const nameInput = root.querySelector('#sk-form-name');
    const descInput = root.querySelector('#sk-form-description');
    const triggersInput = root.querySelector('#sk-form-triggers');
    const bodyInput = root.querySelector('#sk-form-body');
    const name = String(nameInput?.value || '').trim();
    if (!name) {
      showStatus('名前を入力してください', true);
      nameInput?.focus();
      return;
    }
    const sourceFolder = skSourceFolder();
    if (!sourceFolder) {
      showStatus('フォルダツリーで対象フォルダを選択してください', true);
      return;
    }
    const payload = {
      source_folder: sourceFolder,
      name,
      description: String(descInput?.value || '').trim(),
      triggers: skTriggersToArray(triggersInput?.value || ''),
      body: String(bodyInput?.value || ''),
    };
    form.saving = true;
    const saveBtn = root.querySelector('[data-sk-save]');
    const cancelBtn = root.querySelector('[data-sk-cancel]');
    if (saveBtn) { saveBtn.disabled = true; saveBtn.setAttribute('aria-busy', 'true'); }
    if (cancelBtn) cancelBtn.disabled = true;
    try {
      const res = form.mode === 'edit'
        ? await apiPut('/skills', { ...payload, original_name: form.originalName })
        : await apiPost('/skills', payload);
      if (res?.error) {
        showStatus(res.error, true);
      } else {
        showStatus(form.mode === 'edit' ? 'スキルを更新しました' : 'スキルを作成しました');
        state.view = 'list';
        state.form = null;
        renderRoot();
        return;
      }
    } catch {
      // apiPost/apiPut(= apiFetch) が失敗理由のトーストを既に表示している
    }
    form.saving = false;
    if (saveBtn?.isConnected) { saveBtn.disabled = false; saveBtn.removeAttribute('aria-busy'); }
    if (cancelBtn?.isConnected) cancelBtn.disabled = false;
  }

  async function confirmDeleteSkill(item) {
    const ok = await skConfirm(`スキル「${item.name}」を削除しますか？`);
    if (!ok) return;
    const sourceFolder = skSourceFolder();
    if (!sourceFolder) {
      showStatus('フォルダツリーで対象フォルダを選択してください', true);
      return;
    }
    try {
      const res = await apiFetch(
        '/skills?name=' + encodeURIComponent(item.name) + '&source_folder=' + encodeURIComponent(sourceFolder),
        { method: 'DELETE' }
      );
      if (res?.error) {
        showStatus(res.error, true);
        return;
      }
      showStatus('スキルを削除しました');
    } catch {
      return; // apiFetch が失敗理由のトーストを既に表示している
    }
    const root = state.overlay?.querySelector('[data-sk-root]');
    if (root && state.view === 'list') loadSkillsList(root);
  }

  /* ---------- 公開API ---------- */

  function ensureChatSkillsSheet() {
    ensureSkillsModal();
    state.view = 'list';
    state.form = null;
    renderRoot();
    return state.overlay;
  }

  window.ensureChatSkillsSheet = ensureChatSkillsSheet;
  window.GBChatSkills = { open: ensureChatSkillsSheet };
})();

;

/* === gb-compare.js === */
;
/* ==============================
   gb-compare.js: ファイル比較ビュー
   2ファイルの並列表示＋行単位の差分ハイライト
   ============================== */

const SIMPLE_DIFF_MIN_LOOKAHEAD = 2000;
const SIMPLE_DIFF_MAX_LOOKAHEAD = 20000;
const COMPARE_LARGE_FILE_SKIP_BYTES = 5 * 1024 * 1024;
const COMPARE_BINARY_PREVIEW_BYTES = 512;
const COMPARE_TEXT_EXTENSIONS = new Set([
  'txt', 'md', 'markdown', 'csv', 'tsv', 'json', 'js', 'mjs', 'cjs', 'css', 'html',
  'htm', 'xml', 'yaml', 'yml', 'log', 'py', 'ts', 'tsx', 'jsx', 'vue', 'svelte',
  'ini', 'cfg', 'conf', 'toml', 'sql', 'svg', 'ics', 'vtt', 'srt',
]);
const COMPARE_BINARY_EXTENSIONS = new Set([
  'png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'ico', 'tif', 'tiff', 'heic',
  'mp4', 'mov', 'avi', 'mkv', 'webm', 'mp3', 'wav', 'flac', 'ogg', 'm4a',
  'pdf', 'zip', '7z', 'rar', 'tar', 'gz', 'bz2', 'xz', 'psd', 'ai', 'clip',
  'blend', 'exe', 'dll', 'bin', 'dat',
]);

/**
 * 比較ビューを開く
 * @param {string} pathA - 左側ファイルパス
 * @param {string} pathB - 右側ファイルパス
 * @param {object} [opts] - opts.containerEl: 描画先を明示指定（省略時はメイン画面の #compare-view 単一実体）。
 *   opts.skipShowView: メイン画面のビュー切替をしない（サブパネル等、独立した描画先へ渡す場合に使う）
 */
async function openCompareView(pathA, pathB, opts) {
  const openOpts = opts || {};
  if (!openOpts.skipShowView) {
    if (typeof GBPaneBridge !== 'undefined' && GBPaneBridge.initialized && typeof navPush === 'function') {
      navPush({
        type: 'compare',
        label: '比較',
        path: `compare:${pathA}|${pathB}`,
        pathA,
        pathB,
      });
    }
    showView('compare');
  }
  const container = openOpts.containerEl || document.getElementById('compare-view');
  if (!container) return false;
  container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--fg2);">読み込み中...</div>';

  try {
    const [dataA, dataB] = await Promise.all([
      _fetchCompareSide(pathA),
      _fetchCompareSide(pathB),
    ]);
    _renderCompareView(container, pathA, pathB, dataA.content || '', dataB.content || '', {
      modeA: dataA.mode,
      modeB: dataB.mode,
    });
    return true;
  } catch (e) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--red,#d16969);">ファイル取得エラー</div>';
    return false;
  }
}

async function _fetchCompareSide(path) {
  const meta = await _fetchCompareMeta(path);
  if (_shouldSkipCompareRawFetch(path, meta)) {
    return {
      mode: 'binary',
      content: await _binaryCompareSummary(path, null, '', meta),
    };
  }
  const response = await fetch(API_BASE + '/file-raw?path=' + encodeURIComponent(path));
  if (!response.ok) throw new Error(`HTTP ${response.status}: ${response.statusText}`);
  const contentType = response.headers.get('content-type') || '';
  const bytes = new Uint8Array(await response.arrayBuffer());
  const decoded = _decodeCompareText(bytes, contentType, path);
  if (decoded?.text != null && _looksTextLike(decoded.text, contentType)) {
    return { mode: 'text', content: decoded.text, encoding: decoded.encoding };
  }
  return {
    mode: 'binary',
    content: await _binaryCompareSummary(path, bytes, contentType, meta),
  };
}

async function _fetchCompareMeta(path) {
  try {
    const response = await fetch(API_BASE + '/file-meta?path=' + encodeURIComponent(path));
    if (!response?.ok || typeof response.json !== 'function') return null;
    const meta = await response.json();
    const size = Number(meta?.size);
    return Number.isFinite(size) ? { ...meta, size } : meta;
  } catch (_) {
    return null;
  }
}

function _decodeUtf8(bytes) {
  return _decodeWithEncoding(bytes, 'utf-8');
}

function _decodeWithEncoding(bytes, encoding) {
  try {
    return new TextDecoder(encoding, { fatal: true }).decode(bytes);
  } catch (_) {
    return null;
  }
}

function _comparePathExtension(path) {
  const name = String(path || '').split(/[\\/]/).pop() || '';
  const dot = name.lastIndexOf('.');
  return dot >= 0 ? name.slice(dot + 1).toLowerCase() : '';
}

function _contentTypeCharset(contentType) {
  const match = String(contentType || '').match(/charset\s*=\s*([^;\s]+)/i);
  return match ? match[1].replace(/^["']|["']$/g, '').toLowerCase() : '';
}

function _shouldTryLegacyTextDecode(contentType, path) {
  const type = String(contentType || '').toLowerCase();
  if (type.startsWith('text/') || /json|xml|javascript|csv|markdown|yaml/.test(type)) return true;
  return COMPARE_TEXT_EXTENSIONS.has(_comparePathExtension(path));
}

function _isLikelyTextPath(path) {
  return COMPARE_TEXT_EXTENSIONS.has(_comparePathExtension(path));
}

function _shouldSkipCompareRawFetch(path, meta) {
  const size = Number(meta?.size);
  if (!Number.isFinite(size) || size <= COMPARE_LARGE_FILE_SKIP_BYTES) return false;
  const ext = _comparePathExtension(path);
  if (COMPARE_BINARY_EXTENSIONS.has(ext)) return true;
  return !_isLikelyTextPath(path);
}

function _looksLikeUtf16(bytes, littleEndian) {
  const sample = bytes?.slice ? bytes.slice(0, Math.min(bytes.length, 512)) : [];
  if (!sample || sample.length < 4) return false;
  let zeroSlots = 0;
  let printableSlots = 0;
  const zeroOffset = littleEndian ? 1 : 0;
  const charOffset = littleEndian ? 0 : 1;
  for (let i = zeroOffset; i < sample.length; i += 2) {
    if (sample[i] === 0) zeroSlots++;
  }
  for (let i = charOffset; i < sample.length; i += 2) {
    const b = sample[i];
    if (b === 9 || b === 10 || b === 13 || (b >= 32 && b <= 126)) printableSlots++;
  }
  return zeroSlots >= Math.max(2, Math.floor(sample.length / 4)) && printableSlots >= Math.max(1, zeroSlots / 2);
}

function _decodeCompareText(bytes, contentType, path) {
  const encodings = [];
  const push = (encoding) => {
    const key = String(encoding || '').trim().toLowerCase();
    if (key && !encodings.includes(key)) encodings.push(key);
  };
  const legacyText = _shouldTryLegacyTextDecode(contentType, path);
  const charset = _contentTypeCharset(contentType);
  if (legacyText) {
    if (bytes[0] === 0xEF && bytes[1] === 0xBB && bytes[2] === 0xBF) push('utf-8');
    if (bytes[0] === 0xFF && bytes[1] === 0xFE) push('utf-16le');
    if (bytes[0] === 0xFE && bytes[1] === 0xFF) push('utf-16be');
  }
  push(charset);
  if (legacyText && !charset) {
    if (_looksLikeUtf16(bytes, true)) push('utf-16le');
    if (_looksLikeUtf16(bytes, false)) push('utf-16be');
  }
  push('utf-8');
  if (legacyText) {
    push('utf-16le');
    push('utf-16be');
    push('shift_jis');
  }
  for (const encoding of encodings) {
    const text = _decodeWithEncoding(bytes, encoding);
    if (text != null && _looksTextLike(text, contentType)) return { text, encoding };
  }
  return null;
}

function _looksTextLike(text, contentType) {
  const type = String(contentType || '').toLowerCase();
  if (!text) return true;
  if (text.includes('\u0000')) return false;
  const controls = text.split('').filter(ch => {
    const code = ch.charCodeAt(0);
    return code < 32 && ch !== '\n' && ch !== '\r' && ch !== '\t';
  }).length;
  if (controls / Math.max(text.length, 1) >= 0.01) return false;
  if (type.startsWith('text/') || /json|xml|javascript|csv|markdown|yaml/.test(type)) return true;
  return true;
}

async function _binaryCompareSummary(path, bytes, contentType, meta) {
  const hasBytes = bytes instanceof Uint8Array;
  const size = hasBytes ? bytes.length : Number(meta?.size || 0);
  const hash = hasBytes ? await _sha256Hex(bytes) : '';
  const preview = hasBytes ? _hexPreview(bytes, COMPARE_BINARY_PREVIEW_BYTES) : '';
  const lines = [
    '[バイナリ/非テキスト形式]',
    `Content-Type: ${contentType || '不明'}`,
    `ファイルサイズ: ${Number.isFinite(size) ? size : '不明'} bytes`,
    `SHA-256: ${hasBytes ? (hash || '計算不可') : '未計算（大きいファイルのため省略）'}`,
    '',
    '先頭バイト（最大512 bytes）:',
    hasBytes ? (preview || '(空ファイル)') : '(大きいファイルのため先頭バイト取得を省略)',
  ];
  return lines.join('\n');
}

async function _sha256Hex(bytes) {
  try {
    if (!globalThis.crypto?.subtle) return '';
    const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes);
    return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, '0')).join('');
  } catch (_) {
    return '';
  }
}

function _hexPreview(bytes, limit) {
  const max = Math.min(bytes.length, limit || 512);
  const rows = [];
  for (let offset = 0; offset < max; offset += 16) {
    const chunk = bytes.slice(offset, Math.min(offset + 16, max));
    const hex = Array.from(chunk).map(b => b.toString(16).padStart(2, '0')).join(' ');
    const ascii = Array.from(chunk).map(b => (b >= 32 && b <= 126) ? String.fromCharCode(b) : '.').join('');
    rows.push(`${offset.toString(16).padStart(8, '0')}  ${hex.padEnd(47, ' ')}  ${ascii}`);
  }
  if (bytes.length > max) rows.push(`... ${bytes.length - max} bytes 省略`);
  return rows.join('\n');
}

function _splitCompareRows(text) {
  const source = String(text ?? '');
  if (!source) return [{ text: '', ending: '' }];
  const rows = [];
  const re = /([^\r\n]*)(\r\n|\r|\n|$)/g;
  let match;
  while ((match = re.exec(source)) !== null) {
    const line = match[1] || '';
    const ending = match[2] || '';
    if (!line && !ending && match.index === source.length) break;
    rows.push({ text: line, ending });
    if (!ending) break;
  }
  return rows.length ? rows : [{ text: '', ending: '' }];
}

function _newlineMarker(ending) {
  if (ending === '\r\n') return ' [CRLF]';
  if (ending === '\r') return ' [CR]';
  if (ending === '\n') return ' [LF]';
  return ' [EOF]';
}

function _lineEndingsDiffer(rowsA, rowsB) {
  const max = Math.max(rowsA.length, rowsB.length);
  for (let i = 0; i < max; i++) {
    if ((rowsA[i]?.ending || '') !== (rowsB[i]?.ending || '')) return true;
  }
  return false;
}

function _prepareCompareLines(textA, textB) {
  const rowsA = _splitCompareRows(textA);
  const rowsB = _splitCompareRows(textB);
  const showNewlineMarkers = _lineEndingsDiffer(rowsA, rowsB);
  const toLines = rows => rows.map(row => row.text + (showNewlineMarkers ? _newlineMarker(row.ending) : ''));
  return { linesA: toLines(rowsA), linesB: toLines(rowsB), showNewlineMarkers };
}

/**
 * 比較ビュー全体を描画
 */
function _renderCompareView(container, pathA, pathB, textA, textB, options) {
  container.innerHTML = '';

  // ヘッダー
  const header = document.createElement('div');
  header.className = 'compare-header';
  const labelA = document.createElement('span');
  labelA.className = 'compare-label';
  labelA.textContent = pathA.split('/').pop();
  labelA.title = pathA;
  const labelB = document.createElement('span');
  labelB.className = 'compare-label';
  labelB.textContent = pathB.split('/').pop();
  labelB.title = pathB;
  const stats = document.createElement('span');
  stats.className = 'compare-stats';
  header.appendChild(labelA);
  header.appendChild(stats);
  header.appendChild(labelB);
  container.appendChild(header);

  // 差分計算
  const { linesA, linesB, showNewlineMarkers } = _prepareCompareLines(textA, textB);
  const diff = _computeDiff(linesA, linesB);

  // 統計
  let added = 0, removed = 0, changed = 0;
  diff.forEach(d => {
    if (d.type === 'add') added++;
    else if (d.type === 'remove') removed++;
    else if (d.type === 'change') changed++;
  });
  stats.textContent = '+' + added + ' -' + removed + ' ~' + changed;
  if (options?.modeA === 'binary' || options?.modeB === 'binary') {
    const mode = document.createElement('span');
    mode.className = 'compare-stats';
    mode.textContent = '非テキスト形式はメタデータと先頭バイトで比較';
    header.appendChild(mode);
  }
  if (showNewlineMarkers) {
    const newlineMode = document.createElement('span');
    newlineMode.className = 'compare-stats';
    newlineMode.textContent = '改行コード差分を表示';
    header.appendChild(newlineMode);
  }

  // 並列パネル
  const body = document.createElement('div');
  body.className = 'compare-body';

  const panelA = document.createElement('div');
  panelA.className = 'compare-panel';
  const panelB = document.createElement('div');
  panelB.className = 'compare-panel';

  diff.forEach(d => {
    const lineA = document.createElement('div');
    const lineB = document.createElement('div');
    lineA.className = 'compare-line';
    lineB.className = 'compare-line';

    switch (d.type) {
      case 'equal':
        lineA.textContent = d.textA;
        lineB.textContent = d.textB;
        break;
      case 'change':
        lineA.className += ' compare-changed';
        lineB.className += ' compare-changed';
        _renderInlineDiff(lineA, lineB, d.textA, d.textB);
        break;
      case 'remove':
        lineA.className += ' compare-removed';
        lineA.textContent = d.textA;
        lineB.className += ' compare-empty';
        break;
      case 'add':
        lineA.className += ' compare-empty';
        lineB.className += ' compare-added';
        lineB.textContent = d.textB;
        break;
    }

    panelA.appendChild(lineA);
    panelB.appendChild(lineB);
  });

  body.appendChild(panelA);
  body.appendChild(panelB);
  container.appendChild(body);
  const syncLineHeights = () => _syncCompareLineHeights(panelA, panelB);
  syncLineHeights();
  requestAnimationFrame(syncLineHeights);
  if (container._compareResizeCleanup) container._compareResizeCleanup();
  window.addEventListener('resize', syncLineHeights);
  container._compareResizeCleanup = () => window.removeEventListener('resize', syncLineHeights);

  // 同期スクロール
  let syncing = false;
  panelA.addEventListener('scroll', () => {
    if (syncing) return;
    syncing = true;
    panelB.scrollTop = panelA.scrollTop;
    syncing = false;
  });
  panelB.addEventListener('scroll', () => {
    if (syncing) return;
    syncing = true;
    panelA.scrollTop = panelB.scrollTop;
    syncing = false;
  });
}

/* --- 差分アルゴリズム（LCS + 行マッチング） --- */

/**
 * 2つの行配列から差分を計算する
 * @returns {Array<{type: 'equal'|'change'|'add'|'remove', textA: string, textB: string}>}
 */
function _computeDiff(linesA, linesB) {
  // LCS (Longest Common Subsequence) で共通行を特定
  const n = linesA.length, m = linesB.length;

  // メモリ効率のため、短い方の行数が1000を超える場合は簡易比較にフォールバック
  if (n > 1000 || m > 1000) return _simpleDiff(linesA, linesB);

  // LCSテーブル構築
  const dp = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (linesA[i - 1] === linesB[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
      else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
    }
  }

  // バックトレースで差分を構築
  const result = [];
  let i = n, j = m;
  const stack = [];

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && linesA[i - 1] === linesB[j - 1]) {
      stack.push({ type: 'equal', textA: linesA[i - 1], textB: linesB[j - 1] });
      i--; j--;
    } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
      stack.push({ type: 'add', textA: '', textB: linesB[j - 1] });
      j--;
    } else {
      stack.push({ type: 'remove', textA: linesA[i - 1], textB: '' });
      i--;
    }
  }

  // 逆順を戻す
  stack.reverse();

  return _coalesceDiffStack(stack);
}

function _syncCompareLineHeights(panelA, panelB) {
  const linesA = Array.from(panelA?.children || []);
  const linesB = Array.from(panelB?.children || []);
  const max = Math.min(linesA.length, linesB.length);
  for (let i = 0; i < max; i++) {
    const a = linesA[i];
    const b = linesB[i];
    if (!a || !b) continue;
    a.style.minHeight = '';
    b.style.minHeight = '';
    const h = Math.max(
      a.getBoundingClientRect?.().height || a.scrollHeight || 0,
      b.getBoundingClientRect?.().height || b.scrollHeight || 0,
    );
    if (h > 0) {
      a.style.minHeight = h + 'px';
      b.style.minHeight = h + 'px';
    }
  }
}

function _coalesceDiffStack(stack) {
  const result = [];
  for (let k = 0; k < stack.length; k++) {
    if (stack[k].type !== 'remove' && stack[k].type !== 'add') {
      result.push(stack[k]);
      continue;
    }
    const removes = [];
    const adds = [];
    while (k < stack.length && (stack[k].type === 'remove' || stack[k].type === 'add')) {
      if (stack[k].type === 'remove') removes.push(stack[k]);
      else adds.push(stack[k]);
      k++;
    }
    k--;
    const paired = Math.min(removes.length, adds.length);
    for (let i = 0; i < paired; i++) {
      result.push({ type: 'change', textA: removes[i].textA, textB: adds[i].textB });
    }
    for (let i = paired; i < removes.length; i++) result.push(removes[i]);
    for (let i = paired; i < adds.length; i++) result.push(adds[i]);
  }
  return result;
}

/**
 * 簡易差分（大きいファイル用）— 近傍の同一行をアンカーにして行ずれを吸収する
 */
function _simpleDiff(linesA, linesB) {
  const result = [];
  const lookahead = Math.min(
    SIMPLE_DIFF_MAX_LOOKAHEAD,
    Math.max(SIMPLE_DIFF_MIN_LOOKAHEAD, Math.ceil(Math.max(linesA.length, linesB.length) * 0.05)),
  );
  let i = 0, j = 0;
  while (i < linesA.length || j < linesB.length) {
    const a = i < linesA.length ? linesA[i] : null;
    const b = j < linesB.length ? linesB[j] : null;
    if (a !== null && b !== null && a === b) {
      result.push({ type: 'equal', textA: a, textB: b });
      i++; j++;
      continue;
    }
    if (a === null) { result.push({ type: 'add', textA: '', textB: b }); j++; continue; }
    if (b === null) { result.push({ type: 'remove', textA: a, textB: '' }); i++; continue; }

    const bAnchor = _findNextLine(linesB, a, j + 1, lookahead);
    const aAnchor = _findNextLine(linesA, b, i + 1, lookahead);
    if (bAnchor >= 0 && (aAnchor < 0 || (bAnchor - j) <= (aAnchor - i))) {
      while (j < bAnchor) { result.push({ type: 'add', textA: '', textB: linesB[j] }); j++; }
      continue;
    }
    if (aAnchor >= 0) {
      while (i < aAnchor) { result.push({ type: 'remove', textA: linesA[i], textB: '' }); i++; }
      continue;
    }
    result.push({ type: 'change', textA: a, textB: b });
    i++; j++;
  }
  return _coalesceDiffStack(result);
}

function _findNextLine(lines, value, start, limit) {
  const end = Math.min(lines.length, start + limit);
  for (let i = start; i < end; i++) {
    if (lines[i] === value) return i;
  }
  return -1;
}

/* --- インライン差分ハイライト --- */

function _compareTextUnits(text) {
  return Array.from(String(text ?? ''));
}

/**
 * 変更行の中で、具体的にどの部分が変わったかをハイライト表示
 */
function _renderInlineDiff(elA, elB, textA, textB) {
  const charsA = _compareTextUnits(textA);
  const charsB = _compareTextUnits(textB);
  // 共通プレフィックス・サフィックスを検出
  let prefix = 0;
  while (prefix < charsA.length && prefix < charsB.length && charsA[prefix] === charsB[prefix]) prefix++;
  let suffixA = charsA.length, suffixB = charsB.length;
  while (suffixA > prefix && suffixB > prefix && charsA[suffixA - 1] === charsB[suffixB - 1]) { suffixA--; suffixB--; }

  const commonPre = charsA.slice(0, prefix).join('');
  const diffPartA = charsA.slice(prefix, suffixA).join('');
  const diffPartB = charsB.slice(prefix, suffixB).join('');
  const commonSuf = charsA.slice(suffixA).join('');

  elA.innerHTML = '';
  elB.innerHTML = '';

  if (commonPre) { elA.appendChild(document.createTextNode(commonPre)); elB.appendChild(document.createTextNode(commonPre)); }

  if (diffPartA) {
    const span = document.createElement('span');
    span.className = 'compare-diff-text';
    span.textContent = diffPartA;
    elA.appendChild(span);
  }
  if (diffPartB) {
    const span = document.createElement('span');
    span.className = 'compare-diff-text';
    span.textContent = diffPartB;
    elB.appendChild(span);
  }

  if (commonSuf) { elA.appendChild(document.createTextNode(commonSuf)); elB.appendChild(document.createTextNode(commonSuf)); }
}

/* --- 比較ファイル選択モーダル --- */

/**
 * 比較するファイルを選択するモーダルを表示
 * @param {string} [preselectedPath] - 1つ目のファイルが既に選択されている場合
 */
function showCompareModal(preselectedPath) {
  const modalId = 'compare-file-modal-' + Date.now().toString(36);
  const hintId = modalId + '-hint';
  const body = document.createElement('div');
  body.className = 'compare-file-modal-body';

  // ファイルA
  const fieldA = document.createElement('div');
  fieldA.className = 'field';
  const inputAId = modalId + '-a';
  const labelA = document.createElement('label');
  labelA.htmlFor = inputAId;
  labelA.textContent = 'ファイルA（左側）';
  fieldA.appendChild(labelA);
  const inputA = document.createElement('input');
  inputA.id = inputAId;
  inputA.className = 'gb-input';
  inputA.type = 'text';
  inputA.dataset.gbPathInput = '1';
  inputA.value = preselectedPath || '';
  inputA.placeholder = 'パスを入力（例: プロット/第1話/候補A.md）';
  fieldA.appendChild(inputA);
  body.appendChild(fieldA);

  // ファイルB
  const fieldB = document.createElement('div');
  fieldB.className = 'field';
  const inputBId = modalId + '-b';
  const labelB = document.createElement('label');
  labelB.htmlFor = inputBId;
  labelB.textContent = 'ファイルB（右側）';
  fieldB.appendChild(labelB);
  const inputB = document.createElement('input');
  inputB.id = inputBId;
  inputB.className = 'gb-input';
  inputB.type = 'text';
  inputB.dataset.gbPathInput = '1';
  inputB.placeholder = 'パスを入力（例: プロット/第1話/候補B.md）';
  fieldB.appendChild(inputB);
  body.appendChild(fieldB);

  const hint = document.createElement('div');
  hint.id = hintId;
  hint.style.cssText = 'font-size:11px;color:var(--fg2);margin-bottom:12px;';
  hint.textContent = 'フォルダツリーのファイルメニューから「比較...」を選んでも開けます。非テキスト形式はメタデータと先頭バイトで比較します。';
  body.appendChild(hint);

  // ボタン
  const cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.className = 'gb-btn gb-btn-sm cancel-btn';
  cancelBtn.textContent = 'キャンセル';
  const compareBtn = document.createElement('button');
  compareBtn.type = 'button';
  compareBtn.textContent = '比較';
  compareBtn.className = 'gb-btn gb-btn-sm gb-btn-primary primary ok-btn';
  let busy = false;
  const modalApi = window.GBUI.createModal({
    id: modalId,
    title: 'ファイル比較',
    body,
    footer: [cancelBtn, compareBtn],
    variant: 'standard',
    geometryKey: 'compare-file-modal',
    minWidth: '0',
    initialFocus: preselectedPath ? inputB : inputA,
    closeLabel: 'ファイル比較を閉じる',
    closeOnEsc: true,
    closeOnOverlay: true,
    resizable: true,
    onBeforeClose: () => !busy,
  });
  const { overlay, modal } = modalApi;
  overlay.classList.add('modal-overlay', 'compare-modal-overlay');
  overlay.dataset.e2eId = 'compare-file-modal-overlay';
  overlay._compareFileModalApi = modalApi;
  modal.classList.add('modal', 'compare-file-modal');
  modal.dataset.e2eId = 'compare-file-modal-dialog';
  modal.style.cssText = 'width:min(500px,calc(100vw - 24px));max-width:100%;overflow:hidden;';
  modal.setAttribute('aria-describedby', hintId);
  const setBusy = (next) => {
    busy = !!next;
    modal.setAttribute('aria-busy', busy ? 'true' : 'false');
    compareBtn.disabled = busy;
  };
  cancelBtn.addEventListener('click', () => modalApi.close('cancel'));
  compareBtn.addEventListener('click', async () => {
    if (busy) return;
    const a = inputA.value.trim();
    const b = inputB.value.trim();
    if (!a || !b) { showStatus('両方のファイルパスを入力してください', true); return; }
    setBusy(true);
    try {
      const ok = await openCompareView(a, b);
      if (ok) {
        setBusy(false);
        modalApi.close('compared');
      }
      else showStatus('比較に失敗しました。パスを確認してください', true);
    } catch (error) {
      console.error('ファイル比較に失敗しました:', error);
      showStatus('比較に失敗しました。パスを確認してください', true);
    } finally {
      if (modalApi.isOpen()) setBusy(false);
    }
  });
  modalApi.open();
}

