        const actionText = String(error?.action || '').trim();
        const errorText = autoContinuing
          ? `${label} の実行が時間内に終わりませんでした。\n\n作業を分割して、自動で続きから実行します。`
          : `${label} がエラーで終了しました。\n\n${error?.message || error}${actionText ? '\n\n' + actionText : ''}`;
