          m.currentPath = r?.new_path || ((destination ? destination + '/' : '') + from.split('/').pop());
          if (typeof renameAppPathReferences === 'function') {
            renameAppPathReferences(from, m.currentPath, { label: m.item.name, fileId: m.fileId, type: m.item.type });
          }
