let _outlinerLoadGeneration = 0;
let _outlinerLoadInFlight = null;
let _outlinerLastLoadCompletedAt = 0;
const OUTLINER_RECENT_LOAD_REUSE_MS = 4000;
const _treeNodeCache = new Map();

