    const controller = {
      open,
      close,
      toggle,
      isOpen,
      focus,
      syncTriggerButtons,
      getElement: () => _panel,
      getHeaderElement: () => _header,
      getBodyElement: () => _body,
      applyRect: (rect) => _applyRect(rect),
      saveRect: () => _saveRect(),
      isMobileSheetActive: _isMobileSheetActive,
    };
