/* ==============================
   デバッグログ
   ============================== */
const _recentLogs = [];
const _RECENT_LOG_MAX = 50;

function _pushRecentLog(level, data) {
  _recentLogs.push({ level, time: new Date().toISOString(), ...data });
  if (_recentLogs.length > _RECENT_LOG_MAX) _recentLogs.shift();
}

function getRecentLogs() { return [..._recentLogs]; }

function _redactCrashLogData(data) {
  const safe = { ...(data || {}) };
  ['path', 'filePath', 'filename', 'fileName', 'targetPath', 'currentPath', 'currentPagePath', 'currentDbPath'].forEach((key) => {
    if (key in safe) safe[key] = '[redacted]';
  });
  return safe;
}

function _sendLog(level, data) {
  try {
    const safeData = _redactCrashLogData(data);
    _pushRecentLog(level, safeData);
    const payload = JSON.stringify({
      level,
      time: new Date().toISOString(),
      view: state?.view || '',
      ...safeData
    });
    if (window.MeldexBetaFeedback?.recordLog) {
      window.MeldexBetaFeedback.recordLog(level, JSON.parse(payload));
    }
    if (window.MeldexBetaFeedback && !window.MeldexBetaFeedback.isCrashReportEnabled()) return;
    if (window.MeldexRuntimeAdapter?.isBrowserDataMode?.()) return;
    navigator.sendBeacon(API_BASE + '/debug-log',
      new Blob([payload], { type: 'text/plain' }));
  } catch {}
}

window.addEventListener('error', (e) => {
  _sendLog('error', {
    message: e.message,
    filename: e.filename,
    lineno: e.lineno,
    colno: e.colno,
    stack: e.error?.stack || ''
  });
});

window.addEventListener('unhandledrejection', (e) => {
  _sendLog('error', {
    message: e.reason?.message || String(e.reason),
    stack: e.reason?.stack || ''
  });
});

/* ==============================
   状態管理
   ============================== */
// API_BASE は meldex-core.js で定義済み

/* ==============================
   file_id キャッシュ（同期参照専用、APIコール禁止）
   ============================== */
const _fileIdCache = {};  // { path: file_id }
const _pathCache = {};    // { file_id: path }
const FILE_ID_MAP_KEY = 'meldex-file-id-map';
let _storedFileIdMapCache = null;

function _normalizeStoredFileIdMap(map) {
  return map && typeof map === 'object' && !Array.isArray(map) ? map : {};
}

function _readLatestStoredFileIdMap() {
  return _normalizeStoredFileIdMap(_readStorageJson(FILE_ID_MAP_KEY, {}));
}

function _storedFileIdMap() {
  if (_storedFileIdMapCache) return _storedFileIdMapCache;
  _storedFileIdMapCache = _readLatestStoredFileIdMap();
  return _storedFileIdMapCache;
}

function _rememberFileId(path, fileId) {
  const previousId = _fileIdCache[path];
  if (previousId && previousId !== fileId && _pathCache[previousId] === path) delete _pathCache[previousId];
  _fileIdCache[path] = fileId;
  _pathCache[fileId] = path;
}

function _registerFileIds(items) {
  const entries = Array.isArray(items)
    ? items.map(item => [item?.path, item?.file_id || item?.fileId])
    : Object.entries(items || {});
  if (!entries.length) return 0;
  const validEntries = entries.filter(([path, fileId]) => !!(path && fileId));
  if (!validEntries.length) return 0;
  const hadStoredCache = _storedFileIdMapCache != null;
  let map = _storedFileIdMap();
  let changed = false;
  let registered = 0;
  for (const [path, fileId] of validEntries) {
    _rememberFileId(path, fileId);
    registered += 1;
    if (map[path] !== fileId) changed = true;
  }
  if (changed) {
    // 別ウィンドウが追加したキーを古いセッションキャッシュで消さないよう、
    // 変更バッチの書き込み直前にだけ最新値を再読込する。初回バッチは
    // _storedFileIdMap() の1回をそのまま使うため、I/Oは最大1 read + 1 write。
    if (hadStoredCache) map = _readLatestStoredFileIdMap();
    let persistedChanged = false;
    for (const [path, fileId] of validEntries) {
      if (map[path] === fileId) continue;
      map[path] = fileId;
      persistedChanged = true;
    }
    _storedFileIdMapCache = map;
    if (persistedChanged) {
      try { localStorage.setItem(FILE_ID_MAP_KEY, JSON.stringify(map)); } catch {}
    }
  }
  return registered;
}

function _registerFileId(path, fileId) {
  if (!path || !fileId) return;
  if (_fileIdCache[path] === fileId && _pathCache[fileId] === path) return;
  _registerFileIds([{ path, file_id: fileId }]);
}

function _pathToFileId(path) {
  if (!path) return '';
  if (_fileIdCache[path]) return _fileIdCache[path];
  const fileId = _storedFileIdMap()[path] || '';
  if (fileId) _rememberFileId(path, fileId);
  return fileId;
}

function _fileIdToPath(fileId) {
  return _pathCache[fileId] || '';
}

function _syncStoredFileIdMapFromStorageEvent(event) {
  if (!event || event.key !== FILE_ID_MAP_KEY) return;
  let next = {};
  try { next = _normalizeStoredFileIdMap(event.newValue ? JSON.parse(event.newValue) : {}); } catch {}
  const previous = _storedFileIdMapCache || {};
  Object.entries(previous).forEach(([path, fileId]) => {
    if (Object.prototype.hasOwnProperty.call(next, path)) return;
    if (_fileIdCache[path] === fileId) delete _fileIdCache[path];
    if (_pathCache[fileId] === path) delete _pathCache[fileId];
  });
  _storedFileIdMapCache = next;
  Object.entries(next).forEach(([path, fileId]) => {
    if (path && fileId) _rememberFileId(path, fileId);
  });
}

if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
  window.addEventListener('storage', _syncStoredFileIdMapFromStorageEvent);
}

function _readStorageJson(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    const parsed = JSON.parse(raw);
    return parsed == null ? fallback : parsed;
  } catch {
    return fallback;
  }
}

function _readStorageArray(key) {
  const parsed = _readStorageJson(key, []);
  return Array.isArray(parsed) ? parsed : [];
}

function _writeStorageJson(key, value) {
  try { localStorage.setItem(key, JSON.stringify(value)); } catch {}
}

function addLongPressHandler(element, handler, options = {}) {
  if (!element || typeof handler !== 'function') return () => {};
  const requestedDelayMs = Number.isFinite(options.duration) ? options.duration : options.delayMs;
  const requestedMoveTolerance = Number.isFinite(options.moveThreshold) ? options.moveThreshold : options.moveTolerance;
  const delayMs = Number.isFinite(requestedDelayMs) ? Math.max(20, requestedDelayMs) : 520;
  const moveTolerance = Number.isFinite(requestedMoveTolerance) ? Math.max(2, requestedMoveTolerance) : 10;
  let timer = null;
  let suppressTimer = null;
  let startX = 0;
  let startY = 0;
  let pointerId = null;
  let fired = false;
  let suppressNextActivation = false;

  const clear = () => {
    if (timer) clearTimeout(timer);
    timer = null;
    pointerId = null;
    fired = false;
  };
  const clearSuppression = () => {
    if (suppressTimer) clearTimeout(suppressTimer);
    suppressTimer = null;
    suppressNextActivation = false;
  };
  const scheduleSuppressionReset = () => {
    if (suppressTimer) clearTimeout(suppressTimer);
    suppressTimer = setTimeout(() => {
      suppressTimer = null;
      suppressNextActivation = false;
    }, 700);
  };
  const consumeSuppressedActivation = (event) => {
    if (!suppressNextActivation) return false;
    if (event.target?.closest?.('input[type="checkbox"], input[type="radio"], .row-select-cb, .row-select-all-cb')) {
      return false;
    }
    event.preventDefault();
    if (typeof event.stopImmediatePropagation === 'function') event.stopImmediatePropagation();
    else event.stopPropagation();
    fired = false;
    clearSuppression();
    return true;
  };
  const createLongPressEvent = (event) => ({
    clientX: startX,
    clientY: startY,
    target: event.target || element,
    currentTarget: element,
    pointerType: event.pointerType || 'touch',
    pointerId: event.pointerId,
    originalEvent: event,
    preventDefault: () => event.preventDefault(),
    stopPropagation: () => event.stopPropagation(),
    stopImmediatePropagation: () => {
      if (typeof event.stopImmediatePropagation === 'function') event.stopImmediatePropagation();
      else event.stopPropagation();
    },
  });

  const cancelIfMoved = (event) => {
    if (pointerId == null || event.pointerId !== pointerId) return;
    if (Math.abs(event.clientX - startX) > moveTolerance || Math.abs(event.clientY - startY) > moveTolerance) clear();
  };

  const onDown = (event) => {
    if (event.pointerType === 'mouse' && options.mouse !== true) return;
    if (event.button != null && event.button !== 0) return;
    clear();
    clearSuppression();
    pointerId = event.pointerId;
    startX = event.clientX;
    startY = event.clientY;
    timer = setTimeout(() => {
      timer = null;
      fired = true;
      suppressNextActivation = true;
      try {
        event.preventDefault();
        event.stopPropagation();
        element.setPointerCapture?.(event.pointerId);
      } catch {}
      handler(createLongPressEvent(event));
    }, delayMs);
  };

  const onUp = (event) => {
    if (pointerId == null || event.pointerId !== pointerId) return;
    const shouldSuppressClick = fired || suppressNextActivation;
    clear();
    if (shouldSuppressClick) {
      suppressNextActivation = true;
      scheduleSuppressionReset();
      event.preventDefault();
      event.stopPropagation();
    }
  };
  const onClick = (event) => {
    consumeSuppressedActivation(event);
  };
  const onContextMenu = (event) => {
    if (!consumeSuppressedActivation(event)) clear();
  };

  element.addEventListener('pointerdown', onDown);
  element.addEventListener('pointermove', cancelIfMoved);
  element.addEventListener('pointerup', onUp);
  element.addEventListener('pointercancel', clear);
  element.addEventListener('pointerleave', clear);
  element.addEventListener('lostpointercapture', clear);
  element.addEventListener('click', onClick, true);
  element.addEventListener('contextmenu', onContextMenu, true);
  window.addEventListener('scroll', clear, true);

  return () => {
    clear();
    clearSuppression();
    element.removeEventListener('pointerdown', onDown);
    element.removeEventListener('pointermove', cancelIfMoved);
    element.removeEventListener('pointerup', onUp);
    element.removeEventListener('pointercancel', clear);
    element.removeEventListener('pointerleave', clear);
    element.removeEventListener('lostpointercapture', clear);
    element.removeEventListener('click', onClick, true);
    element.removeEventListener('contextmenu', onContextMenu, true);
    window.removeEventListener('scroll', clear, true);
  };
}
window.addLongPressHandler = addLongPressHandler;

function _collectPathsNeedingFileIdMigration() {
  const allPaths = new Set();
  const prefixes = ['dbViewConfig:', 'validationRules:', 'entityTemplates:',
                    'gb-cal-mode-', 'gb-cal-date-', 'fv-panel-cfg:'];
  const allKeys = [];
  for (let i = 0; i < localStorage.length; i++) allKeys.push(localStorage.key(i));
  for (const key of allKeys) {
    if (!key) continue;
    for (const prefix of prefixes) {
      if (key.startsWith(prefix)) {
        const path = key.substring(prefix.length);
        if (path && path.length > 1 && !path.match(/^[0-9a-f]{16}$/)) allPaths.add(path);
      }
    }
  }
  const _collectPaths = (items) => {
    if (!Array.isArray(items)) return;
    items.forEach(item => {
      if (item.path) allPaths.add(item.path);
      if (item.children) _collectPaths(item.children);
    });
  };
  _collectPaths(_readStorageArray('meldex-favorites'));
  _collectPaths(_readStorageArray(RECENT_KEY));
  try { JSON.parse(localStorage.getItem('outliner-expanded') || '[]').forEach(p => { if (p && !p.match(/^[0-9a-f]{16}$/)) allPaths.add(p); }); } catch {}
  for (const key of ['outliner-sort', 'outliner-manual-order', 'outliner-locked-items', 'outliner-node-colors']) {
    try { Object.keys(JSON.parse(localStorage.getItem(key) || '{}')).forEach(p => { if (p && !p.match(/^[0-9a-f]{16}$/)) allPaths.add(p); }); } catch {}
  }
  const wf = localStorage.getItem('outliner-work-folder');
  if (wf) allPaths.add(wf);
  const mcp = localStorage.getItem('main-calendar-path');
  if (mcp) allPaths.add(mcp);
  const lastView = _readStorageJson('lastView', null);
  ['path', 'dbPath', 'entityPath'].forEach(key => { if (lastView?.[key]) allPaths.add(lastView[key]); });
  return { allPaths, wf, mcp, prefixes };
}

// file_id マイグレーション: 旧パスキーを file_id キーに一括変換（初回のみ）
async function _migratePathsToFileIds() {
  const { allPaths, wf, mcp, prefixes } = _collectPathsNeedingFileIdMigration();

  if (localStorage.getItem('_file-id-migrated') && allPaths.size === 0) return;
  if (allPaths.size === 0) { localStorage.setItem('_file-id-migrated', '1'); return; }

  // 2. サーバーに一括解決
  let idMap;
  try {
    idMap = await apiPost('/file-ids', { paths: [...allPaths] });
  } catch (e) {
    console.warn('[Meldex] file_id migration failed:', e);
    return; // 失敗時は次回再試行
  }

  // 3. プレフィックス付きキーを変換
  for (const prefix of prefixes) {
    for (const [path, fileId] of Object.entries(idMap)) {
      if (!fileId) continue;
      const oldKey = prefix + path;
      const val = localStorage.getItem(oldKey);
      if (val) {
        localStorage.setItem(prefix + fileId, val);
        localStorage.removeItem(oldKey);
      }
    }
  }

  // 4. favorites に file_id 付与
  const _addFileIds = (items) => {
    if (!Array.isArray(items)) return;
    items.forEach(item => {
      if (item.path && idMap[item.path] && !item.file_id) item.file_id = idMap[item.path];
      if (item.children) _addFileIds(item.children);
    });
  };
  try {
    const favs = JSON.parse(localStorage.getItem('meldex-favorites') || '[]');
    _addFileIds(favs);
    localStorage.setItem('meldex-favorites', JSON.stringify(favs));
  } catch {}

  // 5. recent に file_id 付与
  try {
    const recent = JSON.parse(localStorage.getItem(RECENT_KEY) || '[]');
    _addFileIds(recent);
    localStorage.setItem(RECENT_KEY, JSON.stringify(recent));
  } catch {}

  // 6. lastView に file_id 付与
  try {
    const lv = JSON.parse(localStorage.getItem('lastView') || 'null');
    const lastPath = lv?.path || lv?.dbPath || lv?.entityPath || '';
    if (lv && lastPath && idMap[lastPath]) { lv.file_id = idMap[lastPath]; localStorage.setItem('lastView', JSON.stringify(lv)); }
  } catch {}

  // 7. オブジェクトキーを変換（sort, manual-order, locked, colors）
  for (const key of ['outliner-sort', 'outliner-manual-order', 'outliner-locked-items', 'outliner-node-colors']) {
    try {
      const obj = JSON.parse(localStorage.getItem(key) || '{}');
      let changed = false;
      for (const [path, fileId] of Object.entries(idMap)) {
        if (!fileId || !(path in obj)) continue;
        obj[fileId] = obj[path];
        delete obj[path];
        changed = true;
      }
      if (changed) localStorage.setItem(key, JSON.stringify(obj));
    } catch {}
  }

  // 8. expanded 配列のパスを変換
  try {
    let expanded = JSON.parse(localStorage.getItem('outliner-expanded') || '[]');
    let changed = false;
    expanded = expanded.map(p => {
      if (idMap[p]) { changed = true; return idMap[p]; }
      return p;
    });
    if (changed) localStorage.setItem('outliner-expanded', JSON.stringify(expanded));
  } catch {}

  // 9. work-folder, main-calendar-path
  if (wf && idMap[wf]) localStorage.setItem('outliner-work-folder-id', idMap[wf]);
  if (mcp && idMap[mcp]) localStorage.setItem('main-calendar-id', idMap[mcp]);

  // キャッシュにも登録
  _registerFileIds(idMap);

  localStorage.setItem('_file-id-migrated', '1');
  _refreshOutlinerStorageViewsAfterMigration();
  console.log('[Meldex] file_id migration completed:', Object.values(idMap).filter(Boolean).length, 'paths resolved');
}

function _refreshOutlinerStorageViewsAfterMigration() {
  try { if (typeof renderFavorites === 'function') renderFavorites(); } catch (e) { console.warn('renderFavorites failed after file_id migration', e); }
  try { if (typeof updateRecentItems === 'function') updateRecentItems(); } catch (e) { console.warn('updateRecentItems failed after file_id migration', e); }
}

// エクスプローラー履歴（戻る/進む — Phase 1 でエクスプローラー経由のオープンに限定）
const _legacyNavHistory = [];
let _legacyNavIndex = -1;
let navNavigating = false; // 戻る/進む操作中フラグ

// 最近使用したファイル
const RECENT_MAX = 8;
const RECENT_KEY = 'meldex-recent';

function addRecent(label, path, type) {
  let recent = _readStorageArray(RECENT_KEY);
  recent = recent.filter(r => r.path !== path);
  const fid = _pathToFileId(path);
  recent.unshift({label, path, type, time: Date.now(), ...(fid ? { file_id: fid } : {})});
  if (recent.length > RECENT_MAX) recent.length = RECENT_MAX;
  localStorage.setItem(RECENT_KEY, JSON.stringify(recent));
  if (typeof updateRecentItems === 'function') updateRecentItems();
}

function _mapRenamedPath(path, oldPath, newPath) {
  const current = String(path || '');
  if (!current || !oldPath || !newPath) return current;
  if (current === oldPath) return newPath;
  const oldPrefix = oldPath + '/';
  if (current.startsWith(oldPrefix)) return newPath + current.substring(oldPath.length);
  return current;
}

const APP_PATH_REF_KEYS = [
  'path', 'dbPath', 'scenarioPath', 'scriptnotePath', 'boardPath',
  'pagePath', 'entityPath', 'folderPath', 'mediaPath', 'csvPath', 'versionPath',
  'calendarFile',
];

function _normalizeAppPathForCompare(path) {
  return String(path || '').trim().replace(/\\/g, '/').replace(/\/+$/, '');
}

function _isSameOrChildPath(path, parentPath) {
  const current = _normalizeAppPathForCompare(path);
  const parent = _normalizeAppPathForCompare(parentPath);
  return !!current && !!parent && (current === parent || current.startsWith(parent + '/'));
}

function _matchesDeletedPaths(path, deletedPaths) {
  return deletedPaths.some(deletedPath => _isSameOrChildPath(path, deletedPath));
}

function _appPathRefs(entry) {
  if (!entry || typeof entry !== 'object') return [];
  return APP_PATH_REF_KEYS
    .map(key => entry[key])
    .filter(value => typeof value === 'string' && value.trim());
}

function _entryMatchesDeletedPaths(entry, deletedPaths) {
  return _appPathRefs(entry).some(path => _matchesDeletedPaths(path, deletedPaths));
}

const DELETED_PATH_FALLBACK_AVOID_TAB_TYPES = new Set(['outliner', 'preview', 'detail', 'chat', 'annotation', 'history', 'search', 'version']);

function _deletedPathTabTarget(tab) {
  return _appPathRefs(tab)[0] || _appPathRefs(tab?.state)[0] || '';
}

function _isRemainingContentTabAfterDeletion(tab, deletedPaths) {
  if (!tab || DELETED_PATH_FALLBACK_AVOID_TAB_TYPES.has(tab.type)) return false;
  if (_entryMatchesDeletedPaths(tab, deletedPaths) || _entryMatchesDeletedPaths(tab.state, deletedPaths)) return false;
  const targetPath = _deletedPathTabTarget(tab);
  return !!targetPath;
}

function _findRemainingContentTabAfterDeletion(deletedPaths) {
  if (typeof GBLayout === 'undefined' || typeof GBLayout.getAllPanes !== 'function' || !GBLayout.root) return null;
  const panes = GBLayout.getAllPanes(GBLayout.root).slice().sort((a, b) => {
    if (a.id === GBLayout.activePane) return -1;
    if (b.id === GBLayout.activePane) return 1;
    return 0;
  });
  for (const pane of panes) {
    const activeTab = pane.tabs?.[pane.activeTabIndex];
    if (_isRemainingContentTabAfterDeletion(activeTab, deletedPaths)) {
      return { paneId: pane.id, tabId: activeTab.id };
    }
  }
  for (const pane of panes) {
    for (const tab of pane.tabs || []) {
      if (_isRemainingContentTabAfterDeletion(tab, deletedPaths)) {
        return { paneId: pane.id, tabId: tab.id };
      }
    }
  }
  return null;
}

function _cancelDeletedPathAutosaves(deletedPaths) {
  const pageContent = document.getElementById('page-content');
  if (pageContent?.dataset?.path && _matchesDeletedPaths(pageContent.dataset.path, deletedPaths) && window._noteAutoSaveTimer) {
    clearTimeout(window._noteAutoSaveTimer);
    window._noteAutoSaveTimer = null;
  }
  const freeText = document.getElementById('entity-freetext');
  if (freeText?.dataset?.entityPath && _matchesDeletedPaths(freeText.dataset.entityPath, deletedPaths) && window._ftAutoSaveTimer) {
    clearTimeout(window._ftAutoSaveTimer);
    window._ftAutoSaveTimer = null;
  }
  if (typeof bd !== 'undefined' && bd?.path && _matchesDeletedPaths(bd.path, deletedPaths)) {
    if (window._bdTimer) {
      clearTimeout(window._bdTimer);
      window._bdTimer = null;
    }
    bd.dirty = false;
    bd.path = '';
  }
}

function _clearDeletedLegacyViewHosts(deletedPaths) {
  let cleared = false;
  document.querySelectorAll('[data-gb-legacy-path]').forEach(host => {
    if (!host?.dataset?.gbLegacyPath || !_matchesDeletedPaths(host.dataset.gbLegacyPath, deletedPaths)) return;
    host.dataset.gbLegacyPath = '';
    host.dataset.gbLegacyView = '';
    cleared = true;
  });
  return cleared;
}

function _updatePathRefs(entry, keys, oldPath, newPath) {
  if (!entry) return false;
  let changed = false;
  keys.forEach(key => {
    if (!Object.prototype.hasOwnProperty.call(entry, key)) return;
    const mapped = _mapRenamedPath(entry[key], oldPath, newPath);
    if (mapped !== entry[key]) {
      entry[key] = mapped;
      changed = true;
    }
  });
  return changed;
}

function _readFileIdMap(options) {
  if (options?.fresh === true) {
    _storedFileIdMapCache = _readLatestStoredFileIdMap();
    return _storedFileIdMapCache;
  }
  return _storedFileIdMap();
}

function _rewriteStoredFileIdMapForRename(oldPath, newPath, fileId) {
  const map = _readFileIdMap({ fresh: true });
  let changed = false;
  Object.keys(map).forEach(path => {
    if (!_isSameOrChildPath(path, oldPath)) return;
    const mapped = _mapRenamedPath(path, oldPath, newPath);
    const existingId = map[path];
    delete map[path];
    map[mapped] = (path === oldPath && fileId) ? fileId : existingId;
    changed = true;
  });
  if (fileId && map[newPath] !== fileId) {
    map[newPath] = fileId;
    changed = true;
  }
  if (changed) _writeStorageJson(FILE_ID_MAP_KEY, map);
}

function _purgeStoredFileIdMapForDeletedPaths(deletedPaths) {
  const map = _readFileIdMap({ fresh: true });
  let changed = false;
  Object.keys(map).forEach(path => {
    if (!_matchesDeletedPaths(path, deletedPaths)) return;
    delete map[path];
    changed = true;
  });
  if (changed) _writeStorageJson(FILE_ID_MAP_KEY, map);
}

function _rewriteStoredPathSettingForRename(pathKey, idKey, oldPath, newPath, fileId) {
  const current = localStorage.getItem(pathKey);
  if (!current || !_isSameOrChildPath(current, oldPath)) return;
  const mapped = _mapRenamedPath(current, oldPath, newPath);
  localStorage.setItem(pathKey, mapped);
  const mappedId = (current === oldPath && fileId) ? fileId : _pathToFileId(mapped);
  if (mappedId) localStorage.setItem(idKey, mappedId);
  else localStorage.removeItem(idKey);
}

function _purgeStoredPathSettingForDeletedPaths(pathKey, idKey, deletedPaths) {
  const current = localStorage.getItem(pathKey);
  if (!current || !_matchesDeletedPaths(current, deletedPaths)) return;
  localStorage.removeItem(pathKey);
  localStorage.removeItem(idKey);
}

const PUBLISH_CONFIG_STORAGE_PREFIX = 'gb:publish:';

function _rewritePublishStorageForRename(oldPath, newPath) {
  try {
    const updates = [];
    const removals = [];
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i);
      if (!key || !key.startsWith(PUBLISH_CONFIG_STORAGE_PREFIX)) continue;
      const storedPath = key.substring(PUBLISH_CONFIG_STORAGE_PREFIX.length);
      if (!_isSameOrChildPath(storedPath, oldPath)) continue;
      const mappedPath = _mapRenamedPath(storedPath, oldPath, newPath);
      if (!mappedPath || mappedPath === storedPath) continue;
      updates.push({ key: PUBLISH_CONFIG_STORAGE_PREFIX + mappedPath, value: localStorage.getItem(key) });
      removals.push(key);
    }
    updates.forEach(item => {
      if (item.value != null) localStorage.setItem(item.key, item.value);
    });
    removals.forEach(key => localStorage.removeItem(key));
  } catch {}
}

function _purgePublishStorageForDeletedPaths(deletedPaths) {
  try {
    const removals = [];
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i);
      if (!key || !key.startsWith(PUBLISH_CONFIG_STORAGE_PREFIX)) continue;
      const storedPath = key.substring(PUBLISH_CONFIG_STORAGE_PREFIX.length);
      if (_matchesDeletedPaths(storedPath, deletedPaths)) removals.push(key);
    }
    removals.forEach(key => localStorage.removeItem(key));
  } catch {}
}

function _refreshRenamedCurrentDatabase(previousDbPath, nextDbPath) {
  if (!previousDbPath || previousDbPath === nextDbPath || typeof selectDatabase !== 'function') return;
  const dbViews = new Set(['pivot', 'database', 'tree', 'gallery', 'kanban', 'timeline', 'gantt', 'calendar', 'tasks', 'shifts', 'chart', 'graph', 'form']);
  if (!dbViews.has(state.view)) return;
  const ctx = typeof _currentPaneState === 'function' ? _currentPaneState() : undefined;
  Promise.resolve(selectDatabase(nextDbPath, ctx, {
    silent: true,
    skipRecent: true,
    skipNavPush: true,
    skipSaveLastView: true,
    skipAutoVersion: true,
  })).catch(() => {});
}

function _renameRuntimePathReferences(oldPath, newPath, exactLabel) {
  if (typeof _csvPath !== 'undefined' && _csvPath) {
    _csvPath = _mapRenamedPath(_csvPath, oldPath, newPath);
  }
  if (typeof _folderPath !== 'undefined' && _folderPath) {
    _folderPath = _mapRenamedPath(_folderPath, oldPath, newPath);
  }
  if (typeof bd !== 'undefined' && bd) {
    if (bd.path) bd.path = _mapRenamedPath(bd.path, oldPath, newPath);
    if (bd._loadedBoardPath) bd._loadedBoardPath = _mapRenamedPath(bd._loadedBoardPath, oldPath, newPath);
  }
}

function renameAppPathReferences(oldPath, newPath, opts) {
  if (!oldPath || !newPath || oldPath === newPath) return;
  // 改名/移動後も、開いている各編集面のsingle-flight・競合保留・参加者を
  // 同じ安定文書IDへ束縛したままにする。フォルダ移動では配下aliasも一括更新。
  window.MeldexDocumentSaveCoordinator?.rebindDocumentPathPrefix?.(oldPath, newPath);
  const options = opts || {};
  if (typeof rebindPendingDbViewConfigBackendSave === 'function') {
    rebindPendingDbViewConfigBackendSave(oldPath, newPath, {
      isFolder: options.type === 'folder' || options.type === 'database',
    }).catch(error => console.warn('[Meldex] シート表示設定の保存先を更新できませんでした', error));
  }
  const exactLabel = Object.prototype.hasOwnProperty.call(options, 'label') ? options.label : null;
  const preResolvedId = options.fileId || _pathToFileId(newPath) || _pathToFileId(oldPath) || '';
  const previousDbPath = state.currentDbPath || '';
  if (_fileIdCache[oldPath]) {
    const oldFid = _fileIdCache[oldPath];
    delete _fileIdCache[oldPath];
    _fileIdCache[newPath] = oldFid;
    _pathCache[oldFid] = newPath;
  }
  if (options.fileId) {
    _fileIdCache[newPath] = options.fileId;
    _pathCache[options.fileId] = newPath;
  }
  const oldPrefix = oldPath + '/';
  const newPrefix = newPath + '/';
  Object.keys(_fileIdCache).forEach(cachedPath => {
    if (cachedPath === oldPath || !cachedPath.startsWith(oldPrefix)) return;
    const remapped = newPrefix + cachedPath.substring(oldPrefix.length);
    const fid = _fileIdCache[cachedPath];
    delete _fileIdCache[cachedPath];
    _fileIdCache[remapped] = fid;
    if (fid) _pathCache[fid] = remapped;
  });
  const fileId = preResolvedId || _pathToFileId(newPath) || '';
  _rewriteStoredFileIdMapForRename(oldPath, newPath, fileId);
  _rewriteStoredPathSettingForRename('outliner-work-folder', 'outliner-work-folder-id', oldPath, newPath, fileId);
  _rewriteStoredPathSettingForRename('main-calendar-path', 'main-calendar-id', oldPath, newPath, fileId);
  _rewritePublishStorageForRename(oldPath, newPath);
  let recentChanged = false;
  let layoutChanged = false;
  let legacyTabsChanged = false;

  try {
    const recent = _readStorageArray(RECENT_KEY);
    recent.forEach(entry => {
      if (_updatePathRefs(entry, APP_PATH_REF_KEYS, oldPath, newPath)) recentChanged = true;
      if (entry.path === newPath && exactLabel != null) {
        entry.label = exactLabel;
        recentChanged = true;
      }
      if (entry.path === newPath && fileId) {
        entry.file_id = fileId;
        recentChanged = true;
      }
    });
    if (recentChanged) {
      localStorage.setItem(RECENT_KEY, JSON.stringify(recent));
      if (typeof updateRecentItems === 'function') updateRecentItems();
    }
  } catch {}

  try {
    const lastView = JSON.parse(localStorage.getItem('lastView') || 'null');
    if (lastView && _updatePathRefs(lastView, APP_PATH_REF_KEYS, oldPath, newPath)) {
      if (lastView.path === newPath && exactLabel != null) lastView.label = exactLabel;
      if (lastView.path === newPath && fileId) lastView.file_id = fileId;
      localStorage.setItem('lastView', JSON.stringify(lastView));
    }
  } catch {}

  _tabs.forEach(tab => {
    const wasExact = tab.path === oldPath;
    const mapped = _mapRenamedPath(tab.path, oldPath, newPath);
    if (mapped !== tab.path) {
      tab.path = mapped;
      legacyTabsChanged = true;
    }
    if (wasExact && exactLabel != null && tab.label !== exactLabel) {
      tab.label = exactLabel;
      legacyTabsChanged = true;
    }
  });

  _legacyNavHistory.forEach(entry => {
    if (_updatePathRefs(entry, APP_PATH_REF_KEYS, oldPath, newPath)) layoutChanged = true;
    if (entry.path === newPath && exactLabel != null) entry.label = exactLabel;
  });

  if (typeof GBLayout !== 'undefined' && typeof GBLayout.getAllPanes === 'function' && GBLayout.root) {
    GBLayout.getAllPanes(GBLayout.root).forEach(pane => {
      (pane.tabs || []).forEach(tab => {
        const wasExact = tab.path === oldPath;
        const mapped = _mapRenamedPath(tab.path, oldPath, newPath);
        if (mapped !== tab.path) {
          tab.path = mapped;
          layoutChanged = true;
        }
        if (wasExact && exactLabel != null && tab.label !== exactLabel) {
          tab.label = exactLabel;
          layoutChanged = true;
        }
        if (tab.state && typeof tab.state === 'object') {
          if (_updatePathRefs(tab.state, APP_PATH_REF_KEYS, oldPath, newPath)) {
            layoutChanged = true;
          }
        }
        // タブ単位の戻る/進む履歴（②タブ別ナビ履歴、2026-07-21）: 各タブの navHistory も追随させる
        if (Array.isArray(tab.navHistory)) {
          tab.navHistory.forEach(entry => {
            if (_updatePathRefs(entry, APP_PATH_REF_KEYS, oldPath, newPath)) layoutChanged = true;
            if (entry.path === newPath && exactLabel != null) entry.label = exactLabel;
          });
        }
      });
    });
  }

  if (typeof forEachComponent === 'function') {
    forEachComponent(component => {
      if (!component?.state || typeof component.state !== 'object') return;
      _updatePathRefs(component.state, APP_PATH_REF_KEYS, oldPath, newPath);
    });
  }

  ['currentDbPath', 'currentEntityPath', 'currentPagePath', 'currentBoardPath'].forEach(key => {
    state[key] = _mapRenamedPath(state[key], oldPath, newPath);
  });
  _renameRuntimePathReferences(oldPath, newPath, exactLabel);

  const pageContent = document.getElementById('page-content');
  if (pageContent?.dataset?.path) {
    pageContent.dataset.path = _mapRenamedPath(pageContent.dataset.path, oldPath, newPath);
  }

  if (typeof _sn2Editors !== 'undefined' && _sn2Editors) {
    Object.keys(_sn2Editors).forEach(path => {
      const mapped = _mapRenamedPath(path, oldPath, newPath);
      if (mapped === path) return;
      const editor = _sn2Editors[path];
      delete _sn2Editors[path];
      if (editor) editor._path = mapped;
      _sn2Editors[mapped] = editor;
      // ファイル名とファイルタイトルの一致（2026-07-21）: ツールバーからのタイトル
      // 編集は既にリネームAPIと同期済みだが、ツリー側からの単独リネームでは
      // doc.title と表示中の #title-input が追随していなかったため、ここで揃える。
      // mapped === newPath は「このファイル自体がリネームされた」場合のみ真になり、
      // 親フォルダの移動/リネームでパスだけが変わった場合は除外される。
      if (editor && editor.doc && mapped === newPath && exactLabel != null && editor.doc.title !== exactLabel) {
        editor.doc.title = exactLabel;
        const scriptNoteRoot = editor.host && typeof editor.host.closest === 'function'
          ? editor.host.closest('.gb-scriptnote-root')
          : null;
        const titleInput = scriptNoteRoot ? scriptNoteRoot.querySelector('#title-input') : null;
        // プログラムによる value 代入は change イベントを発火しないため、
        // タイトル入力の change ハンドラ（リネームAPI再呼び出し）は起動しない。
        if (titleInput && titleInput.value !== exactLabel) titleInput.value = exactLabel;
      }
      if (editor && mapped === newPath && (options.etag || options.transport_revision)) {
        editor._lastSavedEtag = options.etag || options.transport_revision;
        if (editor._lastSavedTransportRevision) {
          editor._lastSavedTransportRevision = options.transport_revision || options.etag;
        }
      }
    });
  }

  if (legacyTabsChanged) renderTabs();
  if (layoutChanged && typeof GBLayout !== 'undefined') {
    if (typeof GBLayout.render === 'function') GBLayout.render();
    if (typeof GBLayout.saveLayout === 'function') GBLayout.saveLayout();
  }
  _refreshRenamedCurrentDatabase(previousDbPath, state.currentDbPath);
}

function purgeAppPathReferences(paths) {
  const deletedPaths = (Array.isArray(paths) ? paths : [paths])
    .map(path => String(path || '').trim())
    .filter(Boolean);
  if (!deletedPaths.length) return;
  let recentChanged = false;
  let layoutChanged = false;
  let legacyTabsChanged = false;
  let clearedCurrentView = false;
  _cancelDeletedPathAutosaves(deletedPaths);
  const activePathKey = {
    pivot: 'currentDbPath',
    gallery: 'currentDbPath',
    kanban: 'currentDbPath',
    timeline: 'currentDbPath',
    calendar: 'currentDbPath',
    tasks: 'currentDbPath',
    shifts: 'currentDbPath',
    chart: 'currentDbPath',
    graph: 'currentDbPath',
    entity: 'currentEntityPath',
    page: 'currentPagePath',
    media: 'currentPagePath',
    board: 'currentBoardPath',
  }[state.view] || null;

  Object.keys(_fileIdCache).forEach(cachedPath => {
    if (!_matchesDeletedPaths(cachedPath, deletedPaths)) return;
    const fid = _fileIdCache[cachedPath];
    delete _fileIdCache[cachedPath];
    if (fid && _pathCache[fid] === cachedPath) delete _pathCache[fid];
  });
  _purgeStoredFileIdMapForDeletedPaths(deletedPaths);
  _purgeStoredPathSettingForDeletedPaths('outliner-work-folder', 'outliner-work-folder-id', deletedPaths);
  _purgeStoredPathSettingForDeletedPaths('main-calendar-path', 'main-calendar-id', deletedPaths);
  _purgePublishStorageForDeletedPaths(deletedPaths);

  try {
    const recent = _readStorageArray(RECENT_KEY);
    const nextRecent = recent.filter(entry => {
      return !_entryMatchesDeletedPaths(entry, deletedPaths);
    });
    if (nextRecent.length !== recent.length) {
      localStorage.setItem(RECENT_KEY, JSON.stringify(nextRecent));
      recentChanged = true;
    }
  } catch {}

  try {
    const lastView = JSON.parse(localStorage.getItem('lastView') || 'null');
    if (lastView) {
      if (_entryMatchesDeletedPaths(lastView, deletedPaths)) {
        localStorage.removeItem('lastView');
      }
    }
  } catch {}

  for (let i = _tabs.length - 1; i >= 0; i -= 1) {
    const tab = _tabs[i];
    if (!_entryMatchesDeletedPaths(tab, deletedPaths)) continue;
    if (_activeTabId === tab.id) _activeTabId = null;
    _tabs.splice(i, 1);
    legacyTabsChanged = true;
  }
  if (!_activeTabId && _tabs.length > 0) {
    _activeTabId = _tabs[0].id;
    legacyTabsChanged = true;
  }

  for (let i = _legacyNavHistory.length - 1; i >= 0; i -= 1) {
    const entry = _legacyNavHistory[i];
    if (_entryMatchesDeletedPaths(entry, deletedPaths)) {
      _legacyNavHistory.splice(i, 1);
      if (_legacyNavIndex >= i) _legacyNavIndex = Math.max(-1, _legacyNavIndex - 1);
    }
  }

  const tabsToClose = [];
  if (typeof GBLayout !== 'undefined' && typeof GBLayout.getAllPanes === 'function' && GBLayout.root) {
    GBLayout.getAllPanes(GBLayout.root).forEach(pane => {
      (pane.tabs || []).forEach(tab => {
        if (_entryMatchesDeletedPaths(tab, deletedPaths) || _entryMatchesDeletedPaths(tab.state, deletedPaths)) {
          tabsToClose.push({ paneId: pane.id, tabId: tab.id });
        }
        // タブ単位の戻る/進む履歴（②タブ別ナビ履歴、2026-07-21）: 削除済みパスを参照する履歴エントリを除去
        if (Array.isArray(tab.navHistory)) {
          const prevLen = tab.navHistory.length;
          tab.navHistory = tab.navHistory.filter(entry => !_entryMatchesDeletedPaths(entry, deletedPaths));
          if (tab.navHistory.length !== prevLen) {
            tab.navIndex = tab.navHistory.length ? Math.min(tab.navIndex, tab.navHistory.length - 1) : -1;
            layoutChanged = true;
          }
        }
      });
    });
  }
  tabsToClose.forEach(({ paneId, tabId }) => {
    if (typeof GBTabs !== 'undefined' && typeof GBTabs.closeTab === 'function') {
      GBTabs.closeTab(paneId, tabId);
    }
  });

  ['currentDbPath', 'currentEntityPath', 'currentPagePath', 'currentBoardPath'].forEach(key => {
    if (_matchesDeletedPaths(state[key], deletedPaths)) {
      state[key] = null;
      if (key === activePathKey) clearedCurrentView = true;
    }
  });
  if (!state.currentDbPath) {
    state.pivotData = null;
    state.dbMetadata = null;
  }
  if (_clearDeletedLegacyViewHosts(deletedPaths)) {
    clearedCurrentView = true;
  }

  const pageContent = document.getElementById('page-content');
  if (pageContent?.dataset?.path && _matchesDeletedPaths(pageContent.dataset.path, deletedPaths)) {
    pageContent.dataset.path = '';
    pageContent.contentEditable = 'false';
    pageContent.dataset.loadFailed = '1';
    clearedCurrentView = true;
  }
  const freeText = document.getElementById('entity-freetext');
  if (freeText?.dataset?.entityPath && _matchesDeletedPaths(freeText.dataset.entityPath, deletedPaths)) {
    freeText.dataset.entityPath = '';
    freeText.contentEditable = 'false';
    clearedCurrentView = true;
  }

  if (typeof _csvPath !== 'undefined' && _matchesDeletedPaths(_csvPath, deletedPaths)) {
    if (typeof _csvAutoSaveTimer !== 'undefined' && _csvAutoSaveTimer) {
      clearTimeout(_csvAutoSaveTimer);
      _csvAutoSaveTimer = null;
    }
    if (typeof _csvDirty !== 'undefined') _csvDirty = false;
    _csvPath = '';
    clearedCurrentView = true;
  }

  if (typeof _folderPath !== 'undefined' && _matchesDeletedPaths(_folderPath, deletedPaths)) {
    _folderPath = '';
    if (typeof _folderItems !== 'undefined') _folderItems = [];
    if (typeof _folderSelected !== 'undefined') _folderSelected = null;
    if (typeof _folderSelectedItems !== 'undefined') _folderSelectedItems = [];
    if (state.view === 'folder') clearedCurrentView = true;
  }

  const htmlIframe = document.getElementById('html-iframe');
  if (htmlIframe) {
    const src = htmlIframe.getAttribute('src') || '';
    const decodedSrc = (() => {
      try { return decodeURIComponent(src); } catch { return src; }
    })();
    if (deletedPaths.some(path => decodedSrc.includes(path))) {
      htmlIframe.removeAttribute('src');
      if (state.view === 'html' || state.view === 'media') clearedCurrentView = true;
    }
  }

  const mediaContent = document.getElementById('media-content');
  if (state.view === 'media' && _matchesDeletedPaths(state.currentPagePath, deletedPaths)) {
    if (mediaContent) mediaContent.replaceChildren();
    clearedCurrentView = true;
  }

  if (typeof _sn2Editors !== 'undefined' && _sn2Editors) {
    Object.keys(_sn2Editors).forEach(path => {
      if (!_matchesDeletedPaths(path, deletedPaths)) return;
      const editor = _sn2Editors[path];
      if (editor?._saveTimer) {
        clearTimeout(editor._saveTimer);
        editor._saveTimer = null;
      }
      if (editor) {
        editor._dirty = false;
        editor._path = '';
      }
      delete _sn2Editors[path];
    });
  }

  if (legacyTabsChanged) renderTabs();
  if (recentChanged && typeof updateRecentItems === 'function') updateRecentItems();
  if (layoutChanged && typeof GBLayout !== 'undefined' && typeof GBLayout.saveLayout === 'function') {
    GBLayout.saveLayout();
  }

  if (clearedCurrentView) {
    const fallbackLayoutTab = _findRemainingContentTabAfterDeletion(deletedPaths);
    if (fallbackLayoutTab && typeof GBTabs !== 'undefined' && typeof GBTabs.activateTab === 'function') {
      GBTabs.activateTab(fallbackLayoutTab.paneId, fallbackLayoutTab.tabId);
      return;
    }
    const fallbackTab = _tabs.find(tab => tab.id === _activeTabId) || _tabs[0];
    if (fallbackTab) activateTab(fallbackTab.id);
    else showView('welcome');
  }
}

function _resolveNavHistoryPaneId(paneId) {
  if (typeof GBLayout === 'undefined' || !GBLayout.root) return null;
  // GBLayout に実在しないペインID（旧split用フォールバックctxの 'main'、制作管理
  // 埋め込みシートの未登録合成ID、閉じたペインの残存ID等）は、truthy のまま通すと
  // 後段の findNode 失敗でレガシー共有履歴へ静かに迷子になる。無指定と同じ扱いへ
  // 降格し、アクティブペイン（→先頭ペイン）で解決する。
  const paneExists = !!(paneId && typeof GBLayout.findNode === 'function' && GBLayout.findNode(GBLayout.root, paneId)?.node);
  return (paneExists ? paneId : null) || GBLayout.activePane || GBLayout.findFirstPane?.(GBLayout.root)?.id || null;
}

// タブ単位の履歴へ解決できない場合（GBLayout未初期化・対象ペイン無し・タブ0枚等）の
// フォールバック。旧フラットタブ配列（_tabs）時代の共有履歴を引き続き使う（現状維持）。
function _legacyNavState() {
  return {
    kind: 'legacy',
    paneId: null,
    tabId: null,
    history: _legacyNavHistory,
    get index() { return _legacyNavIndex; },
    set index(v) { _legacyNavIndex = v; },
  };
}

// 戻る/進む履歴はタブ単位（②タブ別ナビ履歴、2026-07-21）。ペインではなく
// 「対象ペインの、今アクティブなタブ」の navHistory/navIndex を解決して返す。
function _getNavState(paneId) {
  const resolvedPaneId = _resolveNavHistoryPaneId(paneId);
  if (!resolvedPaneId || typeof GBLayout === 'undefined' || !GBLayout.root) {
    return _legacyNavState();
  }
  const pane = GBLayout.findNode?.(GBLayout.root, resolvedPaneId)?.node || null;
  if (!pane || !Array.isArray(pane.tabs) || pane.tabs.length === 0) {
    return _legacyNavState();
  }
  const tabIndex = (Number.isInteger(pane.activeTabIndex) && pane.activeTabIndex >= 0 && pane.activeTabIndex < pane.tabs.length)
    ? pane.activeTabIndex
    : 0;
  const tab = pane.tabs[tabIndex];
  if (!tab) return _legacyNavState();
  if (!Array.isArray(tab.navHistory)) tab.navHistory = [];
  if (!Number.isInteger(tab.navIndex)) tab.navIndex = tab.navHistory.length ? tab.navHistory.length - 1 : -1;
  if (tab.navIndex >= tab.navHistory.length) tab.navIndex = tab.navHistory.length - 1;
  return {
    kind: 'tab',
    paneId: resolvedPaneId,
    tabId: tab.id,
    history: tab.navHistory,
    get index() { return tab.navIndex; },
    set index(v) { tab.navIndex = v; },
  };
}

function _refreshPaneNavUi(paneId) {
  if (typeof GBLayout !== 'undefined' && typeof GBLayout.updatePaneNavButtons === 'function') {
    if (paneId) GBLayout.updatePaneNavButtons(paneId);
    else {
      const allPanes = typeof GBLayout.getAllPanes === 'function' ? GBLayout.getAllPanes(GBLayout.root) : [];
      allPanes.forEach(pane => GBLayout.updatePaneNavButtons(pane.id));
    }
  }
}

function _persistPaneNavState(navState) {
  if (navState?.kind === 'tab' && typeof GBLayout !== 'undefined' && typeof GBLayout.saveLayout === 'function') {
    GBLayout.saveLayout();
  }
}

// ナビゲーション履歴記録 + パネルタブ自動更新の起点
// gb-app.js の wrap1 と gb-pane-bridge.js の wrap2 でラップされる
function navPush(entry, paneId) {
  if (navNavigating) return;
  if (!entry || !entry.type) return;
  const navState = _getNavState(paneId);
  const top = navState.history[navState.index];
  if (top && top.type === entry.type && top.path === entry.path) return;
  navState.history.splice(navState.index + 1);
  navState.history.push(entry);
  if (navState.history.length > 50) {
    navState.history.shift();
  }
  navState.index = navState.history.length - 1;
  _refreshPaneNavUi(navState.paneId);
  _persistPaneNavState(navState);
}

function _forcedNavPush(entry, paneId) {
  if (!entry || !entry.type) return;
  const navState = _getNavState(paneId);
  navState.history.splice(navState.index + 1);
  navState.history.push(entry);
  if (navState.history.length > 50) navState.history.shift();
  navState.index = navState.history.length - 1;
  _refreshPaneNavUi(navState.paneId);
  _persistPaneNavState(navState);
}

function _getDbViewScrollContainer(ctx, viewMode) {
  const mode = ['calendar', 'tasks', 'shifts', 'gantt'].includes(viewMode) ? 'timeline' : (viewMode || 'pivot');
  const names = {
    pivot: 'pivot-view',
    tree: 'tree-view',
    gallery: 'gallery-view',
    kanban: 'kanban-view',
    timeline: 'timeline-view',
    chart: 'chart-view',
    graph: 'graph-view',
    form: 'form-view',
  };
  const name = names[mode] || 'pivot-view';
  // メイン画面のビューコンテナは ID（#pivot-view 等。Meldex.html はクラスを持たない）、
  // 制作管理の埋め込みシートはクラス（.pivot-view 等 + 接尾辞付きID）で識別される。
  // クラスだけで探すと本体側が一度もヒットしない（スクロール保存が常に0・復元が素通り）。
  // ctx.containerEl 内を ID→クラスの順で探し、document 全体へのフォールバックでも
  // 埋め込み側の同クラス要素を誤って掴まないよう ID を優先する。
  const scoped = typeof _paneEl === 'function'
    ? (_paneEl(ctx, '#' + name) || _paneEl(ctx, '.' + name))
    : null;
  return scoped || document.getElementById(name) || document.querySelector('.' + name);
}

function _navPushWithViewState(ctx, entityName) {
  ctx = ctx || (typeof _currentPaneState === 'function' ? _currentPaneState() : null);
  const dbPath = ctx?.dbPath || state.currentDbPath;
  if (!dbPath) return;
  const cfg = getDbViewConfig(dbPath);
  const viewIdx = Number.isInteger(ctx?.currentViewIdx) ? ctx.currentViewIdx : cfg.currentViewIdx;
  const viewMode = getCurrentViewMode(dbPath, { ctx });
  const container = _getDbViewScrollContainer(ctx, viewMode);
  let savedView = null;
  try {
    const source = Array.isArray(cfg.savedViews) && Number.isInteger(viewIdx) ? cfg.savedViews[viewIdx] : null;
    savedView = source ? JSON.parse(JSON.stringify(source)) : null;
  } catch {}
  const snapshot = {
    type: 'pivot',
    path: dbPath,
    label: dbPath.split('/').pop() || dbPath,
    viewIdx,
    viewSnapshot: savedView ? { viewIdx, savedView } : null,
    scrollState: {
      scrollLeft: container?.scrollLeft || 0,
      scrollTop: container?.scrollTop || 0,
      focusedEntity: entityName || null,
    },
  };
  const navState = _getNavState(ctx?.paneId);
  const current = navState.history[navState.index];
  if (current && current.path === dbPath && ['pivot', 'database', 'tree', 'gallery', 'kanban', 'timeline', 'chart', 'graph'].includes(current.type)) {
    navState.history[navState.index] = snapshot;
    _refreshPaneNavUi(navState.paneId);
    _persistPaneNavState(navState);
    return;
  }
  _forcedNavPush(snapshot, ctx?.paneId);
}

function navOpen(entry, opts) {
  if (!entry) return;
  const o = opts || undefined;
  if (entry.type === 'page') return openPage(entry.label, entry.path, o);
  if (entry.type === 'csv') return (typeof openCsvFile === 'function') ? openCsvFile(entry.label, entry.path, o) : openPage(entry.label, entry.path, o);
  if (entry.type === 'board') return openBoard(entry.label, entry.path, o);
  if (entry.type === 'entity') return selectEntity(entry.path, o);
  if (entry.type === 'pivot' || entry.type === 'database' || ['tree', 'gallery', 'kanban', 'timeline', 'chart', 'graph', 'form'].includes(entry.type)) {
    if (entry.calendarFile && entry.type === 'timeline' && typeof openCalendarFile === 'function') return openCalendarFile(entry.label, entry.path, o);
    return selectDatabase(entry.path, null, {
      ...(o || {}),
      restoreViewIdx: entry.viewIdx,
      restoreViewSnapshot: entry.viewSnapshot,
      restoreScrollState: entry.scrollState,
      requestedViewMode: entry.viewMode || (!['database'].includes(entry.type) ? entry.type : ''),
    });
  }
  if (entry.type === 'scriptnote' && typeof openScenarioInScriptNote === 'function') return openScenarioInScriptNote(entry.path, entry.label, o);
  if (entry.type === 'media' || entry.type === 'image' || entry.type === 'video' || entry.type === 'audio') {
    return openMedia(
      entry.label,
      entry.path,
      entry.mediaType || (entry.type === 'media' ? 'image' : entry.type),
      { ...(o || {}), viewerUrl: entry.viewerUrl || o?.viewerUrl },
    );
  }
  if (entry.type === 'html') {
    if (entry.urlExternal && typeof openViewer === 'function') return openViewer(entry.path);
    return openHtmlFile(entry.label, entry.path, o);
  }
  if (entry.type === 'folder') return openFolder(entry.label, entry.path, o);
  if (entry.type === 'archive' && typeof openArchiveFolder === 'function') {
    return openArchiveFolder(entry.archivePath, entry.member || '', o);
  }
  if (entry.type === 'calendar') return openCalendarFile(entry.label, entry.path, o);
}
function _withNavFlag(result) {
  if (result && typeof result.then === 'function') {
    return result.finally(() => { navNavigating = false; });
  }
  navNavigating = false;
  return result;
}

// Phase 1: ブラウザ履歴 API（pushState/popstate/back/forward）の利用を廃止
// 戻る/進むは Alt+←/→ ショートカット、マウス戻る/進むボタン、
// 各パネルのタブバー上の履歴ボタンから呼ぶ
let state = {
  vaultPath: null,
  currentDbPath: null,   // 現在選択中のDBフォルダパス
  currentEntityPath: null, // 現在選択中のエントリパス
  currentPagePath: null, // 現在選択中のページパス
  currentBoardPath: null, // 現在選択中のボードパス
  pivotData: null,
  filter: 'disabled', // 'disabled' | 'all' | 'adopted' | 'nobotsu'
  view: 'pivot', // 'pivot' | 'entity' | 'page'
};

/* ==============================
   タブシステム
   ============================== */
const _tabs = []; // {id, label, type, path, icon}
let _activeTabId = null;
let _tabIdCounter = 0;

function _tabIcon(type) {
  if (typeof uiTypeIconName === 'function') {
    const shared = uiTypeIconName(type);
    if (shared) return shared;
  }
  const icons = {pivot:'db',tree:'listTree',gallery:'db',kanban:'db',timeline:'db',media:'galleryThumbnails',html:'globe'};
  return icons[type] || 'page';
}

function addTab(label, type, path) {
  // 同じパス+タイプのタブがあればそちらをアクティブに
  const existing = _tabs.find(t => t.path === path && t.type === type);
  if (existing) { activateTab(existing.id); return existing.id; }
  const id = 'tab-' + (++_tabIdCounter);
  _tabs.push({ id, label: label || '(無題)', type, path, icon: _tabIcon(type) });
  renderTabs();
  activateTab(id);
  return id;
}

function activateTab(tabId) {
  const tab = _tabs.find(t => t.id === tabId);
  if (!tab) return;
  _activeTabId = tabId;
  renderTabs();
  // タブの内容を表示
  navNavigating = true;
  _withNavFlag(navOpen({ type: tab.type, label: tab.label, path: tab.path }));
}

function closeTab(tabId) {
  const idx = _tabs.findIndex(t => t.id === tabId);
  if (idx < 0) return;
  _tabs.splice(idx, 1);
  if (_activeTabId === tabId) {
    // 隣のタブをアクティブに
    if (_tabs.length > 0) {
      const newIdx = Math.min(idx, _tabs.length - 1);
      activateTab(_tabs[newIdx].id);
    } else {
      _activeTabId = null;
      showView('welcome');
    }
  }
  renderTabs();
}

function renderTabs() {
  const bar = document.getElementById('tab-bar');
  if (!bar) return;
  bar.innerHTML = '';
  _tabs.forEach((tab, i) => {
    const el = document.createElement('div');
    el.className = 'tab-item' + (tab.id === _activeTabId ? ' active' : '');
    el.dataset.tabIdx = i;
    el.addEventListener('click', (e) => { if (!e.target.closest('.tab-close')) activateTab(tab.id); });
    el.onpointerdown = (e) => { if (e.button === 1) { e.preventDefault(); closeTab(tab.id); } };
    const iconSvg = typeof lucide === 'function' ? lucide(tab.icon, 14) : '';
    el.innerHTML = `${iconSvg}<span class="tab-label">${esc(tab.label)}</span><span class="tab-close" data-action="closeTab('${tab.id}')">${lucide('x', 12)}</span>`;

    // D&D: タブ順序入替+ウィンドウ分離
    el.draggable = true;
    el.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('application/x-tab-idx', String(i));
      e.dataTransfer.effectAllowed = 'move';
      el.classList.add('dragging');
    });
    el.addEventListener('dragend', () => { el.classList.remove('dragging'); _clearTabDragIndicators(); });
    el.addEventListener('dragover', (e) => {
      e.preventDefault();
      _clearTabDragIndicators();
      const rect = el.getBoundingClientRect();
      if (e.clientX < rect.left + rect.width / 2) el.classList.add('drag-over-left');
      else el.classList.add('drag-over-right');
    });
    el.addEventListener('dragleave', () => { el.classList.remove('drag-over-left', 'drag-over-right'); });
    el.addEventListener('drop', (e) => {
      e.preventDefault();
      _clearTabDragIndicators();
      const fromIdx = parseInt(e.dataTransfer.getData('application/x-tab-idx'));
      if (isNaN(fromIdx) || fromIdx === i) return;
      const rect = el.getBoundingClientRect();
      const insertBefore = e.clientX < rect.left + rect.width / 2;
      const moved = _tabs.splice(fromIdx, 1)[0];
      let toIdx = insertBefore ? i : i + 1;
      if (fromIdx < i) toIdx--;
      _tabs.splice(toIdx, 0, moved);
      renderTabs();
    });

    bar.appendChild(el);
  });
}

function _clearTabDragIndicators() {
  document.querySelectorAll('.tab-item.drag-over-left,.tab-item.drag-over-right').forEach(el => {
    el.classList.remove('drag-over-left', 'drag-over-right');
  });
}

// Meldex内部タブとして開く
function _normalizeOpenTypeForNav(type) {
  if (type === 'database') return 'pivot';
  if (type === 'scenario') return 'scriptnote';
  return type || 'page';
}

function _openInNewTab(label, path, type) {
  const openType = _normalizeOpenTypeForNav(type);
  const id = 'tab-' + (++_tabIdCounter);
  _tabs.push({ id, label: label || '(無題)', type: openType, path: path || '', icon: _tabIcon(openType) });
  _activeTabId = id;
  renderTabs();
  // コンテンツを開く
  _addingTab = true;
  try {
    return navOpen({ type: openType, label, path });
  } finally {
    _addingTab = false;
  }
}

// タブバーへのフォルダツリーD&Dドロップ
(function() {
  const bar = document.getElementById('tab-bar');
  if (!bar) return;
  bar.addEventListener('dragover', (e) => {
    // Meldexノードまたはタブ移動のみ受け入れ
    e.preventDefault();
    e.dataTransfer.dropEffect = 'link';
    // ドロップ位置のインジケーター表示
    _clearTabDragIndicators();
    const tabEls = [...bar.querySelectorAll('.tab-item')];
    for (const tabEl of tabEls) {
      const rect = tabEl.getBoundingClientRect();
      if (e.clientX < rect.left + rect.width / 2) {
        tabEl.classList.add('drag-over-left');
        return;
      } else if (e.clientX < rect.right) {
        tabEl.classList.add('drag-over-right');
        return;
      }
    }
    // 全タブの右側
    if (tabEls.length > 0) tabEls[tabEls.length - 1].classList.add('drag-over-right');
  });
  bar.addEventListener('dragleave', (e) => {
    if (!bar.contains(e.relatedTarget)) _clearTabDragIndicators();
  });
  bar.addEventListener('drop', (e) => {
    e.preventDefault();
    _clearTabDragIndicators();
    const draggedTabIndex = e.dataTransfer.getData('application/x-tab-idx');
    if (draggedTabIndex) {
      if (e.target.closest?.('.tab-item')) return;
      const fromIdx = parseInt(draggedTabIndex);
      if (isNaN(fromIdx) || fromIdx < 0 || fromIdx >= _tabs.length || fromIdx === _tabs.length - 1) return;
      const moved = _tabs.splice(fromIdx, 1)[0];
      _tabs.push(moved);
      renderTabs();
      return;
    }
    // Meldexノードのドロップ
    const cfData = e.dataTransfer.getData('application/x-meldex-node');
    if (!cfData) return;
    try {
      const { name, path, type } = JSON.parse(cfData);
      const openType = _normalizeOpenTypeForNav(type);
      // 挿入位置を決定
      const tabEls = [...bar.querySelectorAll('.tab-item')];
      let insertIdx = _tabs.length;
      for (let i = 0; i < tabEls.length; i++) {
        const rect = tabEls[i].getBoundingClientRect();
        if (e.clientX < rect.left + rect.width / 2) { insertIdx = i; break; }
      }
      const id = 'tab-' + (++_tabIdCounter);
      const newTab = { id, label: name || '(無題)', type: openType, path: path || '', icon: _tabIcon(openType) };
      _tabs.splice(insertIdx, 0, newTab);
      _activeTabId = id;
      renderTabs();
      _addingTab = true;
      try {
        navOpen({ type: openType, label: name, path });
      } finally {
        _addingTab = false;
      }
    } catch {}
  });
})();

// タブ右クリックメニュー（＋長押しでも同メニュー）
function _handleTabBarContextmenu(e) {
  const tabEl = e.target.closest('.tab-item');
  if (!tabEl) return;
  e.preventDefault();
  const idx = parseInt(tabEl.dataset.tabIdx);
  const tab = _tabs[idx];
  if (!tab) return;

  document.querySelectorAll('.tab-context-menu').forEach(el => el.remove());
  const menu = document.createElement('div');
  menu.className = 'gb-context-menu tab-context-menu';
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', 'タブ操作');
  if (!tabEl.hasAttribute('tabindex')) tabEl.tabIndex = -1;
  let menuClosed = false;
  let closeOnPointer = null;
  let closeOnKey = null;
  function closeMenu(restoreFocus = false) {
    if (menuClosed) return;
    menuClosed = true;
    document.removeEventListener('pointerdown', closeOnPointer, true);
    document.removeEventListener('keydown', closeOnKey, true);
    menu.remove();
    if (restoreFocus && typeof tabEl.focus === 'function') {
      try { tabEl.focus({ preventScroll: true }); } catch { tabEl.focus(); }
    }
  }
  { const z = _getZoom(); menu.style.left = (e.clientX / z) + 'px'; menu.style.top = (e.clientY / z) + 'px'; }
  function addMI(label, fn, disabled = false, e2eId = '') {
    const mi = document.createElement('button');
    mi.type = 'button';
    mi.className = 'gb-context-menu-item';
    mi.setAttribute('role', 'menuitem');
    mi.textContent = label;
    mi.disabled = !!disabled;
    if (disabled) mi.setAttribute('aria-disabled', 'true');
    if (e2eId) mi.dataset.e2eId = e2eId;
    mi.addEventListener('click', () => { closeMenu(false); fn(); });
    menu.appendChild(mi);
  }
  function closeTabsOnSide(side) {
    const targetIndex = _tabs.findIndex(item => item.id === tab.id);
    if (targetIndex < 0) return;
    const shouldClose = (_, index) => side === 'left' ? index < targetIndex : index > targetIndex;
    const activeWillClose = _tabs.some((item, index) => item.id === _activeTabId && shouldClose(item, index));
    const remaining = _tabs.filter((item, index) => !shouldClose(item, index));
    if (remaining.length === _tabs.length) return;
    _tabs.splice(0, _tabs.length, ...remaining);
    activateTab(activeWillClose ? tab.id : (_activeTabId || tab.id));
  }
  addMI('新しいウィンドウで開く', () => {
    const openType = _normalizeOpenTypeForNav(tab.type);
    const url = '/?open=' + encodeURIComponent(openType) + '&path=' + encodeURIComponent(tab.path || '') + '&label=' + encodeURIComponent(tab.label || '');
    Promise.resolve(_open_app_window_js(url)).then((ok) => {
      if (ok) closeTab(tab.id);
      else if (typeof showStatus === 'function') showStatus('新しいウィンドウを開けませんでした', true);
    });
  }, false, 'tab-menu-new-window');
  addMI('タブを閉じる', () => closeTab(tab.id), false, 'tab-menu-close');
  addMI('左のタブを閉じる', () => closeTabsOnSide('left'), idx <= 0, 'tab-menu-close-left');
  addMI('右のタブを閉じる', () => closeTabsOnSide('right'), idx >= _tabs.length - 1, 'tab-menu-close-right');
  addMI('他のタブをすべて閉じる', () => {
    _tabs.splice(0, _tabs.length, tab);
    activateTab(tab.id);
  }, false, 'tab-menu-close-others');
  document.body.appendChild(menu);
  clampPopupToViewport(menu);
  const focusableItems = () => [...menu.querySelectorAll('.gb-context-menu-item')];
  closeOnPointer = function closeTabContextMenuOnPointer(ev) {
    if (!menu.contains(ev.target)) closeMenu(false);
  };
  closeOnKey = function closeTabContextMenuOnKey(ev) {
    if (ev.key === 'Escape') {
      ev.preventDefault();
      closeMenu(true);
      return;
    }
    const items = focusableItems();
    if (!items.length) return;
    const currentIndex = Math.max(0, items.indexOf(document.activeElement));
    let nextIndex = currentIndex;
    if (ev.key === 'ArrowDown') nextIndex = (currentIndex + 1) % items.length;
    else if (ev.key === 'ArrowUp') nextIndex = (currentIndex - 1 + items.length) % items.length;
    else if (ev.key === 'Home') nextIndex = 0;
    else if (ev.key === 'End') nextIndex = items.length - 1;
    else return;
    ev.preventDefault();
    items[nextIndex]?.focus();
  };
  setTimeout(() => {
    if (menuClosed || !menu.isConnected) return;
    document.addEventListener('pointerdown', closeOnPointer, true);
    document.addEventListener('keydown', closeOnKey, true);
  }, 0);
  menu.querySelector('.gb-context-menu-item')?.focus();
}
{
  const _tabBar = document.getElementById('tab-bar');
  _tabBar?.addEventListener('contextmenu', _handleTabBarContextmenu);
  if (_tabBar && typeof addLongPressHandler === 'function') {
    addLongPressHandler(_tabBar, _handleTabBarContextmenu);
  }
}

// Chrome --appモードで新しいウィンドウを開く（JS版）
async function _open_app_window_js(url) {
  const resolvedUrl = new URL(url, location.origin).toString();
  try {
    const res = await fetch(API_BASE + '/open-app-window', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ url: resolvedUrl }),
    });
    if (res.ok) return true;
  } catch {}
  const opened = window.open(resolvedUrl, '_blank', 'width=1200,height=800,menubar=no,toolbar=no,location=no');
  return !!opened;
}

// 既存のopen関数をフックしてタブを追加（再帰防止付き）
let _addingTab = false;
const _origNavPush = navPush;
navPush = function(entry, paneId) {
  _origNavPush(entry, paneId);
  if (_addingTab || navNavigating) return; // activateTab→navOpen→openX→navPush の再帰を防止
  if (entry && entry.type) {
    const label = entry.label || entry.path?.split('/').pop() || '(無題)';
    if (entry.type === 'welcome') return;
    _addingTab = true;
    try {
      // タブを追加（既存ならアクティブ化のみ、navOpenは呼ばない）
      const path = entry.path || entry.dbPath || '';
      const type = typeof _normalizeOpenTypeForNav === 'function' ? _normalizeOpenTypeForNav(entry.type) : entry.type;
      const existing = _tabs.find(t => t.path === path && t.type === type);
      if (existing) {
        _activeTabId = existing.id;
        renderTabs();
      } else {
        // 現在のアクティブタブを上書き（新しいタブを追加しない）
        const activeTab = _tabs.find(t => t.id === _activeTabId);
        if (activeTab) {
          activeTab.label = label || '(無題)';
          activeTab.type = type;
          activeTab.path = path;
          activeTab.icon = _tabIcon(type);
          renderTabs();
        } else {
          const id = 'tab-' + (++_tabIdCounter);
          _tabs.push({ id, label: label || '(無題)', type, path, icon: _tabIcon(type) });
          _activeTabId = id;
          renderTabs();
        }
      }
    } finally {
      _addingTab = false;
    }
  }
};

// 履歴再生では navPush() が navNavigating により記録を抑止するため、同じタブの
// 表示先は履歴エントリから先に確定する。これにより、読み込み側の非同期処理や
// ペインブリッジ初期化状態に左右されず、戻る/進むが別タブを汚さない。
function _applyNavEntryToBoundTab(navState, entry) {
  if (navState?.kind !== 'tab' || !navState.paneId || !navState.tabId || !entry) return true;
  if (typeof GBLayout === 'undefined') return true;
  const pane = GBLayout.findNode?.(GBLayout.root, navState.paneId)?.node;
  const tab = pane?.tabs?.find(candidate => candidate.id === navState.tabId);
  if (!tab) return true;
  const nextType = typeof _normalizeOpenTypeForNav === 'function'
    ? _normalizeOpenTypeForNav(entry.type)
    : entry.type;
  const typeChanged = tab.type !== nextType;
  const applyEntry = () => {
    tab.type = nextType;
    tab.label = entry.label || entry.path?.split('/').pop() || '(無題)';
    tab.path = entry.path || entry.dbPath || '';
    tab.icon = typeof GBTabs !== 'undefined' && typeof GBTabs.tabIcon === 'function'
      ? GBTabs.tabIcon(nextType)
      : tab.icon;
    tab.state = {
      ...(typeChanged ? {} : (tab.state || {})),
      ...(entry.mediaType ? { mediaType: entry.mediaType } : {}),
      ...(entry.viewerUrl ? { viewerUrl: entry.viewerUrl } : {}),
    };
    if (typeChanged) GBLayout.render();
    else {
      const labelEl = GBLayout.paneMap?.[navState.paneId]?.el?.querySelector('.gb-tab.active .gb-tab-label');
      if (labelEl) labelEl.textContent = tab.label;
    }
    return true;
  };
  if (typeChanged && typeof removeComponentInstance === 'function') {
    const component = typeof getComponentInstance === 'function' ? getComponentInstance(tab.id) : null;
    if (component && typeof removeComponentInstanceSafely === 'function') {
      return removeComponentInstanceSafely(tab.id).then(ok => ok ? applyEntry() : false);
    }
    if (removeComponentInstance(tab.id) === false) return false;
  }
  return applyEntry();
}

function _finishPaneHistoryNavigation(navState, nextIndex, entry) {
  navState.index = nextIndex;
  navNavigating = true;
  if (navState.paneId && typeof GBLayout !== 'undefined') GBLayout.setActivePane(navState.paneId, { sync: true });
  _withNavFlag(navOpen(entry));
  if (navState.kind === 'legacy') {
    const tab = _tabs.find(t => t.path === entry.path && t.type === entry.type);
    if (tab) { _activeTabId = tab.id; renderTabs(); }
  }
  _refreshPaneNavUi(navState.paneId);
  _persistPaneNavState(navState);
  return true;
}

function _continuePaneHistoryAfterFlush(navState, nextIndex, entry, applied) {
  if (!applied || typeof applied.then !== 'function') {
    return applied === false ? false : _finishPaneHistoryNavigation(navState, nextIndex, entry);
  }
  navNavigating = true;
  applied.then((ok) => {
    if (!ok) {
      navNavigating = false;
      return;
    }
    _finishPaneHistoryNavigation(navState, nextIndex, entry);
  }).catch((error) => {
    navNavigating = false;
    if (typeof showStatus === 'function') showStatus('画面遷移前の保存に失敗しました: ' + (error?.message || error), true);
  });
  return true;
}

// ナビゲーション履歴の戻る/進む
function navBack(paneId) {
  const railState = typeof GBPanelSet !== 'undefined' && typeof GBPanelSet.rightRailNavigationState === 'function'
    ? GBPanelSet.rightRailNavigationState(paneId)
    : null;
  if (railState) return GBPanelSet.navigateRightRail(paneId, -1);
  const navState = _getNavState(paneId);
  if (navState.index <= 0) return false;
  const nextIndex = navState.index - 1;
  const entry = navState.history[nextIndex];
  if (!entry) return false;
  try {
    return _continuePaneHistoryAfterFlush(
      navState, nextIndex, entry, _applyNavEntryToBoundTab(navState, entry),
    );
  } catch (e) {
    navNavigating = false;
    throw e;
  }
}
function navForward(paneId) {
  const railState = typeof GBPanelSet !== 'undefined' && typeof GBPanelSet.rightRailNavigationState === 'function'
    ? GBPanelSet.rightRailNavigationState(paneId)
    : null;
  if (railState) return GBPanelSet.navigateRightRail(paneId, 1);
  const navState = _getNavState(paneId);
  if (navState.index < 0 || navState.index >= navState.history.length - 1) return false;
  const nextIndex = navState.index + 1;
  const entry = navState.history[nextIndex];
  if (!entry) return false;
  try {
    return _continuePaneHistoryAfterFlush(
      navState, nextIndex, entry, _applyNavEntryToBoundTab(navState, entry),
    );
  } catch (e) {
    navNavigating = false;
    throw e;
  }
}

function showPaneNavHistoryDropdown(e, paneId, direction) {
  e.preventDefault();
  e.stopPropagation();
  document.querySelectorAll('.nav-history-dropdown').forEach(el => el.remove());
  const navState = _getNavState(paneId);
  const items = [];
  if (direction === 'back') {
    for (let i = navState.index - 1; i >= Math.max(0, navState.index - 15); i--) items.push({ index: i, entry: navState.history[i] });
  } else {
    for (let i = navState.index + 1; i <= Math.min(navState.history.length - 1, navState.index + 15); i++) items.push({ index: i, entry: navState.history[i] });
  }
  if (items.length === 0) return;

  const dd = document.createElement('div');
  dd.className = 'ab-dropdown nav-history-dropdown';
  dd.setAttribute('role', 'menu');
  dd.setAttribute('aria-label', direction === 'back' ? '戻る履歴' : '進む履歴');
  dd.style.cssText = 'position:fixed;z-index:9999;min-width:220px;max-width:360px;max-height:400px;overflow-y:auto;';
  items.forEach(({ index, entry }) => {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = 'ab-dropdown-item';
    item.setAttribute('role', 'menuitem');
    item.textContent = entry.label || entry.path?.split('/').pop() || '(不明)';
    item.title = entry.path || '';
    item.addEventListener('click', async () => {
      try {
        const applied = await _applyNavEntryToBoundTab(navState, entry);
        if (!applied) return;
        _finishPaneHistoryNavigation(navState, index, entry);
      } catch (e) {
        navNavigating = false;
        throw e;
      }
      _refreshPaneNavUi(navState.paneId);
      _persistPaneNavState(navState);
      closeDropdown(false);
    });
    dd.appendChild(item);
  });
  const anchor = e.currentTarget || e.target?.closest?.('button') || e.target;
  const rect = anchor.getBoundingClientRect();
  document.body.appendChild(dd);
  if (typeof positionPopup === 'function') positionPopup(dd, rect, { prefer: 'bottom', gap: 2 });
  else {
    const z = _getZoom();
    dd.style.left = (rect.left / z) + 'px';
    dd.style.top = (rect.bottom / z + 2) + 'px';
    clampPopupToViewport(dd);
  }
  const firstItem = dd.querySelector('.ab-dropdown-item');
  let dropdownClosed = false;
  function closeDropdown(restoreFocus) {
    if (dropdownClosed) return;
    dropdownClosed = true;
    dd.remove();
    document.removeEventListener('pointerdown', closeOnPointer, true);
    document.removeEventListener('keydown', closeOnKey, true);
    if (restoreFocus && anchor?.focus) anchor.focus();
  }
  function closeOnPointer(ev) {
    if (!dd.contains(ev.target)) closeDropdown(false);
  }
  function closeOnKey(ev) {
    if (ev.key === 'Escape') {
      ev.preventDefault();
      closeDropdown(true);
      return;
    }
    const menuItems = [...dd.querySelectorAll('.ab-dropdown-item')];
    const current = menuItems.indexOf(document.activeElement);
    if (ev.key === 'ArrowDown' && menuItems.length) {
      ev.preventDefault();
      menuItems[(current + 1 + menuItems.length) % menuItems.length].focus();
    } else if (ev.key === 'ArrowUp' && menuItems.length) {
      ev.preventDefault();
      menuItems[(current - 1 + menuItems.length) % menuItems.length].focus();
    } else if (ev.key === 'Home' && menuItems.length) {
      ev.preventDefault();
      menuItems[0].focus();
    } else if (ev.key === 'End' && menuItems.length) {
      ev.preventDefault();
      menuItems[menuItems.length - 1].focus();
    }
  }
  setTimeout(() => {
    if (dropdownClosed || !dd.isConnected) return;
    document.addEventListener('pointerdown', closeOnPointer, true);
    document.addEventListener('keydown', closeOnKey, true);
  }, 0);
  firstItem?.focus();
}

function showNavHistoryDropdown(e, direction) {
  return showPaneNavHistoryDropdown(e, null, direction);
}

function updateNavBreadcrumb() {}

let _pointerNavTargetId = null;

function _pointerNavigationTargetId(target) {
  const fixedRightDock = target?.closest?.('.gb-dock-fixed-right[data-panelset-id]');
  if (fixedRightDock?.dataset?.panelsetId) return fixedRightDock.dataset.panelsetId;
  return target?.closest?.('.gb-pane')?.dataset?.paneId || null;
}

function _handlePointerNavigationButtons(e) {
  if (e.button !== 3 && e.button !== 4) return;
  const paneId = _pointerNavTargetId || _pointerNavigationTargetId(e.target) || undefined;
  _pointerNavTargetId = null;
  // 以前フォーカスしていた入力欄ではなく、実際にサイドボタンを押した場所で判定する。
  // 入力後に表や本文へマウスを移しても activeElement は入力欄のまま残るため、旧判定では
  // 戻る/進むが永続的に無効になっていた。入力要素そのものの上で押した時だけ保護する。
  const editableTarget = e.target?.closest?.('input, textarea, select, [contenteditable="true"]');
  if (editableTarget) return;
  if (e.button === 3) {
    if (navBack(paneId)) e.preventDefault();
  } else if (e.button === 4) {
    if (navForward(paneId)) e.preventDefault();
  }
}

window.addEventListener('mousedown', (e) => {
  if (e.button === 3 || e.button === 4) {
    _pointerNavTargetId = _pointerNavigationTargetId(e.target);
    e.preventDefault();
  }
}, true);
window.addEventListener('mouseup', _handlePointerNavigationButtons, true);
window.addEventListener('pointercancel', () => { _pointerNavTargetId = null; }, true);

// esc() は meldex-core.js で定義済み
function saveLastView(obj) {
  try {
    if (typeof _chatSetCurrentTargetFromView === 'function') _chatSetCurrentTargetFromView(obj, { reason: 'last-view', deferAdoptSource: true });
  } catch {}
  // 単一タブポップアウト窓では元ウィンドウの lastView を汚染しないよう常にスキップ
  if (window._skipLastViewSave || window._gbSingleWindow) return;
  // file_id を付与
  const filePath = obj?.path || obj?.dbPath || obj?.entityPath || '';
  if (obj && filePath && !obj.file_id) {
    const fid = _pathToFileId(filePath);
    if (fid) obj.file_id = fid;
  }
  localStorage.setItem('lastView', JSON.stringify(obj));
}

function _isCloudPhase1UnsupportedOpenType(type) {
  return !!window.MeldexCloudBootstrap?.isPhase1UnsupportedType?.(type);
}

function _showCloudPhase1UnsupportedOpen(type) {
  if (window.MeldexCloudBootstrap?.showPhase1Unsupported) return window.MeldexCloudBootstrap.showPhase1Unsupported(type);
  showStatus('ブラウザ版Meldexではまだ未対応のビューです', true);
  return false;
}

function _pathTailLabel(path, fallback) {
  const raw = String(path || '').replace(/[\\/]+$/, '');
  if (!raw) return fallback || '';
  return raw.split(/[\\/]/).filter(Boolean).pop() || fallback || raw;
}

function _startupFolderCandidate(roots, homeRes, vault) {
  if (homeRes?.exists && homeRes.path) {
    try {
      if (typeof _homeFolderPath !== 'undefined') _homeFolderPath = homeRes.path;
    } catch (e) {}
    return { label: (typeof HOME_FOLDER_DISPLAY_LABEL !== 'undefined' ? HOME_FOLDER_DISPLAY_LABEL : 'ホームフォルダ'), path: homeRes.path };
  }
  const root = Array.isArray(roots)
    ? roots.find(r => r && r.path && r.visible !== false)
    : null;
  if (root) return { label: root.name || _pathTailLabel(root.path, 'フォルダ'), path: root.path };
  if (vault?.path) {
    return { label: vault.name || _pathTailLabel(vault.path, 'フォルダ'), path: vault.path };
  }
  return null;
}

function _isDesktopStartupLaunch() {
  try {
    const params = new URLSearchParams(window.location.search || '');
    return params.get('desktop') === '1' || document.documentElement?.dataset?.desktopLaunch === '1';
  } catch {
    return false;
  }
}

function _paneLayoutHasAnyTabs() {
  try {
    if (typeof GBLayout === 'undefined' || typeof GBLayout.getAllPanes !== 'function' || !GBLayout.root) return false;
    const panes = GBLayout.getAllPanes(GBLayout.root, { activeOnly: true }) || [];
    return panes.some(p => Array.isArray(p?.tabs) && p.tabs.length > 0);
  } catch {
    return false;
  }
}

const STARTUP_LAYOUT_UTILITY_TAB_TYPES = new Set([
  'outliner',
  'detail',
  'preview',
  'chat',
  'calendar',
  'history',
  'annotation',
  'sticky',
  'search',
  'version',
]);

function _paneLayoutHasContentTabs() {
  try {
    if (typeof GBLayout === 'undefined' || typeof GBLayout.getAllPanes !== 'function' || !GBLayout.root) return false;
    const panes = GBLayout.getAllPanes(GBLayout.root, { activeOnly: true }) || [];
    return panes.some(pane => {
      if (typeof GBLayout.isPaneVisible === 'function' && !GBLayout.isPaneVisible(pane?.id)) return false;
      return (pane?.tabs || []).some(tab => !STARTUP_LAYOUT_UTILITY_TAB_TYPES.has(tab?.type));
    });
  } catch {
    return false;
  }
}

function _paneLayoutRestoredFromStorage() {
  return !!(typeof GBLayout !== 'undefined' && GBLayout.layoutLoadedFromStorage && _paneLayoutHasContentTabs());
}

/* ==============================
   API呼び出し
   ============================== */
function _perfNowMs() {
  return (typeof performance !== 'undefined' && typeof performance.now === 'function')
    ? performance.now()
    : Date.now();
}

function _perfElapsedMs(startedAt) {
  return Math.max(0, Math.round(_perfNowMs() - startedAt));
}

function _perfTargetLabelFromPath(path) {
  try {
    const url = new URL(String(path || ''), 'http://meldex.local');
    const rawPath = url.searchParams.get('path') || '';
    if (!rawPath) return '';
    return rawPath.split(/[\\/]/).filter(Boolean).pop() || rawPath;
  } catch {
    return '';
  }
}

const _apiFetchObservedGetEndpoints = new Set([
  '/outliner-roots',
  '/db-metadata',
  '/pivot',
  '/browse',
  '/check-type',
  '/file',
  '/file-meta',
  '/global-index',
]);

function _apiFetchPerfInfo(path) {
  try {
    const url = new URL(String(path || ''), 'http://meldex.local');
    const endpoint = url.pathname || '';
    if (!_apiFetchObservedGetEndpoints.has(endpoint)) return null;
    return {
      endpoint,
      label: 'api' + endpoint,
      targetLabel: _perfTargetLabelFromPath(path),
    };
  } catch {
    return null;
  }
}

const _apiFetchInFlightGets = new Map();
const GB_APP_API_FETCH_BROWSE_CACHE_TTL_MS = 2500;
const GB_APP_API_FETCH_BROWSE_CACHE_MAX_ENTRIES = 80;
const GB_APP_API_FETCH_TIMEOUT_MS = 15000; // fetch()がハングし続け、フォルダツリー等が無限ロードになるのを防ぐ上限
const GB_APP_API_FETCH_MAX_TIMEOUT_MS = 330000;
// OSのフォルダ／ファイル選択は利用者の操作を待つため、通常APIの15秒上限を使わない。
// サーバー側の待機上限（フォルダ120秒、ファイル300秒）より少し長くして、正常な
// 選択結果をフロント側が先に破棄しない。パスだけを入力する検証POSTも同じendpointを
// 使うが、長い上限は実際の処理時間を延ばさず、応答が止まった場合だけ作用する。
const GB_APP_API_FETCH_NATIVE_DIALOG_TIMEOUTS = new Map([
  ['/pick-folder', 135000],
  ['/add-outliner-root', 135000],
  ['/dropbox-link/pick-workspace-folder', 135000],
  ['/workspaces/pick-folder', 135000],
  ['/standalone/pick-folder', 135000],
  ['/save-file-dialog', 315000],
  ['/open-file-dialog', 315000],
  ['/settings-transfer/export', 315000],
]);
// シート系エンドポイント（セル値・列メタデータ）の保存先 per-sheet SQLite は Dropbox
// 同期フォルダ上にあり、書き込みロック待ちが最大 busy_timeout=30秒 かかり得る。既定15秒
// だとサーバー処理中でもフロントが先に abort して「保存に失敗しました」の偽エラーになる
// ため、これらは 30秒 を上回る既定タイムアウトにする（明示 timeoutMs があればそちら優先）。
const GB_APP_API_FETCH_SHEET_TIMEOUT_MS = 35000;
// 共有設定（プロフィール等）の読み書きも Dropbox 同期フォルダ上のファイルを触るため、
// 同じ理由で15秒では足りずに「通信に失敗しました」の偽エラーになることがある
// （実機で、プロフィール統合の直後に発生。処理自体は成功していた）。
const GB_APP_API_FETCH_SHEET_ENDPOINTS = new Set(['/value', '/db-metadata', '/dropbox-link/settings-file']);
function _gbAppApiFetchDefaultTimeout(path) {
  const pathname = String(path || '').split('?')[0];
  const nativeDialogTimeout = GB_APP_API_FETCH_NATIVE_DIALOG_TIMEOUTS.get(pathname);
  if (nativeDialogTimeout) return nativeDialogTimeout;
  // Cloud reads may include a large sheet and bounded Dropbox retry waits.
  if (window.MeldexRuntimeAdapter?.getMode?.() === 'dropbox'
      && ['/pivot', '/db-metadata', '/value', '/browse', '/check-type'].includes(pathname)) return 120000;
  return GB_APP_API_FETCH_SHEET_ENDPOINTS.has(pathname)
    ? GB_APP_API_FETCH_SHEET_TIMEOUT_MS
    : GB_APP_API_FETCH_TIMEOUT_MS;
}
const _gbAppApiFetchBrowseCache = new Map();
let _gbAppApiFetchCacheGeneration = 0;

function _gbAppApiFetchMethod(opts) {
  return String(opts?.method || 'GET').toUpperCase();
}

function _gbAppApiFetchClonePayload(payload) {
  if (typeof structuredClone === 'function') {
    try { return structuredClone(payload); } catch {}
  }
  try { return JSON.parse(JSON.stringify(payload)); } catch { return payload; }
}

function _gbAppApiFetchCanonicalGetPath(path) {
  try {
    const url = new URL(String(path || ''), 'http://meldex.local');
    const params = [...url.searchParams.entries()]
      .sort(([ak, av], [bk, bv]) => (ak + '=' + av).localeCompare(bk + '=' + bv));
    const query = params.map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(value)).join('&');
    return url.pathname + (query ? '?' + query : '');
  } catch {
    return String(path || '');
  }
}

function _apiFetchInFlightKey(path, opts) {
  if (_gbAppApiFetchMethod(opts) !== 'GET' || opts?.body != null || opts?.signal) return '';
  const nonBenignKeys = Object.keys(opts || {}).filter(key => !['method', 'silentError', 'skipBrowseCache'].includes(key));
  if (nonBenignKeys.length > 0) return '';
  return _gbAppApiFetchCanonicalGetPath(path)
    + '|silent=' + (opts?.silentError === true ? '1' : '0')
    + '|skipBrowseCache=' + (opts?.skipBrowseCache === true ? '1' : '0');
}

function _gbAppApiFetchBrowseCacheKey(path, opts) {
  if (_gbAppApiFetchMethod(opts) !== 'GET' || opts?.body != null || opts?.skipBrowseCache === true || opts?.cache === 'reload') return '';
  try {
    const url = new URL(String(path || ''), 'http://meldex.local');
    return url.pathname === '/browse' ? _gbAppApiFetchCanonicalGetPath(path) : '';
  } catch {
    return '';
  }
}

function _gbAppApiFetchInvalidateReadCaches() {
  _gbAppApiFetchCacheGeneration += 1;
  _gbAppApiFetchBrowseCache.clear();
  _apiFetchInFlightGets.clear();
  if (typeof _clearBrowseItemResolvedTypeCache === 'function') _clearBrowseItemResolvedTypeCache();
}

function _gbAppApiFetchRememberBrowse(cacheKey, payload) {
  _gbAppApiFetchBrowseCache.set(cacheKey, {
    at: Date.now(),
    payload: _gbAppApiFetchClonePayload(payload),
  });
  while (_gbAppApiFetchBrowseCache.size > GB_APP_API_FETCH_BROWSE_CACHE_MAX_ENTRIES) {
    const oldestKey = _gbAppApiFetchBrowseCache.keys().next().value;
    if (!oldestKey) break;
    _gbAppApiFetchBrowseCache.delete(oldestKey);
  }
}

function _apiFetchBackendPerf(res) {
  try {
    const raw = res?.headers?.get?.('x-meldex-perf') || '';
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function _logPerfEvent(label, startedAt, detail) {
  try {
    const durationMs = _perfElapsedMs(startedAt);
    const payload = {
      ...(detail || {}),
      message: `[perf] ${label}: ${durationMs}ms`,
      perf: true,
      label,
      durationMs,
    };
    if (typeof console !== 'undefined' && typeof console.info === 'function') {
      console.info('[Meldex perf] ' + payload.message, payload);
    }
    if (typeof _sendLog === 'function') _sendLog('info', payload);
    return payload;
  } catch {
    return null;
  }
}

function _gbAppApiFetchIsAbortError(e) {
  return !!e && (e.name === 'AbortError' || e.code === 20);
}

// 呼び出し元のsignalを尊重しつつ、一定時間で自動中断するfetchラッパー。
// タイムアウトで中断した場合はisTimeout=trueを付与し、呼び出し元キャンセルと区別できるようにする。
async function _gbAppApiFetchDoFetch(url, requestOpts, timeoutMs) {
  const controller = new AbortController();
  const externalSignal = requestOpts?.signal || null;
  const fetchOpts = { ...(requestOpts || {}) };
  delete fetchOpts.timeoutMs;
  let timedOut = false;
  let onExternalAbort = null;
  if (externalSignal) {
    if (externalSignal.aborted) {
      // 理由付きabortはfetchが通常Errorを投げるため、呼び出し元キャンセルを
      // 通信障害と誤判定しないよう内部signalは標準AbortErrorへ正規化する。
      controller.abort();
    } else {
      onExternalAbort = () => controller.abort();
      externalSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
  }
  const timeoutId = setTimeout(() => { timedOut = true; controller.abort(); }, timeoutMs);
  try {
    return await fetch(url, { ...fetchOpts, signal: controller.signal });
  } catch (e) {
    if (_gbAppApiFetchIsAbortError(e) && timedOut) {
      const timeoutErr = new Error(`HTTPリクエストがタイムアウトしました(${Math.round(timeoutMs / 1000)}秒): ${url}`);
      timeoutErr.name = 'AbortError';
      timeoutErr.isTimeout = true;
      throw timeoutErr;
    }
    throw e;
  } finally {
    clearTimeout(timeoutId);
    if (externalSignal && onExternalAbort) externalSignal.removeEventListener('abort', onExternalAbort);
  }
}

async function apiFetch(path, opts) {
  const method = _gbAppApiFetchMethod(opts);
  const browseCacheKey = _gbAppApiFetchBrowseCacheKey(path, opts);
  const cacheGeneration = _gbAppApiFetchCacheGeneration;
  if (browseCacheKey) {
    const cached = _gbAppApiFetchBrowseCache.get(browseCacheKey);
    if (cached && Date.now() - cached.at < GB_APP_API_FETCH_BROWSE_CACHE_TTL_MS) {
      return _gbAppApiFetchClonePayload(cached.payload);
    }
    _gbAppApiFetchBrowseCache.delete(browseCacheKey);
  }
  const inFlightKey = _apiFetchInFlightKey(path, opts);
  if (inFlightKey && _apiFetchInFlightGets.has(inFlightKey)) {
    return _gbAppApiFetchClonePayload(await _apiFetchInFlightGets.get(inFlightKey));
  }
  const perfInfo = _apiFetchPerfInfo(path);
  const perfStartedAt = perfInfo ? _perfNowMs() : 0;
  const requestPromise = (async () => {
    try {
      let requestOpts = opts;
      let retriedAfterMutation = false;
      while (true) {
        const requestedTimeout = Number(requestOpts?.timeoutMs);
        const timeoutMs = Number.isFinite(requestedTimeout) && requestedTimeout > 0
          ? Math.min(requestedTimeout, GB_APP_API_FETCH_MAX_TIMEOUT_MS)
          : _gbAppApiFetchDefaultTimeout(path);
        const res = await _gbAppApiFetchDoFetch(API_BASE + path, requestOpts, timeoutMs);
        if (perfInfo) {
          _logPerfEvent(perfInfo.label + '.fetch', perfStartedAt, {
            ...perfInfo,
            status: res.status,
            contentLength: res.headers?.get?.('content-length') || '',
            retriedAfterMutation,
          });
        }
        const backendPerf = _apiFetchBackendPerf(res);
        if (!res.ok) {
          let detail = res.statusText || '';
          let payload = null;
          try {
            payload = await res.clone().json();
            const rawDetail = payload?.error || payload?.detail || detail;
            detail = rawDetail && typeof rawDetail === 'object'
              ? (rawDetail.message || rawDetail.code || detail)
              : rawDetail;
          } catch {}
          const error = new Error(`HTTP ${res.status}: ${detail}`);
          error.status = res.status;
          error.payload = payload;
          error.userMessage = window.MeldexErrorMessages?.toStatusText?.(error, { path }) || error.message;
          throw (window.MeldexSaveSafety?.enrichError?.(error, payload, res.status) || error);
        }
        const jsonStartedAt = perfInfo ? _perfNowMs() : 0;
        const data = await res.json();
        if (perfInfo) {
          _logPerfEvent(perfInfo.label + '.json', jsonStartedAt, {
            ...perfInfo,
            backendPerf,
            retriedAfterMutation,
          });
        }
        // GET開始後に作成・保存・移動等が完了した場合、開始時点の古い一覧を
        // 呼び出し元へ返さない。アプリ内キャッシュを迂回して1回だけ取り直す。
        if (browseCacheKey && !retriedAfterMutation && cacheGeneration !== _gbAppApiFetchCacheGeneration) {
          retriedAfterMutation = true;
          requestOpts = { ...(opts || {}), skipBrowseCache: true, cache: 'reload' };
          continue;
        }
        if (backendPerf && data && typeof data === 'object') {
          try {
            Object.defineProperty(data, '_backendPerf', {
              value: backendPerf,
              configurable: true,
            });
          } catch {}
        }
        window.MeldexSaveSafety?.reportApiSuccess?.(path, requestOpts);
        if (method !== 'GET') {
          _gbAppApiFetchInvalidateReadCaches();
        } else if (browseCacheKey && cacheGeneration === _gbAppApiFetchCacheGeneration) {
          _gbAppApiFetchRememberBrowse(browseCacheKey, data);
        }
        if (perfInfo) _logPerfEvent(perfInfo.label, perfStartedAt, { ...perfInfo, backendPerf, retriedAfterMutation });
        return data;
      }
    } catch (e) {
      if (perfInfo) {
        _logPerfEvent(perfInfo.label + '.error', perfStartedAt, {
          ...perfInfo,
          error: e?.message || String(e),
        });
      }
      const quietReadAbort = method === 'GET' && _gbAppApiFetchIsAbortError(e);
      if (!opts?.silentError && !quietReadAbort) {
        window.MeldexDiagnostics?.captureApiError?.(path, opts, e);
      }
      if (!opts?.silentError && !window.MeldexSaveSafety?.reportApiError?.(path, opts, e)) {
        if (quietReadAbort) {
          // GET中断/タイムアウトはエラートースト表示せず、コンソールログのみに留める（呼び出し元は再試行等で処理する）
          try { console.warn('[apiFetch] aborted:', path, e.message); } catch {}
        } else {
          const text = window.MeldexErrorMessages?.toStatusText?.(e, { path }) || e.message;
          showStatus('エラー: ' + text, true);
        }
      }
      throw e;
    }
  })();
  if (inFlightKey) {
    _apiFetchInFlightGets.set(inFlightKey, requestPromise);
    requestPromise.then(
      () => { if (_apiFetchInFlightGets.get(inFlightKey) === requestPromise) _apiFetchInFlightGets.delete(inFlightKey); },
      () => { if (_apiFetchInFlightGets.get(inFlightKey) === requestPromise) _apiFetchInFlightGets.delete(inFlightKey); },
    );
  }
  return _gbAppApiFetchClonePayload(await requestPromise);
}

function _gbAppIsFullFileWrite(path, body) {
  const pathname = String(path || '').split('?', 1)[0].replace(/^\/api/, '');
  return pathname === '/file' && body && typeof body === 'object'
    && (Object.prototype.hasOwnProperty.call(body, 'content')
      || Object.prototype.hasOwnProperty.call(body, 'content_base64'));
}

async function _gbAppPrepareFullFileWrite(path, body) {
  const payload = { ...(body || {}) };
  if (!_gbAppIsFullFileWrite(path, payload)) return payload;
  const coordinator = window.MeldexDocumentSaveCoordinator;
  const force = !!(payload.force_overwrite || payload.forceOverwrite);
  const createOnly = !!(payload.create_only || payload.createOnly);
  let revision = payload.transport_revision || payload.transportRevision
    || payload.if_match_transport_revision || payload.if_match_etag || payload.ifMatchEtag || '';

  if (revision && coordinator?.revisionTokenForWrite) {
    payload.if_match_etag = coordinator.revisionTokenForWrite(revision);
    return payload;
  }
  if (revision || force || createOnly) return payload;

  // revision無しの旧呼び出し元を、保存直前に取得した「最新revision」で
  // 延命してはいけない。古い本文へ最新revisionを付け直すと、読込後に別端末で
  // 更新された内容をCASに成功させて上書きしてしまう。ここで許可する自動補完は、
  // 保存先が存在しないことを確認できた時の create_only だけとする。
  try {
    const separator = String(path).includes('?') ? '&' : '?';
    const current = await apiFetch(`${path}${separator}metadata_only=1`, { silentError: true });
    coordinator?.bindDocumentIdentity?.(
      new URLSearchParams(String(path).split('?')[1] || '').get('path') || '',
      current,
    );
    const error = new Error('既存ファイルの保存には、読込時のrevisionが必要です');
    error.status = 428;
    error.meldexCode = 'precondition_required';
    error.meldexDetail = {
      code: 'precondition_required',
      path: new URLSearchParams(String(path).split('?')[1] || '').get('path') || '',
      current_etag: current?.etag || '',
      current_transport_revision: current?.transport_revision || null,
    };
    throw error;
  } catch (error) {
    if (error?.status === 404 && !(payload.skip_if_missing || payload.skipIfMissing)) {
      payload.create_only = true;
      return payload;
    }
    if (error?.status === 404 && (payload.skip_if_missing || payload.skipIfMissing)) return payload;
    throw error;
  }
}

async function apiPut(path, body, options = {}) {
  const guardedBody = await _gbAppPrepareFullFileWrite(path, body);
  const result = await apiFetch(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(guardedBody),
    ...(options || {}),
  });
  _scheduleLinkDictionaryRefreshForMutation(path);
  return result;
}

function _scheduleLinkDictionaryRefreshForMutation(path) {
  const pathname = String(path || '').split('?')[0];
  if (![
    '/value', '/entity/create', '/entity/rename',
    '/outliner/delete', '/outliner/delete-batch', '/outliner/rename',
  ].includes(pathname)) return;
  if (typeof MeldexAutoLink !== 'undefined' && typeof MeldexAutoLink.scheduleReload === 'function') {
    MeldexAutoLink.scheduleReload(3000);
  }
}

async function apiPost(path, body, options = {}) {
  let stableCopyKey = '';
  if (['/outliner/duplicate', '/outliner/save-as'].includes(String(path || ''))
      && body && typeof body === 'object' && !body.operation_id) {
    const prepared = window.MeldexStableCopyOperationIds?.prepare?.(path, body)
      || { body: { ...body, operation_id: crypto.randomUUID() }, key: '' };
    body = prepared.body; stableCopyKey = prepared.key;
  }
  const result = await apiFetch(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    ...(options || {}),
  });
  window.MeldexStableCopyOperationIds?.complete(stableCopyKey);
  _scheduleLinkDictionaryRefreshForMutation(path);
  return result;
}

/* ==============================
   初期化
   ============================== */
// 認証トークン管理
// 旧認証変数（互換性のため残す — 他モジュールが参照）
let _authToken = '';
let _authUser = null;

function _apiLockJsonBody(opts) {
  const raw = opts?.body;
  if (!raw) return {};
  if (typeof raw === 'string') {
    try { return JSON.parse(raw); } catch { return {}; }
  }
  if (raw && typeof raw === 'object' && !(raw instanceof FormData)) return raw;
  return {};
}

function _apiLockPathDir(path) {
  const text = String(path || '').replace(/\\/g, '/');
  const index = text.lastIndexOf('/');
  return index > 0 ? text.slice(0, index) : '';
}

function _apiLockRenameExtension(path) {
  const text = String(path || '').replace(/\\/g, '/');
  const name = text.slice(text.lastIndexOf('/') + 1);
  if (!name || name.endsWith('.')) return '';
  const visibleName = name.replace(/^\.+/, '');
  const dotIndex = visibleName.indexOf('.');
  return dotIndex >= 0 ? visibleName.slice(dotIndex) : '';
}

function _apiLockAddPath(paths, value) {
  const text = String(value || '').trim();
  if (text) paths.push(text);
}

function _apiLockWriteCandidatePaths(path, opts) {
  const method = String(opts?.method || 'GET').toUpperCase();
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) return [];
  let url;
  try { url = new URL(String(path || ''), window.location.origin); } catch { return []; }
  const route = url.pathname.replace(/^\/api(?=\/|$)/, '') || '/';
  if (route === '/file-lock' || route.startsWith('/file-lock/') || route === '/active-lock' || route.startsWith('/active-lock/')) return [];
  const body = _apiLockJsonBody(opts);
  const query = url.searchParams;
  const paths = [];
  const addQuery = (key) => _apiLockAddPath(paths, query.get(key));
  const addBody = (key) => _apiLockAddPath(paths, body?.[key]);
  const addBoth = (key) => { addQuery(key); addBody(key); };

  if (route === '/file' || route === '/value' || route === '/db-metadata' || route === '/replace') {
    addBoth('path');
    addBody('entry_path');
    addBody('folder_path');
  } else if (route === '/replace-batch') {
    (Array.isArray(body?.targets) ? body.targets : []).forEach(item => _apiLockAddPath(paths, item?.path));
  } else if (route === '/upload-file') {
    addBoth('path');
    addBody('dir');
  } else if (route === '/outliner/add') {
    addBody('parent');
  } else if (route === '/outliner/delete') {
    addBody('path');
  } else if (route === '/outliner/duplicate') {
    const srcPath = String(body?.path || '').trim();
    if (srcPath) _apiLockAddPath(paths, _apiLockPathDir(srcPath));
  } else if (route === '/outliner/save-as') {
    addBody('path');
    addBody('dest_folder');
  } else if (route === '/outliner/delete-batch') {
    (Array.isArray(body?.items) ? body.items : []).forEach(item => _apiLockAddPath(paths, item?.path));
  } else if (route === '/outliner/move') {
    addBody('path');
    addBody('dest_folder');
  } else if (route === '/outliner/rename') {
    addBody('old_path');
    const oldPath = String(body?.old_path || '');
    const newName = String(body?.new_name || '').trim();
    if (oldPath && newName) {
      const destinationBase = (_apiLockPathDir(oldPath) ? _apiLockPathDir(oldPath) + '/' : '') + newName;
      _apiLockAddPath(paths, destinationBase);
      const extension = _apiLockRenameExtension(oldPath);
      if (extension) _apiLockAddPath(paths, destinationBase + extension);
    }
  } else if (route === '/entity/create') {
    addBody('parent_path');
  } else if (route === '/entity/rename') {
    addBody('path');
    const oldPath = String(body?.path || '');
    const newName = String(body?.new_name || '').trim();
    if (oldPath && newName) _apiLockAddPath(paths, (_apiLockPathDir(oldPath) ? _apiLockPathDir(oldPath) + '/' : '') + newName);
  } else if (route === '/annotations' || route === '/annotations/restore' || route === '/annotations/orphan-by-target') {
    addBody('target_path');
  } else if (route === '/entity/auto-name') {
    addBody('db_path');
    addBody('entry_path');
    addBody('path');
  } else if (route === '/folder-links/add' || route === '/folder-links/remove') {
    addBody('folder_path');
    addBody('file_path');
  } else if (route === '/import-csv' || route === '/import-xlsx') {
    addBody('csv_path');
    addBody('xlsx_path');
    addBody('db_path');
  } else if (route === '/public-form/submit') {
    addBody('db_path');
  } else if (route.startsWith('/calendar-db/events') || route.startsWith('/calendar-db/sync') || route.startsWith('/calendar-db/ical') || route.startsWith('/calendar-db/caldav')) {
    addBoth('db_path');
  } else if (route === '/version/restore' || route === '/version/restore-db' || route === '/version/restore-folder' || route === '/version/delete-folder' || route === '/version/delete-db') {
    addBody('path');
  }

  return [...new Set(paths)];
}

function _apiLockBlockIfNeeded(path, opts) {
  if (typeof isItemLocked !== 'function') return false;
  const lockedPath = _apiLockWriteCandidatePaths(path, opts).find(p => {
    try { return isItemLocked(p); } catch { return false; }
  });
  if (!lockedPath) return false;
  const reason = typeof getItemLockReason === 'function' ? getItemLockReason(lockedPath) : '';
  const message = reason
    ? `編集ロック中のため編集できません（理由: ${reason}）`
    : '編集ロック中のため編集できません';
  if (typeof showStatus === 'function') showStatus(message, true);
  throw new Error(message);
}

function _apiUsesTransientActiveLock(path) {
  let route = '';
  try { route = new URL(String(path || ''), window.location.origin).pathname.replace(/^\/api(?=\/|$)/, '') || '/'; }
  catch { return false; }
  return new Set([
    '/upload-file', '/outliner/add', '/outliner/rename', '/outliner/delete',
    '/outliner/delete-batch', '/outliner/restore', '/outliner/duplicate',
    '/outliner/save-as', '/outliner/move', '/trash/restore', '/replace', '/replace-batch',
  ]).has(route);
}

// apiFetchをオーバーライドしてユーザー名を付加
const _origApiFetch = apiFetch;
apiFetch = async function(path, opts) {
  opts = opts || {};
  const lockCandidatePaths = _apiLockWriteCandidatePaths(path, opts);
  _apiLockBlockIfNeeded(path, opts);
  const activeLocks = window.MeldexActiveLocks;
  const transientLease = _apiUsesTransientActiveLock(path) && activeLocks?.acquireMutationLocks
    ? await activeLocks.acquireMutationLocks(lockCandidatePaths)
    : null;
  try {
    if (activeLocks?.beforeApiFetch) {
      opts = await activeLocks.beforeApiFetch(path, opts, { candidatePaths: lockCandidatePaths });
    }
    // 表示名と安定IDを自動付与（監査ログ・版履歴の編集者帰属用）
    const user = getUsername();
    const actorId = window.MeldexProfileIdentity?.getStableActorId?.() || '';
    const requestMethod = String(opts.method || 'GET').toUpperCase();
    const mutationRequest = requestMethod !== 'GET' && requestMethod !== 'HEAD';
    const identityParams = [];
    if (user && user !== 'anonymous' && !/[?&]_user=/.test(path)) identityParams.push('_user=' + encodeURIComponent(user));
    if (mutationRequest && actorId && !/[?&]_actor_id=/.test(path)) identityParams.push('_actor_id=' + encodeURIComponent(actorId));
    if (mutationRequest && !/[?&]_actor_kind=/.test(path)) identityParams.push('_actor_kind=human');
    if (identityParams.length) path += (path.includes('?') ? '&' : '?') + identityParams.join('&');
    const result = await _origApiFetch(path, opts);
    if (result?.history_sync_pending) {
      if (typeof showStatus === 'function') showStatus('本文は保存しました。変更履歴は接続回復後に同期します', true);
    } else if (result?.history_recorded === false) {
      if (typeof showStatus === 'function') showStatus('本文は保存しましたが、変更履歴を記録できませんでした', true);
    }
    return result;
  } finally {
    await transientLease?.release?.();
  }
};

// チームプロフィール同期（起動時に型付き管理領域へ自分を登録。source folderは変更しない）
// フォルダ別ロールを保持（DB列ロック等で参照）
let _myTeamRole = 'editor';  // デフォルト（ソースフォルダ未設定時）
const _myTeamRoles = {};     // { folderPath: role }

async function _syncMyTeamProfile() {
  try { await window.MeldexDropboxProfileSync?.resolveStartupProfile?.(); } catch {}
  const name = getUsername();
  if (!name || name === 'anonymous') return;
  const avatar = localStorage.getItem('meldex-avatar') || '';
  const teamPayload = (extra) => window.MeldexDropboxProfileSync?.teamSyncPayload?.({ name, avatar, ...(extra || {}) }) || { name, avatar, ...(extra || {}) };
  const syncWorkspaceProfiles = async () => {
    try {
      const workspaces = typeof window.MeldexWorkspaces?.load === 'function'
        ? await window.MeldexWorkspaces.load({ force: true })
        : [];
      for (const workspace of workspaces || []) {
        if (!workspace?.id) continue;
        await apiPost('/workspaces/' + encodeURIComponent(workspace.id) + '/sync-profile', teamPayload({ workspace_id: workspace.id }));
      }
      await window.MeldexWorkspaces?.load?.({ force: true });
    } catch {}
  };
  // 全ソースフォルダに対応する管理レコードへ同期
  try {
    const roots = await apiFetch('/outliner-roots').catch(() => []);
    const visibleRoots = roots.filter(r => r.visible && r.path);
    if (visibleRoots.length === 0) {
      // ソースフォルダなし → デフォルトvaultに対応する管理レコードへ同期
      try {
        await apiPost('/team/sync', teamPayload());
        const members = await apiFetch('/team');
        const me = members.find(m => m.name === name);
        if (me) _myTeamRole = me.role || 'editor';
      } catch {}
      await syncWorkspaceProfiles();
      return;
    }
    for (const root of visibleRoots) {
      try {
        await apiPost('/team/sync', teamPayload({ folder: root.path }));
        const members = await apiFetch('/team?folder=' + encodeURIComponent(root.path));
        const me = members.find(m => m.name === name);
        if (me) _myTeamRoles[root.path] = me.role || 'editor';
      } catch {}
    }
    // デフォルトロール = 最初の可視ソースフォルダのロール
    const firstRole = _myTeamRoles[visibleRoots[0].path];
    if (firstRole) _myTeamRole = firstRole;
    await syncWorkspaceProfiles();
  } catch {}
}

let _startupSplashHidden = false;
function _notifyStartupReady() {
  if (typeof apiPost !== 'function') return;
  void apiPost('/startup-ready', {}, { silentError: true }).catch(() => {});
}

function _hideStartupSplash() {
  if (_startupSplashHidden) return;
  _startupSplashHidden = true;
  _notifyStartupReady();
  const splash = document.getElementById('gb-splash');
  if (!splash) return;
  splash.style.pointerEvents = 'none';
  splash.style.transition = 'opacity 0.3s';
  splash.style.opacity = '0';
  setTimeout(() => splash.remove(), 300);
}

function _withStartupTimeout(label, promise, timeoutMs, fallbackValue) {
  const timeout = Number.isFinite(timeoutMs) && timeoutMs > 0 ? timeoutMs : 0;
  if (!timeout) return Promise.resolve(promise);
  const startedAt = typeof _perfNowMs === 'function' ? _perfNowMs() : Date.now();
  return new Promise((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      console.warn(`[Meldex] startup timeout: ${label} (${timeout}ms)`);
      if (typeof _logPerfEvent === 'function') {
        _logPerfEvent('startup.timeout.' + label, startedAt, { timeoutMs: timeout });
      }
      if (typeof _sendLog === 'function') {
        _sendLog('warn', { message: `[startup-timeout] ${label}`, timeoutMs: timeout });
      }
      resolve(fallbackValue);
    }, timeout);
    Promise.resolve(promise).then((value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (typeof _logPerfEvent === 'function') {
        _logPerfEvent('startup.ready.' + label, startedAt, { timeoutMs: timeout });
      }
      resolve(value);
    }).catch((error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (typeof _logPerfEvent === 'function') {
        _logPerfEvent('startup.error.' + label, startedAt, {
          timeoutMs: timeout,
          error: error?.message || String(error),
        });
      }
      reject(error);
    });
  });
}

function _runStartupBackground(label, promise, onReady) {
  Promise.resolve(promise)
    .then((value) => {
      if (typeof onReady === 'function') onReady(value);
      return value;
    })
    .catch((error) => {
      console.warn(`[Meldex] startup background task failed: ${label}`, error);
      if (typeof _sendLog === 'function') {
        _sendLog('warn', {
          message: `[startup-bg-failed] ${label}: ${error?.message || error}`,
          stack: error?.stack || '',
        });
      }
      return null;
    });
}

function _refreshOutlinerAfterStartupReady() {
  try {
    const outlinerOptions = {
      coalesce: true,
      skipIfRecentlyLoaded: true,
      reason: 'startup-ready',
    };
    if (typeof refreshOutliner === 'function') return refreshOutliner(outlinerOptions);
    const refreshJobs = [];
    if (typeof loadOutliner === 'function') refreshJobs.push(Promise.resolve().then(() => loadOutliner(outlinerOptions)));
    if (typeof renderFavorites === 'function') refreshJobs.push(Promise.resolve().then(() => renderFavorites()));
    if (typeof renderHomeFolderTree === 'function') refreshJobs.push(Promise.resolve().then(() => renderHomeFolderTree()));
    return Promise.allSettled(refreshJobs);
  } catch (error) {
    console.warn('[Meldex] startup outliner refresh failed:', error);
    return Promise.resolve(null);
  }
}

function _highlightLastOutlinerNodeAfterStartup() {
  setTimeout(() => {
    const last = _readLastViewFromStorage();
    if (!last) return;
    const p = last.path || last.dbPath || last.entityPath || '';
    if (p) highlightOutlinerNode(p);
  }, 500);
}

function _readLastViewFromStorage() {
  try {
    return JSON.parse(localStorage.getItem('lastView') || 'null');
  } catch {
    localStorage.removeItem('lastView');
    return null;
  }
}

async function _openCloudStartupHome(homeRes, isUrlOpen, onboardingShown) {
  // Explicit links keep their target; Desktop keeps its saved workspace.
  if (_isDesktopStartupLaunch() || isUrlOpen || onboardingShown || !homeRes?.exists || !homeRes.path) return false;
  const label = typeof HOME_FOLDER_DISPLAY_LABEL !== 'undefined' ? HOME_FOLDER_DISPLAY_LABEL : 'ホームフォルダ';
  await openFolder(label, homeRes.path, {
    fromExplorer: true,
    skipAutoAppLayout: true,
    skipSaveLastView: true,
  });
  return true;
}

function _repairStartupDatabaseViewTabs() {
  try {
    if (!state.currentDbPath || typeof _renderDbViewTabsSafely !== 'function') return;
    const tabs = document.getElementById('db-view-tabs') || document.querySelector('.db-view-tabs');
    if (!tabs) return;
    if (tabs.querySelector('[data-e2e-id^="db-view-add-"]')) return;
    _renderDbViewTabsSafely(typeof _currentPaneState === 'function' ? _currentPaneState() : null);
  } catch {}
}

function _scheduleStartupDatabaseViewTabsRepair() {
  [0, 80, 250].forEach(delay => setTimeout(_repairStartupDatabaseViewTabs, delay));
}

async function _restoreStartupBoardView(label, path, opts) {
  const openOpts = opts || {};
  const boardLabel = label || String(path || '').split(/[\\/]/).pop() || '';
  if (typeof GBPaneBridge !== 'undefined'
    && GBPaneBridge?.initialized
    && typeof GBLayout !== 'undefined'
    && typeof GBTabs !== 'undefined'
    && typeof navPush === 'function') {
    state.view = 'board';
    state.currentBoardPath = path;
    navPush({ type: 'board', label: boardLabel, path });
    if (typeof GBPaneBridge.refreshPaneAfterTabSwitch === 'function') {
      GBPaneBridge.refreshPaneAfterTabSwitch(GBLayout.activePane, { force: true });
    }
    if (!openOpts.skipSaveLastView) saveLastView({ type: 'board', label: boardLabel, path });
    if (!openOpts.skipRecent && typeof addRecent === 'function') addRecent(boardLabel, path, 'board');
    if (!openOpts.skipHighlight && typeof highlightOutlinerNode === 'function') highlightOutlinerNode(path);
    if (!openOpts.skipAutoVersion && typeof startAutoVersion === 'function') startAutoVersion(path, 'file');
    return true;
  }
  const opened = typeof openBoard === 'function' ? await openBoard(boardLabel, path, openOpts) : false;
  return opened !== false;
}

// 特定フォルダ内のパスに対するロールを取得
function getMyRoleForPath(filePath) {
  if (!filePath) return _myTeamRole;
  const normFile = String(filePath).replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase();
  let matchedRole = '';
  let matchedLength = -1;
  for (const [folder, role] of Object.entries(_myTeamRoles)) {
    const norm = String(folder || '').replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase();
    if (!norm) continue;
    if ((normFile === norm || normFile.startsWith(norm + '/')) && norm.length > matchedLength) {
      matchedRole = role;
      matchedLength = norm.length;
    }
  }
  return matchedRole || _myTeamRole;
}

// doLogin / ログイン画面は廃止（チーム方式に移行）

// localStorage移行（旧CrossFolio → Meldex、一度だけ実行）
(function migrateLocalStorage() {
  if (localStorage.getItem('gb:migrated')) return;
  const migrations = {
    'crossfolio-auth-token': 'meldex-auth-token',
    'crossfolio-user': 'meldex-user',
    'crossfolio-recent': 'meldex-recent',
    'crossfolio-theme-vars': 'meldex-theme-vars',
    'crossfolio-favorites': 'meldex-favorites',
    'cf-cal-start-day': 'gb-cal-start-day',
  };
  for (const [oldKey, newKey] of Object.entries(migrations)) {
    const val = localStorage.getItem(oldKey);
    if (val !== null && localStorage.getItem(newKey) === null) {
      localStorage.setItem(newKey, val);
    }
  }
  // cf-cal-mode-*, cf-cal-date-* のプレフィックス移行
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && key.startsWith('cf-cal-')) {
      const newKey = key.replace('cf-cal-', 'gb-cal-');
      if (localStorage.getItem(newKey) === null) {
        localStorage.setItem(newKey, localStorage.getItem(key));
      }
    }
  }
  localStorage.setItem('gb:migrated', '1');
  if (typeof _refreshOutlinerStorageViewsAfterMigration === 'function') {
    _refreshOutlinerStorageViewsAfterMigration();
  }
})();

// 起動時に正本「スタッフ管理シート」へ自分の行を fill-only 登録する
// （ユーザーアカウント一元管理 計画書 Phase 2、§5.6）。行が既に存在するなら
// 一切上書きしない（管理者がシートで編集した値は同期に負けない契約）。
// 正本シート自体が未設定の場合はここで無ダイアログ自動作成される
// （計画書§5.1「起動時同期」が自動作成のトリガーの一つ）。
async function _primeStaffRegistrySelfUpsert() {
  if (!window.MeldexUserRegistry) return;
  const me = typeof getUsername === 'function' ? String(getUsername() || '').trim() : '';
  if (!me || me === 'anonymous') return;
  try {
    await window.MeldexUserRegistry.upsertStaff({ user: me, display: me }, { fillOnly: true });
  } catch (e) {
    // ソースフォルダ未設定・オフライン等では起動処理を止めない。
  }
}

async function init() {
  const initStartedAt = typeof _perfNowMs === 'function' ? _perfNowMs() : Date.now();
  // チームプロフィール同期は権限情報の更新用途。起動表示は待たず、裏で完了させる。
  _runStartupBackground('team-profile-sync', _syncMyTeamProfile());
  _runStartupBackground('staff-registry-self-upsert', _primeStaffRegistrySelfUpsert());

  try {
    const initialFetchStartedAt = typeof _perfNowMs === 'function' ? _perfNowMs() : Date.now();
    const [vault, roots, homeRes] = await Promise.all([
      _withStartupTimeout('vault', apiFetch('/vault'), 5000, { path: '', name: '' }),
      _withStartupTimeout('outliner-roots', apiFetch('/outliner-roots').catch(() => []), 5000, []),
      _withStartupTimeout('home-folder', apiFetch('/home-folder').catch(() => ({ exists: false })), 5000, { exists: false }),
    ]);
    if (typeof _logPerfEvent === 'function') {
      _logPerfEvent('startup.initial-fetches', initialFetchStartedAt, {
        rootsCount: Array.isArray(roots) ? roots.length : 0,
        hasHome: !!homeRes?.exists,
      });
    }
    state.vaultPath = vault.path;
    window.MeldexRegisteredSourceRoots = Array.isArray(roots)
      ? roots.filter(root => root?.path).map(root => ({ ...root }))
      : [];
    try {
      if (homeRes?.path && typeof _homeFolderPath !== 'undefined') _homeFolderPath = homeRes.path;
    } catch (e) {}

    const hasRoots = roots.length > 0 && roots.some(r => r.visible);
    const hasHome = homeRes.exists;
    const onboardingShown = !!window.MeldexOnboarding?.handleStartupState?.({
      vaultPath: vault.path || '',
      hasRoots,
      hasHome,
      homePath: homeRes?.path || '',
    });
    if (!vault.path && !hasRoots && !hasHome) {
      // ソースフォルダもルートもホームもない場合はウェルカム画面
      // ただしサイドバーは表示したまま（設定ボタンにアクセスできるように）
      showView('welcome');
    }

    // ホームフォルダの版間共有: 起動時の共有警告・引き継ぎ提案チェック。
    // オンボーディングウィザードが出る場合はダイアログの重なりを避けて後回しにする
    // （設定画面を開いた時に loadHomeFolderSharingStatusForSettings() 経由で再チェックされる）。
    if (!onboardingShown && window.MeldexHomeFolderSharing?.loadHomeFolderSharingStatusForSettings) {
      _runStartupBackground(
        'home-folder-sharing-check',
        window.MeldexHomeFolderSharing.loadHomeFolderSharingStatusForSettings()
      );
    }

    document.getElementById('sb-work').textContent = vault.path ? ('ソースフォルダ: ' + vault.name) : '';
    document.getElementById('current-title').textContent = '';

    // file_id マイグレーションは初回のみだが、起動表示を止めないよう背景化する。
    const rawMigrationPromise = _migratePathsToFileIds();
    const migrationPromise = _withStartupTimeout('file-id-migration', rawMigrationPromise, 5000, null);

    // 廃止された非表示機能の localStorage を一度だけ除去
    if (!localStorage.getItem('_folder-hidden-removed')) {
      localStorage.removeItem('folder-files-hidden');
      localStorage.setItem('_folder-hidden-removed', '1');
    }

    // フォルダツリーとビュー復元を並行実行
    const outlinerStartedAt = typeof _perfNowMs === 'function' ? _perfNowMs() : Date.now();
    const outlinerPromise = Promise.resolve(loadOutliner()).finally(() => {
      if (typeof _logPerfEvent === 'function') _logPerfEvent('startup.loadOutliner.promise', outlinerStartedAt);
    });
    const linkDictPromise = loadLinkDict();

    // URLパラメータによる初期表示（新しいタブ/ウィンドウで開く用）
    let restored = onboardingShown;
    let openedCloudStartupHome = false;
    const restoredByPaneLayout = _paneLayoutRestoredFromStorage();
    const urlParams = new URLSearchParams(window.location.search);
    const openType = urlParams.get('open');
    const openPath = urlParams.get('path');
    const openLabel = urlParams.get('label') || (openPath ? openPath.split('/').pop() : '');
    const isUrlOpen = !!(openType && openPath);
    if (isUrlOpen && _isCloudPhase1UnsupportedOpenType(openType)) {
      _showCloudPhase1UnsupportedOpen(openType);
      restored = true;
    } else if (isUrlOpen) {
      const _urlOpenOpts = { skipAutoAppLayout: true, skipSaveLastView: true };
      // URLパラメータ経由の場合、lastViewを上書きしないフラグを設定
      const previousSkipLastView = window._skipLastViewSave;
      window._skipLastViewSave = true;
      try {
        if (openType === 'page') { openPage(openLabel, openPath, _urlOpenOpts); restored = true; }
        else if (openType === 'board') { restored = await _restoreStartupBoardView(openLabel, openPath, _urlOpenOpts); }
        else if (openType === 'entity') { selectEntity(openPath, _urlOpenOpts); restored = true; }
        else if (openType === 'pivot' || openType === 'database') { await selectDatabase(openPath, null, _urlOpenOpts); restored = true; }
        else if (openType === 'media' || openType === 'image' || openType === 'video' || openType === 'audio') {
          const mt = urlParams.get('mediaType') || (openType === 'media' ? 'image' : openType);
          openMedia(openLabel, openPath, mt, _urlOpenOpts);
          restored = true;
        }
        else if (openType === 'document') {
          if (typeof openViewer === 'function') {
            const viewerUrl = /\.pdf(?:[?#]|$)/i.test(openPath)
              ? '/viewer?pdf=' + encodeURIComponent(openPath)
              : '/viewer?file=' + encodeURIComponent(openPath);
            openViewer(viewerUrl, _urlOpenOpts);
            restored = true;
          }
        }
        else if (openType === 'html') { openHtmlFile(openLabel, openPath, _urlOpenOpts); restored = true; }
        else if (openType === 'csv') { if (typeof openCsvFile === 'function') { openCsvFile(openLabel, openPath, _urlOpenOpts); restored = true; } }
        else if (openType === 'folder') { openFolder(openLabel, openPath, _urlOpenOpts); restored = true; }
        else if (openType === 'calendar') { await openCalendarFile(openLabel, openPath, _urlOpenOpts); restored = true; }
        else if (openType === 'chat') {
          if (typeof openSavedChat === 'function') {
            await openSavedChat(openPath);
            restored = true;
          }
        }
        else if (openType === 'scriptnote' || openType === 'scenario') {
          if (typeof openScenarioInScriptNote === 'function') {
            openScenarioInScriptNote(openPath, openLabel, _urlOpenOpts);
            restored = true;
          }
        }
      } finally {
        window._skipLastViewSave = previousSkipLastView;
      }
    }

    // Cloud starts at Home even when an older document/layout is remembered.
    // Keep saved tabs and unsaved drafts available for explicit recovery.
    if (!restored) {
      openedCloudStartupHome = await _openCloudStartupHome(homeRes, isUrlOpen, onboardingShown);
      restored = openedCloudStartupHome;
    }

    // v5.0 ペイン配置が復元済みなら、旧 lastView 復元でアクティブペインを上書きしない。
    if (!restored && restoredByPaneLayout) restored = true;

    // 前回のビューを即座に復元（URLパラメータがなかった場合）
    if (!restored) {
      const restoreStartedAt = typeof _perfNowMs === 'function' ? _perfNowMs() : Date.now();
      try {
        let last = _readLastViewFromStorage();
        if (last && _isCloudPhase1UnsupportedOpenType(last.type)) {
          localStorage.removeItem('lastView');
          _showCloudPhase1UnsupportedOpen(last.type);
          last = null;
        }
        const _expOpts = { fromExplorer: true, skipAutoAppLayout: true };
        if (last) {
          if (last.type === 'pivot' && last.dbPath) { await selectDatabase(last.dbPath, null, _expOpts); restored = true; }
          else if (last.type === 'entity' && last.entityPath) { selectEntity(last.entityPath, _expOpts); restored = true; }
          else if (last.type === 'page' && last.path) { openPage(last.label || '', last.path, _expOpts); restored = true; }
          else if (last.type === 'board' && last.path) { restored = await _restoreStartupBoardView(last.label || '', last.path, _expOpts); }
          else if (last.type === 'media' && last.path) { openMedia(last.label || '', last.path, last.mediaType || 'image', _expOpts); restored = true; }
          else if (last.type === 'html' && last.path) { openHtmlFile(last.label || '', last.path, _expOpts); restored = true; }
          else if (last.type === 'csv' && last.path) { if (typeof openCsvFile === 'function') { openCsvFile(last.label || '', last.path, _expOpts); restored = true; } }
          else if (last.type === 'scriptnote' && last.path && typeof openScenarioInScriptNote === 'function') { openScenarioInScriptNote(last.path, last.label || '', _expOpts); restored = true; }
          else if (last.type === 'folder' && last.path) { openFolder(last.label || '', last.path, _expOpts); restored = true; }
          else if (last.type === 'calendar' && last.path) { await openCalendarFile(last.label || '', last.path, _expOpts); restored = true; }
        }
      } catch (e) {}
      if (typeof _logPerfEvent === 'function') {
        _logPerfEvent('startup.restore-last-view', restoreStartedAt, { restored });
      }
    } // if (!restored) from URL params

    if (!restored && !_isDesktopStartupLaunch()) {
      const startupFolder = _startupFolderCandidate(roots, homeRes, vault);
      if (startupFolder?.path) {
        const _startupOpts = { fromExplorer: true, skipAutoAppLayout: true };
        await openFolder(startupFolder.label || _pathTailLabel(startupFolder.path, 'フォルダ'), startupFolder.path, _startupOpts);
        restored = true;
      }
    }

    // v5.0 ペインシステムがタブを復元している場合は welcome にフォールバックしない。
    // lastView ベースの復元が hit しなくても、ペイン配置が残っていれば画面は埋まっている。
    if (!restored) {
      const _paneHasTabs = _paneLayoutHasAnyTabs();
      if (!_paneHasTabs) showView('welcome');
    }

    // 起動後の重い補助処理は背景で継続し、表示を先に返す。
    _scheduleStartupDatabaseViewTabsRepair();
    _hideStartupSplash();
    if (typeof _logPerfEvent === 'function') {
      _logPerfEvent('startup.visible', initStartedAt, { restored });
    }
    _runStartupBackground('file-id-migration-finalize', rawMigrationPromise.then(() => _migratePathsToFileIds()), () => {
      if (state.currentDbPath && typeof _refreshDbViewConfigAfterHistory === 'function') {
        _refreshDbViewConfigAfterHistory(state.currentDbPath);
      }
    });
    _runStartupBackground('post-init-ready', Promise.allSettled([migrationPromise, outlinerPromise, linkDictPromise]), () => {
      initGlobalFilterBar();
      _runStartupBackground('outliner-startup-refresh', _refreshOutlinerAfterStartupReady(), () => {
        if (openedCloudStartupHome) highlightOutlinerNode(homeRes.path);
        else _highlightLastOutlinerNodeAfterStartup();
        showStatus('準備完了');
      });
    });
  } catch (e) {
    showStatus('ソースフォルダ情報の取得に失敗しました', true);
  }
  _hideStartupSplash();
}
/* ==============================
   表示切替
   ============================== */
function showView(viewName, ctx) {
  const resolvedViewName = ['calendar', 'tasks', 'shifts', 'gantt'].includes(viewName) ? 'timeline' : viewName;
  const isDbViewName = (name) => ['pivot', 'tree', 'gallery', 'kanban', 'timeline', 'gantt', 'chart', 'graph', 'form', 'calendar', 'tasks', 'shifts'].includes(name);
  // スプリットペイン内のビュー切替（ctxにcontainerElがある場合）
  if (ctx && ctx.containerEl) {
    const isDbView = isDbViewName(viewName);
    const c = ctx.containerEl;
    const hasPaneViewSurfaces = !!c.querySelector('#pivot-view, #tree-view, #gallery-view, #kanban-view, #timeline-view, #chart-view, #graph-view, #form-view, .pivot-view, .tree-view, .gallery-view, .kanban-view, .timeline-view, .chart-view, .graph-view, .form-view');
    if (hasPaneViewSurfaces) {
      const _sv = (sel, show) => { const el = c.querySelector(sel); if (el) el.style.display = show; };
      _sv('#db-view-container, .db-view-container', isDbView ? 'flex' : 'none');
      _sv('#pivot-view, .pivot-view', resolvedViewName === 'pivot' ? '' : 'none');
      _sv('#tree-view, .tree-view', resolvedViewName === 'tree' ? 'flex' : 'none');
      _sv('#gallery-view, .gallery-view', resolvedViewName === 'gallery' ? 'flex' : 'none');
      _sv('#kanban-view, .kanban-view', resolvedViewName === 'kanban' ? 'flex' : 'none');
      _sv('#timeline-view, .timeline-view', resolvedViewName === 'timeline' ? '' : 'none');
      _sv('#chart-view, .chart-view', resolvedViewName === 'chart' ? 'flex' : 'none');
      _sv('#graph-view, .graph-view', resolvedViewName === 'graph' ? 'flex' : 'none');
      _sv('#form-view, .form-view', resolvedViewName === 'form' ? 'flex' : 'none');
      ctx.viewMode = viewName;
      if (typeof _dbTreeSetOptionTabVisible === 'function') {
        _dbTreeSetOptionTabVisible(resolvedViewName === 'tree', ctx);
      }
      return;
    }
  }
  // ビュー切替前にボードの未保存を即時保存
  if (state.view === 'board' && viewName !== 'board' && typeof bd !== 'undefined' && bd.dirty && bd.path) {
    if (typeof bdSave === 'function') bdSave();
  }
  // ボードから離れたらノートタブを非表示
  if (state.view === 'board' && viewName !== 'board' && typeof hideBoardNoteTab === 'function') {
    hideBoardNoteTab();
  }
  // フォルダ以外のビューに切り替わったら一括処理バーを非表示
  if (viewName !== 'folder') {
    const fvBar = document.getElementById('fv-bulk-bar');
    if (fvBar) { fvBar.classList.remove('visible'); fvBar.hidden = true; fvBar.setAttribute('aria-hidden', 'true'); }
  }
  if (state.view === 'board' && viewName !== 'board' && typeof clearBoardDetailTabs === 'function') {
    clearBoardDetailTabs();
  }
  // viewName: 'welcome' | 'pivot' | 'gallery' | 'kanban' | 'entity' | 'page' | 'board'
  const isDbView = isDbViewName(viewName);
  const _setDisplay = (id, value) => {
    const el = document.getElementById(id);
    if (el) el.style.display = value;
  };
  _setDisplay('login-view', 'none');
  _setDisplay('welcome-view', resolvedViewName === 'welcome' ? 'flex' : 'none');
  _setDisplay('db-view-container', isDbView ? 'flex' : 'none');
  _setDisplay('pivot-view', resolvedViewName === 'pivot' ? '' : 'none');
  _setDisplay('tree-view', resolvedViewName === 'tree' ? 'flex' : 'none');
  _setDisplay('gallery-view', resolvedViewName === 'gallery' ? 'flex' : 'none');
  _setDisplay('kanban-view', resolvedViewName === 'kanban' ? 'flex' : 'none');
  _setDisplay('timeline-view', resolvedViewName === 'timeline' ? '' : 'none');
  _setDisplay('chart-view', resolvedViewName === 'chart' ? 'flex' : 'none');
  _setDisplay('graph-view', resolvedViewName === 'graph' ? 'flex' : 'none');
  _setDisplay('form-view', resolvedViewName === 'form' ? 'flex' : 'none');
  _setDisplay('compare-view', resolvedViewName === 'compare' ? 'flex' : 'none');
  _setDisplay('entity-view', resolvedViewName === 'entity' ? 'flex' : 'none');
  _setDisplay('page-view', resolvedViewName === 'page' ? 'flex' : 'none');
  _setDisplay('media-view', resolvedViewName === 'media' ? 'flex' : 'none');
  _setDisplay('html-view', resolvedViewName === 'html' ? 'flex' : 'none');
  _setDisplay('csv-view', resolvedViewName === 'csv' ? 'flex' : 'none');
  _setDisplay('folder-view', resolvedViewName === 'folder' ? 'flex' : 'none');
  if (typeof _dbTreeSetOptionTabVisible === 'function') {
    _dbTreeSetOptionTabVisible(resolvedViewName === 'tree');
  }
  // app-toolbarの表示切替
  const appTb = document.getElementById('app-toolbar');
  _setDisplay('tb-db', isDbView ? 'contents' : 'none');
  // ページビュー: app-toolbarにリッチテキストツールバー表示
  const showRtInAppbar = (resolvedViewName === 'page');
  _setDisplay('rt-toolbar', showRtInAppbar ? '' : 'none');
  const hasAppTb = isDbView || showRtInAppbar;
  if (appTb) appTb.classList.toggle('visible', hasAppTb);
  // エントリビュー: エントリ内ツールバー
  const entityRt = document.getElementById('entity-rt-toolbar');
  if (entityRt) entityRt.style.display = (resolvedViewName === 'entity') ? 'flex' : 'none';
  // ステータスバーのショートカットヘルプ
  const sc = document.getElementById('sb-shortcuts');
  if (isDbView) {
    const csvSheetActive = typeof isCsvSheetModeActive === 'function' && isCsvSheetModeActive();
    if (csvSheetActive && typeof updateCsvShortcutStatusbar === 'function') updateCsvShortcutStatusbar(sc);
    else if (typeof updateDatabaseShortcutStatusbar === 'function') updateDatabaseShortcutStatusbar(sc);
    else sc.textContent = '';
  } else if (resolvedViewName === 'entity' || resolvedViewName === 'page') {
    sc.textContent = 'Ctrl+B 太字 | Ctrl+I 斜体 | Ctrl+U 下線 | Ctrl+Shift+1~6 見出し | Ctrl+Shift+8 箇条書き | Tab インデント | Ctrl+Shift+↑↓ 移動';
  } else if (resolvedViewName === 'scriptnote') {
    if (typeof updateScriptnoteShortcutStatusbar === 'function') updateScriptnoteShortcutStatusbar(sc);
    else sc.textContent = 'Enter 行追加 | Ctrl+Enter 同タイプ行追加 | Shift+Del 行削除 | Tab タイプ選択 | Ctrl+↑↓ 行移動 | Ctrl+R ルビ | Ctrl+Z Undo | Ctrl+Y Redo';
  } else if (resolvedViewName === 'media') {
    if (typeof updateMediaViewerShortcutStatusbar === 'function') updateMediaViewerShortcutStatusbar(sc);
    else sc.textContent = '';
  } else {
    sc.textContent = '';
  }

  state.view = viewName;

  // メモ: ビュー切替時にターゲット更新＋再読み込み＋スクロール同期
  if (typeof ann !== 'undefined') {
    const newTarget = typeof getAnnotationTarget === 'function' ? getAnnotationTarget() : '';
    if (newTarget !== ann.targetPath) {
      ann.targetPath = newTarget;
      // 埋め込みサーフェス (board/html) の場合は iframe/bridge 側でロードされるため、
      // スタンドアロン側の loadAnnotations を呼ぶと同じアノテートが二重に描画される
      const embedded = typeof _usesEmbeddedAnnotationSurface === 'function'
        && _usesEmbeddedAnnotationSurface(viewName);
      if (embedded) {
        // 旧ビューからの残留（スタンドアロン overlay の描画＋付箋）をクリア
        const layer = document.getElementById('ann-layer');
        if (layer) layer.innerHTML = '';
        if (typeof _forEachStandaloneAnnotationNote === 'function') {
          _forEachStandaloneAnnotationNote(el => el.remove());
        }
      } else if (typeof loadAnnotations === 'function') {
        loadAnnotations();
      }
    }
    if (typeof _setupOverlayScroll === 'function') _setupOverlayScroll(viewName);
  }
}
// スクリーンショットメニュー
function showScreenshotMenu(e) {
  const btn = e?.target?.closest?.('button') || e?.target;
  const existing = document.querySelector('.ab-dropdown.ss-menu');
  if (existing) {
    existing.remove();
    btn?.setAttribute?.('aria-expanded', 'false');
    return;
  }
  const menu = document.createElement('div');
  menu.className = 'ab-dropdown ss-menu';
  menu.id = 'screenshot-menu';
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', 'スクリーンショット');
  if (btn?.setAttribute) {
    btn.setAttribute('aria-haspopup', 'menu');
    btn.setAttribute('aria-expanded', 'true');
    btn.setAttribute('aria-controls', menu.id);
  }
  let closed = false;
  let pointerCloser = null;
  let keyCloser = null;
  const closeMenu = (restoreFocus = false) => {
    if (closed) return;
    closed = true;
    if (pointerCloser) document.removeEventListener('pointerdown', pointerCloser, true);
    if (keyCloser) document.removeEventListener('keydown', keyCloser, true);
    if (btn?.setAttribute) btn.setAttribute('aria-expanded', 'false');
    menu.remove();
    if (restoreFocus) btn?.focus?.();
  };
  function addItem(label, fn, mode) {
    const item = document.createElement('button');
    item.type = 'button';
    item.className = 'ab-dropdown-item';
    item.setAttribute('role', 'menuitem');
    if (mode) item.dataset.screenshotMode = mode;
    item.textContent = label;
    item.addEventListener('click', () => { closeMenu(false); fn(); });
    menu.appendChild(item);
  }
  function addSep() {
    const s = document.createElement('div');
    s.className = 'ab-dropdown-sep';
    s.setAttribute('role', 'separator');
    menu.appendChild(s);
  }
  addItem('全画面キャプチャ', () => captureScreenshot('full'), 'full');
  addItem('範囲選択キャプチャ', () => captureScreenshot('region'), 'region');
  addSep();
  addItem('全画面（GB非表示）', () => captureScreenshot('full-hide'), 'full-hide');
  addItem('範囲選択（GB非表示）', () => captureScreenshot('region-hide'), 'region-hide');
  addSep();
  addItem('トレイアプリから操作', () => showStatus('Ctrl+Shift+S (全画面) / Ctrl+Shift+R (範囲) / Ctrl+Shift+W (ウィンドウ)'));
  document.body.appendChild(menu);
  const placeMenu = () => {
    if (!btn?.getBoundingClientRect) return;
    const rect = btn.getBoundingClientRect();
    if (typeof positionPopup === 'function') {
      positionPopup(menu, rect, { prefer: 'right', gap: 4 });
      return;
    }
    const z = _getZoom();
    menu.style.left = (rect.right / z + 4) + 'px';
    menu.style.top = (rect.top / z) + 'px';
    requestAnimationFrame(() => {
      const mr = menu.getBoundingClientRect();
      if (mr.bottom > window.innerHeight) menu.style.top = ((window.innerHeight - mr.height - 4) / z) + 'px';
      if (mr.right > window.innerWidth) menu.style.left = ((rect.left - mr.width - 4) / z) + 'px';
    });
  };
  placeMenu();
  menu.addEventListener('keydown', (ev) => {
    const items = [...menu.querySelectorAll('.ab-dropdown-item')];
    const index = items.indexOf(document.activeElement);
    if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp') {
      ev.preventDefault();
      const delta = ev.key === 'ArrowDown' ? 1 : -1;
      items[(index + delta + items.length) % items.length]?.focus();
    } else if (ev.key === 'Home') {
      ev.preventDefault();
      items[0]?.focus();
    } else if (ev.key === 'End') {
      ev.preventDefault();
      items.at(-1)?.focus();
    } else if (ev.key === 'Escape') {
      ev.preventDefault();
      closeMenu(true);
    }
  });
  pointerCloser = (ev) => {
    if (!menu.contains(ev.target) && !btn?.contains?.(ev.target)) closeMenu(false);
  };
  keyCloser = (ev) => {
    if (ev.key === 'Escape') {
      ev.preventDefault();
      closeMenu(true);
    }
  };
  document.addEventListener('pointerdown', pointerCloser, true);
  document.addEventListener('keydown', keyCloser, true);
  requestAnimationFrame(() => menu.querySelector('.ab-dropdown-item')?.focus());
}

function _screenshotModeIsRegion(mode) {
  return String(mode || '').includes('region');
}

async function _setMeldexWindowVisibilityForScreenshot(action, hwnds) {
  if (window.MeldexRuntimeAdapter?.isBrowserDataMode?.()) return null;
  try {
    const res = await fetch(API_BASE + '/app-window-visibility', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action, hwnds: hwnds || [] }),
    });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

async function _hideMeldexWindowForScreenshot() {
  const state = await _setMeldexWindowVisibilityForScreenshot('hide');
  if (!state?.hidden) window.blur();
  await new Promise(r => setTimeout(r, 500));
  return state;
}

async function _restoreMeldexWindowForScreenshot(state) {
  if (state?.hidden) await _setMeldexWindowVisibilityForScreenshot('restore', state.hwnds || []);
  else window.focus();
}

function _cropScreenshotCanvas(canvas, region) {
  const cropped = document.createElement('canvas');
  cropped.width = Math.max(1, Math.round(region.width));
  cropped.height = Math.max(1, Math.round(region.height));
  cropped.getContext('2d').drawImage(
    canvas,
    Math.round(region.x),
    Math.round(region.y),
    cropped.width,
    cropped.height,
    0,
    0,
    cropped.width,
    cropped.height
  );
  return cropped;
}

function _selectScreenshotRegionFromCanvas(canvas) {
  return new Promise(resolve => {
    if (typeof window.GBUI?.createModal !== 'function') {
      resolve(null);
      return;
    }
    const restoreFocusTo = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const stage = document.createElement('div');
    stage.className = 'screenshot-region-stage';
    stage.dataset.e2eId = 'screenshot-region-stage';
    stage.tabIndex = 0;
    stage.setAttribute('role', 'group');
    stage.setAttribute('aria-label', '保存する範囲');

    const preview = document.createElement('canvas');
    preview.className = 'screenshot-region-preview';
    preview.setAttribute('aria-hidden', 'true');
    preview.width = canvas.width;
    preview.height = canvas.height;
    preview.getContext('2d').drawImage(canvas, 0, 0);
    const maxW = Math.max(1, Math.floor(window.innerWidth * 0.94));
    const maxH = Math.max(1, Math.floor(window.innerHeight * 0.82));
    const scale = Math.min(maxW / canvas.width, maxH / canvas.height, 1);
    preview.style.width = Math.max(1, Math.round(canvas.width * scale)) + 'px';
    preview.style.height = Math.max(1, Math.round(canvas.height * scale)) + 'px';

    const selection = document.createElement('div');
    selection.className = 'screenshot-region-selection';
    selection.setAttribute('aria-hidden', 'true');
    selection.style.display = 'none';

    const actions = document.createElement('div');
    actions.className = 'screenshot-region-actions';
    actions.style.width = '100%';
    actions.style.minWidth = '0';
    actions.setAttribute('aria-label', '範囲選択の操作');

    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.className = 'gb-btn gb-btn-sm';
    cancel.style.flex = '0.8 1 0';
    cancel.dataset.e2eId = 'screenshot-region-cancel';
    cancel.textContent = 'キャンセル';

    const ok = document.createElement('button');
    ok.type = 'button';
    ok.className = 'gb-btn gb-btn-sm gb-btn-primary';
    ok.style.flex = '1.5 1 0';
    ok.style.minWidth = '0';
    ok.dataset.e2eId = 'screenshot-region-save';
    ok.textContent = 'スクリーンショット撮影';

    stage.append(preview, selection);
    actions.append(cancel, ok);

    let start = null;
    let current = null;
    let activePointerId = null;
    let cleaned = false;
    let result = null;
    let modalApi = null;

    const cleanup = (value, reason = 'programmatic') => {
      if (cleaned) return;
      result = value;
      modalApi.close(reason);
    };
    const pointFromEvent = (ev) => {
      const rect = preview.getBoundingClientRect();
      return {
        x: Math.max(0, Math.min(rect.width, ev.clientX - rect.left)),
        y: Math.max(0, Math.min(rect.height, ev.clientY - rect.top)),
        rect,
      };
    };
    const visibleRect = () => {
      if (!start || !current) return null;
      const left = Math.min(start.x, current.x);
      const top = Math.min(start.y, current.y);
      const width = Math.abs(current.x - start.x);
      const height = Math.abs(current.y - start.y);
      return { left, top, width, height };
    };
    const updateSelection = () => {
      const rect = visibleRect();
      if (!rect || rect.width < 1 || rect.height < 1) {
        selection.style.display = 'none';
        return;
      }
      selection.style.display = 'block';
      selection.style.left = rect.left + 'px';
      selection.style.top = rect.top + 'px';
      selection.style.width = rect.width + 'px';
      selection.style.height = rect.height + 'px';
    };
    const canvasRegion = () => {
      const rect = visibleRect();
      if (!rect || rect.width < 4 || rect.height < 4) return null;
      const bounds = preview.getBoundingClientRect();
      const scaleX = canvas.width / bounds.width;
      const scaleY = canvas.height / bounds.height;
      const x = Math.max(0, Math.min(canvas.width - 1, rect.left * scaleX));
      const y = Math.max(0, Math.min(canvas.height - 1, rect.top * scaleY));
      return {
        x,
        y,
        width: Math.max(1, Math.min(canvas.width - x, rect.width * scaleX)),
        height: Math.max(1, Math.min(canvas.height - y, rect.height * scaleY)),
      };
    };
    function onKeyDown(ev) {
      if (ev.key === 'Enter') {
        const region = canvasRegion();
        if (region) cleanup(region, 'submit');
      }
    }
    stage.addEventListener('pointerdown', (ev) => {
      if (ev.button !== 0) return;
      ev.preventDefault();
      stage.focus?.();
      activePointerId = ev.pointerId;
      try { stage.setPointerCapture?.(ev.pointerId); } catch {}
      start = pointFromEvent(ev);
      current = start;
      updateSelection();
    });
    stage.addEventListener('pointermove', (ev) => {
      if (activePointerId == null || ev.pointerId !== activePointerId) return;
      current = pointFromEvent(ev);
      updateSelection();
    });
    stage.addEventListener('pointerup', (ev) => {
      if (activePointerId == null || ev.pointerId !== activePointerId) return;
      current = pointFromEvent(ev);
      try { stage.releasePointerCapture?.(ev.pointerId); } catch {}
      activePointerId = null;
      updateSelection();
    });
    stage.addEventListener('pointercancel', (ev) => {
      if (activePointerId != null && ev.pointerId === activePointerId) activePointerId = null;
    });
    cancel.addEventListener('click', () => cleanup(null, 'cancel'));
    ok.addEventListener('click', () => {
      const region = canvasRegion();
      if (!region) {
        showStatus('範囲を選択してください', true);
        return;
      }
      cleanup(region, 'submit');
    });
    document.addEventListener('keydown', onKeyDown);
    modalApi = window.GBUI.createModal({
      id: 'screenshot-region-selector',
      title: 'スクリーンショット撮影対象を選択',
      body: stage,
      footer: actions,
      variant: 'full-bleed',
      extraClass: 'screenshot-region-shell',
      geometryKey: 'screenshot-region-selector',
      minWidth: '0',
      initialFocus: stage,
      returnFocus: restoreFocusTo || undefined,
      closeLabel: '範囲選択を閉じる',
      closeOnEsc: true,
      closeOnOverlay: true,
      onClose: () => {
        if (cleaned) return;
        cleaned = true;
        document.removeEventListener('keydown', onKeyDown);
        resolve(result);
      },
    });
    const overlay = modalApi.overlay;
    overlay.classList.add('modal-overlay', 'screenshot-region-overlay');
    overlay.dataset.e2eId = 'screenshot-region-overlay';
    overlay.style.zIndex = '5000';
    overlay._screenshotRegionModalApi = modalApi;
    modalApi.modal.dataset.e2eId = 'screenshot-region-shell';
    modalApi.footer.classList.add('screenshot-region-actions');
    modalApi.open();
  });
}

async function captureScreenshot(mode) {
  let stream = null;
  let hideState = null;
  try {
    const hideFirst = mode.includes('hide');
    if (hideFirst) hideState = await _hideMeldexWindowForScreenshot();
    stream = await navigator.mediaDevices.getDisplayMedia({ video: { displaySurface: 'monitor' } });
    const video = document.createElement('video');
    const loaded = new Promise((resolve, reject) => {
      video.onloadeddata = resolve;
      video.onerror = () => reject(new Error('画面キャプチャ映像を読み込めませんでした'));
    });
    video.srcObject = stream;
    await video.play();
    await loaded;
    await new Promise(r => setTimeout(r, 200));
    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth; canvas.height = video.videoHeight;
    canvas.getContext('2d').drawImage(video, 0, 0);
    stream.getTracks().forEach(t => t.stop());
    stream = null;
    if (hideFirst) {
      await _restoreMeldexWindowForScreenshot(hideState);
      hideState = null;
    }
    let outputCanvas = canvas;
    if (_screenshotModeIsRegion(mode)) {
      const region = await _selectScreenshotRegionFromCanvas(canvas);
      if (!region) return;
      outputCanvas = _cropScreenshotCanvas(canvas, region);
    }
    const b64 = outputCanvas.toDataURL('image/png');
    const screenshotHome = ((typeof _homeFolderPath !== 'undefined' ? _homeFolderPath : '') || '').replace(/[\\/]$/, '');
    const defaultScreenshotFolder = screenshotHome ? screenshotHome + '/スクリーンショット' : 'スクリーンショット';
    const screenshotFolder = localStorage.getItem('meldex-screenshot-folder') || defaultScreenshotFolder;
    const currentTarget = (typeof getAnnotationTarget === 'function' ? getAnnotationTarget() : (typeof currentFilePath !== 'undefined' ? currentFilePath : '')) || '';
    const res = await apiPost('/annotation/screenshot', {
      data: b64,
      target_path: screenshotFolder,
      source_target: currentTarget,
      mode: mode,
      width: outputCanvas.width,
      height: outputCanvas.height,
    });
    if (res.path) {
      if (typeof loadRpAnnotationList === 'function') loadRpAnnotationList();
      showStatus('スクリーンショットを保存しました', false, { showSaveDialog: true });
    }
  } catch (e) {
    if (e.name !== 'NotAllowedError') showStatus('スクリーンショット失敗: ' + e.message, true);
  } finally {
    if (stream) stream.getTracks().forEach(t => t.stop());
    if (hideState) await _restoreMeldexWindowForScreenshot(hideState);
  }
}

// モバイル: スワイプでサイドバー開閉
(function() {
  let touchStartX = 0, touchStartY = 0;
  document.addEventListener('touchstart', (e) => {
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
  }, { passive: true });
  document.addEventListener('touchend', (e) => {
    if (window.innerWidth > 768) return;
    const dx = e.changedTouches[0].clientX - touchStartX;
    const dy = e.changedTouches[0].clientY - touchStartY;
    if (Math.abs(dx) < 60 || Math.abs(dy) > Math.abs(dx)) return; // 横スワイプのみ
    const sidebar = document.getElementById('sidebar');
    const backdrop = document.getElementById('sidebar-backdrop');
    if (dx > 0 && touchStartX < 40 && !sidebar.classList.contains('open')) {
      // 左端から右スワイプ → サイドバー開く
      sidebar.classList.add('open');
      if (backdrop) {
        backdrop.classList.add('open');
        backdrop.style.setProperty('display', 'block', 'important');
      }
    } else if (dx < 0 && sidebar.classList.contains('open')) {
      // 左スワイプ → サイドバー閉じる
      sidebar.classList.remove('open');
      if (backdrop) {
        backdrop.classList.remove('open');
        backdrop.style.setProperty('display', 'none', 'important');
      }
    }
  }, { passive: true });
})();

/* ==============================
   ステータスバー
   ============================== */
// メッセージ先頭行をタイトル、残りを本文として安全なDOMへ変換する。
// 単一行メッセージは従来通り本文だけ、複数行のみ先頭行を強調する。
function _buildCfDialogBodyNodes(message, idBase) {
  const text = String(message ?? '');
  if (!text) return [];
  const lines = text.split('\n');
  const entries = lines.length < 2
    ? [{ text, kind: 'body' }]
    : [
        { text: (lines.shift() || '').trim(), kind: 'title' },
        { text: lines.join('\n').trim(), kind: 'muted' },
      ];
  return entries.filter(entry => entry.text).map((entry, index) => {
    const node = document.createElement('div');
    node.className = 'gb-confirm-message';
    node.id = `${idBase}-message-${index}`;
    node.textContent = entry.text;
    if (entry.kind === 'title') node.style.fontWeight = '600';
    if (entry.kind === 'muted') node.style.color = 'var(--ui-fg-muted)';
    return node;
  });
}

// 短い問いかけ用の .gb-confirm 表示を保ちつつ、生成・閉鎖・フォーカス・
// モバイル変換を GBUI.createModal へ統一する。
// - OK ボタンは .gb-btn-primary 基準、message に「削除」が含まれる場合は .gb-btn-danger + ラベル「削除」に自動切替
// - options.danger で明示指定可、options.okLabel / options.cancelLabel で文言上書き可
function _cfIsDeleteMessage(text) {
  // 破壊的操作を示唆するキーワード。
  // 「元に戻す」(= undo) は破壊的でないため「デフォルト.*戻」のみ (リセット系) を拾う。
  // 「を空に」は「ゴミ箱を空にする/します/しますか」を両活用形でカバーする。
  return /削除|破棄|除去|消去|初期化|リセット|を空に|デフォルト.{0,8}戻/.test(String(text || ''));
}

let _cfDialogSeq = 0;
function _cfRestoreFocusTarget() {
  return document.activeElement instanceof HTMLElement ? document.activeElement : null;
}

function _cfIsTopmostDialog(dialog) {
  const managed = window.GBDialogKeyboard?.topmostDialog?.();
  if (managed) return managed === dialog;
  const dialogs = [...document.querySelectorAll('[role="dialog"][aria-modal="true"], [role="alertdialog"][aria-modal="true"]')]
    .filter(node => node.isConnected && !node.hidden);
  return !dialogs.length || dialogs[dialogs.length - 1] === dialog;
}

function _configureCfModal(modalApi, kind, label, role, messageNodes, idBase) {
  modalApi.overlay.classList.add('modal-overlay');
  modalApi.overlay.dataset.e2eId = `${kind}-overlay`;
  modalApi.modal.classList.add('gb-confirm');
  modalApi.modal.dataset.e2eId = `${kind}-dialog`;
  modalApi.modal.dataset.dialogType = kind;
  modalApi.modal.id = `${idBase}-dialog`;
  modalApi.modal.setAttribute('role', role);
  modalApi.modal.setAttribute('aria-label', label);
  const closeButton = modalApi.header.querySelector('.gb-modal-close');
  if (closeButton) closeButton.dataset.e2eId = `${kind}-close`;
  if (messageNodes.length) {
    modalApi.modal.setAttribute('aria-describedby', messageNodes.map(node => node.id).join(' '));
  }
  modalApi.footer.classList.add('gb-confirm-actions');
  return modalApi;
}

function _completeCfModalPromise(modalApi, resolve, value) {
  const settle = () => {
    if (modalApi?.overlay?.isConnected) {
      setTimeout(settle, 40);
      return;
    }
    // GBUI.createModal のフォーカス復帰は、モバイル下端シートの閉じるアニメーション後に
    // 同じ40ms周期で実行される。onClose時点で先にPromiseを解決すると、直後に開いた
    // ダイアログから旧ダイアログの復帰処理がフォーカスを奪うため、次タスクまで待つ。
    setTimeout(() => resolve(value), 0);
  };
  settle();
}

// カスタムalertダイアログ（alert()の代替、画面中央モーダル）
function cfAlert(message, options) {
  const opts = options || {};
  const okLabel = opts.okLabel || 'OK';
  const showSupport = opts.support !== false && /HTTP\s+\d{3}|Error|エラー|失敗|例外/.test(String(message || ''));
  if (typeof window.GBUI?.createModal !== 'function') {
    if (typeof window.alert === 'function') window.alert(String(message || ''));
    return Promise.resolve();
  }
  return new Promise(resolve => {
    const restoreFocusTo = _cfRestoreFocusTarget();
    const idBase = `gb-cf-alert-${++_cfDialogSeq}`;
    const messageNodes = _buildCfDialogBodyNodes(message, idBase);
    const supportButton = document.createElement('button');
    supportButton.type = 'button';
    supportButton.id = '_gb-support';
    supportButton.className = 'gb-btn gb-btn-sm';
    supportButton.textContent = 'サポートに送信';
    const ok = document.createElement('button');
    ok.type = 'button';
    ok.id = '_gb-ok';
    ok.className = 'gb-btn gb-btn-sm gb-btn-primary';
    ok.textContent = okLabel;
    let modalApi = null;
    const onDocumentKeydown = event => {
      if (event.key !== 'Enter' || !_cfIsTopmostDialog(modalApi?.modal)) return;
      const active = document.activeElement;
      const interactive = active?.closest?.('button, a[href], input, select, textarea, [contenteditable="true"], [role="button"]');
      if (interactive && modalApi.modal.contains(interactive)) return;
      event.preventDefault();
      modalApi.close('submit');
    };
    modalApi = _configureCfModal(window.GBUI.createModal({
      id: idBase,
      titleId: `${idBase}-title`,
      title: 'お知らせ',
      body: messageNodes,
      footer: showSupport ? [supportButton, ok] : [ok],
      variant: 'standard',
      extraClass: 'gb-confirm',
      geometryKey: 'cf-alert',
      initialFocus: () => ok,
      returnFocus: () => restoreFocusTo,
      closeLabel: 'お知らせを閉じる',
      closeOnEsc: true,
      closeOnOverlay: true,
      onClose: () => {
        document.removeEventListener('keydown', onDocumentKeydown);
        _completeCfModalPromise(modalApi, resolve);
      },
    }), 'cf-alert', 'お知らせ', 'alertdialog', messageNodes, idBase);
    ok.addEventListener('click', () => modalApi.close('submit'));
    supportButton.addEventListener('click', () => {
      window.MeldexDiagnostics?.showSupportDialog?.(new Error(String(message || '')), { kind: 'cfAlert' });
    });
    document.addEventListener('keydown', onDocumentKeydown);
    modalApi.open();
  });
}

// カスタムconfirmダイアログ（confirm()の代替、画面中央モーダル）
// options: { danger?: boolean, okLabel?: string, cancelLabel?: string, extraNode?: Node }
// extraNode: メッセージ本文とボタン列の間に挿入する追加DOM要素（呼び出し元が
// textContent等で安全に組み立てたNodeを渡す想定。innerHTML文字列連結はしない。
// ファイル参照整合性計画 Phase 4: 削除確認ダイアログへの被参照警告表示に使う
// （app/gb-delete-impact-warning.js 参照）。
function cfConfirm(message, options) {
  if (typeof window.cfConfirm === 'function' && window.cfConfirm !== cfConfirm) {
    return window.cfConfirm(message, options);
  }
  const opts = options || {};
  const extraNode = opts.extraNode instanceof Node ? opts.extraNode : null;
  const autoDanger = _cfIsDeleteMessage(message);
  const isDanger = opts.danger !== undefined ? !!opts.danger : autoDanger;
  const defaultOk = isDanger ? (autoDanger && /削除/.test(String(message)) ? '削除' : '実行') : '決定';
  const okLabel = opts.okLabel || defaultOk;
  const cancelLabel = opts.cancelLabel || 'キャンセル';
  const okVariant = isDanger ? 'gb-btn-danger' : 'gb-btn-primary';
  if (typeof window.GBUI?.createModal !== 'function') {
    const nativeValue = typeof window.confirm === 'function' ? window.confirm(String(message || '')) : false;
    return Promise.resolve(nativeValue);
  }
  return new Promise(resolve => {
    const restoreFocusTo = _cfRestoreFocusTarget();
    const idBase = `gb-cf-confirm-${++_cfDialogSeq}`;
    const messageNodes = _buildCfDialogBodyNodes(message, idBase);
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.id = '_gb-cancel';
    cancel.className = 'gb-btn gb-btn-sm';
    cancel.textContent = cancelLabel;
    const ok = document.createElement('button');
    ok.type = 'button';
    ok.id = '_gb-ok';
    ok.className = `gb-btn gb-btn-sm ${okVariant}`;
    ok.textContent = okLabel;
    let result = false;
    let modalApi = null;
    const finish = (value, reason) => {
      result = value;
      modalApi.close(reason);
    };
    const onDocumentKeydown = event => {
      // 通常モードは Enter = OK のショートカット。
      // danger モードは誤操作防止のため Enter のショートカットを無効化し、
      // フォーカスされたボタン (初期は cancel) の自然な Enter 起動に任せる。
      if (event.key === 'Enter' && !isDanger && _cfIsTopmostDialog(modalApi?.modal)) {
        const active = document.activeElement;
        const interactive = active?.closest?.('button, a[href], input, select, textarea, [contenteditable="true"], [role="button"]');
        if (interactive && modalApi.modal.contains(interactive)) return;
        event.preventDefault();
        finish(true, 'submit');
      }
    };
    modalApi = _configureCfModal(window.GBUI.createModal({
      id: idBase,
      titleId: `${idBase}-title`,
      title: '確認',
      body: extraNode ? [...messageNodes, extraNode] : messageNodes,
      footer: [cancel, ok],
      variant: 'standard',
      extraClass: 'gb-confirm',
      geometryKey: 'cf-confirm',
      initialFocus: () => isDanger ? cancel : ok,
      returnFocus: () => restoreFocusTo,
      closeLabel: '確認をキャンセル',
      closeOnEsc: true,
      closeOnOverlay: true,
      onClose: () => {
        document.removeEventListener('keydown', onDocumentKeydown);
        _completeCfModalPromise(modalApi, resolve, result);
      },
    }), 'cf-confirm', '確認', 'alertdialog', messageNodes, idBase);
    ok.addEventListener('click', () => finish(true, 'submit'));
    cancel.addEventListener('click', () => finish(false, 'cancel'));
    document.addEventListener('keydown', onDocumentKeydown);
    modalApi.open();
  });
}
// カスタムpromptダイアログ（prompt()の代替）
function cfPrompt(message, defaultValue, options) {
  const opts = options || {};
  const okLabel = opts.okLabel || '決定';
  const cancelLabel = opts.cancelLabel || 'キャンセル';
  if (typeof window.GBUI?.createModal !== 'function') {
    const nativeValue = typeof window.prompt === 'function'
      ? window.prompt(String(message || ''), String(defaultValue ?? ''))
      : null;
    return Promise.resolve(nativeValue);
  }
  return new Promise(resolve => {
    const restoreFocusTo = _cfRestoreFocusTarget();
    const idBase = `gb-cf-prompt-${++_cfDialogSeq}`;
    const messageNodes = _buildCfDialogBodyNodes(message, idBase);
    const input = document.createElement('input');
    input.type = 'text';
    input.id = '_gb-prompt-input';
    input.className = 'gb-confirm-input';
    input.value = String(defaultValue ?? '');
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.id = '_gb-cancel';
    cancel.className = 'gb-btn gb-btn-sm';
    cancel.textContent = cancelLabel;
    const ok = document.createElement('button');
    ok.type = 'button';
    ok.id = '_gb-ok';
    ok.className = 'gb-btn gb-btn-sm gb-btn-primary';
    ok.textContent = okLabel;
    let result = null;
    let modalApi = null;
    const finish = (value, reason) => {
      result = value;
      modalApi.close(reason);
    };
    modalApi = _configureCfModal(window.GBUI.createModal({
      id: idBase,
      titleId: `${idBase}-title`,
      title: '入力',
      body: [...messageNodes, input],
      footer: [cancel, ok],
      variant: 'standard',
      extraClass: 'gb-confirm',
      geometryKey: 'cf-prompt',
      initialFocus: () => input,
      returnFocus: () => restoreFocusTo,
      closeLabel: '入力をキャンセル',
      closeOnEsc: true,
      closeOnOverlay: true,
      onClose: () => _completeCfModalPromise(modalApi, resolve, result),
    }), 'cf-prompt', '入力', 'dialog', messageNodes, idBase);
    ok.addEventListener('click', () => finish(input.value, 'submit'));
    cancel.addEventListener('click', () => finish(null, 'cancel'));
    input.addEventListener('keydown', event => {
      if (event.key === 'Enter') {
        event.preventDefault();
        finish(input.value, 'submit');
      }
    });
    modalApi.open();
    requestAnimationFrame(() => input.select());
  });
}

// showStatus() は meldex-core.js で定義済み（nullチェック付き）

// xlsx取込: ファイル選択 → 新規台本作成 → 台本エディタで開く
function importXlsxToOutliner() {
  document.getElementById('xlsx-import-input').click();
}

function _readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(reader.error || new Error('ファイルを読み込めませんでした'));
    reader.readAsDataURL(file);
  });
}

async function handleXlsxImportToOutliner(e) {
  const file = e.target.files[0];
  if (!file) return;
  e.target.value = '';
  if (!/\.xlsx$/i.test(file.name)) {
    showStatus('xlsx取込は .xlsx ファイルを選択してください', true);
    return;
  }

  // ファイル名（拡張子なし）を台本名にする
  const baseName = file.name.replace(/\.xlsx$/i, '');

  try {
    const data = await _readFileAsDataUrl(file);
    const res = await apiPost('/import-xlsx-scriptnote', {
      filename: file.name,
      title: baseName,
      data,
    });
    const scriptnotePath = res.path || res.node?.path;
    const label = res.label || baseName;

    // 台本エディタで開く
    if (scriptnotePath && typeof openScenarioInScriptNote === 'function') {
      openScenarioInScriptNote(scriptnotePath, label);
    }

    // フォルダツリーをリロード
    await loadOutliner();
    showStatus(`xlsx取込: ${label}`);
  } catch (err) {
    showStatus('xlsx取込に失敗しました: ' + err.message, true);
  }
}

// Phase C: ボードエンジンはgb-canvas-engine.js + gb-canvas-features.js + gb-canvas-interact.js に移行済み
// bd オブジェクトは gb-canvas-engine.js で定義

// グローバルdrop防止（未処理エリアへのドロップでブラウザがファイルを開くのを防ぐ）
document.addEventListener('dragover', (e) => { e.preventDefault(); }, false);
document.addEventListener('drop', (e) => {
  // 個別ハンドラでpreventDefaultされていない場合のみ（フォールバック）
  if (!e.defaultPrevented) e.preventDefault();
}, false);
// timeline-view(カレンダー)へのD&Dドロップ（ファイルから新規イベント作成）
function _appLocalDateTimeInputValue(date) {
  if (typeof formatLocalDateTime === 'function') return formatLocalDateTime(date);
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
  const pad = (n) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function _appShouldHandleStandaloneCalendarDrop() {
  return state.view === 'timeline'
    && !state.currentDbPath
    && typeof _showCalEventInDetailPanel === 'function';
}

{
  const tv = document.getElementById('timeline-view');
  if (tv) tv.addEventListener('dragover', (e) => {
    if (e.dataTransfer.types.includes('application/x-meldex-node') && _appShouldHandleStandaloneCalendarDrop()) e.preventDefault();
  });
  if (tv) tv.addEventListener('drop', (e) => {
    if (!_appShouldHandleStandaloneCalendarDrop()) return;
    const cfData = e.dataTransfer.getData('application/x-meldex-node');
    if (!cfData) return;
    e.preventDefault();
    try {
      const { name, path } = JSON.parse(cfData);
      // 詳細パネルにイベント編集を表示（タイトルにファイル名、リンク付き）
      const now = new Date();
      const startVal = _appLocalDateTimeInputValue(now);
      const endH = new Date(now.getTime() + 3600000);
      const endVal = _appLocalDateTimeInputValue(endH);
      if (typeof _showCalEventInDetailPanel === 'function') {
        _showCalEventInDetailPanel(
          { title: name, description: '[[' + name + ']](' + path + ')' },
          [], startVal, endVal, false
        );
      }
    } catch {}
  });
}

// main-viewsへのD&Dドロップ
// 通常ドロップ: 各ビュー固有のハンドラに委ねる（ノート→リンク挿入、キャンバス→ノード追加）
// Ctrl+ドロップ: ファイルをそのパネルで開く
{
  const mv = document.getElementById('main-views');
  // 注意: #sidebar は GBLayout のドッキング対象として #gb-layout-root（#main-views の
  // 子孫）へ組み込まれるため、フォルダツリー（お気に入り・最近使った項目・ワークスペースを
  // 含む #sidebar 全体）は実行時には #main-views の子孫になる。Ctrl+ドロップでパネルに
  // 開くこの機能は「ドロップ先がツリー以外のパネル領域」の場合だけに限定し、ツリー内へ
  // Ctrl+ドロップしても項目が開かないようにする（フォルダツリー改修 Phase 2 §2.5・§9）。
  const _isMainViewsSidebarDrop = (e) => !!e.target?.closest?.('#sidebar');
  if (mv) mv.addEventListener('dragover', (e) => {
    if (e.dataTransfer.types.includes('application/x-meldex-node')) {
      // Ctrl+ドラッグ時のみmain-viewsレベルで受け付け（ファイルを開く）
      // 通常時は各ビュー固有のdragoverに委ねる
      if (e.ctrlKey && state.view !== 'board' && !_isMainViewsSidebarDrop(e)) e.preventDefault();
    }
  });
  if (mv) mv.addEventListener('drop', (e) => {
    // Ctrl+ドロップ: ファイルをパネルで開く
    if (!e.ctrlKey) return; // 通常ドロップは各ビュー固有ハンドラに委ねる
    if (state.view === 'board') return;
    if (_isMainViewsSidebarDrop(e)) return; // フォルダツリー（サイドバー）内へのCtrl+ドロップでは開かない
    const cfData = e.dataTransfer.getData('application/x-meldex-node');
    if (!cfData) return;
    e.preventDefault();
    try {
      const { name, path, type } = JSON.parse(cfData);
      const navType = typeof _normalizeOpenTypeForNav === 'function'
        ? _normalizeOpenTypeForNav(type)
        : (type === 'database' ? 'pivot' : type === 'board' ? 'board' : (type || 'page'));
      navOpen({ type: navType, label: name, path });
    } catch {}
  });
}

// Phase D: HTMLビューワー(viewer.html)のiframe通信のみ残存
// canvas/calendarのpostMessageはPhase Cで直接関数呼び出しに変換済み
function _getTrustedEmbeddedMessageIframe(e) {
  if (!e) return null;
  const candidates = [];
  const addCandidate = iframe => {
    if (iframe && !candidates.includes(iframe)) candidates.push(iframe);
  };
  addCandidate((typeof _getActiveIframe === 'function') ? _getActiveIframe() : null);
  addCandidate(document.getElementById('html-iframe'));
  document.querySelectorAll('iframe').forEach(addCandidate);
  for (const iframe of candidates) {
    if (!iframe?.contentWindow || e.source !== iframe.contentWindow) continue;
    const iframeSrc = iframe.getAttribute('src') || iframe.src || '';
    if (!_gbIsTrustedInternalViewerUrl(iframeSrc)) continue;
    if (e.origin === window.location.origin || e.origin === 'null') return iframe;
  }
  return null;
}

function _isTrustedEmbeddedMessage(e) {
  return !!_getTrustedEmbeddedMessageIframe(e);
}

function _syncViewerCurrentFileFromMessage(msg) {
  const path = typeof msg?.path === 'string' ? msg.path : '';
  if (!path) return false;
  state.currentPagePath = path;
  if (typeof highlightOutlinerNode === 'function') highlightOutlinerNode(path);
  if (typeof _showFileInfoInDetailPanel === 'function') _showFileInfoInDetailPanel(path);
  return true;
}

const _VIEWER_FOLDER_NAV_FILE_EXTS = new Set([
  '.png', '.apng', '.jpg', '.jpeg', '.jpe', '.jfif', '.gif', '.bmp', '.webp',
  '.svg', '.ico', '.avif', '.tif', '.tiff', '.heic', '.heif', '.psd', '.psb',
  '.pdf',
]);
const _viewerFolderNavDisplayableCache = new Map();

function _viewerFolderNavCleanPath(path) {
  return String(path || '').replace(/\\/g, '/').split('#')[0].split('?')[0].replace(/\/+$/, '');
}

function _viewerFolderNavExt(path) {
  const name = _viewerFolderNavCleanPath(path).split('/').pop() || '';
  const index = name.lastIndexOf('.');
  return index >= 0 ? name.slice(index).toLowerCase() : '';
}

function _viewerFolderNavIsDisplayableFile(path) {
  return _VIEWER_FOLDER_NAV_FILE_EXTS.has(_viewerFolderNavExt(path));
}

function _viewerFolderNavParentPath(path) {
  const clean = _viewerFolderNavCleanPath(path);
  if (!clean) return '';
  if (!_viewerFolderNavIsDisplayableFile(clean)) return clean;
  const index = clean.lastIndexOf('/');
  return index >= 0 ? clean.slice(0, index) : '';
}

function _viewerFolderNavCurrentFolderFromMessage(msg) {
  const folderPath = _viewerFolderNavCleanPath(msg?.folderPath || '');
  if (folderPath) return folderPath;
  return _viewerFolderNavParentPath(msg?.currentPath || msg?.path || state.currentPagePath || '');
}

function _viewerFolderNavNodePath(node) {
  return _viewerFolderNavCleanPath(node?._nodeData?.path || node?.dataset?.path || '');
}

function _viewerFolderNavPathMatches(nodePath, targetPath) {
  if (typeof _outlinerHighlightPathMatches === 'function') return _outlinerHighlightPathMatches(nodePath, targetPath);
  const a = _viewerFolderNavCleanPath(nodePath).toLowerCase();
  const b = _viewerFolderNavCleanPath(targetPath).toLowerCase();
  return !!a && !!b && (a === b || a.endsWith('/' + b) || b.endsWith('/' + a));
}

function _viewerFolderNavIsFolderNode(node) {
  const data = node?._nodeData || {};
  if (!node || node.style?.display === 'none') return false;
  return data.type === 'folder' || data._isRoot === true;
}

function _viewerFolderNavFolderNodes() {
  const candidates = [...document.querySelectorAll('#outliner-tree .tree-node, #body-home .tree-node')];
  return candidates.filter(node => _viewerFolderNavIsFolderNode(node) && _viewerFolderNavNodePath(node));
}

function _viewerFolderNavFindIndex(nodes, targetPath) {
  if (!targetPath) return -1;
  return nodes.findIndex(node => _viewerFolderNavPathMatches(_viewerFolderNavNodePath(node), targetPath));
}

function _viewerFolderNavDelay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function _viewerFolderNavEnsureNodeExpanded(node) {
  const toggle = node?.querySelector?.(':scope > .tree-node-row .tree-toggle');
  if (!toggle || toggle.dataset.expanded === undefined || toggle.dataset.expanded === 'true') return false;
  const childrenDiv = node.querySelector(':scope > .tree-children');
  toggle.click();
  for (let i = 0; i < 30; i++) {
    await _viewerFolderNavDelay(100);
    if (!childrenDiv) break;
    if (!childrenDiv.classList.contains('collapsed') && childrenDiv.dataset.loaded === 'true') break;
  }
  return true;
}

async function _viewerFolderNavEnsureAncestorsExpanded(node) {
  const ancestors = [];
  let parent = node?.parentElement?.closest?.('.tree-node') || null;
  while (parent) {
    ancestors.unshift(parent);
    parent = parent.parentElement?.closest?.('.tree-node') || null;
  }
  for (const ancestor of ancestors) {
    await _viewerFolderNavEnsureNodeExpanded(ancestor);
  }
}

async function _viewerFolderNavRevealCurrentFolder(folderPath, options = {}) {
  if (!folderPath) return;
  if (typeof _autoExpandToPath === 'function') {
    try { await _autoExpandToPath(folderPath, true); } catch {}
  }
  if (!options.skipHighlight && typeof highlightOutlinerNode === 'function') {
    try { highlightOutlinerNode(folderPath, { noScroll: true }); } catch {}
  }
  await _viewerFolderNavDelay(50);
}

function _viewerFolderNavDisplayableFromBrowseItems(items) {
  const files = Array.isArray(items) ? items.filter(item => item && item.type !== 'folder') : [];
  const images = files.filter(item => item.type === 'image' || _viewerFolderNavIsDisplayableFile(item.path || item.name || ''))
    .filter(item => _viewerFolderNavExt(item.path || item.name || '') !== '.pdf');
  const pdfs = files.filter(item => _viewerFolderNavExt(item.path || item.name || '') === '.pdf');
  return {
    has: images.length > 0 || pdfs.length > 0,
    hasImage: images.length > 0,
    firstImage: images[0] || null,
    firstPdf: pdfs[0] || null,
  };
}

async function _viewerFolderNavDisplayableInFolder(folderPath) {
  const key = _viewerFolderNavCleanPath(folderPath);
  if (!key) return { has: false, hasImage: false, firstImage: null, firstPdf: null };
  if (_viewerFolderNavDisplayableCache.has(key)) return _viewerFolderNavDisplayableCache.get(key);
  const result = await apiFetch('/browse?path=' + encodeURIComponent(key) + '&all_files=true')
    .then(items => _viewerFolderNavDisplayableFromBrowseItems(items))
    .catch(() => ({ has: false, hasImage: false, firstImage: null, firstPdf: null }));
  _viewerFolderNavDisplayableCache.set(key, result);
  return result;
}

function _viewerFolderNavOpenTarget(folderPath, result, targetIframe = null) {
  const url = result?.hasImage
    ? '/viewer?folder=' + encodeURIComponent(folderPath)
    : (result?.firstPdf?.path ? '/viewer?pdf=' + encodeURIComponent(result.firstPdf.path) : '');
  if (!url) return;
  if (targetIframe) {
    // サブパネルのビューワーからの移動は、そのビューワーだけを切り替える。メインのビューワー・
    // フォルダツリーの選択・プロパティは動かさない（2つ目の表示面がメインを奪わないようにする）。
    const resolvedUrl = window.MeldexResourceUrl?.rewriteInternalUrl?.(url) || url;
    const preparedIframe = typeof _gbPrepareUntrustedIframe === 'function'
      ? _gbPrepareUntrustedIframe(targetIframe, resolvedUrl)
      : targetIframe;
    _gbOpenViewerIframe(preparedIframe || targetIframe, url, resolvedUrl, { skipGlobalUi: true, skipHighlight: true });
    return;
  }
  const targetPath = result?.hasImage ? folderPath : (result?.firstPdf?.path || folderPath);
  if (typeof highlightOutlinerNode === 'function') highlightOutlinerNode(targetPath);
  openViewer(url);
}

async function _navigateViewerFolderByTreeOrder(direction, currentFolderPath, targetIframe = null) {
  await _viewerFolderNavRevealCurrentFolder(currentFolderPath, { skipHighlight: !!targetIframe });
  let cursorPath = currentFolderPath;
  for (let guard = 0; guard < 400; guard++) {
    const nodes = _viewerFolderNavFolderNodes();
    if (!nodes.length) break;
    let cursorIndex = _viewerFolderNavFindIndex(nodes, cursorPath);
    if (cursorIndex < 0) cursorIndex = direction > 0 ? -1 : nodes.length;
    const candidate = nodes[cursorIndex + direction];
    if (!candidate) break;
    await _viewerFolderNavEnsureAncestorsExpanded(candidate);
    const candidatePath = _viewerFolderNavNodePath(candidate);
    if (!candidatePath) {
      cursorPath = '';
      continue;
    }
    const result = await _viewerFolderNavDisplayableInFolder(candidatePath);
    if (result.has) {
      _viewerFolderNavOpenTarget(candidatePath, result, targetIframe);
      return true;
    }
    const expanded = await _viewerFolderNavEnsureNodeExpanded(candidate);
    if (expanded && direction < 0) continue;
    cursorPath = candidatePath;
  }
  return false;
}

function _handleViewerFolderNavRequest(msg, targetIframe = null) {
  const direction = Number(msg?.direction) < 0 ? -1 : 1;
  const currentFolderPath = _viewerFolderNavCurrentFolderFromMessage(msg);
  _navigateViewerFolderByTreeOrder(direction, currentFolderPath, targetIframe).then(moved => {
    if (!moved && typeof showStatus === 'function') {
      showStatus('画像またはPDFがあるフォルダがありません', true);
    }
  }).catch(error => {
    if (typeof showStatus === 'function') showStatus('フォルダ移動に失敗しました: ' + (error?.message || error || ''), true);
  });
}

window.addEventListener('message', (e) => {
  const sourceIframe = _getTrustedEmbeddedMessageIframe(e);
  if (!sourceIframe) return;
  const msg = e.data;
  if (!msg || !msg.type) return;
  // サブパネルのビューワー（2つ目の表示面）は、メインの「現在のファイル」（state.currentPagePath）・
  // フォルダツリーの選択・プロパティを書き換えない。書き換えると、メインで開いているノートのタブ状態や
  // 移動・改名時の追従先がサブパネルの画像へすり替わる。前後のフォルダ移動もそのビューワーの中で行う。
  const fromSubpanelViewer = !!sourceIframe.classList?.contains('gb-subpanel-viewer-frame');
  if (msg.type === 'viewer-current-file-changed') {
    if (!fromSubpanelViewer) _syncViewerCurrentFileFromMessage(msg);
    return;
  }
  if (msg.type === 'viewer-sheet-context-request' && window.MeldexViewerSheetContext) {
    window.MeldexViewerSheetContext.handleRequest(msg, e.source);
    return;
  }
  if (msg.type === 'viewer-sheet-row-nav-request' && window.MeldexViewerSheetContext) {
    window.MeldexViewerSheetContext.handleRowNavigation(msg, e.source);
    return;
  }
  if (msg.type === 'viewer-folder-nav-request') {
    _handleViewerFolderNavRequest(msg, fromSubpanelViewer ? sourceIframe : null);
    return;
  }
  const reloadEmbeddedAnnotations = () => {
    const annotationView = (typeof _getAnnotationViewName === 'function') ? _getAnnotationViewName() : state.view;
    if (typeof _usesEmbeddedAnnotationSurface === 'function' && _usesEmbeddedAnnotationSurface(annotationView) && typeof _loadAnnotationsToIframe === 'function') {
      _loadAnnotationsToIframe();
    }
  };
  // HTMLビューワーiframeからのステータス通知
  if (msg.type === 'board-status') { showStatus(msg.message, msg.isError); }
  // ヒストリー更新通知
  if (msg.type === 'history-update') { renderHistoryList(); }
  // HTMLビューワーiframe内メモからの保存依頼
  if (msg.type === 'ann-save-stroke') {
    apiPost('/annotations', {
      target_path: msg.targetPath || ann.targetPath, type: msg.annType,
      data: msg.data, color: msg.color, opacity: msg.opacity, user: getUsername(),
    }).then(res => {
      if (res?.id && typeof _pushAnnotationCreateHistory === 'function') {
        _pushAnnotationCreateHistory(res.id, 'アノテート: 描画追加', msg.targetPath || ann.targetPath).catch(() => {});
      }
      if (typeof _dispatchEmbeddedAnnotationMessage === 'function') _dispatchEmbeddedAnnotationMessage({ type: 'ann-stroke-saved', annId: res.id, annClientId: msg.annClientId });
    }).catch((err) => {
      if (typeof _dispatchEmbeddedAnnotationMessage === 'function') {
        _dispatchEmbeddedAnnotationMessage({ type: 'ann-stroke-save-failed', annClientId: msg.annClientId });
      }
      if (typeof showStatus === 'function') showStatus('アノテートの保存に失敗しました: ' + (err?.message || err || ''), true);
    });
  }
  if (msg.type === 'ann-delete') {
    if (msg.annId) {
      (async () => {
        const before = typeof _fetchAnnotationHistoryRow === 'function'
          ? await _fetchAnnotationHistoryRow(msg.annId).catch(() => null)
          : null;
        await apiDelete('/annotations/' + encodeURIComponent(msg.annId));
        if (typeof _pushAnnotationHistory === 'function') _pushAnnotationHistory('アノテート: 削除', before, null, msg.annId);
        reloadEmbeddedAnnotations();
      })().catch(() => {});
    }
  }
  if (msg.type === 'ann-delete-note') {
    if (msg.annId && msg.data) {
      if (typeof _putAnnotationWithHistory === 'function') {
        _putAnnotationWithHistory(msg.annId, { data: msg.data }, 'アノテート: 削除', msg.annId)
          .then(reloadEmbeddedAnnotations)
          .catch(() => {});
      } else {
        apiPut('/annotations/' + encodeURIComponent(msg.annId), { data: msg.data }).then(reloadEmbeddedAnnotations).catch(() => {});
      }
    }
  }
  if (msg.type === 'ann-update-note') {
    if (msg.annId && (msg.data || msg.color)) {
      const body = msg.color ? { color: msg.color } : { data: msg.data };
      const label = msg.color ? 'アノテート: 色変更' : 'アノテート: 付箋更新';
      if (typeof _putAnnotationWithHistory === 'function') {
        _putAnnotationWithHistory(msg.annId, body, label, msg.annId).catch(() => {});
      } else {
        apiPut('/annotations/' + encodeURIComponent(msg.annId), body).catch(() => {});
      }
    }
  }
  if (msg.type === 'ann-create-note') {
    const annotationView = (typeof _getAnnotationViewName === 'function') ? _getAnnotationViewName() : state.view;
    const embedded = typeof _usesEmbeddedAnnotationSurface === 'function' && _usesEmbeddedAnnotationSurface(annotationView);
    if (!embedded && !msg.targetPath && typeof createNote === 'function') {
      const prevColor = ann.color;
      const prevOpacity = ann.opacity;
      if (msg.color) ann.color = msg.color;
      ann.opacity = 1;
      Promise.resolve(createNote(msg.x, msg.y, 'sticky')).finally(() => {
        ann.color = prevColor;
        ann.opacity = prevOpacity;
      });
      return;
    }
    const annClientId = msg.annClientId || ('pending-note-' + Date.now().toString(36));
    const noteData = { x: msg.x, y: msg.y, width: 180, height: 100, text: '', html: '', user: getUsername() };
    if (embedded && typeof _dispatchEmbeddedAnnotationMessage === 'function') {
      _dispatchEmbeddedAnnotationMessage({
        type: 'ann-add-note',
        item: {
          id: annClientId,
          type: 'comment',
          shape: 'sticky',
          data: noteData,
          color: msg.color || ann.color,
          opacity: 1,
          user: getUsername(),
          created: new Date().toISOString(),
        },
      });
    }
    apiPost('/annotations', {
      target_path: msg.targetPath || ann.targetPath,
      type: 'comment', shape: 'sticky',
      data: noteData, color: msg.color || ann.color, opacity: 1, user: getUsername(),
    }).then(res => {
      if (res?.id && typeof _pushAnnotationCreateHistory === 'function') {
        _pushAnnotationCreateHistory(res.id, 'アノテート: 付箋追加', msg.targetPath || ann.targetPath).catch(() => {});
      }
      if (embedded) reloadEmbeddedAnnotations();
      else renderNote(res.id, 'sticky', noteData, msg.color || ann.color, 1, getUsername(), res.created);
    }).catch(() => {
      if (embedded && typeof _dispatchEmbeddedAnnotationMessage === 'function') {
        _dispatchEmbeddedAnnotationMessage({ type: 'ann-remove-note', annId: annClientId });
      }
    });
  }
});

// Phase C: bdToMd/bdSave等のスタブは廃止 → gb-canvas-engine.js + gb-canvas-features.js に実装済み

function bdOpenBgPalette(event) {
  if (typeof openColorPalette !== 'function') return;
  const swatch = document.getElementById('bd-bg-swatch');
  const canvas = document.getElementById('bd-canvas');
  if (!swatch || !canvas) return;
  openColorPalette(swatch, (typeof bd !== 'undefined' && bd._bgColor) || '', function(v) {
    canvas.style.background = v;
    setColorSwatchValue(swatch, v);
    if (typeof bd !== 'undefined') bd._bgColor = v || '';
    if (typeof bdMarkExtrasDirty === 'function') {
      bdMarkExtrasDirty({ minimap: true, boardUi: true }, 'bg-palette');
      if (typeof bdScheduleBoardUpdates === 'function') bdScheduleBoardUpdates();
    }
  });
}

async function openBoard(label, path, opts) {
  const openOpts = opts || {};
  let navPushedBeforeLoad = false;
  let mountedBoardLoad = null;
  let requestedPane = null;
  let requestedPaneId = null;
  let requestedTab = null;
  let requestedTabIndex = -1;
  let requestedTabSnapshot = null;
  const showOpenLoading = !openOpts.silent
    && !openOpts.skipGlobalUi
    && typeof showLoading === 'function'
    && typeof hideLoading === 'function';
  const prevView = state.view;
  const prevBoardPath = state.currentBoardPath;
  const currentTitleEl = document.getElementById('current-title');
  const prevTitle = currentTitleEl ? currentTitleEl.textContent : '';
  const restorePreviousView = () => {
    if (navPushedBeforeLoad && requestedPane && requestedTab && requestedTabSnapshot) {
      Object.assign(requestedTab, requestedTabSnapshot.fields);
      requestedTab.navHistory = requestedTabSnapshot.navHistory;
      requestedTab.navIndex = requestedTabSnapshot.navIndex;
      requestedPane.activeTabIndex = requestedTabIndex;
      if (typeof GBLayout !== 'undefined' && typeof GBLayout.render === 'function') GBLayout.render();
      if (typeof GBLayout !== 'undefined' && typeof GBLayout.saveLayout === 'function') GBLayout.saveLayout({ immediate: true });
    }
    state.currentBoardPath = prevBoardPath || null;
    if (currentTitleEl && !openOpts.skipGlobalUi) currentTitleEl.textContent = prevTitle;
    if (!openOpts.skipShowView && prevView && prevView !== 'board') showView(prevView);
    else if (!openOpts.skipStateView) state.view = prevView || '';
  };
  const loading = showOpenLoading ? showLoading('ボードを読み込み中...', { key: 'board:' + path }) : null;
  try {
    if (!openOpts.skipStateView) state.view = 'board';
    state.currentBoardPath = path;
    if (!openOpts.skipHistoryScope && typeof historySetScope === 'function') historySetScope('');
    // ペインブリッジでは board はコンポーネント型なので、showView('board') 自体は
    // DOMをマウントしない。ノート等の別型タブから開く場合は先にnavPushして
    // CanvasComponentを作り、そのコンポーネントが開始した読込を待つ。
    const boardCanvas = typeof bdGetBoardElement === 'function' ? bdGetBoardElement('canvas') : document.getElementById('bd-canvas');
    if (!boardCanvas
      && !openOpts.skipNavPush
      && typeof navPush === 'function'
      && typeof GBPaneBridge !== 'undefined'
      && GBPaneBridge?.initialized) {
      requestedPaneId = openOpts.paneId || (typeof GBLayout !== 'undefined' ? GBLayout.activePane : null);
      const paneInfo = requestedPaneId
        && typeof GBLayout !== 'undefined'
        && typeof GBLayout.findNode === 'function'
        ? GBLayout.findNode(GBLayout.root, requestedPaneId)
        : null;
      requestedPane = paneInfo?.node || null;
      requestedTabIndex = requestedPane?.activeTabIndex ?? -1;
      requestedTab = requestedPane?.tabs?.[requestedTabIndex] || null;
      if (requestedTab) {
        requestedTabSnapshot = {
          fields: {
            type: requestedTab.type,
            label: requestedTab.label,
            path: requestedTab.path,
            state: requestedTab.state,
            icon: requestedTab.icon,
          },
          navHistory: Array.isArray(requestedTab.navHistory) ? [...requestedTab.navHistory] : requestedTab.navHistory,
          navIndex: requestedTab.navIndex,
        };
      }
      await navPush({ type: 'board', label, path }, requestedPaneId);
      navPushedBeforeLoad = true;
      if (requestedPane && typeof getComponentInstance === 'function') {
        const tab = requestedPane.tabs?.[requestedPane.activeTabIndex] || null;
        const component = tab ? getComponentInstance(tab.id) : null;
        mountedBoardLoad = component?._boardLoadPending || null;
      }
    }
    if (!openOpts.skipShowView) showView('board');
    if (currentTitleEl && !openOpts.skipGlobalUi) currentTitleEl.textContent = label;
    const opened = mountedBoardLoad
      ? await mountedBoardLoad
      : (typeof bdOpenBoard === 'function' ? await bdOpenBoard(label, path, { ...openOpts, loading }) : true);
    if (opened === false) {
      restorePreviousView();
      return false;
    }
    if (!openOpts.skipSaveLastView) saveLastView({type:'board', label, path});
    if (!openOpts.skipNavPush && !navPushedBeforeLoad) {
      const _navEntry = {type:'board', label, path};
      navPush(_navEntry);
    }
    if (!openOpts.skipRecent) addRecent(label, path, 'board');
    if (!openOpts.skipHighlight) highlightOutlinerNode(path);
    if (!openOpts.skipAutoVersion) startAutoVersion(path, 'file');
    return true;
  } catch (err) {
    restorePreviousView();
    showStatus('ボード読み込みエラー: ' + (err.message || err), true);
    return false;
  } finally {
    if (showOpenLoading) {
      hideLoading(loading);
    }
  }
}

function openMedia(label, path, type, opts) {
  const openOpts = opts || {};
  // 画像/PDF/動画はビューワー（html-view の #html-iframe）で表示するため、media-view を
  // 経由する showView('media') は行わない（openViewer 側の showView('html') に一本化）。
  // media-view を一瞬マウントすると html-view が退避（DOM移動）され、iframe が強制
  // 再読み込みされて開き直しの高速パスが成立しなくなる（v0.7.139検証で実測）。
  const viewerRouted = (type === 'image' || type === 'pdf' || type === 'video');
  if (!openOpts.skipShowView) { if (!viewerRouted) showView('media'); }
  else if (!openOpts.skipStateView) state.view = 'media';
  const mediaTitleEl = document.getElementById('media-title');
  if (mediaTitleEl) mediaTitleEl.textContent = label;
  const currentTitleEl = document.getElementById('current-title');
  if (currentTitleEl && !openOpts.skipGlobalUi) currentTitleEl.textContent = label;
  if (!openOpts.skipSaveLastView) saveLastView({type:'media', label, path, mediaType: type});
  if (!openOpts.skipNavPush) {
    const _navEntry = {type:'media', label, path, mediaType: type, viewerUrl: openOpts.viewerUrl || ''};
    navPush(_navEntry);
  }
  if (!openOpts.skipRecent) addRecent(label, path, 'media');
  if (!openOpts.skipHighlight) highlightOutlinerNode(path);
  // 詳細パネルにファイル情報を表示
  if (!openOpts.skipGlobalUi && typeof _showFileInfoInDetailPanel === 'function') _showFileInfoInDetailPanel(path);
  // ビューワーペインを更新
  state.currentPagePath = path;
  const container = document.getElementById('media-content');
  const url = openOpts.rawUrl || (API_BASE + '/file-raw?path=' + encodeURIComponent(path));
  if (type === 'image') {
    openViewer(openOpts.viewerUrl || openOpts.rawUrl || ('/viewer?file=' + encodeURIComponent(path)), openOpts);
    return;
  } else if (type === 'pdf') {
    openViewer('/viewer?pdf=' + encodeURIComponent(path), openOpts);
    return;
  } else if (type === 'video') {
    // 動画も画像・PDFと同じくビューワー（viewer.html／#html-iframe）側へ統一する。
    // ビューワー側の動画対応は並行して実装中で、ここではルーティングのみ行う
    // （旧・#media-content への直接注入は廃止。共有コンテナのタブ間混入対策も
    // ビューワー経由に一本化することで簡素化される）。
    openViewer(openOpts.viewerUrl || openOpts.rawUrl || ('/viewer?file=' + encodeURIComponent(path)), openOpts);
    return;
  } else if (!container) {
    return;
  } else if (type === 'audio') {
    container.innerHTML = '<div style="text-align:center;padding:40px;">' + lucide('audio',48) + '<br><audio src="' + esc(url) + '" controls style="margin-top:16px;width:400px;">音声を再生できません</audio></div>';
    // タブ復帰時、共有コンテナ（media-content）の実内容が対象タブと一致しているか
    // 検証するための署名（gb-pane-bridge.part02.part01.js の _gbMediaTabExpectedSignature /
    // _gbVerifyAndFixMediaContainer 参照）。
    container.dataset.gbMediaPath = path;
    container.dataset.gbMediaKind = 'audio';
  } else {
    container.innerHTML = '<div class="gb-empty-state"><div class="gb-empty-message">このメディア形式は表示できません</div><div class="gb-empty-hint">' + esc(label || path || '') + '</div></div>';
    delete container.dataset.gbMediaPath;
    delete container.dataset.gbMediaKind;
    if (!openOpts.skipGlobalUi) showStatus('このメディア形式は表示できません: ' + (label || type || path), true);
    return;
  }
  if (!openOpts.skipGlobalUi) showStatus(type + ': ' + label);
}

function openCalendarFile(label, path, opts) {
  const openOpts = opts || {};
  const paneContext = openOpts.paneContext || openOpts.paneCtx || null;
  if (paneContext?.embedded || openOpts.skipViewPersistence) {
    return selectDatabase(path, paneContext, { ...openOpts, requestedViewMode: 'timeline' });
  }
  // カレンダーDBをタイムラインビュー（カレンダーモード）で開く
  const cfg = getDbViewConfig(path);
  const view = typeof _getCurrentDbViewConfigEntryFromConfig === 'function'
    ? _getCurrentDbViewConfigEntryFromConfig(cfg)
    : null;
  if (view) {
    if (typeof _ensureDbViewTypeSpecific === 'function') _ensureDbViewTypeSpecific(view, cfg);
    view.viewMode = 'timeline';
    cfg.currentViewIdx = Math.max(0, cfg.currentViewIdx || 0);
    saveDbViewConfig(path, cfg, { skipHistory: true });
  }
  return selectDatabase(path, paneContext, openOpts);
}

const _GB_UNTRUSTED_IFRAME_SANDBOX = 'allow-scripts allow-forms allow-popups allow-downloads';
const _GB_EXTERNAL_HTML_IFRAME_SANDBOX = _GB_UNTRUSTED_IFRAME_SANDBOX + ' allow-same-origin';
const _GB_TRUSTED_VIEWER_IFRAME_SANDBOX = _GB_UNTRUSTED_IFRAME_SANDBOX + ' allow-same-origin';

function _gbIsTrustedInternalViewerUrl(rawUrl) {
  const text = String(rawUrl || '').trim();
  if (!text) return false;
  try {
    const parsed = new URL(text, window.location.origin);
    const pathname = parsed.pathname.replace(/\/+$/, '').toLowerCase();
    return parsed.origin === window.location.origin && /\/viewer(?:\.html)?$/.test(pathname);
  } catch {
    return false;
  }
}

function _gbHtmlIframeSandboxForUrl(rawUrl) {
  const text = String(rawUrl || '').trim();
  if (!text) return _GB_UNTRUSTED_IFRAME_SANDBOX;
  try {
    const parsed = new URL(text, window.location.origin);
    if (_gbIsTrustedInternalViewerUrl(parsed.href)) {
      return _GB_TRUSTED_VIEWER_IFRAME_SANDBOX;
    }
    if (['http:', 'https:'].includes(parsed.protocol) && parsed.origin !== window.location.origin) {
      return _GB_EXTERNAL_HTML_IFRAME_SANDBOX;
    }
  } catch {}
  return _GB_UNTRUSTED_IFRAME_SANDBOX;
}

function _gbPrepareUntrustedIframe(iframe, rawUrl) {
  if (!iframe) return null;
  iframe.setAttribute('sandbox', _gbHtmlIframeSandboxForUrl(rawUrl || iframe.getAttribute('src') || iframe.src || ''));
  iframe.setAttribute('referrerpolicy', 'no-referrer');
  return iframe;
}

function _gbNormalizeHtmlViewerUrl(rawUrl) {
  const text = String(rawUrl || '').trim();
  if (!text) return '';
  try {
    const parsed = new URL(text, window.location.origin);
    if (!['http:', 'https:'].includes(parsed.protocol)) return '';
    return parsed.href;
  } catch {
    return '';
  }
}

function _gbSetHtmlViewerSrc(rawUrl, iframeEl, options) {
  const url = _gbNormalizeHtmlViewerUrl(rawUrl);
  if (!url) {
    if (typeof showStatus === 'function') showStatus('HTMLビューワーで開けないURLです', true);
    return false;
  }
  const iframe = _gbPrepareUntrustedIframe(iframeEl || document.getElementById('html-iframe'), url);
  if (iframe) iframe.src = url;
  const urlBar = options?.skipUrlBar ? null : document.getElementById('html-url-bar');
  if (urlBar) urlBar.value = url;
  return true;
}

_gbPrepareUntrustedIframe(document.getElementById('html-iframe'));

function openHtmlFile(label, path, opts) {
  const openOpts = opts || {};
  if (!openOpts.skipShowView) showView('html');
  else if (!openOpts.skipStateView) state.view = 'html';
  if (!openOpts.skipGlobalState) state.currentPagePath = path;
  const currentTitleEl = document.getElementById('current-title');
  if (currentTitleEl && !openOpts.skipGlobalUi) currentTitleEl.textContent = label;
  if (!openOpts.skipSaveLastView) saveLastView({type:'html', label, path});
  if (!openOpts.skipNavPush) {
    const _navEntry = {type:'html', label, path};
    navPush(_navEntry);
  }
  if (!openOpts.skipRecent) addRecent(label, path, 'html');
  if (!openOpts.skipHighlight) highlightOutlinerNode(path);
  const url = API_BASE + '/file-raw?path=' + encodeURIComponent(path);
  const iframe = openOpts.iframeEl || document.getElementById('html-iframe');
  if (typeof trackIframeLoading === 'function') {
    trackIframeLoading(iframe, 'HTMLを読み込み中...', openOpts);
  }
  _gbSetHtmlViewerSrc(url, iframe, { skipUrlBar: !!openOpts.iframeEl });
  if (!openOpts.skipGlobalUi) showStatus('HTML: ' + label);
}
/* LUCIDE, lucide(), fileTypeIcon() は meldex-core.js で定義済み */
function getUsername() {
  try { const cfg = JSON.parse(localStorage.getItem('meldex-user') || '{}'); return cfg.name || 'anonymous'; } catch { return 'anonymous'; }
}

// ビュー切り替え時のアノテーション再読み込みは showView 本体 (720-731行) で処理済み

// replaceIcons() は meldex-core.js で定義済み（DOMContentLoaded内で呼び出し）

// ダイアログのリサイズは gb-modal-shell.js の1系統に統合した（2026-08-07）。
// 以前はここにも独自のリサイズ機構があり、表示サイズ（拡大率）を考慮しない座標計算と
// max-width/max-height の上書きで、共通側と互いに打ち消し合っていた。
/* ==============================
   起動
   ============================== */
replaceIcons();
loadColorSettings();
updateColorScheme();
updateUserIcon();
// UIスケール復元
// ページ離脱時の未保存データ保護
function _sendUnloadJson(url, method, body) {
  let requestMethod = method || 'POST';
  let requestBody = body || {};
  if (requestMethod === 'PUT' && String(url || '').includes('/value?')) {
    requestMethod = 'POST';
    requestBody = { ...requestBody, _unload_update: true };
  }
  const payload = JSON.stringify(requestBody);
  const blob = new Blob([payload], { type: 'application/json' });
  if (requestMethod === 'POST' && navigator.sendBeacon) {
    try {
      if (navigator.sendBeacon(url, blob)) return true;
    } catch {}
  }
  try {
    fetch(url, {
      method: requestMethod,
      headers: { 'Content-Type': 'application/json' },
      body: payload,
      keepalive: true,
    }).catch(() => {});
    return payload.length <= 60000;
  } catch {}
  return false;
}

window.addEventListener('beforeunload', (e) => {
  let unloadSaveQueued = true;
  // ノート: 未保存の自動保存タイマーが残っている場合、即座に保存
  if (window._noteAutoSaveTimer) {
    clearTimeout(window._noteAutoSaveTimer);
    window._noteAutoSaveTimer = null;
    const pc = document.getElementById('page-content');
    const currentPath = pc?.dataset?.path;
    if (currentPath) {
      const md = htmlToMd(pc?.innerHTML || '');
      const fm = pc.dataset.frontmatter || '';
      const full = fm ? fm + md : md;
      const body = typeof _noteSavePayload === 'function'
        ? _noteSavePayload(pc, full)
        : { content: full, if_match_etag: pc?.dataset?.lastSavedEtag || '', skip_if_missing: true };
      const noteSaveQueued = _sendUnloadJson(API_BASE + '/file?path=' + encodeURIComponent(currentPath), 'POST', body);
      unloadSaveQueued = noteSaveQueued && unloadSaveQueued;
      if (!noteSaveQueued) {
        window._noteAutoSaveTimer = setTimeout(() => {
          if (typeof flushPendingEditorAutosave === 'function') flushPendingEditorAutosave();
        }, 500);
      }
    }
  }
  // entity-freetext: 未保存タイマーが残っている場合
  if (window._ftAutoSaveTimer) {
    clearTimeout(window._ftAutoSaveTimer);
    const ft = document.getElementById('entity-freetext');
    const ep = ft?.dataset?.entityPath;
    if (ep) {
      const md = htmlToMd(ft?.innerHTML || '');
      const isEntry = ep.endsWith('.md');
      const url = isEntry
        ? API_BASE + '/value?path=' + encodeURIComponent(ep)
        : API_BASE + '/file?path=' + encodeURIComponent(ep + '/_freetext.md');
      const body = isEntry ? { new_body: md, skip_if_missing: true } : { content: md, skip_if_missing: true };
      unloadSaveQueued = _sendUnloadJson(url, isEntry ? 'PUT' : 'POST', body) && unloadSaveQueued;
    }
  }
  // キャンバス: 未保存タイマーが残っている場合
  if (window._bdTimer && typeof bd !== 'undefined' && bd.dirty && bd.path && typeof bdToMd === 'function') {
    const canSaveBoardPath = typeof _bdCanSaveCurrentBoardPath !== 'function' || _bdCanSaveCurrentBoardPath(bd.path);
    if (!canSaveBoardPath) {
      unloadSaveQueued = false;
    } else {
      clearTimeout(window._bdTimer);
      const boardSaveQueued = _sendUnloadJson(API_BASE + '/file?path=' + encodeURIComponent(bd.path), 'POST', { content: bdToMd(), skip_if_missing: true });
      unloadSaveQueued = boardSaveQueued && unloadSaveQueued;
      if (!boardSaveQueued) window._bdTimer = setTimeout(bdSave, 500);
    }
  }
  if (!unloadSaveQueued) {
    e.preventDefault();
    e.returnValue = '';
  }
});

// ノート縦書き復元
// 復元も切替も MeldexNoteWritingMode.applyState() へ集約する（組方向へ追従するUIの配線が
// 1箇所に集まるため、目次レイアウトやセパレータのARIAが復元時だけ取り残されない）。
// 上の replaceIcons() は既に実行済みなので、ボタンのアイコンは applyState() が lucide() で埋め直す。
if (typeof MeldexNoteWritingMode !== 'undefined') MeldexNoteWritingMode.restoreFromStorage();
// ノート余白復元
if (typeof applyNoteMargin === 'function') applyNoteMargin();
if (typeof applyNoteContentMaxWidth === 'function') applyNoteContentMaxWidth();
// UIスケール復元
document.documentElement.style.fontSize = ''; // 旧font-sizeスケーリングをクリア
// 表示サイズの決め方（初回の自動判定・手動値の保全・過去の自動値の付け直し）は
// gb-ui-scale.js が一手に引き受ける。ここでは決まった値を適用するだけにする。
applyUIScale(window.MeldexUIScale
  ? window.MeldexUIScale.resolveStartupScale()
  : (parseInt(localStorage.getItem('ui-scale'), 10) || 100));

// ステータスバー表示状態復元
try {
  if (typeof applyStatusbarHidden === 'function') {
    applyStatusbarHidden(localStorage.getItem('meldex-statusbar-hidden') === '1');
  }
} catch (e) { console.warn('ステータスバー状態復元失敗:', e); }

// Ctrl+ホイールでUIスケール変更（pywebviewではブラウザネイティブzoomが無効のため自前実装）
document.addEventListener('wheel', (e) => {
  if (!e.ctrlKey) return;
  // キャンバス・フォルダビュー等の独自ズームが処理する場合はスキップ
  const canvas = document.getElementById('bd-canvas');
  if (canvas && canvas.contains(e.target)) return;
  const folderGrid = document.getElementById('folder-grid');
  if (folderGrid && folderGrid.contains(e.target)) return;
  e.preventDefault();
  const steps = [67, 75, 80, 90, 100, 110, 125, 150, 175, 200];
  const cur = parseInt(localStorage.getItem('ui-scale') || '100', 10);
  const idx = steps.indexOf(cur);
  let newIdx;
  if (idx === -1) {
    // 現在値がステップ外の場合、最も近いステップを探す
    newIdx = steps.reduce((best, v, i) => Math.abs(v - cur) < Math.abs(steps[best] - cur) ? i : best, 0);
  } else {
    newIdx = e.deltaY < 0 ? Math.min(idx + 1, steps.length - 1) : Math.max(idx - 1, 0);
  }
  if (steps[newIdx] !== cur) {
    // Ctrl+ホイールは常にユーザー自身の操作なので「手動」として記録する
    const applied = applyUIScale(steps[newIdx], { source: 'manual' });
    if (applied !== cur) showStatus('表示サイズ: ' + applied + '%');
  }
}, { passive: false });

// モバイルツールメニュー（トップバー折りたたみ時）
function showMobileToolMenu(e) {
  document.querySelectorAll('.mobile-tool-menu').forEach(el => el.remove());
  const btn = e.target.closest('button') || e.target;
  const items = [
    { label: 'フォルダ', action: () => openToolTab('folder') },
    { label: 'ノート', action: () => openToolTab('page') },
    { label: 'シート', action: () => openToolTab('database') },
    { label: 'ボード', action: () => openToolTab('board') },
    null,
    { label: 'ビューワー', action: () => toggleRightPanelTab('preview') },
    { label: 'オプション', action: () => toggleOptionPanel() },
    null,
    { label: 'アノテートツール', action: () => toggleAnnotationToolbar() },
    { label: 'オーバーレイ', action: () => toggleOverlayVisibility() },
  ];
  const menu = document.createElement('div');
  menu.className = 'gb-context-menu mobile-tool-menu';
  menu.setAttribute('role', 'menu');
  menu.setAttribute('aria-label', 'ツールメニュー');
  menu.style.cssText = 'position:fixed;z-index:999;max-height:80vh;overflow-y:auto;';
  let menuClosed = false;
  let closeOnPointer = null;
  let closeOnKey = null;
  function closeMenu(restoreFocus = false) {
    if (menuClosed) return;
    menuClosed = true;
    document.removeEventListener('pointerdown', closeOnPointer, true);
    document.removeEventListener('keydown', closeOnKey, true);
    menu.remove();
    if (restoreFocus && typeof btn.focus === 'function') {
      try { btn.focus({ preventScroll: true }); } catch { btn.focus(); }
    }
  }
  function focusableItems() {
    return [...menu.querySelectorAll('.gb-context-menu-item')];
  }
  items.forEach(it => {
    if (!it) { const sep = document.createElement('div'); sep.className = 'gb-context-menu-sep'; sep.setAttribute('role', 'separator'); menu.appendChild(sep); return; }
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'gb-context-menu-item';
    row.setAttribute('role', 'menuitem');
    row.textContent = it.label;
    row.addEventListener('click', () => { closeMenu(false); try { it.action(); } catch {} });
    menu.appendChild(row);
  });
  document.body.appendChild(menu);
  const br = btn.getBoundingClientRect();
  if (typeof positionPopup === 'function') {
    positionPopup(menu, br, { prefer: 'bottom', gap: 2 });
  } else {
    { const z = _getZoom(); menu.style.left = Math.max(4, Math.min(br.left / z, window.innerWidth / z - menu.offsetWidth - 4)) + 'px'; menu.style.top = (br.bottom / z + 2) + 'px'; }
    if (typeof clampPopupToViewport === 'function') clampPopupToViewport(menu);
  }
  closeOnPointer = function closeMobileToolMenuOnPointer(ev) {
    if (!menu.contains(ev.target)) closeMenu(false);
  };
  closeOnKey = function closeMobileToolMenuOnKey(ev) {
    if (ev.key === 'Escape') {
      ev.preventDefault();
      closeMenu(true);
      return;
    }
    const rows = focusableItems();
    if (!rows.length) return;
    const currentIndex = Math.max(0, rows.indexOf(document.activeElement));
    let nextIndex = currentIndex;
    if (ev.key === 'ArrowDown') nextIndex = (currentIndex + 1) % rows.length;
    else if (ev.key === 'ArrowUp') nextIndex = (currentIndex - 1 + rows.length) % rows.length;
    else if (ev.key === 'Home') nextIndex = 0;
    else if (ev.key === 'End') nextIndex = rows.length - 1;
    else return;
    ev.preventDefault();
    rows[nextIndex]?.focus();
  };
  setTimeout(() => {
    if (menuClosed || !menu.isConnected) return;
    document.addEventListener('pointerdown', closeOnPointer, true);
    document.addEventListener('keydown', closeOnKey, true);
  }, 0);
  menu.querySelector('.gb-context-menu-item')?.focus();
}

