    const top = Number.isFinite(rect.top) ? Math.max(0, rect.top) : 0;
    const zoom = Math.max(0.1, parseFloat(document.documentElement.style.zoom || '1') || 1);
    const availableHeight = Math.max(160, window.innerHeight - top - 12);
