  'calendar.dragMove':     { key: '', display: '予定のドラッグ',          label: '予定を移動',                      scope: 'calendar', readonly: true },
  'calendar.dragResize':   { key: '', display: '端のドラッグ',            label: '予定の長さを変える',              scope: 'calendar', readonly: true },

