function _updateAllTooltips() {
  const shortcuts = _getEffectiveShortcuts();

  // ID指定のツールチップ
  for (const [elemId, tip] of Object.entries(GB_TOOLTIPS)) {
    const el = document.getElementById(elemId);
    if (!el) continue;
    let text = tip.title || tip.label;
    if (!tip.title && tip.desc) text += ' — ' + tip.desc;
    if (tip.shortcutId && shortcuts[tip.shortcutId]?.key) {
      text += ' (' + _formatKeyDisplay(shortcuts[tip.shortcutId].key) + ')';
    }
    el.title = text;
  }

  // data-shortcut-id 属性を持つ要素（動的生成ボタン用）
  document.querySelectorAll('[data-shortcut-id]').forEach(el => {
    const id = el.dataset.shortcutId;
    const def = shortcuts[id];
    if (def) {
      const base = (el.title || el.textContent.trim()).replace(/\s*\([^)]*\)\s*$/, '');
      el.title = def.key ? base + ' (' + _formatKeyDisplay(def.key) + ')' : base;
    }
  });
}


// === Part 2-2: ショートカット設定タブ ===

// 一覧の描画・キー変更・競合チェックは gb-shortcut-registry.js に一本化した
// （設定ダイアログとオプションパネルのショートカットタブで同じ実装を使うため）。
// ここは設定ダイアログ側の入口だけを残す。
function renderShortcutSettings(container) {
  // 設定ダイアログでは従来どおり枠付き・全スコープ表示
  window.MeldexShortcutRegistry?.renderSettings(container, { boxed: true });
}

function _applyShortcutSettingsFilter(container) {
  window.MeldexShortcutRegistry?.applyFilter(container);
}

function _checkKeyConflict(selfId, newKey) {
  return window.MeldexShortcutRegistry?.conflict(selfId, newKey) ?? null;
}


// === 初期化 ===

document.addEventListener('DOMContentLoaded', _updateAllTooltips);

;

/* === gb-db-column-filter.js === */
;
/* シート列ヘッダーの値フィルター
   条件フィルターとは独立して保存し、行表示時には両方を AND で適用する。 */

const DB_COLUMN_FILTER_BLANK = '\u0000meldex:blank';

function _dbColumnValueFiltersObject(dbPath, ctx) {
  if (typeof getColumnValueFilters === 'function') {
    const saved = getColumnValueFilters(dbPath, { ctx });
    return saved && typeof saved === 'object' && !Array.isArray(saved) ? saved : {};
  }
  const view = typeof getCurrentDbViewConfigEntry === 'function'
    ? getCurrentDbViewConfigEntry(dbPath, { ctx })
    : null;
  return view?.columnValueFilters && typeof view.columnValueFilters === 'object'
    ? view.columnValueFilters
    : {};
}

function _dbColumnFilterEntry(dbPath, propName, ctx) {
  const entry = _dbColumnValueFiltersObject(dbPath, ctx)?.[propName];
  return entry && Array.isArray(entry.selected) ? entry : null;
}

function isDbColumnValueFilterActive(dbPath, propName, ctx) {
  return !!_dbColumnFilterEntry(dbPath, propName, ctx);
}

function isDbColumnFilterActive(dbPath, propName, ctx) {
  if (isDbColumnValueFilterActive(dbPath, propName, ctx)) return true;
  const conditions = typeof getAdvancedFilters === 'function'
    ? getAdvancedFilters(dbPath, { ctx })
    : [];
  return conditions.some(filter => filter?.property === propName || filter?.prop === propName);
}

function _dbColumnFilterText(value) {
  if (value === null || value === undefined || value === '') return DB_COLUMN_FILTER_BLANK;
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    const text = String(value);
    return text ? text : DB_COLUMN_FILTER_BLANK;
  }
  if (typeof _dbSearchValueText === 'function') {
    const text = String(_dbSearchValueText(value) || '');
    return text || DB_COLUMN_FILTER_BLANK;
  }
  try {
    const text = JSON.stringify(value);
    return text && text !== '{}' && text !== '[]' ? text : DB_COLUMN_FILTER_BLANK;
  } catch {
    return String(value || '') || DB_COLUMN_FILTER_BLANK;
  }
}

function _dbColumnFilterValuesForEntity(entityName, entityData, propName, dbPath, ctx, filterMode) {
  if (propName === '__entity__') return [_dbColumnFilterText(entityName)];
  const ptc = typeof getPropertyTypes === 'function'
    ? (getPropertyTypes(dbPath, ctx)?.[propName] || null)
    : null;
  const metadataSource = typeof _dbPropertyMetadataSource === 'function'
    ? _dbPropertyMetadataSource(ptc)
    : (['created', 'modified', 'modified_by'].includes(ptc?.source) ? ptc.source : '');
  if (metadataSource) {
    return [_dbColumnFilterText(entityData?.['_' + metadataSource])];
  }
  const raw = Array.isArray(entityData?.[propName]) ? entityData[propName] : [];
  const visible = typeof filterValues === 'function'
    ? filterValues(raw, undefined, filterMode)
    : raw;
  const values = visible.map(item => _dbColumnFilterText(item?.value));
  return values.length ? [...new Set(values)] : [DB_COLUMN_FILTER_BLANK];
}

function _dbEntityPassesColumnValueFilters(entityName, entityData, filters, dbPath, ctx, filterMode) {
  const entries = Object.entries(filters || {}).filter(([, entry]) => Array.isArray(entry?.selected));
  if (!entries.length) return true;
  return entries.every(([propName, entry]) => {
    const selected = new Set(entry.selected.map(value => String(value)));
    const candidates = _dbColumnFilterValuesForEntity(
      entityName,
      entityData || {},
      propName,
      dbPath,
      ctx,
      filterMode,
    );
    return candidates.some(value => selected.has(String(value)));
  });
}

function _dbColumnFilterEntries(dbPath, propName, ctx) {
  const data = ctx?.pivotData
    || (state.currentDbPath === dbPath ? state.pivotData : null)
    || state.pivotData
    || {};
  const counts = new Map();
  const filterMode = ctx?.filter ?? state.filter ?? 'disabled';
  Object.entries(data.entities || {}).forEach(([entityName, entityData]) => {
    _dbColumnFilterValuesForEntity(entityName, entityData, propName, dbPath, ctx, filterMode)
      .forEach(value => counts.set(value, (counts.get(value) || 0) + 1));
  });
  return [...counts.entries()]
    .map(([value, count]) => ({
      value,
      label: value === DB_COLUMN_FILTER_BLANK ? '（空白）' : value,
      count,
    }))
    .sort((a, b) => {
      if (a.value === DB_COLUMN_FILTER_BLANK) return -1;
      if (b.value === DB_COLUMN_FILTER_BLANK) return 1;
      return a.label.localeCompare(b.label, 'ja', { numeric: true, sensitivity: 'base' });
    });
}

function _dbSaveColumnValueFilter(dbPath, propName, selected, allValues, ctx) {
  const filters = { ..._dbColumnValueFiltersObject(dbPath, ctx) };
  const selectedValues = [...new Set((selected || []).map(String))];
  const everyValueSelected = selectedValues.length === allValues.length
    && allValues.every(value => selectedValues.includes(String(value)));
  if (everyValueSelected) delete filters[propName];
  else filters[propName] = { selected: selectedValues };
  if (typeof setColumnValueFilters === 'function') {
    setColumnValueFilters(dbPath, filters, {
      ctx,
      detail: propName,
      label: 'シート表示: 列の値フィルター',
    });
  }
  return filters;
}

function _dbRefreshAfterColumnFilter(dbPath, ctx) {
  if (typeof _updateFilterBadge === 'function') _updateFilterBadge({ dbPath, ctx });
  if (typeof _renderCurrentDbView === 'function') _renderCurrentDbView(ctx, dbPath);
  else if (typeof renderPivot === 'function') renderPivot(ctx);
}

function clearDbColumnValueFilter(dbPath, propName, ctx) {
  const filters = { ..._dbColumnValueFiltersObject(dbPath, ctx) };
  if (!Object.prototype.hasOwnProperty.call(filters, propName)) return;
  delete filters[propName];
  if (typeof setColumnValueFilters === 'function') {
    setColumnValueFilters(dbPath, filters, {
      ctx,
      detail: propName,
      label: 'シート表示: 列の値フィルターを解除',
    });
  }
  _dbRefreshAfterColumnFilter(dbPath, ctx);
}

function clearDbColumnFilter(dbPath, propName, ctx) {
  const valueFilters = { ..._dbColumnValueFiltersObject(dbPath, ctx) };
  const hadValueFilter = Object.prototype.hasOwnProperty.call(valueFilters, propName);
  if (hadValueFilter) {
    delete valueFilters[propName];
    if (typeof setColumnValueFilters === 'function') {
      setColumnValueFilters(dbPath, valueFilters, {
        ctx,
        detail: propName,
        label: 'シート表示: この列のフィルターを解除',
      });
    }
  }
  const advanced = typeof getAdvancedFilters === 'function'
    ? getAdvancedFilters(dbPath, { ctx })
    : [];
  const nextAdvanced = advanced.filter(filter => filter?.property !== propName && filter?.prop !== propName);
  if (nextAdvanced.length !== advanced.length && typeof setAdvancedFilters === 'function') {
    setAdvancedFilters(dbPath, nextAdvanced, {
      ctx,
      detail: propName,
      label: 'シート表示: この列のフィルターを解除',
    });
  }
  if (hadValueFilter || nextAdvanced.length !== advanced.length) {
    _dbRefreshAfterColumnFilter(dbPath, ctx);
  }
}

const DB_COLUMN_FILTER_OPERATOR_LABEL = {
  contains: '含む',
  not_contains: '含まない',
  equals: '一致',
  not_equals: '不一致',
  empty: '空',
  not_empty: '空でない',
};
// 条件フィルタ1件の要約文字列（列ヘッダーのフィルターポップアップに表示する）。
function _dbColumnFilterConditionSummaryText(cond) {
  const fieldLabel = cond?.field === 'status' ? 'ステータス' : '値';
  const opLabel = DB_COLUMN_FILTER_OPERATOR_LABEL[cond?.operator] || cond?.operator || '';
  const hasValue = !['empty', 'not_empty'].includes(cond?.operator);
  const valueText = hasValue && cond?.value !== '' && cond?.value != null ? `「${cond.value}」` : '';
  return `${fieldLabel} ${opLabel}${valueText}`;
}

function _dbCloseColumnFilterPopup() {
  document.querySelectorAll('.db-column-filter-popover').forEach(el => el.remove());
}

function _dbPositionColumnFilterPopup(popover, source) {
  const rect = source?.currentTarget?.getBoundingClientRect?.()
    || source?.target?.getBoundingClientRect?.();
  if (typeof positionPopup === 'function') {
    if (rect) {
      positionPopup(popover, { left: rect.left, right: rect.right, top: rect.bottom, bottom: rect.bottom });
    } else {
      const x = Number(source?.clientX) || Math.max(12, window.innerWidth - 380);
      const y = Number(source?.clientY) || 80;
      positionPopup(popover, { left: x, right: x, top: y, bottom: y });
    }
  } else {
    popover.style.left = Math.max(8, Number(source?.clientX) || 8) + 'px';
    popover.style.top = Math.max(8, Number(source?.clientY) || 8) + 'px';
  }
}

function showDbColumnFilterPopup(source, propName, ctxOverride, dbPathOverride) {
  _dbCloseColumnFilterPopup();
  const ctx = ctxOverride || (typeof _dbPaneContextFromEvent === 'function'
    ? _dbPaneContextFromEvent(source?.target || source?.currentTarget, { dbPath: dbPathOverride || state.currentDbPath })
    : null);
  const dbPath = dbPathOverride || ctx?.dbPath || state.currentDbPath;
  if (!dbPath || !propName) return;

  const entries = _dbColumnFilterEntries(dbPath, propName, ctx);
  const allValues = entries.map(entry => String(entry.value));
  const active = _dbColumnFilterEntry(dbPath, propName, ctx);
  const selected = new Set(active ? active.selected.map(String) : allValues);

  const popover = document.createElement('div');
  popover.className = 'db-column-filter-popover';
  popover.dataset.e2eId = 'db-column-filter-popover';
  popover.dataset.dbPath = dbPath;
  const viewConfig = typeof getDbViewConfig === 'function' ? getDbViewConfig(dbPath) : null;
  const viewIndex = typeof _getCurrentDbViewIndexFromConfig === 'function'
    ? _getCurrentDbViewIndexFromConfig(viewConfig, { ctx })
    : -1;
  popover.dataset.viewIndex = String(viewIndex);
  popover.setAttribute('role', 'dialog');
  popover.setAttribute('aria-label', `${propName === '__entity__' ? 'トピック名' : propName}列のフィルター`);

  const header = document.createElement('div');
  header.className = 'db-column-filter-header';
  const title = document.createElement('strong');
  title.textContent = propName === '__entity__' ? 'トピック名をフィルター' : `${propName}をフィルター`;
  const closeButton = document.createElement('button');
  closeButton.type = 'button';
  closeButton.className = 'db-column-filter-icon-button';
  closeButton.title = '閉じる';
  closeButton.setAttribute('aria-label', '列フィルターを閉じる');
  closeButton.innerHTML = typeof lucide === 'function' ? lucide('x', 14) : '×';
  closeButton.addEventListener('click', _dbCloseColumnFilterPopup);
  header.append(title, closeButton);
  popover.appendChild(header);

  if (propName !== '__entity__') {
    // 既にこの列に条件フィルタ（advancedFilters）があれば要約を表示し、ダイアログへの導線を示す
    // （ツールバーの統合フィルタダイアログと同じ状態を読み書きするため、内容はそこで編集した結果と一致する）。
    const conditions = (typeof getAdvancedFilters === 'function' ? getAdvancedFilters(dbPath, { ctx }) : [])
      .filter(f => f?.property === propName || f?.prop === propName);
    if (conditions.length && typeof _dbColumnFilterConditionSummaryText === 'function') {
      const summary = document.createElement('div');
      summary.className = 'db-column-filter-condition-summary';
      conditions.forEach(cond => {
        const item = document.createElement('span');
        item.className = 'db-column-filter-condition-summary-item';
        item.textContent = '条件: ' + _dbColumnFilterConditionSummaryText(cond);
        summary.appendChild(item);
      });
      popover.appendChild(summary);
    }
    const conditionButton = document.createElement('button');
    conditionButton.type = 'button';
    conditionButton.className = 'db-column-filter-condition';
    conditionButton.innerHTML = (typeof lucide === 'function' ? lucide('slidersHorizontal', 14) : '')
      + (conditions.length ? ' 条件フィルターを編集' : ' 条件フィルターを追加');
    conditionButton.addEventListener('click', () => {
      _dbCloseColumnFilterPopup();
      if (typeof showUnifiedFilterModal === 'function') {
        showUnifiedFilterModal({ ctx, initialProperty: propName });
      }
    });
    popover.appendChild(conditionButton);
  }

  const search = document.createElement('input');
  search.type = 'search';
  search.className = 'db-column-filter-search';
  search.placeholder = '値を検索';
  search.setAttribute('aria-label', '列の値を検索');
  popover.appendChild(search);

  const actions = document.createElement('div');
  actions.className = 'db-column-filter-select-actions';
  const selectAllButton = document.createElement('button');
  selectAllButton.type = 'button';
  selectAllButton.textContent = 'すべて表示';
  const clearAllButton = document.createElement('button');
  clearAllButton.type = 'button';
  clearAllButton.textContent = 'すべてクリア';
  actions.append(selectAllButton, clearAllButton);
  popover.appendChild(actions);

  const list = document.createElement('div');
  list.className = 'db-column-filter-value-list';
  list.setAttribute('role', 'group');
  list.setAttribute('aria-label', '表示する値');
  entries.forEach((entry, index) => {
    const label = document.createElement('label');
    label.className = 'db-column-filter-value';
    label.dataset.searchText = entry.label.toLocaleLowerCase('ja');
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = selected.has(String(entry.value));
    checkbox.value = String(entry.value);
    checkbox.dataset.e2eId = `db-column-filter-value-${index}`;
    const text = document.createElement('span');
    text.className = 'db-column-filter-value-label';
    text.textContent = entry.label;
    const count = document.createElement('span');
    count.className = 'db-column-filter-value-count';
    count.textContent = String(entry.count);
    label.append(checkbox, text, count);
    list.appendChild(label);
  });
  if (!entries.length) {
    const empty = document.createElement('div');
    empty.className = 'db-column-filter-empty';
    empty.textContent = 'この列に値はありません';
    list.appendChild(empty);
  }
  popover.appendChild(list);

  search.addEventListener('input', () => {
    const needle = search.value.trim().toLocaleLowerCase('ja');
    list.querySelectorAll('.db-column-filter-value').forEach(label => {
      label.hidden = !!needle && !String(label.dataset.searchText || '').includes(needle);
    });
  });
  selectAllButton.addEventListener('click', () => {
    list.querySelectorAll('.db-column-filter-value input').forEach(input => { input.checked = true; });
  });
  clearAllButton.addEventListener('click', () => {
    list.querySelectorAll('.db-column-filter-value input').forEach(input => { input.checked = false; });
  });

  const footer = document.createElement('div');
  footer.className = 'db-column-filter-footer';
  const removeButton = document.createElement('button');
  removeButton.type = 'button';
  removeButton.textContent = 'この列を解除';
  removeButton.disabled = !isDbColumnFilterActive(dbPath, propName, ctx);
  removeButton.addEventListener('click', () => {
    _dbCloseColumnFilterPopup();
    clearDbColumnFilter(dbPath, propName, ctx);
  });
  const applyButton = document.createElement('button');
  applyButton.type = 'button';
  applyButton.className = 'primary';
  applyButton.textContent = '適用';
  applyButton.addEventListener('click', () => {
    const picked = [...list.querySelectorAll('input[type="checkbox"]:checked')].map(input => input.value);
    _dbSaveColumnValueFilter(dbPath, propName, picked, allValues, ctx);
    _dbCloseColumnFilterPopup();
    _dbRefreshAfterColumnFilter(dbPath, ctx);
  });
  footer.append(removeButton, applyButton);
  popover.appendChild(footer);

  popover.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      _dbCloseColumnFilterPopup();
    }
  });
  document.body.appendChild(popover);
  _dbPositionColumnFilterPopup(popover, source);
  setTimeout(() => search.focus(), 0);

  setTimeout(() => {
    const closer = event => {
      if (!popover.isConnected) {
        document.removeEventListener('pointerdown', closer);
        return;
      }
      if (!popover.contains(event.target)) {
        _dbCloseColumnFilterPopup();
        document.removeEventListener('pointerdown', closer);
      }
    };
    document.addEventListener('pointerdown', closer);
  }, 0);
}

if (typeof window !== 'undefined') {
  window.showDbColumnFilterPopup = showDbColumnFilterPopup;
  window.clearDbColumnValueFilter = clearDbColumnValueFilter;
  window.clearDbColumnFilter = clearDbColumnFilter;
}

;

/* === gb-db-tree-header.js === */
;
/* ツリービューの列ヘッダー操作。
   列幅、列順、固定状態、共通列メニューを保存済みビュー単位で扱う。 */

function _dbTreeApplyLiveColumnWidth(list, propName, width) {
  const layout = list?._dbTreeLayout;
  if (!layout || !layout.keys.includes(propName)) return;
  layout.widths[propName] = Math.max(60, Math.min(640, Math.round(width)));
  const parts = layout.keys.map(key => `${layout.widths[key]}px`);
  layout.template = [...parts, `${layout.actionWidth}px`].join(' ');
  layout.totalWidth = layout.keys.reduce((sum, key) => sum + layout.widths[key], 0) + layout.actionWidth;
  const header = list.querySelector('.db-tree-header');
  const rows = list.querySelector('.db-tree-rows');
  if (header) {
    header.style.gridTemplateColumns = layout.template;
    header.style.width = `${layout.totalWidth}px`;
  }
  if (rows) rows.style.width = `${layout.totalWidth}px`;
  list.querySelectorAll('.db-tree-row').forEach(row => { row.style.gridTemplateColumns = layout.template; });
  list.querySelectorAll('.db-tree-row-window').forEach(windowHost => {
    windowHost.style.width = `${layout.totalWidth}px`;
  });
  list.querySelectorAll('.db-tree-column-resize-handle').forEach(handle => {
    if (handle.dataset.dbResizeToken === propName) {
      handle.setAttribute('aria-valuenow', String(layout.widths[propName]));
    }
  });
  let stickyLeft = 0;
  (layout.pinnedKeys || []).forEach(key => {
    list.querySelectorAll('.db-tree-header-cell.is-pinned').forEach(cell => {
      if (cell.dataset.dbColToken === key) cell.style.left = `${stickyLeft}px`;
    });
    list.querySelectorAll('[data-db-pinned-token]').forEach(cell => {
      if (cell.dataset.dbPinnedToken === key) cell.style.left = `${stickyLeft}px`;
    });
    stickyLeft += layout.widths[key] || 0;
  });
}

function _dbTreePersistColumnWidth(list, propName, width, ctx, dbPath) {
  const nextWidth = Math.max(60, Math.min(640, Math.round(width)));
  setColWidthPersist(dbPath, propName, nextWidth, {
    ctx,
    label: 'シート表示: 列幅',
    detail: propName,
  });
  _dbTreeApplyLiveColumnWidth(list, propName, nextWidth);
}

function _dbTreeStartColumnResize(event, handle, list, propName, ctx, dbPath) {
  event.preventDefault();
  event.stopPropagation();
  const layout = list?._dbTreeLayout;
  if (!layout) return;
  const startX = event.clientX;
  const startWidth = layout.widths[propName];
  let lastWidth = startWidth;
  handle.classList.add('active');
  try {
    handle.setPointerCapture?.(event.pointerId);
  } catch {
    // Synthetic pointer events used by deterministic E2E do not own a native pointer.
  }
  const onMove = moveEvent => {
    lastWidth = startWidth + moveEvent.clientX - startX;
    _dbTreeApplyLiveColumnWidth(list, propName, lastWidth);
  };
  const onUp = upEvent => {
    document.removeEventListener('pointermove', onMove);
    document.removeEventListener('pointerup', onUp);
    document.removeEventListener('pointercancel', onUp);
    handle.classList.remove('active');
    try {
      handle.releasePointerCapture?.(upEvent?.pointerId ?? event.pointerId);
    } catch {
      // The browser may already have released capture after cancellation.
    }
    _dbTreePersistColumnWidth(list, propName, list._dbTreeLayout.widths[propName], ctx, dbPath);
  };
  document.addEventListener('pointermove', onMove);
  document.addEventListener('pointerup', onUp);
  document.addEventListener('pointercancel', onUp);
}

function _dbTreeReorderColumn(dbPath, ctx, config, properties, fromName, targetName, beforeTarget) {
  const labelKey = config.labelProp || '__entity__';
  if (!fromName || fromName === labelKey || fromName === targetName) return false;
  const hidden = typeof getHiddenCols === 'function' ? getHiddenCols(dbPath, { ctx }) : [];
  const structural = new Set([
    config.parentProp,
    config.orderProp,
    config.collapsedProp,
    '内部ID',
  ].filter(Boolean));
  const oldOrder = typeof getColOrder === 'function' ? (getColOrder(dbPath, { ctx }) || []) : [];
  const extra = [...new Set([...oldOrder, ...properties])]
    .filter(name => name !== labelKey && properties.includes(name) && !hidden.includes(name) && !structural.has(name));
  const nextExtra = extra.filter(name => name !== fromName);
  const targetIndex = targetName === labelKey ? 0 : nextExtra.indexOf(targetName);
  const insertIndex = targetIndex < 0
    ? nextExtra.length
    : Math.max(0, targetIndex + (beforeTarget || targetName === labelKey ? 0 : 1));
  nextExtra.splice(insertIndex, 0, fromName);
  const visible = [labelKey, ...nextExtra];
  const remainder = [...new Set([...oldOrder, ...properties])]
    .filter(name => !visible.includes(name));
  setColOrder(dbPath, [...visible, ...remainder], {
    ctx,
    label: 'シート表示: 列順序',
    detail: `${fromName} → ${insertIndex + 2}列目`,
  });
  renderDbTreeView(ctx);
  return true;
}

function _dbTreeOpenColumnMenu(event, propName, index, hierarchy, ctx, dbPath) {
  const rect = event.currentTarget?.getBoundingClientRect?.()
    || event.target?.getBoundingClientRect?.()
    || { right: 0, bottom: 0 };
  const menuEvent = {
    target: event.target,
    currentTarget: event.currentTarget,
    clientX: Number(event.clientX) || rect.right,
    clientY: Number(event.clientY) || rect.bottom,
  };
  if (propName === '__entity__') {
    showEntityColMenu(menuEvent, ctx, dbPath);
    return;
  }
  showColHeaderMenu(menuEvent, propName, index, ctx, dbPath, {
    omitGroupBy: true,
    protectLeftEdge: hierarchy,
    protectVisibility: hierarchy,
    includeManualSort: true,
  });
}

function _dbTreeAppendHeaderIndicator(cell, icon, title, className) {
  const indicator = document.createElement('span');
  indicator.className = className;
  indicator.innerHTML = lucide(icon, 12);
  indicator.title = title;
  indicator.setAttribute('aria-label', title);
  cell.appendChild(indicator);
}

function _dbTreeCreateColumnHeader({
  propName,
  index,
  hierarchy,
  ctx,
  dbPath,
  config,
  properties,
  list,
  host,
  pinnedOffsets,
}) {
  const cell = document.createElement('span');
  cell.className = 'db-tree-header-cell';
  cell.dataset.dbColToken = propName;
  cell.dataset.e2eId = `db-tree-column-header-${propName}`;
  cell.setAttribute('role', 'columnheader');
  cell.tabIndex = 0;
  if (hierarchy) cell.classList.add('is-hierarchy');
  const stickyLeft = pinnedOffsets[propName];
  if (Number.isFinite(stickyLeft)) {
    cell.classList.add('is-pinned');
    cell.style.left = `${stickyLeft}px`;
  }

  if (propName !== '__entity__') {
    const type = getPropertyTypes(dbPath, ctx)?.[propName]?.type || 'text';
    const typeIcon = document.createElement('span');
    typeIcon.className = 'db-tree-header-type';
    typeIcon.innerHTML = lucide(
      typeof getPropertyTypeIcon === 'function' ? getPropertyTypeIcon(type) : 'alignLeft',
      13,
    );
    typeIcon.title = `列タイプ: ${typeof getPropertyTypeLabel === 'function' ? getPropertyTypeLabel(type) : type}`;
    cell.appendChild(typeIcon);
  }
  const label = document.createElement('span');
  label.className = 'db-tree-header-label';
  label.textContent = propName === '__entity__'
    ? (typeof _dbEntityColumnDisplayLabel === 'function' ? _dbEntityColumnDisplayLabel(dbPath, { ctx }) : 'トピック名')
    : propName;
  cell.appendChild(label);

  const sortConfig = typeof getDbSortConfig === 'function' ? getDbSortConfig(dbPath, { ctx }) : null;
  const sortKey = propName === '__entity__' ? 'name' : propName;
  if (sortConfig?.key === sortKey) {
    cell.classList.add('is-sorted');
    cell.setAttribute('aria-sort', sortConfig.dir === 'desc' ? 'descending' : 'ascending');
    _dbTreeAppendHeaderIndicator(
      cell,
      sortConfig.dir === 'desc' ? 'arrowDown' : 'arrowUp',
      sortConfig.dir === 'desc' ? '降順' : '昇順',
      'db-tree-header-indicator is-sort',
    );
  }
  if (typeof isDbColumnFilterActive === 'function' && isDbColumnFilterActive(dbPath, propName, ctx)) {
    cell.classList.add('is-filtered');
    _dbTreeAppendHeaderIndicator(cell, 'filter', 'フィルター適用中', 'db-tree-header-indicator is-filter');
  }
  if (propName !== '__entity__') {
    const ptc = getPropertyTypes(dbPath, ctx)?.[propName];
    const lock = typeof getColumnLock === 'function' ? getColumnLock(dbPath, propName) : 'none';
    if (ptc?.source || lock !== 'none') {
      _dbTreeAppendHeaderIndicator(
        cell,
        ptc?.source ? 'zap' : lock === 'admin' ? 'shield' : 'lock',
        ptc?.source ? '自動入力（読み取り専用）' : lock === 'admin' ? '管理者のみ編集' : 'ロック',
        'db-tree-header-indicator is-lock',
      );
    }
  }
  if (Number.isFinite(stickyLeft)) {
    _dbTreeAppendHeaderIndicator(cell, 'pin', '固定列', 'db-tree-header-indicator is-pin');
  }

  const more = document.createElement('button');
  more.type = 'button';
  more.className = 'db-tree-header-more';
  more.innerHTML = lucide('moreHorizontal', 14);
  more.title = '列メニュー';
  more.setAttribute('aria-label', `${label.textContent}列メニュー`);
  more.addEventListener('click', event => {
    event.stopPropagation();
    _dbTreeOpenColumnMenu(event, propName, index, hierarchy, ctx, dbPath);
  });
  cell.appendChild(more);

  const resize = document.createElement('span');
  resize.className = 'db-tree-column-resize-handle';
  resize.dataset.e2eId = `db-tree-column-resize-${propName}`;
  resize.dataset.dbResizeToken = propName;
  resize.tabIndex = 0;
  resize.setAttribute('role', 'separator');
  resize.setAttribute('aria-orientation', 'vertical');
  resize.setAttribute('aria-valuemin', '60');
  resize.setAttribute('aria-valuemax', '640');
  resize.setAttribute('aria-valuenow', String(list._dbTreeLayout?.widths?.[propName] || 150));
  resize.setAttribute('aria-label', `${label.textContent}の列幅を変更`);
  resize.addEventListener('pointerdown', event => {
    _dbTreeStartColumnResize(event, resize, list, propName, ctx, dbPath);
  });
  resize.addEventListener('keydown', event => {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
    event.preventDefault();
    event.stopPropagation();
    const amount = event.shiftKey ? 40 : 8;
    const direction = event.key === 'ArrowLeft' ? -1 : 1;
    _dbTreePersistColumnWidth(list, propName, list._dbTreeLayout.widths[propName] + amount * direction, ctx, dbPath);
  });
  cell.appendChild(resize);

  cell.addEventListener('contextmenu', event => {
    event.preventDefault();
    _dbTreeOpenColumnMenu(event, propName, index, hierarchy, ctx, dbPath);
  });
  if (typeof addLongPressHandler === 'function') {
    addLongPressHandler(cell, event => {
      if (!cell.isConnected) return;
      if (event.target?.closest?.('button, .db-tree-column-resize-handle')) return;
      _dbTreeOpenColumnMenu(event, propName, index, hierarchy, ctx, dbPath);
    });
  }
  cell.addEventListener('click', event => {
    if (event.target.closest('button, .db-tree-column-resize-handle')) return;
    if (typeof _setSelectedColumns === 'function') _setSelectedColumns(dbPath, [propName], propName);
    host.querySelectorAll('.db-tree-header-cell.is-selected').forEach(item => item.classList.remove('is-selected'));
    cell.classList.add('is-selected');
  });

  cell.draggable = !hierarchy;
  if (!hierarchy) {
    cell.addEventListener('dragstart', event => {
      if (event.target.closest('button, .db-tree-column-resize-handle')) {
        event.preventDefault();
        return;
      }
      host.dataset.draggingColumn = propName;
      event.dataTransfer?.setData('text/x-db-tree-column', propName);
      if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move';
      cell.classList.add('is-dragging');
    });
    cell.addEventListener('dragend', () => {
      host.dataset.draggingColumn = '';
      cell.classList.remove('is-dragging');
      host.querySelectorAll('.is-drop-before,.is-drop-after').forEach(item => {
        item.classList.remove('is-drop-before', 'is-drop-after');
      });
    });
  }
  cell.addEventListener('dragover', event => {
    const fromName = host.dataset.draggingColumn || event.dataTransfer?.getData('text/x-db-tree-column');
    if (!fromName || fromName === propName) return;
    event.preventDefault();
    if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
    const rect = cell.getBoundingClientRect();
    const before = hierarchy || event.clientX < rect.left + rect.width / 2;
    cell.classList.toggle('is-drop-before', before);
    cell.classList.toggle('is-drop-after', !before);
  });
  cell.addEventListener('dragleave', event => {
    if (!event.relatedTarget || !cell.contains(event.relatedTarget)) {
      cell.classList.remove('is-drop-before', 'is-drop-after');
    }
  });
  cell.addEventListener('drop', event => {
    event.preventDefault();
    const fromName = host.dataset.draggingColumn || event.dataTransfer?.getData('text/x-db-tree-column');
    const before = cell.classList.contains('is-drop-before');
    cell.classList.remove('is-drop-before', 'is-drop-after');
    host.dataset.draggingColumn = '';
    _dbTreeReorderColumn(dbPath, ctx, config, properties, fromName, propName, before);
  });
  return cell;
}

function _dbTreeRenderColumnHeaders(host, options) {
  const {
    ctx,
    dbPath,
    config,
    properties,
    extraProps,
    list,
    gridLayout,
  } = options;
  const keys = [gridLayout.labelKey, ...extraProps];
  const configuredPinnedCols = typeof getPinnedCols === 'function' ? getPinnedCols(dbPath, { ctx }) : [];
  const configuredEntityPinned = typeof getEntityColumnPinned === 'function'
    ? getEntityColumnPinned(dbPath, { ctx })
    : true;
  const pinnedRange = typeof getPinnedColumnRangeState === 'function'
    ? getPinnedColumnRangeState(keys, configuredPinnedCols, configuredEntityPinned)
    : {
      pinnedCols: configuredPinnedCols,
      entityColumnPinned: configuredEntityPinned,
    };
  const pinnedCols = pinnedRange.pinnedCols;
  const entityPinned = pinnedRange.entityColumnPinned;
  const pinnedOffsets = {};
  let left = 0;
  keys.forEach(key => {
    const pinned = key === '__entity__' ? entityPinned : pinnedCols.includes(key);
    if (!pinned) return;
    pinnedOffsets[key] = left;
    left += gridLayout.widths[key];
  });
  list._dbTreeLayout = {
    keys,
    labelKey: gridLayout.labelKey,
    widths: { ...gridLayout.widths },
    actionWidth: gridLayout.actionWidth,
    template: gridLayout.template,
    totalWidth: gridLayout.totalWidth,
    pinnedKeys: keys.filter(key => Number.isFinite(pinnedOffsets[key])),
  };
  keys.forEach((propName, index) => {
    host.appendChild(_dbTreeCreateColumnHeader({
      propName,
      index,
      hierarchy: index === 0,
      ctx,
      dbPath,
      config,
      properties,
      list,
      host,
      pinnedOffsets,
    }));
  });
  const actions = document.createElement('span');
  actions.className = 'db-tree-header-actions';
  actions.setAttribute('aria-hidden', 'true');
  host.appendChild(actions);
  return pinnedOffsets;
}

;

/* === gb-db-tree-view.js === */
;
/* シート共通ツリービュー
   親を表す列と並び順列を選び、同一シート内のエントリを階層表示・編集する。 */

function _dbTreeViewSurface(ctx) {
  if (typeof _dbViewSurfaceEl === 'function') return _dbViewSurfaceEl(ctx, '.tree-view', 'tree-view');
  return ctx?.containerEl?.querySelector?.('.tree-view')
    || document.getElementById('tree-view')
    || document.querySelector('.tree-view');
}

function _dbTreeFirstValue(entityData, propName, filterMode) {
  if (!propName) return '';
  const raw = Array.isArray(entityData?.[propName]) ? entityData[propName] : [];
  const values = typeof filterValues === 'function' ? filterValues(raw, undefined, filterMode) : raw;
  const picked = values.find(item => ['採用', '掲載済み'].includes(item?.status || '採用'))
    || values[0];
  return picked?.value ?? '';
}

function _dbTreeDisplayValue(value) {
  if (value === null || value === undefined || value === '') return '—';
  if (typeof value === 'boolean') return value ? 'オン' : 'オフ';
  if (typeof _dbSearchValueText === 'function') {
    const text = String(_dbSearchValueText(value) || '').trim();
    if (text) return text;
  }
  if (Array.isArray(value)) return value.map(_dbTreeDisplayValue).filter(text => text !== '—').join(', ') || '—';
  if (typeof value === 'object') {
    return String(value.name || value.label || value.value || value.path || value.id || '—');
  }
  return String(value);
}

function _dbTreeEditableProperty(dbPath, ctx, propName, config) {
  if (!propName || propName === config.parentProp || propName === config.orderProp || propName === config.collapsedProp) {
    return false;
  }
  const typeConfig = getPropertyTypes(dbPath, ctx)?.[propName] || {};
  return !typeConfig.source && !['formula', 'rollup', 'button'].includes(typeConfig.type);
}

async function _dbTreeEditProperty(dbPath, ctx, node, propName, config) {
  if (!_dbTreeEditableProperty(dbPath, ctx, propName, config)) return;
  const filterMode = ctx?.filter ?? state.filter ?? 'disabled';
  const current = _dbTreeFirstValue(node.entityData, propName, filterMode);
  const typeConfig = getPropertyTypes(dbPath, ctx)?.[propName] || {};
  let nextValue;
  if (typeConfig.type === 'checkbox') {
    nextValue = !['1', 'true', 'yes', 'on', 'はい'].includes(String(current || '').toLowerCase());
  } else if (typeof cfPrompt === 'function') {
    nextValue = await cfPrompt(`${propName}を編集`, _dbTreeDisplayValue(current) === '—' ? '' : String(current ?? ''), {
      okLabel: '保存',
    });
  } else {
    nextValue = window.prompt(`${propName}を編集`, String(current ?? ''));
  }
  if (nextValue === null || nextValue === undefined) return;
  if (typeConfig.type === 'number' && String(nextValue).trim() !== '') {
    const parsed = Number(nextValue);
    if (!Number.isFinite(parsed)) {
      showStatus('数値を入力してください', true);
      return;
    }
    nextValue = parsed;
  }
  try {
    await _dbTreeSetValue(dbPath, ctx, node.entityName, propName, nextValue, `ツリー: ${propName}を編集`);
    await _dbTreeRefreshAfterEdit(dbPath, ctx);
    showStatus(`${propName}を更新しました`);
  } catch (error) {
    showStatus(error?.message || `${propName}の更新に失敗しました`, true);
  }
}

function _dbTreeDefaultConfig(dbPath, ctx) {
  const data = ctx?.pivotData || state.pivotData || {};
  const props = Array.isArray(data.properties) ? data.properties : [];
  const has = name => props.includes(name);
  const tagDictionary = has('親グループ') && has('正式名') && has('種類');
  const relationProp = props.find(prop => {
    const type = getPropertyTypes(dbPath, ctx)?.[prop]?.type;
    return type === 'relation' || type === 'multi-relation';
  }) || '';
  return {
    parentProp: has('親グループ') ? '親グループ' : relationProp,
    orderProp: has('並び順') ? '並び順' : '',
    labelProp: has('正式名') ? '正式名' : '',
    typeProp: has('種類') ? '種類' : '',
    colorProp: has('色') ? '色' : '',
    collapsedProp: has('折りたたみ') ? '折りたたみ' : '',
    parentTypeValue: tagDictionary ? 'グループ' : '',
  };
}

function _dbTreeIsTagDictionary(ctx) {
  const properties = ctx?.pivotData?.properties || state.pivotData?.properties || [];
  return ['親グループ', '正式名', '種類', '並び順']
    .every(name => Array.isArray(properties) && properties.includes(name));
}

function _dbTreeNotifyTagDictionaryChanged(dbPath, ctx) {
  if (!_dbTreeIsTagDictionary(ctx)) return;
  const sourceFolder = String(window.MeldexAutoTagSourceFolder?.(dbPath) || '').trim();
  window.MeldexGlobalTags?.notifyDictionaryChanged?.('dictionary-sheet-tree-updated', sourceFolder);
}

function getDbTreeViewConfig(dbPath, ctx) {
  const view = typeof getCurrentDbViewConfigEntry === 'function'
    ? getCurrentDbViewConfigEntry(dbPath, { ctx })
    : null;
  const stored = view?.typeSpecific?.tree;
  return { ..._dbTreeDefaultConfig(dbPath, ctx), ...(stored && typeof stored === 'object' ? stored : {}) };
}

function setDbTreeViewConfig(dbPath, config, ctx) {
  if (typeof _saveCurrentDbViewField !== 'function') return;
  _saveCurrentDbViewField(dbPath, 'シート表示: ツリービュー設定', '', { ctx }, view => {
    if (!view.typeSpecific || typeof view.typeSpecific !== 'object') view.typeSpecific = {};
    view.typeSpecific.tree = { ...config };
  });
}

function _dbTreeValueKey(value) {
  const text = typeof value === 'object' && value
    ? (value.name || value.label || value.entity || value.entity_name || value.file || value.path || value.id || '')
    : value;
  return String(text ?? '')
    .replace(/\\/g, '/')
    .split('/')
    .pop()
    ?.replace(/\.md$/i, '')
    .trim() || '';
}

function _dbTreePresetNames(entityData, filterMode) {
  const raw = Array.isArray(entityData?.['プリセット']) ? entityData['プリセット'] : [];
  const values = typeof filterValues === 'function' ? filterValues(raw, undefined, filterMode) : raw;
  return [...new Set(values
    .flatMap(item => String(item?.value ?? '').split(/[\r\n,、;；]+/))
    .map(value => value.trim())
    .filter(Boolean))];
}

function _dbTreeSortConfig(dbPath, ctx) {
  return typeof getDbSortConfig === 'function'
    ? getDbSortConfig(dbPath, { ctx })
    : (typeof getDbViewConfig === 'function' ? getDbViewConfig(dbPath)?.sortConfig || null : null);
}

function _dbTreeUsesHierarchyOrder(dbPath, ctx) {
  const sortConfig = _dbTreeSortConfig(dbPath, ctx);
  return !sortConfig || sortConfig.key === 'manual';
}

function _dbTreeCompareSortValues(first, second) {
  const a = first == null ? '' : first;
  const b = second == null ? '' : second;
  const aText = typeof a === 'object' ? _dbTreeDisplayValue(a) : String(a);
  const bText = typeof b === 'object' ? _dbTreeDisplayValue(b) : String(b);
  const aNumber = Number(aText);
  const bNumber = Number(bText);
  if (aText.trim() && bText.trim() && Number.isFinite(aNumber) && Number.isFinite(bNumber)) {
    return aNumber - bNumber;
  }
  return aText.localeCompare(bText, 'ja', { numeric: true, sensitivity: 'base' });
}

function _dbTreeNodeComparator(dbPath, ctx, config, filterMode) {
  const sortConfig = _dbTreeSortConfig(dbPath, ctx);
  if (!sortConfig || sortConfig.key === 'manual') {
    return (a, b) => a.order - b.order
      || a.label.localeCompare(b.label, 'ja', { numeric: true })
      || a.sourceIndex - b.sourceIndex;
  }
  const direction = sortConfig.dir === 'desc' ? -1 : 1;
  const key = sortConfig.key;
  return (a, b) => {
    const first = key === 'name' || key === '__entity__'
      ? a.entityName
      : _dbTreeFirstValue(a.entityData, key, filterMode);
    const second = key === 'name' || key === '__entity__'
      ? b.entityName
      : _dbTreeFirstValue(b.entityData, key, filterMode);
    return direction * _dbTreeCompareSortValues(first, second)
      || a.order - b.order
      || a.label.localeCompare(b.label, 'ja', { numeric: true })
      || a.sourceIndex - b.sourceIndex;
  };
}

function _dbTreeBuildModel(data, dbPath, ctx, config) {
  const filterMode = ctx?.filter ?? state.filter ?? 'disabled';
  const entities = data?.entities || {};
  const filteredNames = typeof _dbSortedEntityNames === 'function'
    ? _dbSortedEntityNames(data, dbPath, ctx, { applyAdvancedFilters: true })
    : Object.keys(entities);
  const names = Object.keys(entities);
  const filteredNameSet = new Set(filteredNames);
  const hasFilteredRows = filteredNameSet.size !== names.length
    || names.some(entityName => !filteredNameSet.has(entityName));
  const nodes = names.map((entityName, sourceIndex) => {
    const entityData = entities[entityName] || {};
    const rawOrder = _dbTreeFirstValue(entityData, config.orderProp, filterMode);
    const label = String(_dbTreeFirstValue(entityData, config.labelProp, filterMode) || entityName);
    const searchText = [entityName, label, ...Object.values(entityData)
      .flatMap(values => Array.isArray(values) ? values : [])
      .map(value => _dbTreeDisplayValue(value?.value))]
      .join('\n')
      .toLocaleLowerCase('ja');
    return {
      entityName,
      entityData,
      label,
      parentRef: _dbTreeValueKey(_dbTreeFirstValue(entityData, config.parentProp, filterMode)),
      order: Number.isFinite(Number(rawOrder)) ? Number(rawOrder) : sourceIndex,
      type: String(_dbTreeFirstValue(entityData, config.typeProp, filterMode) || ''),
      color: String(_dbTreeFirstValue(entityData, config.colorProp, filterMode) || ''),
      presets: _dbTreePresetNames(entityData, filterMode),
      searchText,
      initiallyCollapsed: ['1', 'true', 'yes', 'on', 'はい'].includes(
        String(_dbTreeFirstValue(entityData, config.collapsedProp, filterMode) || '').toLowerCase(),
      ),
      sourceIndex,
      parent: null,
      children: [],
      orphaned: false,
    };
  });
  const byName = new Map();
  const register = (key, node) => {
    const normalized = String(key || '').trim().toLocaleLowerCase('ja');
    if (normalized && !byName.has(normalized)) byName.set(normalized, node);
  };
  nodes.forEach(node => {
    register(node.entityName, node);
    register(node.label, node);
    register(_dbTreeFirstValue(node.entityData, '内部ID', filterMode), node);
  });
  const roots = [];
  nodes.forEach(node => {
    if (!node.parentRef) {
      roots.push(node);
      return;
    }
    const parent = byName.get(node.parentRef.toLocaleLowerCase('ja')) || null;
    if (!parent || parent === node) {
      node.orphaned = true;
      roots.push(node);
      return;
    }
    node.parent = parent;
    parent.children.push(node);
  });
  const compare = _dbTreeNodeComparator(dbPath, ctx, config, filterMode);
  roots.sort(compare);
  nodes.forEach(node => node.children.sort(compare));
  const rootSet = new Set(roots);
  nodes.forEach(node => {
    const seen = new Set([node]);
    let cursor = node.parent;
    while (cursor) {
      if (seen.has(cursor)) {
        const previousParent = node.parent;
        if (previousParent) {
          previousParent.children = previousParent.children.filter(child => child !== node);
        }
        node.parent = null;
        node.orphaned = true;
        if (!rootSet.has(node)) {
          rootSet.add(node);
          roots.push(node);
          roots.sort(compare);
        }
        break;
      }
      seen.add(cursor);
      cursor = cursor.parent;
    }
  });
  return {
    nodes,
    roots,
    byEntity: new Map(nodes.map(node => [node.entityName, node])),
    filterMatches: hasFilteredRows ? filteredNameSet : null,
  };
}

function _dbTreeState(ctx, dbPath, model, config = {}) {
  const viewConfig = typeof getDbViewConfig === 'function' ? getDbViewConfig(dbPath) : null;
  const viewIndex = typeof _getCurrentDbViewIndexFromConfig === 'function'
    ? _getCurrentDbViewIndexFromConfig(viewConfig, { ctx })
    : (Number.isInteger(ctx?.currentViewIdx) ? ctx.currentViewIdx : Number(viewConfig?.currentViewIdx) || 0);
  const viewKey = `${dbPath}\n${viewIndex}`;
  if (!ctx._dbTreeViewState || ctx._dbTreeViewState.viewKey !== viewKey) {
    const collapsed = new Set();
    model.nodes.forEach(node => {
      if (node.initiallyCollapsed) collapsed.add(node.entityName);
    });
    if (model.nodes.length > 500 && collapsed.size === 0) {
      model.roots.forEach(node => {
        if (node.children.length) collapsed.add(node.entityName);
      });
    }
    ctx._dbTreeViewState = {
      dbPath,
      viewKey,
      collapsed,
      query: '',
      presetFilter: String(config.presetFilter || ''),
      selected: '',
      dragging: '',
    };
  }
  return ctx._dbTreeViewState;
}

function _dbTreeSearchVisibility(model, query) {
  const needle = String(query || '').trim().toLocaleLowerCase('ja');
  if (!needle) return null;
  const visible = new Set();
  model.nodes.forEach(node => {
    if (!node.searchText.includes(needle)) return;
    let cursor = node;
    while (cursor) {
      visible.add(cursor.entityName);
      cursor = cursor.parent;
    }
  });
  return visible;
}

function _dbTreePresetVisibility(model, presetName) {
  const target = String(presetName || '').trim();
  if (!target) return null;
  const visible = new Set();
  model.nodes.forEach(node => {
    if (!node.presets.includes(target)) return;
    let cursor = node;
    while (cursor) {
      visible.add(cursor.entityName);
      cursor = cursor.parent;
    }
  });
  return visible;
}

function _dbTreeCombinedVisibility(model, stateInfo) {
  const needle = String(stateInfo.query || '').trim().toLocaleLowerCase('ja');
  const target = String(stateInfo.presetFilter || '').trim();
  if (!model.filterMatches && !needle && !target) return null;
  const visible = new Set();
  model.nodes.forEach(node => {
    if (model.filterMatches && !model.filterMatches.has(node.entityName)) return;
    if (target && !node.presets.includes(target)) return;
    if (needle && !node.searchText.includes(needle)) return;
    let cursor = node;
    while (cursor) {
      visible.add(cursor.entityName);
      cursor = cursor.parent;
    }
  });
  return visible;
}

function _dbTreeFlattenVisible(model, stateInfo, visible) {
  const rows = [];
  const visit = (node, depth) => {
    if (visible && !visible.has(node.entityName)) return;
    rows.push({ node, depth });
    if (!visible && stateInfo.collapsed.has(node.entityName)) return;
    node.children.forEach(child => visit(child, depth + 1));
  };
  model.roots.forEach(node => visit(node, 0));
  return rows;
}

function _dbTreeWouldCreateCycle(node, parent) {
  let cursor = parent;
  while (cursor) {
    if (cursor === node) return true;
    cursor = cursor.parent;
  }
  return false;
}

function _dbTreeValueRef(dbPath, entityName, propName, value, rawIndex, data) {
  return {
    file: value?.file || _entityPath(dbPath, entityName, data),
    property: value?.property || propName,
    candidate_index: value?.candidate_index != null ? value.candidate_index : rawIndex,
    value: value?.value,
    status: value?.status,
  };
}

async function _dbTreeSetValue(dbPath, ctx, entityName, propName, nextValue, label) {
  if (!propName) return;
  const data = ctx?.pivotData || state.pivotData;
  const entityData = data?.entities?.[entityName] || {};
  const raw = Array.isArray(entityData[propName]) ? entityData[propName] : [];
  const adopted = typeof getAdoptedValueForWrite === 'function'
    ? getAdoptedValueForWrite(raw)
    : raw[0];
  const oldValue = adopted?.value ?? '';
  if (String(oldValue ?? '') === String(nextValue ?? '')) return;
  if (adopted) {
    const rawIndex = Math.max(0, raw.indexOf(adopted));
    const ref = _dbTreeValueRef(dbPath, entityName, propName, adopted, rawIndex, data);
    await _apiPutValue(ref, { new_value: nextValue, __source: 'sheet-tree-view' });
    if (typeof _dbUndoValue === 'function') {
      _dbUndoValue(label, ref, oldValue, nextValue, undefined, undefined, { dbPath, ctx });
    }
    adopted.value = nextValue;
  } else {
    const entityPath = _entityPath(dbPath, entityName, data);
    await _apiPostValue(entityPath, propName, nextValue, '採用', '', '', { __source: 'sheet-tree-view' });
    entityData[propName] = [{ value: nextValue, status: '採用', file: entityPath, property: propName, candidate_index: 0 }];
  }
}

async function _dbTreeRefreshAfterEdit(dbPath, ctx) {
  if (typeof selectDatabase === 'function') {
    await selectDatabase(dbPath, ctx, {
      silent: true,
      skipRecent: true,
      skipNavPush: true,
      skipSaveLastView: true,
    });
  } else {
    renderDbTreeView(ctx);
  }
  _dbTreeNotifyTagDictionaryChanged(dbPath, ctx);
}

async function _dbTreeMoveNode(dbPath, ctx, model, config, node, target, mode) {
  if (!node || !config.parentProp) return;
  if (mode !== 'child' && !_dbTreeUsesHierarchyOrder(dbPath, ctx)) {
    showStatus('同じ階層で位置を変えるには、列メニューの並び替えを「階層の並び順」に戻してください。', true);
    return;
  }
  let parent = null;
  let nextOrder = node.order;
  if (mode === 'child') {
    parent = target;
    if (target && config.parentTypeValue && target.type !== config.parentTypeValue) {
      showStatus(`${config.parentTypeValue}の行だけを親にできます`, true);
      return;
    }
    if (_dbTreeWouldCreateCycle(node, parent)) {
      showStatus('子孫を親にはできません', true);
      return;
    }
    const siblings = parent?.children || model.roots;
    nextOrder = siblings.length ? Math.max(...siblings.map(item => item.order)) + 1000 : 0;
  } else {
    parent = target?.parent || null;
    if (_dbTreeWouldCreateCycle(node, parent)) {
      showStatus('子孫の階層へは移動できません', true);
      return;
    }
    const siblings = parent?.children || model.roots;
    const targetIndex = siblings.indexOf(target);
    const previous = siblings[mode === 'before' ? targetIndex - 1 : targetIndex];
    const next = siblings[mode === 'before' ? targetIndex : targetIndex + 1];
    if (previous && next && next.order > previous.order) nextOrder = (previous.order + next.order) / 2;
    else if (previous && next) nextOrder = mode === 'before' ? next.order - 0.5 : previous.order + 0.5;
    else if (previous) nextOrder = previous.order + 1;
    else if (next) nextOrder = next.order - 1;
    else nextOrder = 0;
  }
  const parentValue = parent?.entityName || '';
  try {
    await _dbTreeSetValue(dbPath, ctx, node.entityName, config.parentProp, parentValue, 'ツリー: 親を変更');
    if (config.orderProp) {
      await _dbTreeSetValue(dbPath, ctx, node.entityName, config.orderProp, nextOrder, 'ツリー: 並び順を変更');
    }
    await _dbTreeRefreshAfterEdit(dbPath, ctx);
    showStatus('階層を変更しました');
  } catch (error) {
    showStatus(error?.message || '階層の変更に失敗しました', true);
  }
}

async function _dbTreeSwapSibling(dbPath, ctx, config, node, direction) {
  if (!_dbTreeUsesHierarchyOrder(dbPath, ctx)) {
    showStatus('行を前後へ動かすには、列メニューの並び替えを「階層の並び順」に戻してください。', true);
    return;
  }
  const siblings = node.parent?.children || ctx._dbTreeViewModel?.roots || [];
  const index = siblings.indexOf(node);
  const other = siblings[index + direction];
  if (!other || !config.orderProp) return;
  try {
    const first = node.order;
    const second = other.order;
    if (first === second) {
      const nextOrder = direction < 0 ? second - 1 : second + 1;
      await _dbTreeSetValue(dbPath, ctx, node.entityName, config.orderProp, nextOrder, 'ツリー: 並び順を変更');
    } else {
      await _dbTreeSetValue(dbPath, ctx, node.entityName, config.orderProp, second, 'ツリー: 並び順を変更');
      await _dbTreeSetValue(dbPath, ctx, other.entityName, config.orderProp, first, 'ツリー: 並び順を変更');
    }
    await _dbTreeRefreshAfterEdit(dbPath, ctx);
  } catch (error) {
    showStatus(error?.message || '並び替えに失敗しました', true);
  }
}

function _dbTreeRenderDetails(host, node, dbPath, ctx, config) {
  host.textContent = '';
  if (!node) {
    host.className = 'db-tree-details is-empty';
    host.textContent = '行を選択すると、階層と値を確認できます';
    return;
  }
  host.className = 'db-tree-details';
  const title = document.createElement('h3');
  title.textContent = node.label;
  host.appendChild(title);
  const path = [];
  let cursor = node;
  while (cursor) {
    path.unshift(cursor.label);
    cursor = cursor.parent;
  }
  const pathLabel = document.createElement('div');
  pathLabel.className = 'db-tree-detail-path';
  pathLabel.textContent = path.join('  ›  ');
  host.appendChild(pathLabel);
  const meta = document.createElement('dl');
  [
    ['トピック', node.entityName],
    ['親', node.parent?.label || '最上位'],
    ['子', `${node.children.length}件`],
    ...(config.orderProp ? [['並び順', String(node.order)]] : []),
    ...(node.type ? [['種類', node.type]] : []),
  ].forEach(([term, value]) => {
    const dt = document.createElement('dt');
    dt.textContent = term;
    const dd = document.createElement('dd');
    dd.textContent = value;
    meta.append(dt, dd);
  });
  host.appendChild(meta);
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'トピックを開く';
  open.addEventListener('click', () => {
    const pathValue = _entityPath(dbPath, node.entityName, ctx?.pivotData || state.pivotData);
    if (typeof selectEntity === 'function') selectEntity(pathValue);
  });
  host.appendChild(open);
}

function _dbTreeApplyPinnedCell(cell, propName, pinnedOffsets) {
  const left = pinnedOffsets?.[propName];
  if (!Number.isFinite(left)) return;
  cell.classList.add('is-pinned');
  cell.dataset.dbPinnedToken = propName;
  cell.style.left = `${left}px`;
}

function _dbTreeApplyCellPresentation(cell, value, propName, dbPath, ctx) {
  const override = typeof getDbColumnCellDisplay === 'function'
    ? getDbColumnCellDisplay(dbPath, propName, ctx)
    : null;
  if (override) {
    cell.dataset.cellOverflow = override.overflow;
    cell.style.setProperty('--db-tree-cell-lines', String(override.lines));
  }
  const color = typeof getCellColor === 'function' ? getCellColor(value, propName, dbPath, ctx) : null;
  if (color?.bg) cell.style.backgroundColor = color.bg;
  if (color?.fg) cell.style.color = color.fg;
}

function _dbTreeRowHeight(dbPath, columnKeys, ctx) {
  const base = typeof matchMedia === 'function' && matchMedia('(max-width: 720px)').matches ? 42 : 34;
  if (typeof getDbColumnCellDisplay !== 'function') return base;
  let maxLines = 1;
  columnKeys.forEach(propName => {
    const display = getDbColumnCellDisplay(dbPath, propName, ctx);
    if (display?.overflow === 'wrap') maxLines = Math.max(maxLines, Math.min(10, Number(display.lines) || 1));
  });
  return base + (maxLines - 1) * 16;
}

function _dbTreeRenderRow(node, depth, parentEl, renderCtx) {
  const {
    stateInfo,
    dbPath,
    ctx,
    config,
    model,
    extraProps,
    gridTemplate,
    labelKey,
    pinnedOffsets,
    rowHeight,
  } = renderCtx;
  const row = document.createElement('div');
  row.className = 'db-tree-row';
  row.dataset.entityName = node.entityName;
  row.dataset.meldexEntityPath = _entityPath(dbPath, node.entityName, ctx?.pivotData || state.pivotData);
  row.dataset.e2eId = `db-tree-row-${node.entityName}`;
  row.draggable = true;
  row.style.setProperty('--db-tree-depth', String(depth));
  row.style.setProperty('--db-tree-row-height', `${rowHeight}px`);
  row.style.gridTemplateColumns = gridTemplate;
  row.setAttribute('role', 'treeitem');
  row.tabIndex = 0;
  row.setAttribute('aria-level', String(depth + 1));
  row.setAttribute('aria-selected', stateInfo.selected === node.entityName ? 'true' : 'false');
  if (node.children.length) row.setAttribute('aria-expanded', stateInfo.collapsed.has(node.entityName) ? 'false' : 'true');
  if (stateInfo.selected === node.entityName) row.classList.add('selected');
  if (node.orphaned) row.classList.add('orphaned');
  if (node.color) row.style.setProperty('--db-tree-node-color', node.color);

  const nameCell = document.createElement('div');
  nameCell.className = 'db-tree-name-cell';
  nameCell.style.setProperty('--db-tree-depth', String(depth));
  _dbTreeApplyPinnedCell(nameCell, labelKey, pinnedOffsets);
  _dbTreeApplyCellPresentation(nameCell, node.label, labelKey, dbPath, ctx);
  const grip = document.createElement('span');
  grip.className = 'db-tree-grip';
  grip.innerHTML = lucide('gripVertical', 13);
  grip.title = 'ドラッグして親または位置を変更';
  nameCell.appendChild(grip);

  const caret = document.createElement('button');
  caret.type = 'button';
  caret.className = 'db-tree-caret';
  if (node.children.length) {
    caret.innerHTML = lucide(stateInfo.collapsed.has(node.entityName) ? 'chevronRight' : 'chevronDown', 14);
    caret.title = stateInfo.collapsed.has(node.entityName) ? '展開' : '折りたたむ';
    caret.addEventListener('click', event => {
      event.stopPropagation();
      if (stateInfo.collapsed.has(node.entityName)) stateInfo.collapsed.delete(node.entityName);
      else stateInfo.collapsed.add(node.entityName);
      renderCtx.redraw();
    });
  } else {
    caret.disabled = true;
  }
  nameCell.appendChild(caret);

  const marker = document.createElement('span');
  marker.className = 'db-tree-marker';
  nameCell.appendChild(marker);
  const label = document.createElement('span');
  label.className = 'db-tree-label';
  label.textContent = node.label;
  if (_dbTreeEditableProperty(dbPath, ctx, config.labelProp, config)) {
    label.title = 'ダブルクリックして編集';
    label.addEventListener('dblclick', event => {
      event.stopPropagation();
      _dbTreeEditProperty(dbPath, ctx, node, config.labelProp, config);
    });
  }
  nameCell.appendChild(label);
  if (node.children.length) {
    const count = document.createElement('span');
    count.className = 'db-tree-count';
    count.textContent = String(node.children.length);
    nameCell.appendChild(count);
  }
  row.appendChild(nameCell);

  extraProps.forEach(propName => {
    const cell = document.createElement('div');
    cell.className = 'db-tree-value-cell';
    cell.dataset.propName = propName;
    const rawValue = _dbTreeFirstValue(node.entityData, propName, ctx?.filter ?? state.filter ?? 'disabled');
    const displayValue = _dbTreeDisplayValue(rawValue);
    const cellText = document.createElement('span');
    cellText.className = 'db-tree-cell-text';
    cellText.textContent = displayValue;
    cell.appendChild(cellText);
    _dbTreeApplyPinnedCell(cell, propName, pinnedOffsets);
    _dbTreeApplyCellPresentation(cell, rawValue, propName, dbPath, ctx);
    cell.title = _dbTreeEditableProperty(dbPath, ctx, propName, config)
      ? `${displayValue}\nダブルクリックして編集`
      : displayValue;
    if (propName === config.typeProp) cell.classList.add('is-type');
    if (propName === config.colorProp && String(rawValue || '')) {
      cellText.style.color = String(rawValue);
    }
    if (_dbTreeEditableProperty(dbPath, ctx, propName, config)) {
      cell.tabIndex = 0;
      cell.addEventListener('dblclick', event => {
        event.stopPropagation();
        _dbTreeEditProperty(dbPath, ctx, node, propName, config);
      });
      cell.addEventListener('keydown', event => {
        if (event.key !== 'Enter' || event.isComposing) return;
        event.preventDefault();
        event.stopPropagation();
        _dbTreeEditProperty(dbPath, ctx, node, propName, config);
      });
    }
    row.appendChild(cell);
  });
  const moveButtons = document.createElement('span');
  moveButtons.className = 'db-tree-move-buttons';
  [-1, 1].forEach(direction => {
    const button = document.createElement('button');
    button.type = 'button';
    button.innerHTML = lucide(direction < 0 ? 'arrowUp' : 'arrowDown', 12);
    button.title = direction < 0 ? '同じ階層で前へ' : '同じ階層で次へ';
    button.disabled = !config.orderProp || !_dbTreeUsesHierarchyOrder(dbPath, ctx);
    if (!_dbTreeUsesHierarchyOrder(dbPath, ctx)) {
      button.title = '列で並び替え中は位置を変更できません';
    }
    button.addEventListener('click', event => {
      event.stopPropagation();
      _dbTreeSwapSibling(dbPath, ctx, config, node, direction);
    });
    moveButtons.appendChild(button);
  });
  row.appendChild(moveButtons);
  row.addEventListener('click', () => {
    stateInfo.selected = node.entityName;
    _dbTreeRenderOptionPanel(ctx);
    parentEl.querySelectorAll('.db-tree-row.selected').forEach(el => el.classList.remove('selected'));
    row.classList.add('selected');
    parentEl.querySelectorAll('.db-tree-row[aria-selected="true"]').forEach(el => el.setAttribute('aria-selected', 'false'));
    row.setAttribute('aria-selected', 'true');
  });
  row.addEventListener('keydown', event => {
    if (event.target !== row || event.key !== 'Enter' || event.isComposing) return;
    event.preventDefault();
    _dbTreeEditProperty(dbPath, ctx, node, config.labelProp, config);
  });
  row.addEventListener('dragstart', event => {
    stateInfo.dragging = node.entityName;
    event.dataTransfer?.setData('text/x-db-tree-entity', node.entityName);
    window.MeldexBoardTransfer?.setEntityDragData?.(
      event.dataTransfer,
      dbPath,
      node.entityName,
      row.dataset.meldexEntityPath,
    );
    if (event.dataTransfer) event.dataTransfer.effectAllowed = 'copyMove';
    row.classList.add('dragging');
  });
  row.addEventListener('dragend', () => {
    stateInfo.dragging = '';
    row.classList.remove('dragging');
    document.querySelectorAll('.db-tree-row.drop-before,.db-tree-row.drop-child,.db-tree-row.drop-after')
      .forEach(el => el.classList.remove('drop-before', 'drop-child', 'drop-after'));
  });
  row.addEventListener('dragover', event => {
    const draggedName = stateInfo.dragging || event.dataTransfer?.getData('text/x-db-tree-entity');
    if (!draggedName || draggedName === node.entityName) return;
    event.preventDefault();
    const rect = row.getBoundingClientRect();
    const ratio = (event.clientY - rect.top) / Math.max(1, rect.height);
    row.classList.remove('drop-before', 'drop-child', 'drop-after');
    row.classList.add(ratio < 0.25 ? 'drop-before' : ratio > 0.75 ? 'drop-after' : 'drop-child');
  });
  row.addEventListener('dragleave', event => {
    if (!event.relatedTarget || !row.contains(event.relatedTarget)) {
      row.classList.remove('drop-before', 'drop-child', 'drop-after');
    }
  });
  row.addEventListener('drop', event => {
    event.preventDefault();
    const draggedName = stateInfo.dragging || event.dataTransfer?.getData('text/x-db-tree-entity');
    const dragged = model.byEntity.get(draggedName);
    const mode = row.classList.contains('drop-before')
      ? 'before'
      : row.classList.contains('drop-after') ? 'after' : 'child';
    row.classList.remove('drop-before', 'drop-child', 'drop-after');
    _dbTreeMoveNode(dbPath, ctx, model, config, dragged, node, mode);
  });
  parentEl.appendChild(row);
}

function _dbTreeGridLayout(currentView, config, extraProps) {
  const widths = currentView?.colWidths || {};
  const bounded = (value, fallback, min = 80) => {
    const number = Number(value);
    return Math.max(min, Math.min(640, Number.isFinite(number) ? number : fallback));
  };
  const labelKey = config.labelProp || '__entity__';
  const labelWidth = bounded(widths[labelKey] ?? widths.__entity__, 320, 60);
  const columnWidths = extraProps.map(propName => bounded(widths[propName], 150, 60));
  const widthMap = { [labelKey]: labelWidth };
  extraProps.forEach((propName, index) => { widthMap[propName] = columnWidths[index]; });
  const actionWidth = 58;
  const parts = [`${labelWidth}px`, ...columnWidths.map(width => `${width}px`), `${actionWidth}px`];
  return {
    labelKey,
    widths: widthMap,
    actionWidth,
    template: parts.join(' '),
    totalWidth: labelWidth + columnWidths.reduce((sum, width) => sum + width, 0) + actionWidth,
  };
}

function renderDbTreeView(ctx) {
  ctx = ctx || _currentPaneState();
  const container = _dbTreeViewSurface(ctx);
  const data = ctx?.pivotData || state.pivotData;
  const dbPath = ctx?.dbPath || state.currentDbPath;
  if (!container || !data?.entities || !dbPath) return;
  container.style.display = 'flex';
  container.textContent = '';
  const config = getDbTreeViewConfig(dbPath, ctx);
  const properties = Array.from(new Set([
    ...(data.properties || []),
    ...Object.keys(getPropertyTypes(dbPath, ctx) || {}),
  ])).filter(prop => typeof isDbPropertyDeleted !== 'function' || !isDbPropertyDeleted(dbPath, prop));

  if (Object.keys(data.entities).length === 0) {
    _dbTreeSetOptionTabVisible(true, ctx);
    if (typeof _dbRenderEmptyStateWithCreate === 'function') {
      _dbRenderEmptyStateWithCreate(container, 'listTree', 'トピックがありません', 'トピックを追加して開始してください', ctx);
    } else if (typeof renderEmptyState === 'function') {
      renderEmptyState(container, 'listTree', 'トピックがありません', 'トピックを追加して開始してください');
    }
    return;
  }

  const toolbar = document.createElement('div');
  toolbar.className = 'db-tree-toolbar';
  const search = document.createElement('input');
  search.type = 'search';
  search.placeholder = 'ツリーを検索';
  search.setAttribute('aria-label', 'ツリーを検索');
  const expand = document.createElement('button');
  expand.type = 'button';
  expand.innerHTML = lucide('unfoldVertical', 14) + ' すべて展開';
  const collapse = document.createElement('button');
  collapse.type = 'button';
  collapse.innerHTML = lucide('foldVertical', 14) + ' すべて折りたたむ';
  const settings = document.createElement('button');
  settings.type = 'button';
  settings.innerHTML = lucide('settings', 14) + ' ツリー設定';
  toolbar.append(search, expand, collapse, settings);
  container.appendChild(toolbar);
  _dbTreeSetOptionTabVisible(true, ctx);

  if (!config.parentProp || !properties.includes(config.parentProp)) {
    const empty = document.createElement('div');
    empty.className = 'db-tree-setup-empty';
    const title = document.createElement('strong');
    title.textContent = '親を表す列を選択してください';
    const hint = document.createElement('span');
    hint.textContent = '同じシート内のトピックを参照する列を使って階層を作ります。';
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'primary';
    button.textContent = 'ツリー設定を開く';
    button.addEventListener('click', () => _dbTreeOpenOptions(ctx));
    empty.append(title, hint, button);
    container.appendChild(empty);
    settings.addEventListener('click', () => _dbTreeOpenOptions(ctx));
    return;
  }

  const model = _dbTreeBuildModel(data, dbPath, ctx, config);
  ctx._dbTreeViewModel = model;
  const stateInfo = _dbTreeState(ctx, dbPath, model, config);
  const presetOptions = [...new Set(model.nodes.flatMap(node => node.presets))]
    .sort((a, b) => a.localeCompare(b, 'ja', { numeric: true }));
  if (presetOptions.length) {
    const presetFilter = document.createElement('select');
    presetFilter.className = 'db-tree-preset-filter';
    presetFilter.setAttribute('aria-label', 'タグプリセットで絞り込む');
    const all = document.createElement('option');
    all.value = '';
    all.textContent = `全プリセット（${presetOptions.length}件）`;
    presetFilter.appendChild(all);
    presetOptions.forEach(presetName => {
      const option = document.createElement('option');
      option.value = presetName;
      option.textContent = presetName;
      presetFilter.appendChild(option);
    });
    if (!presetOptions.includes(stateInfo.presetFilter)) stateInfo.presetFilter = '';
    presetFilter.value = stateInfo.presetFilter;
    presetFilter.addEventListener('change', () => {
      stateInfo.presetFilter = presetFilter.value;
      setDbTreeViewConfig(dbPath, { ...config, presetFilter: stateInfo.presetFilter }, ctx);
      list.scrollTop = 0;
      draw();
    });
    toolbar.insertBefore(presetFilter, expand);
  }
  const currentView = typeof getCurrentDbViewConfigEntry === 'function'
    ? getCurrentDbViewConfigEntry(dbPath, { ctx })
    : null;
  const hidden = typeof getHiddenCols === 'function' ? getHiddenCols(dbPath, { ctx }) : [];
  const preferredOrder = Array.isArray(currentView?.colOrder) && currentView.colOrder.length
    ? currentView.colOrder
    : properties;
  const excluded = new Set([
    '__entity__',
    config.labelProp,
    config.parentProp,
    config.orderProp,
    config.collapsedProp,
    '内部ID',
  ].filter(Boolean));
  const extraProps = [...new Set([...preferredOrder, ...properties])]
    .filter(propName => properties.includes(propName) && !hidden.includes(propName) && !excluded.has(propName));
  const gridLayout = _dbTreeGridLayout(currentView, config, extraProps);
  const gridTemplate = gridLayout.template;
  const rowHeight = _dbTreeRowHeight(dbPath, [gridLayout.labelKey, ...extraProps], ctx);
  search.value = stateInfo.query || '';
  const content = document.createElement('div');
  content.className = 'db-tree-content';
  const list = document.createElement('div');
  list.className = 'db-tree-list';
  list.dataset.e2eId = 'db-tree-list';
  const header = document.createElement('div');
  header.className = 'db-tree-header';
  header.setAttribute('role', 'row');
  header.style.gridTemplateColumns = gridTemplate;
  header.style.width = `${gridLayout.totalWidth}px`;
  const rowsHost = document.createElement('div');
  rowsHost.className = 'db-tree-rows';
  rowsHost.setAttribute('role', 'tree');
  rowsHost.style.width = `${gridLayout.totalWidth}px`;
  if (typeof _dbTreeRenderColumnHeaders === 'function') {
    _dbTreeRenderColumnHeaders(header, {
      ctx,
      dbPath,
      config,
      properties,
      extraProps,
      list,
      gridLayout,
    });
  } else {
    [gridLayout.labelKey, ...extraProps].forEach(propName => {
      const column = document.createElement('span');
      column.className = 'db-tree-header-cell';
      column.textContent = propName === '__entity__' ? 'トピック名' : propName;
      header.appendChild(column);
    });
    const actions = document.createElement('span');
    actions.className = 'db-tree-header-actions';
    header.appendChild(actions);
  }
  list.append(header, rowsHost);
  content.appendChild(list);
  container.appendChild(content);

  let visibleRows = [];
  let lastWindow = '';
  let virtualFrame = 0;
  const renderWindow = () => {
    virtualFrame = 0;
    const virtualized = visibleRows.length > 250;
    const start = virtualized ? Math.max(0, Math.floor(list.scrollTop / rowHeight) - 12) : 0;
    const end = virtualized
      ? Math.min(visibleRows.length, start + Math.ceil(list.clientHeight / rowHeight) + 24)
      : visibleRows.length;
    const windowKey = `${start}:${end}:${stateInfo.selected}:${stateInfo.collapsed.size}:${stateInfo.query}:${stateInfo.presetFilter}`;
    if (windowKey === lastWindow) return;
    lastWindow = windowKey;
    rowsHost.textContent = '';
    rowsHost.classList.toggle('is-virtualized', virtualized);
    rowsHost.style.height = virtualized ? `${visibleRows.length * rowHeight}px` : '';
    const windowHost = document.createElement('div');
    windowHost.className = 'db-tree-row-window';
    const activeLayout = list._dbTreeLayout || gridLayout;
    const activePinnedOffsets = {};
    let activeStickyLeft = 0;
    (activeLayout.pinnedKeys || []).forEach(key => {
      activePinnedOffsets[key] = activeStickyLeft;
      activeStickyLeft += activeLayout.widths[key] || 0;
    });
    windowHost.style.width = `${activeLayout.totalWidth}px`;
    if (virtualized) windowHost.style.transform = `translateY(${start * rowHeight}px)`;
    const renderCtx = {
      stateInfo,
      dbPath,
      ctx,
      config,
      model,
      extraProps,
      gridTemplate: activeLayout.template,
      labelKey: gridLayout.labelKey,
      pinnedOffsets: activePinnedOffsets,
      rowHeight,
      redraw: draw,
    };
    visibleRows.slice(start, end).forEach(({ node, depth }) => {
      _dbTreeRenderRow(node, depth, windowHost, renderCtx);
    });
    rowsHost.appendChild(windowHost);
    if (!visibleRows.length) {
      const empty = document.createElement('div');
      empty.className = 'db-tree-no-results';
      empty.textContent = stateInfo.query || stateInfo.presetFilter
        ? '一致する行はありません'
        : '表示できる行はありません';
      rowsHost.appendChild(empty);
    }
  };
  const draw = () => {
    const visible = _dbTreeCombinedVisibility(model, stateInfo);
    visibleRows = _dbTreeFlattenVisible(model, stateInfo, visible);
    lastWindow = '';
    renderWindow();
  };
  draw();
  list.addEventListener('scroll', () => {
    if (virtualFrame) return;
    virtualFrame = requestAnimationFrame(renderWindow);
  }, { passive: true });

  let searchTimer = 0;
  search.addEventListener('input', () => {
    clearTimeout(searchTimer);
    stateInfo.query = search.value;
    searchTimer = setTimeout(draw, 80);
  });
  expand.addEventListener('click', () => {
    stateInfo.collapsed.clear();
    draw();
  });
  collapse.addEventListener('click', () => {
    model.nodes.forEach(node => {
      if (node.children.length) stateInfo.collapsed.add(node.entityName);
    });
    draw();
  });
  settings.addEventListener('click', () => _dbTreeOpenOptions(ctx));
  rowsHost.addEventListener('dragover', event => {
    if (!event.target.closest?.('.db-tree-row')) event.preventDefault();
  });
  rowsHost.addEventListener('drop', event => {
    if (event.target.closest?.('.db-tree-row')) return;
    event.preventDefault();
    const draggedName = stateInfo.dragging || event.dataTransfer?.getData('text/x-db-tree-entity');
    _dbTreeMoveNode(dbPath, ctx, model, config, model.byEntity.get(draggedName), null, 'child');
  });
}

if (typeof window !== 'undefined') {
  window.renderDbTreeView = renderDbTreeView;
  window.getDbTreeViewConfig = getDbTreeViewConfig;
}

;

/* === gb-db-tree-options.js === */
;
/* ツリービューのオプションパネルと共通ツールバー連携。 */

function _dbTreeIsCurrentView(ctx, dbPath) {
  ctx = ctx || (typeof _currentPaneState === 'function' ? _currentPaneState() : null);
  dbPath = dbPath || ctx?.dbPath || state?.currentDbPath;
  if (!dbPath) return false;
  if (typeof _dbCurrentViewModeForContext === 'function') {
    return _dbCurrentViewModeForContext(ctx, dbPath) === 'tree';
  }
  return typeof getCurrentViewMode === 'function' && getCurrentViewMode(dbPath, { ctx }) === 'tree';
}

function _dbTreeSetOptionTabVisible(visible, ctx) {
  const rpDetail = document.getElementById('rp-detail');
  if (rpDetail && typeof _ensureDetailTabShell === 'function') _ensureDetailTabShell(rpDetail);
  document.querySelectorAll('.detail-tab-db-tree').forEach(tab => { tab.hidden = !visible; });
  if (!visible && typeof _currentDetailTab !== 'undefined' && _currentDetailTab === 'db-tree'
      && typeof switchDetailTab === 'function') {
    switchDetailTab(null);
  }
  if (visible) _dbTreeRenderOptionPanel(ctx);
}

function _dbTreeOpenOptions(ctx) {
  if (typeof _openDetailRightPanel === 'function') _openDetailRightPanel();
  _dbTreeSetOptionTabVisible(true, ctx);
  if (typeof switchDetailTab === 'function') switchDetailTab('db-tree');
}

function _dbTreeRenderSettings(host, dbPath, ctx, config, properties) {
  const section = document.createElement('section');
  section.className = 'db-tree-option-section';
  const heading = document.createElement('h3');
  heading.textContent = 'ツリービュー設定';
  const hint = document.createElement('p');
  hint.textContent = '階層に使う列を選びます。この設定は現在のビューに保存されます。';
  section.append(heading, hint);
  const fields = [
    ['parentProp', '親を表す列', true],
    ['orderProp', '並び順の列', false],
    ['labelProp', '表示名の列', false],
    ['typeProp', '種類の列', false],
    ['colorProp', '色の列', false],
    ['collapsedProp', '折りたたみの列', false],
  ];
  const selects = {};
  fields.forEach(([key, label, required]) => {
    const row = document.createElement('label');
    row.textContent = label;
    const select = document.createElement('select');
    if (!required) {
      const none = document.createElement('option');
      none.value = '';
      none.textContent = '使用しない';
      select.appendChild(none);
    }
    properties.forEach(propName => {
      const option = document.createElement('option');
      option.value = propName;
      option.textContent = propName;
      select.appendChild(option);
    });
    select.value = config[key] || '';
    row.appendChild(select);
    section.appendChild(row);
    selects[key] = select;
  });
  const actions = document.createElement('div');
  actions.className = 'db-tree-settings-actions';
  const apply = document.createElement('button');
  apply.type = 'button';
  apply.className = 'primary';
  apply.textContent = '適用';
  apply.addEventListener('click', () => {
    const next = { ...config };
    Object.entries(selects).forEach(([key, select]) => { next[key] = select.value; });
    if (!next.parentProp) {
      showStatus('親を表す列を選択してください', true);
      return;
    }
    setDbTreeViewConfig(dbPath, next, ctx);
    renderDbTreeView(ctx);
  });
  actions.appendChild(apply);
  section.appendChild(actions);
  host.appendChild(section);
}

function _dbTreeRenderOptionPanel(ctx) {
  const host = document.getElementById('detail-tab-db-tree');
  if (!host) return;
  ctx = ctx || (typeof _currentPaneState === 'function' ? _currentPaneState() : null);
  const data = ctx?.pivotData || state?.pivotData;
  const dbPath = ctx?.dbPath || state?.currentDbPath;
  if (!data?.entities || !dbPath || !_dbTreeIsCurrentView(ctx, dbPath)) return;
  const config = getDbTreeViewConfig(dbPath, ctx);
  const properties = Array.from(new Set([
    ...(data.properties || []),
    ...Object.keys(getPropertyTypes(dbPath, ctx) || {}),
  ])).filter(prop => typeof isDbPropertyDeleted !== 'function' || !isDbPropertyDeleted(dbPath, prop));
  host.textContent = '';
  _dbTreeRenderSettings(host, dbPath, ctx, config, properties);
  const detailsSection = document.createElement('section');
  detailsSection.className = 'db-tree-option-section';
  const heading = document.createElement('h3');
  heading.textContent = '選択中のトピック';
  const details = document.createElement('div');
  const stateInfo = ctx?._dbTreeViewState;
  const model = ctx?._dbTreeViewModel;
  _dbTreeRenderDetails(details, model?.byEntity?.get(stateInfo?.selected), dbPath, ctx, config);
  detailsSection.append(heading, details);
  host.appendChild(detailsSection);
}

function _dbTreeAutoFitColumns(ctx, dbPath) {
  ctx = ctx || (typeof _currentPaneState === 'function' ? _currentPaneState() : null);
  const data = ctx?.pivotData || state.pivotData;
  dbPath = dbPath || ctx?.dbPath || state.currentDbPath;
  if (!data?.entities || !dbPath) return;
  const config = getDbTreeViewConfig(dbPath, ctx);
  const viewConfig = getDbViewConfig(dbPath);
  const viewIndex = typeof _getCurrentDbViewIndexFromConfig === 'function'
    ? _getCurrentDbViewIndexFromConfig(viewConfig, { ctx })
    : Number(viewConfig?.currentViewIdx) || 0;
  const currentView = Array.isArray(viewConfig?.savedViews) ? viewConfig.savedViews[viewIndex] : viewConfig;
  if (!currentView) return;
  const before = typeof captureDbViewConfigHistory === 'function' ? captureDbViewConfigHistory(dbPath) : null;
  const properties = Array.isArray(data.properties) ? data.properties : [];
  const hidden = typeof getHiddenCols === 'function' ? getHiddenCols(dbPath, { ctx }) : [];
  const excluded = new Set([
    config.labelProp,
    config.parentProp,
    config.orderProp,
    config.collapsedProp,
    '内部ID',
  ].filter(Boolean));
  const visibleProps = properties.filter(prop => !hidden.includes(prop) && !excluded.has(prop));
  const nodes = ctx._dbTreeViewModel?.nodes || _dbTreeBuildModel(data, dbPath, ctx, config).nodes;
  const charsFor = (texts, header) => typeof _dbAutoWidthCharsForTexts === 'function'
    ? _dbAutoWidthCharsForTexts(texts, header)
    : Math.min(48, Math.max(6, ...[header, ...texts].map(value => [...String(value || '')].length)));
  const pxFor = chars => typeof _dbWidthPxFromChars === 'function'
    ? _dbWidthPxFromChars(chars)
    : Math.max(80, Math.min(640, chars * 12 + 28));
  currentView.colWidths = { ...(currentView.colWidths || {}) };
  const labelKey = config.labelProp || '__entity__';
  currentView.colWidths[labelKey] = Math.max(180, pxFor(charsFor(nodes.map(node => node.label), labelKey)) + 48);
  visibleProps.forEach(propName => {
    const values = nodes.map(node => _dbTreeDisplayValue(
      _dbTreeFirstValue(node.entityData, propName, ctx?.filter ?? state.filter ?? 'disabled'),
    ));
    currentView.colWidths[propName] = pxFor(charsFor(values, propName));
  });
  saveDbViewConfig(dbPath, viewConfig, { skipHistory: true, ctx });
  if (before && typeof pushDbViewConfigHistory === 'function' && typeof captureDbViewConfigHistory === 'function') {
    pushDbViewConfigHistory(dbPath, 'シート表示: 列幅自動調整', before, captureDbViewConfigHistory(dbPath), 'ツリーの全列');
  }
  renderDbTreeView(ctx);
  showStatus('ツリービューの列幅を自動調整しました');
}

function _dbTreeInstallAutoFitAdapter() {
  if (typeof window === 'undefined' || typeof window.autoFitCurrentSheetColumns !== 'function') return;
  const original = window.autoFitCurrentSheetColumns;
  if (original._dbTreeAware) return;
  const wrapped = function (event, ctxOverride, dbPathOverride) {
    const ctx = ctxOverride || (typeof _dbPaneContextFromEvent === 'function'
      ? _dbPaneContextFromEvent(event, { dbPath: dbPathOverride || state.currentDbPath })
      : (typeof _currentPaneState === 'function' ? _currentPaneState() : null));
    const dbPath = dbPathOverride || ctx?.dbPath || state.currentDbPath;
    if (_dbTreeIsCurrentView(ctx, dbPath)) return _dbTreeAutoFitColumns(ctx, dbPath);
    return original.apply(this, arguments);
  };
  wrapped._dbTreeAware = true;
  wrapped._dbTreeOriginal = original;
  window.autoFitCurrentSheetColumns = wrapped;
}

if (typeof window !== 'undefined') {
  window._dbTreeIsCurrentView = _dbTreeIsCurrentView;
  window._dbTreeSetOptionTabVisible = _dbTreeSetOptionTabVisible;
  _dbTreeInstallAutoFitAdapter();
}

;

/* === gb-staff-registry-schema.js === */
;
/* ==============================
   gb-staff-registry-schema.js: スタッフ管理シート（正本）のスキーマ定義

   ユーザーアカウント一元管理 計画書 Phase 1
   （docs/user-account-unification-plan-2026-07-18.md §5.1）

   Pythonの meldex_staff_registry_schema.py と1:1で対応する。
   test_meldex_staff_registry_schema_contract.py が両者の一致を検査する
   （gb-production-management-schema-definitions.js と
   meldex_production_schema.py の契約テストと同型）。
   ============================== */
(function () {
  'use strict';

  const REGISTRY_MARKER_KEY = 'meldex_registry';
  const REGISTRY_MARKER_VALUE = 'staff-v1';
  const DEFAULT_SHEET_NAME = 'スタッフ管理';
  const PERMISSION_OPTIONS = ['管理者', 'メンバー', '閲覧'];
  const USER_KEY_PROPERTY = 'スタッフ';
  const DISPLAY_NAME_PROPERTY = '表示名';
  const USER_META_KEY = 'meldex_user';
  const USER_META_SCHEMA_VERSION = 1;
  const USER_TYPE_ACCOUNT = 'account';
  const USER_TYPE_VIRTUAL = 'virtual';
  const USER_TYPES = [USER_TYPE_ACCOUNT, USER_TYPE_VIRTUAL];

  const date = (withTime = false) => ({ type: 'date', ...(withTime ? { withTime: true } : {}) });

  // 必須列（保護対象）。列名 → プロパティ型設定。
  const REQUIRED_PROPERTY_TYPES = {
    'スタッフ': { type: 'user' },
    '表示名': { type: 'text' },
    '権限': { type: 'select', options: [...PERMISSION_OPTIONS] },
    '作業可能時間': { type: 'text' },
    '休憩時間': { type: 'text' },
    '標準時間単価': { type: 'number' },
    '休日': { type: 'text' },
    '参加開始日': date(false),
    '参加終了日': date(false),
    '外部カレンダーURL（Google）': { type: 'url' },
    '外部カレンダーURL（CalDAV）': { type: 'url' },
    '同期有効': { type: 'checkbox' },
    '備考': { type: 'text' },
  };

  const REQUIRED_PROPERTY_ORDER = Object.keys(REQUIRED_PROPERTY_TYPES);

  function isRequiredProperty(propName) {
    return Object.prototype.hasOwnProperty.call(REQUIRED_PROPERTY_TYPES, String(propName || ''));
  }

  function isStaffRegistryFrontmatter(frontmatter) {
    return !!frontmatter && typeof frontmatter === 'object'
      && frontmatter[REGISTRY_MARKER_KEY] === REGISTRY_MARKER_VALUE;
  }

  function deepFreeze(value) {
    if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
    Object.values(value).forEach(deepFreeze);
    return Object.freeze(value);
  }

  window.MeldexStaffRegistrySchema = deepFreeze({
    REGISTRY_MARKER_KEY,
    REGISTRY_MARKER_VALUE,
    DEFAULT_SHEET_NAME,
    PERMISSION_OPTIONS,
    USER_KEY_PROPERTY,
    DISPLAY_NAME_PROPERTY,
    USER_META_KEY,
    USER_META_SCHEMA_VERSION,
    USER_TYPE_ACCOUNT,
    USER_TYPE_VIRTUAL,
    USER_TYPES,
    REQUIRED_PROPERTY_TYPES,
    REQUIRED_PROPERTY_ORDER,
    isRequiredProperty,
    isStaffRegistryFrontmatter,
  });
})();

;

/* === gb-user-registry.js === */
;
/* ==============================
   gb-user-registry.js: スタッフ管理シート（正本）の読み口プロバイダ

   ユーザーアカウント一元管理 計画書 Phase 1〜3
   （docs/user-account-unification-plan-2026-07-18.md §5.4）

   apiFetch/apiPost/apiPut に統一されているため、デスクトップ/クラウド静的の
   両方で同じ実装が動く（クラウド静的では apiFetch が gb-cloud-fetch.js で
   モンキーパッチされ、window.MeldexDataAccess.requestJson 経由になる）。

   責務: 正本シートの設定（置き場所）取得・変更、スタッフ一覧の取得（キャッシュ
   付き）、スタッフ行の作成・更新（fill-only 対応）、一意制約の簡易チェック、
   変更通知、正本シートを開く導線。
   ============================== */
(function () {
  'use strict';

  const STAFF_CACHE_TTL_MS = 15000;

  let _configCache = null; // { path, updated }
  let _staffCache = null; // { staff: [...], duplicates: [...], loadedAt }
  const _listeners = [];

  function _normPath(path) {
    return String(path || '').replace(/\\/g, '/').replace(/\/+$/, '');
  }

  function _notify() {
    _listeners.slice().forEach((cb) => {
      try { cb(); } catch (e) { console.warn('MeldexUserRegistry: onChange listener failed', e); }
    });
  }

  function _applyConfigResult(result) {
    _configCache = { path: String(result?.path || ''), updated: String(result?.updated || '') };
    return _configCache;
  }

  function _applyStaffResult(result) {
    _applyConfigResult(result);
    _staffCache = {
      staff: Array.isArray(result?.staff) ? result.staff : [],
      duplicates: Array.isArray(result?.duplicates) ? result.duplicates : [],
      loadedAt: Date.now(),
    };
    return _staffCache;
  }

  async function getConfig(opts) {
    const force = !!(opts && opts.force);
    if (!force && _configCache) return _configCache;
    const result = await apiFetch('/staff-registry/config');
    return _applyConfigResult(result);
  }

  // 同期アクセス用: ネットワーク待ちができない呼び出し元
  // （gb-tool-calendar-production-task-view.js の managedPath 等、UIの
  // 選択状態を同期的に組み立てる箇所）のために、ウォームアップ済みキャッシュを
  // そのまま返す。未ウォームアップ時は空文字を返す（自己修復・後続の
  // getConfig() 呼び出しでの再解決に委ねる。isRegistryPathSync と同じ方針）。
  function getConfigSync() {
    return _configCache ? { ..._configCache } : { path: '', updated: '' };
  }

  // 同期チェック用: getSchemaProtectionLevel() 等、ネットワーク待ちができない
  // 呼び出し元のために primeConfigCache() でウォームアップ済みのキャッシュを見る。
  // 未ウォームアップ時は false を返す（自己修復が安全網のため実害は小さい。
  // 計画書§5.2「自己修復」参照）。
  function isRegistryPathSync(dbPath) {
    if (!_configCache || !_configCache.path || !dbPath) return false;
    return _normPath(dbPath) === _normPath(_configCache.path);
  }

  async function primeConfigCache() {
    try { await getConfig({ force: true }); } catch (e) { /* ソースフォルダ未設定時などは静かに諦める */ }
  }

  async function ensure() {
    const result = await apiPost('/staff-registry/ensure', {});
    _applyStaffResult(result);
    // 初回作成でスタッフが1件も無い場合、現在ユーザーを1行目として登録する
    // （ダイアログなしの自動作成。計画書§5.1）。fill-only のため既存行があれば
    // 何もしない（起動時 self-upsert・Phase 2 と同じ契約）。
    if (_staffCache.staff.length === 0 && typeof getUsername === 'function') {
      const me = String(getUsername() || '').trim();
      if (me && me !== 'anonymous') {
        try {
          await upsertStaff({ user: me, display: me, user_type: 'account' }, { fillOnly: true });
          await listStaff({ force: true });
        } catch (e) { console.warn('MeldexUserRegistry: self-registration failed', e); }
      }
    }
    return { path: _configCache.path, updated: _configCache.updated, staff: _staffCache.staff, duplicates: _staffCache.duplicates };
  }

  async function listStaff(opts) {
    const force = !!(opts && opts.force);
    if (!force && _staffCache && (Date.now() - _staffCache.loadedAt) < STAFF_CACHE_TTL_MS) {
      return _staffCache.staff;
    }
    const result = await apiFetch('/staff-registry/list');
    _applyStaffResult(result);
    return _staffCache.staff;
  }

  function listDuplicatesSync() {
    return _staffCache ? _staffCache.duplicates.slice() : [];
  }

  async function findByUser(name, opts) {
    const wanted = String(name || '').trim();
    if (!wanted) return null;
    const staff = await listStaff(opts);
    return staff.find((row) => row.user === wanted) || null;
  }

  // クライアント側の簡易重複チェック（計画書§5.3・§5.8）。書き込み前のUIヒント
  // 用途で、確定的な一意制約はバックエンド（meldex_staff_registry_service.
  // ensure_unique_user）が担う。
  function validateUniqueUser(user, excludeEntryName) {
    const wanted = String(user || '').trim();
    if (!wanted || !_staffCache) return null;
    return _staffCache.staff.find((row) => row.user === wanted && row.entry_name !== excludeEntryName) || null;
  }

  async function upsertStaff(entry, opts) {
    const options = opts || {};
    const body = Object.assign({}, entry || {}, { fill_only: !!options.fillOnly });
    const result = await apiPost('/staff-registry/upsert', body);
    invalidate();
    _notify();
    return result?.staff || null;
  }

  async function addVirtualUser(display) {
    const name = String(display || '').trim();
    if (!name) throw new Error('仮ユーザーの表示名を入力してください');
    return upsertStaff({ display: name, user_type: 'virtual' });
  }

  async function setUserWorkspace(userOrId, workspaceId, included) {
    const identity = String(userOrId || '').trim();
    const targetWorkspaceId = String(workspaceId || '').trim();
    if (!identity || !targetWorkspaceId) throw new Error('ユーザーとワークスペースを指定してください');
    const users = await listStaff({ force: true });
    const row = users.find(item => item.user_id === identity || item.user === identity || item.display === identity);
    if (!row) throw new Error('ユーザーが見つかりません');
    const workspaceIds = new Set(Array.isArray(row.workspace_ids) ? row.workspace_ids : []);
    if (included) workspaceIds.add(targetWorkspaceId);
    else workspaceIds.delete(targetWorkspaceId);
    return upsertStaff({
      user: row.user,
      user_id: row.user_id,
      user_type: row.user_type || 'account',
      display: row.display || row.user,
      role: row.role,
      work_hours: row.work_hours,
      break_hours: row.break_hours,
      hourly_rate: row.hourly_rate,
      holidays: row.holidays,
      active_from: row.active_from,
      active_to: row.active_to,
      google_url: row.google_url,
      caldav_url: row.caldav_url,
      sync_enabled: row.sync_enabled,
      note: row.note,
      workspace_ids: [...workspaceIds],
    });
  }

  function invalidate() {
    _staffCache = null;
  }

  async function relocate(path) {
    const result = await apiPut('/staff-registry/config', { path: String(path || '') });
    _applyConfigResult(result);
    invalidate();
    _notify();
    return _configCache;
  }

  async function openSheet() {
    const config = await getConfig().catch(() => null);
    if (!config || !config.path) {
      if (typeof showStatus === 'function') showStatus('ユーザー管理シートの場所が未設定です。設定の「ユーザー」を開いて初期化してください', true);
      return false;
    }
    if (typeof closeSettingsModalRestoringTheme === 'function') closeSettingsModalRestoringTheme();
    if (typeof showView === 'function') showView('database');
    if (typeof selectDatabase === 'function') {
      await selectDatabase(config.path);
      return true;
    }
    if (typeof openFolder === 'function') {
      await openFolder('ユーザー管理', config.path, {});
      return true;
    }
    return false;
  }

  function onChange(cb) {
    if (typeof cb === 'function') _listeners.push(cb);
  }

  window.MeldexUserRegistry = {
    getConfig,
    getConfigSync,
    isRegistryPathSync,
    primeConfigCache,
    ensure,
    listStaff,
    listDuplicatesSync,
    findByUser,
    validateUniqueUser,
    upsertStaff,
    addVirtualUser,
    setUserWorkspace,
    invalidate,
    relocate,
    openSheet,
    onChange,
  };
})();

;

/* === gb-user-picker.js === */
;
/* ==============================
   gb-user-picker.js: ユーザー選択ピッカーの共通モジュール

   ユーザーアカウント一元管理 計画書 Phase 3（§5.8 ピッカー統一）

   6箇所に重複していた候補ユーザー一覧の実装（`/team`・`/auth/users` の
   マージ）を `getCandidates()` に集約する。候補 = 正本「スタッフ管理シート」
   （MeldexUserRegistry.listStaff）+ ワークスペースメンバーのマージ。
   制作管理はPhase 4で正本へ完全統合済みだが、ワークスペースメンバーの
   マージ自体は「ワークスペースに参加済みだが正本未登録（fill-only同期が
   まだ走っていない等）」のユーザーを候補から漏らさないための恒常的な設計
   であり、Phase 4完了後も残す（計画書 §5.4・§5.8）。
   `/auth/users` への参照はここで無くなる。

   `open()` は既存 `_showUserDropdown`（gb-db-value-editors.part03.js）を
   母体に一般化した共通ポップアップ（検索・複数選択・自由入力対応）。
   UI共通ルール（meldex-ui-common-rules-2026-07-01.md）に従い、位置決めは
   positionPopup()/_positionCellDropdown() を使い、選択以外の操作（複数選択の
   確定・解除）を持つため閉じるボタンを備える。
   ============================== */
(function () {
  'use strict';

  function _isActiveLeftStaffRow(row) {
    const today = new Date().toISOString().slice(0, 10);
    return !!(row && row.active_to && String(row.active_to) <= today);
  }

  // 候補ユーザー一覧を取得する（正本 + ワークスペースメンバーのマージ）。
  // 6箇所の重複実装（/team・/auth/users のマージ）の統一先。
  async function getCandidates(opts) {
    const options = opts || {};
    const seen = new Set();
    const result = [];
    const add = (name, extra) => {
      const trimmed = String(name || '').trim();
      if (!trimmed || seen.has(trimmed)) return;
      seen.add(trimmed);
      result.push(Object.assign({ name: trimmed, display: trimmed, role: '', has_avatar: false, user_type: 'account' }, extra || {}));
    };

    if (typeof getUsername === 'function') {
      const me = getUsername();
      if (me && me !== 'anonymous') add(me);
    }

    try {
      if (window.MeldexUserRegistry) {
        const staff = await window.MeldexUserRegistry.listStaff(options.force ? { force: true } : {});
        staff.forEach((row) => {
          if (_isActiveLeftStaffRow(row)) return; // 離脱者は選択候補から外す（計画書§5.6）
          add(row.user || row.display, {
            id: row.user_id || '',
            display: row.display || row.user || '',
            role: row.role || '',
            user_type: row.user_type || 'account',
            workspace_ids: Array.isArray(row.workspace_ids) ? row.workspace_ids.slice() : [],
          });
        });
      }
    } catch (e) { /* 正本シート未設定時は無視して次の候補源へ */ }

    try {
      if (window.MeldexWorkspaces?.load) {
        const workspaces = await window.MeldexWorkspaces.load({ force: false });
        (Array.isArray(workspaces) ? workspaces : []).forEach((workspace) => {
          (workspace.members || []).forEach((member) => add(member?.name, { role: member?.role || '' }));
        });
      }
    } catch (e) { /* ワークスペース未使用時は無視 */ }

    (options.extraCandidates || []).forEach((name) => add(name));
    return result;
  }

  function _pickerAvatarHtml(name) {
    if (typeof _userAvatarSmall === 'function') return _userAvatarSmall(name);
    return '';
  }

  function _pickerEsc(text) {
    return MeldexEscape.html(text);
  }

  // 共通ユーザー選択ポップアップ。
  // opts: { multi, value, onCommit, onCancel, onClose, allowFreeText, extraCandidates,
  //         candidates（省略時は getCandidates() で取得）, useCellPositioning }
  async function open(anchor, opts) {
    const options = opts || {};
    document.querySelectorAll('.gb-user-picker-dd').forEach((el) => el.remove());

    const candidates = options.candidates || await getCandidates(options);
    const isMulti = !!options.multi;
    const currentValue = options.value == null ? '' : String(options.value);
    const selected = new Set(
      isMulti && currentValue ? currentValue.split(',').map((s) => s.trim()).filter(Boolean) : []
    );
    if (!isMulti && currentValue) selected.add(currentValue.trim());

    const dd = document.createElement('div');
    dd.className = 'cell-inline-dd gb-user-picker-dd';
    dd.style.cssText = 'position:fixed;z-index:9999;min-width:200px;max-height:320px;overflow-y:auto;background:var(--ui-popup-bg, var(--bg2));border:1px solid var(--border);border-radius:6px;box-shadow:0 4px 12px rgba(0,0,0,.3);padding:4px;';
    dd.addEventListener('pointerdown', (e) => e.stopPropagation());
    dd.addEventListener('click', (e) => e.stopPropagation());

    const searchInput = document.createElement('input');
    searchInput.type = 'text';
    searchInput.placeholder = options.allowFreeText ? 'ユーザーを検索・入力...' : 'ユーザーを検索...';
    searchInput.style.cssText = 'width:100%;padding:4px 8px;font-size:12px;background:var(--bg);color:var(--fg);border:1px solid var(--border);border-radius:3px;margin-bottom:4px;box-sizing:border-box;';
    dd.appendChild(searchInput);

    let closer = null;
    function closeDropdown() {
      if (dd.parentNode) dd.remove();
      if (closer) { document.removeEventListener('pointerdown', closer); closer = null; }
      if (typeof options.onClose === 'function') options.onClose();
    }
    function commitSingle(name) {
      closeDropdown();
      if (typeof options.onCommit === 'function') options.onCommit(name);
    }
    function commitMulti() {
      closeDropdown();
      if (typeof options.onCommit === 'function') options.onCommit([...selected].join(', '));
    }

    function renderList(filter) {
      dd.querySelectorAll('.user-option,.user-confirm-btn,.user-clear-btn,.user-empty-msg,.user-freetext-btn').forEach((el) => el.remove());
      const filtered = filter
        ? candidates.filter((u) => u.name.toLowerCase().includes(filter.toLowerCase()))
        : candidates;

      if (!filtered.length) {
        const msg = document.createElement('div');
        msg.className = 'user-empty-msg';
        msg.style.cssText = 'padding:8px;color:var(--fg2);font-size:12px;text-align:center;';
        msg.textContent = options.allowFreeText ? '一致するユーザーがいません（そのまま入力できます）' : '該当するユーザーがいません';
        dd.appendChild(msg);
      }

      filtered.forEach((u) => {
        const item = document.createElement('div');
        item.className = 'user-option';
        const isSelected = selected.has(u.name);
        item.style.cssText = 'display:flex;align-items:center;gap:6px;padding:4px 8px;cursor:pointer;border-radius:3px;font-size:12px;'
          + (isSelected ? 'background:var(--accent);color:var(--ui-accent-fg, var(--ui-fg-strong));' : '');
        const userKind = u.user_type === 'virtual' ? '仮ユーザー' : (u.role || '');
        item.innerHTML = (isMulti ? '<span style="font-size:11px;">' + (isSelected ? '✓' : '　') + '</span> ' : '')
          + _pickerAvatarHtml(u.name) + ' ' + _pickerEsc(u.display || u.name)
          + '<span style="margin-left:auto;font-size:10px;color:' + (isSelected ? 'color-mix(in srgb, var(--ui-fg-strong) 70%, transparent)' : 'var(--fg2)') + ';">' + _pickerEsc(userKind) + '</span>';
        item.addEventListener('mouseover', () => { if (!isSelected) item.style.background = 'var(--bg3)'; });
        item.addEventListener('mouseout', () => { if (!isSelected) item.style.background = ''; });
        item.addEventListener('click', () => {
          if (isMulti) {
            if (selected.has(u.name)) selected.delete(u.name);
            else selected.add(u.name);
            renderList(searchInput.value);
          } else {
            commitSingle(u.name);
          }
        });
        dd.appendChild(item);
      });

      const trimmedFilter = String(filter || '').trim();
      if (options.allowFreeText && trimmedFilter && !candidates.some((u) => u.name === trimmedFilter)) {
        const freeItem = document.createElement('div');
        freeItem.className = 'user-freetext-btn dd-nav-item';
        freeItem.style.cssText = 'padding:4px 8px;cursor:pointer;font-size:12px;color:var(--accent);border-top:1px solid var(--border);margin-top:4px;';
        freeItem.textContent = `"${trimmedFilter}" をそのまま使う`;
        freeItem.addEventListener('click', () => {
          if (isMulti) { selected.add(trimmedFilter); searchInput.value = ''; renderList(''); }
          else commitSingle(trimmedFilter);
        });
        dd.appendChild(freeItem);
      }

      if (isMulti) {
        const confirmBtn = document.createElement('div');
        confirmBtn.className = 'user-confirm-btn dd-nav-item';
        confirmBtn.style.cssText = 'padding:4px 8px;margin-top:4px;text-align:center;cursor:pointer;font-size:12px;color:var(--accent);border-top:1px solid var(--border);font-weight:bold;';
        confirmBtn.textContent = '✓ 確定';
        confirmBtn.addEventListener('click', commitMulti);
        dd.appendChild(confirmBtn);
      }

      if (!isMulti && currentValue) {
        const clearBtn = document.createElement('div');
        clearBtn.className = 'user-clear-btn';
        clearBtn.style.cssText = 'padding:4px 8px;text-align:center;cursor:pointer;font-size:11px;color:var(--fg2);border-top:1px solid var(--border);margin-top:4px;';
        clearBtn.textContent = '選択を解除';
        clearBtn.addEventListener('click', () => commitSingle(''));
        dd.appendChild(clearBtn);
      }
    }

    searchInput.addEventListener('input', () => renderList(searchInput.value));
    renderList('');

    // 選択以外の操作（複数選択の確定・解除・自由入力）を持つため、
    // UI共通ルールに従い閉じるボタンを備える。
    if (isMulti || options.allowFreeText || currentValue) {
      if (typeof attachMeldexDropdownCloseButton === 'function') {
        dd.insertAdjacentHTML('beforeend', typeof meldexDropdownCloseButtonHtml === 'function' ? meldexDropdownCloseButtonHtml() : '');
        attachMeldexDropdownCloseButton(dd, () => {
          closeDropdown();
          if (typeof focusMeldexDropdownTrigger === 'function' && anchor) focusMeldexDropdownTrigger(anchor);
        });
      }
    }

    if (options.useCellPositioning && typeof _positionCellDropdown === 'function') {
      _positionCellDropdown(dd, anchor, { gap: 2, minWidth: 200 });
    } else {
      document.body.appendChild(dd);
      const anchorRect = anchor && typeof anchor.getBoundingClientRect === 'function' ? anchor.getBoundingClientRect() : anchor;
      if (typeof positionPopup === 'function' && anchorRect) {
        positionPopup(dd, anchorRect);
      } else if (typeof clampPopupToViewport === 'function') {
        clampPopupToViewport(dd);
      }
    }

    if (typeof _enableDropdownKeyNav === 'function') {
      _enableDropdownKeyNav(dd, '.user-option,.user-confirm-btn,.user-clear-btn,.user-freetext-btn');
    }
    searchInput.focus();

    setTimeout(() => {
      closer = (ev) => {
        if (!dd.contains(ev.target)) {
          closeDropdown();
          if (typeof options.onCancel === 'function') options.onCancel();
        }
      };
      document.addEventListener('pointerdown', closer);
    }, 0);

    return dd;
  }

  window.MeldexUserPicker = { getCandidates, open };
})();

;

/* === gb-staff-registry-cloud-twin.js === */
;
/* ==============================
   gb-staff-registry-cloud-twin.js: 正本「スタッフ管理シート」のクラウド静的版twin

   ユーザーアカウント一元管理 計画書 Phase 1-4
   （docs/user-account-unification-plan-2026-07-18.md）

   デスクトップ版のサーバーAPI（meldex_api_staff_registry.py /
   meldex_staff_registry_service.py）が正本の意味論を持つ。このファイルは
   同じ5ルート（config GET/PUT・ensure・list・upsert）を、Dropboxブラウザ
   完結版（サーバー無し）向けに __MeldexPwaDataAccessExtensions ハンドラとして
   再実装する（gb-production-management.part01.js の
   _pmInstallCloudHandler と同じ配線パターン）。

   正本シートは通常のフォルダ型シート（フォルダノート + 1スタッフ=1個別.md）
   であり、gb-data-access-dropbox-expanded.part01.js の _ensureFolderNote が
   作る「storage: sqlite 集約ストア」方式のsettings-dbとは別物（デスクトップ版と
   同じVaultを共有する必要があるため）。フォルダノートのfrontmatterはPythonの
   meldex_frontmatter.write_frontmatter が書くYAMLと相互互換な「行ごとに
   JSON.stringify した値」形式（JSONはYAML flow styleのサブセット）で書く。

   デスクトップとの既知の差異（設計判断。詳細は同計画書の実装ログ参照）:
   - デスクトップは複数の「ソースフォルダ」（load_outliner_roots）を横断して
     正本を自動発見・既定作成できるが、クラウド静的版は1つのDropbox接続 =
     1つのワークスペースルートしか持たない（gb-production-management.js が
     制作管理フォルダをワークスペース直下に直接作るのと同じ前提）。そのため
     自動発見・既定作成はワークスペース直下（相対パス ''）だけを対象にする。
   - 設定の保存先は editor-config.json ではなく、既存の /ui-config twin
     （gb-data-access.part01.js の PWA_UI_CONFIG_KEY）と同じ localStorage
     キーを使う（計画書§5.1）。/ui-config 自体のGET/PUTはオブジェクト全体を
     置き換えるため、ここでは同じキーを読み書きしつつ staff_registry
     サブキーだけをマージする（他のUI設定を巻き戻さない）。
   - YAML-lite フロントマターの読み書きと書き込み権限エラー判定は
     gb-cloud-frontmatter-lite.js（共有ヘルパー、2026-07-20にproduction-management側と統合）へ委譲する。
   ============================== */
(function () {
  'use strict';

  const internals = window.__MeldexPwaDataAccessInternals;
  const handlers = window.__MeldexPwaDataAccessExtensions;
  if (!internals || !Array.isArray(handlers)) return;

  const {
    NOT_HANDLED,
    _normalizeFolderPath,
    _joinPath,
    _basename,
    _requirePwaProvider,
    _directoryHandle,
    _resolveEntryHandle,
    _listDirectoryEntries,
    _safeReadJson,
    _safeWriteJson,
  } = internals;

  // gb-data-access.part01.js の PWA_UI_CONFIG_KEY と同じ値（internals経由では
  // 未公開の定数のためここで複製する。値を変更する場合は両方同時に直すこと）。
  const UI_CONFIG_KEY = 'meldex-cloud-ui-config';
  const CONFIG_SUBKEY = 'staff_registry';
  const STAFF_STATUS = '採用';

  function _schema() {
    return window.MeldexStaffRegistrySchema;
  }

  function _nowIso() {
    return new Date().toISOString();
  }

  // ============================================================
  // YAML-lite フロントマター読み書き・権限エラー判定は
  // gb-cloud-frontmatter-lite.js（共有ヘルパー）へ委譲
  // ============================================================

  const {
    isNotFoundError: _srtIsNotFoundError,
    isWriteAccessError: _srtIsWriteAccessError,
    frontmatterText: _srtFrontmatterText,
    readFrontmatter: _srtReadFrontmatter,
  } = window.MeldexCloudFrontmatterLite;

  // ============================================================
  // パス・エントリの下請け
  // ============================================================

  function _srtSafeName(value) {
    return String(value || '無題').replace(/[\\/:*?"<>|\x00-\x1f]/g, '_').trim().slice(0, 100) || '無題';
  }

  function _srtRandomHex(len) {
    if (globalThis.crypto?.randomUUID) return crypto.randomUUID().replace(/-/g, '').slice(0, len);
    let hex = '';
    while (hex.length < len) hex += Math.random().toString(16).slice(2);
    return hex.slice(0, len);
  }

  async function _srtDirectoryEntries(provider, path) {
    try {
      return await _listDirectoryEntries(provider, path);
    } catch (error) {
      if (_srtIsNotFoundError(error)) return [];
      throw error;
    }
  }

  async function _srtEntryKind(provider, path) {
    if (typeof provider?.statPath === 'function') {
      const stat = await provider.statPath(path).catch(() => null);
      return stat?.kind || null;
    }
    try {
      const entry = await _resolveEntryHandle(provider, path);
      return entry?.kind || null;
    } catch {
      return null;
    }
  }

  async function _srtPathExists(provider, path) {
    return !!(await _srtEntryKind(provider, path));
  }

  async function _srtIsDirectory(provider, path) {
    return (await _srtEntryKind(provider, path)) === 'directory';
  }

  async function _srtEntryFiles(provider, root) {
    const rootBase = _basename(root);
    const entries = await _srtDirectoryEntries(provider, root);
    return entries
      .filter(e => e?.handle?.kind === 'file' && e.name.endsWith('.md') && e.name !== rootBase + '.md' && !e.name.startsWith('_'))
      .map(e => ({ name: e.name, path: _joinPath(root, e.name), stem: e.name.replace(/\.md$/i, '') }));
  }

  // ============================================================
  // 設定（正本の置き場所）— /ui-config と同じ localStorage キーを共有する
  // ============================================================

  function _srtGetConfig() {
    const cfg = _safeReadJson(UI_CONFIG_KEY, {});
    const raw = cfg && typeof cfg === 'object' ? cfg[CONFIG_SUBKEY] : null;
    if (!raw || typeof raw !== 'object') return { path: '', updated: '' };
    return { path: String(raw.path || ''), updated: String(raw.updated || '') };
  }

  function _srtSetConfig(path) {
    const cfg = _safeReadJson(UI_CONFIG_KEY, {});
    const base = cfg && typeof cfg === 'object' ? { ...cfg } : {};
    const value = { path: _normalizeFolderPath(path || ''), updated: _nowIso() };
    base[CONFIG_SUBKEY] = value;
    _safeWriteJson(UI_CONFIG_KEY, base);
    return value;
  }

  function _srtRole() {
    const state = window.MeldexRuntimeAdapter?.getWorkspaceState?.() || {};
    if (state.isOwner) return 'owner';
    if (state.access === 'viewer') return 'viewer';
    return 'editor';
  }

  function _srtRequireOwner() {
    if (_srtRole() !== 'owner') throw new Error('ユーザー管理シートの保存先変更は管理者のみ可能です');
  }

  // ============================================================
  // 正本の場所解決（自己修復・自動発見・無ダイアログ既定作成）
  //
  // meldex_staff_registry_service.ensure_or_discover_registry_root と同じ
  // 優先順位・同じ安全設計（設定済みパスは実在確認してから信用する→全階層を
  // マーカーで再発見→再発見できなければ従来どおり設定済みパスへ新規作成→
  // 未設定なら既定パス作成）。設定済みパスが移動・改名で実在しなくなっていた
  // 場合にそのパスを信用しないのがインポート・機能生成ファイル保護計画
  // Phase 1の本体（旧パスへ空フォルダを再生成する「最高リスク」経路の解消。
  // クラウド静的版はワークスペースルートが1つしか無いため「複数ソースフォルダを
  // 横断」する部分だけ単純化する。全階層を辿る部分はデスクトップ版と揃える）。
  // ============================================================

  // meldex_staff_registry_service._discover_existing_registry と同じ安全上限
  // （巨大なワークスペースで走査が終わらなくなることを防ぐ）。
  const SRT_DISCOVERY_SCAN_LIMIT = 8000;

  async function _srtDiscoverExistingRootUnder(provider, schema, dir, state) {
    if (state.checked > SRT_DISCOVERY_SCAN_LIMIT) return null;
    const entries = await _srtDirectoryEntries(provider, dir);
    for (const entry of entries) {
      if (entry?.handle?.kind !== 'directory') continue;
      const name = String(entry.name || '');
      // 内部管理フォルダ（_trash, _chat, .meldex等）は正本の置き場所になり
      // 得ないため、無駄な走査を避けるためにスキップする（デスクトップ版の
      // rglobは全走査するが、意味のある候補だけに絞る安全側の簡略化）。
      if (!name || name.startsWith('.') || name.startsWith('_')) continue;
      const folderPath = dir ? _joinPath(dir, name) : name;
      state.checked += 1;
      if (state.checked > SRT_DISCOVERY_SCAN_LIMIT) return null;
      const note = _joinPath(folderPath, name + '.md');
      if (await _srtPathExists(provider, note)) {
        let parsed = null;
        try { parsed = await _srtReadFrontmatter(provider, note); } catch { parsed = null; }
        if (parsed && schema.isStaffRegistryFrontmatter(parsed.frontmatter)) return folderPath;
      }
      const nested = await _srtDiscoverExistingRootUnder(provider, schema, folderPath, state);
      if (nested) return nested;
      if (state.checked > SRT_DISCOVERY_SCAN_LIMIT) return null;
    }
    return null;
  }

  async function _srtDiscoverExistingRoot(provider) {
    return _srtDiscoverExistingRootUnder(provider, _schema(), '', { checked: 0 });
  }

  async function _srtEnsureOrDiscoverRoot(provider) {
    const configured = _normalizeFolderPath(_srtGetConfig().path || '');
    if (configured && await _srtIsDirectory(provider, configured)) {
      await _srtEnsureRegistrySheet(provider, configured);
      return configured;
    }
    const discovered = await _srtDiscoverExistingRoot(provider);
    if (discovered) {
      _srtSetConfig(discovered);
      await _srtEnsureRegistrySheet(provider, discovered);
      return discovered;
    }
    if (configured) {
      // 設定済みパスは存在しないが再発見もできなかった。初回セットアップ
      // （一度も作られていない設定パス）と外部で完全に失われたケースを区別する
      // 手段が無いため、meldex_staff_registry_service.ensure_or_discover_registry_root
      // と同じ判断で、従来どおり設定済みパスへ新規作成する（既存の挙動・テストを
      // 壊さない）。Phase 1の移動追従フックが効いている環境では、この分岐へ
      // 実際に到達するケース自体が減る。
      await _srtEnsureRegistrySheet(provider, configured);
      return configured;
    }
    const defaultRoot = _schema().DEFAULT_SHEET_NAME;
    await _directoryHandle(provider, defaultRoot, true);
    _srtSetConfig(defaultRoot);
    await _srtEnsureRegistrySheet(provider, defaultRoot);
    return defaultRoot;
  }

  // ============================================================
  // フォルダノートの自己修復（meldex_staff_registry_service.ensure_registry_sheet）
  // ============================================================

  function _srtSameSpec(a, b) {
    try { return JSON.stringify(a) === JSON.stringify(b); } catch { return a === b; }
  }

  async function _srtEnsureRegistrySheet(provider, root) {
    const schema = _schema();
    await _directoryHandle(provider, root, true);
    const note = _joinPath(root, _basename(root) + '.md');
    const parsed = await _srtReadFrontmatter(provider, note);
    const frontmatter = { ...(parsed.frontmatter || {}) };
    frontmatter.type = 'settings-db';
    if (!frontmatter.schema_version) frontmatter.schema_version = 1;
    frontmatter[schema.REGISTRY_MARKER_KEY] = schema.REGISTRY_MARKER_VALUE;
    const propTypes = { ...(frontmatter.property_types || {}) };
    Object.entries(schema.REQUIRED_PROPERTY_TYPES).forEach(([name, spec]) => {
      if (!_srtSameSpec(propTypes[name], spec)) propTypes[name] = spec;
    });
    frontmatter.property_types = propTypes;
    const viewConfig = frontmatter.view_config;
    if (!viewConfig || typeof viewConfig !== 'object' || !Array.isArray(viewConfig.savedViews) || !viewConfig.savedViews.length) {
      frontmatter.view_config = { savedViews: [{ name: 'テーブル', viewMode: 'pivot' }], currentViewIdx: 0 };
    }
    await provider.writeText(note, _srtFrontmatterText(frontmatter, parsed.body || `# ${_basename(root)}\n\n`));
  }

  // ============================================================
  // スタッフ行の読み書き（meldex_staff_registry_service の対応関数と同型）
  // ============================================================

  function _srtPropValue(frontmatter, propName) {
    const raw = (frontmatter?.properties || {})[propName];
    const values = Array.isArray(raw) ? raw : (raw == null ? [] : [raw]);
    const adopted = values.find(v => v && typeof v === 'object' && (v.status === '採用' || v.status === '掲載済み'));
    const value = adopted !== undefined ? adopted : (values.length ? values[0] : '');
    return String(value && typeof value === 'object' ? (value.value ?? '') : (value ?? ''));
  }

  function _srtRowFromFrontmatter(stem, frontmatter) {
    const schema = _schema();
    const rawUser = _srtPropValue(frontmatter, schema.USER_KEY_PROPERTY).trim();
    const display = _srtPropValue(frontmatter, schema.DISPLAY_NAME_PROPERTY).trim() || stem;
    const meta = frontmatter?.[schema.USER_META_KEY] && typeof frontmatter[schema.USER_META_KEY] === 'object'
      ? frontmatter[schema.USER_META_KEY] : {};
    const types = Array.isArray(schema.USER_TYPES) ? schema.USER_TYPES : ['account', 'virtual'];
    const userType = types.includes(String(meta.type || '')) ? String(meta.type) : (rawUser ? 'account' : 'virtual');
    const workspaceIds = [...new Set((Array.isArray(meta.workspace_ids) ? meta.workspace_ids : []).map(value => String(value || '').trim()).filter(Boolean))];
    return {
      user: rawUser || display,
      user_id: String(meta.id || frontmatter?.id || '').trim(),
      user_type: userType,
      workspace_ids: workspaceIds,
      entry_name: stem,
      display,
      role: _srtPropValue(frontmatter, '権限'),
      work_hours: _srtPropValue(frontmatter, '作業可能時間'),
      break_hours: _srtPropValue(frontmatter, '休憩時間'),
      hourly_rate: _srtPropValue(frontmatter, '標準時間単価'),
      holidays: _srtPropValue(frontmatter, '休日'),
      active_from: _srtPropValue(frontmatter, '参加開始日'),
      active_to: _srtPropValue(frontmatter, '参加終了日'),
      google_url: _srtPropValue(frontmatter, '外部カレンダーURL（Google）'),
      caldav_url: _srtPropValue(frontmatter, '外部カレンダーURL（CalDAV）'),
      sync_enabled: ['true', 'True', '1'].includes(_srtPropValue(frontmatter, '同期有効')),
      note: _srtPropValue(frontmatter, '備考'),
    };
  }

  async function _srtLoadStaff(provider, root) {
    const schema = _schema();
    const rows = [];
    const duplicates = [];
    const seen = new Map();
    for (const file of await _srtEntryFiles(provider, root)) {
      let parsed;
      try { parsed = await _srtReadFrontmatter(provider, file.path); } catch { continue; }
      const row = _srtRowFromFrontmatter(file.stem, parsed.frontmatter);
      const user = String(row.user || '').trim();
      if (!user) continue;
      if (seen.has(user)) duplicates.push({ user, entries: [seen.get(user), file.stem] });
      else seen.set(user, file.stem);
      rows.push(row);
    }
    return { staff: rows, duplicates };
  }

  async function _srtFindStaffPathByUser(provider, root, user) {
    const wanted = String(user || '').trim();
    if (!wanted) return null;
    const schema = _schema();
    for (const file of await _srtEntryFiles(provider, root)) {
      let parsed;
      try { parsed = await _srtReadFrontmatter(provider, file.path); } catch { continue; }
      if (_srtPropValue(parsed.frontmatter, schema.USER_KEY_PROPERTY) === wanted) return file.path;
    }
    return null;
  }

  async function _srtEnsureUniqueUser(provider, root, user, excludePath) {
    const identity = String(user || '').trim();
    if (!identity) return;
    const schema = _schema();
    const excluded = excludePath ? _normalizeFolderPath(excludePath) : null;
    for (const file of await _srtEntryFiles(provider, root)) {
      if (excluded && _normalizeFolderPath(file.path) === excluded) continue;
      let parsed;
      try { parsed = await _srtReadFrontmatter(provider, file.path); } catch { continue; }
      if (_srtPropValue(parsed.frontmatter, schema.USER_KEY_PROPERTY) === identity) {
        const error = new Error(`ユーザー「${identity}」は「${file.stem}」に設定済みです`);
        error.status = 409;
        error.code = 'staff_registry_duplicate_user';
        throw error;
      }
    }
  }

  async function _srtFindUnlinkedEntryByDisplay(provider, root, displayName) {
    const wanted = String(displayName || '').trim();
    if (!wanted) return null;
    const schema = _schema();
    for (const file of await _srtEntryFiles(provider, root)) {
      let parsed;
      try { parsed = await _srtReadFrontmatter(provider, file.path); } catch { continue; }
      if (_srtPropValue(parsed.frontmatter, schema.USER_KEY_PROPERTY)) continue;
      if (_srtPropValue(parsed.frontmatter, schema.DISPLAY_NAME_PROPERTY) === wanted || file.stem === wanted) return file.path;
    }
    return null;
  }

  async function _srtFindEntryByUserId(provider, root, userId) {
    const wanted = String(userId || '').trim();
    if (!wanted) return null;
    const schema = _schema();
    for (const file of await _srtEntryFiles(provider, root)) {
      let parsed;
      try { parsed = await _srtReadFrontmatter(provider, file.path); } catch { continue; }
      const meta = parsed.frontmatter?.[schema.USER_META_KEY];
      const identity = String((meta && typeof meta === 'object' ? meta.id : '') || parsed.frontmatter?.id || '').trim();
      if (identity === wanted) return file.path;
    }
    return null;
  }

  function _srtCandidate(value) {
    return { value: String(value), status: STAFF_STATUS, note: '', created: _nowIso() };
  }

  async function _srtUpsertStaff(provider, root, entry, fillOnly) {
    const schema = _schema();
    const payload = entry || {};
    const user = String(payload.user || '').trim();
    const rawDisplay = String(payload.display || user).trim();
    const requestedUserId = String(payload.user_id || '').trim();
    const requestedUserType = String(payload.user_type || '').trim();
    const userTypes = Array.isArray(schema.USER_TYPES) ? schema.USER_TYPES : ['account', 'virtual'];
    if (requestedUserType && !userTypes.includes(requestedUserType)) {
      const error = new Error('ユーザー種別が不正です');
      error.status = 400;
      throw error;
    }
    if (!user && !rawDisplay) {
      const error = new Error('ユーザー名または表示名のいずれかは必須です');
      error.status = 400;
      throw error;
    }
    await _srtEnsureRegistrySheet(provider, root);

    let existingPath = await _srtFindEntryByUserId(provider, root, requestedUserId);
    const prospectiveType = requestedUserType || (user ? 'account' : 'virtual');
    if (existingPath && requestedUserType) {
      const parsed = await _srtReadFrontmatter(provider, existingPath);
      const existingRow = _srtRowFromFrontmatter(_basename(existingPath).replace(/\.md$/i, ''), parsed.frontmatter);
      if (existingRow.user_type !== requestedUserType) {
        const error = new Error('既存ユーザーの種別は変更できません');
        error.status = 409;
        throw error;
      }
    }
    const lookupUser = user || (prospectiveType === 'virtual' ? rawDisplay : '');
    if (!existingPath && lookupUser) {
      existingPath = await _srtFindStaffPathByUser(provider, root, lookupUser);
      if (existingPath && requestedUserType) {
        const parsed = await _srtReadFrontmatter(provider, existingPath);
        const existingRow = _srtRowFromFrontmatter(_basename(existingPath).replace(/\.md$/i, ''), parsed.frontmatter);
        if (existingRow.user_type !== requestedUserType) {
          const error = new Error(`同じ名前の${existingRow.user_type === 'account' ? 'アカウント' : '仮ユーザー'}が既にあります`);
          error.status = 409;
          throw error;
        }
      }
      try {
        await _srtEnsureUniqueUser(provider, root, lookupUser, existingPath);
      } catch (error) {
        // 起動時の空欄補完では、重複した既存行から更新対象を選ばない。
        // 既存データを保全し、重複は一覧の警告と手動編集時の拒否で扱う。
        if (!fillOnly || !existingPath || error.code !== 'staff_registry_duplicate_user') throw error;
        const parsed = await _srtReadFrontmatter(provider, existingPath);
        return { ..._srtRowFromFrontmatter(_basename(existingPath).replace(/\.md$/i, ''), parsed.frontmatter), path: existingPath };
      }
    }
    if (!existingPath && prospectiveType === 'virtual') {
      existingPath = await _srtFindUnlinkedEntryByDisplay(provider, root, rawDisplay);
    }

    const displayName = rawDisplay || user;
    let currentFrontmatter = {};
    let currentBody = '';
    let path = existingPath;
    if (existingPath) {
      const parsed = await _srtReadFrontmatter(provider, existingPath);
      currentFrontmatter = parsed.frontmatter || {};
      currentBody = parsed.body || '';
    } else {
      const safeName = _srtSafeName(displayName);
      path = _joinPath(root, safeName + '.md');
      let suffix = 2;
      while (await _srtPathExists(provider, path)) {
        path = _joinPath(root, `${safeName}_${suffix}.md`);
        suffix += 1;
      }
    }

    const frontmatter = { ...currentFrontmatter };
    if (!frontmatter.type) frontmatter.type = 'settings-entry';
    if (!frontmatter.id) frontmatter.id = 'ent_' + _srtRandomHex(10);
    frontmatter.category = _basename(root);
    frontmatter.modified = _nowIso();
    const currentMeta = frontmatter[schema.USER_META_KEY] && typeof frontmatter[schema.USER_META_KEY] === 'object'
      ? frontmatter[schema.USER_META_KEY] : {};
    const currentType = String(currentMeta.type || '');
    const userType = requestedUserType || (userTypes.includes(currentType) ? currentType : (user ? 'account' : 'virtual'));
    const workspaceIds = 'workspace_ids' in payload
      ? [...new Set((Array.isArray(payload.workspace_ids) ? payload.workspace_ids : []).map(value => String(value || '').trim()).filter(Boolean))]
      : [...new Set((Array.isArray(currentMeta.workspace_ids) ? currentMeta.workspace_ids : []).map(value => String(value || '').trim()).filter(Boolean))];
    frontmatter[schema.USER_META_KEY] = {
      schema_version: Number(schema.USER_META_SCHEMA_VERSION || 1),
      id: requestedUserId || String(currentMeta.id || '').trim() || (existingPath ? String(frontmatter.id || '').trim() : '') || ('usr_' + _srtRandomHex(12)),
      type: userType,
      workspace_ids: workspaceIds,
    };
    const properties = frontmatter.properties && typeof frontmatter.properties === 'object' ? { ...frontmatter.properties } : {};

    const setIfAllowed = (propName, value) => {
      if (value == null || value === '') return;
      if (fillOnly && _srtPropValue({ properties }, propName)) return;
      properties[propName] = [_srtCandidate(value)];
    };
    setIfAllowed(schema.USER_KEY_PROPERTY, user || (userType === 'virtual' ? displayName : ''));
    setIfAllowed(schema.DISPLAY_NAME_PROPERTY, payload.display || displayName);
    setIfAllowed('権限', payload.role);
    setIfAllowed('作業可能時間', payload.work_hours);
    setIfAllowed('休憩時間', payload.break_hours);
    setIfAllowed('標準時間単価', payload.hourly_rate);
    setIfAllowed('休日', payload.holidays);
    setIfAllowed('参加開始日', payload.active_from);
    setIfAllowed('参加終了日', payload.active_to);
    setIfAllowed('外部カレンダーURL（Google）', payload.google_url);
    setIfAllowed('外部カレンダーURL（CalDAV）', payload.caldav_url);
    if ('sync_enabled' in payload) setIfAllowed('同期有効', payload.sync_enabled ? 'true' : '');
    setIfAllowed('備考', payload.note);

    frontmatter.properties = properties;
    await provider.writeText(path, _srtFrontmatterText(frontmatter, currentBody));
    const row = _srtRowFromFrontmatter(_basename(path).replace(/\.md$/i, ''), frontmatter);
    row.path = path;
    return row;
  }

  // ============================================================
  // ルート本体
  // ============================================================

  async function _srtSetConfigRoute(body) {
    _srtRequireOwner();
    const path = String(body?.path || '').trim();
    if (!path) {
      const error = new Error('パスは必須です');
      error.status = 400;
      throw error;
    }
    const provider = await _requirePwaProvider('readwrite');
    const normalized = _normalizeFolderPath(path);
    if (await _srtIsDirectory(provider, normalized)) {
      const note = _joinPath(normalized, _basename(normalized) + '.md');
      if (await _srtPathExists(provider, note)) {
        const parsed = await _srtReadFrontmatter(provider, note);
        if (parsed.frontmatter?.type && !_schema().isStaffRegistryFrontmatter(parsed.frontmatter)) {
          const error = new Error('指定先は別の種類のシートです。空の新規フォルダかユーザー管理シートを指定してください');
          error.status = 409;
          throw error;
        }
      }
    }
    const config = _srtSetConfig(normalized);
    await _srtEnsureRegistrySheet(provider, normalized);
    return { ok: true, ...config };
  }

  async function _srtEnsureRoute() {
    const provider = await _requirePwaProvider('readwrite');
    const root = await _srtEnsureOrDiscoverRoot(provider);
    const result = await _srtLoadStaff(provider, root);
    return { ok: true, ..._srtGetConfig(), ...result };
  }

  async function _srtListRoute() {
    const configured = _normalizeFolderPath(_srtGetConfig().path || '');
    if (!configured) return { ok: true, ..._srtGetConfig(), staff: [], duplicates: [] };
    let provider = await _requirePwaProvider('read');
    if (!await _srtIsDirectory(provider, configured)) {
      return { ok: true, ..._srtGetConfig(), staff: [], duplicates: [] };
    }
    // デスクトップ版は GET list でも自己修復（ensure_registry_sheet）を行うが、
    // クラウド静的版はDropbox共有リンクの閲覧専用ユーザーも一覧を見られるべき
    // なので、書き込み権限が無ければ自己修復だけ諦めて読み取りを続行する
    // （gb-production-management.part01.js の migrateOnFirstDisplay と同じ流儀）。
    try {
      const writableProvider = await _requirePwaProvider('readwrite');
      await _srtEnsureRegistrySheet(writableProvider, configured);
      provider = writableProvider;
    } catch (error) {
      if (!_srtIsWriteAccessError(error)) throw error;
    }
    const result = await _srtLoadStaff(provider, configured);
    return { ok: true, ..._srtGetConfig(), ...result };
  }

  async function _srtUpsertRoute(body) {
    const provider = await _requirePwaProvider('readwrite');
    const root = await _srtEnsureOrDiscoverRoot(provider);
    const payload = { ...(body || {}) };
    const fillOnly = !!payload.fill_only;
    delete payload.fill_only;
    const row = await _srtUpsertStaff(provider, root, payload, fillOnly);
    return { ok: true, staff: row };
  }

  window.MeldexStaffRegistryCloudTwin = Object.freeze({
    createBoundStaffResolver(provider, requestIdentity) {
      if (!provider) throw new Error('Cloudユーザーデータを利用できません');
      const identity = Object.freeze({
        actor: String(requestIdentity?.actor || ''),
        role: String(requestIdentity?.role || ''),
        workspaceId: String(requestIdentity?.workspaceId || ''),
      });
      const configuredPath = _normalizeFolderPath(_srtGetConfig().path || '');
      return Object.freeze({
        identity,
        async resolve() {
          if (!configuredPath || !await _srtIsDirectory(provider, configuredPath)) {
            return { identity, staff: [], duplicates: [] };
          }
          const result = await _srtLoadStaff(provider, configuredPath);
          return { identity, staff: structuredClone(result.staff || []), duplicates: structuredClone(result.duplicates || []) };
        },
      });
    },
  });

  handlers.push(async function _staffRegistryCloudHandler({ method, body, pathname }) {
    if (!/^\/staff-registry(\/|$)/.test(pathname)) return NOT_HANDLED;
    if (pathname === '/staff-registry/config' && method === 'GET') {
      return { ok: true, ..._srtGetConfig() };
    }
    if (pathname === '/staff-registry/config' && method === 'PUT') {
      return _srtSetConfigRoute(body || {});
    }
    if (pathname === '/staff-registry/ensure' && method === 'POST') {
      return _srtEnsureRoute();
    }
    if (pathname === '/staff-registry/list' && method === 'GET') {
      return _srtListRoute();
    }
    if (pathname === '/staff-registry/upsert' && method === 'POST') {
      return _srtUpsertRoute(body || {});
    }
    return NOT_HANDLED;
  });
})();

;
